#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define MLX91219_SENSITIVITY 40.0  // in mV/A
#define MLX91219_ZERO_CURRENT_OFFSET 2048  // in 12-bit ADC code

static int i2c_fd;
static volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int signum) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (i2c_fd = open("/dev/i2c-1", O_RDWR) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure ADS1115
    uint8_t config_reg = 0x01;  // Single-shot mode, AIN0 single-ended, PGA ±4.096V, 128 samples per second
    if (i2cWriteI2CBlockData(i2c_fd, config_reg, 1) < 0) {
        fprintf(stderr, "Failed to write configuration register\n");
        close(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (!exit_flag) {
        // Read ADC data
        uint8_t data[2];
        if (i2cReadI2CBlockData(i2c_fd, 0x00, 2) < 0) {
            fprintf(stderr, "Failed to read ADC data\n");
            continue;
        }

        // Convert ADC data to voltage
        uint16_t adc_code = (data[0] << 8) | data[1];
        float voltage = adc_code * 4.096 / 32768.0;

        // Calculate current
        float current = (voltage - MLX91219_ZERO_CURRENT_OFFSET) * MLX91219_SENSITIVITY / 1000.0;

        // Log current
        printf("Current: %.3f A\n", current);

        // Wait for 500ms
        usleep(500000);
    }

    close(i2c_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

