#define BUZZER_ON 1
#define BUZZER_OFF 0

static int flame_sensor_fd;
static int adc_fd;
static int running = 1;
static int flame_event = 0;
static int temperature_event = 0;
static int last_flame_event_time = 0;
static int last_temperature_event_time = 0;

static void flame_isr(int gpio, int level, uint32_t tick) {
    if (level == PI_FALLING_EDGE) {
        if (tick - last_flame_event_time >= DEBOUNCE_TIME * 1000) {
            flame_event = 1;
            last_flame_event_time = tick;
        }
    }
}

static void log_event(const char *event, int temperature) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    fprintf(log_file, "%s %s", timestamp, event);
    if (temperature > 0) {
        fprintf(log_file, "%d°C\n", temperature);
    } else {
        fprintf(log_file, "\n");
    }
    fclose(log_file);
}

static void buzz(int duration) {
    gpioWrite(BUZZER_PIN, BUZZER_ON);
    usleep(duration * 1000);
    gpioWrite(BUZZER_PIN, BUZZER_OFF);
}

static void handle_sigint(int signum) {
    running = 0;
    buzz(2000);
    gpioWrite(BUZZER_PIN, BUZZER_OFF);
    gpioUnregisterISR(FLAME_SENSOR_PIN);
    close(adc_fd);
    close(flame_sensor_fd);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set flame sensor pull-up: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFunc(FLAME_SENSOR_PIN, PI_FALLING_EDGE, DEBOUNCE_TIME, flame_isr) < 0) {
        fprintf(stderr, "Failed to set flame sensor ISR: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if ((flame_sensor_fd = open("/dev/gpiochip4", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open flame sensor GPIO chip: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if ((adc_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", strerror(errno));
        close(flame_sensor_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(adc_fd, I2C_SLAVE, ADC_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(adc_fd);
        close(flame_sensor_fd);
        gpioTerminate();
        return 1;
    }

    uint8_t config[2] = {0x40, 0x00}; // Single-shot mode, gain ±4.096V, 128 SPS
    if (write(adc_fd, config, 2) != 2) {
        fprintf(stderr, "Failed to write ADC configuration: %s\n", strerror(errno));
        close(adc_fd);
        close(flame_sensor_fd);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(adc_fd);
        close(flame_sensor_fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        if (flame_event) {
            log_event("Flame detected!", 0);
            buzz(2000);
            flame_event = 0;
        }

        if (temperature_event) {
            uint8_t data[2];
            if (read(adc_fd, data, 2) != 2) {
                fprintf(stderr, "Failed to read ADC: %s\n", strerror(errno));
                continue;
            }

            int adc_value = (data[0] << 8) | data[1];
            float voltage = adc_value * 3.3 / 4096.0;
            float temperature = (voltage - 0.5) * 100.0; // Linear mapping 0V-3.3V to 20°C-80°C

            if (temperature > 60.0) {
                log_event("Temperature above 60°C!", (int)temperature);
                buzz(2000);
                temperature_event = 0;
            }
        }

        usleep(100000);
    }

    fclose(log_file);
    close(adc_fd);
    close(flame_sensor_fd);
    gpioTerminate();
    return 0;
}

