#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_FAN_PIN 18
#define DEFAULT_SENSITIVITY 100  // in mV/A
#define DEFAULT_THRESHOLD 5.0    // in A

static int spi_fd = -1;
static int gpio_fd = -1;
static int fan_pin = -1;
static int sensitivity = DEFAULT_SENSITIVITY;
static double threshold = DEFAULT_THRESHOLD;

static void handle_signal(int sig) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_fd >= 0) {
        gpiod_chip_close(gpio_fd);
    }
    if (fan_pin >= 0) {
        gpiod_line_set_value(gpio_fd, fan_pin, 0);
    }
    exit(0);
}

static void log_reading(double current) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    FILE *log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(1);
    }
    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fclose(log_file);
}

static int read_adc() {
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tx);
    if (ret < 0) {
        perror("SPI ioctl failed");
        return -1;
    }
    if (rx[0] != 0x00 || rx[1] == 0xff || rx[2] == 0xff) {
        fprintf(stderr, "Sensor absent or ADC read error\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_current(int adc_value) {
    return adc_value * sensitivity / 1000.0;
}

static void check_current(double current) {
    if (current > threshold) {
        gpiod_line_set_value(gpio_fd, fan_pin, 1);
    } else {
        gpiod_line_set_value(gpio_fd, fan_pin, 0);
    }
}

int main(int argc, char *argv[]) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            sensitivity = atoi(argv[i + 1]);
        } else if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = atof(argv[i + 1]);
        }
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }

    // Set SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(1);
    }
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(1);
    }

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (chip == NULL) {
        chip = gpiod_chip_open("gpiochip0");
        if (chip == NULL) {
            perror("Failed to open GPIO chip");
            close(spi_fd);
            exit(1);
        }
    }

    // Get GPIO line for fan control
    line = gpiod_chip_get_line(chip, GPIO_FAN_PIN);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(1);
    }

    // Request the line for output
    ret = gpiod_line_request_output(line, "fan_control", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
