#define DEFAULT_SENSITIVITY 100  // in mV/A
#define DEFAULT_THRESHOLD 5.0    // in A

static int spi_fd = -1;
static int gpio_fd = -1;
static int fan_pin = -1;
static int sensitivity = DEFAULT_SENSITIVITY;
static double threshold = DEFAULT_THRESHOLD;

static void handle_signal(int sig) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_fd >= 0) {
        gpiod_chip_close(gpio_fd);
    }
    if (fan_pin >= 0) {
        gpiod_line_set_value(gpio_fd, fan_pin, 0);
    }
    exit(0);
}

static void log_reading(double current) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    FILE *log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(1);
    }
    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fclose(log_file);
}

static int read_adc() {
    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tx);
    if (ret < 0) {
        perror("SPI ioctl failed");
        return -1;
    }
    if (rx[0] != 0x00 || rx[1] == 0xff || rx[2] == 0xff) {
        fprintf(stderr, "Sensor absent or ADC read error\n");
        return -1;
    }
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_current(int adc_value) {
    return adc_value * sensitivity / 1000.0;
}

static void check_current(double current) {
    if (current > threshold) {
        gpiod_line_set_value(gpio_fd, fan_pin, 1);
    } else {
        gpiod_line_set_value(gpio_fd, fan_pin, 0);
    }
}

