    line = gpiod_chip_get_line(chip, GPIO_FAN_PIN);
    if (line == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(1);
    }

    // Request the line for output
    ret = gpiod_line_request_output(line, "fan_control", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(1);
    }

    // Set initial fan state
    gpiod_line_set_value(line, 0);

    // Register signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            continue;
        }
        double current = adc_to_current(adc_value);
        check_current(current);
        log_reading(current);
        sleep(1);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);

