#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDRESS 0x48
#define I2C_BUS 1
#define ALERT_THRESHOLD 25
#define LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    int fd;
    uint16_t ox, red;
    float co_ppm;
    char buffer[100];
    struct timespec sleep_time = {0, 500000000}; // 5 seconds

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up I2C bus
    fd = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        // Read data from I2C
        if (i2cRead(fd, buffer, 4) != 4) {
            fprintf(stderr, "Failed to read from I2C\n");
            continue;
        }

        // Parse data
        ox = (buffer[0] << 8) | buffer[1];
        red = (buffer[2] << 8) | buffer[3];

        // Calculate CO level in PPM
        co_ppm = (ox * 250.0 / 65535.0) * 1000.0;

        // Log CO level
        snprintf(buffer, sizeof(buffer), "CO: %.2f PPM\n", co_ppm);
        FILE *co_log = fopen(LOG_FILE, "a");
        if (co_log == NULL) {
            fprintf(stderr, "Failed to open CO log file\n");
        } else {
            fprintf(co_log, buffer);
            fclose(co_log);
        }

        // Check for alert
        if (co_ppm > ALERT_THRESHOLD) {
            snprintf(buffer, sizeof(buffer), "Alert: CO level %.2f PPM\n", co_ppm);
            FILE *alert_log = fopen(ALERT_LOG_FILE, "a");
            if (alert_log == NULL) {
                fprintf(stderr, "Failed to open alert log file\n");
            } else {
                fprintf(alert_log, buffer);
                fclose(alert_log);
            }
        }

        // Sleep for 5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    i2cClose(fd);
    gpioTerminate();

    return 0;
}

