        if (co_ppm > ALERT_THRESHOLD) {
            snprintf(buffer, sizeof(buffer), "Alert: CO level %.2f PPM\n", co_ppm);
            FILE *alert_log = fopen(ALERT_LOG_FILE, "a");
            if (alert_log == NULL) {
                fprintf(stderr, "Failed to open alert log file\n");
            } else {
                fprintf(alert_log, buffer);
                fclose(alert_log);
            }
        }

        // Sleep for 5 seconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    i2cClose(fd);
    gpioTerminate();

    return 0;
}
