        double sound_pressure2 = read_mic(i2c_handle2, REG_ADDR);

        if (sound_pressure1 == -999.0 || sound_pressure2 == -999.0) {
            log_to_file(-999.0);
        } else {
            double average_sound_pressure = (sound_pressure1 + sound_pressure2) / 2.0;
            log_to_file(average_sound_pressure);
        }

        usleep(SAMPLE_RATE * 1000);
    }

    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

