#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>

#define ADC_CHANNEL_1 0
#define ADC_CHANNEL_2 1
#define LED_PIN 27
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define THRESHOLD 0.7
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_DURATION_MS 100
#define CSV_FILE "audio_events.csv"

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    fclose(fp);
    printf("Exiting gracefully.\n");
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_CHANNEL, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SPI_CHANNEL, PI_ALT0) < 0) {
        fprintf(stderr, "Failed to set SPI mode to ALT0.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMFrequency(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMRange(SPI_CHANNEL, 1024) < 0) {
        fprintf(stderr, "Failed to set SPI range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(CSV_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open CSV file.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec start_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (keep_running) {
        uint16_t adc_value1 = 0, adc_value2 = 0;
        uint32_t sum1 = 0, sum2 = 0;

        for (int i = 0; i < WINDOW_DURATION_MS / SAMPLE_INTERVAL_MS; i++) {
            gpioWrite(SPI_CHANNEL, 1);
            usleep(SAMPLE_INTERVAL_MS * 1000);
            gpioWrite(SPI_CHANNEL, 0);

            uint8_t data[3];
            data[0] = 0b11000000 | (ADC_CHANNEL_1 << 4);
            data[1] = 0;
            data[2] = 0;

            if (gpioSPIDataRead(SPI_CHANNEL, data, 3) < 0) {
                fprintf(stderr, "Failed to read SPI data.\n");
                gpioTerminate();
                fclose(fp);
                return EXIT_FAILURE;
            }

            adc_value1 = (data[1] << 8) | data[2];
            sum1 += adc_value1;

            data[0] = 0b11000000 | (ADC_CHANNEL_2 << 4);
            data[1] = 0;
            data[2] = 0;

            if (gpioSPIDataRead(SPI_CHANNEL, data, 3) < 0) {
                fprintf(stderr, "Failed to read SPI data.\n");
                gpioTerminate();
                fclose(fp);
                return EXIT_FAILURE;
            }

            adc_value2 = (data[1] << 8) | data[2];
            sum2 += adc_value2;
        }

        double rms1 = sqrt((double)sum1 / (WINDOW_DURATION_MS / SAMPLE_INTERVAL_MS));
        double rms2 = sqrt((double)sum2 / (WINDOW_DURATION_MS / SAMPLE_INTERVAL_MS));

        clock_gettime(CLOCK_MONOTONIC, &end_time);
        double elapsed_time = (end_time.tv_sec - start_time.tv_sec) + (end_time.tv_nsec - start_time.tv_nsec) / 1e9;

        fprintf(fp, "%.9f,%.3f,%.3f\n", elapsed_time, rms1, rms2);

        if (rms1 > THRESHOLD || rms2 > THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            usleep(500000);
            gpioWrite(LED_PIN, 0);
        }

        start_time = end_time;
    }

    fclose(fp);
    gpioTerminate();
    return EXIT_SUCCESS;
}

