#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

#define I2C_ADDRESS 0x48
#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define LED_PIN 17
#define BUFFER_SIZE 100
#define THRESHOLD 50.0

static int i2c_fd;
static int buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int current_sum = 0;
static int current_count = 0;
static int led_state = 0;
static int running = 1;

void handle_sigint(int signum) {
    running = 0;
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    exit(0);
}

void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);
}

void init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        exit(1);
    }
}

void read_sensor() {
    uint8_t reg = 0x00; // Register for reading the current value
    uint8_t data[2];
    int result;

    result = i2cWriteDevice(i2c_fd, &reg, 1);
    if (result < 0) {
        fprintf(stderr, "Failed to write to I2C register\n");
        return;
    }

    result = i2cReadDevice(i2c_fd, data, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return;
    }

    int current_raw = (data[0] << 8) | data[1];
    float current_voltage = current_raw * 5.0 / 4096.0;
    float current_amps = current_voltage / 0.5;

    buffer[buffer_index] = current_amps;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    current_sum += current_amps;
    current_count++;

    if (current_count >= BUFFER_SIZE) {
        current_sum -= buffer[(buffer_index - BUFFER_SIZE + 1) % BUFFER_SIZE];
        current_count--;
    }

    float average_current = current_sum / current_count;
    if (average_current > THRESHOLD) {
        led_state = 1;
    } else {
        led_state = 0;
    }
}

void update_led() {
    gpioWrite(LED_PIN, led_state);
}

int main() {
    signal(SIGINT, handle_sigint);

    init_pigpio();
    init_i2c();

    while (running) {
        read_sensor();
        update_led();
        usleep(100000); // 10Hz sampling rate
    }

    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

