#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define ID_REG 0x12
#define ATIME_REG 0x01
#define CONTROL_REG 0x0F
#define ENABLE_REG 0x00
#define CLEAR_REG 0x14
#define RED_REG 0x15
#define GREEN_REG 0x16
#define BLUE_REG 0x17

#define MAX_RETRIES 3

void sigint_handler(int sig) {
    FILE *fp = fopen("color_log.csv", "a");
    if (fp) {
        fclose(fp);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    if (pigpio_i2c_open(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    uint8_t id;
    if (pigpio_i2c_read_reg(I2C_BUS, I2C_ADDR, ID_REG, &id) < 0) {
        fprintf(stderr, "Failed to read ID register\n");
        gpioTerminate();
        return 1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Invalid sensor ID\n");
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    uint8_t atime = 0xFF;
    uint8_t control = 0x01; // 4x gain
    if (pigpio_i2c_write_reg(I2C_BUS, I2C_ADDR, ATIME_REG, atime) < 0) {
        fprintf(stderr, "Failed to write ATIME register\n");
        gpioTerminate();
        return 1;
    }
    if (pigpio_i2c_write_reg(I2C_BUS, I2C_ADDR, CONTROL_REG, control) < 0) {
        fprintf(stderr, "Failed to write CONTROL register\n");
        gpioTerminate();
        return 1;
    }
    if (pigpio_i2c_write_reg(I2C_BUS, I2C_ADDR, ENABLE_REG, 0x01 | 0x02) < 0) {
