#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define MCP3008_CS_LINE 8
#define MOISTURE_SENSOR_1_CHANNEL 0
#define MOISTURE_SENSOR_2_CHANNEL 1
#define LOG_FILE "moisture_log.csv"
#define LOG_HEADER "Timestamp,Moisture1,Moisture2\n"

static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *cs_line;
static FILE *log_file;

static void signal_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    exit(signum);
}

static void log_moisture(int channel, int value) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld,%d,%d\n", (long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000, value, value);
}

static int read_moisture(int channel) {
    uint8_t tx[3] = {0x01, (channel << 4) | 0x01, 0x00};
    uint8_t rx[3];
    int ret;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tx);
    if (ret < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    ret = read(spi_fd, rx, 3);
    if (ret < 0) {
        perror("read");
        return -1;
    }

    return (rx[1] << 8) | rx[2];
}

int main() {
    int ret;
    struct timespec sleep_time = {0, 500000000}; // 5 seconds

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    // Set SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("SPI_IOC_WR_MODE");
        goto cleanup;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        goto cleanup;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        goto cleanup;
    }

    // Open libgpiod chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        goto cleanup;
    }

    // Request line for MCP3008 CS
    cs_line = gpiod_chip_get_line(chip, MCP3008_CS_LINE);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    // Request output mode for CS line
    ret = gpiod_line_request_output(cs_line, "moisture_sensor", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        goto cleanup;
    }

    // Write header to log file
    fprintf(log_file, LOG_HEADER);

    // Main loop
    while (1) {
        // Set CS line low
        ret = gpiod_line_set_value(cs_line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            continue;
        }

        // Read moisture from sensor 1
        int moisture1 = read_moisture(MOISTURE_SENSOR_1_CHANNEL);
        if (moisture1 < 0) {
            perror("read_moisture");
            continue;
        }

        // Read moisture from sensor 2
        int moisture2 = read_moisture(MOISTURE_SENSOR_2_CHANNEL);
        if (moisture2 < 0) {
            perror("read_moisture");
            continue;
        }

        // Set CS line high
        ret = gpiod_line_set_value(cs_line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            continue;
        }

        // Log moisture readings
        log_moisture(MOISTURE_SENSOR_1_CHANNEL, moisture1);
        log_moisture(MOISTURE_SENSOR_2_CHANNEL, moisture2);

        // Sleep for 5 seconds
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    return EXIT_FAILURE;
}

