This C program reads analog values from two Seeed Studio Grove Moisture Sensors connected to an MCP3008 SPI ADC on a Raspberry Pi Zero W. It uses the modern libgpiod API for GPIO control and the standard Linux spidev for SPI communication. The program logs timestamped readings to a CSV file named `moisture_log.csv` with headers `Timestamp,Moisture1,Moisture2`. It handles errors and ensures clean release of all resources on all exit paths via SIGINT/SIGTERM signal handling.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define GPIO_SHUTDOWN 17
#define MAX_RETRIES 3
#define LOG_FILE "current_log.csv"
#define HEADER "timestamp,current_in_Amperes\n"

static int spi_fd;
static int gpio_shutdown_fd;
static gpiod_chip *chip;
static gpiod_line *line_shutdown;
static FILE *log_file;

static void signal_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_shutdown_fd >= 0) {
        close(gpio_shutdown_fd);
    }
    exit(signum);
}

static void log_current(double current) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%f\n", timestamp, current);
    fflush(log_file);
}

static int read_adc() {
    uint8_t tx[3] = {0x01, (ADC_CHANNEL << 4), 0x00};
    uint8_t rx[3];
    int retries = 0;
    int ret;

    do {
        ret = spi_read(spi_fd, rx, 3);
        if (ret < 0) {
            perror("spi_read");
            retries++;
        }
    } while (ret < 0 && retries < MAX_RETRIES);

    if (ret < 0) {
        return -1;
    }

    return (rx[1] << 8) | rx[2];
}

static double convert_adc_to_current(int adc_value) {
    double voltage = adc_value * 3.3 / 1023.0;
    double current = (voltage - 0.05) / 0.1;
    return current;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, 0x03) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        exit(EXIT_FAILURE);
    }

    // Open GPIO for shutdown
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }
    line_shutdown = gpiod_chip_get_line(chip, GPIO_SHUTDOWN);
    if (!line_shutdown) {
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(line_shutdown, "shutdown", 0) < 0) {
        perror("gpiod_line_request_output");
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Write header if file is new or empty
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, HEADER);
        fflush(log_file);
    }

    // Main loop
    while (1) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            continue;
        }

        double current = convert_adc_to_current(adc_value);
        log_current(current);

        if (current > 10.0) {
            gpiod_line_set_value(line_shutdown, 0);
            fprintf(stderr, "Overcurrent detected, shutting down motor\n");
            sleep(1);
            gpiod_line_set_value(line_shutdown, 1);
            fprintf(stderr, "Motor re-enabled\n");
        }

        sleep(1);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line_shutdown);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

