#define I2C_BUS 1
#define I2C_ADDR 0x40
#define REG_PRESSURE 0x00
#define FILE_NAME "pressure_log.csv"

static FILE *log_file;
static int i2c_handle;

void log_pressure(double pressure_kPa) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(log_file, "%s,%f\n", timestamp, pressure_kPa);
    fflush(log_file);
}

void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle != -1) {
        gpioI2CClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n", I2C_BUS, I2C_ADDR, gpioErrDescription(i2c_handle));
        gpioTerminate();
        return 1;
    }

    log_file = fopen(FILE_NAME, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", FILE_NAME, strerror(errno));
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "timestamp,pressure_kPa\n");
    fflush(log_file);

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        uint16_t raw_value;
        int result = gpioI2CReadReg16(i2c_handle, REG_PRESSURE, &raw_value);
        if (result < 0) {
            fprintf(stderr, "Failed to read from register 0x%02X: %s\n", REG_PRESSURE, gpioErrDescription(result));
            continue;
        }

        double pressure_kPa = (raw_value / 65535.0) * 500.0;
        log_pressure(pressure_kPa);

        sleep(1);
    }

    fclose(log_file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return 0;
}

