#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <math.h>

#define ADS1115_ADDRESS 0x48
#define GPIO17 17
#define PRESSURE_THRESHOLD 105.0
#define MAX_RETRIES 3

// Function to convert ADC voltage to pressure
double adc_to_pressure(float adc_voltage) {
    return adc_voltage * 400.0 / 5.0;
}

// Function to convert ADC voltage to temperature using a simplified NTC approximation
double adc_to_temperature(float adc_voltage) {
    // Simplified NTC approximation: V = 1.0 + 0.01 * T
    // Rearranging for T: T = (V - 1.0) / 0.01
    return (adc_voltage - 1.0) / 0.01;
}

// Function to read from the ADS1115
int read_ads1115(int channel, int gain) {
    int retries = 0;
    int result = 0;
    while (retries < MAX_RETRIES) {
        result = pi_i2c_read_word_data(ADS1115_ADDRESS, 0x00); // Start conversion
        if (result < 0) {
            printf("Failed to start conversion: %s\n", strerror(errno));
            retries++;
            continue;
        }
        usleep(100000); // Wait for conversion to complete
        result = pi_i2c_read_word_data(ADS1115_ADDRESS, 0x01); // Read conversion result
        if (result < 0) {
            printf("Failed to read conversion result: %s\n", strerror(errno));
            retries++;
            continue;
        }
        // Convert result to voltage
        float adc_voltage = (result >> 4) * 0.0625;
        return adc_voltage;
    }
    printf("Failed to read from ADS1115 after %d retries\n", MAX_RETRIES);
    return -1;
}

// Signal handler for SIGINT
void sigint_handler(int signum) {
    pi_i2c_close(ADS1115_ADDRESS);
    gpio_write(GPIO17, 0);
    gpio_close(GPIO17);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }
    if (pi_i2c_open(ADS1115_ADDRESS, 1) < 0) {
        printf("Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }
    gpioSetMode(GPIO17, PI_OUTPUT);
    gpioWrite(GPIO17, 0);

    signal(SIGINT, sigint_handler);

    while (1) {
        float pressure_voltage = read_ads1115(0, 1); // Single-ended on AIN0
        if (pressure_voltage < 0) {
            continue;
        }
        float pressure = adc_to_pressure(pressure_voltage);
        float temperature = adc_to_temperature(pressure_voltage);

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        if (pressure > PRESSURE_THRESHOLD) {
            gpioWrite(GPIO17, 1);
        } else {
            gpioWrite(GPIO17, 0);
        }

        sleep(1);
    }

    pi_i2c_close(ADS1115_ADDRESS);
    gpioWrite(GPIO17, 0);
    gpio_close(GPIO17);
    gpioTerminate();
    return 0;
}

