#define MLX91209_CHANNEL 0
#define MLX91209_VCC 3.3
#define MLX91209_SENSITIVITY 66e-3 // 66 mV/A
#define MLX91209_ZERO_CURRENT (MLX91209_VCC / 2)
#define MLX91209_MAX_CURRENT 10.0
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL_MS 100

static int spiHandle;
static int gpioShutdownPin = 27;
static FILE *logFile;
static volatile sig_atomic_t shouldExit = 0;

void signalHandler(int sig) {
    shouldExit = 1;
}

void logCurrent(float current) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(logFile, "%s,%.2f\n", timestamp, current);
    fflush(logFile);
}

void shutdownMotor() {
    gpioWrite(gpioShutdownPin, 1);
    logCurrent(MLX91209_MAX_CURRENT);
    gpioWrite(gpioShutdownPin, 0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(gpioShutdownPin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for shutdown pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(gpioShutdownPin, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO low for shutdown pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((spiHandle = gpioSpiOpen(0, 1000000, 0)) < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((logFile = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioSpiClose(spiHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    while (!shouldExit) {
        uint8_t tx[3] = {0x01, (MLX91209_CHANNEL << 4) | 0x00, 0x00};
        uint8_t rx[3];

        if (gpioSpiRead(spiHandle, rx, sizeof(rx)) < 0) {
            fprintf(stderr, "Failed to read SPI data\n");
            break;
        }

        uint16_t adcValue = (rx[1] << 8) | rx[2];
        if (adcValue > 1023) {
            fprintf(stderr, "Invalid ADC value\n");
            break;
        }

        float voltage = adcValue * (MLX91209_VCC / 1024.0);
        float current = (voltage - MLX91209_ZERO_CURRENT) / MLX91209_SENSITIVITY;

        logCurrent(current);

        if (current > MLX91209_MAX_CURRENT) {
            shutdownMotor();
            shouldExit = 1;
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(logFile);
    gpioSpiClose(spiHandle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

