#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define CO_SENSOR_CHANNEL 0
#define SPI_BUS 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define ALARM_PIN 4
#define LOG_FILE "co_log.txt"

static int spiHandle;
static FILE *logFile;

void logError(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void logReading(const char *timeStr, float voltage) {
    fprintf(logFile, "%s,Voltage: %.2f V\n", timeStr, voltage);
}

void handleAlarm(int alarmState) {
    if (gpioWrite(ALARM_PIN, alarmState)) {
        logError("Failed to set alarm state");
    }
}

void handleSignal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        if (logFile) {
            fclose(logFile);
        }
        if (spiHandle != -1) {
            spiClose(spiHandle);
        }
        gpioTerminate();
        exit(0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        logError("Failed to initialize GPIO");
        return 1;
    }

    if (gpioSetMode(ALARM_PIN, PI_OUTPUT)) {
        logError("Failed to set alarm pin mode");
        gpioTerminate();
        return 1;
    }

    if (spiOpen(SPI_BUS, SPI_CHANNEL, SPI_SPEED) < 0) {
        logError("Failed to open SPI bus");
        gpioTerminate();
        return 1;
    }

    logFile = fopen(LOG_FILE, "w");
    if (!logFile) {
        logError("Failed to open log file");
        spiClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);

    while (1) {
        char spiData[3];
        spiData[0] = 0b11000000 | (CO_SENSOR_CHANNEL << 4); // Start bit, MSB first, channel 0
        spiData[1] = 0;
        spiData[2] = 0;

        if (spiXfer(spiHandle, spiData, spiData, 3) < 0) {
            logError("SPI transfer failed");
            handleAlarm(0); // Turn off alarm
            sleep(1);
            continue;
        }

        int adcValue = (spiData[1] << 8) | spiData[2];
        float voltage = (adcValue * 3.3) / 1023.0;

        char timeStr[20];
        time_t now = time(NULL);
        strftime(timeStr, sizeof(timeStr), "%Y-%m-%d %H:%M:%S", localtime(&now));

        logReading(timeStr, voltage);

        handleAlarm(voltage > 2.5);

