#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MLX90830_I2C_ADDR 0x48
#define ADS1115_I2C_ADDR 0x48
#define ADS1115_AIN0 0x00
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_DATA_REG 0x00
#define ADS1115_GAIN_1 = 0x00
#define ADS1115_MODE_CONTINUOUS = 0x01
#define ADS1115_RATE_128 = 0x01
#define ADS1115_DR_128 = 0x00
#define ADS1115_PGA_6144 = 0x00
#define ADS1115_MODE_SINGLE_SHOT = 0x00
#define ADS1115_RATE_128 = 0x01
#define ADS1115_DR_128 = 0x00
#define ADS1115_PGA_6144 = 0x00
#define MLX90830_OFFSET 0.5
#define MLX90830_SENSITIVITY 0.1
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t quit = 0;

void signal_handler(int sig) {
    quit = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (i2cOpen(1, MLX90830_I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus for MLX90830\n");
        gpioTerminate();
        return 1;
    }

    if (i2cOpen(1, ADS1115_I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus for ADS1115\n");
        i2cClose(1, MLX90830_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115 for continuous conversion mode, 128SPS, PGA 6144
    uint16_t config = ADS1115_MODE_CONTINUOUS | ADS1115_RATE_128 | ADS1115_DR_128 | ADS1115_PGA_6144;
    if (i2cWriteReg(1, ADS1115_I2C_ADDR, ADS1115_CONFIG_REG, config) < 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        i2cClose(1, MLX90830_I2C_ADDR);
        i2cClose(1, ADS1115_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(1, MLX90830_I2C_ADDR);
        i2cClose(1, ADS1115_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        fclose(log_file);
        i2cClose(1, MLX90830_I2C_ADDR);
        i2cClose(1, ADS1115_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    while (!quit) {
        uint16_t adc_value;
        if (i2cReadReg(1, ADS1115_I2C_ADDR, ADS1115_DATA_REG, &adc_value) < 0) {
            fprintf(stderr, "Failed to read ADC data\n");
            continue;
        }

        // Convert ADC value to voltage
        float voltage = (adc_value * 4.096) / 65536.0;

        // Convert voltage to pressure
        float pressure = (voltage - MLX90830_OFFSET) / MLX90830_SENSITIVITY;

        // Check if pressure is within valid range
        if (pressure >= 0.0 && pressure <= 100.0) {
            // Log pressure with ISO-8601 timestamp
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
            fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
        }

        // Sleep for 1 second
        sleep(1);
    }

    fclose(log_file);
    i2cClose(1, MLX90830_I2C_ADDR);
    i2cClose(1, ADS1115_I2C_ADDR);
    gpioTerminate();

    return 0;
}

