#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <syslog.h>
#include <curl/curl.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3208_CS 8
#define MCP3208_DIN 9
#define MCP3208_DOUT 10
#define MCP3208_CLK 11
#define HIH4602_A_VCC 5.0
#define HIH4602_A_BETA 3950.0
#define HIH4602_A_R0 10000.0
#define HIH4602_A_TEMP_25 25.0
#define HIH4602_A_TEMP_OFFSET 0.0
#define HIH4602_A_TEMP_SCALE 0.0
#define HIH4602_A_HUMIDITY_OFFSET 0.0
#define HIH4602_A_HUMIDITY_SCALE 0.0
#define EMAIL_ALERT_THRESHOLD 80.0
#define EMAIL_ALERT_SUBJECT "Honeywell HIH-4602-A Alert"
#define EMAIL_ALERT_BODY "Humidity exceeds 80%: %f%%"
#define EMAIL_ALERT_SERVER "smtp.example.com"
#define EMAIL_ALERT_PORT 587
#define EMAIL_ALERT_USER "your-email@example.com"
#define EMAIL_ALERT_PASS "your-email-password"
#define EMAIL_ALERT_FROM "your-email@example.com"
#define EMAIL_ALERT_TO "recipient-email@example.com"

static int spiHandle;
static FILE *logFile;
static CURL *curl;
static CURLcode res;

static void signalHandler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        syslog(LOG_INFO, "Received signal %d, cleaning up", sig);
        if (logFile) {
            fclose(logFile);
        }
        if (curl) {
            curl_easy_cleanup(curl);
        }
        if (spiHandle != -1) {
            gpioTerminate();
        }
        syslog(LOG_INFO, "Exiting...");
        exit(EXIT_SUCCESS);
    }
}

static size_t writeCallback(void *contents, size_t size, size_t nmemb, void *userp) {
    FILE *file = (FILE *)userp;
    size_t totalSize = size * nmemb;
    if (fwrite(contents, 1, totalSize, file) != totalSize) {
        syslog(LOG_ERR, "Failed to write to file");
        return 0;
    }
    return totalSize;
}

static void logReading(const char *timestamp, float humidity, float temperature) {
    if (logFile) {
        fprintf(logFile, "%s,%f,%f\n", timestamp, humidity, temperature);
        fflush(logFile);
    }
}

static void sendEmailAlert(float humidity) {
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, EMAIL_ALERT_SERVER);
        curl_easy_setopt(curl, CURLOPT_PORT, EMAIL_ALERT_PORT);
        curl_easy_setopt(curl, CURLOPT_USE_SSL, (long)CURLUSESSL_ALL);
        curl_easy_setopt(curl, CURLOPT_USERNAME, EMAIL_ALERT_USER);
        curl_easy_setopt(curl, CURLOPT_PASSWORD, EMAIL_ALERT_PASS);
        curl_easy_setopt(curl, CURLOPT_MAIL_FROM, EMAIL_ALERT_FROM);
        curl_easy_setopt(curl, CURLOPT_MAIL_RCPT, EMAIL_ALERT_TO);
        curl_easy_setopt(curl, CURLOPT_MAIL_SUBJECT, EMAIL_ALERT_SUBJECT);
        curl_easy_setopt(curl, CURLOPT_MAIL_BODY, EMAIL_ALERT_BODY, humidity);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, logFile);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "Failed to send email: %s", curl_easy_strerror(res));
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    if (gpioSetMode(MCP3208_CS, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set MCP3208 CS mode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(MCP3208_DIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set MCP3208 DIN mode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(MCP3208_DOUT, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set MCP3208 DOUT mode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(MCP3208_CLK, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set MCP3208 CLK mode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if ((spiHandle = gpioSpiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        syslog(LOG_ERR, "Failed to open SPI channel");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if ((logFile = fopen("humidity_log.txt", "w")) == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if ((curl = curl_easy_init()) == NULL) {
        syslog(LOG_ERR, "Failed to initialize curl");
        fclose(logFile);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    while (1) {
        char spiData[3];
        spiData[0] = 0b11000000; // Start bit, single-ended mode, channel 0
        spiData[1] = 0b00000000; // MSB of channel number
        spiData[2] = 0b00000000; // LSB of channel number

        if (gpioSpiRead(spiHandle, spiData, 3) < 0) {
            syslog(LOG_ERR, "Failed to read SPI data");
            continue;
        }

        int adcValue = (spiData[1] << 8) | spiData[2];
        float voltage = adcValue * (HIH4602_A_VCC / 4095.0);

        float humidity = (voltage - 0.824) / 0.0315;
        float temperature = HIH4602_A_TEMP_25 + (HIH4602_A_TEMP_OFFSET + HIH4602_A_TEMP_SCALE * (log(voltage / HIH4602_A_R0) / log(10.0))) / (HIH4602_A_BETA / (HIH4602_A_BETA + HIH4602_A_TEMP_25));

        logReading(strftime(NULL, 0, "%Y-%m-%d %H:%M:%S", NULL), humidity, temperature);

        if (humidity > EMAIL_ALERT_THRESHOLD) {
            sendEmailAlert(humidity);
        }

        sleep(60); // Read every minute
    }

    curl_easy_cleanup(curl);
    fclose(logFile);
    gpioTerminate();
    return 0;
}

