#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define ADC_CHANNEL 0
#define VREF 3.3
#define TEMP_MIN_C -40.0
#define TEMP_MAX_C 125.0
#define LOG_FILE "temperature_log.csv"
#define MAX_LOG_SIZE 1024 * 1024 // 1MB

static int spi_fd;
static int gpio_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

static void signal_handler(int sig) {
    should_exit = 1;
}

static void log_temperature(double temp_celsius) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d,%H:%M:%S", tm);
    fprintf(log_file, "%s,%f\n", timestamp, temp_celsius);
    fflush(log_file);
}

static void read_temperature() {
    uint8_t tx[3] = {0b11000000, (ADC_CHANNEL << 4) | 0x01, 0x00};
    uint8_t rx[3];
    int ret;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, tx, sizeof(tx), rx, sizeof(rx));
    if (ret < 0) {
        perror("SPI_IOC_MESSAGE");
        return;
    }

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    double voltage = adc_value * VREF / 4095.0;
    double temp_celsius = (voltage - 0.5) / 0.01;

    if (temp_celsius < TEMP_MIN_C || temp_celsius > TEMP_MAX_C) {
        fprintf(stderr, "Invalid temperature reading: %f\n", temp_celsius);
        return;
    }

    log_temperature(temp_celsius);
}

static void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line, "spi_cs", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpiod_line_get_fd(line);
    if (gpio_fd < 0) {
        perror("gpiod_line_get_fd");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ);
    if (ret < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

static void setup_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
}

static void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_fd >= 0) {
        close(gpio_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    gpiod_chip_close(gpio_fd);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();
    setup_spi();
    setup_log_file();

    while (!should_exit) {
        read_temperature();
        sleep(1);
    }

    cleanup();
    return 0;
}

