#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNELS 3
#define LOG_FILE "impact_log.txt"
#define G_THRESHOLD 2.0
#define G_SENSITIVITY 0.3
#define G_OFFSET 1.65
#define G_VREF 3.3

static volatile sig_atomic_t exit_flag = 0;

void signal_handler(int signum) {
    exit_flag = 1;
}

int main() {
    int spi_fd, adc_fd;
    struct spi_ioc_transfer transfers[ADC_CHANNELS];
    uint8_t spi_buf[ADC_CHANNELS * 3];
    uint8_t adc_buf[ADC_CHANNELS];
    uint32_t adc_values[ADC_CHANNELS];
    double acceleration_magnitude;
    char timestamp[20];
    struct timespec ts;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up SPI
    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    // Set up ADC channels
    for (int i = 0; i < ADC_CHANNELS; i++) {
        transfers[i].cs_change = 1;
        transfers[i].bits_per_word = 8;
        transfers[i].len = 3;
        transfers[i].speed_hz = SPI_SPEED;
        transfers[i].delay_usecs = 0;
        transfers[i].tx_buf = (unsigned long)(spi_buf + i * 3);
        transfers[i].rx_buf = (unsigned long)(adc_buf + i);
    }

    // Set up file for logging
    adc_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!exit_flag) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Perform SPI transfers
        for (int i = 0; i < ADC_CHANNELS; i++) {
            if (spiXfer(spi_fd, &transfers[i]) < 0) {
                fprintf(stderr, "Failed to transfer SPI data\n");
                break;
            }
        }

        // Read ADC values
        for (int i = 0; i < ADC_CHANNELS; i++) {
            adc_values[i] = (adc_buf[i] << 8) | (adc_buf[i + 1]);
            if (adc_values[i] > 1023 || adc_values[i] < 0) {
                fprintf(stderr, "Invalid ADC value: %d\n", adc_values[i]);
                break;
            }
        }

        // Calculate acceleration magnitude
        acceleration_magnitude = G_SENSITIVITY * (adc_values[0] - G_OFFSET) / G_VREF;
        acceleration_magnitude += G_SENSITIVITY * (adc_values[1] - G_OFFSET) / G_VREF;
        acceleration_magnitude += G_SENSITIVITY * (adc_values[2] - G_OFFSET) / G_VREF;
        acceleration_magnitude /= 3.0;

        // Log data
        fprintf(adc_fd, "%s,%d,%d,%d,%f\n", timestamp, adc_values[0], adc_values[1], adc_values[2], acceleration_magnitude);

        // Check for impact
        if (acceleration_magnitude > G_THRESHOLD) {
            fprintf(adc_fd, "IMPACT DETECTED\n");
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    close(adc_fd);
    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}

