            fprintf(adc_fd, "IMPACT DETECTED\n");
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    close(adc_fd);
    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}
```

This C program interfaces with an ADXL335 accelerometer via an MCP3008 10-bit ADC on SPI0, CE0/GPIO8, at 1 MHz, SPI Mode 0, using the pigpio library for SPI and GPIO. It logs the X, Y, Z raw ADC values to impact_log.txt, timestamped and comma-separated, computes the acceleration magnitude in g, and flags impacts exceeding 2.0g with an 'IMPACT DETECTED' line in the log. It includes robust error handling and a signal handler to cleanly exit on SIGINT.

