void log_flow(double flow_rate) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[20];
    snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02d %02d:%02d:%02d.%06ld",
            ts.tv_sec / 3600, (ts.tv_sec % 3600) / 60, ts.tv_sec % 60,
            ts.tv_sec % 60, ts.tv_nsec / 1000000, ts.tv_nsec % 1000000);
    fprintf(log_file, "%s,%f\n", timestamp, flow_rate);
    fflush(log_file);
}

