#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x67
#define MEASURE_CMD 0x6845
#define CRC_LENGTH 3
#define MAX_RETRIES 5
#define LOG_FILE "environmental_data.csv"

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

static void log_data(const char *data) {
    if (log_file) {
        fprintf(log_file, "%s\n", data);
    }
}

static void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

static void init_i2c() {
    char i2c_path[20];
    snprintf(i2c_path, sizeof(i2c_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_path, O_RDWR);
    if (i2c_fd == -1) {
        log_error("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void write_measure_cmd() {
    if (write(i2c_fd, &MEASURE_CMD, 2) != 2) {
        log_error("Failed to write measurement command");
    }
}

static void read_result(unsigned char *result) {
    if (read(i2c_fd, result, 6) != 6) {
        log_error("Failed to read result");
    }
}

static void calculate_temperature(unsigned char *result) {
    unsigned int temp_raw = (result[0] << 8) | result[1];
    float temp_celsius = (temp_raw * 0.000152675) - 40.0;
    printf("Temperature: %.2f°C\n", temp_celsius);
}

static void calculate_pressure(unsigned char *result) {
    unsigned int pressure_raw = (result[2] << 16) | (result[3] << 8) | result[4];
    float pressure_pa = (pressure_raw * 0.01) + 98066.5;
    printf("Pressure: %.2fPa\n", pressure_pa);
}

static void log_csv(const char *data) {
    if (log_file) {
        fprintf(log_file, "%s\n", data);
    }
}

static void log_timestamped_data(const char *data) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    log_csv(timestamp);
    log_csv(data);
}

static void sample_data() {
    unsigned char result[6];
    for (int i = 0; i < MAX_RETRIES; i++) {
        write_measure_cmd();
        usleep(100000); // Wait for conversion to finish
        read_result(result);
        calculate_temperature(result);
        calculate_pressure(result);
        char data[100];
        snprintf(data, sizeof(data), "%d,%d,%d,%d,%d,%d", result[0], result[1], result[2], result[3], result[4], result[5]);
        log_timestamped_data(data);
        sleep(5); // Sample every 5 seconds
    }
    log_error("Failed to read data after multiple retries");
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c();
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        log_error("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    sample_data();

    fclose(log_file);
    close(i2c_fd);

    return 0;
}

