#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

#define ADC_CHANNEL 0
#define ADC_CHANNEL_2 1
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SAMPLE_RATE 44100
#define BUFFER_SIZE 1024
#define GAIN 1.0

static int gpiod_handle;
static int spi_handle;
static int gain = 1;

static void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, cleaning up...\n");
        gpioTerminate();
        close(spi_handle);
        exit(EXIT_SUCCESS);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <gain>\n", argv[0]);
        return EXIT_FAILURE;
    }

    if (sscanf(argv[1], "%d", &gain) != 1) {
        fprintf(stderr, "Invalid gain value\n");
        return EXIT_FAILURE;
    }

    if (gain < 0 || gain > 10) {
        fprintf(stderr, "Gain must be between 0 and 10\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (pigpio_start(&gpiod_handle, 0) < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (pigpio_spi_open(gpiod_handle, SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        pigpio_stop(gpiod_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    int16_t buffer[BUFFER_SIZE];
    int16_t buffer2[BUFFER_SIZE];
    int16_t result[BUFFER_SIZE];
    int16_t *data = buffer;
    int16_t *data2 = buffer2;
    int16_t *result_data = result;

    while (1) {
        if (data == buffer) {
            data = buffer2;
            data2 = buffer;
        }

        if (pigpio_spi_read(gpiod_handle, SPI_CHANNEL, data, BUFFER_SIZE * 2) < 0) {
            fprintf(stderr, "SPI read error\n");
            continue;
        }

        for (int i = 0; i < BUFFER_SIZE; i++) {
            data[i] = data[i] * gain;
            data2[i] = data2[i] * gain;
            result[i] = data[i] - data2[i];
        }

        for (int i = 0; i < BUFFER_SIZE; i++) {
            printf("%d,", result[i]);
        }
        printf("\n");

        usleep(1000000 / SAMPLE_RATE);
    }

    pigpio_spi_close(gpiod_handle);
    pigpio_stop(gpiod_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

