#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define ADC_MAX 1023
#define LOG_FILE "moisture_log.txt"
#define SAMPLE_INTERVAL 60000 // 60 seconds in milliseconds

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
}

int main() {
    FILE *log_file;
    struct timespec ts;
    uint16_t adc_value;
    char timestamp[20];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up SPI channel
    if (gpioSetMode(SPI_CHANNEL, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMFrequency(SPI_CHANNEL, 1000000) < 0) {
        fprintf(stderr, "Failed to set SPI frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMRange(SPI_CHANNEL, 1024) < 0) {
        fprintf(stderr, "Failed to set SPI range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        // Generate SPI command to read ADC
        uint8_t command = 0b11000000 | (SPI_CHANNEL << 5);

        // Transfer command and read ADC value
        if (gpioSPIDataRW(SPI_CHANNEL, &command, 1) < 0) {
            fprintf(stderr, "Failed to send SPI command\n");
            break;
        }

        if (gpioSPIDataRW(SPI_CHANNEL, &adc_value, 2) < 0) {
            fprintf(stderr, "Failed to read SPI data\n");
            break;
        }

        // Validate ADC value
        if (adc_value > ADC_MAX) {
            fprintf(stderr, "Invalid ADC value: %u\n", adc_value);
            break;
        }

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%FT%TZ", gmtime(&ts.tv_sec));

        // Write to log file
        fprintf(log_file, "%s,%u\n", timestamp, adc_value);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL);
    }

    // Close log file
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();

    return EXIT_SUCCESS;
}

