#define FLAME_THRESHOLD 1.0
#define TEMP_OFFSET 25.0
#define TEMP_SCALE 0.001

static int spi_fd;
static int buzzer_fd;
static FILE *log_file;
static int flame_detected = 0;
static int ambient_temp = 25;

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    if (log_file) {
        fprintf(log_file, "Error: %s\n", msg);
    }
}

void log_reading(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%d,%f,%f,%f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
}

void read_ambient_temp() {
    FILE *file = fopen(AMBIENT_TEMP_FILE, "r");
    if (file) {
        if (fscanf(file, "%d", &ambient_temp) != 1) {
            log_error("Invalid ambient temperature in file");
            ambient_temp = 25;
        }
        fclose(file);
    } else {
        log_error("Failed to open ambient temperature file");
        ambient_temp = 25;
    }
}

void read_flame_log() {
    FILE *file = fopen(FLAME_LOG_FILE, "r");
    if (file) {
        char line[256];
        while (fgets(line, sizeof(line), file)) {
            // Parse the line and update flame_detected if necessary
        }
        fclose(file);
    }
}

void write_flame_log(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    FILE *file = fopen(FLAME_LOG_FILE, "a");
    if (file) {
        log_reading(raw_adc, voltage, compensated_voltage, temperature, flame_detected);
        fclose(file);
    } else {
        log_error("Failed to open flame log file");
    }
}

void setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer transfer;
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)0; // Dummy transmit buffer
    transfer.rx_buf = (unsigned long)0; // Dummy receive buffer
    transfer.len = 3; // 3-byte transfer (start bit, single-ended config, dummy byte)
    transfer.speed_hz = SPI_SPEED_HZ;
    transfer.bits_per_word = SPI_BITS_PER_WORD;
    transfer.cs_change = 1; // Change CS after transfer

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer) < 0) {
        log_error("Failed to send SPI message");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_buzzer() {
    buzzer_fd = gpiochip_open(0);
    if (buzzer_fd < 0) {
        log_error("Failed to open GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    int gpio = gpio_export(BUZZER_PIN, GPIOF_OUT_INIT_LOW);
    if (gpio < 0) {
        log_error("Failed to export GPIO");
        gpiochip_close(buzzer_fd);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (buzzer_fd >= 0) {
        gpio_unexport(BUZZER_PIN);
        gpiochip_close(buzzer_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void handle_sigint(int signum) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    signal(SIGINT, handle_sigint);

    read_ambient_temp();
    read_flame_log();

    setup_spi();
    setup_buzzer();

    log_file = fopen(FLAME_LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open flame log file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        int raw_adc;
        float voltage, compensated_voltage, temperature;

        for (int retry = 0; retry < SPI_MAX_RETRIES; retry++) {
            struct spi_ioc_transfer transfer;
            memset(&transfer, 0, sizeof(transfer));
            transfer.tx_buf = (unsigned long)0; // Dummy transmit buffer
            transfer.rx_buf = (unsigned long)&raw_adc; // Receive buffer for ADC value
            transfer.len = 3; // 3-byte transfer (start bit, single-ended config, dummy byte)
            transfer.speed_hz = SPI_SPEED_HZ;
            transfer.bits_per_word = SPI_BITS_PER_WORD;
            transfer.cs_change = 1; // Change CS after transfer

            if (ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer) >= 0) {
                break;
            } else {
                log_error("Failed to send SPI message");
                usleep(100000); // Wait before retrying
            }
        }

        if (retry == SPI_MAX_RETRIES) {
            log_error("Failed to read ADC value");
            continue;
        }

        voltage = (float)raw_adc / 1023.0 * 3.3;
        compensated_voltage = voltage + (temperature - TEMP_OFFSET) * TEMP_SCALE;
        flame_detected = compensated_voltage > FLAME_THRESHOLD;

        log_reading(raw_adc, voltage, compensated_voltage, temperature, flame_detected);

        if (flame_detected) {
            gpio_set_value(buzzer_fd, 1);
        } else {
            gpio_set_value(buzzer_fd, 0);
        }

        usleep(500000); // Sample every 500ms
    }

    cleanup();
    return 0;
}

