code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define LED_PIN 17
#define HYSTERESIS 5

static int spiHandle;
static FILE *jsonFile;
static int ledState = 0;
static int waterLevel = 0;

static void sigHandler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fclose(jsonFile);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

static void logJsonEntry(const char *timestamp, int waterLevel) {
    fprintf(jsonFile, "{\"timestamp\": \"%s\", \"water_level\": %d}\n", timestamp, waterLevel);
}

static void updateLed() {
    if (waterLevel > 75) {
        ledState = 1;
    } else if (waterLevel < 70) {
        ledState = 0;
    }
    gpioWrite(LED_PIN, ledState);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error(gpioInitialise()));
        return EXIT_FAILURE;
    }
    signal(SIGINT, sigHandler);
    signal(SIGTERM, sigHandler);

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode: %s\n", pigpio_error(gpioSetMode(LED_PIN, PI_OUTPUT)));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((spiHandle = gpioSpiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %s\n", SPI_CHANNEL, pigpio_error(spiHandle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    jsonFile = fopen("water_levels.json", "w");
    if (jsonFile == NULL) {
        fprintf(stderr, "Failed to open JSON file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(jsonFile, "[");

    while (1) {
        struct timespec sleepTime = {0, 500000000}; // 5 seconds
        nanosleep(&sleepTime, NULL);

        uint8_t tx[3] = {0x01, 0x80 | (ADC_CHANNEL << 4), 0x00};
        uint8_t rx[3];
        int result = gpioSpiXfer(spiHandle, tx, rx, 3);
        if (result < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", pigpio_error(result));
            continue;
        }

        waterLevel = ((rx[1] & 0x03) << 8) | rx[2];
        logJsonEntry(strftime(NULL, sizeof(NULL), "%Y-%m-%dT%H:%M:%S.%03dZ", time(NULL)), waterLevel);
        updateLed();

        if (jsonFile != NULL) {
            fprintf(jsonFile, ",");
        }
    }

    fclose(jsonFile);
    gpioTerminate();
    return EXIT_SUCCESS;
}

