#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0
#define AWM7300V_CHANNEL 0
#define AWM7300V_OFFSET 0.0001 // Adjust based on sensor calibration
#define AWM7300V_SCALE 0.0001 // Adjust based on sensor calibration
#define LPM_TO_LITERS 0.001 // 1 LPM = 0.001 liters per second

static int spiHandle;
static FILE *logFile;
static volatile sig_atomic_t shouldExit = 0;

void handleSignal(int sig) {
    shouldExit = 1;
}

void setupPigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
}

void setupSPI() {
    spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_BITS, SPI_MODE);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void setupLogging() {
    logFile = fopen("airflow_log.csv", "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file airflow_log.csv\n");
        spiClose(spiHandle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (fseek(logFile, 0, SEEK_END) == 0) {
        // File is not empty, append to it
    } else {
        // File is empty, write header
        fprintf(logFile, "Timestamp,FlowRateLPM\n");
    }
}

void readAWM7300V() {
    uint8_t command[3] = {0x01, 0x00, 0x00}; // Start conversion
    if (spiXfer(spiHandle, command, command, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return;
    }
    usleep(100000); // Wait for conversion to complete
    uint8_t data[3] = {0x00, 0x00, 0x00};
    if (spiXfer(spiHandle, data, data, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return;
    }
    uint16_t rawValue = (data[1] << 8) | data[0];
    double flowRate = (rawValue - AWM7300V_OFFSET) * AWM7300V_SCALE;
    fprintf(logFile, "%s,%f\n", ctime(&time(NULL)), flowRate * LPM_TO_LITERS);
}

void cleanup() {
    if (logFile != NULL) {
        fclose(logFile);
    }
    if (spiHandle >= 0) {
        spiClose(spiHandle);
    }
    gpioTerminate();
}

int main() {
    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);

    setupPigpio();
    setupSPI();
    setupLogging();

    while (!shouldExit) {
        readAWM7300V();
        usleep(100000); // Sample every 100 milliseconds
    }

    cleanup();
    return 0;
}

