#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define CALIB_MIN 300
#define CALIB_MAX 700
#define MOISTURE_THRESHOLD 30
#define LOGGING_FREQUENCY 60
#define EMAIL_RECIPIENT "example@example.com"
#define MSMTP_CONFIG "/etc/msmtp.conf"

static int spi_fd;
static int gpio_fd;
static int pigpio_handle;
static FILE *log_file;
static int email_sent = 0;

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

void log_data(const char *timestamp, int moisture_percent) {
    fprintf(log_file, "%s, %d\n", timestamp, moisture_percent);
}

void send_email(const char *body) {
    FILE *msmtp = popen("msmtp " EMAIL_RECIPIENT, "w");
    if (!msmtp) {
        log_error("Failed to open msmtp");
        return;
    }
    fprintf(msmtp, "%s", body);
    int status = pclose(msmtp);
    if (status != 0) {
        log_error("Failed to send email");
    } else {
        email_sent = 1;
    }
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        close(spi_fd);
        gpioTerminate();
        fclose(log_file);
        exit(0);
    }
}

int main(int argc, char *argv[]) {
    if (argc != 10) {
        fprintf(stderr, "Usage: %s <spi_channel> <adc_channel> <calib_min> <calib_max> <moisture_threshold> <logging_frequency> <email_recipient> <msmtp_config>\n", argv[0]);
        return 1;
    }

    int spi_channel = atoi(argv[1]);
    int adc_channel = atoi(argv[2]);
    int calib_min = atoi(argv[3]);
    int calib_max = atoi(argv[4]);
    int moisture_threshold = atoi(argv[5]);
    int logging_frequency = atoi(argv[6]);
    const char *email_recipient = argv[7];
    const char *msmtp_config = argv[8];

    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        return 1;
    }
    gpio_fd = gpioOpen(21, 0); // Assuming GPIO 21 is used for SPI CE0
    if (gpio_fd < 0) {
        log_error("Failed to open GPIO");
        gpioTerminate();
        return 1;
    }

    if (pigpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        gpioTerminate();
        gpioClose(gpio_fd);
        return 1;
    }
    pigpio_handle = pigpio_start(0, 0);
    if (pigpio_handle < 0) {
        log_error("Failed to start pigpio");
        gpioTerminate();
        gpioClose(gpio_fd);
        return 1;
    }

    if (access(msmtp_config, F_OK) != 0) {
        log_error("MSMTP config file not found");
        gpioTerminate();
        gpioClose(gpio_fd);
        return 1;
    }

    if (access(email_recipient, F_OK) != 0) {
        log_error("Email recipient not found");
        gpioTerminate();
        gpioClose(gpio_fd);
        return 1;
    }

    if (access("/dev/spidev0.0", F_OK) != 0) {
        log_error("SPI device not found");
        gpioTerminate();
        gpioClose(gpio_fd);
        return 1;
    }

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        log_error("Failed to open SPI device");
        gpioTerminate();
        gpioClose(gpio_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, 0) < 0) {
        log_error("Failed to set SPI mode");
        close(spi_fd);
        gpioTerminate();
        gpioClose(gpio_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) < 0) {
        log_error("Failed to set SPI bits per word");
        close(spi_fd);
        gpioTerminate();
        gpioClose(gpio_fd);
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 500000) < 0) {
        log_error("Failed to set SPI max speed");
        close(spi_fd);
        gpioTerminate();
        gpioClose(gpio_fd);
        return 1;
    }

    log_file = fopen("plant_data.txt", "a");
    if (!log_file) {
        log_error("Failed to open log file");
        close(spi_fd);
        gpioTerminate();
        gpioClose(gpio_fd);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        uint8_t tx[3] = {0x01, (adc_channel << 4) | 0x00, 0x00};
        uint8_t rx[3] = {0, 0, 0};

        if (write(spi_fd, tx, 3) != 3) {
            log_error("Failed to write to SPI");
            continue;
        }

        if (read(spi_fd, rx, 3) != 3) {
            log_error("Failed to read from SPI");
            continue;
        }

        int raw_value = (rx[1] << 8) | rx[2];
        int moisture_percent = (raw_value - calib_min) * 100 / (calib_max - calib_min);

        log_data(asctime(timegm), moisture_percent);

        if (moisture_percent < moisture_threshold && !email_sent) {
            char email_body[256];
            snprintf(email_body, sizeof(email_body), "Moisture level is below %d%%: %d%%", moisture_threshold, moisture_percent);
            send_email(email_body);
        }

        sleep(logging_frequency);
    }

    close(spi_fd);
    gpioTerminate();
    gpioClose(gpio_fd);
    fclose(log_file);

    return 0;
}

