#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define LOG_FILE "soil_moisture.log"
#define MAX_SAMPLES 1000000
#define DEFAULT_SAMPLE_INTERVAL 1

static int spi_fd;
static FILE *log_file;
static int sample_interval = DEFAULT_SAMPLE_INTERVAL;
static int running = 1;

void sigint_handler(int sig) {
    running = 0;
    close(spi_fd);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    int ret;
    struct spi_ioc_transfer xfer;
    uint8_t tx[2] = {0x01, ADC_CHANNEL << 4};
    uint8_t rx[2];
    uint16_t adc_value;
    float moisture_percentage;
    char timestamp[20];

    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Invalid sample interval: %s\n", argv[1]);
            return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", SPI_DEVICE);
        gpioTerminate();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        memset(&xfer, 0, sizeof(xfer));
        xfer.tx_buf = (unsigned long)tx;
        xfer.rx_buf = (unsigned long)rx;
        xfer.len = 2;
        xfer.speed_hz = SPI_SPEED_HZ;
        xfer.bits_per_word = 8;
        xfer.cs_change = 0;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE, &xfer) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        adc_value = (rx[0] << 8) | rx[1];
        moisture_percentage = (adc_value / 1023.0) * 100.0;
        moisture_percentage = fmax(0.0, fmin(moisture_percentage, 100.0));

        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        fprintf(log_file, "%s, %d, %.2f\n", timestamp, adc_value, moisture_percentage);
        fflush(log_file);

        usleep(sample_interval * 1000000);
    }

    close(spi_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

