#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_TRANSFER_SIZE 3
#define SPI_TRANSFER_COUNT 1
#define SPI_CMD 0b11000000
#define SPI_CMD_LEN 8
#define SPI_DATA_LEN 10
#define SPI_DATA_OFFSET 1
#define SPI_DATA_MASK 0x3FF
#define SPI_CALIBRATION_DRY 700
#define SPI_CALIBRATION_WET 300

static int spi_fd;
static int gpio_fd;
static int dry_calib;
static int wet_calib;

static void signal_handler(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_fd >= 0) {
        gpiod_chip_close(gpio_fd);
    }
    exit(signum);
}

int main() {
    struct spi_ioc_transfer transfers[SPI_TRANSFER_COUNT];
    unsigned char tx_buf[SPI_MAX_TRANSFER_SIZE];
    unsigned char rx_buf[SPI_MAX_TRANSFER_SIZE];
    int ret;
    int moisture_percentage;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Request line for SPI CS
    line = gpiod_chip_get_line(chip, 8);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Request line for SPI MOSI
    line = gpiod_chip_get_line(chip, 10);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Request line for SPI MISO
    line = gpiod_chip_get_line(chip, 9);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_line_release(line);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Request line for SPI SCLK
