#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define SPI_BUS 0
#define SPI_CE 0
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11
#define MAX_READS 1000
#define LOG_FILE "pressure_log.txt"

static int gpiod_handle;
static FILE *log_file;

void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
}

void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (gpiod_handle >= 0) {
        gpioTerminate();
    }
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpiod_handle = gpioOpen(0, 0, 0);
    if (gpiod_handle < 0) {
        fprintf(stderr, "Failed to open GPIO\n");
        gpioTerminate();
        return 1;
    }

    if (pigpio_start(SPI_BUS, 1000000) < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        pigpio_stop();
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    for (int i = 0; i < MAX_READS; i++) {
        uint16_t adc_value;
        if (gpioRead(SPI_CE) == 0) {
            fprintf(stderr, "Sensor is absent\n");
            continue;
        }
        if (pigpio_spi_read(SPI_BUS, SPI_CE, SPI_MISO, SPI_MOSI, SPI_SCLK, 1, &adc_value) < 0) {
            fprintf(stderr, "Failed to read SPI\n");
            continue;
        }
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "ADC value out of range\n");
            continue;
        }
        double voltage = (double)adc_value / 1023.0 * 3.3;
        double pressure = 100.0 * (voltage - 0.5) / (4.5 - 0.5);
        log_pressure(pressure);
        printf("Pressure: %.2f kPa\n", pressure);
        sleep(1);
    }

    fclose(log_file);
    pigpio_stop();
    gpioTerminate();
    return 0;
}

