#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED_HZ 1000000
#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700
#define CHANNEL 0
#define BUFFER_SIZE 1024

static int spi_fd;
static int gpio_fd;
static int gpio_line;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

static void cleanup(void) {
    if (gpio_fd >= 0) {
        gpiod_line_release(gpio_line);
        close(gpio_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    printf("Cleanup complete.\n");
}

static void signal_handler(int sig) {
    cleanup();
    exit(0);
}

int main() {
    struct spi_ioc_transfer transfer;
    uint8_t tx[BUFFER_SIZE] = {0x01, 0x80 | CHANNEL, 0x00};
    uint8_t rx[BUFFER_SIZE];
    int adc_value;
    double moisture_percentage;
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        cleanup();
        return EXIT_FAILURE;
    }

    // Set SPI mode and speed
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request GPIO line
    gpio_line = gpiod_chip_get_line(chip, 8);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request output mode for GPIO line
    if (gpiod_line_request_output(gpio_line, "SEN0193", 0) < 0) {
        perror("Failed to request GPIO line output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Enable SPI chip select
    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        perror("Failed to set GPIO line high");
        cleanup();
        return EXIT_FAILURE;
    }

    // Transfer data to ADC
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)tx;
    transfer.rx_buf = (unsigned long)rx;
    transfer.len = BUFFER_SIZE;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer) < 0) {
        perror("Failed to transfer data to ADC");
        cleanup();
        return EXIT_FAILURE;
    }

    // Read ADC value
    adc_value = (rx[1] << 8) | rx[2];
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "ADC value stuck at 0 or 1023, sensor may be faulty.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Convert ADC value to moisture percentage
    moisture_percentage = (adc_value - MIN_ADC_VALUE) * 100.0 / (MAX_ADC_VALUE - MIN_ADC_VALUE);

    // Get current time
    now = time(NULL);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    // Log moisture percentage
    printf("%s: Moisture percentage = %.2f%%\n", timestamp, moisture_percentage);

    // Disable SPI chip select
    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        perror("Failed to set GPIO line low");
        cleanup();
        return EXIT_FAILURE;
    }

    // Close GPIO line
    gpiod_line_release(gpio_line);

    // Close SPI device
    close(spi_fd);

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

