    gpio_line = gpiod_chip_get_line(chip, 8);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request output mode for GPIO line
    if (gpiod_line_request_output(gpio_line, "SEN0193", 0) < 0) {
        perror("Failed to request GPIO line output");
        cleanup();
        return EXIT_FAILURE;
    }

    // Enable SPI chip select
    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        perror("Failed to set GPIO line high");
        cleanup();
        return EXIT_FAILURE;
    }

    // Transfer data to ADC
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)tx;
    transfer.rx_buf = (unsigned long)rx;
    transfer.len = BUFFER_SIZE;
    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer) < 0) {
        perror("Failed to transfer data to ADC");
        cleanup();
        return EXIT_FAILURE;
    }

    // Read ADC value
    adc_value = (rx[1] << 8) | rx[2];
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "ADC value stuck at 0 or 1023, sensor may be faulty.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Convert ADC value to moisture percentage
    moisture_percentage = (adc_value - MIN_ADC_VALUE) * 100.0 / (MAX_ADC_VALUE - MIN_ADC_VALUE);

    // Get current time
    now = time(NULL);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    // Log moisture percentage
    printf("%s: Moisture percentage = %.2f%%\n", timestamp, moisture_percentage);

    // Disable SPI chip select
    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        perror("Failed to set GPIO line low");
        cleanup();
        return EXIT_FAILURE;
    }

    // Close GPIO line
    gpiod_line_release(gpio_line);

    // Close SPI device
    close(spi_fd);

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}
