#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <string.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_CLOCK_SPEED_HZ 1000000
#define MCP3008_SINGLE_ENDED_READ_CMD 0b11000000
#define MOISTURE_PERCENTAGE_MAX 100
#define MOISTURE_PERCENTAGE_MIN 0

static int spi_fd;
static volatile sig_atomic_t should_exit = 0;

void signal_handler(int sig) {
    should_exit = 1;
}

int main() {
    struct spi_ioc_transfer transfer;
    uint8_t cmd[3] = {MCP3008_SINGLE_ENDED_READ_CMD, 0x00, 0x00};
    uint8_t result[3];
    int moisture_percentage;
    int ret;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI clock speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_CLOCK_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI clock speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Prepare SPI transfer
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)cmd;
    transfer.rx_buf = (unsigned long)result;
    transfer.len = 3;

    while (!should_exit) {
        // Perform SPI transfer
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer);
        if (ret < 0) {
            perror("Failed to perform SPI transfer");
            close(spi_fd);
            exit(EXIT_FAILURE);
        }

        // Extract moisture percentage from result
        moisture_percentage = (result[1] << 2) | (result[2] >> 6);

        // Clamp moisture percentage to 0-100 range
        moisture_percentage = (moisture_percentage * MOISTURE_PERCENTAGE_MAX) / 1023;

        // Log moisture percentage
        printf("Moisture percentage: %d%%\n", moisture_percentage);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close SPI device
    close(spi_fd);

    return 0;
}

