#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_CHANNELS 4
#define VREF 3.3
#define CSV_FILE "environmental_data.csv"

static int spi_fd;
static int gpiod_chip;
static int gpiod_line[SPI_MAX_CHANNELS];
static FILE *csv_file;

static void signal_handler(int signum) {
    if (csv_file) {
        fclose(csv_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpiod_chip >= 0) {
        gpiod_chip_close(gpiod_chip);
    }
    for (int i = 0; i < SPI_MAX_CHANNELS; i++) {
        if (gpiod_line[i] >= 0) {
            gpiod_line_close(gpiod_line[i]);
        }
    }
    exit(signum);
}

static void setup_spi() {
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.speed_hz = SPI_SPEED_HZ;
    xfer.mode = SPI_MODE;
    xfer.bits_per_word = SPI_BITS_PER_WORD;
    xfer.len = 3; // 3 bytes for command, channel, and dummy byte

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &xfer.mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &xfer.bits_per_word) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &xfer.speed_hz) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        exit(EXIT_FAILURE);
    }
}

static void setup_gpiod() {
    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip < 0) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < SPI_MAX_CHANNELS; i++) {
        gpiod_line[i] = gpiod_line_request_by_name(gpiod_chip, "spi0-ce0", 0);
        if (gpiod_line[i] < 0) {
            perror("gpiod_line_request_by_name");
            exit(EXIT_FAILURE);
        }
        gpiod_line_set_value(gpiod_line[i], 1); // Set CE0 high
    }
}

static void setup_csv() {
    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    fprintf(csv_file, "Timestamp,Voltage\n");
}

static void write_csv(double timestamp, double voltage) {
    fprintf(csv_file, "%.6f,%f\n", timestamp, voltage);
}

static void read_adc(int channel) {
    struct spi_ioc_transfer xfer[2];
    memset(xfer, 0, sizeof(xfer));
    xfer[0].len = 3; // 3 bytes for command, channel, and dummy byte
    xfer[0].tx_buf = (unsigned long)(&channel);
    xfer[1].len = 2; // 2 bytes for ADC response
    xfer[1].rx_buf = (unsigned long)(&xfer[1].tx_buf);

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, xfer) < 0) {
        perror("SPI_IOC_MESSAGE");
        exit(EXIT_FAILURE);
    }

    int adc_value = (xfer[1].tx_buf[0] << 8) | xfer[1].tx_buf[1];
    double voltage = (double)adc_value * VREF / 1023.0;
    write_csv(time(NULL), voltage);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    setup_spi();
    setup_gpiod();
    setup_csv();

    while (1) {
        for (int i = 0; i < SPI_MAX_CHANNELS; i++) {
            read_adc(i);
        }
        sleep(1);
    }

    return 0;
}

