This C program sets up a Raspberry Pi 5 to continuously sample voltage readings from four analog sensors connected to an MCP3008 ADC via the SPI0 interface using the libgpiod library for SPI chip-select control and standard Linux spidev for SPI communication. It configures SPI0 at 1 MHz, Mode 0, and reads channels 0 through 3 in single-ended mode using a VREF of 3.3V. The program samples once per second and logs timestamped voltage values to a CSV file named `environmental_data.csv`. It includes robust error handling for SPI communication failures and ensures clean resource release on all exit paths via SIGINT/SIGTERM signal handling.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <stdint.h>

#define SPI_BUS 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define BUFFER_SIZE 20
#define BUFFER_MASK (BUFFER_SIZE - 1)

static int spiHandle;
static int pumpPin;
static int bufferIndex = 0;
static uint16_t buffer[BUFFER_SIZE];
static struct timespec lastSampleTime;
static struct timespec currentTime;
static int pumpState = 0;
static int running = 1;

static void signalHandler(int signum) {
    running = 0;
    gpioWrite(pumpPin, 0);
    gpioTerminate();
    close(spiHandle);
    printf("Program terminated.\n");
    exit(0);
}

static void logSample(uint16_t moisture, int pumpState) {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    buffer[bufferIndex] = (now.tv_sec << 16) | (now.tv_nsec >> 16);
    buffer[bufferIndex] |= (moisture << 8) | pumpState;
    bufferIndex = (bufferIndex + 1) & BUFFER_MASK;
}

static void readMoisture() {
    uint8_t command = 0b11000000 | (MCP3008_CHANNEL << 4);
    uint8_t data[3];
    int result;

    result = spiXfer(spiHandle, &command, data, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return;
    }

    uint16_t moisture = (data[1] << 8) | data[2];
    logSample(moisture, pumpState);

    if (moisture < LOW_THRESHOLD) {
        if (pumpState == 0) {
            gpioWrite(pumpPin, 1);
            pumpState = 1;
        }
    } else if (moisture > HIGH_THRESHOLD) {
        if (pumpState == 1) {
            gpioWrite(pumpPin, 0);
            pumpState = 0;
        }
    }
}

static void sampleMoisture() {
    clock_gettime(CLOCK_MONOTONIC, &currentTime);
    if (difftime(currentTime.tv_sec, lastSampleTime.tv_sec) >= 5) {
        readMoisture();
        lastSampleTime = currentTime;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    pumpPin = 17;
    if (gpioSetMode(pumpPin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set pump pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(pumpPin, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pump pin pull-up\n");
        gpioTerminate();
        return 1;
    }

    if ((spiHandle = spiOpen(SPI_BUS, SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    clock_gettime(CLOCK_MONOTONIC, &lastSampleTime);

    while (running) {
        sampleMoisture();
        usleep(1000000); // Sleep for 1 second
    }

    gpioWrite(pumpPin, 0);
    gpioTerminate();
    close(spiHandle);
    printf("Program terminated.\n");
    return 0;
}

