#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_FLAGS (SPI_MODE | SPI_SPEED | SPI_BITS)
#define MCP3008_CMD 0b11000000
#define MCP3008_CHANNEL_MASK 0b00001111
#define MCP3008_DUMMY_BYTE 0x00
#define VREF 3.3

static FILE *log_file;
static int spi_handle;

void log_data(int channel, float voltage) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);
    fprintf(log_file, "%s,%d,%f\n", timestamp, channel, voltage);
}

void handle_sigint(int signum) {
    if (spi_handle != -1) {
        gpioTerminate();
        close(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    signal(SIGINT, handle_sigint);

    if ((spi_handle = gpioSpiOpen(SPI_CHANNEL, SPI_MODE, SPI_SPEED)) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen("analog_log.csv", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        close(spi_handle);
        return 1;
    }
    fprintf(log_file, "Timestamp,Channel,Voltage\n");

    while (1) {
        uint8_t tx_buf[3] = {MCP3008_CMD, 0, MCP3008_DUMMY_BYTE};
        uint8_t rx_buf[3];

        for (int channel = 0; channel < 3; channel++) {
            tx_buf[1] = (channel << 4) | MCP3008_DUMMY_BYTE;
            int ret = gpioSpiRead(spi_handle, tx_buf, 3);
            if (ret < 0) {
                fprintf(stderr, "SPI read failed for channel %d\n", channel);
                continue;
            }

            float voltage = (rx_buf[1] & 0x03) * 1024.0 / VREF + (rx_buf[2] * 1024.0 / VREF) / 4.0;
            log_data(channel, voltage);
        }

        sleep(0.5);
    }

    gpioTerminate();
    close(spi_handle);
    fclose(log_file);
    return 0;
}

