#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BuzzerPin 24
#define GasSensorPin 0
#define Threshold 500
#define SPI_CHANNEL 0
#define SPI_CLOCK_SPEED 1000000

static volatile sig_atomic_t keepRunning = 1;

void handleSignal(int sig) {
    keepRunning = 0;
}

int main() {
    int spiHandle;
    int gasValue;
    int gpioState = 0;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up GPIO pin for buzzer
    if (gpioSetMode(BuzzerPin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for buzzer\n");
        gpioTerminate();
        return 1;
    }

    // Set up SPI interface
    spiHandle = spiOpen(SPI_CHANNEL, SPI_CLOCK_SPEED, 0);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handleSignal);

    while (keepRunning) {
        // Read analog value from MQ-2 gas sensor
        if (spiRead(spiHandle, (unsigned char*)&gasValue, 2) < 0) {
            fprintf(stderr, "Failed to read SPI data\n");
            break;
        }

        // Convert 16-bit data to 10-bit ADC value
        gasValue = (gasValue >> 6) & 0x3FF;

        // Control buzzer based on gas value
        if (gasValue < Threshold) {
            if (gpioWrite(BuzzerPin, 1) < 0) {
                fprintf(stderr, "Failed to write to GPIO\n");
                break;
            }
            gpioState = 1;
        } else {
            if (gpioWrite(BuzzerPin, 0) < 0) {
                fprintf(stderr, "Failed to write to GPIO\n");
                break;
            }
            gpioState = 0;
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Clean up resources
    spiClose(spiHandle);
    gpioWrite(BuzzerPin, gpioState); // Ensure buzzer is off
    gpioTerminate();

    return 0;
}

