static void log_soil_moisture(int sensor, int value) {
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
    }
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor == 0 ? value : -1, sensor == 1 ? value : -1, sensor == 2 ? value : -1);
