    if (ret < 0) {
        perror("SPI ioctl");
        return -1;
    }
    ret = read(spi_fd, rx, 3);
    if (ret < 0) {
        perror("SPI read");
        return -1;
    }
    return (rx[1] & 0x03) << 8 | rx[2];
}

