    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        exit(EXIT_FAILURE);
    }
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        exit(EXIT_FAILURE);
    }
}

static void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    for (int i = 0; i < SPI_CS_LINES; i++) {
        gpiod_line_release(cs_lines[i]);
    }
    gpiod_chip_close(chip);
    close(spi_fd);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);
    setup_gpio();
    setup_spi();
    while (!should_exit) {
        for (int i = 0; i < 3; i++) {
            gpiod_line_set_value(cs_lines[i], 0);
            int value = read_mcp3008(i);
            gpiod_line_set_value(cs_lines[i], 1);
            log_soil_moisture(i, value);
        }
        sleep(LOG_INTERVAL);
    }
    cleanup();
    return 0;
}

