This C program sets up a Raspberry Pi 5 to log simultaneous ADC readings from three MCP3008 chips, each reading an analog soil moisture sensor on channel 0 in single-ended mode, into 'soil_moisture_log.csv' in the specified format. It uses libgpiod for manual CS line control and standard Linux spidev for SPI communication. The program handles SIGINT and SIGTERM for a graceful shutdown, releasing all resources by closing every open file descriptor and freeing all libgpiod lines and chips before the process exits.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <mcp3008.h>

#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_CLOCK 1000000
#define SPI_MODE 0
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60

static int threshold = DEFAULT_THRESHOLD;
static int duration = DEFAULT_DURATION;
static int sleep_interval = DEFAULT_SLEEP_INTERVAL;
static int pump_pin = 18;
static int adc_channel = 0;
static int retries = 3;
static int pump_state = 0;
static FILE *log_file;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(log_file, format, args);
    va_end(args);
    fprintf(log_file, "\n");
}

void handle_signal(int signum) {
    if (pump_state) {
        gpioWrite(pump_pin, 0);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio\n");
    }
    exit(EXIT_SUCCESS);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(pump_pin, PI_OUTPUT);
    gpioWrite(pump_pin, 0);
}

void setup_spi() {
    if (mcp3008Setup(SPI_CHANNEL, SPI_CE, SPI_CLOCK, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        exit(EXIT_FAILURE);
    }
}

void read_moisture() {
    int adc_value;
    for (int i = 0; i < retries; i++) {
        adc_value = mcp3008Read(adc_channel);
        if (adc_value >= 0) {
            break;
        }
        usleep(100000); // Wait for 100ms before retrying
    }
    if (adc_value < 0) {
        log_message("Failed to read ADC, skipping irrigation cycle");
        return;
    }
    int moisture = (adc_value - 200) * 100 / (800 - 200);
    moisture = moisture < 0 ? 0 : moisture > 100 ? 100 : moisture;
    log_message("Moisture: %d%%", moisture);
    if (moisture < threshold) {
        log_message("Moisture below threshold, activating pump");
        pump_state = 1;
        gpioWrite(pump_pin, 1);
        sleep(duration);
        pump_state = 0;
        gpioWrite(pump_pin, 0);
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen("irrigation.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    setup_gpio();
    setup_spi();

    while (1) {
