static void handle_signal(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    if (spi != -1) {
        gpio SpiClose(spi);
    }
    if (gpio != -1) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

static void init_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(SPI_CE0, PI_OUTPUT);
    gpioSetMode(SPI_CLK, PI_OUTPUT);
    gpioSetMode(SPI_MOSI, PI_OUTPUT);
    gpioSetMode(SPI_MISO, PI_INPUT);
    gpioWrite(SPI_CE0, 1);
}

static void init_spi() {
    spi = gpioSpiOpen(0, 1000000, 0);
    if (spi < 0) {
        syslog(LOG_ERR, "Failed to open SPI");
        exit(EXIT_FAILURE);
    }
}

static void init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

static void close_log_file() {
    if (log_file) {
        fclose(log_file);
    }
}

static void close_spi() {
    if (spi != -1) {
        gpioSpiClose(spi);
    }
}

static void close_gpio() {
    if (gpio != -1) {
        gpioTerminate();
    }
}

