#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define AIN0_CHANNEL 0
#define SAMPLE_INTERVAL_MS 100

static int i2c_fd;
static int gpiod_chip;
static int gpiod_line;

void handle_sigint(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpiod_chip >= 0) {
        gpiod_chip_close(gpiod_chip);
    }
    if (gpiod_line >= 0) {
        gpiod_line_close(gpiod_line);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    // Register SIGINT handler
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set up GPIO chip
    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip < 0) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up GPIO line for I2C SDA
    gpiod_line = gpiod_chip_get_line(gpiod_chip, 21);
    if (gpiod_line < 0) {
        perror("Failed to get GPIO line for I2C SDA");
        gpiod_chip_close(gpiod_chip);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up GPIO line for I2C SCL
    gpiod_line = gpiod_chip_get_line(gpiod_chip, 20);
    if (gpiod_line < 0) {
        perror("Failed to get GPIO line for I2C SCL");
        gpiod_chip_close(gpiod_chip);
        close(i2c_fd);
        gpiod_line_close(gpiod_line);
        return EXIT_FAILURE;
    }

    // Request I2C lines
    if (gpiod_line_request_input(gpiod_line, "i2c_sda") < 0) {
        perror("Failed to request I2C SDA line");
        gpiod_chip_close(gpiod_chip);
        close(i2c_fd);
        gpiod_line_close(gpiod_line);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(gpiod_line, "i2c_scl") < 0) {
        perror("Failed to request I2C SCL line");
        gpiod_chip_close(gpiod_chip);
        close(i2c_fd);
        gpiod_line_close(gpiod_line);
        gpiod_line_close(gpiod_line);
        return EXIT_FAILURE;
    }

    // Set up control byte for single-ended mode on channel 0 with analog output disabled
    unsigned char control_byte = (AIN0_CHANNEL << 4) | 0x00;

    // Perform a dummy read to discard the previous conversion result
    unsigned char dummy_read;
    if (write(i2c_fd, &control_byte, 1) != 1) {
        perror("Failed to write control byte");
        gpiod_chip_close(gpiod_chip);
        close(i2c_fd);
        gpiod_line_close(gpiod_line);
        gpiod_line_close(gpiod_line);
        return EXIT_FAILURE;
    }

    if (read(i2c_fd, &dummy_read, 1) != 1) {
        perror("Failed to read dummy read");
        gpiod_chip_close(gpiod_chip);
        close(i2c_fd);
        gpiod_line_close(gpiod_line);
        gpiod_line_close(gpiod_line);
        return EXIT_FAILURE;
    }

    while (1) {
        // Read the current sample
        unsigned char sample;
        if (write(i2c_fd, &control_byte, 1) != 1) {
            perror("Failed to write control byte");
            gpiod_chip_close(gpiod_chip);
            close(i2c_fd);
            gpiod_line_close(gpiod_line);
            gpiod_line_close(gpiod_line);
            return EXIT_FAILURE;
        }

        if (read(i2c_fd, &sample, 1) != 1) {
            perror("Failed to read sample");
            gpiod_chip_close(gpiod_chip);
            close(i2c_fd);
            gpiod_line_close(gpiod_line);
            gpiod_line_close(gpiod_line);
            return EXIT_FAILURE;
        }

        // Print the sample value
        printf("%d\n", sample);

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Close I2C bus
    close(i2c_fd);

    // Close GPIO chip
    gpiod_chip_close(gpiod_chip);

    // Close GPIO lines
    gpiod_line_close(gpiod_line);
    gpiod_line_close(gpiod_line);

    return EXIT_SUCCESS;
}

