#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define ADC_ADDRESS 0x48
#define ADC_CHANNEL 0
#define ADC_GAIN 1
#define ADC_SAMPLE_RATE 1000
#define BUFFER_SIZE 10
#define THRESHOLD 500
#define GPIO_PIN 27

static int adcHandle;
static int gpioHandle;
static int buffer[BUFFER_SIZE];
static int bufferIndex = 0;
static int thresholdExceeded = 0;
static int running = 1;

void signalHandler(int signum) {
    running = 0;
    gpioWrite(gpioHandle, GPIO_PIN, 0);
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
    gpioHandle = gpioOpen(GPIO_PIN, OUTPUT);
    if (gpioHandle < 0) {
        syslog(LOG_ERR, "Failed to open GPIO %d", GPIO_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    gpioWrite(gpioHandle, GPIO_PIN, 0);

    if (i2cOpen(1, ADC_ADDRESS, 0) < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus 1 at address 0x48");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    adcHandle = i2cOpen(1, ADC_ADDRESS, 0);

    if (adcHandle < 0) {
        syslog(LOG_ERR, "Failed to open ADC handle");
        i2cClose(adcHandle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    while (running) {
        int rawValue = 0;
        if (i2cReadReg16(adcHandle, 0x00) < 0) {
            syslog(LOG_ERR, "Failed to read ADC register 0x00");
            continue;
        }
        rawValue = i2cReadReg16(adcHandle, 0x00);

        if (rawValue < 0 || rawValue > 4095) {
            syslog(LOG_ERR, "Invalid ADC value: %d", rawValue);
            continue;
        }

        float voltage = (float)rawValue / 4095.0 * 3.3;
        float gauss = (voltage - 2.5) / 1.4;

        buffer[bufferIndex] = (int)gauss;
        bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;

        int sum = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            sum += buffer[i];
        }
        int average = sum / BUFFER_SIZE;

        if (average > THRESHOLD) {
            if (!thresholdExceeded) {
                syslog(LOG_INFO, "Threshold exceeded: %d Gauss", average);
                thresholdExceeded = 1;
                gpioWrite(gpioHandle, GPIO_PIN, 1);
            }
        } else {
            if (thresholdExceeded) {
                syslog(LOG_INFO, "Threshold cleared: %d Gauss", average);
                thresholdExceeded = 0;
                gpioWrite(gpioHandle, GPIO_PIN, 0);
            }
        }

        syslog(LOG_INFO, "ADC value: %d, Voltage: %.2f V, Gauss: %.2f", rawValue, voltage, gauss);

        usleep(1000000 / ADC_SAMPLE_RATE);
    }

    i2cClose(adcHandle);
    gpioTerminate();
    closelog();

    return 0;
}

