    int spiHandle;
    int adcValue;
    int pwmValue;
    int dutyCycle;
    struct spi_ioc_transfer transfer;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up SPI
    spiHandle = spiOpen(0, SPI_SPEED, SPI_MODE);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    // Set up PWM
    if (gpioPWM(PWM_CHANNEL, 0) < 0) {
        fprintf(stderr, "Failed to set up PWM\n");
        spiClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!quit) {
        // Read ADC
        transfer.tx_buf = 0;
        transfer.rx_buf = (unsigned int *)&adcValue;
        transfer.len = 2;
        transfer.speed_hz = SPI_SPEED;
        transfer.delay_usecs = SPI_DELAY;
        transfer.bits_per_word = 8;
        transfer.cs_change = 1;

        if (spiXfer(spiHandle, &transfer) < 0) {
            fprintf(stderr, "Failed SPI transfer\n");
            continue;
        }

        // Map ADC value to duty cycle
        dutyCycle = (adcValue >> 2) & PWM_RANGE;

        // Set PWM
        if (gpioPWM(PWM_CHANNEL, dutyCycle) < 0) {
            fprintf(stderr, "Failed to set PWM\n");
            continue;
        }

        // Print values
        printf("ADC: %d, PWM: %d\n", adcValue, dutyCycle);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpioPWM(PWM_CHANNEL, 0);
    spiClose(spiHandle);
    gpioTerminate();

    return 0;
