#include <wiringPi.h>
#include <math.h>

#define ADC_ADDRESS 0x48
#define ADC_CHANNEL 0
#define ADC_GAIN 4.096
#define LED_PIN 17
#define DEFAULT_THRESHOLD 100.0
#define I2C_BUS 1
#define I2C_TIMEOUT 1000

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main(int argc, char *argv[]) {
    double threshold = DEFAULT_THRESHOLD;
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Initialize LED
    if (gpioSetMode(LED_PIN, PI_OUTPUT)) {
        fprintf(stderr, "Failed to set LED mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    if (i2cOpen(I2C_BUS, ADC_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        // Read ADC value
        uint16_t adc_value;
        if (i2cReadWordData(I2C_BUS, ADC_ADDRESS, 0x00) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        // Convert ADC value to voltage
        double voltage = (adc_value * 3.3) / 65535.0;

        // Convert voltage to magnetic field strength in Gauss
        double gauss = (voltage / ADC_GAIN) * 1000.0;

        // Output magnetic field strength
        printf("Magnetic field strength: %.2f Gauss\n", gauss);

        // Check if field exceeds threshold
        if (gauss > threshold) {
            // Blink LED rapidly
            for (int i = 0; i < 10; i++) {
                gpioWrite(LED_PIN, 1);
                usleep(50000);
                gpioWrite(LED_PIN, 0);
                usleep(50000);
            }
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up resources
    gpioWrite(LED_PIN, 0);
    i2cClose(I2C_BUS);
    gpioTerminate();

    return EXIT_SUCCESS;
}

