#include <paho-mqtt-c/mqtt_client.h>

#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define HISTO_RECOVERY 5
#define MQTT_TOPIC "soil_moisture"
#define MQTT_CLIENT_ID "soil_moisture_sensor"
#define MQTT_BROKER "mqtt.example.com"
#define MQTT_PORT 1883
#define SPI_CHANNEL 0
#define SPI_CLOCK_SPEED 1000000
#define GPIO_RELAY 17
#define GPIO_MCP3008_CS 8

static int mqtt_client = -1;
static int spi_handle = -1;
static int gpio_relay = -1;
static int gpio_mcp3008_cs = -1;
static int moisture_level = -1;
static int moisture_count = 0;
static int moisture_hysteresis = 0;

static void sig_handler(int sig) {
    if (mqtt_client != -1) {
        mqtt_client_disconnect(mqtt_client);
    }
    if (spi_handle != -1) {
        spi_close(spi_handle);
    }
    if (gpio_relay != -1) {
        gpio_write(gpio_relay, 0);
    }
    if (gpio_mcp3008_cs != -1) {
        gpio_write(gpio_mcp3008_cs, 1);
    }
    syslog(LOG_INFO, "Program terminated by signal %d", sig);
    exit(EXIT_SUCCESS);
}

static void mqtt_connect_callback(void *context, MQTTClient_deliveryToken token) {
    syslog(LOG_INFO, "Connected to MQTT broker");
}

static void mqtt_disconnect_callback(void *context, int reasonCode) {
    syslog(LOG_INFO, "Disconnected from MQTT broker with reason code %d", reasonCode);
}

static void mqtt_publish_callback(void *context, MQTTClient_deliveryToken token) {
    syslog(LOG_INFO, "Published moisture level to MQTT topic '%s'", MQTT_TOPIC);
}

static void mqtt_message_callback(void *context, MQTTClient_message *message) {
    char *topic = message->topicName;
    char *payload = message->payload;
    int payload_len = message->payloadlen;

    if (strcmp(topic, "pump_control") == 0) {
        if (strcmp(payload, "pump_on") == 0) {
            gpio_write(gpio_relay, 1);
        } else if (strcmp(payload, "pump_off") == 0) {
            gpio_write(gpio_relay, 0);
        }
    }
}

static void mqtt_subscribe_callback(void *context, MQTTClient_deliveryToken token) {
    syslog(LOG_INFO, "Subscribed to MQTT topic '%s'", MQTT_TOPIC);
}

static void spi_transfer_callback(void *context, int status) {
    if (status != 0) {
        syslog(LOG_ERR, "SPI transfer failed with status %d", status);
    }
}

static void gpio_write_callback(void *context, int status) {
    if (status != 0) {
        syslog(LOG_ERR, "GPIO write failed with status %d", status);
    }
}

static void log_error(const char *msg) {
    syslog(LOG_ERR, "Error: %s", msg);
}

static int read_moisture_level() {
    int data[3];
    int status;

    gpio_write(gpio_mcp3008_cs, 0);
    status = spi_transfer(spi_handle, (unsigned char *)data, 3);
    gpio_write(gpio_mcp3008_cs, 1);

    if (status != 0) {
        log_error("SPI transfer failed");
        return -1;
    }

    moisture_level = (data[1] << 8) | data[2];
    moisture_level = (moisture_level >> 2) & 0x3FF;

    return moisture_level;
}

static void publish_moisture_level() {
    char buffer[20];
    snprintf(buffer, sizeof(buffer), "%d", moisture_level);
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    pubmsg.payload = buffer;
    pubmsg.payloadlen = strlen(buffer);
    pubmsg.qos = 1;
    pubmsg.retained = 0;

    if (MQTTClient_publish(mqtt_client, MQTT_TOPIC, pubmsg.payloadlen, pubmsg.payload, pubmsg.qos, pubmsg.retained) != MQTTCLIENT_SUCCESS) {
        log_error("Failed to publish moisture level");
    }
}

static void check_moisture_level() {
    moisture_level = read_moisture_level();
    if (moisture_level == -1) {
        return;
    }

    if (moisture_level < MOISTURE_THRESHOLD_LOW) {
        if (moisture_hysteresis < HISTO_RECOVERY) {
            moisture_hysteresis++;
        } else {
            gpio_write(gpio_relay, 1);
        }
    } else if (moisture_level > MOISTURE_THRESHOLD_HIGH) {
        if (moisture_hysteresis > -HISTO_RECOVERY) {
            moisture_hysteresis--;
        } else {
            gpio_write(gpio_relay, 0);
        }
    }

    moisture_count++;
    if (moisture_count % 60 == 0) {
        publish_moisture_level();
    }
}

int main() {
    if (gpio_init() < 0) {
        log_error("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }
    if (spi_init() < 0) {
        log_error("Failed to initialize SPI");
        exit(EXIT_FAILURE);
    }
    if (mqtt_client_init() < 0) {
        log_error("Failed to initialize MQTT client");
        exit(EXIT_FAILURE);
    }

    gpio_relay = gpio_claim_output(GPIO_RELAY);
    gpio_mcp3008_cs = gpio_claim_output(GPIO_MCP3008_CS);

    if (gpio_relay < 0 || gpio_mcp3008_cs < 0) {
        log_error("Failed to claim GPIO pins");
        exit(EXIT_FAILURE);
    }

    if (spi_open(SPI_CHANNEL, SPI_CLOCK_SPEED, 0) < 0) {
        log_error("Failed to open SPI channel");
        exit(EXIT_FAILURE);
    }

    if (mqtt_client_connect(MQTT_BROKER, MQTT_PORT, 60, mqtt_connect_callback, mqtt_disconnect_callback, mqtt_publish_callback, mqtt_message_callback, mqtt_subscribe_callback, NULL) != MQTTCLIENT_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        exit(EXIT_FAILURE);
    }

    if (mqtt_client_subscribe(mqtt_client, MQTT_TOPIC, 1) != MQTTCLIENT_SUCCESS) {
        log_error("Failed to subscribe to MQTT topic");
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        check_moisture_level();
        sleep(1);
    }

    mqtt_client_disconnect(mqtt_client);
    spi_close(spi_handle);
    gpio_write(gpio_relay, 0);
    gpio_write(gpio_mcp3008_cs, 1);
    gpio_unclaim_output(gpio_relay);
    gpio_unclaim_output(gpio_mcp3008_cs);
    gpio_deinit();
    mqtt_client_deinit();

    return 0;
}

