#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CLOCK_SPEED 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE 0
#define SPI_CHANNEL_0 CE0
#define VREF 3.3
#define NUM_CHANNELS 3
#define LOG_FILE "sensor_data.csv"
#define LOG_INTERVAL 5

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    FILE *log_file;
    struct timespec sleep_time = {LOG_INTERVAL, 0};
    int spi_handle;
    uint8_t spi_data[NUM_CHANNELS * 2];
    uint16_t adc_values[NUM_CHANNELS];
    char buffer[256];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Open SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_CLOCK_SPEED, SPI_BITS_PER_WORD, SPI_MODE, SPI_CHANNEL_0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Voltage Channel 0,Voltage Channel 1,Voltage Channel 2\n");

    while (!should_exit) {
        // Read from SPI
        for (int i = 0; i < NUM_CHANNELS; i++) {
            spi_data[i * 2] = 0b11000000 | (i << 4); // Start bit, channel select
            spi_data[i * 2 + 1] = 0; // Dummy byte
            if (spiXfer(spi_handle, spi_data + i * 2, spi_data + i * 2, 2) < 0) {
                fprintf(stderr, "Failed to transfer SPI data\n");
                break;
            }
            adc_values[i] = (spi_data[i * 2] << 8) | spi_data[i * 2 + 1];
        }

        // Calculate voltage
        for (int i = 0; i < NUM_CHANNELS; i++) {
            adc_values[i] = (adc_values[i] * VREF) / 1023;
        }

        // Get current time
        struct timespec now;
        if (clock_gettime(CLOCK_REALTIME, &now) < 0) {
            fprintf(stderr, "Failed to get current time\n");
            break;
        }

        // Format timestamp
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now.tv_sec));

        // Write to log file
        fprintf(log_file, "%s,%f,%f,%f\n", buffer, adc_values[0], adc_values[1], adc_values[2]);

        // Sleep for LOG_INTERVAL
        if (nanosleep(&sleep_time, NULL) < 0) {
            fprintf(stderr, "Failed to sleep\n");
            break;
        }
    }

    // Close log file
    fclose(log_file);

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

