#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define PWM_FREQUENCY 100
#define PWM_DUTY_CYCLE_MAX 100
#define THRESHOLD 500
#define LOG_FILE "vibration_log.txt"

static int spi_fd;
static int pwm_handle[2];
static volatile sig_atomic_t running = 1;

void sig_handler(int sig) {
    running = 0;
    gpioPWMWrite(pwm_handle[0], 0);
    gpioPWMWrite(pwm_handle[1], 0);
    gpioTerminate();
    close(spi_fd);
    printf("Program terminated gracefully.\n");
    exit(0);
}

void log_event(int adc_value) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log, "%s: ADC value: %d\n", timestamp, adc_value);
    fclose(log);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        return 1;
    }

    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode for motor 1");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(27, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode for motor 2");
        gpioTerminate();
        return 1;
    }

    if (gpioPWMWrite(17, 0) < 0) {
        perror("Failed to set initial PWM duty cycle for motor 1");
        gpioTerminate();
        return 1;
    }

    if (gpioPWMWrite(27, 0) < 0) {
        perror("Failed to set initial PWM duty cycle for motor 2");
        gpioTerminate();
        return 1;
    }

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        gpioTerminate();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    pwm_handle[0] = gpioGetPWMHandleForChannel(17);
    if (pwm_handle[0] < 0) {
        perror("Failed to get PWM handle for motor 1");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    pwm_handle[1] = gpioGetPWMHandleForChannel(27);
    if (pwm_handle[1] < 0) {
        perror("Failed to get PWM handle for motor 2");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    gpioPWM(pwm_handle[0], 0);
    gpioPWM(pwm_handle[1], 0);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        uint8_t tx[2] = {0x01, ADC_CHANNEL};
        uint8_t rx[3];

        if (write(spi_fd, tx, 2) != 2) {
            perror("Failed to write to SPI");
            continue;
        }

        if (read(spi_fd, rx, 3) != 3) {
            perror("Failed to read from SPI");
            continue;
        }

        int adc_value = (rx[1] << 8) | rx[2];
        log_event(adc_value);

        if (adc_value > THRESHOLD) {
            int duty_cycle = (adc_value - THRESHOLD) * PWM_DUTY_CYCLE_MAX / (ADC_MAX - THRESHOLD);
            gpioPWM(pwm_handle[0], duty_cycle);
            gpioPWM(pwm_handle[1], duty_cycle);
        } else {
            gpioPWM(pwm_handle[0], 0);
            gpioPWM(pwm_handle[1], 0);
        }

        usleep(10000);
    }

    gpioPWMWrite(pwm_handle[0], 0);
    gpioPWMWrite(pwm_handle[1], 0);
    gpioTerminate();
    close(spi_fd);
    printf("Program terminated gracefully.\n");
    return 0;
}

