#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE SPI_MODE_0
#define MOISTURE_THRESHOLD 30
#define PUMP_PIN 17
#define LOG_INTERVAL 60

static int spi_fd;
static int pump_pin;
static int gpio_handle;
static int pigpio_handle;
static int retries = 3;

void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpio_write(pump_pin, 0); // Turn off the pump
        close(spi_fd);
        gpioTerminate();
        pigpioTerminate();
        printf("Program terminated gracefully.\n");
        exit(EXIT_SUCCESS);
    }
}

void log_reading(int moisture) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    printf("%s: Moisture: %d%%\n", timestamp, moisture);
}

int read_moisture() {
    uint8_t tx[3] = {0x01, 0x80, 0x00}; // Start bit, single-ended conversion, channel 0
    uint8_t rx[3];
    int ret;

    for (int i = 0; i < retries; i++) {
        ret = spi_xfer(spi_fd, tx, rx, 3);
        if (ret == 3) {
            int moisture = (rx[1] << 8) | rx[2];
            moisture = (moisture & 0x3FF) * 100 / 1023;
            return moisture;
        }
        usleep(100000); // Wait for 100ms before retrying
    }
    return -1; // Return -1 if all retries fail
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
