#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define FAN_PIN 18
#define LOG_FILE "air_quality.log"
#define SAMPLE_INTERVAL 5000000 // 5 seconds in microseconds

static volatile int running = 1;
static int fan_state = 0;

void signal_handler(int sig) {
    running = 0;
    gpioWrite(FAN_PIN, 0); // Turn off the fan
    gpioTerminate(); // Terminate pigpio
    printf("Program terminated.\n");
    exit(0);
}

void log_data(double co2_ppm, int fan_state) {
    FILE *log = fopen(LOG_FILE, "a");
    if (!log) {
        perror("Failed to open log file");
        return;
    }
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(log, "%04d-%02d-%02d %02d:%02d:%02d,%f,%d\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, co2_ppm, fan_state);
    fclose(log);
}

double adc_read() {
    int adc_value = 0;
    int retries = 3;
    while (retries--) {
        if (gpioRead(ADC_CHANNEL) == 0) {
            if (spiXfer(0, &adc_value, 1, 0) == 1) {
                return (double)adc_value / 1023.0 * 5000.0; // Convert to CO2 ppm
            }
        }
        usleep(100000); // Wait for 100ms before retrying
    }
    fprintf(stderr, "ADC read failed, retrying...\n");
    return -1.0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioWrite(FAN_PIN, 0); // Turn off the fan initially

    if (spiOpen(0, 1000000, 0) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        double co2_ppm = adc_read();
        if (co2_ppm >= 700.0) {
            fan_state = 1;
        } else {
            fan_state = 0;
        }
        log_data(co2_ppm, fan_state);
        usleep(SAMPLE_INTERVAL);
    }

    gpioWrite(FAN_PIN, 0); // Turn off the fan
    spiClose(0);
    gpioTerminate();
    return 0;
}

