#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define SPI_CHANNEL 0
#define SPI_CLOCK 1000000
#define SPI_MODE 0
#define ADC_CHANNELS 3
#define LOG_FILE "irrigation.log"
#define LOG_INTERVAL 5

static int pigpio_handle = -1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void log_data(int *adc_values, int avg, int valve_position) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(log_file, "%s, %d, %d, %d, %d\n", timestamp, adc_values[0], adc_values[1], adc_values[2], valve_position);
    fflush(log_file);
}

static void handle_signal(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (spi_handle != -1) {
        spiClose(spi_handle);
    }
    if (pigpio_handle != -1) {
        gpioTerminate();
    }
    exit(signum);
}

static int read_adc(int channel) {
    uint8_t command = 0b11000000 | (channel << 4);
    uint8_t data[3];
    int result = spiXfer(spi_handle, &command, data, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed for channel %d\n", channel);
        return -1;
    }
    return (data[1] << 8) | data[2];
}

static void set_pwm(int duty_cycle) {
    gpioPWM(GPIO_PIN, duty_cycle);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    pigpio_handle = gpioInitialise();
    if (pigpio_handle < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_CLOCK, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_CLOCK, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int adc_values[ADC_CHANNELS];
        int sum = 0;
        int count = 0;

        for (int i = 0; i < ADC_CHANNELS; i++) {
            int adc_value = read_adc(i);
            if (adc_value >= 0) {
                sum += adc_value;
                count++;
            } else {
                fprintf(stderr, "Failed to read ADC channel %d\n", i);
            }
        }

        if (count > 0) {
            int avg = sum / count;
            int valve_position = 100 - (avg * 100) / 1023;
            set_pwm(valve_position);
            log_data(adc_values, avg, valve_position);
        } else {
            fprintf(stderr, "No valid ADC readings\n");
        }

        sleep(LOG_INTERVAL);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

