#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8
#define SPI_DELAY 0
#define SPI_CS 8
#define YL69_CHANNEL 0
#define MAX_RETRIES 5
#define RETRY_DELAY 1000000 // 1 second

static int spiHandle;
static int pigpioHandle;
static FILE *logFile;

void signalHandler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (logFile) {
            fclose(logFile);
        }
        if (spiHandle != -1) {
            gpio SpiClose(spiHandle);
        }
        if (pigpioHandle != -1) {
            gpioTerminate();
        }
        exit(EXIT_SUCCESS);
    }
}

int readSoilMoisture() {
    uint8_t command[3] = {0x01, (YL69_CHANNEL << 4), 0x00};
    uint8_t response[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (gpio SpiXfer(spiHandle, command, response, 3) == 3) {
            int adcValue = (response[1] << 8) | response[2];
            if (adcValue >= 0 && adcValue <= 1023) {
                return adcValue;
            } else {
                fprintf(stderr, "Invalid ADC value: %d\n", adcValue);
            }
        } else {
            fprintf(stderr, "SPI transfer failed, retrying...\n");
            usleep(RETRY_DELAY);
            retries++;
        }
    }

    fprintf(stderr, "Failed to read soil moisture after %d retries\n", MAX_RETRIES);
    return -1;
}

void logReading(int adcValue) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(logFile, "%s, %d\n", timestamp, adcValue);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }
    pigpioHandle = gpioInitialise();

    if (gpio SpiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    spiHandle = gpioSpiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);

    logFile = fopen("soil_data.txt", "w");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        gpioSpiClose(spiHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    while (1) {
        int adcValue = readSoilMoisture();
        if (adcValue != -1) {
            logReading(adcValue);
        }
        sleep(5);
    }

    fclose(logFile);
    gpioSpiClose(spiHandle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

