#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>
#include <gpiod.h>
#include <time.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define LDR_PIN 0
#define PWM_PIN 18
#define PWM0_PATH "/sys/class/pwm/pwmchip0/pwm0"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MODE 0
#define MAX_CALIBRATION_POINTS 10
#define CONFIG_FILE "theremin_config.txt"

static int gpiod_ctx = -1;
static int spi_fd = -1;
static int pwm_fd = -1;
static int calibration_points[MAX_CALIBRATION_POINTS];
static int calibration_count = 0;
static int last_valid_distance = -1;
static int last_valid_volume = -1;

void handle_sigint(int signum) {
    if (gpiod_ctx != -1) {
        gpiod_close(gpiod_ctx);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (pwm_fd != -1) {
        close(pwm_fd);
    }
    printf("Program terminated by user.\n");
    exit(0);
}

void load_calibration_data() {
    FILE *file = fopen(CONFIG_FILE, "r");
    if (file == NULL) {
        printf("Failed to open calibration file. Using default values.\n");
        return;
    }
    for (int i = 0; i < MAX_CALIBRATION_POINTS; i++) {
        if (fscanf(file, "%d", &calibration_points[i]) != 1) {
            printf("Error reading calibration data. Using default values.\n");
            break;
        }
    }
    fclose(file);
}

void save_calibration_data() {
    FILE *file = fopen(CONFIG_FILE, "w");
    if (file == NULL) {
        printf("Failed to open calibration file for writing.\n");
        return;
    }
    for (int i = 0; i < calibration_count; i++) {
        fprintf(file, "%d\n", calibration_points[i]);
    }
    fclose(file);
}

int read_distance() {
    int trigger_fd = open("/dev/gpiochip0", O_WRONLY);
    if (trigger_fd == -1) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    ioctl(trigger_fd, GPIO_SETVALUE, TRIG_PIN, 1);
    usleep(10);
    ioctl(trigger_fd, GPIO_SETVALUE, TRIG_PIN, 0);
    close(trigger_fd);

    int echo_fd = open("/dev/gpiochip0", O_RDONLY);
    if (echo_fd == -1) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (ioctl(echo_fd, GPIO_GETVALUE, ECHO_PIN) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
    }
    close(echo_fd);

    long duration = (end.tv_sec - start.tv_sec) * 1000000000 + (end.tv_nsec - start.tv_nsec);
    if (duration < 1000000) {
        return -1; // Timeout
    }
    return duration / 58.2; // Convert microseconds to centimeters
}

int read_volume() {
    int adc_value = 0;
    struct spi_ioc_transfer transfer = {
        .tx_buf = NULL,
        .rx_buf = &adc_value,
        .len = 2,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer) < 0) {
        perror("SPI read failed");
        return -1;
    }

    return adc_value;
}

void set_pwm_frequency(int frequency) {
    char path[100];
    snprintf(path, sizeof(path), "%s/duty_cycle", PWM0_PATH);
    FILE *file = fopen(path, "w");
    if (file == NULL) {
        perror("Failed to open PWM duty cycle file");
        return;
    }
    fprintf(file, "%d\n", frequency);
    fclose(file);
}

void set_pwm_volume(int volume) {
    char path[100];
    snprintf(path, sizeof(path), "%s/duty_cycle", PWM0_PATH);
    FILE *file = fopen(path, "w");
    if (file == NULL) {
        perror("Failed to open PWM duty cycle file");
        return;
    }
    fprintf(file, "%d\n", volume);
    fclose(file);
}

int main() {
    signal(SIGINT, handle_sigint);

    // Initialize libgpiod
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        return 1;
    }

    // Initialize PWM
    pwm_fd = open(PWM0_PATH, O_RDWR);
    if (pwm_fd == -1) {
        perror("Failed to open PWM device");
        return 1;
    }
    if (ioctl(pwm_fd, PWM_GET_FREQ, &frequency) < 0) {
        perror("Failed to get PWM frequency");
        return 1;
    }
    if (ioctl(pwm_fd, PWM_SET_FREQ, 440) < 0) {
        perror("Failed to set PWM frequency");
        return 1;
    }
    if (ioctl(pwm_fd, PWM_GET_DUTY_CYCLE, &volume) < 0) {
        perror("Failed to get PWM duty cycle");
        return 1;
    }
    if (ioctl(pwm_fd, PWM_SET_DUTY_CYCLE, 50) < 0) {
        perror("Failed to set PWM duty cycle");
        return 1;
    }

    load_calibration_data();

    while (1) {
        int distance = read_distance();
        if (distance == -1) {
            printf("Distance read error. Using last valid distance: %d cm\n", last_valid_distance);
        } else {
            last_valid_distance = distance;
            int frequency = 220 + (distance * 660) / 100; // Linear mapping
            set_pwm_frequency(frequency);
        }

        int volume = read_volume();
        if (volume == -1) {
            printf("Volume read error. Using last valid volume: %d\n", last_valid_volume);
        } else {
            last_valid_volume = volume;
            set_pwm_volume(volume);
        }

        usleep(100000); // Adjust as needed
    }

    close(spi_fd);
    close(pwm_fd);
    gpiod_chip_close(gpiod_ctx);

    return 0;
}

