    struct spi_ioc_transfer transfer = {
        .tx_buf = NULL,
        .rx_buf = &adc_value,
        .len = 2,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE, &transfer) < 0) {
        perror("SPI read failed");
        return -1;
    }

    return adc_value;
}

