#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define AQI_THRESHOLD 100
#define GPIO_FAN 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define LOG_FILE "air_quality.log"
#define MAX_RETRIES 3
#define RETRY_DELAY 1000000 // 1 second in microseconds

static int spi_fd;
static FILE *log_file;
static volatile sig_atomic_t exit_flag = 0;

void signal_handler(int sig) {
    exit_flag = 1;
}

void log_data(const char *timestamp, int aqi) {
    fprintf(log_file, "%s, %d\n", timestamp, aqi);
    fflush(log_file);
}

void initialize_spi() {
    if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void close_spi() {
    if (spi_fd >= 0) {
        spiClose(spi_fd);
    }
}

void initialize_log() {
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void close_log() {
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void close_pigpio() {
    if (gpioInitialise() >= 0) {
        gpioTerminate();
    }
}

void turn_fan_on() {
    gpioWrite(GPIO_FAN, 0);
}

void turn_fan_off() {
    gpioWrite(GPIO_FAN, 1);
}

int read_adc() {
    uint8_t tx[3] = {0x01, 0x80, 0x00}; // Start bit, single-ended mode, channel 0
    uint8_t rx[3] = {0, 0, 0};

    for (int i = 0; i < MAX_RETRIES; i++) {
        if (spiRead(spi_fd, rx, 3) < 0) {
            fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
            usleep(RETRY_DELAY);
            continue;
        }
        break;
    }

    if (i == MAX_RETRIES) {
        fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
        close_spi();
        initialize_spi();
        return -1;
    }

    int adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    initialize_pigpio();
    initialize_spi();
    initialize_log();

    turn_fan_off();

    while (!exit_flag) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        int adc_value = read_adc();
        if (adc_value < 0) {
            continue;
        }

        int aqi = (adc_value * 500) / 1023; // Linear mapping

        log_data(timestamp, aqi);

        if (aqi > AQI_THRESHOLD) {
            turn_fan_on();
        } else {
            turn_fan_off();
        }

        sleep(5);
    }

    close_log();
    close_spi();
    close_pigpio();

    return 0;
}

