#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define ADC_CHANNEL 0
#define LOG_FILE "alcohol_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static int spi_fd;
static int gpio_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

static void sig_handler(int sig) {
    should_exit = 1;
}

static void log_reading(int adc_value, double ppm) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);
    fprintf(log_file, "%s, %d, %.2f\n", timestamp, adc_value, ppm);
    fflush(log_file);
}

static int read_adc() {
    uint8_t tx[3] = {0x01, (ADC_CHANNEL << 4) | 0x80, 0x00};
    uint8_t rx[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (spi_xfer(spi_fd, tx, rx, 3, NULL) < 0) {
            perror("SPI transfer failed");
            retries++;
            usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        break;
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Sensor absent or ADC read error\n");
        return -1;
    }

    double ppm = (adc_value * 0.5) - 10.0;
    return adc_value;
}

static void classify_reading(int adc_value, double ppm) {
    if (ppm > 50.0) {
        printf("Alcohol detected! Limit exceeded.\n");
    } else if (ppm < 20.0) {
        printf("Sobriety confirmed.\n");
    } else {
        printf("Alcohol level within acceptable range.\n");
    }
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            continue;
        }

        double ppm = (adc_value * 0.5) - 10.0;
        log_reading(adc_value, ppm);
        classify_reading(adc_value, ppm);

        sleep(1);
    }

    fclose(log_file);
    close(spi_fd);

    return EXIT_SUCCESS;
}

