This C program uses the libgpiod library for GPIO control and the standard Linux spidev for SPI communication with an MCP3008 ADC. It reads analog voltage from an MQ-3 alcohol sensor connected to MCP3008 channel 0 via SPI0, logs readings to 'alcohol_log.txt', and classifies readings based on PPM values. The program handles ADC read errors robustly by retrying up to 3 times with a 100 ms delay before logging an error. It also handles SIGINT/SIGTERM for graceful shutdown, closing all file descriptors and releasing GPIO resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define MCP3008_CHANNEL 0
#define SPI_CLOCK_SPEED 1000000
#define THRESHOLD 300
#define LOG_FILE "irrigation.log"
#define MAX_LOG_SIZE 1024

static int pumpPin = 18;
static int spiHandle;
static FILE *logFile;

void logEvent(const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(logFile, "%s - %s\n", timestamp, event);
    fflush(logFile);
}

void handleSignal(int signum) {
    logEvent("Received signal, shutting down...");
    gpioWrite(pumpPin, 0); // Turn off the pump
    if (spiHandle != -1) {
        spiClose(spiHandle);
    }
    if (logFile != NULL) {
        fclose(logFile);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpioSetMode(pumpPin, PI_OUTPUT);
    gpioWrite(pumpPin, 0); // Turn off the pump initially

    if ((spiHandle = spiOpen(SPI_CHANNEL, SPI_CLOCK_SPEED, 0)) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);

    while (1) {
        int adcValue = spiRead(spiHandle, MCP3008_CHANNEL, 1);
        if (adcValue < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            continue;
        }

        logEvent(adcValue < THRESHOLD ? "Pump ON" : "Pump OFF");

        if (adcValue < THRESHOLD) {
            gpioWrite(pumpPin, 1); // Turn on the pump
        } else {
            gpioWrite(pumpPin, 0); // Turn off the pump
        }

        sleep(60); // Sample every 60 seconds
    }

    fclose(logFile);
    spiClose(spiHandle);
    gpioTerminate();
    return 0;
}

