#define ADC_MOSI 10
#define ADC_MISO 9
#define ADC_SCLK 11
#define LED_PIN 17
#define CALIBRATION_TIME 5
#define NOISE_THRESHOLD 10

static int spiHandle;
static int ledState = 0;
static int calibratedLevel = 0;

void handleSigint(int signum) {
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    close(spiHandle);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(ADC_CS, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set ADC CS mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ADC_MOSI, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set ADC MOSI mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ADC_MISO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ADC MISO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ADC_SCLK, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set ADC SCLK mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED mode\n");
        gpioTerminate();
        return 1;
    }

    if ((spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0)) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handleSigint);

    // Calibrate for 5 seconds
    calibratedLevel = 0;
    for (int i = 0; i < 5000; i++) {
        calibratedLevel += readADC();
        usleep(10000);
    }
    calibratedLevel /= 5000;

    printf("Calibrated level: %d\n", calibratedLevel);

    while (1) {
        int level = readADC();
        if (level > calibratedLevel + (calibratedLevel * NOISE_THRESHOLD / 100)) {
            if (ledState == 0) {
                ledState = 1;
                gpioWrite(LED_PIN, 1);
                usleep(100000); // Debounce
            }
        } else {
            if (ledState == 1) {
                ledState = 0;
                gpioWrite(LED_PIN, 0);
            }
        }
        usleep(10000); // Sample rate of 10 Hz
    }

    return 0;
}

int readADC() {
    uint8_t tx[3] = {0x01, 0x80, 0x00}; // Start conversion, single-ended, channel 0
    uint8_t rx[3];

    gpioWrite(ADC_CS, 0);
    spiXfer(spiHandle, tx, rx, 3);
    gpioWrite(ADC_CS, 1);

    int adcValue = (rx[1] << 8) | rx[2];
    return adcValue;
}

