#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define LOG_FILE "airflow_log.txt"
#define BUFFER_SIZE 1024

static int spiHandle;
static FILE *logFile;
static volatile sig_atomic_t shouldExit = 0;

void signalHandler(int signum) {
    shouldExit = 1;
}

void logError(const char *message) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(stderr, "%s: ERROR: %s\n", timestamp, message);
}

void logReading(float airflow) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(logFile, "%s: %.2f SLPM\n", timestamp, airflow);
}

void initPigpio() {
    if (gpioInitialise() < 0) {
        logError("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
}

void initSPI() {
    spiHandle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spiHandle < 0) {
        logError("Failed to open SPI");
        exit(EXIT_FAILURE);
    }
}

void closeSPI() {
    if (spiHandle >= 0) {
        spiClose(spiHandle);
    }
}

void initLogFile() {
    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        logError("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void closeLogFile() {
    if (logFile != NULL) {
        fclose(logFile);
    }
}

void readADC() {
    uint8_t command[3] = {0x01, (ADC_CHANNEL << 4), 0x00};
    uint8_t buffer[BUFFER_SIZE];
    int bytesRead = spiRead(spiHandle, buffer, sizeof(buffer));
    if (bytesRead < 0) {
        logError("ADC read failed");
        return;
    }
    uint16_t adcValue = (buffer[1] << 8) | buffer[0];
    float voltage = adcValue * 3.3 / 1023.0;
    float airflow = (voltage - 0.5) / (4.5 - 0.5) * 200.0;
    logReading(airflow);
}

int main() {
    initPigpio();
    initSPI();
    initLogFile();

    signal(SIGINT, signalHandler);

    while (!shouldExit) {
        readADC();
        usleep(100000); // 100 ms
    }

    closeLogFile();
    closeSPI();
    gpioTerminate();

    return 0;
}

