#define MCP3008_MISO 9
#define MCP3008_SCLK 11
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define FILTER_Q 0.01
#define FILTER_R 0.01
#define FILTER_P 1.0
#define FILTER_K 0.0
#define FILTER_X 0.0
#define FILTER_PX 0.0
#define FILTER_VX 0.0
#define FILTER_VPX 0.0
#define FILTER_Y 0.0
#define FILTER_PY 0.0
#define FILTER_VY 0.0
#define FILTER_VPY 0.0
#define FILTER_Z 0.0
#define FILTER_PZ 0.0
#define FILTER_VZ 0.0
#define FILTER_VPZ 0.0
#define FILTER_RATE 10
#define FILTER_DT 1.0 / FILTER_RATE

static int gpiod_handle;
static int mcp3008_handle;
static int spi_handle;
static int adc_channel[3] = {ADXL335_XOUT, ADXL335_YOUT, ADXL335_ZOUT};
static int adc_cs = MCP3008_CS;
static int adc_mosi = MCP3008_MOSI;
static int adc_miso = MCP3008_MISO;
static int adc_sclk = MCP3008_SCLK;
static int adc_channels[3] = {0, 1, 2};
static int adc_buffer[3];
static int adc_value[3];
static double filter_x, filter_px, filter_vx, filter_vpx;
static double filter_y, filter_py, filter_vy, filter_vpy;
static double filter_z, filter_pz, filter_vz, filter_vpz;
static double filter_rate = 10.0;
static double filter_dt = 1.0 / filter_rate;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Exiting...\n");
        gpioTerminate();
        mcp3008_close(mcp3008_handle);
        spi_close(spi_handle);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }
    gpiod_handle = gpioOpen(0, 0);
    if (gpiod_handle < 0) {
        fprintf(stderr, "Failed to open GPIO\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mcp3008_init(&mcp3008_handle, adc_cs, adc_mosi, adc_miso, adc_sclk, SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to initialize MCP3008\n");
        gpioTerminate();
        mcp3008_close(mcp3008_handle);
        return EXIT_FAILURE;
    }

    if (spi_open(&spi_handle, SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        mcp3008_close(mcp3008_handle);
        spi_close(spi_handle);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        for (int i = 0; i < 3; i++) {
            if (mcp3008_read(mcp3008_handle, adc_channels[i], adc_buffer) < 0) {
                fprintf(stderr, "Failed to read ADC\n");
                continue;
            }
            adc_value[i] = (adc_buffer[0] << 8) | adc_buffer[1];
        }

        double x = (adc_value[0] - 512.0) * 300.0 / 1024.0;
        double y = (adc_value[1] - 512.0) * 300.0 / 1024.0;
        double z = (adc_value[2] - 512.0) * 300.0 / 1024.0;

        filter_x = filter_x + filter_dt * (x - filter_x);
        filter_px = filter_px + filter_dt * (x - filter_x) * (x - filter_x);
        filter_vx = filter_vx + filter_dt * (filter_x - filter_vx);
        filter_vpx = filter_vpx + filter_dt * (filter_x - filter_vx) * (filter_x - filter_x);

        filter_y = filter_y + filter_dt * (y - filter_y);
        filter_py = filter_py + filter_dt * (y - filter_y) * (y - filter_y);
        filter_vy = filter_vy + filter_dt * (filter_y - filter_vy);
        filter_vpy = filter_vpy + filter_dt * (filter_y - filter_vy) * (filter_y - filter_y);

        filter_z = filter_z + filter_dt * (z - filter_z);
        filter_pz = filter_pz + filter_dt * (z - filter_z) * (z - filter_z);
        filter_vz = filter_vz + filter_dt * (filter_z - filter_vz);
        filter_vpz = filter_vpz + filter_dt * (filter_z - filter_vz) * (filter_z - filter_z);

        double kx = filter_px / (filter_px + filter_r);
        double ky = filter_py / (filter_py + filter_r);
        double kz = filter_pz / (filter_pz + filter_r);

        filter_x = filter_x + kx * (x - filter_x);
        filter_px = filter_px + kx * (x - filter_x) * (x - filter_x);
        filter_vx = filter_vx + kx * (filter_x - filter_vx);
        filter_vpx = filter_vpx + kx * (filter_x - filter_vx) * (filter_x - filter_x);

        filter_y = filter_y + ky * (y - filter_y);
        filter_py = filter_py + ky * (y - filter_y) * (y - filter_y);
        filter_vy = filter_vy + ky * (filter_y - filter_vy);
        filter_vpy = filter_vpy + ky * (filter_y - filter_vy) * (filter_y - filter_y);

        filter_z = filter_z + kz * (z - filter_z);
        filter_pz = filter_pz + kz * (z - filter_z) * (z - filter_z);
        filter_vz = filter_vz + kz * (filter_z - filter_vz);
        filter_vpz = filter_vpz + kz * (filter_z - filter_vz) * (filter_z - filter_z);

        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", filter_x / 1000.0, filter_y / 1000.0, filter_z / 1000.0);
        usleep(100000);
    }

    gpioTerminate();
    mcp3008_close(mcp3008_handle);
    spi_close(spi_handle);
    return EXIT_SUCCESS;
}

