#define VCC 3.3
#define V_QUIESCENT 1.65
#define SENSITIVITY 0.025
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100
#define MAX_SENSORS 3

static volatile sig_atomic_t should_exit = 0;

void handle_sigint(int signum) {
    should_exit = 1;
}

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *lines[MAX_SENSORS];
    int sensor_values[MAX_SENSORS];
    double magnetic_fields[MAX_SENSORS];
    FILE *log_file;
    struct timespec sleep_time = {0, SAMPLE_INTERVAL_MS * 1000000};

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for each sensor
    for (int i = 0; i < MAX_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (lines[i] == NULL) {
            perror("Failed to get GPIO line");
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_input(lines[i], "DRV5055VA") < 0) {
            perror("Failed to request GPIO line input");
            exit(EXIT_FAILURE);
        }
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        // Read the digital state of each sensor
        for (int i = 0; i < MAX_SENSORS; i++) {
            sensor_values[i] = gpiod_line_get_value(lines[i]);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Failed to read GPIO line %d\n", i);
                continue;
            }
        }

        // Calculate the magnetic field strength in millitesla
        for (int i = 0; i < MAX_SENSORS; i++) {
            double v_out = sensor_values[i] ? VCC : 0.0;
            magnetic_fields[i] = (v_out - V_QUIESCENT) / SENSITIVITY;
        }

        // Log the readings to the file
        fprintf(log_file, "%d,%d,%d\n", (int)magnetic_fields[0], (int)magnetic_fields[1], (int)magnetic_fields[2]);
        fflush(log_file);

        // Check for magnetic field values outside the range -100 mT to +100 mT
        for (int i = 0; i < MAX_SENSORS; i++) {
            if (magnetic_fields[i] < -100.0 || magnetic_fields[i] > 100.0) {
                fprintf(stderr, "Warning: Magnetic field value %f mT out of range\n", magnetic_fields[i]);
            }
        }

        // Sleep for the sample interval
        nanosleep(&sleep_time, NULL);
    }

    // Close the log file
    fclose(log_file);

    // Release all libgpiod resources
    for (int i = 0; i < MAX_SENSORS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    close(fd);

    return 0;
