            double v_out = sensor_values[i] ? VCC : 0.0;
            magnetic_fields[i] = (v_out - V_QUIESCENT) / SENSITIVITY;
        }

        // Log the readings to the file
        fprintf(log_file, "%d,%d,%d\n", (int)magnetic_fields[0], (int)magnetic_fields[1], (int)magnetic_fields[2]);
        fflush(log_file);

        // Check for magnetic field values outside the range -100 mT to +100 mT
        for (int i = 0; i < MAX_SENSORS; i++) {
            if (magnetic_fields[i] < -100.0 || magnetic_fields[i] > 100.0) {
                fprintf(stderr, "Warning: Magnetic field value %f mT out of range\n", magnetic_fields[i]);
            }
        }

        // Sleep for the sample interval
        nanosleep(&sleep_time, NULL);
    }

    // Close the log file
    fclose(log_file);

    // Release all libgpiod resources
    for (int i = 0; i < MAX_SENSORS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    close(fd);

    return 0;
}
```

This C program reads three Texas Instruments DRV5055VA Hall-Effect sensors connected to GPIO4, GPIO17, and GPIO27 using the libgpiod C API. It simulates the analog-to-digital conversion by reading the digital logic state of each pin and treating it as the sensor output. The magnetic field strength is calculated using the formula B = (V_out - V_quiescent) / Sensitivity, with VCC = 3.3V and a sensitivity of 0.025 V/mT. The readings are logged to 'magnetic_log.txt' in comma-separated format, and the program handles SIGINT for graceful shutdown.

