#define CHECK_INTERVAL 60

static volatile sig_atomic_t keep_running = 1;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s - %s\n", timestamp, event);
        fclose(log);
    }
}

void signal_handler(int signum) {
    keep_running = 0;
    log_event("Program terminated by signal");
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        log_event("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(MOISTURE_PIN, PI_INPUT);
    gpioSetMode(PUMP_PIN, PI_OUTPUT);
    gpioSetPullUpDown(MOISTURE_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(PUMP_PIN, PI_PUD_UP);
}

void read_moisture() {
    int moisture_value = gpioRead(MOISTURE_PIN);
    log_event(moisture_value < 30 ? "Pump turned on" : "Pump turned off");
    gpioWrite(PUMP_PIN, moisture_value < 30);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    setup_gpio();

    while (keep_running) {
        read_moisture();
        sleep(CHECK_INTERVAL);
    }

    gpioTerminate();
    log_event("Program terminated normally");
    return 0;
}

