#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED_HZ 1000000
#define NUM_CHANNELS 3
#define CSV_FILE "sensor_data.csv"
#define DELAY_MS 1000

static int spi_fd;
static gpiod_chip *chip;
static gpiod_line *ce_line;

void signal_handler(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (ce_line) {
        gpiod_line_release(ce_line);
    }
    printf("Exiting...\n");
    exit(0);
}

int main() {
    int ret;
    uint8_t command[3];
    uint8_t data[3];
    FILE *csv_file;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode, bits per word, and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO chip and CE line
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(csv_file);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ce_line = gpiod_chip_get_line(chip, 25); // Assuming CE0 is GPIO25
    if (!ce_line) {
        perror("Failed to get CE line");
        gpiod_chip_close(chip);
        fclose(csv_file);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(ce_line, "CE0", 0);
    if (ret < 0) {
        perror("Failed to request CE line");
        gpiod_line_release(ce_line);
        gpiod_chip_close(chip);
        fclose(csv_file);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Write to CSV header
    fprintf(csv_file, "Channel,Value\n");

    while (1) {
        // Set CE line high
        ret = gpiod_line_set_value(ce_line, 1);
        if (ret < 0) {
            perror("Failed to set CE line high");
            break;
        }

        // Send command for channel 0
        command[0] = 0x01; // Start bit
        command[1] = 0x80 | (0 << 4); // Single-ended mode, channel 0
        command[2] = 0x00; // Dummy byte
        ret = write(spi_fd, command, sizeof(command));
        if (ret < 0) {
            perror("Failed to write to SPI");
            break;
        }

        // Read data
        ret = read(spi_fd, data, sizeof(data));
        if (ret < 0) {
            perror("Failed to read from SPI");
            break;
        }

        // Calculate 10-bit value
        uint16_t value = ((data[1] & 0x03) << 8) | data[2];

        // Write to CSV
        fprintf(csv_file, "0,%d\n", value);

        // Send command for channel 1
        command[1] = 0x80 | (1 << 4); // Single-ended mode, channel 1
        ret = write(spi_fd, command, sizeof(command));
        if (ret < 0) {
            perror("Failed to write to SPI");
            break;
        }

        // Read data
        ret = read(spi_fd, data, sizeof(data));
        if (ret < 0) {
            perror("Failed to read from SPI");
            break;
        }

        // Calculate 10-bit value
        value = ((data[1] & 0x03) << 8) | data[2];

        // Write to CSV
        fprintf(csv_file, "1,%d\n", value);

        // Send command for channel 2
        command[1] = 0x80 | (2 << 4); // Single-ended mode, channel 2
        ret = write(spi_fd, command, sizeof(command));
        if (ret < 0) {
            perror("Failed to write to SPI");
            break;
        }

        // Read data
        ret = read(spi_fd, data, sizeof(data));
        if (ret < 0) {
            perror("Failed to read from SPI");
            break;
        }

        // Calculate 10-bit value
        value = ((data[1] & 0x03) << 8) | data[2];

        // Write to CSV
        fprintf(csv_file, "2,%d\n", value);

        // Set CE line low
        ret = gpiod_line_set_value(ce_line, 0);
        if (ret < 0) {
            perror("Failed to set CE line low");
            break;
        }

        // Delay for 1 second
        usleep(DELAY_MS * 1000);
    }

    // Close CSV file
    fclose(csv_file);

    // Release resources
    gpiod_line_release(ce_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

