#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_SOUND_PIN 17
#define GPIO_ALARM_PIN 18
#define DELAY_MS 100
#define MAX_READS 1000

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *sound_line, *alarm_line;
    unsigned int value;
    int sound_level = 0;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    sound_line = gpiod_chip_get_line(chip, GPIO_SOUND_PIN);
    if (!sound_line) {
        perror("Failed to get sound line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    alarm_line = gpiod_chip_get_line(chip, GPIO_ALARM_PIN);
    if (!alarm_line) {
        perror("Failed to get alarm line");
        gpiod_line_release(sound_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set line direction
    ret = gpiod_line_request_input(sound_line, "sound_sensor");
    if (ret) {
        perror("Failed to request sound line input");
        gpiod_line_release(sound_line);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(alarm_line, "alarm_led", 0);
    if (ret) {
        perror("Failed to request alarm line output");
        gpiod_line_release(sound_line);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    printf("Sound sensor and alarm LED initialized.\n");

    while (!should_exit) {
        // Read sound level
        ret = gpiod_line_get_value(sound_line, &value);
        if (ret) {
            perror("Failed to read sound line value");
            break;
        }
        sound_level = value;

        // Print sound level
        printf("Sound level: %d\n", sound_level);

        // Blink alarm LED if sound is detected
        if (sound_level == 0) {
            gpiod_line_set_value(alarm_line, 1);
            usleep(1000000); // 1 second ON
            gpiod_line_set_value(alarm_line, 0);
        }

        // Delay
        usleep(DELAY_MS * 1000);
    }

    // Clean up
    gpiod_line_release(sound_line);
    gpiod_line_release(alarm_line);
    gpiod_chip_close(chip);

    printf("Program exited cleanly.\n");

    return 0;
}

