#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <gpiod.h>

#define VIBRATION_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define MAX_LINE_LENGTH 256

volatile sig_atomic_t exit_flag = 0;

static void handle_signal(int sig) {
    exit_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    FILE *log_file;
    char timestamp[20];
    time_t now;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Get the line for GPIO17
    line = gpiod_chip_get_line(chip, VIBRATION_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the line for falling-edge event detection
    if (gpiod_line_request_edge_event(line, "vibration-monitor", GPIOD_EDGE_FALLING)) {
        perror("Failed to request falling-edge event");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (!exit_flag) {
        // Wait for the next falling-edge event
        if (gpiod_line_event_wait(line, -1) < 0) {
            perror("Failed to wait for event");
            break;
        }

        // Read the event
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("Failed to read event");
            break;
        }

        // Get the current timestamp
        now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Append the timestamped line to the log file
        if (fprintf(log_file, "%s: Vibration detected\n", timestamp) < 0) {
            perror("Failed to write to log file");
            break;
        }

        // Print the same message to stdout
        printf("%s: Vibration detected\n", timestamp);

        // Invoke system("sudo shutdown -h now")
        if (system("sudo shutdown -h now") < 0) {
            perror("Failed to invoke shutdown");
            break;
        }
    }

    // Clean up resources
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

