#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define BUFFER_SIZE 120
#define FILE_NAME "temp_log.dat"
#define TEMP_PER_VREF 10.0f
#define VREF 3.3f
#define INTERVAL 5

static int spi_fd;
static float buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int running = 1;

void signal_handler(int signum) {
    running = 0;
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio\n");
    }
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_HZ, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        uint8_t tx[4] = {0x01, 0x80, 0x00, 0x00};
        uint8_t rx[3];

        if (write(spi_fd, tx, 4) != 4) {
            fprintf(stderr, "Failed to write to SPI\n");
            continue;
        }

        if (read(spi_fd, rx, 3) != 3) {
            fprintf(stderr, "Failed to read from SPI\n");
            continue;
        }

        float temp = ((rx[1] & 0x03) << 8) | rx[2];
        temp *= TEMP_PER_VREF;
        temp /= VREF;

        buffer[buffer_index++] = temp;
        if (buffer_index >= BUFFER_SIZE) {
            buffer_index = 0;
        }

        if (running) {
            sleep(INTERVAL);
        }
    }

    FILE *file = fopen(FILE_NAME, "wb+");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file %s\n", FILE_NAME);
    } else {
        fwrite(buffer, sizeof(float), BUFFER_SIZE, file);
        fclose(file);
    }

    close(spi_fd);
    gpioTerminate();
    return 0;
}

