code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define BH1750_ADDR 0x23
#define MAX4466_ADDR 0x44
#define MCP3008_ADDR 0x08
#define SPI_CHANNEL 0
#define SPI_SPEED_HZ 1000000
#define I2C_BUS 1
#define LOG_FILE "environmental_log.txt"

static int i2c_fd;
static int spi_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

void log_entry(const char *format, ...) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    va_list args;
    va_start(args, format);
    fprintf(log_file, "%s, ", timestamp);
    vfprintf(log_file, format, args);
    fprintf(log_file, "\n");
    va_end(args);
}

void read_bh1750() {
    uint8_t cmd = 0x10; // Start measurement at 1lx resolution
    uint8_t data[2];
    int ret;

    ret = i2c_smbus_write_byte(i2c_fd, cmd);
    if (ret < 0) {
        perror("Failed to write to BH1750");
        return;
    }

    usleep(100000); // Wait for measurement to complete

    ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0x01, 2, data);
    if (ret < 0) {
        perror("Failed to read from BH1750");
        return;
    }

    uint16_t lux = (data[0] << 8) | data[1];
    log_entry("Light: %d", lux);
}

void read_max4466() {
    uint8_t cmd = 0x00; // Start conversion
    uint8_t data[2];
    int ret;

    ret = i2c_smbus_write_byte(i2c_fd, cmd);
    if (ret < 0) {
        perror("Failed to write to MAX4466");
        return;
    }

    usleep(100000); // Wait for conversion to complete

    ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0x00, 2, data);
    if (ret < 0) {
        perror("Failed to read from MAX4466");
        return;
    }

    uint16_t raw_adc = (data[0] << 8) | data[1];
    log_entry("Sound: %d", raw_adc);
}

void read_mcp3008() {
    uint8_t cmd = 0x00; // Start conversion
    uint8_t data[3];
    int ret;

    ret = spi_transfer(spi_fd, &cmd, 1, data, 3);
    if (ret < 0) {
        perror("Failed to transfer SPI");
        return;
    }

    uint16_t raw_adc = (data[1] << 8) | data[2];
    log_entry("Sound: %d", raw_adc);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

