#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL 1000000 // 1 second in microseconds

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    const char *chip_name = "gpiochip0";
    const char *line_name = "gpio17";
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    FILE *log_file;
    struct timespec ts;
    char timestamp[20];

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(gpiod_last_error()));
        return EXIT_FAILURE;
    }

    // Get the line
    line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", gpiod_strerror(gpiod_last_error()));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line for input with pull-down
    ret = gpiod_line_request_input(line, "flame_sensor");
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", gpiod_strerror(gpiod_last_error()));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Log header
    fprintf(log_file, "timestamp,pin,state\n");

    while (!should_exit) {
        // Get the current time
        clock_gettime(CLOCK_MONOTONIC, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%f", localtime(&ts.tv_sec));

        // Read the line state
        int state = gpiod_line_get_value(line);
        if (state < 0) {
            fprintf(stderr, "Failed to read GPIO line: %s\n", gpiod_strerror(gpiod_last_error()));
            break;
        }

        // Log the event
        fprintf(log_file, "%s,%d,%d\n", timestamp, FLAME_SENSOR_PIN, state);
        fflush(log_file);

        // Print alarm message if flame is detected
        if (state) {
            printf("ALARM: Flame detected!\n");
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

