#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_MODE 0
#define SPI_CLOCK_SPEED_HZ 1000000
#define ADC_CHANNELS 3
#define LOG_FILE "soil_data.txt"
#define BUFFER_SIZE 1024

static int spiHandle;
static FILE *logFile;
static volatile sig_atomic_t exitFlag = 0;

void signalHandler(int signum) {
    exitFlag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (spiOpen(SPI_CHANNEL, SPI_CLOCK_SPEED_HZ, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signalHandler);

    while (!exitFlag) {
        char buffer[BUFFER_SIZE];
        int adcValues[ADC_CHANNELS];
        int i;

        for (i = 0; i < ADC_CHANNELS; i++) {
            buffer[0] = 0b11000000 | (i << 4); // Start bit, single-ended, channel 0-2
            buffer[1] = 0; // Dummy byte

            if (spiXfer(spiHandle, buffer, buffer, 2) < 0) {
                fprintf(stderr, "Failed to read from SPI\n");
                continue;
            }

            adcValues[i] = (buffer[0] << 8) | buffer[1];
            if (adcValues[i] < 0 || adcValues[i] > 1023) {
                fprintf(stderr, "Invalid ADC value: %d\n", adcValues[i]);
                continue;
            }
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        for (i = 0; i < ADC_CHANNELS; i++) {
            double moisture = (1.0 - (adcValues[i] / 1023.0)) * 100.0;
            fprintf(logFile, "%s, Sensor %d: %.2f%%\n", timestamp, i, moisture);
        }

        fclose(logFile);
        logFile = fopen(LOG_FILE, "a");
        if (logFile == NULL) {
            fprintf(stderr, "Failed to reopen log file\n");
            spiClose(spiHandle);
            gpioTerminate();
            return 1;
        }

        gpioDelay(60000000); // 60 seconds
    }

    fclose(logFile);
    spiClose(spiHandle);
    gpioTerminate();

    printf("Goodbye!\n");
    return 0;
}

