#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the Songle SRD-05VDC-SL relays
#define RELAY_1 17
#define RELAY_2 22
#define RELAY_3 23
#define RELAY_4 24

// Array to hold the GPIO lines for the relays
static struct gpiod_line *relay_lines[4];

// Signal handler to clean up and exit
void signal_handler(int sig) {
    // Deactivate all relays
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(relay_lines[i], 0);
    }
    // Release all GPIO lines
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(relay_lines[i]);
    }
    // Exit the program
    exit(EXIT_SUCCESS);
}

int main() {
    // Initialize the GPIO library
    int fd = gpiod_chip_open_by_name("gpiochip0");
    if (fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for the relays
    for (int i = 0; i < 4; i++) {
        relay_lines[i] = gpiod_chip_get_line(fd, i);
        if (relay_lines[i] < 0) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(fd);
            exit(EXIT_FAILURE);
        }
        // Set the line as an output
        int ret = gpiod_line_request_output(relay_lines[i], "songle_relay", 0);
        if (ret < 0) {
            perror("Failed to request GPIO line as output");
            gpiod_line_release(relay_lines[i]);
            gpiod_chip_close(fd);
            exit(EXIT_FAILURE);
        }
    }

    // Set all relays initially inactive
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(relay_lines[i], 0);
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to sequence the relays
    while (1) {
        // Activate each relay in sequence
        for (int i = 0; i < 4; i++) {
            gpiod_line_set_value(relay_lines[i], 1);
            sleep(1); // Relay activation time
        }
        // Deactivate each relay in sequence
        for (int i = 0; i < 4; i++) {
            gpiod_line_set_value(relay_lines[i], 0);
            sleep(1); // Relay deactivation time
        }
    }

    // This line should never be reached
    return EXIT_FAILURE;
}

