#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define LED_PIN 16
#define SPI_CE0 8
#define SPI_MODE 0
#define SPI_CLOCK 1000000
#define THRESHOLD 500
#define DEBOUNCE_DELAY 1000000 // 1 ms

static int spiHandle;
static int ledPin;
static int gpioHandle;
static FILE *logFile;

void signalHandler(int signum) {
    if (signum == SIGINT) {
        // Close SPI
        if (spiHandle != -1) {
            if (pigpio_spi_close(spiHandle) < 0) {
                fprintf(stderr, "Failed to close SPI\n");
            }
        }
        // Terminate pigpio
        if (gpioHandle != -1) {
            if (gpioTerminate() < 0) {
                fprintf(stderr, "Failed to terminate pigpio\n");
            }
        }
        // Turn off LED
        if (ledPin != -1) {
            if (gpioWrite(ledPin, 0) < 0) {
                fprintf(stderr, "Failed to turn off LED\n");
            }
        }
        // Close log file
        if (logFile != NULL) {
            fclose(logFile);
        }
        exit(0);
    }
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signalHandler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    gpioHandle = gpioInitialise();

    // Initialize SPI
    spiHandle = pigpio_spi_open(SPI_CE0, SPI_MODE, SPI_CLOCK);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LED
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED mode\n");
        gpioTerminate();
        pigpio_spi_close(spiHandle);
        return 1;
    }
    ledPin = LED_PIN;

    // Open log file
    logFile = fopen("sound_events.log", "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        pigpio_spi_close(spiHandle);
        gpioFree();
        return 1;
    }

    // Main loop
    struct timespec lastTriggerTime = {0, 0};
    while (1) {
        // Read ADC
        uint8_t tx[3] = {0x01, (ADC_CHANNEL << 4) | 0x00, 0x00};
        uint8_t rx[3] = {0, 0, 0};
        if (pigpio_spi_transfer(spiHandle, tx, rx, 3) < 0) {
            fprintf(stderr, "Failed to transfer SPI\n");
            continue;
        }
        uint16_t adcValue = (rx[1] << 8) | rx[2];

        // Check if sound level exceeds threshold
        if (adcValue > THRESHOLD) {
            // Check for debounce
            struct timespec currentTime;
            clock_gettime(CLOCK_MONOTONIC, &currentTime);
            if (currentTime.tv_nsec - lastTriggerTime.tv_nsec < DEBOUNCE_DELAY) {
                continue;
            }
            lastTriggerTime = currentTime;

            // Turn on LED
            if (gpioWrite(ledPin, 1) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
                continue;
            }

            // Log event
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(logFile, "%s\n", timestamp);
            fflush(logFile);

            // Keep LED on for 500 ms
            struct timespec sleepTime = {0, 500000000};
            nanosleep(&sleepTime, NULL);

            // Turn off LED
            if (gpioWrite(ledPin, 0) < 0) {
                fprintf(stderr, "Failed to turn off LED\n");
                continue;
            }
        }
    }

    // Clean up
    fclose(logFile);
    gpioTerminate();
    pigpio_spi_close(spiHandle);
    gpioFree();

    return 0;
}

