#define SPI_MODE 0
#define ADC_CHANNEL 0
#define ADC_BITS 10
#define ADC_MAX 1023
#define RAIN_THRESHOLD 5
#define LOG_FILE "rain_log.txt"
#define LOG_FORMAT "%s, %d\n"

volatile sig_atomic_t exit_flag = 0;

