        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up SPI
    if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE)) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up log file
    if ((log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644)) < 0) {
        fprintf(stderr, "Failed to open log file\n");
        close(spi_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set motor to open position
    gpioWrite(17, 0);
    gpioWrite(18, 1);
    gpioPWM(27, 150);

    while (!exit_flag) {
        // Read ADC
        if (spiXfer(spi_fd, tx, rx, 3) < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            close(log_fd);
            close(spi_fd);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }

        // Parse ADC value
        adc_value = (rx[1] & 0x03) << 8 | rx[2];
        rain_level = (adc_value * 10) / ADC_MAX;

        // Log rain reading
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        if (fprintf(log_file, LOG_FORMAT, timestamp, rain_level) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            close(log_fd);
            close(spi_fd);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }
        fflush(log_file);

        // Control motor based on rain level
        if (rain_level >= RAIN_THRESHOLD) {
            // Close window
            gpioWrite(17, 1);
            gpioWrite(18, 0);
            gpioPWM(27, 150);
            sleep(3);
            gpioWrite(17, 0);
            gpioWrite(18, 1);
            gpioPWM(27, 150);
        } else {
            // Open window
            gpioWrite(17, 0);
            gpioWrite(18, 1);
            gpioPWM(27, 150);
            sleep(3);
            gpioWrite(17, 1);
            gpioWrite(18, 0);
            gpioPWM(27, 150);
        }

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    close(log_fd);
    close(spi_fd);
    gpioTerminate();

    return 0;
}

