#define LED_PIN 16
#define MIC_PIN 26
#define ADC_CHANNEL 0
#define THRESHOLD 700
#define DEBOUNCE_TIME 50
#define LED_ON_TIME 500

static volatile sig_atomic_t keep_running = 1;

void sigint_handler(int signum) {
    keep_running = 0;
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("Program terminated by user.\n");
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MIC_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set microphone pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
