#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"
#define A 26.0
#define B -6.0
#define MAX_RETRIES 5

static int gpio_fd;
static int log_fd;
static int retries = 0;

void log_distance(double distance) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_fd, "%s,%.2f\n", timestamp, distance);
    fflush(log_fd);
}

void handle_signal(int signum) {
    if (gpio_fd >= 0) {
        gpio_fd = gpio_close(gpio_fd);
    }
    if (log_fd >= 0) {
        log_fd = close(log_fd);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiochip_open("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request line
    line = gpiochip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiochip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request output mode
    ret = gpio_line_request_output(line, "distance_sensor", 0);
    if (ret) {
        perror("Failed to request GPIO line output");
        gpiochip_close(chip);
        gpio_line_release(line);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        gpiochip_close(chip);
        gpio_line_release(line);
        exit(EXIT_FAILURE);
    }

    // Log header
    fprintf(log_fd, "Timestamp,Distance(mm)\n");
    fflush(log_fd);

    while (1) {
        double distance;
        int value;

        // Read GPIO value
        for (retries = 0; retries < MAX_RETRIES; retries++) {
            ret = gpio_line_get_value(line, &value);
            if (ret == 0) {
                break;
            }
            perror("Failed to read GPIO line value");
            sleep(1);
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read GPIO line value after %d retries\n", MAX_RETRIES);
            continue;
        }

        // Convert GPIO value to distance
        distance = A / value + B;

        // Log distance
        log_distance(distance);

        // Check proximity and print message
        if (distance < 200.0) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        // Sleep for a short period
        sleep(1);
    }

    // Clean up
    gpiochip_close(chip);
    gpio_line_release(line);
    close(log_fd);

    return 0;
}

