#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE SPI_MODE_0
#define ADC_CHANNEL 0
#define DRY_ADC_VALUE 800
#define WET_ADC_VALUE 300
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "soil_moisture.log"
#define LOG_FORMAT "%s,%.2f,%s\n"
#define MAX_LOG_SIZE 1024 * 1024

static int spi_fd;
static int gpio_fd;
static int relay_gpio;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *relay_line;
static struct timespec sleep_time = {0, 60000000}; // 60 seconds

static void log_data(double moisture, int pump_status) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), LOG_FORMAT, timestamp, moisture, pump_status ? "ON" : "OFF");
    if (fputs(log_entry, log_file) == EOF) {
        perror("Failed to write to log file");
    }
    if (fflush(log_file) != 0) {
        perror("Failed to flush log file");
    }
}

static void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_fd >= 0) {
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(0);
}

static void init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED_HZ) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    relay_gpio = 17;
    relay_line = gpiod_chip_get_line(chip, relay_gpio);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(relay_line, "soil_moisture_pump", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

static int read_adc() {
    uint8_t tx[3] = {0x01, (ADC_CHANNEL << 4) | 0x01, 0x00};
    uint8_t rx[3];
    if (write(spi_fd, tx, 3) != 3) {
        perror("Failed to write to SPI");
        return -1;
    }
    if (read(spi_fd, rx, 3) != 3) {
        perror("Failed to read from SPI");
        return -1;
    }
    return (rx[1] << 8) | rx[2];
}

static void check_adc_value(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        exit(EXIT_FAILURE);
    }
}

static void main() {
    signal(SIGINT, handle_sigint);
    init_spi();
    init_gpio();
    init_log_file();

    while (1) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC\n");
            continue;
        }
        check_adc_value(adc_value);

        double moisture = (double)(WET_ADC_VALUE - adc_value) / (WET_ADC_VALUE - DRY_ADC_VALUE) * 100;
        int pump_status = moisture < MOISTURE_THRESHOLD;

        log_data(moisture, pump_status);

        if (pump_status) {
            gpiod_line_set_value(relay_line, 1);
        } else {
            gpiod_line_set_value(relay_line, 0);
        }

        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    close(spi_fd);
}

