This C program initializes the Raspberry Pi 3 Model B+ using the libgpiod library to control a 12V submersible water pump connected to GPIO17 through an active-high relay. It reads analog soil moisture data from a Vegetronix VH400 sensor via an MCP3008 ADC over SPI (CE0, SCLK=GPIO11, MOSI=GPIO10, MISO=GPIO9), configured for single-ended mode on channel 0. The program logs each reading to "soil_moisture.log" with a timestamp, the moisture percentage, and the pump status (ON/OFF), sampling every 60 seconds continuously. It handles sensor read failures gracefully, validates ADC values, and shuts down gracefully on SIGINT.

code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define ADC_CHANNEL 0
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 500

static int spi_fd;
static int gpio_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static FILE *log_file;

static void sig_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_fd >= 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(signum);
}

static void setup_gpio() {
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    int ret = gpiod_line_request_output(line, "spi_cs", 0);
    if (ret) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        exit(EXIT_FAILURE);
    }
}

static void setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer tr = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 1,
        .delay_usecs = 0,
    };

    tr.tx_buf = malloc(tr.len);
    if (!tr.tx_buf) {
        perror("Failed to allocate memory for SPI transfer");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    tr.tx_buf[0] = 0b11000000 | (ADC_CHANNEL << 4); // Start bit, channel select
    tr.tx_buf[1] = 0; // Dummy byte
    tr.tx_buf[2] = 0; // Dummy byte

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
    if (ret < 0) {
        perror("Failed to send SPI message");
        free(tr.tx_buf);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    free(tr.tx_buf);
}

static void setup_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

static void log_magnetic_field(double b_mt) {
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%0.2f\n", now, b_mt);
    fflush(log_file);
}

static void read_adc() {
    struct spi_ioc_transfer tr = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 1,
        .delay_usecs = 0,
    };

    tr.tx_buf = malloc(tr.len);
    if (!tr.tx_buf) {
        perror("Failed to allocate memory for SPI transfer");
        return;
    }

    tr.tx_buf[0] = 0b11000000 | (ADC_CHANNEL << 4); // Start bit, channel select
    tr.tx_buf[1] = 0; // Dummy byte
    tr.tx_buf[2] = 0; // Dummy byte

    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
    if (ret < 0) {
        perror("Failed to send SPI message");
        free(tr.tx_buf);
        return;
    }

    uint16_t adc_value = (tr.rx_buf[1] << 8) | tr.rx_buf[2];
    free(tr.tx_buf);

    if (adc_value > 1023) {
        fprintf(stderr, "ADC read failed: invalid value %u\n", adc_value);
        return;
    }

    double vout_mV = adc_value * 3300.0 / 1023.0;
    double b_mt = (vout_mV - 1650.0) / 100.0;

    log_magnetic_field(b_mt);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    setup_gpio();
    setup_spi();
    setup_log_file();

    while (1) {
        read_adc();
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

