This C program sets up a Raspberry Pi Zero W to read analog voltage from a DRV5055-A1 Hall-effect sensor via an external MCP3008 ADC over SPI. It uses the Linux spidev interface on `/dev/spidev0.0` at 1 MHz, SPI mode 0, 8 bits per word, and manually drives the chip-select line low during each SPI transfer. The program handles errors, logs data to a CSV file, and handles SIGINT and SIGTERM signals to clean up resources.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define LED_PIN 21
#define VCC 3.3
#define THRESHOLD 10.0
#define LOG_FILE "magnetic_log.txt"
#define SPI_SPEED 1000000
#define SPI_MODE 0

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int pi = -1;
    int spi = -1;
    FILE *log_file = NULL;
    uint16_t adc_value;
    float voltage, field_mT;
    struct timespec delay = {0, 100000000}; // 100 ms

    // Initialize pigpio
    if ((pi = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioErrDescription(pi));
        exit(EXIT_FAILURE);
    }

    // Set up LED pin
    if (gpioSetMode(pi, LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode: %s\n", gpioErrDescription(pi));
        gpioTerminate(pi);
        exit(EXIT_FAILURE);
    }

    // Initialize SPI
    if ((spi = gpioSpiOpen(pi, 0, SPI_SPEED, SPI_MODE)) < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", gpioErrDescription(pi));
        gpioTerminate(pi);
        exit(EXIT_FAILURE);
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate(pi);
        gpioSpiClose(spi);
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (running) {
        // Read ADC value
        if (gpioSpiRead(pi, spi, &adc_value, 2) < 0) {
            fprintf(stderr, "Failed to read ADC: %s\n", gpioErrDescription(pi));
            break;
        }

        // Convert ADC value to voltage
        voltage = (float)adc_value * VCC / 1023.0;

        // Convert voltage to magnetic field strength in mT
        field_mT = (voltage - VCC / 2.0) * 1000.0 / (2.5 * VCC / 5.0);

        // Log the reading
        fprintf(log_file, "%ld,%.2f\n", (long)time(NULL), field_mT);
        fflush(log_file);

        // Turn on LED if field exceeds threshold
        if (field_mT > THRESHOLD) {
            gpioWrite(pi, LED_PIN, 1);
        } else {
            gpioWrite(pi, LED_PIN, 0);
        }

        // Delay
        nanosleep(&delay, NULL);
    }

    // Clean up
    fclose(log_file);
    gpioTerminate(pi);
    gpioSpiClose(spi);

    return 0;
}

