This C program initializes the Raspberry Pi Zero W using the pigpio library to read analog voltage from a TI DRV5055VA Hall-effect sensor via an external MCP3008 ADC over SPI0. It logs each timestamped field-strength reading to "magnetic_log.txt" and turns on an LED on GPIO21 if the field exceeds a threshold of 10.0 mT. The program handles initialization failures, SPI and file operations, and SIGINT for graceful cleanup.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define LOG_FILE "moisture_log.txt"

static volatile sig_atomic_t quit = 0;

void signal_handler(int sig) {
    quit = 1;
}

int main() {
    int fd, ret;
    uint8_t tx_buf[3] = {0x01, 0x80, 0x00};
    uint8_t rx_buf[3];
    struct timespec ts;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI
    fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    while (!quit) {
        // Start SPI transfer
        ret = spiXfer(fd, tx_buf, rx_buf, 3);
        if (ret < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        // Parse ADC result
        int adc_value = (rx_buf[1] << 2) | rx_buf[2];

        // Get current timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Log the reading
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            continue;
        }

        fprintf(log_file, "%s, %d\n", timestamp, adc_value);
        fclose(log_file);

        // Wait for 60 seconds
        ts.tv_sec += 60;
        nanosleep(&ts, NULL);
    }

    // Close SPI
    spiClose(fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

