#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED_HZ 1000000
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_BUFFER_SIZE 1024
#define GPIO_CHIP 0
#define GPIO_LINE 17
#define LOG_FILE "current_log.txt"
#define LOG_INTERVAL 1

static int spi_fd;
static int gpio_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

static void signal_handler(int sig) {
    should_exit = 1;
}

static void log_current(float current) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld,%f\n", (long)ts.tv_sec, current);
    fflush(log_file);
}

static float read_current() {
    uint8_t tx[3] = {0x01, 0x80, 0x00}; // Start conversion, single-ended, channel 0
    uint8_t rx[3];
    int ret;

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tx);
    if (ret < 0) {
        perror("SPI ioctl");
        return -1;
    }

    ret = read(spi_fd, rx, 3);
    if (ret < 0) {
        perror("SPI read");
        return -1;
    }

    // Convert ADC result to voltage
    float voltage = (rx[1] << 8) | rx[2];
    voltage *= 5.0 / 1023.0;

    // Convert voltage to current
    float current = voltage / 0.1; // Sensitivity is 100 mV/A

    return current;
}

static void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line, "current_sensor", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
}

static void setup_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

static void setup_log_file() {
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
}

static void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_fd >= 0) {
        gpiod_line_release(gpio_fd);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();
    setup_spi();
    setup_log_file();

    while (!should_exit) {
        float current = read_current();
        if (current >= 0) {
            log_current(current);
        } else {
            fprintf(stderr, "Failed to read current\n");
        }
        sleep(LOG_INTERVAL);
    }

    cleanup();
    return 0;
}

