#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MLX91211_VDD 5.0
#define MLX91211_VREF 2.5
#define MLX91211_FULL_SCALE 50.0
#define MLX91211_ZERO_CURRENT 0.0
#define MLX91211_MAX_CURRENT 50.0
#define MLX91211_MAX_VOLTAGE 5.0
#define MLX91211_MIN_VOLTAGE 0.0
#define MLX91211_MAX_RAW 1023
#define MLX91211_MIN_RAW 0
#define MLX91211_MAX_INTERPOLATED 1023
#define MLX91211_MIN_INTERPOLATED 0
#define MLX91211_INTERPOLATED_STEP (MLX91211_MAX_INTERPOLATED - MLX91211_MIN_INTERPOLATED) / (MLX91211_MAX_CURRENT - MLX91211_ZERO_CURRENT)
#define MLX91211_INTERPOLATED_OFFSET (MLX91211_MIN_INTERPOLATED - MLX91211_ZERO_CURRENT * MLX91211_INTERPOLATED_STEP)

volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int signum) {
    exit_flag = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI0 at 1 MHz, mode 0
    int spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI0\n");
        gpioTerminate();
        return 1;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open log file
    FILE *log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!exit_flag) {
        // Read MCP3008 channel 0
        uint8_t tx[3] = {0x01, 0x80 | (SPI_CHANNEL << 4), 0x00};
        uint8_t rx[3];
        int result = spiXfer(spi_fd, tx, rx, 3);
        if (result < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        // Compute 10-bit result
        int raw = ((rx[1] & 0x03) << 8) | rx[2];

        // Convert raw code to voltage
        float voltage = (raw / (float)MLX91211_MAX_RAW) * MLX91211_VDD;

        // Convert voltage to current
        if (voltage < MLX91211_MIN_VOLTAGE || voltage > MLX91211_MAX_VOLTAGE) {
            fprintf(stderr, "Voltage out of range: %.2fV\n", voltage);
            continue;
        }
        float current = (voltage - MLX91211_VREF) * (MLX91211_FULL_SCALE / (MLX91211_VDD - MLX91211_VREF));

        // Interpolate current
        int interpolated_current = MLX91211_MIN_INTERPOLATED + (int)((current - MLX91211_ZERO_CURRENT) * MLX91211_INTERPOLATED_STEP);

        // Format timestamped line
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        char line[100];
        snprintf(line, sizeof(line), "%s %.2f A\n", timestamp, interpolated_current);

        // Write to log file
        if (fprintf(log_file, line) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            break;
        }
        fflush(log_file);

        // Delay 100 ms
        gpioDelay(100000);
    }

    // Close log file
    fclose(log_file);

    // Close SPI
    spiClose(spi_fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

