code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2
#define LOG_INTERVAL_SEC 1

static volatile sig_atomic_t should_exit = 0;

void handle_sigint(int signum) {
    should_exit = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    int sensor1_state, sensor2_state;
    int majority_count;
    struct timespec sleep_time = {0, DEBOUNCE_DELAY_MS * 1000000};

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for sensor 1 and sensor 2
    line1 = gpiod_chip_get_line(chip, SENSOR1_GPIO);
    if (!line1) {
        perror("Failed to get line for sensor 1");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_GPIO);
    if (!line2) {
        perror("Failed to get line for sensor 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request input for both lines
    if (gpiod_line_request_input(line1, "sensor1") < 0) {
        perror("Failed to request input for sensor 1");
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line2, "sensor2") < 0) {
        perror("Failed to request input for sensor 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        sensor1_state = 0;
        sensor2_state = 0;

        // Debounce sensor 1
        for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
            if (gpiod_line_get_value(line1) == 0) {
                sensor1_state++;
            }
            nanosleep(&sleep_time, NULL);
        }

        // Debounce sensor 2
        for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
            if (gpiod_line_get_value(line2) == 0) {
                sensor2_state++;
            }
            nanosleep(&sleep_time, NULL);
        }

        // Determine majority state
        majority_count = (sensor1_state > sensor2_state) ? sensor1_state : sensor2_state;
        if (majority_count == DEBOUNCE_SAMPLES) {
            if (sensor1_state == 1 && sensor2_state == 1) {
                printf("ALERT: Both sensors detect object\n");
            } else if (sensor1_state == 1) {
                printf("Sensor 1: Object present\n");
            } else if (sensor2_state == 1) {
                printf("Sensor 2: Object present\n");
            }
        } else {
            printf("Sensor 1: No object\n");
            printf("Sensor 2: No object\n");
        }

        // Sleep for log interval
        sleep(LOG_INTERVAL_SEC);
    }

    // Release lines and close chip
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

