code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <libcamera/still.h>

#define PIR_PIN 17
#define DEBOUNCE_DELAY 200
#define CAPTURE_DELAY 50
#define CAPTURE_PATH "/home/pi/security_cam/%Y-%m-%d_%H-%M-%S.jpg"
#define LOG_TAG "security_cam"

static int gpio_initialized = 0;
static int motion_detected = 0;
static int camera_running = 0;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        syslog(LOG_INFO, "Received signal %d, stopping...", signum);
        gpioTerminate();
        camera_running = 0;
        closelog();
        exit(EXIT_SUCCESS);
    }
}

void setup_logging() {
    openlog(LOG_TAG, LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Security camera started");
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }
    gpio_initialized = 1;
    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN);
}

void capture_image() {
    if (!camera_running) {
        syslog(LOG_ERR, "Camera not running");
        return;
    }

    libcamera::StillCapture capture;
    capture.setFormat("jpeg");
    capture.setSize(1280, 720);
    capture.setISO(8601);
    capture.setExposureTime(1000000); // 1 second

    if (!capture.start()) {
        syslog(LOG_ERR, "Failed to start camera capture");
        return;
    }

    if (!capture.wait()) {
        syslog(LOG_ERR, "Camera capture timed out");
        return;
    }

    if (!capture.stop()) {
        syslog(LOG_ERR, "Failed to stop camera capture");
        return;
    }

    char filename[256];
    snprintf(filename, sizeof(filename), CAPTURE_PATH, time(NULL));
    if (capture.save(filename)) {
        syslog(LOG_INFO, "Image captured: %s", filename);
    } else {
        syslog(LOG_ERR, "Failed to save image: %s", filename);
    }
}

void poll_gpio() {
    int current_state = gpioRead(PIR_PIN);
    if (current_state != motion_detected) {
        motion_detected = current_state;
        usleep(DEBOUNCE_DELAY * 1000);
        int confirmed_state = gpioRead(PIR_PIN);
        if (confirmed_state == motion_detected) {
            capture_image();
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
