#define DEFAULT_DEVICE "/dev/video0"
#define DEFAULT_WIDTH 640
#define DEFAULT_HEIGHT 480
#define DEFAULT_FORMAT V4L2_PIX_FMT_GREY
#define DEFAULT_BUFFERS 1
#define DEFAULT_TIMEOUT 2000 // 2 seconds

static int device_fd = -1;
static void *buffers[DEFAULT_BUFFERS];
static unsigned int buffer_sizes[DEFAULT_BUFFERS];
static unsigned int buffer_count = DEFAULT_BUFFERS;
static unsigned int buffer_index = 0;
static struct v4l2_buffer buffer;
static struct v4l2_requestbuffers req;
static struct v4l2_format fmt;
static struct v4l2_capability cap;
static struct sigaction sa;

static void signal_handler(int signum) {
    if (device_fd >= 0) {
        close(device_fd);
    }
    for (int i = 0; i < buffer_count; i++) {
        if (buffers[i]) {
            munmap(buffers[i], buffer_sizes[i]);
        }
    }
    exit(signum);
}

static void init_device() {
    device_fd = open(DEFAULT_DEVICE, O_RDWR);
    if (device_fd < 0) {
        perror("Failed to open device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(device_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query capabilities");
        close(device_fd);
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(device_fd);
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(device_fd);
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = DEFAULT_WIDTH;
    fmt.fmt.pix.height = DEFAULT_HEIGHT;
    fmt.fmt.pix.pixelformat = DEFAULT_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(device_fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set format");
        close(device_fd);
        exit(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));
    req.count = buffer_count;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(device_fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        close(device_fd);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < buffer_count; i++) {
        memset(&buffer, 0, sizeof(buffer));
        buffer.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffer.memory = V4L2_MEMORY_MMAP;
        buffer.index = i;

        if (ioctl(device_fd, VIDIOC_QUERYBUF, &buffer) < 0) {
            perror("Failed to query buffer");
            close(device_fd);
            exit(EXIT_FAILURE);
        }

        buffer_sizes[i] = buffer.length;
        buffers[i] = mmap(NULL, buffer_sizes[i], PROT_READ | PROT_WRITE, MAP_SHARED, device_fd, buffer.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Failed to mmap buffer");
            close(device_fd);
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < buffer_count; i++) {
        buffer.index = i;
        if (ioctl(device_fd, VIDIOC_QBUF, &buffer) < 0) {
            perror("Failed to queue buffer");
            close(device_fd);
            exit(EXIT_FAILURE);
        }
    }

    if (ioctl(device_fd, VIDIOC_STREAMON, &buffer.type) < 0) {
        perror("Failed to start streaming");
        close(device_fd);
        exit(EXIT_FAILURE);
    }
}

static void capture_frames() {
    struct timeval start, end;
    gettimeofday(&start, NULL);

    while (1) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(device_fd, &fds);

        if (select(device_fd + 1, &fds, NULL, NULL, NULL) < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            perror("Failed to select");
            break;
        }

        memset(&buffer, 0, sizeof(buffer));
        buffer.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (ioctl(device_fd, VIDIOC_DQBUF, &buffer) < 0) {
            perror("Failed to dequeue buffer");
            break;
        }

        char filename[256];
        snprintf(filename, sizeof(filename), "image_%04d.pgm", buffer_index + 1);
        FILE *file = fopen(filename, "wb");
        if (!file) {
            perror("Failed to open file");
            break;
        }

        fprintf(file, "P5\n%d %d\n255\n", fmt.fmt.pix.width, fmt.fmt.pix.height);
        fwrite(buffers[buffer_index], 1, buffer_sizes[buffer_index], file);
        fclose(file);

        buffer_index = (buffer_index + 1) % buffer_count;
        if (ioctl(device_fd, VIDIOC_QBUF, &buffer) < 0) {
            perror("Failed to queue buffer");
            break;
        }

        gettimeofday(&end, NULL);
        long elapsed = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);
        if (elapsed >= DEFAULT_TIMEOUT * 1000) {
            fprintf(stderr, "Timeout reached, stopping streaming\n");
            break;
        }
    }
}

int main(int argc, char *argv[]) {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_device();

    capture_frames();

    close(device_fd);
    for (int i = 0; i < buffer_count; i++) {
        if (buffers[i]) {
            munmap(buffers[i], buffer_sizes[i]);
        }
    }

    return 0;
}

