code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <time.h>

#define VID_DEV "/dev/video0"
#define FRAME_LOG "frame_log.txt"
#define WIDTH 640
#define HEIGHT 480
#define FRAMES_PER_SECOND 30
#define BUFFER_COUNT 4

struct buffer {
    void *start;
    size_t length;
};

static int fd;
static struct buffer buffers[BUFFER_COUNT];
static int n_buffers;
static int frame_count;
static int running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

static int init_video() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    int i;

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.count = BUFFER_COUNT;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req.count < BUFFER_COUNT) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    for (i = 0; i < req.count; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            return -1;
        }

        buffers[i].length = buf.length;
    }

    n_buffers = req.count;

    return 0;
}

static void start_streaming() {
    struct v4l2_buffer buf;
    int i;

    for (i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            return;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return;
    }
}

static void stop_streaming() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF");
    }
}

static void unmap_buffers() {
    int i;

    for (i = 0; i < n_buffers; ++i) {
        munmap(buffers[i].start, buffers[i].length);
    }
}

static void log_frame_timestamp() {
    struct timespec ts;
    char timestamp[20];

    clock_gettime(CLOCK_MONOTONIC, &ts);
    snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", (long)ts.tv_sec, (long)ts.tv_nsec / 1000);

    FILE *log_file = fopen(FRAME_LOG, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);
}

static void capture_frames() {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int ret;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    while (running) {
        tv.tv_sec = 0;
        tv.tv_usec = 1000000 / FRAMES_PER_SECOND;

        ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret < 0) {
            perror("select");
            break;
        }

        if (ret == 0) {
            continue;
        }

        if (FD_ISSET(fd, &fds)) {
            if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
                perror("VIDIOC_DQBUF");
                break;
            }

            log_frame_timestamp();

            if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                perror("VIDIOC_QBUF");
                break;
            }
        }
    }
}

int main() {
    signal(SIGINT, sigint_handler);

    if ((fd = open(VID_DEV, O_RDWR)) < 0) {
        perror("open");
        return -1;
    }

    if (init_video() < 0) {
        close(fd);
        return -1;
    }

    start_streaming();

    capture_frames();

    stop_streaming();
    unmap_buffers();

    close(fd);

    return 0;
}

