    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req.count < BUFFER_COUNT) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    for (i = 0; i < req.count; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i].start == MAP_FAILED) {
            perror("mmap");
            return -1;
        }

        buffers[i].length = buf.length;
    }

    n_buffers = req.count;

    return 0;
}

static void start_streaming() {
    struct v4l2_buffer buf;
    int i;

    for (i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            return;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return;
    }
}

static void stop_streaming() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF");
    }
}

static void unmap_buffers() {
    int i;

    for (i = 0; i < n_buffers; ++i) {
        munmap(buffers[i].start, buffers[i].length);
    }
}

static void log_frame_timestamp() {
    struct timespec ts;
    char timestamp[20];

    clock_gettime(CLOCK_MONOTONIC, &ts);
    snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", (long)ts.tv_sec, (long)ts.tv_nsec / 1000);

    FILE *log_file = fopen(FRAME_LOG, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);
}

static void capture_frames() {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int ret;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    while (running) {
        tv.tv_sec = 0;
        tv.tv_usec = 1000000 / FRAMES_PER_SECOND;

        ret = select(fd + 1, &fds, NULL, NULL, &tv);
        if (ret < 0) {
            perror("select");
            break;
        }

        if (ret == 0) {
            continue;
        }

        if (FD_ISSET(fd, &fds)) {
            if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
                perror("VIDIOC_DQBUF");
                break;
            }

            log_frame_timestamp();

            if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
                perror("VIDIOC_QBUF");
                break;
            }
        }
    }
}

int main() {
    signal(SIGINT, sigint_handler);

    if ((fd = open(VID_DEV, O_RDWR)) < 0) {
        perror("open");
        return -1;
    }

    if (init_video() < 0) {
        close(fd);
        return -1;
    }

    start_streaming();

    capture_frames();

    stop_streaming();
    unmap_buffers();

    close(fd);

    return 0;
}
