void handle_signal(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for servos and buttons
    pan_line = gpiod_chip_get_line(chip, PAN_GPIO);
    tilt_line = gpiod_chip_get_line(chip, TILT_GPIO);
    int pan_button_line = gpiod_chip_get_line(chip, PAN_BUTTON);
    int tilt_button_line = gpiod_chip_get_line(chip, TILT_BUTTON);
    int pan_left_button_line = gpiod_chip_get_line(chip, PAN_LEFT_BUTTON);
    int pan_right_button_line = gpiod_chip_get_line(chip, PAN_RIGHT_BUTTON);

    if (!pan_line || !tilt_line || !pan_button_line || !tilt_button_line || !pan_left_button_line || !pan_right_button_line) {
        perror("Failed to request GPIO lines");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set line direction
    gpiod_line_request_input(pan_button_line);
    gpiod_line_request_input(tilt_button_line);
    gpiod_line_request_input(pan_left_button_line);
    gpiod_line_request_input(pan_right_button_line);

    // Set line bias to pull-up
    gpiod_line_set_bias(pan_button_line, GPIOD_LINE_BIAS_PULL_UP);
    gpiod_line_set_bias(tilt_button_line, GPIOD_LINE_BIAS_PULL_UP);
    gpiod_line_set_bias(pan_left_button_line, GPIOD_LINE_BIAS_PULL_UP);
    gpiod_line_set_bias(pan_right_button_line, GPIOD_LINE_BIAS_PULL_UP);

    // Set line event detection
    gpiod_line_event_config(pan_button_line, GPIOD_LINE_EVENT_RISING_EDGE, true);
    gpiod_line_event_config(tilt_button_line, GPIOD_LINE_EVENT_RISING_EDGE, true);
    gpiod_line_event_config(pan_left_button_line, GPIOD_LINE_EVENT_RISING_EDGE, true);
    gpiod_line_event_config(pan_right_button_line, GPIOD_LINE_EVENT_RISING_EDGE, true);

    // Initialize PWM
    gpiod_line_request_output(pan_line, "pan_servo", 0);
    gpiod_line_request_output(tilt_line, "tilt_servo", 0);

    // Set initial positions
    pan_position = MID_POSITION;
    tilt_position = MID_POSITION;
    pan_duty = (pan_position - PWM_DUTY_MIN) * 100 / (PWM_DUTY_MAX - PWM_DUTY_MIN);
    tilt_duty = (tilt_position - PWM_DUTY_MIN) * 100 / (PWM_DUTY_MAX - PWM_DUTY_MIN);

    gpiod_line_set_value(pan_line, pan_duty / 100);
    gpiod_line_set_value(tilt_line, tilt_duty / 100);

