                } else if (event.line == tilt_button_line) {
                    tilt_position = (tilt_position + POSITION_INCREMENT) % (PWM_DUTY_MAX - PWM_DUTY_MIN) + PWM_DUTY_MIN;
                }
            }
        }

        ret = gpiod_line_event_wait(tilt_button_line, &event);
        if (ret == 0) {
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                if (event.line == pan_button_line) {
                    pan_position = (pan_position - POSITION_INCREMENT) % (PWM_DUTY_MAX - PWM_DUTY_MIN) + PWM_DUTY_MIN;
                } else if (event.line == tilt_button_line) {
                    tilt_position = (tilt_position - POSITION_INCREMENT) % (PWM_DUTY_MAX - PWM_DUTY_MIN) + PWM_DUTY_MIN;
                }
            }
        }

        ret = gpiod_line_event_wait(pan_left_button_line, &event);
        if (ret == 0) {
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                pan_position = (pan_position - POSITION_INCREMENT) % (PWM_DUTY_MAX - PWM_DUTY_MIN) + PWM_DUTY_MIN;
            }
        }

        ret = gpiod_line_event_wait(pan_right_button_line, &event);
        if (ret == 0) {
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                pan_position = (pan_position + POSITION_INCREMENT) % (PWM_DUTY_MAX - PWM_DUTY_MIN) + PWM_DUTY_MIN;
            }
        }

        // Update PWM duty
        pan_duty = (pan_position - PWM_DUTY_MIN) * 100 / (PWM_DUTY_MAX - PWM_DUTY_MIN);
        tilt_duty = (tilt_position - PWM_DUTY_MIN) * 100 / (PWM_DUTY_MAX - PWM_DUTY_MIN);

        gpiod_line_set_value(pan_line, pan_duty / 100);
        gpiod_line_set_value(tilt_line, tilt_duty / 100);

        usleep(50000);  // 50 ms delay
    }

    // Clean up
    gpiod_line_release(pan_line);
    gpiod_line_release(tilt_line);
    gpiod_line_release(pan_button_line);
    gpiod_line_release(tilt_button_line);
    gpiod_line_release(pan_left_button_line);
    gpiod_line_release(pan_right_button_line);
    gpiod_chip_close(chip);

    return 0;
