    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (req.count < QUEUE_SIZE) {
        fprintf(stderr, "Insufficient buffers\n");
        return -1;
