        perror("VIDIOC_STREAMON");
        return;
    }
}

static void stop_streaming() {
    struct v4l2_buf_type type;

    type.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF");
        return;
    }
}

