    enum_framesizes.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &enum_framesizes) >= 0) {
        if (enum_framesizes.type == V4L2_BUF_TYPE_VIDEO_CAPTURE) {
            frame_size.index = 0;
            while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frame_size) >= 0) {
                printf("Supported resolution: %ux%u\n", frame_size.pixel_width, frame_size.pixel_height);
                frame_size.index++;
            }
        }
        enum_framesizes.index++;
    }

    // Enumerate supported frame intervals
    enum_frameintervals.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    enum_frameintervals.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &enum_frameintervals) >= 0) {
        if (enum_frameintervals.type == V4L2_BUF_TYPE_VIDEO_CAPTURE) {
            frame_interval.index = 0;
            while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frame_interval) >= 0) {
                printf("Supported frame rate: %ux%u\n", frame_interval.pulse_numerator, frame_interval.pulse_denominator);
                frame_interval.index++;
            }
        }
        enum_frameintervals.index++;
    }

    // Query autofocus support
    queryctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) >= 0) {
        focus_supported = 1;
        printf("Autofocus is supported\n");
    } else {
        printf("Autofocus is not supported\n");
    }

    // Close the video device
    close(fd);

    // Exit with a non-zero code on fatal errors
    if (!focus_supported) {
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

