    if (gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set up pull-up for DOWN button\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set up pull-up for LEFT button\n");
        gpioTerminate();
        return 1;
