    if (gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set up pull-up for RIGHT button\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handler
