#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <libcamera/still.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME_MS 50
#define LOG_FILE "/home/pi/motion_capture.log"
#define IMAGE_DIR "/home/pi/images"
#define IMAGE_FORMAT "%Y%m%d_%H%M%S_%3d.jpg"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define IMAGE_TIMEOUT 2000

static int gpiod_chip = -1;
static int gpiod_line = -1;
static FILE *log_file = NULL;

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s - %s\n", timestamp, event);
    fflush(log_file);
}

static void handle_signal(int signum) {
    if (gpiod_chip >= 0) {
        gpiod_chip_close(gpiod_chip);
    }
    if (gpiod_line >= 0) {
        gpiod_line_release(gpiod_line);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

static void setup_gpio() {
    gpiod_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_chip < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpiod_line = gpiod_chip_get_line(gpiod_chip, GPIO_PIN);
    if (gpiod_line < 0) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }

    int flags = GPIOD_LINE_REQUEST_INPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
    int ret = gpiod_line_request_input(gpiod_line, "motion_sensor", flags);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(gpiod_line);
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_FAILURE);
    }
}

static void setup_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

static void capture_image(const char *filename) {
    libcamera::StillCaptureSession session;
    libcamera::StillCaptureRequest request;
    libcamera::StillCaptureResult result;

    request.settings.resolution = {IMAGE_WIDTH, IMAGE_HEIGHT};
    request.settings.quality = IMAGE_QUALITY;
    request.settings.timeout = IMAGE_TIMEOUT;
    request.settings.noPreview = true;

    session.addRequest(&request);
    session.start();

    if (session.waitForResult() != libcamera::Result::Done) {
        fprintf(stderr, "Failed to capture image: %s\n", session.result().error().message().c_str());
        return;
    }

    result = session.result();
    if (result.error().code() != libcamera::Result::Done) {
        fprintf(stderr, "Failed to capture image: %s\n", result.error().message().c_str());
        return;
    }

    if (result.image().save(filename) != libcamera::Result::Done) {
        fprintf(stderr, "Failed to save image: %s\n", result.image().error().message().c_str());
        return;
    }

    log_event("Image captured: " + std::string(filename));
}

static void wait_for_motion() {
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = DEBOUNCE_TIME_MS * 1000000;

    while (1) {
        int value = gpiod_line_get_value(gpiod_line);
        if (value == 0) {
            struct timespec start = {0, 0};
            struct timespec end = {0, 0};
            clock_gettime(CLOCK_MONOTONIC, &start);

            while (1) {
                value = gpiod_line_get_value(gpiod_line);
                if (value != 0) {
                    break;
                }
                clock_gettime(CLOCK_MONOTONIC, &end);
                if (end.tv_sec - start.tv_sec > 1) {
                    break;
                }
            }

            if (value == 0) {
                continue;
            }
        }

        char filename[100];
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        strftime(filename, sizeof(filename), IMAGE_FORMAT, tm, 0);
        capture_image(filename);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_logging();

    wait_for_motion();

    return 0;
}

