#include <linux/videodev2.h>
#include <signal.h>
#include <sys/mman.h>
#include <errno.h>

#define VIDIOC_QUERYCAP 0xC0105500
#define VIDIOC_REQBUFS 0xC0105501
#define VIDIOC_QUERYBUF 0xC0105502
#define VIDIOC_QBUF 0xC0105504
#define VIDIOC_DQBUF 0xC0105505
#define VIDIOC_STREAMON 0xC0105506
#define VIDIOC_STREAMOFF 0xC0105507

#define YUYV_WIDTH 640
#define YUYV_HEIGHT 480
#define CROPPED_WIDTH 200
#define CROPPED_HEIGHT 150

struct v4l2_capability cap;
struct v4l2_format fmt;
struct v4l2_requestbuffers req;
struct v4l2_buffer buf;
struct v4l2_buffer *buffers;
int fd;

void sig_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (buffers) {
            for (int i = 0; i < req.count; i++) {
                if (buffers[i].bytesused) {
                    munmap(buffers[i].m.offset, buffers[i].length);
                }
            }
            free(buffers);
        }
        close(fd);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    fd = open("/dev/video0", O_RDWR);
    if (fd == -1) {
        perror("Failed to open /dev/video0");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP failed");
        close(fd);
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        close(fd);
        exit(EXIT_FAILURE);
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = YUYV_WIDTH;
    fmt.fmt.pix.height = YUYV_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT failed");
        close(fd);
        exit(EXIT_FAILURE);
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS failed");
        close(fd);
        exit(EXIT_FAILURE);
    }

    buffers = (struct v4l2_buffer *)malloc(req.count * sizeof(struct v4l2_buffer));
    if (!buffers) {
        perror("Failed to allocate buffers");
        close(fd);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < req.count; i++) {
        memset(&buffers[i], 0, sizeof(buffers[i]));
        buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffers[i].memory = V4L2_MEMORY_MMAP;
        buffers[i].index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buffers[i]) == -1) {
            perror("VIDIOC_QUERYBUF failed");
            close(fd);
            free(buffers);
            exit(EXIT_FAILURE);
        }

        buffers[i].m.offset = buffers[i].m.offset + buffers[i].length;

        if (mmap(buffers[i].m.offset, buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buffers[i].m.offset) == MAP_FAILED) {
            perror("mmap failed");
            close(fd);
            free(buffers);
            exit(EXIT_FAILURE);
        }
    }

    if (ioctl(fd, VIDIOC_STREAMON, &req.type) == -1) {
        perror("VIDIOC_STREAMON failed");
        close(fd);
        free(buffers);
        munmap(buffers[0].m.offset, buffers[0].length);
        exit(EXIT_FAILURE);
    }

    struct timeval start, end;
    gettimeofday(&start, NULL);

    while (1) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        if (select(fd + 1, &fds, NULL, NULL, NULL) == -1) {
            if (errno == EINTR) {
                continue;
            }
            perror("select failed");
            close(fd);
            free(buffers);
            munmap(buffers[0].m.offset, buffers[0].length);
            exit(EXIT_FAILURE);
        }

        if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
            perror("VIDIOC_DQBUF failed");
            close(fd);
            free(buffers);
            munmap(buffers[0].m.offset, buffers[0].length);
            exit(EXIT_FAILURE);
        }

        if (buf.bytesused != fmt.fmt.pix.width * fmt.fmt.pix.height * 2) {
            fprintf(stderr, "Buffer size mismatch\n");
            close(fd);
            free(buffers);
            munmap(buffers[0].m.offset, buffers[0].length);
            exit(EXIT_FAILURE);
        }

        if (buf.type != V4L2_BUF_TYPE_VIDEO_CAPTURE) {
            fprintf(stderr, "Buffer type mismatch\n");
            close(fd);
            free(buffers);
            munmap(buffers[0].m.offset, buffers[0].length);
            exit(EXIT_FAILURE);
        }

        gettimeofday(&end, NULL);
        long elapsed = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec);
        if (elapsed > 2000000) {
            fprintf(stderr, "Timeout waiting for frame\n");
            close(fd);
            free(buffers);
            munmap(buffers[0].m.offset, buffers[0].length);
            exit(EXIT_FAILURE);
        }

        break;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF failed");
        close(fd);
        free(buffers);
        munmap(buffers[0].m.offset, buffers[0].length);
        exit(EXIT_FAILURE);
    }

    FILE *output = fopen("cropped.yuv", "wb");
    if (!output) {
        perror("Failed to open cropped.yuv");
        close(fd);
        free(buffers);
        munmap(buffers[0].m.offset, buffers[0].length);
        exit(EXIT_FAILURE);
    }

    unsigned char *src = (unsigned char *)buffers[0].m.offset;
    unsigned char *dst = (unsigned char *)malloc(CROPPED_WIDTH * CROPPED_HEIGHT * 2);
    if (!dst) {
        perror("Failed to allocate cropped buffer");
        fclose(output);
        close(fd);
        free(buffers);
        munmap(buffers[0].m.offset, buffers[0].length);
        exit(EXIT_FAILURE);
    }

    for (int y = 50; y < 50 + CROPPED_HEIGHT; y++) {
        for (int x = 100; x < 100 + CROPPED_WIDTH; x++) {
            int src_index = (y * YUYV_WIDTH + x) * 2;
            int dst_index = (y - 50) * CROPPED_WIDTH + (x - 100) * 2;
            dst[dst_index] = src[src_index];
            dst[dst_index + 1] = src[src_index + 1];
        }
    }

    if (fwrite(dst, 1, CROPPED_WIDTH * CROPPED_HEIGHT * 2, output) != CROPPED_WIDTH * CROPPED_HEIGHT * 2) {
        perror("fwrite failed");
        fclose(output);
        free(dst);
        close(fd);
        free(buffers);
        munmap(buffers[0].m.offset, buffers[0].length);
        exit(EXIT_FAILURE);
    }

    free(dst);
    fclose(output);

    close(fd);
    free(buffers);
    munmap(buffers[0].m.offset, buffers[0].length);

    return EXIT_SUCCESS;
}

