#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define PAN_GPIO 17
#define TILT_GPIO 18
#define PWM_FREQ 50
#define PWM_MIN 500
#define PWM_MAX 2500
#define PAN_NEUTRAL 90
#define TILT_NEUTRAL 90
#define PAN_MIN 0
#define PAN_MAX 180
#define TILT_MIN 0
#define TILT_MAX 180

static int pan_angle = PAN_NEUTRAL;
static int tilt_angle = TILT_NEUTRAL;
static int running = 1;

void handle_signal(int signum) {
    if (signum == SIGINT || (signum == SIGTERM && running)) {
        running = 0;
        gpioPWM(PAN_GPIO, 0);
        gpioPWM(TILT_GPIO, 0);
        gpioTerminate();
        printf("Exiting...\n");
        exit(0);
    }
}

void set_servo_angle(int gpio, int angle) {
    if (angle < PAN_MIN || angle > PAN_MAX || angle < TILT_MIN || angle > TILT_MAX) {
        fprintf(stderr, "Error: Angle out of range for GPIO %d\n", gpio);
        return;
    }
    int pulse_width = PWM_MIN + (angle - PAN_MIN) * (PWM_MAX - PWM_MIN) / (PAN_MAX - PAN_MIN);
    if (gpioPWM(gpio, pulse_width) < 0) {
        fprintf(stderr, "Error: Failed to set PWM for GPIO %d\n", gpio);
    }
}

void process_input(char input) {
    switch (input) {
        case 'w': // Up
            if (pan_angle < PAN_MAX) {
                pan_angle += 5;
                set_servo_angle(PAN_GPIO, pan_angle);
            }
            break;
        case 's': // Down
            if (pan_angle > PAN_MIN) {
                pan_angle -= 5;
                set_servo_angle(PAN_GPIO, pan_angle);
            }
            break;
        case 'a': // Left
            if (tilt_angle < TILT_MAX) {
                tilt_angle += 5;
                set_servo_angle(TILT_GPIO, tilt_angle);
            }
            break;
        case 'd': // Right
            if (tilt_angle > TILT_MIN) {
                tilt_angle -= 5;
                set_servo_angle(TILT_GPIO, tilt_angle);
            }
            break;
        case 'q': // Quit
            running = 0;
            gpioPWM(PAN_GPIO, 0);
            gpioPWM(TILT_GPIO, 0);
            gpioTerminate();
            printf("Exiting...\n");
            exit(0);
            break;
        default:
            fprintf(stderr, "Invalid input: %c\n", input);
            break;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        return 1;
    }
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);
    gpioPWMFrequency(PAN_GPIO, PWM_FREQ);
    gpioPWMFrequency(TILT_GPIO, PWM_FREQ);
    gpioPWM(PAN_GPIO, 0);
    gpioPWM(TILT_GPIO, 0);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        char input;
        if (fgets(&input, 2, stdin) != NULL) {
            input = tolower(input[0]);
            process_input(input);
            usleep(100000); // 100 ms delay
        }
    }

    return 0;
}

