#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <string.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define GPIO_PIN 17
#define LCD_ADDRESS 0x27
#define LCD_ROWS 2
#define LCD_COLS 16
#define I2C_BUS 1
#define PULSE_PER_LITER 450
#define LOG_INTERVAL 1000000 // 1 second in microseconds
#define LCD_UPDATE_INTERVAL 10000000 // 10 seconds in microseconds

static volatile int running = 1;
static volatile int pulse_count = 0;
static volatile double total_volume = 0.0;
static volatile double current_flow_rate = 0.0;
static volatile struct timespec last_log_time;
static volatile struct timespec last_lcd_update_time;

void handle_sigint(int signum) {
    running = 0;
    printf("Shutting down...\n");
}

void handle_sigterm(int signum) {
    running = 0;
    printf("Shutting down...\n");
}

void log_flow_rate() {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    if (difftime(current_time.tv_sec, last_log_time.tv_sec) >= 1) {
        current_flow_rate = pulse_count / (1.0 * LOG_INTERVAL / 1000000);
        total_volume += current_flow_rate / 60.0; // Convert to liters per minute
        printf("Current Flow Rate: %.2f L/min\n", current_flow_rate);
        printf("Total Volume: %.2f L\n", total_volume);
        pulse_count = 0;
        last_log_time = current_time;
    }
}

void update_lcd() {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    if (difftime(current_time.tv_sec, last_lcd_update_time.tv_sec) >= 10) {
        char buffer[128];
        snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min\nVol: %.2f L", current_flow_rate, total_volume);
        int fd = open("/dev/i2c-1", O_RDWR);
        if (fd < 0) {
            perror("Failed to open I2C bus");
            return;
        }

        if (ioctl(fd, I2C_SLAVE, LCD_ADDRESS) < 0) {
            perror("Failed to select I2C device");
            close(fd);
            return;
        }

        for (int i = 0; i < strlen(buffer); i++) {
            if (write(fd, &buffer[i], 1) != 1) {
                perror("Failed to write to LCD");
                close(fd);
                return;
            }
        }

        close(fd);
        last_lcd_update_time = current_time;
    }
}

void gpio_init() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    gpioSetAlertFunc(GPIO_PIN, pulse_handler);
}

void pulse_handler(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    gpio_init();

    clock_gettime(CLOCK_MONOTONIC, &last_log_time);
    clock_gettime(CLOCK_MONOTONIC, &last_lcd_update_time);

    while (running) {
        log_flow_rate();
        update_lcd();
        usleep(LOG_INTERVAL);
    }

    gpioTerminate();
    return 0;
}

