#define LCD_COLS 16
#define I2C_BUS 1
#define PULSE_PER_LITER 450
#define LOG_INTERVAL 1000000 // 1 second in microseconds
#define LCD_UPDATE_INTERVAL 10000000 // 10 seconds in microseconds

static volatile int running = 1;
static volatile int pulse_count = 0;
static volatile double total_volume = 0.0;
static volatile double current_flow_rate = 0.0;
static volatile struct timespec last_log_time;
static volatile struct timespec last_lcd_update_time;

void handle_sigint(int signum) {
    running = 0;
    printf("Shutting down...\n");
}

