}

void update_lcd() {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    if (difftime(current_time.tv_sec, last_lcd_update_time.tv_sec) >= 10) {
        char buffer[128];
        snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min\nVol: %.2f L", current_flow_rate, total_volume);
        int fd = open("/dev/i2c-1", O_RDWR);
        if (fd < 0) {
            perror("Failed to open I2C bus");
            return;
        }

        if (ioctl(fd, I2C_SLAVE, LCD_ADDRESS) < 0) {
            perror("Failed to select I2C device");
            close(fd);
            return;
        }

        for (int i = 0; i < strlen(buffer); i++) {
            if (write(fd, &buffer[i], 1) != 1) {
                perror("Failed to write to LCD");
                close(fd);
                return;
