        }

        close(fd);
        last_lcd_update_time = current_time;
    }
}

void gpio_init() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    gpioSetAlertFunc(GPIO_PIN, pulse_handler);
}

void pulse_handler(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    gpio_init();

    clock_gettime(CLOCK_MONOTONIC, &last_log_time);
    clock_gettime(CLOCK_MONOTONIC, &last_lcd_update_time);

