#include <pigpio.h>
#include <wiringPiI2C.h>

#define GPIO_PIN 17
#define LCD_ADDRESS 0x27
#define LCD_ROWS 2
#define LCD_COLS 16
#define CALIBRATION_FACTOR 7.5
#define INTERVAL 1000000 // 1 second in microseconds

static int gpiopin;
static int lcd_fd;
static int pulse_count = 0;
static int running = 1;

void handle_signal(int sig) {
    running = 0;
    gpioTerminate();
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x00); // Clear display
    printf("Program terminated.\n");
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    // Set GPIO pin mode to input with pull-up
    if (gpioSetMode(gpio_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(gpio_pin, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up.\n");
        gpioTerminate();
        return 1;
    }

    // Set up alert for GPIO pin
    if (gpioAlertSet(gpio_pin, 0, 0, pulse_count) < 0) {
        fprintf(stderr, "Failed to set alert.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C bus
    lcd_fd = wiringPiI2CSetup(1);
    if (lcd_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C bus.\n");
        gpioTerminate();
        return 1;
    }

