        wiringPiI2CWriteReg8(lcd_fd, 0x47, 't');
        wiringPiI2CWriteReg8(lcd_fd, 0x48, 'e');
        wiringPiI2CWriteReg8(lcd_fd, 0x49, ':');
        wiringPiI2CWriteReg8(lcd_fd, 0x4A, ' ');

        // Set cursor to second line
        wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x40);

        // Display flow rate
        char buffer[10];
        snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);
        for (int i = 0; i < strlen(buffer); i++) {
            wiringPiI2CWriteReg8(lcd_fd, 0x40 + i, buffer[i]);
