        // Reset pulse count
        pulse_count = 0;
    }

    // Clean up
    gpioTerminate();
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x00); // Clear display
    printf("Program terminated.\n");

    return 0;
}

