#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_ROWS 8
#define NUM_COLS 8
#define GPIO_BASE 17
#define GPIO_DELAY 800

static gpiod_chip *chip;
static gpiod_line *rows[NUM_ROWS];
static gpiod_line *cols[NUM_COLS];

void handle_sigint(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines for rows and columns
    for (int i = 0; i < NUM_ROWS; i++) {
        rows[i] = gpiod_chip_get_line(chip, GPIO_BASE + i);
        if (!rows[i]) {
            perror("Failed to get row line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(rows[i], "row", 0)) {
            perror("Failed to request row line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        cols[i] = gpiod_chip_get_line(chip, GPIO_BASE + NUM_ROWS + i);
        if (!cols[i]) {
            perror("Failed to get column line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        if (gpiod_line_request_output(cols[i], "column", 0)) {
            perror("Failed to request column line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Define wave patterns
    int wave_left[NUM_ROWS] = {0, 1, 2, 3, 4, 5, 6, 7};
    int wave_right[NUM_ROWS] = {7, 6, 5, 4, 3, 2, 1, 0};

    // Main loop for wave animation
    while (1) {
        // Left-to-right wave
        for (int i = 0; i < NUM_ROWS; i++) {
            for (int j = 0; j < NUM_COLS; j++) {
                gpiod_line_set_value(cols[j], 0); // Turn off all columns
                gpiod_line_set_value(rows[wave_left[i]], 1); // Turn on the current row
                usleep(GPIO_DELAY); // Delay for scan
            }
        }

        // Right-to-left wave
        for (int i = 0; i < NUM_ROWS; i++) {
            for (int j = 0; j < NUM_COLS; j++) {
                gpiod_line_set_value(cols[j], 0); // Turn off all columns
                gpiod_line_set_value(rows[wave_right[i]], 1); // Turn on the current row
                usleep(GPIO_DELAY); // Delay for scan
            }
        }
    }

    // Clean up
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_release(rows[i]);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line_release(cols[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

