        for (int i = 0; i < NUM_ROWS; i++) {
            for (int j = 0; j < NUM_COLS; j++) {
                gpiod_line_set_value(cols[j], 0); // Turn off all columns
                gpiod_line_set_value(rows[wave_right[i]], 1); // Turn on the current row
                usleep(GPIO_DELAY); // Delay for scan
            }
        }
    }

    // Clean up
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_release(rows[i]);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line_release(cols[i]);
    }
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
