#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4C
#define DISTANCE_REG 0x0D
#define LOG_FILE "depth_log.csv"

int main() {
    int i2c_handle;
    int distance;
    FILE *log_file;
    struct timespec ts;
    char buffer[3];
    char log_line[100];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d, address 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if file is newly created
    if (fseek(log_file, 0, SEEK_END) == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
    }

    // Main loop
    while (1) {
        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &ts);

        // Write register address
        if (i2cWriteByte(i2c_handle, DISTANCE_REG) < 0) {
            fprintf(stderr, "Failed to write register address 0x%02X\n", DISTANCE_REG);
            i2cClose(i2c_handle);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        // Read two bytes in big-endian order
        if (i2cReadBytes(i2c_handle, buffer, 2) < 0) {
            fprintf(stderr, "Failed to read distance register\n");
            i2cClose(i2c_handle);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        // Convert two bytes to 16-bit distance
        distance = (buffer[0] << 8) | buffer[1];

        // Log timestamped distance reading
        snprintf(log_line, sizeof(log_line), "%ld,%d\n", ts.tv_sec * 1000000 + ts.tv_nsec / 1000, distance);
        if (fprintf(log_file, log_line) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            i2cClose(i2c_handle);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        // Sleep for 100 milliseconds
        usleep(100000);
    }

    // Handle SIGINT for graceful shutdown
    signal(SIGINT, handle_sigint);

    // Close I2C handle and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

void handle_sigint(int signum) {
    printf("Caught SIGINT, shutting down...\n");
    exit(0);
}

