#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define SI1145_ADDR 0x60
#define SI1145_PART_ID_REG 0x00
#define SI1145_COMMAND_REG 0x18
#define SI1145_MEAS_RATE_100MS 0x00
#define SI1145_CLEAR_IRQ 0x01

void log_reading(const char *timestamp, int proximity, int ambient) {
    FILE *log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "%s, %d, %d\n", timestamp, proximity, ambient);
    fclose(log_file);
}

void sigint_handler(int signum) {
    gpioTerminate();
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Read PART ID register to verify sensor presence
    uint8_t part_id;
    if (i2cReadReg8(i2c_handle, SI1145_PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART ID register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Sensor is not a Si1145\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Initialize the sensor
    if (i2cWriteReg8(i2c_handle, SI1145_COMMAND_REG, SI1145_MEAS_RATE_100MS | SI1145_CLEAR_IRQ) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec sleep_time = {0, 500000000}; // 500 ms
    time_t now;
    char timestamp[20];
    FILE *log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        // Read proximity and ambient light data
        uint8_t proximity_data[2];
        uint8_t ambient_data[2];
        if (i2cReadReg8(i2c_handle, 0x19, proximity_data) < 0) {
            fprintf(stderr, "Failed to read proximity data\n");
        } else if (i2cReadReg8(i2c_handle, 0x1B, ambient_data) < 0) {
            fprintf(stderr, "Failed to read ambient light data\n");
        } else {
            int proximity = (proximity_data[0] << 8) | proximity_data[1];
            int ambient = (ambient_data[0] << 8) | ambient_data[1];
            log_reading(timestamp, proximity, ambient);
        }

        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

