#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_KEY_REG 0x07
#define CH_LIST_REG 0x4F
#define COMMAND_REG 0x30
#define PS1_DATA_REG 0x18
#define ALS_VIS_DATA_REG 0x22

#define LOG_FILE "biometric_data.log"

int i2c_handle;
FILE *log_file;

void log_data(const char *timestamp, int ps1, int als_vis) {
    fprintf(log_file, "%s, %d, %d\n", timestamp, ps1, als_vis);
    fflush(log_file);
}

void sigint_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpioSetSignalFunc(SIGINT, sigint_handler);

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Verify PART_ID register
    uint8_t part_id;
    if (i2cReadReg8(i2c_handle, PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Invalid PART_ID: 0x%02X\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write HW_KEY to enable sensor
    if (i2cWriteReg8(i2c_handle, HW_KEY_REG, 0x17) < 0) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set CH_LIST to enable PS1 and ALS_VIS channels
    if (i2cWriteReg8(i2c_handle, CH_LIST_REG, 0x0F) < 0) {
        fprintf(stderr, "Failed to set CH_LIST\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure measurement rates
    if (i2cWriteReg8(i2c_handle, COMMAND_REG, 0x06) < 0) {
        fprintf(stderr, "Failed to configure ALS measurement\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteReg8(i2c_handle, COMMAND_REG, 0x07) < 0) {
        fprintf(stderr, "Failed to configure PS measurement\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Log header
    log_data("Timestamp", "PS1", "ALS_VIS");
    fprintf(log_file, "Timestamp, PS1, ALS_VIS\n");
    fflush(log_file);

    // Infinite loop to read and log data
    while (1) {
        // Read PS1 data
        uint8_t ps1_data[2];
        if (i2cReadReg8(i2c_handle, PS1_DATA_REG, &ps1_data[0]) < 0) {
            fprintf(stderr, "Failed to read PS1 data\n");
        }
        if (i2cReadReg8(i2c_handle, PS1_DATA_REG + 1, &ps1_data[1]) < 0) {
            fprintf(stderr, "Failed to read PS1 data\n");
        }
        int ps1 = (ps1_data[0] << 8) | ps1_data[1];

        // Read ALS_VIS data
        uint8_t als_vis_data[2];
        if (i2cReadReg8(i2c_handle, ALS_VIS_DATA_REG, &als_vis_data[0]) < 0) {
            fprintf(stderr, "Failed to read ALS_VIS data\n");
        }
        if (i2cReadReg8(i2c_handle, ALS_VIS_DATA_REG + 1, &als_vis_data[1]) < 0) {
            fprintf(stderr, "Failed to read ALS_VIS data\n");
        }
        int als_vis = (als_vis_data[0] << 8) | als_vis_data[1];

        // Log data
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        log_data(timestamp, ps1, als_vis);

        // Sleep for 1 second
        sleep(1);
    }

    // Close log file and I2C handle
    fclose(log_file);
    i2cClose(i2c_handle);

    // Clean up GPIO
    gpioTerminate();

    return 0;
}

