#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define TIMEOUT_MS 30
#define LOG_FILE "distance_log.txt"
#define MIN_DISTANCE 15
#define MAX_DISTANCE 400

static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    struct timespec trigger_pulse = {0, 10000000}; // 10 microsecond pulse
    struct timespec echo_timeout = {0, TIMEOUT_MS * 1000000}; // 30 ms timeout
    struct timespec start_time, end_time;
    struct timespec pulse_duration;
    double distance;
    FILE *log_file;
    int gpiod_fd;
    int trigger_gpio;
    int echo_gpio;
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open libgpiod context
    gpiod_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines
    trigger_gpio = gpiod_chip_get_line(gpiod_fd, TRIGGER_PIN);
    echo_gpio = gpiod_chip_get_line(gpiod_fd, ECHO_PIN);
    if (trigger_gpio < 0 || echo_gpio < 0) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(gpiod_fd);
        exit(EXIT_FAILURE);
    }

    // Request output and input modes
    ret = gpiod_line_request_output(trigger_gpio, "trigger", 0);
    if (ret < 0) {
        perror("Failed to request trigger GPIO");
        gpiod_line_release(trigger_gpio);
        gpiod_chip_close(gpiod_fd);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(echo_gpio, "echo");
    if (ret < 0) {
        perror("Failed to request echo GPIO");
        gpiod_line_release(trigger_gpio);
        gpiod_chip_close(gpiod_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(trigger_gpio);
        gpiod_line_release(echo_gpio);
        gpiod_chip_close(gpiod_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Generate 10 microsecond trigger pulse
        ret = gpiod_line_set_value(trigger_gpio, 1);
        if (ret < 0) {
            perror("Failed to set trigger GPIO high");
            goto cleanup;
        }
        nanosleep(&trigger_pulse, NULL);
        ret = gpiod_line_set_value(trigger_gpio, 0);
        if (ret < 0) {
            perror("Failed to set trigger GPIO low");
            goto cleanup;
        }

        // Wait for echo pulse
        ret = gpiod_line_event_wait(echo_gpio, &echo_timeout, &start_time);
        if (ret < 0) {
            if (ret == -EAGAIN) {
                fprintf(log_file, "%s,Error: Echo timeout\n", asctime(gmtime(&time(NULL))));
            } else {
                perror("Failed to wait for echo event");
            }
            goto cleanup;
        }

        // Measure echo pulse width
        ret = gpiod_line_event_read(echo_gpio, &end_time);
        if (ret < 0) {
            perror("Failed to read echo event");
            goto cleanup;
        }

        // Calculate pulse duration
        pulse_duration.tv_sec = end_time.tv_sec - start_time.tv_sec;
        pulse_duration.tv_nsec = end_time.tv_nsec - start_time.tv_nsec;
        if (pulse_duration.tv_nsec < 0) {
            pulse_duration.tv_sec--;
            pulse_duration.tv_nsec += 1000000000;
        }

        // Calculate distance
        distance = (pulse_duration.tv_sec + pulse_duration.tv_nsec / 1000000000.0) * 34300.0 / 2.0;

        // Log measurement
        fprintf(log_file, "%s,Distance: %.2f cm\n", asctime(gmtime(&time(NULL))), distance);

        // Check distance and log reminder if necessary
        if (distance < MIN_DISTANCE) {
            fprintf(log_file, "%s,Reminder: Time to water the plant!\n", asctime(gmtime(&time(NULL))));
        }

        // Wait 60 seconds before next measurement
        sleep(60);
    }

cleanup:
    // Release GPIO lines and close log file
    gpiod_line_release(trigger_gpio);
    gpiod_line_release(echo_gpio);
    fclose(log_file);
    gpiod_chip_close(gpiod_fd);

    return 0;
}

