    if (i2cWriteReg8(i2c_handle, CONTROL_REG, config) < 0) {
        fprintf(stderr, "Failed to write CONTROL register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    config = 0x01;
    if (i2cWriteReg8(i2c_handle, CONFIG2_REG, config) < 0) {
