    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        exit(EXIT_FAILURE);
    }

    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        exit(EXIT_FAILURE);
    }

    csv_file = fopen("color_proximity_log.csv", "w");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        exit(EXIT_FAILURE);
    }

    initialize_sensor();

    while (!should_exit) {
        read_sensor_data();
        usleep(100000); // 100 ms
    }

    fclose(csv_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

