#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define PART_ID_REG 0x00
#define MEAS_RATE0_REG 0x08
#define COMMAND_REG 0x47
#define PS_DATA0_REG 0x24
#define PS_DATA1_REG 0x25
#define CSV_FILE "heartrate.csv"
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd, csv_fd;
    struct i2c_smbus_ioctl_data i2c_data;
    uint8_t part_id;
    uint16_t ps_data0, ps_data1;
    struct timespec ts;
    char timestamp[20];
    char line[100];
    FILE *csv;

    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Read PART_ID register
    i2c_data.read_write = I2C_SMBUS_READ;
    i2c_data.command = PART_ID_REG;
    i2c_data.size = I2C_SMBUS_BYTE;
    if (ioctl(i2c_fd, I2C_SMBUS_IOCTL, &i2c_data) < 0) {
        perror("Failed to read PART_ID register");
        close(i2c_fd);
        return 1;
    }
    part_id = i2c_data.data;

    // Verify PART_ID
    if (part_id != 0x82) {
        fprintf(stderr, "Invalid PART_ID: 0x%02X\n", part_id);
        close(i2c_fd);
        return 1;
    }

    // Configure continuous proximity measurement
    i2c_data.command = MEAS_RATE0_REG;
    i2c_data.data = 0x01; // Set measurement rate to 100 Hz
    if (ioctl(i2c_fd, I2C_SMBUS_IOCTL, &i2c_data) < 0) {
        perror("Failed to write MEAS_RATE0 register");
        close(i2c_fd);
        return 1;
    }

    // Reset/start command
    i2c_data.command = COMMAND_REG;
    i2c_data.data = 0x01; // Start measurement
    if (ioctl(i2c_fd, I2C_SMBUS_IOCTL, &i2c_data) < 0) {
        perror("Failed to write COMMAND register");
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (csv_fd < 0) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read proximity data
        i2c_data.command = PS_DATA0_REG;
        i2c_data.size = I2C_SMBUS_WORD;
        if (ioctl(i2c_fd, I2C_SMBUS_IOCTL, &i2c_data) < 0) {
            fprintf(stderr, "Failed to read PS_DATA0 register\n");
            continue;
        }
        ps_data0 = i2c_data.data;

        i2c_data.command = PS_DATA1_REG;
        i2c_data.size = I2C_SMBUS_WORD;
        if (ioctl(i2c_fd, I2C_SMBUS_IOCTL, &i2c_data) < 0) {
            fprintf(stderr, "Failed to read PS_DATA1 register\n");
            continue;
        }
        ps_data1 = i2c_data.data;

        // Combine data
        uint16_t proximity = (ps_data1 << 8) | ps_data0;

        // Compute placeholder BPM
        // This is a placeholder and should be replaced with actual heart rate calculation
        int bpm = proximity * 100; // Example calculation

        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));

        // Log sample
        snprintf(line, sizeof(line), "%s,%d\n", timestamp, bpm);
        if (write(csv_fd, line, strlen(line)) < 0) {
            perror("Failed to write to CSV file");
        }
        fflush(csv_fd);

        // Sleep for 100 ms
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Close files
    close(csv_fd);
    close(i2c_fd);

    return 0;
}

