#define GPIO_TRIGGER 17
#define TIMEOUT_MS 100

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int signum) {
    exit_flag = 1;
}

void log_distance(unsigned long long timestamp, int distance_mm) {
    fprintf(log_file, "%llu,%d\n", timestamp, distance_mm);
    fflush(log_file);
}

void check_sensor_presence() {
    uint8_t data[1];
    if (i2c_read_byte_data(i2c_handle, 0x01, data) < 0) {
        fprintf(stderr, "Failed to read sensor presence\n");
        exit(EXIT_FAILURE);
    }
    if (data[0] != 0x00) {
        fprintf(stderr, "Sensor not present at address 0x29\n");
        exit(EXIT_FAILURE);
    }
}

void init_sensor() {
    if (i2c_open(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }
    check_sensor_presence();
    if (i2c_write_byte_data(i2c_handle, 0x00, 0x01) < 0) {
        fprintf(stderr, "Failed to start range measurement\n");
        exit(EXIT_FAILURE);
    }
}

void read_distance() {
    uint8_t data[14];
    unsigned long long timestamp = time(NULL) * 1000 + (unsigned long long)clock() / CLOCKS_PER_SEC;
    if (i2c_read_i2c_block_data(i2c_handle, 0x14, data, 14) < 0) {
        fprintf(stderr, "Failed to read distance data\n");
        return;
    }
    int distance_mm = (data[10] << 8) | data[11];
    log_distance(timestamp, distance_mm);
}

void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2c_close(i2c_handle);
    }
    if (gpio_is_initialized()) {
        gpioTerminate();
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(GPIO_TRIGGER, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpioSetPullUpDown(GPIO_TRIGGER, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO pull-up\n");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (gpioSetAlertFunc(GPIO_TRIGGER, handle_sigint) < 0) {
        fprintf(stderr, "Failed to set GPIO alert function\n");
        cleanup();
        exit(EXIT_FAILURE);
