    log_file = fopen("distance_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        exit(EXIT_FAILURE);
    }
    init_sensor();
    while (!exit_flag) {
        if (gpioWaitForEdge(GPIO_TRIGGER, PI_FALLING_EDGE, TIMEOUT_MS * 1000) < 0) {
            fprintf(stderr, "Failed to wait for edge\n");
            continue;
        }
        read_distance();
    }
    cleanup();
    return 0;
