#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x45
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define SAMPLE_INTERVAL_MS 200
#define LOG_FILE "distance_log.txt"
#define BUFFER_SIZE 64

static volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN pull-up\n");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDRESS);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct timespec sleep_time = {0, SAMPLE_INTERVAL_MS * 1000000};
    struct timespec remaining_time;
    time_t now;
    char timestamp[BUFFER_SIZE];

    signal(SIGINT, handle_sigint);

    while (!stop) {
        now = time(NULL);
        strftime(timestamp, BUFFER_SIZE, "%Y-%m-%d %H:%M:%S", localtime(&now));

        gpioWrite(TRIGGER_PIN, 1);
        usleep(1000);
        gpioWrite(TRIGGER_PIN, 0);

        int result = i2cReadWordData(i2c_handle, 0);
        if (result < 0) {
            fprintf(stderr, "I2C read error at address 0x%02X\n", I2C_ADDRESS);
            continue;
        }

        fprintf(log_file, "%s, %d\n", timestamp, result);
        printf("%s, %d\n", timestamp, result);

        nanosleep(&sleep_time, &remaining_time);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

