#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN1 17
#define GPIO_PIN2 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    FILE *log_file;
    struct timespec sleep_time;
    int sensor1, sensor2;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO pins as input
    if (gpioSetMode(GPIO_PIN1, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GPIO_PIN2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    while (keep_running) {
        // Read sensor values
        sensor1 = gpioRead(GPIO_PIN1);
        sensor2 = gpioRead(GPIO_PIN2);

        // Log the readings with a timestamp
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, "%s, %d, %d\n", timestamp, sensor1, sensor2);

        // Sleep for the specified interval
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000;
        nanosleep(&sleep_time, NULL);
    }

    // Close log file
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();

    return EXIT_SUCCESS;
}

