#include <signal.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x6A
#define LED_PIN 17
#define LOG_FILE "distance_log.txt"
#define INTERVAL_MS 100

static volatile sig_atomic_t quit = 0;

void handle_signal(int sig) {
    quit = 1;
}

int main() {
    int i2c_handle;
    int gpio;
    struct timespec sleep_time;
    char timestamp[20];
    float distance;
    FILE *log_file;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up I2C handle
    i2c_handle = i2cOpen(1, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x6A\n");
        gpioTerminate();
        return 1;
    }

    // Set up LED pin
    gpio = gpioGetMode(LED_PIN);
    if (gpio != PI_OUTPUT) {
        gpioSetMode(LED_PIN, PI_OUTPUT);
    }

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!quit) {
        // Read distance from sensor
        if (i2cReadWordData(i2c_handle, 0x00) < 0) {
            fprintf(stderr, "I2C read error\n");
            break;
        }

        // Convert distance to centimeters
        distance = (float)i2cReadWordData(i2c_handle, 0x02) / 10.0;

        // Log distance with timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);

        // Turn on LED if distance is below 20 cm
        if (distance < 20.0) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        // Sleep for 100 ms
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = INTERVAL_MS * 1000000;
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

