#define AMBIENT_LIGHT_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define MAX_RETRIES 3

static volatile sig_atomic_t should_exit = 0;

void handle_sigint(int signum) {
    should_exit = 1;
}

int main() {
    FILE *log_file;
    int i2c_handle;
    uint16_t proximity_data, ambient_light_data;
    struct timespec sleep_time = {0, 500000000}; // 500 ms

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (!should_exit) {
        for (int retry = 0; retry < MAX_RETRIES; retry++) {
            // Read proximity data
            if (i2cReadWordData(i2c_handle, PROXIMITY_REG, &proximity_data) == 0) {
                break;
            } else {
                fprintf(stderr, "Failed to read proximity data from register 0x%02x, retrying...\n", PROXIMITY_REG);
                usleep(1000000); // Wait for 1 second before retrying
            }
        }

        if (should_exit) {
            break;
        }

        for (int retry = 0; retry < MAX_RETRIES; retry++) {
            // Read ambient light data
            if (i2cReadWordData(i2c_handle, AMBIENT_LIGHT_REG, &ambient_light_data) == 0) {
                break;
            } else {
                fprintf(stderr, "Failed to read ambient light data from register 0x%02x, retrying...\n", AMBIENT_LIGHT_REG);
                usleep(1000000); // Wait for 1 second before retrying
            }
        }

        if (should_exit) {
            break;
        }

        // Log the readings
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity_data, ambient_light_data);

        // Sleep for 500 ms
        nanosleep(&sleep_time, NULL);
    }

    // Close log file
    fclose(log_file);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}
