int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <threshold_mm>\n", argv[0]);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpio_handle = gpioExport(LED_PIN, GPIO_OUTPUT);
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);

    if (i2cReadReg8(i2c_handle, WHO_AM_I_REG) != 0x20) {
        fprintf(stderr, "WHO_AM_I register does not match expected value\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        uint16_t distance;
        if (i2cReadReg16(i2c_handle, 0x00) < 0) {
            fprintf(stderr, "Failed to read distance from sensor\n");
            continue;
        }

        distance = (i2cReadReg16(i2c_handle, 0x00) << 8) | i2cReadReg16(i2c_handle, 0x01);

        if (distance < THRESHOLD_MM) {
            led_state = 1;
        } else {
            led_state = 0;
        }

        gpioWrite(gpio_handle, LED_PIN, led_state);

        struct timespec ts = {0, 50000000}; // 50 ms
        nanosleep(&ts, NULL);

        FILE *log_file = fopen("tof_log.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open tof_log.txt for writing\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, "%s, %d mm\n", timestamp, distance);
        fclose(log_file);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

