#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x50
#define CMD_FRAME {0x50, 0x0A, 0x00, 0x01}
#define RESPONSE_FRAME_SIZE 15
#define LOG_FILE "intrusion_log.txt"
#define MAX_SAMPLES 10
#define DELAY_MS 100

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void log_event(int distance_mm) {
    time_t now;
    struct tm *tm_info;
    char timestamp[20];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: Distance: %d mm\n", timestamp, distance_mm);
    fflush(log_file);
}

static void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    int samples[MAX_SAMPLES];
    int distance_mm;
    int sum = 0;
    int i;
    struct timespec sleep_time = {0, DELAY_MS * 1000000};

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Send command frame
        if (write(i2c_fd, CMD_FRAME, sizeof(CMD_FRAME)) != sizeof(CMD_FRAME)) {
            perror("Failed to write command frame");
            continue;
        }

        // Wait for 10 ms
        nanosleep(&sleep_time, NULL);

        // Read response frame
        if (read(i2c_fd, samples, RESPONSE_FRAME_SIZE) != RESPONSE_FRAME_SIZE) {
            perror("Failed to read response frame");
            continue;
        }

        // Validate header
        if (samples[0] != 0x50) {
            fprintf(stderr, "Invalid header in response frame\n");
            continue;
        }

        // Calculate distance
        distance_mm = (samples[11] << 8) | samples[12];

        // Sum distances
        sum += distance_mm;

        // Calculate average distance
        if (i == MAX_SAMPLES - 1) {
            distance_mm = sum / MAX_SAMPLES;
            sum = 0;

            // Log event if distance is less than 1000 mm
            if (distance_mm < 1000) {
                log_event(distance_mm);
            }
        }

        // Increment sample counter
        i = (i + 1) % MAX_SAMPLES;
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

