#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define VL53L0X_I2C_ADDR 0x29
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define RESULT_RANGE_STATUS 0x14
#define SYSTEM_INTERRUPT_CLEAR 0x0B

static volatile sig_atomic_t quit = 0;

void handle_signal(int sig) {
    quit = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2cHandle = i2cOpen(1, VL53L0X_I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify sensor presence
    uint16_t modelId;
    if (i2cReadWordData(i2cHandle, 0xC0, &modelId) < 0) {
        fprintf(stderr, "Failed to read model ID: %s\n", strerror(errno));
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (modelId != 0xEE) {
        fprintf(stderr, "Invalid model ID: 0x%04X\n", modelId);
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec sleepTime = {0, 500000000}; // 500 ms

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!quit) {
        // Start a single-shot ranging measurement
        if (i2cWriteByteData(i2cHandle, SYSRANGE_START, 0x01) < 0) {
            fprintf(stderr, "Failed to start ranging: %s\n", strerror(errno));
            continue;
        }

        // Wait for the interrupt
        uint16_t status;
        while (1) {
            if (i2cReadWordData(i2cHandle, RESULT_INTERRUPT_STATUS, &status) < 0) {
                fprintf(stderr, "Failed to read interrupt status: %s\n", strerror(errno));
                break;
            }
            if (status & 0x01) {
                break;
            }
            if (nanosleep(&sleepTime, NULL) < 0) {
                fprintf(stderr, "Failed to sleep: %s\n", strerror(errno));
                break;
            }
        }

        // Read the distance
        uint16_t distance;
        if (i2cReadWordData(i2cHandle, RESULT_RANGE_STATUS, &distance) < 0) {
            fprintf(stderr, "Failed to read range status: %s\n", strerror(errno));
            continue;
        }

        // Clear the interrupt
        if (i2cWriteByteData(i2cHandle, SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
            fprintf(stderr, "Failed to clear interrupt: %s\n", strerror(errno));
            continue;
        }

        // Print the distance
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        printf("%s Distance: %d mm\n", timestamp, distance);

        // Sleep for 500 ms
        if (nanosleep(&sleepTime, NULL) < 0) {
            fprintf(stderr, "Failed to sleep: %s\n", strerror(errno));
            break;
        }
    }

    i2cClose(i2cHandle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

