        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    while (!quit) {
        if (i2cReadByte(I2C_BUS, I2C_ADDR, IRQ_STATUS_REG) < 0) {
            fprintf(stderr, "Failed to read IRQ status register\n");
            continue;
        }

