            fprintf(stderr, "Failed to read proximity data register\n");
            continue;
        }

        uint8_t msb = i2cReadByte(I2C_BUS, I2C_ADDR, PROXIMITY_DATA_MSB_REG);
        uint8_t lsb = i2cReadByte(I2C_BUS, I2C_ADDR, PROXIMITY_DATA_LSB_REG);

        uint16_t proximity = (msb << 8) | lsb;
        printf("Proximity: %d\n", proximity);

        sleep(0.5);
    }

    i2cClose(I2C_BUS);
    gpioTerminate();
    return 0;
