#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x4C
#define I2C_READ_REG 0x00
#define I2C_READ_LEN 2
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY 1000000 // 1 ms

static int i2c_fd = -1;
static volatile sig_atomic_t should_exit = 0;

void sig_handler(int sig) {
    should_exit = 1;
}

int main() {
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data data;
    uint8_t buffer[I2C_READ_LEN];
    uint16_t distance_mm;
    int retries = 0;
    int ret;

    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open /dev/i2c-1
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify the device responds
    ret = write(i2c_fd, buffer, 1);
    if (ret != 1) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        return 1;
    }

    // Read the distance register
    while (!should_exit) {
        msgs[0].addr = I2C_ADDRESS;
        msgs[0].flags = 0;
        msgs[0].len = I2C_READ_LEN;
        msgs[0].buf = buffer;

        msgs[1].addr = I2C_ADDRESS;
        msgs[1].flags = I2C_M_RD;
        msgs[1].len = 0;

        data.msgs = msgs;
        data.nmsgs = 2;

        ret = ioctl(i2c_fd, I2C_RDWR, &data);
        if (ret < 0) {
            perror("Failed to read from I2C device");
            retries++;
            if (retries >= I2C_RETRY_COUNT) {
                fprintf(stderr, "Failed to read from I2C device after %d retries\n", I2C_RETRY_COUNT);
                close(i2c_fd);
                return 1;
            }
            nanosleep((const struct timespec[]){{0, I2C_RETRY_DELAY}}, NULL);
            continue;
        }

        // Convert the raw value to millimetres
        distance_mm = (buffer[0] << 8) | buffer[1];
        distance_mm *= 0.125;

        // Print the distance
        printf("Distance: %.2f mm\n", distance_mm);

        // Sleep for 500 ms
        nanosleep((const struct timespec[]){{0, 500000}}, NULL);
    }

    // Close the I2C file descriptor
    close(i2c_fd);

    return 0;
}

