This C program uses the Linux I2C userland API to read distance data from a Melexis MLX75030 Time-of-Flight sensor over I2C bus 1. It sets up a signal handler to cleanly exit on Ctrl-C, opens the I2C bus, sets the slave address, verifies the device's presence, reads the distance register, converts the raw value to millimetres, and logs the distance every 500 ms. If the sensor is absent or an I2C read fails, it retries up to three times with a 1 ms delay between retries.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define OPT3101_ADDR 0x44
#define OPT3101_CHANNEL 0
#define I2C_BUS 1
#define LOG_INTERVAL 500000 // 500 ms

static volatile sig_atomic_t quit = 0;

void handle_sigint(int sig) {
    quit = 1;
}

int main() {
    int i2c_handle;
    uint8_t data[3];
    uint16_t distance;
    uint8_t ambient_light;
    uint8_t error_flags;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Request I2C handle
    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, OPT3101_ADDR);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (!quit) {
        // Read distance data
        if (i2cReadData(i2c_handle, OPT3101_CHANNEL, data, 3) < 0) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        // Extract distance and ambient light data
        distance = (data[0] << 8) | data[1];
        ambient_light = data[2];

        // Read error flags
        if (i2cReadData(i2c_handle, 0x01, &error_flags, 1) < 0) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        // Log data
        printf("Distance: %d mm, Ambient Light: %d, Error Flags: 0x%02X\n", distance, ambient_light, error_flags);

        // Sleep for 500 ms
        usleep(LOG_INTERVAL);
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

