#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define MAX_PULSE_US 38000
#define TIMEOUT_US 200000
#define LOG_INTERVAL 1000000

static volatile int running = 1;
static volatile int echo_rising = 0;
static volatile int echo_falling = 0;
static volatile int pulse_us = 0;

void handle_signal(int sig) {
    running = 0;
    gpioTerminate();
    printf("Program terminated by signal %d\n", sig);
    exit(EXIT_SUCCESS);
}

void log_distance(double distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    printf("%ld.%09ld: Distance: %.2f cm\n", (long)ts.tv_sec, (long)ts.tv_nsec / 1000, distance);
}

void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    usleep(10);
    gpioWrite(TRIGGER_PIN, 0);
}

void read_echo() {
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_UP);

    while (!echo_rising) {
        if (gpioRead(ECHO_PIN) == 1) {
            echo_rising = 1;
        }
    }

    long start = gpioTick();

    while (echo_rising) {
        if (gpioRead(ECHO_PIN) == 0) {
            echo_rising = 0;
        }
    }

    long end = gpioTick();

    pulse_us = end - start;

    if (pulse_us <= 0 || pulse_us > MAX_PULSE_US) {
        printf("Invalid pulse duration: %ld us\n", pulse_us);
        return;
    }

    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_UP);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        trigger_pulse();
        read_echo();

        if (pulse_us > 0) {
            double distance = (pulse_us * 0.0343) / 2.0;
            log_distance(distance);
        }

        usleep(LOG_INTERVAL);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

