#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define UART_BAUDRATE B115200
#define UART_TIMEOUT 1000
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0
#define LOG_FILE "intrusion_log.csv"

static int uart_fd;
static int gpio_led;
static FILE *log_file;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        close(uart_fd);
        gpioTerminate();
        fclose(log_file);
        printf("Exiting...\n");
        exit(0);
    }
}

void log_intrusion(double distance) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d,%H:%M:%S", tm);
    fprintf(log_file, "%s,%f\n", timestamp, distance);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        return 1;
    }
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    if ((uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY)) == -1) {
        perror("Failed to open UART device");
        gpioTerminate();
        return 1;
    }
    fcntl(uart_fd, F_SETFL, 0);

    struct termios options;
    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, UART_BAUDRATE);
    cfsetospeed(&options, UART_BAUDRATE);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag |= CREAD | CLOCAL;
    options.c_lflag &= ~ICANON;
    options.c_lflag &= ~ECHO;
    options.c_lflag &= ~ECHOE;
    options.c_lflag &= ~ECHONL;
    options.c_lflag &= ~ISIG;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;
    tcsetattr(uart_fd, TCSANOW, &options);

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
