        close(uart_fd);
        gpioTerminate();
        fclose(log_file);
        printf("Exiting...\n");
        exit(0);
    }
}

void log_intrusion(double distance) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d,%H:%M:%S", tm);
    fprintf(log_file, "%s,%f\n", timestamp, distance);
    fflush(log_file);
}

