#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line, *buzzer_line;
    int sensor_value, buzzer_value;
    char timestamp[20];
    FILE *log_file;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Failed to request sensor line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to request buzzer line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set line direction
    if (gpiod_line_request_input(sensor_line, "obstacle_sensor") < 0) {
        perror("Failed to set sensor line direction");
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(buzzer_line, "obstacle_buzzer", 0) < 0) {
        perror("Failed to set buzzer line direction");
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read sensor value
        sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value < 0) {
            perror("Failed to read sensor value");
            break;
        }

        // Get current time
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        // Log state transition
        if (sensor_value == 0) {
            fprintf(log_file, "%s: Obstacle detected\n", timestamp);
            buzzer_value = 1;
        } else {
            fprintf(log_file, "%s: Obstacle removed\n", timestamp);
            buzzer_value = 0;
        }

        // Write buzzer value
        if (gpiod_line_set_value(buzzer_line, buzzer_value) < 0) {
            perror("Failed to write buzzer value");
            break;
        }

        // Sleep for poll interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Close log file
    fclose(log_file);

    // Release lines and close chip
    gpiod_line_release(sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);

    return 0;
}

