#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define GPIO_ALERT 17
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_MS 100

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    FILE *log_file;
    struct timespec sleep_time;
    uint16_t distance;
    char timestamp[20];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up GPIO alert
    if (gpioSetMode(GPIO_ALERT, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for alert\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up I2C bus
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!should_exit) {
        // Check for signal-requested shutdown
        if (should_exit) {
            break;
        }

        // Read distance from sensor
        if (i2cReadReg16(I2C_BUS, 0x31, &distance) < 0) {
            fprintf(stderr, "Failed to read distance from sensor\n");
            continue;
        }

        // Log the reading
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%.2f\n", timestamp, distance / 100.0);

        // Trigger GPIO alert if distance is below 10.0 cm
        if (distance < 1000) {
            gpioWrite(GPIO_ALERT, 1);
        } else {
            gpioWrite(GPIO_ALERT, 0);
        }

        // Sleep for the specified interval
        sleep_time.tv_sec = SAMPLE_INTERVAL_MS / 1000;
        sleep_time.tv_nsec = (SAMPLE_INTERVAL_MS % 1000) * 1000000;
        nanosleep(&sleep_time, NULL);
    }

    // Clean up resources
    fclose(log_file);
    i2cClose(I2C_BUS);
    gpioTerminate();

    return 0;
}

