#include <time.h>
#include <libgpiod.h>

#define VL53L1X_I2C_BUS 1
#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_MODEL_ID_REG 0x010F
#define VL53L1X_SYSTEM_MODE_START_REG 0x007
#define VL53L1X_SYSRANGE_START_REG 0x000
#define VL53L1X_RESULT_INTERRUPT_STATUS_REG 0x013
#define VL53L1X_SYSTEM_INTERRUPT_CLEAR_REG 0x014
#define VL53L1X_RESULT_RANGE_STATUS_REG 0x078
#define VL53L1X_RESULT_RANGE_STATUS_OFFSET 10
#define MAX_DISTANCE_MM 1200
#define MIN_DISTANCE_MM 300
#define APPROACH_DISTANCE_MM 600
#define CLEAR_DISTANCE_MM 1200
#define TIMEOUT_MS 100
#define LOG_FILE "distance_log.csv"

static int i2c_handle;
static FILE *log_file;
static int running = 1;

void sig_handler(int sig) {
    running = 0;
    if (log_file) fclose(log_file);
    if (i2c_handle) i2c_close(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    i2c_handle = i2cOpen(VL53L1X_I2C_BUS, VL53L1X_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor is present
    uint16_t model_id;
    if (i2cReadWordData(i2c_handle, VL53L1X_MODEL_ID_REG, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Invalid model ID: 0x%04X\n", model_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Software reset
    if (i2cWriteByteData(i2c_handle, VL53L1X_SYSTEM_MODE_START_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write software reset\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    usleep(2000);

    // Begin continuous back-to-back ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_SYSTEM_MODE_START_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to start continuous ranging\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Poll SYSRANGE__START register until it self-clears
    uint8_t sysrange_start;
    while (1) {
        if (i2cReadByteData(i2c_handle, VL53L1X_SYSRANGE_START_REG, &sysrange_start) < 0) {
            fprintf(stderr, "Failed to read SYSRANGE__START\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
        if ((sysrange_start & 0x01) == 0) break;
        usleep(1000);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row
    if (fputs("timestamp,distance_mm\n", log_file) < 0) {
        fprintf(stderr, "Failed to write header row\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 100000000; // 100 ms
    while (running) {
        // Poll RESULT__INTERRUPT_STATUS register for data-ready
        uint8_t interrupt_status;
        if (i2cReadByteData(i2c_handle, VL53L1X_RESULT_INTERRUPT_STATUS_REG, &interrupt_status) < 0) {
            fprintf(stderr, "Failed to read RESULT__INTERRUPT_STATUS\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
        if ((interrupt_status & 0x01) == 0) {
            usleep(1000);
            continue;
        }

        // Read 16-bit distance from RESULT__RANGE_STATUS + 10
        uint16_t range_status;
        if (i2cReadWordData(i2c_handle, VL53L1X_RESULT_RANGE_STATUS_REG + VL53L1X_RESULT_RANGE_STATUS_OFFSET, &range_status) < 0) {
            fprintf(stderr, "Failed to read RESULT__RANGE_STATUS\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
        if (range_status == 0x00) {
            fprintf(stderr, "Invalid range status\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Clear interrupt
        if (i2cWriteByteData(i2c_handle, VL53L1X_SYSTEM_INTERRUPT_CLEAR_REG, 0x01) < 0) {
            fprintf(stderr, "Failed to clear interrupt\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Append reading to log file
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s,%d\n", timestamp, range_status);

        // Print parking guidance message
        if (range_status < MIN_DISTANCE_MM) {
            printf("STOP\n");
        } else if (range_status < APPROACH_DISTANCE_MM) {
            printf("APPROACH\n");
        } else if (range_status < CLEAR_DISTANCE_MM) {
            printf("SLOW\n");
        } else {
            printf("CLEAR\n");
        }

        // Wait 100 ms
        nanosleep(&ts, NULL);
    }

    // Close log file and I2C handle
    fclose(log_file);
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}
