#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x45
#define LED_PIN 18
#define MAX_DISTANCE 500
#define MIN_DISTANCE 50
#define MAX_BRIGHTNESS 10
#define MIN_BRIGHTNESS 1
#define MAX_DELAY 1000000 // 1 second
#define MIN_DELAY 100000 // 100 ms

static int i2c_handle;
static int led_state = 0;
static int brightness = 10;
static int delay = 100000; // 100 ms
static int sensor_present = 1;

static void sigint_handler(int sig) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    gpio_write(LED_PIN, 0);
    gpioTerminate();
    exit(0);
}

static void sigterm_handler(int sig) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    gpio_write(LED_PIN, 0);
    gpioTerminate();
    exit(0);
}

static void update_brightness(int distance) {
    if (distance < MIN_DISTANCE) {
        brightness = MAX_BRIGHTNESS;
    } else if (distance > MAX_DISTANCE) {
        brightness = MIN_BRIGHTNESS;
    } else {
        brightness = (distance - MIN_DISTANCE) * (MAX_BRIGHTNESS - MIN_BRIGHTNESS) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_BRIGHTNESS;
    }
    delay = MAX_DELAY - (brightness - MIN_BRIGHTNESS) * (MAX_DELAY - MIN_DELAY) / (MAX_BRIGHTNESS - MIN_BRIGHTNESS);
}

static void update_led_state(int distance) {
    if (distance < MIN_DISTANCE) {
        led_state = 1 - led_state;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle == -1) {
        fprintf(stderr, "Failed to open I2C bus\n");
        sensor_present = 0;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        if (sensor_present) {
            uint8_t data[2];
            if (i2cReadData(i2c_handle, 0x00, data, 2) != 2) {
                fprintf(stderr, "Failed to read from I2C\n");
                sensor_present = 0;
            } else {
                int distance = (data[0] << 8) | data[1];
                update_brightness(distance);
                update_led_state(distance);
                printf("%ld: %d mm, %d Hz\n", time(NULL), distance, 1000 / delay);
            }
        } else {
            printf("%ld: Sensor absent\n", time(NULL));
        }
        usleep(delay);
    }

    i2c_close(i2c_handle);
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return 0;
}

