            break;
        }
        usleep(100000); // Wait 100 ms before retrying
    }
    if (retries == 0) {
        log_error("Failed to read distance data");
        return;
    }
    int distance_cm = (data[0] << 8) | data[1];
    fprintf(log_file, "%ld,%d\n", time(NULL), distance_cm);
}

