#define GPIO_PIN_17 17
#define GPIO_PIN_27 27
#define DEBOUNCE_TIME 50
#define LOG_FILE "proximity_log.txt"
#define MAX_LOG_LINE 256

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
}

void log_event(int sensor_id, int event_type) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    char log_line[MAX_LOG_LINE];
    snprintf(log_line, sizeof(log_line), "%s,%d,%s\n", timestamp, sensor_id, event_type == 1 ? "DETECTED" : "CLEARED");
    if (fwrite(log_line, strlen(log_line), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write to log file: %s\n", LOG_FILE);
    }

    fclose(log_file);
}

void poll_sensors() {
    int sensor_1_state = gpioRead(GPIO_PIN_17);
    int sensor_2_state = gpioRead(GPIO_PIN_27);

    static int prev_sensor_1_state = -1;
    static int prev_sensor_2_state = -1;

    if (sensor_1_state != prev_sensor_1_state) {
        if (sensor_1_state == 0) {
            log_event(1, 1); // DETECTED
        } else {
            log_event(1, 0); // CLEARED
        }
        prev_sensor_1_state = sensor_1_state;
    }

    if (sensor_2_state != prev_sensor_2_state) {
        if (sensor_2_state == 0) {
            log_event(2, 1); // DETECTED
        } else {
            log_event(2, 0); // CLEARED
        }
        prev_sensor_2_state = sensor_2_state;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN_17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", GPIO_PIN_17);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN_27, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", GPIO_PIN_27);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (keep_running) {
        poll_sensors();
        usleep(10000); // 10 ms
    }

    fclose(log_file); // Ensure log file is closed before terminating
    gpioTerminate();

    return EXIT_SUCCESS;
}

