#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09
#define TIMEOUT_MS 50
#define CSV_FILE "distance_log.csv"

static int i2c_fd = -1;
static FILE *csv_file = NULL;

static void log_data(const char *timestamp, int distance_mm) {
    if (csv_file == NULL) {
        csv_file = fopen(CSV_FILE, "a");
        if (csv_file == NULL) {
            perror("Failed to open CSV file");
            return;
        }
    }
    fprintf(csv_file, "%s,%d\n", timestamp, distance_mm);
    fflush(csv_file);
}

static void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    exit(0);
}

static int i2c_read_register(int reg) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write to I2C");
        return -1;
    }
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from I2C");
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

static int i2c_write_register(int reg, int value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write to I2C");
        return -1;
    }
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        struct timespec start, end;
        clock_gettime(CLOCK_MONOTONIC, &start);

        if (i2c_write_register(MEAS_TRIGGER, 0x01) != 0) {
            continue;
        }

        while (1) {
            int status = i2c_read_register(MEAS_STATUS);
            if (status == -1) {
                continue;
            }
            if (status & 0x01) {
                break;
            }
            clock_gettime(CLOCK_MONOTONIC, &end);
            if (difftime(end.tv_sec, start.tv_sec) * 1000 + (end.tv_nsec - start.tv_nsec) / 1000000 > TIMEOUT_MS) {
                break;
            }
            usleep(1000);
        }

        if (status & 0x01) {
            int distance_mm = i2c_read_register(DIST_HIGH) << 8 | i2c_read_register(DIST_LOW);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&start.tv_sec));
            log_data(timestamp, distance_mm);
        }
    }

    close(i2c_fd);
    fclose(csv_file);
    return 0;
}

