#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MLX75030_ADDR 0x4C
#define I2C_BUS 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static int i2c_handle;
static volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int signum) {
    exit_flag = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, MLX75030_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    struct timespec sleep_time = {0, 100000000}; // 100 ms

    while (!exit_flag) {
        for (int retry = 0; retry < MAX_RETRIES; retry++) {
            int result = i2cReadReg(i2c_handle, 0x00); // Read status register
            if (result >= 0) {
                if (result & 0x01) { // Check if sensor is present
                    uint16_t distance;
                    result = i2cReadReg(i2c_handle, 0x01); // Read distance register
                    if (result >= 0) {
                        distance = (result << 8) | (i2cReadReg(i2c_handle, 0x02) & 0xFF);
                        printf("%ld ms: Distance = %d mm\n", (long)timespec_get(&sleep_time, TIME_UTC).tv_nsec / 1000000, distance);
                        break;
                    }
                }
                break;
            }
            usleep(RETRY_DELAY_MS * 1000);
        }
        if (exit_flag) {
            break;
        }
        nanosleep(&sleep_time, NULL);
    }

    // Clean up resources
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

