#define START_RANGING_REG 0x0009
#define INTERRUPT_STATUS_REG 0x0046
#define DISTANCE_HIGH_REG 0x0096
#define DISTANCE_LOW_REG 0x0097

static volatile sig_atomic_t quit = 0;

void sig_handler(int sig) {
    quit = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDRESS);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteReg16(I2C_BUS, I2C_ADDRESS, SOFT_RESET_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to SOFT_RESET_REG\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }
    usleep(10000); // Wait 10 ms

    if (i2cWriteReg16(I2C_BUS, I2C_ADDRESS, START_RANGING_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to START_RANGING_REG\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!quit) {
        if (i2cReadReg16(I2C_BUS, I2C_ADDRESS, INTERRUPT_STATUS_REG) & 0x0001) {
            uint16_t distance_high, distance_low;
            if (i2cReadReg16(I2C_BUS, I2C_ADDRESS, DISTANCE_HIGH_REG, &distance_high) < 0) {
                fprintf(stderr, "Failed to read from DISTANCE_HIGH_REG\n");
                continue;
            }
            if (i2cReadReg16(I2C_BUS, I2C_ADDRESS, DISTANCE_LOW_REG, &distance_low) < 0) {
                fprintf(stderr, "Failed to read from DISTANCE_LOW_REG\n");
                continue;
            }
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("Timestamp: %04d-%02d-%02d %02d:%02d:%02d.%06ld, Distance: %d mm\n",
                   ts.tv_sec / 1000000000, (ts.tv_sec / 1000000) % 1000, ts.tv_sec % 1000,
                   (ts.tv_nsec / 1000000) % 1000, (ts.tv_nsec / 1000) % 1000, ts.tv_nsec % 1000,
                   (distance_high << 8) | distance_low);
        }
        usleep(500000); // Poll every 500 ms
    }

    i2cClose(I2C_BUS);
    gpioTerminate();
    return 0;
}

