#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VL53L1X_I2C_ADDR 0x29
#define GPIO_BUZZER 22
#define I2C_BUS 1
#define RANGING_INTERVAL_MS 500

static volatile int running = 1;

void handle_sigint(int signum) {
    running = 0;
}

int main() {
    int i2c_handle;
    int distance_mm;
    int status;
    uint8_t data[2];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up GPIO for buzzer
    if (gpioSetMode(GPIO_BUZZER, PI_OUTPUT)) {
        fprintf(stderr, "Failed to set GPIO mode for buzzer\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Reset the sensor
    data[0] = 0x00;
    data[1] = 0x01;
    status = i2cWrite(i2c_handle, data, 2);
    if (status < 0) {
        fprintf(stderr, "Failed to reset VL53L1X sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    data[0] = 0x00;
    data[1] = 0x01;
    status = i2cWrite(i2c_handle, data, 2);
    if (status < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure continuous ranging mode
    data[0] = 0x00;
    data[1] = 0x07;
    status = i2cWrite(i2c_handle, data, 2);
    if (status < 0) {
        fprintf(stderr, "Failed to configure continuous ranging mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (running) {
        // Read the distance
        data[0] = 0x00;
        data[1] = 0x96;
        status = i2cRead(i2c_handle, data, 2);
        if (status < 0) {
            fprintf(stderr, "Failed to read distance from VL53L1X sensor\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
        distance_mm = (data[0] << 8) | data[1];

        // Check if the distance is below 100 mm
        if (distance_mm < 100) {
            // Activate the buzzer
            gpioWrite(GPIO_BUZZER, 1);
        } else {
            // Deactivate the buzzer
            gpioWrite(GPIO_BUZZER, 0);
        }

        // Sleep for the specified interval
        usleep(RANGING_INTERVAL_MS * 1000);
    }

    // Clean up resources
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

