#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <mqueue.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_Buzzer 23
#define MODEL_ID_REG 0x010F
#define SOFTWARE_RESET_REG 0x0000
#define TIMING_BUDGET_REG 0x0001
#define DATA_READY_REG 0x0089
#define DISTANCE_REG 0x0096
#define DISTANCE_SIZE 2
#define BUZZER_ON 1
#define BUZZER_OFF 0
#define QUEUE_NAME "/distance_queue"
#define QUEUE_PERMISSIONS 0666
#define QUEUE_MAX_MSGS 10
#define QUEUE_MSG_SIZE sizeof(int)

static mqd_t queue;
static int i2c_handle;
static int gpio_buzzer;
static int model_id;
static int timing_budget;
static int data_ready;
static int distance;
static int buzzer_state = BUZZER_OFF;

static void handle_sigint(int signum) {
    if (queue != -1) {
        mq_close(queue);
        mq_unlink(QUEUE_NAME);
    }
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (gpio_buzzer != -1) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

static void init_i2c() {
    if (i2c_handle == -1) {
        i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
        if (i2c_handle == -1) {
            perror("Failed to open I2C bus");
            exit(EXIT_FAILURE);
        }
    }
}

static void init_gpio() {
    if (gpio_buzzer == -1) {
        gpio_buzzer = gpioGetGpioNumber(GPIO_Buzzer);
        if (gpio_buzzer == -1) {
            perror("Failed to get GPIO number");
            exit(EXIT_FAILURE);
        }
        gpioSetMode(gpio_buzzer, PI_OUTPUT);
    }
}

static void init_queue() {
    if (queue == -1) {
        queue = mq_open(QUEUE_NAME, O_CREAT | O_RDWR, QUEUE_PERMISSIONS, NULL);
        if (queue == (mqd_t)-1) {
            perror("Failed to create message queue");
            exit(EXIT_FAILURE);
        }
    }
}

static void init_sensor() {
    init_i2c();
    init_gpio();
    init_queue();

    // Check model ID
    if (i2cReadReg16(i2c_handle, MODEL_ID_REG, &model_id) != 0) {
        perror("Failed to read model ID");
        exit(EXIT_FAILURE);
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Invalid model ID: 0x%02X\n", model_id);
        exit(EXIT_FAILURE);
    }

    // Software reset
    if (i2cWriteReg8(i2c_handle, SOFTWARE_RESET_REG, 0x00) != 0) {
        perror("Failed to write software reset 0x00");
        exit(EXIT_FAILURE);
    }
    if (i2cWriteReg8(i2c_handle, SOFTWARE_RESET_REG, 0x01) != 0) {
        perror("Failed to write software reset 0x01");
        exit(EXIT_FAILURE);
    }

    // Configure timing budget
    timing_budget = 50; // 50 ms
    if (i2cWriteReg8(i2c_handle, TIMING_BUDGET_REG, timing_budget) != 0) {
        perror("Failed to write timing budget");
        exit(EXIT_FAILURE);
    }
}

static void start_ranging() {
    if (i2cWriteReg8(i2c_handle, DATA_READY_REG, 0x01) != 0) {
        perror("Failed to start ranging");
        exit(EXIT_FAILURE);
    }
}

static void read_distance() {
    if (i2cReadReg16(i2c_handle, DISTANCE_REG, &distance) != 0) {
        perror("Failed to read distance");
        exit(EXIT_FAILURE);
    }
}

static void log_distance() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    int timestamp = (int)ts.tv_sec * 1000 + (int)ts.tv_nsec / 1000000;
    int message[2] = {timestamp, distance};
    if (mq_send(queue, (char*)&message, QUEUE_MSG_SIZE, 0) != 0) {
        perror("Failed to send message to queue");
        exit(EXIT_FAILURE);
    }
}

static void activate_buzzer() {
    gpioWrite(gpio_buzzer, BUZZER_ON);
    buzzer_state = BUZZER_ON;
}

static void deactivate_buzzer() {
    gpioWrite(gpio_buzzer, BUZZER_OFF);
    buzzer_state = BUZZER_OFF;
}

static void check_data_ready() {
    if (i2cReadReg8(i2c_handle, DATA_READY_REG, &data_ready) != 0) {
        perror("Failed to read data ready");
        exit(EXIT_FAILURE);
    }
    if (data_ready & 0x01) {
        read_distance();
        log_distance();
        if (distance < 100) {
            activate_buzzer();
        } else {
            deactivate_buzzer();
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }
    signal(SIGINT, handle_sigint);

    init_sensor();
    start_ranging();

    while (1) {
        check_data_ready();
        usleep(50000); // 50 ms
    }

    return 0;
}

