#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22
#define MAX_DISTANCE 400
#define MIN_DISTANCE 2
#define BEEP_INTERVAL 100000  // 100 ms
#define TIMEOUT 1000000000  // 1 second

static volatile int distance = 0;
static volatile int buzzer_state = 0;
static volatile int timeout_occurred = 0;

void gpioAlertFuncEx(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == PI_HIGH) {
            uint32_t start_tick = tick;
            while (gpioRead(ECHO_PIN) == PI_HIGH) {
                if (tick - start_tick > TIMEOUT) {
                    timeout_occurred = 1;
                    break;
                }
                start_tick = tick;
            }
            if (!timeout_occurred) {
                uint32_t end_tick = tick;
                distance = (end_tick - start_tick) / 58;
                if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                    buzzer_state = 1;
                } else {
                    buzzer_state = 0;
                }
            }
        }
    }
}

void handle_sigint(int signum) {
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    gpioSetAlertFuncEx(ECHO_PIN, gpioAlertFuncEx);

    signal(SIGINT, handle_sigint);

    while (1) {
        if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
            gpioWrite(BUZZER_PIN, 1);
        } else {
            gpioWrite(BUZZER_PIN, 0);
        }
        printf("Distance: %d cm\n", distance);
        usleep(BEEP_INTERVAL);
    }

    gpioTerminate();
    return 0;
}

