#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <vl53l1x_api.h>
#include <mqtt.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_GPIO 18
#define MAX_RETRIES 5
#define DISTANCE_THRESHOLD 20
#define LOG_FILE "gate_log.txt"

static int i2c_fd;
static int servo_handle;
static int mqtt_client;
static int mqtt_connected = 0;
static int force_open = 0;
static int force_close = 0;
static int status_request = 0;

static void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (mqtt_client) {
            mqtt_disconnect(mqtt_client);
        }
        if (servo_handle) {
            gpioPWMWrite(servo_handle, 0);
            gpioClose(servo_handle);
        }
        if (i2c_fd) {
            close(i2c_fd);
        }
        printf("Exiting...\n");
        exit(0);
    }
}

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s - %s\n", timestamp, event);
        fclose(log);
    }
}

static void handle_mqtt_message(const char *topic, const char *payload, size_t payload_len) {
    if (strcmp(topic, "force_open") == 0) {
        force_open = 1;
    } else if (strcmp(topic, "force_close") == 0) {
        force_close = 1;
    } else if (strcmp(topic, "status_request") == 0) {
        status_request = 1;
    }
}

static void mqtt_callback(void *context, char *topic, int qos, const unsigned char *payload, int payload_len) {
    handle_mqtt_message(topic, payload, payload_len);
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_vl53l1x() {
    VL53L1X_Dev_t dev;
    VL53L1X_Error status = VL53L1X_Initialize(&dev);
    if (status != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to initialize VL53L1X: %d\n", status);
        exit(EXIT_FAILURE);
    }
    status = VL53L1X_StartRanging(&dev);
    if (status != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to start ranging: %d\n", status);
        VL53L1X_DeepSleep(&dev);
        VL53L1X_Uninitialize(&dev);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_servo() {
    servo_handle = gpioCreatePWMOutput(SERVO_GPIO, 50);
    if (servo_handle < 0) {
        perror("Failed to create PWM output");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    gpioPWMWrite(servo_handle, 0); // Start at 0 degrees
}

static void init_mqtt() {
    mqtt_client = mqtt_client_new("localhost", 1883, NULL, NULL, NULL);
    if (!mqtt_client) {
        fprintf(stderr, "Failed to create MQTT client\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    mqtt_client_set_callback(mqtt_client, mqtt_callback);
    if (mqtt_connect(mqtt_client) != MQTT_ERR_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        mqtt_client_destroy(mqtt_client);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    mqtt_connected = 1;
}

static void close_mqtt() {
    if (mqtt_connected) {
        mqtt_disconnect(mqtt_client);
    }
    mqtt_client_destroy(mqtt_client);
}

static void close_servo() {
    if (servo_handle) {
        gpioPWMWrite(servo_handle, 0);
        gpioClose(servo_handle);
    }
}

static void close_i2c() {
    if (i2c_fd) {
        close(i2c_fd);
    }
}

static void open_gate() {
    gpioPWMWrite(servo_handle, 1000); // 180 degrees
    log_event("Gate opened");
}

static void close_gate() {
    gpioPWMWrite(servo_handle, 0); // 0 degrees
    log_event("Gate closed");
}

static void check_distance() {
    VL53L1X_Dev_t dev;
    VL53L1X_Error status = VL53L1X_Initialize(&dev);
    if (status != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to initialize VL53L1X: %d\n", status);
        return;
    }
    status = VL53L1X_StartRanging(&dev);
    if (status != VL53L1X_ERROR_NONE) {
        fprintf(stderr, "Failed to start ranging: %d\n", status);
        VL53L1X_DeepSleep(&dev);
        VL53L1X_Uninitialize(&dev);
        return;
    }
    uint16_t distance;
    for (int i = 0; i < MAX_RETRIES; i++) {
        status = VL53L1X_GetDistance(&dev, &distance);
        if (status == VL53L1X_ERROR_NONE) {
            if (distance < DISTANCE_THRESHOLD) {
                open_gate();
            } else {
                close_gate();
            }
            break;
        }
        usleep(100000); // Wait 100 ms
    }
    VL53L1X_StopRanging(&dev);
    VL53L1X_DeepSleep(&dev);
    VL53L1X_Uninitialize(&dev);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    init_i2c();
    init_vl53l1x();
    init_servo();
    init_mqtt();

    while (1) {
        if (force_open) {
            open_gate();
            force_open = 0;
        } else if (force_close) {
            close_gate();
            force_close = 0;
        } else if (status_request) {
            mqtt_publish(mqtt_client, "status", "gate_status", "open", 0);
            status_request = 0;
        } else {
            check_distance();
        }
        usleep(100000); // Wait 100 ms
    }

    close_mqtt();
    close_servo();
    close_i2c();
    gpioTerminate();

    return 0;
}

