This C program initializes the Raspberry Pi Zero W with the pigpio library to control a gate using a VL53L1X time-of-flight sensor and an SG90 servo motor. It automatically opens the gate when an object is detected within 20 cm and closes it when the path is clear. The program logs all gate events with timestamps to 'gate_log.txt'. It also supports remote control using the paho-mqtt v2 callback API, handling force_open, force_close, and status_request commands. The program ensures clean resource release on all exit paths via signal handling.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_PIN 23
#define ECHO_PIN 24
#define LOG_FILE "distance_log.txt"
#define SAMPLE_RATE 5  // Hz
#define TIMEOUT_MS 60  // ms
#define MIN_PULSE_WIDTH_US 100
#define MAX_PULSE_WIDTH_US 30000

static volatile int running = 1;
static FILE *log_file;
static struct timespec last_trigger_time;

void handle_signal(int signum) {
    running = 0;
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void alert_callback(unsigned int gpio, unsigned int level, uint32_t tick) {
    static uint32_t rising_edge_tick = 0;
    static uint32_t falling_edge_tick = 0;

    if (level == PI_RISING_EDGE) {
        rising_edge_tick = tick;
    } else if (level == PI_FALLING_EDGE) {
        falling_edge_tick = tick;
        uint32_t pulse_width_us = falling_edge_tick - rising_edge_tick;
        if (pulse_width_us < MIN_PULSE_WIDTH_US || pulse_width_us > MAX_PULSE_WIDTH_US) {
            fprintf(stderr, "Warning: Invalid pulse width %u us\n", pulse_width_us);
        } else {
            double distance_cm = pulse_width_us * 0.0343 / 2.0;
            char timestamp[20];
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
            fprintf(stdout, "%s,%.2f\n", timestamp, distance_cm);
            if (log_file) {
                fprintf(log_file, "%s,%.2f\n", timestamp, distance_cm);
                fflush(log_file);
            }
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN pull-down\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, alert_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert callback\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        gpioWrite(TRIG_PIN, 0);
        nanosleep((const struct timespec[]){{0, 1000000}}, NULL);
        gpioWrite(TRIG_PIN, 1);
        nanosleep((const struct timespec[]){{0, 10}}, NULL);
        gpioWrite(TRIG_PIN, 0);

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec - last_trigger_time.tv_sec > 200 / SAMPLE_RATE) {
            fprintf(stderr, "Warning: No valid echo received within 60 ms\n");
        }

        last_trigger_time = now;
        nanosleep((const struct timespec[]){{200, 0}}, NULL);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

