#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define VL53L1X_ADDRESS 0x29
#define VL53L1X_SHUTDOWN_PIN 23
#define VL53L1X_INTERRUPT_PIN 24
#define SERVO_PWM_PIN 18
#define HISTORIC_DISTANCE 50
#define CURRENT_DISTANCE 60
#define LOG_FILE "parking_log.txt"

static volatile int running = 1;
static int distance = 0;

void sig_handler(int sig) {
    running = 0;
    gpioTerminate();
    printf("Exiting...\n");
    exit(0);
}

void log_state(int state, int distance) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log, "%s - State: %d, Distance: %d cm\n", timestamp, state, distance);
    fclose(log);
}

void init_sensor() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        exit(1);
    }
    if (gpioSetMode(VL53L1X_SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        perror("Failed to set shutdown pin mode");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetMode(VL53L1X_INTERRUPT_PIN, PI_INPUT) < 0) {
        perror("Failed to set interrupt pin mode");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetPullUpDown(VL53L1X_INTERRUPT_PIN, PI_PUD_UP) < 0) {
        perror("Failed to set interrupt pin pull-up");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetPWMFrequency(SERVO_PWM_PIN, 50) < 0) {
