#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_SOFT_RESET 0x00
#define VL53L1X_SYSRANGE_START 0x00
#define VL53L1X_RESULT_RANGE_MM 0x14
#define GPIO_OPEN 18
#define GPIO_CLOSE 19
#define LOG_FILE "gate_events.log"
#define POLL_INTERVAL_MS 500

static int i2cHandle;
static FILE *logFile;
static volatile sig_atomic_t exitFlag = 0;

void logEvent(const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(logFile, "%s %s\n", timestamp, event);
    fflush(logFile);
}

void handleSignal(int sig) {
    exitFlag = 1;
}

void initGPIO() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(GPIO_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_CLOSE, PI_OUTPUT);
    gpioWrite(GPIO_OPEN, 0);
    gpioWrite(GPIO_CLOSE, 1);
}

void initI2C() {
    i2cHandle = i2cOpen(1, VL53L1X_I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }
}

void softResetVL53L1X() {
    uint8_t data = 0x01;
    if (i2cWriteI2CBlockData(i2cHandle, VL53L1X_SOFT_RESET, &data, 1) < 0) {
        fprintf(stderr, "Failed to soft reset VL53L1X\n");
        exit(EXIT_FAILURE);
    }
    usleep(100000); // Wait for VL53L1X to reset
}

void configureVL53L1X() {
    uint8_t data[2];
    data[0] = 0x00; // Start ranging
    data[1] = 0x00; // Continuous mode
    if (i2cWriteI2CBlockData(i2cHandle, VL53L1X_SYSRANGE_START, data, 2) < 0) {
        fprintf(stderr, "Failed to configure VL53L1X\n");
        exit(EXIT_FAILURE);
    }
}

void readDistance() {
    uint8_t data[2];
    if (i2cReadI2CBlockData(i2cHandle, VL53L1X_RESULT_RANGE_MM, data, 2) < 0) {
        fprintf(stderr, "Failed to read distance from VL53L1X\n");
        exit(EXIT_FAILURE);
    }
    int distance = (data[0] << 8) | data[1];
    if (distance < 200) {
        logEvent("Gate opened");
        gpioWrite(GPIO_OPEN, 1);
        gpioWrite(GPIO_CLOSE, 0);
    } else {
        logEvent("Gate closed");
        gpioWrite(GPIO_OPEN, 0);
        gpioWrite(GPIO_CLOSE, 1);
    }
}

int main() {
    if (signal(SIGINT, handleSignal) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler for SIGINT\n");
        exit(EXIT_FAILURE);
    }
    if (signal(SIGTERM, handleSignal) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler for SIGTERM\n");
        exit(EXIT_FAILURE);
    }

    initGPIO();
    initI2C();
    softResetVL53L1X();
    configureVL53L1X();

    logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    while (!exitFlag) {
        readDistance();
        usleep(POLL_INTERVAL_MS * 1000);
    }

    fclose(logFile);
    i2cClose(i2cHandle);
    gpioTerminate();

    return 0;
}

