#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <vl53l1x_api.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_TRIGGER 24
#define GPIO_MOTOR_FORWARD 17
#define GPIO_MOTOR_BACKWARD 18
#define MAX_RETRIES 10
#define RETRY_DELAY_MS 100

static volatile int running = 1;
static int i2c_handle;
static int motor_forward = 0;
static int motor_backward = 0;

void sig_handler(int sig) {
    running = 0;
    gpioWrite(GPIO_MOTOR_FORWARD, 0);
    gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    gpioTerminate();
    close(i2c_handle);
    printf("Program terminated by signal %d\n", sig);
    exit(0);
}

void motor_control(int distance) {
    if (distance < 100) {
        gpioWrite(GPIO_MOTOR_FORWARD, 1);
        gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    } else if (distance > 300) {
        gpioWrite(GPIO_MOTOR_FORWARD, 0);
        gpioWrite(GPIO_MOTOR_BACKWARD, 1);
    } else {
        gpioWrite(GPIO_MOTOR_FORWARD, 0);
        gpioWrite(GPIO_MOTOR_BACKWARD, 0);
    }
}

void i2c_write(uint8_t reg, uint8_t value) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = i2cWriteReg(i2c_handle, reg, value);
        if (result == PI_OK) {
            return;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    printf("I2C write to 0x%02x failed after %d retries\n", reg, MAX_RETRIES);
}

uint16_t i2c_read(uint8_t reg) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = i2cReadReg(i2c_handle, reg);
        if (result != PI_ERROR) {
            return result;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    printf("I2C read from 0x%02x failed after %d retries\n", reg, MAX_RETRIES);
    return 0;
}

void soft_reset() {
    i2c_write(0x00, 0x00);
    usleep(1000);
    i2c_write(0x00, 0x01);
}

void start_measurement() {
    i2c_write(0x00, 0x01);
}

