    int retries = 0;
    while (retries < MAX_RETRIES) {
        uint16_t status = i2c_read(0x0089);
        if (status & 0x0001) {
            return;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000);
    }
    printf("Data ready not set after %d retries\n", MAX_RETRIES);
}

void read_distance() {
    uint16_t distance = (i2c_read(0x0096) << 8) | i2c_read(0x0097);
    printf("Distance: %d mm\n", distance);
    motor_control(distance);
}

