        printf("Failed to set GPIO_MOTOR_FORWARD mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_MOTOR_BACKWARD, PI_OUTPUT) < 0) {
        printf("Failed to set GPIO_MOTOR_BACKWARD mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISR(GPIO_TRIGGER, RISING_EDGE, 0, &trigger_isr) < 0) {
        printf("Failed to set ISR for GPIO_TRIGGER\n");
        gpioTerminate();
        return 1;
    }
    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        printf("Failed to open I2C bus %d at address 0x%02x\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
