#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_MS 30
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0

static volatile sig_atomic_t should_exit = 0;

static void sigint_handler(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct timespec sleep_time = {0, 1000000}; // 1 ms
    struct timespec timeout = {0, TIMEOUT_MS * 1000000}; // Timeout in ns
    struct timespec start_time, end_time;
    struct tm *timeinfo;
    char timestamp[20];
    double distance;
    gpiod_chip *chip;
    gpiod_line *trigger_line, *echo_line;
    gpiod_line_request *trigger_request, *echo_request;
    gpiod_line_bulk *bulk_request;
    unsigned int trigger_value = 0, echo_value = 0;
    unsigned int pulse_us = 0;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open the chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request trigger line as output
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    trigger_request = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (!trigger_request) {
        perror("Failed to request trigger line as output");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request echo line as input
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    echo_request = gpiod_line_request_input(echo_line, "echo");
    if (!echo_request) {
        perror("Failed to request echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!should_exit) {
        // Trigger sequence
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        gpiod_line_set_value(trigger_line, 0); // Hold trigger low for 5 microseconds
        usleep(5000);
        gpiod_line_set_value(trigger_line, 1); // Pulse trigger high for 10 microseconds
        usleep(10000);
        gpiod_line_set_value(trigger_line, 0); // Hold trigger low for 5 microseconds
        clock_gettime(CLOCK_MONOTONIC, &end_time);

        // Wait for echo rising edge
        bulk_request = gpiod_line_request_bulk(chip, 2, GPIOD_LINE_REQUEST_FLAG_BULK);
        if (!bulk_request) {
            perror("Failed to request bulk lines");
            gpiod_line_release(trigger_line);
            gpiod_line_release(echo_line);
            gpiod_chip_close(chip);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }
        gpiod_line_request_input(bulk_request, 0, "echo");
        gpiod_line_request_output(bulk_request, 1, "trigger", 0);
        gpiod_line_set_value(bulk_request, 1, 1); // Pulse trigger high for 10 microseconds
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        while (gpiod_line_get_value(bulk_request, 0) == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &end_time) == -1) {
                perror("Failed to get end time");
                gpiod_line_release(trigger_line);
                gpiod_line_release(echo_line);
                gpiod_chip_close(chip);
                fclose(log_file);
                exit(EXIT_FAILURE);
            }
            if (difftime(end_time.tv_sec, start_time.tv_sec) > 1) {
                fprintf(log_file, "Echo never rose\n");
                fflush(log_file);
                break;
            }
            nanosleep(&sleep_time, NULL);
        }
        gpiod_line_release(bulk_request);

        // Measure echo pulse width
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        while (gpiod_line_get_value(echo_line) == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &end_time) == -1) {
                perror("Failed to get end time");
                gpiod_line_release(trigger_line);
                gpiod_line_release(echo_line);
                gpiod_chip_close(chip);
                fclose(log_file);
                exit(EXIT_FAILURE);
            }
            if (difftime(end_time.tv_sec, start_time.tv_sec) > 1) {
                fprintf(log_file, "Echo never fell\n");
                fflush(log_file);
                break;
            }
            nanosleep(&sleep_time, NULL);
        }
        pulse_us = (end_time.tv_sec - start_time.tv_sec) * 1000000 + (end_time.tv_nsec - start_time.tv_nsec) / 1000;

        // Calculate distance
        distance = (pulse_us * 0.0343) / 2.0;
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(log_file, "Distance out of range: %.2f cm\n", distance);
            fflush(log_file);
        } else {
            time_t now = time(NULL);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
            fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
            fflush(log_file);
        }

        // Sleep for 1 second
        nanosleep(&timeout, NULL);
    }

    // Release resources
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

