#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define VL53L1X_I2C_ADDR 0x29
#define VL53L1X_XSHUT_PIN 27
#define VL53L1X_REG_CONTINUOUS_MODE 0x0018
#define VL53L1X_REG_NO_TIMEOUT 0x0019
#define VL53L1X_REG_START_RANGING 0x0020
#define VL53L1X_REG_DISTANCE 0x0014
#define VL53L1X_REG_STATUS 0x0016

static int i2c_handle;
static int xshut_pin;

void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (i2c_handle != -1) {
            i2c_close(i2c_handle);
        }
        if (gpioInitialised()) {
            gpioTerminate();
        }
        syslog(LOG_INFO, "Program terminated by signal %d", signum);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    // Initialize syslog
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        closelog();
        exit(EXIT_FAILURE);
    }

    // Set GPIO27 as an output and set it high
    if (gpioSetMode(xshut_pin, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO27 mode");
        gpioTerminate();
        closelog();
        exit(EXIT_FAILURE);
    }
    if (gpioWrite(xshut_pin, 1) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO27 high");
        gpioTerminate();
        closelog();
        exit(EXIT_FAILURE);
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, VL53L1X_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        gpioTerminate();
        closelog();
        exit(EXIT_FAILURE);
    }

    // Configure sensor
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_CONTINUOUS_MODE, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0018");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        exit(EXIT_FAILURE);
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_NO_TIMEOUT, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0019");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        exit(EXIT_FAILURE);
    }
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_START_RANGING, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x0020");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        exit(EXIT_FAILURE);
    }

    // Set up signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Main loop
    while (1) {
        uint16_t distance;
        uint8_t status;

        // Read distance
        if (i2cReadWordData(i2c_handle, VL53L1X_REG_DISTANCE, &distance) < 0) {
            syslog(LOG_ERR, "Failed to read distance from register 0x0014");
        } else {
            syslog(LOG_INFO, "Timestamp: %ld, Distance: %d mm, Status: %d", time(NULL), distance, status);
        }

        // Read status
        if (i2cReadByteData(i2c_handle, VL53L1X_REG_STATUS, &status) < 0) {
            syslog(LOG_ERR, "Failed to read status from register 0x0016");
        }

        // Wait 100 ms
        usleep(100000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

