This C program initializes the VL53L1X time-of-flight sensor on a Raspberry Pi 4 Model B using the pigpio library. It sets up GPIO27 as an output to control the sensor's XSHUT pin, configures the sensor to operate in continuous mode, and reads the distance and status from the sensor in an infinite loop. The program logs the results to the systemd journal and handles signals to clean up resources and terminate gracefully.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_GATE 24
#define LOG_FILE "gate_log.txt"
#define SHORT_RANGE_MODE 0x00
#define LONG_RANGE_MODE 0x01
#define MAX_DISTANCE 4000 // in mm

static volatile sig_atomic_t quit = 0;

void sig_handler(int sig) {
    quit = 1;
}

int main() {
    FILE *log_file;
    struct timespec ts;
    int i2c_handle;
    uint8_t data[2];
    uint16_t distance_mm;
    uint8_t mode;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO for the gate actuator
    if (gpioSetMode(GPIO_GATE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for gate\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the VL53L1X sensor
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Read the model ID to verify the sensor
    result = i2cReadReg(i2c_handle, 0x010F, data, 1);
    if (result < 0) {
        fprintf(stderr, "Failed to read model ID\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (data[0] != 0xEA) {
        fprintf(stderr, "Invalid model ID\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set the ranging mode to short
    mode = SHORT_RANGE_MODE;
    result = i2cWriteReg(i2c_handle, 0x0021, mode);
    if (result < 0) {
        fprintf(stderr, "Failed to set ranging mode\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Start ranging
    result = i2cWriteReg(i2c_handle, 0x0015, 0x01);
    if (result < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set the gate to closed
    gpioWrite(GPIO_GATE, 0);

    // Main loop
    while (!quit) {
        // Read the distance
        result = i2cReadReg(i2c_handle, 0x0089, data, 1);
        if (result < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }
        distance_mm = (data[0] << 8) | data[1];

        // Log the distance
        time(&ts);
        fprintf(log_file, "%ld: Distance: %d mm\n", ts.tv_sec, distance_mm);

        // Open the gate if the distance is less than 20 cm
        if (distance_mm < 200) {
            if (gpioWrite(GPIO_GATE, 1) < 0) {
                fprintf(stderr, "Failed to open gate\n");
            }
        } else {
            if (gpioWrite(GPIO_GATE, 0) < 0) {
                fprintf(stderr, "Failed to close gate\n");
            }
        }

        // Wait for 100 ms
        nanosleep(&(struct timespec){0, 100000000}, NULL);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

