        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set the ranging mode to short
    mode = SHORT_RANGE_MODE;
    result = i2cWriteReg(i2c_handle, 0x0021, mode);
    if (result < 0) {
        fprintf(stderr, "Failed to set ranging mode\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Start ranging
    result = i2cWriteReg(i2c_handle, 0x0015, 0x01);
    if (result < 0) {
        fprintf(stderr, "Failed to start ranging\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set the gate to closed
    gpioWrite(GPIO_GATE, 0);

    // Main loop
    while (!quit) {
        // Read the distance
        result = i2cReadReg(i2c_handle, 0x0089, data, 1);
        if (result < 0) {
            fprintf(stderr, "Failed to read distance\n");
            continue;
        }
        distance_mm = (data[0] << 8) | data[1];

        // Log the distance
        time(&ts);
        fprintf(log_file, "%ld: Distance: %d mm\n", ts.tv_sec, distance_mm);

        // Open the gate if the distance is less than 20 cm
        if (distance_mm < 200) {
            if (gpioWrite(GPIO_GATE, 1) < 0) {
                fprintf(stderr, "Failed to open gate\n");
            }
        } else {
            if (gpioWrite(GPIO_GATE, 0) < 0) {
                fprintf(stderr, "Failed to close gate\n");
            }
        }

        // Wait for 100 ms
        nanosleep(&(struct timespec){0, 100000000}, NULL);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}
