#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define SAMPLES 5
#define TIMEOUT 30000 // 30 ms timeout
#define LOG_FILE "distance_log.csv"
#define LOG_HEADER "Timestamp,Distance (cm),Servo Angle (deg)\n"

volatile sig_atomic_t stop = 0;

void handle_sigint(int sig) {
    stop = 1;
    gpioWrite(SERVO_PIN, 90); // Default servo angle
    gpioTerminate();
    fclose(fp);
    printf("Program terminated by user.\n");
}

void alert_callback(unsigned int gpio, unsigned int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    static uint32_t pulse_width = 0;
    static int samples[SAMPLES];
    static int sample_index = 0;
    static int sum = 0;
    static int count = 0;
    static int distance = -1;
    static int servo_angle = 90;

    if (level == PI_HIGH) {
        last_tick = tick;
    } else {
        pulse_width = tick - last_tick;
        if (pulse_width > TIMEOUT) {
            distance = -1;
        } else {
            samples[sample_index] = pulse_width;
            sum += samples[sample_index];
            count++;
            sample_index = (sample_index + 1) % SAMPLES;
            if (count == SAMPLES) {
                distance = sum / SAMPLES;
                if (distance < 2 || distance > 400) {
                    distance = -1;
                }
            }
        }
    }

    if (distance != -1) {
        servo_angle = map_distance_to_angle(distance);
        gpioServo(SERVO_PIN, servo_angle);
    }

    if (stop) {
        gpioWrite(SERVO_PIN, 90); // Default servo angle
        gpioTerminate();
        fclose(fp);
        printf("Program terminated by user.\n");
    }
}

int map_distance_to_angle(int distance) {
    if (distance < 2 || distance > 400) {
        return 90;
    }
    double angle = 180.0 * log10(distance / 20.0) / log10(400.0 / 20.0) + 90.0;
    return (int)angle;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin mode.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioServo(SERVO_PIN, 90) < 0) {
        fprintf(stderr, "Failed to set servo to default position.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, alert_callback, NULL) < 0) {
        fprintf(stderr, "Failed to register alert callback.\n");
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(LOG_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    fprintf(fp, LOG_HEADER);
    fflush(fp);

    struct timespec sleep_time = {0, 100000000}; // 100 ms sleep

    while (!stop) {
        gpioWrite(TRIGGER_PIN, 1);
        usleep(10);
        gpioWrite(TRIGGER_PIN, 0);

        nanosleep(&sleep_time, NULL);
    }

    fclose(fp);
    gpioTerminate();
    return 0;
}

