#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define LOG_FILE "proximity.log"
#define MAX_LOG_SIZE 1024 * 1024

static int i2c_fd;
static int gpio_fd;
static int threshold = DEFAULT_THRESHOLD;
static int interrupt_flag = 0;
static int log_fd;
static pthread_t interrupt_thread;

static void log_proximity(int proximity) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s, %d, %s\n", timestamp, proximity, proximity <= threshold ? "SAFE" : "ALERT");

    if (write(log_fd, log_entry, strlen(log_entry)) == -1) {
        perror("Error writing to log file");
    }
}

static void handle_interrupt(void *arg) {
    while (1) {
        if (interrupt_flag) {
            interrupt_flag = 0;
            int proximity_high = gpio_read(gpio_fd);
            int proximity_low = gpio_read(gpio_fd);
            int proximity = (proximity_high << 8) | proximity_low;

            log_proximity(proximity);
        }
        usleep(100000); // Sleep for 100ms
    }
}

static void sigint_handler(int signum) {
    close(i2c_fd);
    close(log_fd);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    if (argc > 1) {
        for (int i = 1; i < argc; i += 2) {
            if (strcmp(argv[i], "-a") == 0) {
                if (sscanf(argv[i + 1], "%x", &i2c_address) != 1) {
                    fprintf(stderr, "Invalid I2C address\n");
                    gpioTerminate();
                    return 1;
                }
            } else if (strcmp(argv[i], "-t") == 0) {
                if (sscanf(argv[i + 1], "%d", &threshold) != 1) {
                    fprintf(stderr, "Invalid threshold\n");
                    gpioTerminate();
                    return 1;
                }
            }
        }
    }

    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) == -1) {
        perror("Error opening I2C device");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) == -1) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if ((gpio_fd = open("/dev/gpiochip0", O_RDWR)) == -1) {
        perror("Error opening GPIO device");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(gpio_fd, GPIOHANDLE_REQUEST, &gpio_handle) == -1) {
        perror("Error requesting GPIO");
        close(gpio_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(gpio_fd, GPIOHANDLE_SET_DIRECTION, &gpio_direction) == -1) {
        perror("Error setting GPIO direction");
        close(gpio_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(gpio_fd, GPIOHANDLE_SET_EDGE_DETECT, &gpio_edge) == -1) {
        perror("Error setting GPIO edge detect");
        close(gpio_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

