#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MIN_DIST 5
#define MAX_DIST 50
#define TIMEOUT 100000

static volatile int running = 1;
static int last_distance = 0;
static int last_frequency = 0;

void sigint_handler(int signum) {
    running = 0;
    gpioHardwarePWM(PWM_PIN, 0, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set echo pin pull-down\n");
        gpioTerminate();
        return 1;
    }

    if (gpioHardwarePWM(PWM_PIN, 0, 0) < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        gpioWrite(TRIGGER_PIN, 0);
        gpioDelay(2);
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        int start_time = gpioTick();
        int end_time = 0;
        int pulse_width = 0;

        while (gpioRead(ECHO_PIN) == 0) {
            if (gpioTick() - start_time > TIMEOUT) {
                fprintf(stderr, "Echo timeout\n");
                last_distance = last_frequency = 0;
                break;
            }
        }

        start_time = gpioTick();

        while (gpioRead(ECHO_PIN) == 1) {
            if (gpioTick() - start_time > TIMEOUT) {
                fprintf(stderr, "Echo timeout\n");
                last_distance = last_frequency = 0;
                break;
            }
        }

        end_time = gpioTick();
        pulse_width = end_time - start_time;

        if (pulse_width > 0) {
            int distance = pulse_width / 58.2; // Convert pulse width to distance in cm
            if (distance >= MIN_DIST && distance <= MAX_DIST) {
                last_distance = distance;
                last_frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);
                last_frequency = (last_frequency < MIN_FREQ) ? MIN_FREQ : ((last_frequency > MAX_FREQ) ? MAX_FREQ : last_frequency);
                gpioHardwarePWM(PWM_PIN, last_frequency, 0);
            } else {
                last_distance = last_frequency = 0;
            }
        }

        printf("Distance: %d cm, Frequency: %d Hz\n", last_distance, last_frequency);
        gpioDelay(10000);
    }

    gpioHardwarePWM(PWM_PIN, 0, 0);
    gpioTerminate();
    return 0;
}

