#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT 500000 // 500 ms in microseconds
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400

static volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int signum) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    gpioSetPullUpDown(ECHO_PIN, PI_PUD_UP);

    signal(SIGINT, handle_sigint);

    while (!exit_flag) {
        gpioWrite(TRIGGER_PIN, 0);
        usleep(2); // Wait for 2 us to ensure the trigger pin is low
        gpioWrite(TRIGGER_PIN, 1);
        usleep(10); // Send a 10 us pulse
        gpioWrite(TRIGGER_PIN, 0);

        int pulse_width = gpioPulseIn(ECHO_PIN, 1, TIMEOUT);

        if (pulse_width == -1) {
            fprintf(stderr, "Timeout waiting for echo pulse\n");
            continue;
        }

        float distance = pulse_width / 2.0 / 29.1;

        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            printf("Invalid reading\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            if (distance < 10.0) {
                printf("Too close!\n");
            }
        }

        usleep(500000); // Wait for 500 ms before the next measurement
    }

    gpioTerminate();
    return 0;
}

