#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_CLOCK_SPEED 1000000
#define SPI_CS_PIN 8
#define REG_CONTINUOUS_MODE 0x01
#define REG_RANGE 0x02
#define REG_TRIGGER 0x00
#define REG_LOW_BYTE 0x0C
#define REG_HIGH_BYTE 0x0D
#define LOG_FILE "distance_log.csv"

static int spiHandle = -1;
static FILE *logFile = NULL;

void sigintHandler(int sig) {
    if (spiHandle != -1) {
        gpio SpiClose(spiHandle);
    }
    if (logFile != NULL) {
        fclose(logFile);
    }
    exit(0);
}

void sigtermHandler(int sig) {
    if (spiHandle != -1) {
        gpio SpiClose(spiHandle);
    }
    if (logFile != NULL) {
        fclose(logFile);
    }
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    if (gpioSetMode(SPI_CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI CS pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(SPI_CS_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set SPI CS pin pull-up\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPI_CHANNEL, PI_ALT0) < 0) {
        fprintf(stderr, "Failed to set SPI channel mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetClockDivider(SPI_CHANNEL, 1) < 0) {
        fprintf(stderr, "Failed to set SPI clock divider\n");
        gpioTerminate();
        return 1;
    }
    if ((spiHandle = gpioSpiOpen(SPI_CHANNEL, SPI_CLOCK_SPEED, 0)) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    if (logFile = fopen(LOG_FILE, "a")) {
        fprintf(logFile, "Timestamp,Distance (mm)\n");
    } else {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigintHandler);
    signal(SIGTERM, sigtermHandler);

    while (1) {
        gpioWrite(SPI_CS_PIN, 0);
        uint8_t tx[3] = {REG_TRIGGER, 0x00, 0x00};
        uint8_t rx[3];
        if (gpioSpiXfer(spiHandle, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
        }
        gpioWrite(SPI_CS_PIN, 1);

        usleep(100000); // 100 ms delay

        gpioWrite(SPI_CS_PIN, 0);
        tx[0] = REG_LOW_BYTE;
        if (gpioSpiXfer(spiHandle, tx, rx, 2) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioWrite(SPI_CS_PIN, 1);
            continue;
        }
        uint16_t distance = (rx[1] << 8) | rx[0];
        gpioWrite(SPI_CS_PIN, 1);

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        if (logFile != NULL) {
            fprintf(logFile, "%s,%d\n", timestamp, distance);
            fflush(logFile);
        }
    }

    fclose(logFile);
    gpioTerminate();
    return 0;
}

