#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SI1120_ADDR 0x60
#define SI1120_RESET_REG 0x30
#define SI1120_PART_ID_REG 0x00
#define SI1120_ALS_LOW_REG 0x22
#define SI1120_ALS_HIGH_REG 0x23
#define SI1120_PS1_LOW_REG 0x18
#define SI1120_PS1_HIGH_REG 0x19

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void sigint_handler(int signum) {
    should_exit = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x60\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByte(i2c_handle, SI1120_RESET_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to reset the Si1120 sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t part_id;
    if (i2cReadByte(i2c_handle, SI1120_PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read part ID from the Si1120 sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (part_id != 0x41) {
        fprintf(stderr, "Incorrect part ID read from the Si1120 sensor (expected 0x41, got 0x%02x)\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file 'si1120_log.txt' for appending\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up SIGINT handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        uint8_t als_low, als_high, ps1_low, ps1_high;
        for (int i = 0; i < 3; i++) {
            if (i2cReadByte(i2c_handle, SI1120_ALS_LOW_REG, &als_low) < 0) {
                fprintf(stderr, "Failed to read ALS low byte from the Si1120 sensor\n");
                continue;
            }
            if (i2cReadByte(i2c_handle, SI1120_ALS_HIGH_REG, &als_high) < 0) {
                fprintf(stderr, "Failed to read ALS high byte from the Si1120 sensor\n");
                continue;
            }
            if (i2cReadByte(i2c_handle, SI1120_PS1_LOW_REG, &ps1_low) < 0) {
                fprintf(stderr, "Failed to read PS1 low byte from the Si1120 sensor\n");
                continue;
            }
            if (i2cReadByte(i2c_handle, SI1120_PS1_HIGH_REG, &ps1_high) < 0) {
                fprintf(stderr, "Failed to read PS1 high byte from the Si1120 sensor\n");
                continue;
            }

            uint16_t als = (als_high << 8) | als_low;
            uint16_t ps1 = (ps1_high << 8) | ps1_low;

            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

            fprintf(log_file, "%s: ALS = %u, PS1 = %u\n", timestamp, als, ps1);
            fflush(log_file);

            usleep(500000); // Sleep for 500 ms
        }
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

