#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x39
#define PART_ID_REG 0x00
#define MEAS_RATE_REG 0x08
#define AMBIENT_LIGHT_REG 0x22
#define PROXIMITY_REG 0x24

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void sig_handler(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize the sensor
    uint8_t part_id[1];
    if (write(i2c_fd, &PART_ID_REG, 1) != 1) {
        perror("Failed to write to PART_ID_REG");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (read(i2c_fd, part_id, 1) != 1) {
        perror("Failed to read from PART_ID_REG");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (part_id[0] != 0x82) {
        fprintf(stderr, "Sensor not found (part ID: 0x%02x)\n", part_id[0]);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    uint8_t meas_rate[1] = {0x07};
    if (write(i2c_fd, &MEAS_RATE_REG, 1) != 1) {
        perror("Failed to write to MEAS_RATE_REG");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (write(i2c_fd, meas_rate, 1) != 1) {
        perror("Failed to write to MEAS_RATE_REG");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    log_file = fopen("biometric_log.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    struct timespec ts;
    while (1) {
        clock_gettime(CLOCK_REALTIME, &ts);

        uint8_t ambient_light[2];
        if (write(i2c_fd, &AMBIENT_LIGHT_REG, 1) != 1) {
            perror("Failed to write to AMBIENT_LIGHT_REG");
            close(i2c_fd);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }
        if (read(i2c_fd, ambient_light, 2) != 2) {
            perror("Failed to read from AMBIENT_LIGHT_REG");
            close(i2c_fd);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }
        uint16_t lux = (ambient_light[0] << 8) | ambient_light[1];
        lux *= 0.1;

        uint8_t proximity[2];
        if (write(i2c_fd, &PROXIMITY_REG, 1) != 1) {
            perror("Failed to write to PROXIMITY_REG");
            close(i2c_fd);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }
        if (read(i2c_fd, proximity, 2) != 2) {
            perror("Failed to read from PROXIMITY_REG");
            close(i2c_fd);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }
        uint16_t proximity_raw = (proximity[0] << 8) | proximity[1];

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03ld", &ts);

        fprintf(log_file, "%s,%f,%u\n", timestamp, lux, proximity_raw);
        printf("%s,%f,%u\n", timestamp, lux, proximity_raw);

        usleep(100000); // Sleep for 100 ms
    }

    close(i2c_fd);
    fclose(log_file);
    return 0;
}

