#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x60
#define I2C_BUS 1
#define MAX_RETRIES 3

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void sig_handler(int signum) {
    should_exit = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    if (log_file = fopen("proximity_log.txt", "a")) {
        fprintf(log_file, "Timestamp,Proximity\n");
    } else {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialisation sequence
    uint8_t init_sequence[] = {
        0x03, 0x07, 0x02, 0x06, 0x00, 0x1A, 0x0B, 0x21,
        0x00, 0x24, 0x49, 0x22, 0x03, 0x0C, 0x0F, 0x0F,
        0x03, 0x11, 0x07, 0x0D, 0x03, 0x80
    };

    for (int i = 0; i < sizeof(init_sequence); i++) {
        int retries = 0;
        while (retries < MAX_RETRIES) {
            if (i2cWriteByteData(i2c_handle, 0x00, init_sequence[i]) >= 0) {
                break;
            }
            retries++;
            fprintf(stderr, "I2C write error at address 0x00, register 0x00, value 0x%02X, retry %d\n", init_sequence[i], retries);
            sleep(1);
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to initialize sensor\n");
            fclose(log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (!should_exit) {
        uint8_t proximity_low, proximity_high;
        int retries = 0;
        while (retries < MAX_RETRIES) {
            if (i2cReadByteData(i2c_handle, 0x16, &proximity_low) >= 0 &&
                i2cReadByteData(i2c_handle, 0x17, &proximity_high) >= 0) {
                break;
            }
            retries++;
            fprintf(stderr, "I2C read error at address 0x16, register 0x16, retry %d\n", retries);
            sleep(1);
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read proximity data\n");
            continue;
        }

        uint16_t proximity = (proximity_high << 8) | proximity_low;
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, "%s,%u\n", timestamp, proximity);
        fflush(log_file);
        sleep(2); // Read every 2 seconds
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

