This C program initializes a Silicon Labs Si1145 proximity sensor on a Raspberry Pi Zero W using the pigpio library. It performs a series of I2C write operations to configure the sensor, then continuously reads the proximity data from the sensor and logs it to a file with a timestamp. The program handles I2C errors and sensor initialisation failures, and provides a clean shutdown mechanism using SIGINT and SIGTERM signals.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define MAX_DISTANCE 20.0
#define SAMPLE_RATE 1000

static volatile int echo_state = 0;
static volatile long long echo_time = 0;
static volatile long long trigger_time = 0;
static volatile int buzzer_state = 0;

static void echo_callback(gpioHandle handle, uint32_t level, uint32_t tick) {
    if (level == 1) {
        echo_time = tick;
    } else {
        echo_state = 1;
        trigger_time = tick;
    }
}

static void handle_sigint(int signum) {
    gpioTerminate();
    printf("Program terminated by user.\n");
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set echo pin alert function.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(10);
        gpioWrite(TRIGGER_PIN, 0);

        while (!echo_state) {
            // Wait for echo to start
        }

        long long pulse_width = echo_time - trigger_time;
        double distance = pulse_width * 0.0343 / 2.0;

        if (distance < MAX_DISTANCE) {
            buzzer_state = 1;
        } else {
            buzzer_state = 0;
        }

        gpioWrite(BUZZER_PIN, buzzer_state);

        printf("Distance: %.2f cm\n", distance);
        gpioDelay(1000000 / SAMPLE_RATE);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

