### Explanation:
- **Pigpio Initialization**: The program initializes the pigpio library and checks for errors.
- **Pin Configuration**: It sets the trigger pin as an output, the echo pin as an input with an alert callback, and the buzzer pin as an output.
- **Echo Callback**: The callback function records the rising and falling edge timestamps of the echo signal.
- **Distance Calculation**: The distance is calculated using the formula `distance = pulse_width * 0.0343 / 2.0`.
- **Buzzer Control**: The buzzer is activated when the distance is below 20 cm.
- **Signal Handling**: The program handles `SIGINT` to terminate pigpio and exit cleanly.
- **Resource Cleanup**: The program terminates pigpio and exits on all exit paths.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18
#define MAX_DISTANCE 200
#define MIN_DISTANCE 20
#define SERVO_MIN_PULSE 500
#define SERVO_MAX_PULSE 2500
#define SERVO_CENTER_PULSE 1500
#define UPDATE_INTERVAL 100000  // 100 ms

static volatile int running = 1;
static volatile double distance = -1.0;
static volatile int servo_angle = 90;

void handle_sigint(int signum) {
    running = 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioServo(SERVO_PIN, SERVO_CENTER_PULSE);
}

void cleanup_gpio() {
    gpioSetMode(TRIGGER_PIN, PI_INPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_INPUT);
    gpioStopServo(SERVO_PIN);
    gpioTerminate();
}

double measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    usleep(10);
    gpioWrite(TRIGGER_PIN, 0);

    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioRead(ECHO_PIN) == 1) {
            return -1.0;  // Echo timeout
        }
    }

    long start = micros();
    while (gpioRead(ECHO_PIN) == 1) {
        if (micros() - start > 5000000) {  // 5 seconds timeout
            return -1.0;  // Echo timeout
        }
    }

    long end = micros();
    long duration = end - start;
    double distance = duration / 58.2;  // Speed of sound is approximately 343 m/s

    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0;  // Out of range
    }

    return distance;
}

void update_servo() {
    int pulse_width = SERVO_MIN_PULSE + (SERVO_MAX_PULSE - SERVO_MIN_PULSE) * (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    signal(SIGINT, handle_sigint);

    setup_gpio();

    while (running) {
        distance = measure_distance();
        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
            update_servo();
        } else {
            printf("Error: Distance out of range or sensor error\n");
        }
        usleep(UPDATE_INTERVAL);
    }

    cleanup_gpio();
    return 0;
}

