This C program uses the pigpio library to control a Raspberry Pi Zero W's GPIO pins for an ultrasonic sensor and an SG90 servo motor. It measures the distance to an object using the HC-SR04 sensor and rotates the servo motor proportionally to the distance. The program handles sensor errors and timeouts, and it gracefully exits on SIGINT.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define SERVO_GPIO 18
#define SERVO_MIN 1000
#define SERVO_MAX 2000
#define HYS 50
#define LOG_FILE "gate_log.txt"

static volatile int running = 1;
static int i2c_handle;
static int servo_handle;

void sigint_handler(int sig) {
    running = 0;
    gpioTerminate();
    close(i2c_handle);
    fclose(log_file);
    printf("Program terminated by user.\n");
    exit(0);
}

int main() {
    struct timespec ts;
    FILE *log_file;
    uint16_t distance;
    uint8_t data[2];
    int model_id;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    // Initialize servo
    servo_handle = gpioServo(SERVO_GPIO, SERVO_MIN);
    if (servo_handle < 0) {
        fprintf(stderr, "Failed to initialize servo on GPIO %d.\n", SERVO_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read model ID
    if (i2cReadReg16(i2c_handle, 0x010F, &model_id) < 0) {
        fprintf(stderr, "Failed to read model ID from register 0x010F.\n");
        gpioServo(SERVO_GPIO, SERVO_MIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Invalid model ID 0x%02X.\n", model_id);
        gpioServo(SERVO_GPIO, SERVO_MIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set timing budget
    if (i2cWriteReg16(i2c_handle, 0x0014, 0x0001) < 0) {
        fprintf(stderr, "Failed to set timing budget.\n");
        gpioServo(SERVO_GPIO, SERVO_MIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start ranging
    if (i2cWriteReg8(i2c_handle, 0x0000, 0x01) < 0) {
        fprintf(stderr, "Failed to start ranging.\n");
        gpioServo(SERVO_GPIO, SERVO_MIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
