This C program initializes the VL53L1X time-of-flight sensor and a servo on a Raspberry Pi 3 Model B+ using the pigpio library. It reads the distance from the sensor, logs open/close events with timestamps, and transitions the servo between 1000 us (closed) and 2000 us (open) pulse widths based on the distance. The program handles I2C read/write errors and ensures clean release of resources on SIGINT.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18
#define TIMEOUT 50000
#define MIN_DISTANCE 20
#define MAX_DISTANCE 400
#define MIN_ANGLE 0
#define MAX_ANGLE 180

static volatile int stop = 0;

void handle_sigint(int signum) {
    stop = 1;
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Program terminated by user.\n");
    exit(EXIT_SUCCESS);
}

int measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    int start = gpioTick();
    int end = gpioTick();

    while (gpioRead(ECHO_PIN) == 0 && gpioTick() - start < TIMEOUT) {
        start = gpioTick();
    }

    while (gpioRead(ECHO_PIN) == 1 && gpioTick() - start < TIMEOUT) {
        end = gpioTick();
    }

    if (end - start < TIMEOUT) {
        return (end - start) * 0.0343 / 2;
    } else {
        return -1.0;
    }
}

int map_distance_to_angle(double distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return (int)((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioSetPullUpDown(ECHO_PIN, PI_PUD_UP);

    signal(SIGINT, handle_sigint);

    while (!stop) {
        double distance = measure_distance();
        if (distance >= 0) {
            int angle = map_distance_to_angle(distance);
            printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);
            gpioServo(SERVO_PIN, angle * 50 + 500);
        } else {
            printf("Distance measurement failed.\n");
        }
        gpioDelay(100000);
    }

    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

