This C program initializes the Raspberry Pi 4 Model B using the pigpio library to implement a parking assist system. It uses an HC-SR04 ultrasonic sensor to measure distances and an SG90 micro servo to indicate the distance visually. The program handles sensor timeouts, invalid distances, and SIGINT (Ctrl+C) to stop the servo and terminate pigpio cleanly.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMIDITY_REG 0x02

static volatile sig_atomic_t quit = 0;

void sigint_handler(int sig) {
    quit = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d, address 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteReg(I2C_BUS, I2C_ADDR, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    usleep(10000); // Wait 10 ms

    while (!quit) {
        uint16_t temp_raw, humidity_raw;

        if (i2cReadReg(I2C_BUS, I2C_ADDR, TEMP_REG, &temp_raw) < 0) {
            fprintf(stderr, "Failed to read temperature register\n");
            i2cClose(I2C_BUS);
            gpioTerminate();
            return 1;
        }

        if (i2cReadReg(I2C_BUS, I2C_ADDR, HUMIDITY_REG, &humidity_raw) < 0) {
            fprintf(stderr, "Failed to read humidity register\n");
            i2cClose(I2C_BUS);
            gpioTerminate();
            return 1;
        }

        float temp = (175.72 * temp_raw) / 65536.0 - 46.85;
        float humidity = (125.0 * humidity_raw) / 65536.0 - 6.0;

        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temp, humidity);

        usleep(2000000); // Wait 2 seconds
    }

    i2cClose(I2C_BUS);
    gpioTerminate();

    return 0;
}

