#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MPU6050_ADDRESS 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define SAMPLE_RATE_DIVIDER 0x19
#define I2C_BUS 1
#define I2C_TIMEOUT 1000

static int i2cHandle;
static volatile sig_atomic_t shouldExit = 0;

void handleSignal(int sig) {
    shouldExit = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);

    // Open I2C bus
    i2cHandle = i2cOpen(I2C_BUS, MPU6050_ADDRESS, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify WHO_AM_I register
    uint8_t whoAmI;
    if (i2cReadByte(i2cHandle, WHO_AM_I) != WHO_AM_I) {
        fprintf(stderr, "MPU-6050 not found at address 0x68\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Reset the device
    if (i2cWriteByte(i2cHandle, PWR_MGMT_1, 0x80) < 0) {
        fprintf(stderr, "Failed to reset MPU-6050\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    usleep(100000); // Wait for stabilization

    // Clear the sleep bit
    if (i2cWriteByte(i2cHandle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to clear sleep bit\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set the sample-rate divider
    if (i2cWriteByte(i2cHandle, SAMPLE_RATE_DIVIDER, 7) < 0) {
        fprintf(stderr, "Failed to set sample-rate divider\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure ACCEL_CONFIG
    if (i2cWriteByte(i2cHandle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure ACCEL_CONFIG\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure GYRO_CONFIG
    if (i2cWriteByte(i2cHandle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to configure GYRO_CONFIG\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Print startup message
    printf("MPU-6050 initialized and running\n");

    // Main loop
    while (!shouldExit) {
        uint8_t data[14];
        if (i2cReadI2CBlockData(i2cHandle, 0x3B, data, 14) < 0) {
            fprintf(stderr, "Failed to read data from MPU-6050\n");
            continue;
        }

        // Parse and print the data
        int16_t accelX = (data[0] << 8) | data[1];
        int16_t accelY = (data[2] << 8) | data[3];
        int16_t accelZ = (data[4] << 8) | data[5];
        int16_t temp = (data[6] << 8) | data[7];
        int16_t gyroX = (data[8] << 8) | data[9];
        int16_t gyroY = (data[10] << 8) | data[11];
        int16_t gyroZ = (data[12] << 8) | data[13];

        printf("Accel: X=%d, Y=%d, Z=%d\n", accelX, accelY, accelZ);
        printf("Temp: %d\n", temp);
        printf("Gyro: X=%d, Y=%d, Z=%d\n", gyroX, gyroY, gyroZ);
        printf("\n");

        usleep(100000); // Wait 100 ms
    }

    // Print clean-shutdown message
    printf("MPU-6050 stopped\n");

    // Close I2C handle and terminate pigpio
    i2cClose(i2cHandle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

