#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define REG_AMBIENT 0x06
#define REG_OBJECT 0x07
#define LOG_FILE "temperature_log.csv"
#define LOG_INTERVAL 5

static int i2c_fd;
static FILE *log_file;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;

static void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    exit(0);
}

static void log_temperature(int ambient, int object) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d,%H:%M:%S", tm);
    fprintf(log_file, "%s,%d,%d\n", timestamp, ambient, object);
}

static int read_temperature(int reg) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write to I2C");
        return -1;
    }
    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Failed to read from I2C");
        return -1;
    }
    return (buffer[0] << 8) | buffer[1];
}

int main() {
    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        perror("Failed to set SIGINT handler");
        exit(1);
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(1);
    }

    if ((gpio_chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(1);
    }

    if ((gpio_line = gpiod_chip_get_line(gpio_chip, 17)) == NULL) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        exit(1);
    }

    if (gpiod_line_request_output(gpio_line, "Temperature Logger", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        exit(1);
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        exit(1);
    }

    fprintf(log_file, "Timestamp,Ambient,Object\n");

    while (1) {
        int ambient = read_temperature(REG_AMBIENT);
        int object = read_temperature(REG_OBJECT);
        if (ambient < 0 || object < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            continue;
        }
        log_temperature(ambient, object);
        gpiod_line_set_value(gpio_line, 1);
        sleep(LOG_INTERVAL);
        gpiod_line_set_value(gpio_line, 0);
        sleep(LOG_INTERVAL);
    }

    fclose(log_file);
    close(i2c_fd);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);

    return 0;
}

