This C program initializes the Raspberry Pi's I2C interface to communicate with a Melexis MLX90614ESF-BAA infrared temperature sensor. It reads the ambient and object temperatures every 5 seconds and logs them to a CSV file named `temperature_log.csv`. The program handles I2C initialization failures, sensor-absent scenarios, file I/O errors, and SIGINT for clean resource release.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define STS30_I2C_ADDR 0x4A
#define I2C_BUS 1
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL 5000000  // 5 seconds in microseconds

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int sig) {
    should_exit = 1;
}

int main() {
    FILE *log_file, *error_log_file;
    int i2c_handle;
    uint16_t data;
    struct timespec sleep_time;
    struct tm *timeinfo;
    char timestamp[20];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STS30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, STS30_I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    // Open log files
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        fprintf(stderr, "Failed to open error log file %s\n", ERROR_LOG_FILE);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    while (!should_exit) {
        // Read temperature data from the sensor
        if (i2cReadWordData(i2c_handle, 0x00) < 0) {
            fprintf(error_log_file, "I2C read error\n");
            fclose(log_file);
            fclose(error_log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Read the temperature data
        if (i2cReadWordData(i2c_handle, 0x00) < 0) {
            fprintf(error_log_file, "I2C read error\n");
            fclose(log_file);
            fclose(error_log_file);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Convert the raw data to temperature
        data = i2cReadWordData(i2c_handle, 0x00);
        float temperature = (data >> 2) * 0.01;

        // Get the current time
        time_t now = time(NULL);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log the temperature and timestamp
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);

        // Sleep for the specified interval
        sleep_time.tv_sec = SAMPLE_INTERVAL / 1000000;
        sleep_time.tv_nsec = SAMPLE_INTERVAL % 1000000;
        nanosleep(&sleep_time, NULL);
    }

    // Clean up resources
    fclose(log_file);
    fclose(error_log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

