#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define CRC8_TABLE_SIZE 256

// Function to calculate CRC-8 checksum
unsigned char crc8(unsigned char *data, int length) {
    unsigned char crc = CRC8_INIT;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
int read_sensor_data(unsigned char *data) {
    int result = piI2cRead(I2C_BUS, I2C_ADDRESS, 0x36, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to send command to sensor\n");
        return -1;
    }
    result = piI2cRead(I2C_BUS, I2C_ADDRESS, 0x08, 9);
    if (result < 0) {
        fprintf(stderr, "Failed to read data from sensor\n");
        return -1;
    }
    // Check CRC-8 checksum
    unsigned char expected_crc = crc8(data, 9);
    if (data[9] != expected_crc) {
        fprintf(stderr, "CRC-8 checksum error\n");
        return -1;
    }
    return 0;
}

// Function to log data to a CSV file
void log_data(const char *timestamp, float pressure, float temperature) {
    FILE *file = fopen("pressure_log.csv", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    fprintf(file, "%s,%f,%f\n", timestamp, pressure, temperature);
    fclose(file);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    piI2cClose(I2C_BUS);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    if (piI2cOpen(I2C_BUS, I2C_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Write header row if the file is new
    FILE *file = fopen("pressure_log.csv", "r");
    if (file == NULL) {
        file = fopen("pressure_log.csv", "w");
        if (file == NULL) {
            fprintf(stderr, "Failed to create file\n");
            piI2cClose(I2C_BUS);
            gpioTerminate();
            return 1;
        }
        fprintf(file, "Timestamp,Pressure (Pa),Temperature (°C)\n");
        fclose(file);
    }

    // Main loop
    while (1) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        unsigned char data[9];
        if (read_sensor_data(data) < 0) {
            continue;
        }

        // Convert raw data to pressure and temperature
        float pressure = (data[0] << 8) | data[1];
        float temperature = (data[2] << 8) | data[3];
        pressure *= 0.01; // Scale factor for pressure
        temperature *= 0.01; // Scale factor for temperature

        // Log data
        log_data(timestamp, pressure, temperature);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    piI2cClose(I2C_BUS);
    gpioTerminate();
    return 0;
}

