#define I2C_BUS 1
#define I2C_ADDR 0x44
#define SHT40_CMD_HIGH_REP 0xFD
#define SHT40_TEMP_OFFSET -45.0
#define SHT40_TEMP_SCALE 175.0
#define SHT40_HUMIDITY_OFFSET 0.0
#define SHT40_HUMIDITY_SCALE 100.0
#define SHT40_CRC_POLY 0x31
#define SHT40_CRC_INIT 0xFF
#define SHT40_LOG_FILE "sht40_log.txt"
#define SHT40_LOG_INTERVAL 5

static int i2c_fd;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

static void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

static void log_reading(double temp, double humidity) {
    struct tm *timeinfo;
    char timestamp[20];
    time_t now = time(NULL);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp, humidity);
}

static void handle_signal(int sig) {
    should_exit = 1;
}

static int calculate_crc8(const unsigned char *data, size_t length) {
    unsigned char crc = SHT40_CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sht40() {
    unsigned char cmd[1] = {SHT40_CMD_HIGH_REP};
    unsigned char data[8];
    int ret;

    // Send command
    ret = write(i2c_fd, cmd, 1);
    if (ret != 1) {
        log_error("Failed to send command");
        return -1;
    }

    // Wait for measurement to complete
    usleep(10000);

    // Read data
    ret = read(i2c_fd, data, 8);
    if (ret != 8) {
        log_error("Failed to read data");
        return -1;
    }

    // Validate CRC
    unsigned char expected_crc = calculate_crc8(data, 6);
    if (data[6] != expected_crc) {
        log_error("CRC mismatch");
        return -1;
    }

    // Convert raw data to temperature and humidity
    double temp = SHT40_TEMP_OFFSET + SHT40_TEMP_SCALE * ((data[0] << 8) | data[1]);
    double humidity = SHT40_HUMIDITY_OFFSET + SHT40_HUMIDITY_SCALE * ((data[3] << 8) | data[4]);

    return 0;
}

static void setup_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
}

static void setup_gpio() {
    // Configure GPIO pins for I2C
    struct gpiod_chip *chip;
    struct gpiod_line *sda, *scl;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    sda = gpiod_chip_get_line(chip, 2);
    scl = gpiod_chip_get_line(chip, 3);
    if (!sda || !scl) {
        log_error("Failed to get GPIO lines");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(sda, "sda", 0);
    if (ret) {
        log_error("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(scl, "scl", 0);
    if (ret) {
        log_error("Failed to request GPIO line");
        gpiod_line_release(sda);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_chip_close(chip);
}

static void setup_logging() {
    log_file = fopen(SHT40_LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

static void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_i2c();
    setup_logging();

    while (!should_exit) {
        if (read_sht40() == 0) {
            log_reading(temp, humidity);
        }
        sleep(SHT40_LOG_INTERVAL);
    }

    cleanup();
    return 0;
}

