#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define TRIGGER_CMD 0x21
#define TRIGGER_CMD_LEN 2
#define READ_CMD 0x03
#define READ_CMD_LEN 1
#define READ_LEN 6
#define LOG_FILE "airflow.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

int main() {
    FILE *log_file;
    int i2c_handle;
    uint8_t buffer[READ_LEN];
    uint8_t retry_count = 0;
    struct timespec sleep_time = {0, 1000000}; // 1 ms

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!exit_flag) {
        // Trigger measurement
        if (i2cWriteDevice(i2c_handle, TRIGGER_CMD, TRIGGER_CMD_LEN) < 0) {
            retry_count++;
            if (retry_count >= MAX_RETRIES) {
                fprintf(stderr, "Failed to trigger measurement after %d retries\n", MAX_RETRIES);
                break;
            }
            nanosleep(&sleep_time, NULL);
            continue;
        }
        retry_count = 0;

        // Wait for measurement to complete
        usleep(1000); // Minimum wait time is 1 ms

        // Read data
        if (i2cReadDevice(i2c_handle, READ_CMD, READ_CMD_LEN, buffer, READ_LEN) < 0) {
            retry_count++;
            if (retry_count >= MAX_RETRIES) {
                fprintf(stderr, "Failed to read data after %d retries\n", MAX_RETRIES);
                break;
            }
            nanosleep(&sleep_time, NULL);
            continue;
        }
        retry_count = 0;

        // Convert raw data to pressure and temperature
        uint16_t raw_pressure = (buffer[0] << 8) | buffer[1];
        uint16_t raw_temperature = (buffer[3] << 8) | buffer[4];

        double pressure_pa = raw_pressure / 60.0;
        double temperature_c = raw_temperature / 200.0;

        // Log data
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%f,%f\n", timestamp, pressure_pa, temperature_c);
        fflush(log_file);

        // Sleep for 100 ms
        nanosleep(&sleep_time, NULL);
    }

    // Close log file
    fclose(log_file);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return EXIT_SUCCESS;
}

