#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define SI7015_ADDR 0x40
#define SI7015_TEMP_CMD 0xF3
#define SI7015_HUM_CMD 0xF5
#define SI7015_READ_CMD 0xE0
#define SI7015_READ_TEMP 0xE3
#define SI7015_READ_HUM 0xE5
#define SI7015_READ_TEMP_HUM 0xE7
#define SI7015_READ_TEMP_HUM_NO_HOLD 0xF3
#define SI7015_READ_HUM_NO_HOLD 0xF5
#define SI7015_READ_TEMP_HUM_NO_HOLD_2 0xF4
#define SI7015_READ_TEMP_HUM_NO_HOLD_3 0xF5
#define SI7015_READ_TEMP_HUM_NO_HOLD_4 0xF6
#define SI7015_READ_TEMP_HUM_NO_HOLD_5 0xF7
#define SI7015_READ_TEMP_HUM_NO_HOLD_6 0xF8
#define SI7015_READ_TEMP_HUM_NO_HOLD_7 0xF9
#define SI7015_READ_TEMP_HUM_NO_HOLD_8 0xFA
#define SI7015_READ_TEMP_HUM_NO_HOLD_9 0xFB
#define SI7015_READ_TEMP_HUM_NO_HOLD_10 0xFC
#define SI7015_READ_TEMP_HUM_NO_HOLD_11 0xFD
#define SI7015_READ_TEMP_HUM_NO_HOLD_12 0xFE
#define SI7015_READ_TEMP_HUM_NO_HOLD_13 0xFF

#define MAX_RETRIES 5
#define SAMPLE_INTERVAL 5000000 // 5 seconds in microseconds

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int signum) {
    exit_flag = 1;
}

void log_reading(double temp, double hum) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp, hum);
    printf("%s,%.2f,%.2f\n", timestamp, temp, hum);
}

void read_sensor(int cmd) {
    uint16_t raw;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_word_data(i2c_handle, SI7015_ADDR, cmd) < 0) {
            fprintf(stderr, "I2C write error: %s\n", pigpio_error(i2c_handle));
            return;
        }

        if (i2c_read_word_data(i2c_handle, SI7015_ADDR, &raw) < 0) {
            fprintf(stderr, "I2C read error: %s\n", pigpio_error(i2c_handle));
            return;
        }

        if (raw & 0x0001) {
            retries++;
            usleep(10000); // Wait for measurement to complete
        } else {
            break;
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Sensor not responding\n");
        exit(EXIT_FAILURE);
    }

    if (cmd == SI7015_TEMP_CMD) {
        double temp = (175.72 * raw / 65536.0) - 46.85;
        log_reading(temp, 0.0);
    } else if (cmd == SI7015_HUM_CMD) {
        double hum = (125.0 * raw / 65536.0) - 6.0;
        log_reading(0.0, hum);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (!exit_flag) {
        read_sensor(SI7015_TEMP_CMD);
        read_sensor(SI7015_HUM_CMD);
        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

