        if (i2c_write_word_data(i2c_handle, SI7015_ADDR, cmd) < 0) {
            fprintf(stderr, "I2C write error: %s\n", pigpio_error(i2c_handle));
            return;
        }

        if (i2c_read_word_data(i2c_handle, SI7015_ADDR, &raw) < 0) {
            fprintf(stderr, "I2C read error: %s\n", pigpio_error(i2c_handle));
            return;
        }

        if (raw & 0x0001) {
            retries++;
            usleep(10000); // Wait for measurement to complete
        } else {
            break;
        }
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Sensor not responding\n");
        exit(EXIT_FAILURE);
    }

    if (cmd == SI7015_TEMP_CMD) {
        double temp = (175.72 * raw / 65536.0) - 46.85;
        log_reading(temp, 0.0);
    } else if (cmd == SI7015_HUM_CMD) {
        double hum = (125.0 * raw / 65536.0) - 6.0;
        log_reading(0.0, hum);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (!exit_flag) {
        read_sensor(SI7015_TEMP_CMD);
        read_sensor(SI7015_HUM_CMD);
        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}
