#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x25
#define CMD_CONT_MEASURE 0x362F
#define CRC8_POLYNOMIAL 0x07
#define CRC8_INIT 0xFF
#define CRC8_UPDATE(c, b) ((c) ^= (b), (c) &= 0xFF, (c) = (c) >> 1 ? (c) ^ CRC8_POLYNOMIAL : (c))

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void log_data(const char *timestamp, float pressure, float temperature) {
    fprintf(log_file, "%s,%f,%f\n", timestamp, pressure, temperature);
}

static void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

static void init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void send_command(int command) {
    if (write(i2c_fd, &command, 2) != 2) {
        perror("Failed to send command");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    usleep(45000); // Wait for 45 ms
}

static void read_data(uint8_t *data) {
    if (read(i2c_fd, data, 9) != 9) {
        perror("Failed to read data");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < length; ++i) {
        crc = CRC8_UPDATE(crc, data[i]);
    }
    return crc;
}

static void validate_crc8(const uint8_t *data, size_t length) {
    uint8_t calculated_crc = calculate_crc8(data, length);
    if (calculated_crc != data[length]) {
        fprintf(stderr, "CRC-8 mismatch for data: ");
        for (size_t i = 0; i < length; ++i) {
            fprintf(stderr, "%02X ", data[i]);
        }
        fprintf(stderr, "\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static float convert_pressure(uint16_t raw_pressure, uint8_t scale_factor) {
    return (float)raw_pressure / scale_factor;
}

static float convert_temperature(uint16_t raw_temperature) {
    return (float)raw_temperature / 200.0f - 45.0f;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c();

    log_file = fopen("airflow_data.txt", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (°C)\n");

    uint8_t data[9];
    uint8_t scale_factor;
    while (1) {
        send_command(CMD_CONT_MEASURE);
        read_data(data);

        validate_crc8(data, 3);
        uint16_t raw_pressure = (data[0] << 8) | data[1];
        validate_crc8(data + 3, 3);
        uint16_t raw_temperature = (data[3] << 8) | data[4];
        validate_crc8(data + 6, 3);
        scale_factor = data[6];

        float pressure = convert_pressure(raw_pressure, scale_factor);
        float temperature = convert_temperature(raw_temperature);

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        log_data(timestamp, pressure, temperature);

        usleep(100000); // Log every 100 ms
    }

    fclose(log_file);
    close(i2c_fd);

    return 0;
}

