#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define STS30_I2C_ADDR 0x4A
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF
#define READ_LENGTH 3
#define DELAY_MS 15
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

static volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int signum) {
    exit_flag = 1;
}

int calculate_crc8(const unsigned char *data, size_t length) {
    unsigned char crc = CRC8_INITIAL;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            crc = (crc & 0x80) ? (crc << 1) ^ CRC8_POLYNOMIAL : (crc << 1);
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (!error_log_file) {
        fprintf(stderr, "Failed to open error log file %s\n", ERROR_LOG_FILE);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (pigpio_i2c_open(1, STS30_I2C_ADDR, 0) < 0) {
        fprintf(error_log_file, "Failed to open I2C bus 1 at address 0x4A\n");
        fclose(log_file);
        fclose(error_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(error_log_file, "Failed to set SIGINT handler\n");
        fclose(log_file);
        fclose(error_log_file);
        pigpio_i2c_close(1, STS30_I2C_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!exit_flag) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        if (pigpio_i2c_write_byte(1, STS30_I2C_ADDR, 0x2C06) < 0) {
            fprintf(error_log_file, "Failed to write command 0x2C06 to STS30 at %s\n", timestamp);
            continue;
        }

        usleep(DELAY_MS * 1000);

        unsigned char data[READ_LENGTH];
        if (pigpio_i2c_read(1, STS30_I2C_ADDR, data, READ_LENGTH) < 0) {
            fprintf(error_log_file, "Failed to read data from STS30 at %s\n", timestamp);
            continue;
        }

        unsigned char crc = calculate_crc8(data, READ_LENGTH - 1);
        if (crc != data[READ_LENGTH - 1]) {
            fprintf(error_log_file, "CRC mismatch for data read from STS30 at %s\n", timestamp);
            continue;
        }

        int raw = (data[0] << 8) | data[1];
        float temperature = -45 + 175 * (raw / 65535.0);

        fprintf(log_file, "%s,%.2f\n", timestamp, temperature);

        usleep(5000000); // Wait 5 seconds before next reading
    }

    fclose(log_file);
    fclose(error_log_file);
    pigpio_i2c_close(1, STS30_I2C_ADDR);
    gpioTerminate();

    return EXIT_SUCCESS;
}

