#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define SHT40_CMD_HIGH_REP 0xFD
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define LOG_FILE "sht40_log.txt"
#define LOG_INTERVAL 5

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

static void log_data(double temp, double humidity) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp, humidity);
}

static void handle_sigint(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

static void calculate_crc8(const unsigned char *data, int length) {
    unsigned char crc = CRC8_INIT;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
}

static int validate_crc8(const unsigned char *data, int length) {
    unsigned char crc = CRC8_INIT;
    for (int i = 0; i < length - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc == data[length - 1];
}

static int read_sht40() {
    unsigned char cmd[1] = {SHT40_CMD_HIGH_REP};
    unsigned char data[6];
    int ret;

    // Write command
    ret = write(i2c_fd, cmd, 1);
    if (ret != 1) {
        log_error("Failed to write command");
        return -1;
    }

    // Wait for 8.5 ms
    usleep(8500);

    // Read data
    ret = read(i2c_fd, data, 6);
    if (ret != 6) {
        log_error("Failed to read data");
        return -1;
    }

    // Validate CRC
    if (!validate_crc8(data, 6)) {
        log_error("CRC validation failed");
        return -1;
    }

    // Convert raw data
    double temp = -45 + 175 * data[0] / 65535.0;
    double humidity = 100 * data[3] / 65535.0;

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        log_error("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Log header
    fprintf(log_file, "Timestamp, Temperature (°C), Humidity (%)\n");

    while (1) {
        if (read_sht40() == 0) {
            log_data(temp, humidity);
        }
        sleep(LOG_INTERVAL);
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

