#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define FAN_PIN 18
#define BUFFER_SIZE 60
#define RETRIES 3
#define HUMIDITY_THRESHOLD 28.0
#define TEMPERATURE_THRESHOLD 27.0

typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

void handle_sigint(int signum) {
    printf("Received SIGINT, shutting down...\n");
    gpioWrite(FAN_PIN, 0); // Turn off the fan
    gpioI2cClose(0); // Close the I2C handle
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

void log_reading(Reading reading) {
    printf("Timestamp: %s, Temperature: %.2f °C, Humidity: %.2f %%\n",
           ctime(&reading.timestamp), reading.temperature, reading.humidity);
}

void read_sensor(int retries) {
    int i;
    uint16_t raw_temp, raw_humidity;
    int result;

    for (i = 0; i < retries; i++) {
        result = gpioI2cReadReg16(0, 0xE3); // Read temperature
        if (result == PI_I2C_ERROR) {
            printf("I2C read error (temperature): %s\n", gpioI2cErrmsg(0));
            continue;
        }
        raw_temp = result;

        result = gpioI2cReadReg16(0, 0xE5); // Read humidity
        if (result == PI_I2C_ERROR) {
            printf("I2C read error (humidity): %s\n", gpioI2cErrmsg(0));
            continue;
        }
        raw_humidity = result;

        // Convert raw values to temperature and humidity
        float temperature = 175.72 * raw_temp / 65536.0 - 46.85;
        float humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

        // Log the reading
        Reading reading = {time(NULL), temperature, humidity};
        buffer[buffer_index] = reading;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        buffer_count = (buffer_count + 1) % BUFFER_SIZE;

        // Print the reading
        log_reading(reading);

        // Check if the fan should be turned on or off
        if (temperature > TEMPERATURE_THRESHOLD) {
            gpioWrite(FAN_PIN, 1); // Turn on the fan
        } else if (temperature < TEMPERATURE_THRESHOLD) {
            gpioWrite(FAN_PIN, 0); // Turn off the fan
        }

        // Wait for 10 ms
        usleep(10000);

        break; // Exit the loop if successful
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for fan\n");
        gpioTerminate();
        return 1;
    }

    if (gpioI2cOpen(0, I2C_ADDR, I2C_BUS) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        read_sensor(RETRIES);
        sleep(2); // Wait for 2 seconds
    }

    gpioI2cClose(0); // Close the I2C handle
    gpioTerminate(); // Terminate pigpio

    return 0;
}

