#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define SCD40_START_PERIODIC 0x21B1
#define SCD40_STOP_PERIODIC 0x3F86
#define SCD40_DATA_READY 0xE4B8
#define SCD40_READ_DATA 0xEC05
#define SCD40_CRC_POLY 0x31
#define SCD40_CRC_INIT 0xFF

#define LOG_FILE "air_quality.log"
#define LOG_FORMAT "%lu,%d,%d,%d\n"

static volatile sig_atomic_t quit = 0;

void sigint_handler(int sig) {
    quit = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x62\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByte(i2c_handle, SCD40_START_PERIODIC) < 0) {
        fprintf(stderr, "Failed to send Start Periodic Measurement command\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct timespec sleep_time = {1, 0}; // 1 second
    nanosleep(&sleep_time, NULL);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (!quit) {
        if (i2cWriteByte(i2c_handle, SCD40_DATA_READY) < 0) {
            fprintf(stderr, "Failed to send Data Ready check command\n");
            continue;
        }

        uint8_t data_ready = i2cReadByte(i2c_handle);
        if (data_ready != 0x01) {
            fprintf(stderr, "Data Ready flag not set\n");
            continue;
        }

        uint8_t data[9];
        if (i2cReadBlockData(i2c_handle, SCD40_READ_DATA, data, 9) < 0) {
            fprintf(stderr, "Failed to read data\n");
            continue;
        }

        uint8_t crc = data[8];
        for (int i = 0; i < 8; i += 2) {
            uint8_t word = (data[i] << 8) | data[i + 1];
            uint8_t calculated_crc = crc8(word, SCD40_CRC_POLY, SCD40_CRC_INIT);
            if (calculated_crc != crc) {
                fprintf(stderr, "CRC check failed for word 0x%04X\n", word);
                continue;
            }
        }

        uint16_t co2 = (data[0] << 8) | data[1];
        int16_t temperature = (int16_t)((data[2] << 8) | data[3]) * 175 / 65535 - 45;
        uint16_t humidity = (data[4] << 8) | data[5] * 100 / 65535;

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, LOG_FORMAT, now, co2, temperature, humidity);

        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

uint8_t crc8(uint16_t word, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (int i = 0; i < 16; i++) {
        crc ^= (word >> i) & 1;
        for (int j = 0; j < 8; j++) {
            if (crc & 1) {
                crc = (crc >> 1) ^ poly;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

