#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TMP05_GPIO 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 5000000 // 5 seconds in microseconds
#define TIMEOUT 50000 // 50 ms timeout in microseconds
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0

static volatile int running = 1;
static int sensor_present = 1;
static int consecutive_failures = 0;

void handle_signal(int sig) {
    running = 0;
    if (sig == SIGTERM) {
        printf("Received SIGTERM, exiting...\n");
    } else if (sig == SIGINT) {
        printf("Received SIGINT, exiting...\n");
    }
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

void log_temperature(double temp) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f\n", timestamp, temp);
    fflush(log_file);
}

double read_temperature() {
    uint32_t start = gpioTick();
    uint32_t end = start;
    uint32_t high_pulse = 0;
    uint32_t total_cycle = 0;

    while (running) {
        if (gpioRead(TMP05_GPIO) == 0) {
            start = gpioTick();
            while (gpioRead(TMP05_GPIO) == 0 && gpioTick() - start < TIMEOUT) {
                // Wait for the low pulse to end
            }
            end = gpioTick();
            if (end - start > TIMEOUT) {
                sensor_present = 0;
                return -1;
            }
            high_pulse = end - start;
            break;
        }
        if (gpioRead(TMP05_GPIO) == 1) {
            start = gpioTick();
            while (gpioRead(TMP05_GPIO) == 1 && gpioTick() - start < TIMEOUT) {
                // Wait for the high pulse to end
            }
            end = gpioTick();
            if (end - start > TIMEOUT) {
                sensor_present = 0;
                return -1;
            }
            total_cycle = end - start;
            break;
        }
    }

    if (total_cycle == 0) {
        return -1;
    }

    double temp = 4215.0 - (2143.0 * high_pulse / total_cycle);
    if (temp < MIN_TEMP || temp > MAX_TEMP) {
        consecutive_failures++;
        if (consecutive_failures >= 3) {
            log_temperature(-1.0);
            fprintf(log_file, "SENSOR MALFUNCTION\n");
            fclose(log_file);
            gpioTerminate();
            exit(0);
        }
    } else {
        consecutive_failures = 0;
        log_temperature(temp);
    }

    return temp;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TMP05_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        double temp = read_temperature();
        if (temp == -1.0) {
            if (sensor_present) {
                fprintf(stderr, "Sensor absent or stuck line detected\n");
                sensor_present = 0;
            }
        }
        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

