}

double read_temperature() {
    uint32_t start = gpioTick();
    uint32_t end = start;
    uint32_t high_pulse = 0;
    uint32_t total_cycle = 0;

    while (running) {
        if (gpioRead(TMP05_GPIO) == 0) {
            start = gpioTick();
            while (gpioRead(TMP05_GPIO) == 0 && gpioTick() - start < TIMEOUT) {
                // Wait for the low pulse to end
            }
            end = gpioTick();
            if (end - start > TIMEOUT) {
                sensor_present = 0;
                return -1;
            }
            high_pulse = end - start;
            break;
        }
        if (gpioRead(TMP05_GPIO) == 1) {
            start = gpioTick();
            while (gpioRead(TMP05_GPIO) == 1 && gpioTick() - start < TIMEOUT) {
                // Wait for the high pulse to end
            }
            end = gpioTick();
            if (end - start > TIMEOUT) {
                sensor_present = 0;
                return -1;
            }
            total_cycle = end - start;
            break;
        }
    }

    if (total_cycle == 0) {
        return -1;
    }

    double temp = 4215.0 - (2143.0 * high_pulse / total_cycle);
    if (temp < MIN_TEMP || temp > MAX_TEMP) {
        consecutive_failures++;
        if (consecutive_failures >= 3) {
            log_temperature(-1.0);
            fprintf(log_file, "SENSOR MALFUNCTION\n");
            fclose(log_file);
            gpioTerminate();
            exit(0);
        }
    } else {
        consecutive_failures = 0;
        log_temperature(temp);
    }

    return temp;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TMP05_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        double temp = read_temperature();
        if (temp == -1.0) {
            if (sensor_present) {
                fprintf(stderr, "Sensor absent or stuck line detected\n");
                sensor_present = 0;
            }
        }
        usleep(SAMPLE_INTERVAL);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}
