#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL 0xFF
#define CRC8_TABLE_SIZE 256
#define CRC8_TABLE_INIT 0xFF
#define CRC8_TABLE_UPDATE(x, y) (x = (x >> 1) ^ ((x & 1) ? CRC8_POLYNOMIAL : 0))

static int i2c_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;
static FILE *csv_file;

static void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fclose(csv_file);
        close(i2c_fd);
        gpiod_chip_close(gpio_chip);
        exit(EXIT_SUCCESS);
    }
}

static void init_i2c() {
    char i2c_path[20];
    snprintf(i2c_path, sizeof(i2c_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_gpio() {
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    gpio_line = gpiod_chip_get_line(gpio_chip, 17); // Assuming GPIO17 is used for SDA
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(gpio_line, "i2c") < 0) {
        perror("Failed to request GPIO line as input");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        gpiod_line_release(gpio_line);
        exit(EXIT_FAILURE);
    }
}

static void init_csv() {
    csv_file = fopen("airflow.csv", "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        exit(EXIT_FAILURE);
    }
    fprintf(csv_file, "Timestamp,Pressure (Pa),Temperature (°C)\n");
}

static void write_command(uint16_t command) {
    uint8_t buffer[2];
    buffer[0] = (command >> 8) & 0xFF;
    buffer[1] = command & 0xFF;
    if (write(i2c_fd, buffer, 2) != 2) {
        perror("Failed to write command");
        close(i2c_fd);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        fclose(csv_file);
        exit(EXIT_FAILURE);
    }
}

static uint8_t crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC8_TABLE_INIT;
    for (size_t i = 0; i < length; i++) {
        crc = CRC8_TABLE_UPDATE(crc, data[i]);
    }
    return crc;
}

static void read_data(uint8_t *data) {
    if (read(i2c_fd, data, 9) != 9) {
        perror("Failed to read data");
        close(i2c_fd);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        fclose(csv_file);
        exit(EXIT_FAILURE);
    }
}

static void validate_crc(const uint8_t *data) {
    uint8_t calculated_crc = crc8(data, 8);
    if (calculated_crc != data[8]) {
        fprintf(stderr, "CRC mismatch: expected %02X, got %02X\n", data[8], calculated_crc);
        close(i2c_fd);
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(gpio_line);
        fclose(csv_file);
        exit(EXIT_FAILURE);
    }
}

static void convert_data(uint8_t *data, float *pressure, float *temperature) {
    uint16_t raw_pressure = (data[0] << 8) | data[1];
    uint16_t raw_temperature = (data[2] << 8) | data[3];
    float scale_factor = (data[4] << 8) | data[5];
    *pressure = (raw_pressure * 100.0f) / scale_factor;
    *temperature = (raw_temperature * 100.0f) / scale_factor;
}

static void log_data(const struct timespec *timestamp, float pressure, float temperature) {
    fprintf(csv_file, "%ld,%f,%f\n", timestamp->tv_sec, pressure, temperature);
}

static void main() {
    struct timespec timestamp;
    struct sigaction sa;
    uint8_t data[9];
    float pressure, temperature;

    init_i2c();
    init_gpio();
    init_csv();

    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    write_command(CMD_CONTINUOUS_MEASUREMENT);

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &timestamp);
        read_data(data);
        validate_crc(data);
        convert_data(data, &pressure, &temperature);
        log_data(&timestamp, pressure, temperature);
        sleep(1);
    }

    fclose(csv_file);
    close(i2c_fd);
    gpiod_chip_close(gpio_chip);
    gpiod_line_release(gpio_line);
    exit(EXIT_SUCCESS);
}

