This C program initializes the I2C bus and GPIO lines, sets up a CSV file for logging, and continuously reads data from the Sensirion SDP810-125Pa sensor. It handles CRC validation, data conversion, and logging every second. The program gracefully shuts down on SIGINT and SIGTERM, ensuring proper resource cleanup.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

#define SHT35_ADDR 0x44
#define SHT35_CMD 0x2400
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

static void sigint_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (i2c_close(i2c_handle) < 0) {
            fprintf(stderr, "Failed to close I2C handle: %s\n", strerror(errno));
        }
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

static uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < len; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            crc = (crc & 0x80) ? (crc << 1) ^ CRC8_POLYNOMIAL : (crc << 1);
        }
    }
    return crc;
}

static int read_sht35(uint8_t *data) {
    if (i2c_write_byte(i2c_handle, SHT35_CMD) < 0) {
        fprintf(stderr, "Failed to send SHT35 command: %s\n", strerror(errno));
        return -1;
    }
    usleep(15000); // Wait at least 15 ms
    if (i2c_read(i2c_handle, data, 6) < 0) {
        fprintf(stderr, "Failed to read from SHT35: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int validate_crc(const uint8_t *data) {
    uint8_t calculated_crc = crc8(data, 5);
    return calculated_crc == data[5];
}

static void log_reading(const char *timestamp, float temperature, float humidity) {
    FILE *file = fopen("environment.csv", "a");
    if (file == NULL) {
        if (errno == ENOENT || errno == ENOTDIR) {
            file = fopen("environment.csv", "w");
            if (file == NULL) {
                fprintf(stderr, "Failed to create environment.csv: %s\n", strerror(errno));
                return;
            }
            fprintf(file, "timestamp,temperature_c,humidity_pct\n");
        } else {
            fprintf(stderr, "Failed to open environment.csv: %s\n", strerror(errno));
            return;
        }
    }
    fprintf(file, "%s,%f,%f\n", timestamp, temperature, humidity);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (i2cOpen(1, SHT35_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at address 0x44: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    time_t now;
    struct tm *tm_info;
    char timestamp[20];
    float temperature, humidity;

    while (1) {
        now = time(NULL);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

        uint8_t data[6];
        if (read_sht35(data) < 0) {
            continue;
        }

        if (!validate_crc(data)) {
            fprintf(stderr, "CRC validation failed for SHT35 reading\n");
            continue;
        }

        temperature = -45 + 175 * data[0] / 65535.0;
        humidity = 100 * data[1] / 65535.0;

        log_reading(timestamp, temperature, humidity);

        sleep(5); // Sample every 5 seconds
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

