#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define I2C_FILE "/dev/i2c-1"
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0x00
#define MAX_RETRIES 10
#define TIMEOUT_MS 100
#define LOG_FILE "environment.log"
#define HEADER "timestamp,temperature_C,humidity_percent\n"

static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;

static void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    exit(0);
}

static void log_error(const char *message) {
    fprintf(stderr, "ERROR: %s\n", message);
}

static void log_data(const char *timestamp, float temperature, float humidity) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s,%f,%f\n", timestamp, temperature, humidity);
    fclose(log_file);
}

static int calculate_crc8(const unsigned char *data, size_t length) {
    unsigned char crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_i2c_data(unsigned char *data, size_t length) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (read(i2c_fd, data, length) == length) {
            return 0;
        }
        retries++;
        usleep(TIMEOUT_MS * 1000);
    }
    return -1;
}

static int write_i2c_data(const unsigned char *data, size_t length) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(i2c_fd, data, length) == length) {
            return 0;
        }
        retries++;
        usleep(TIMEOUT_MS * 1000);
    }
    return -1;
}

static int read_temperature() {
    unsigned char command = 0xF3;
    unsigned char data[3];
    if (write_i2c_data(&command, 1) != 0) {
        log_error("Failed to write temperature command");
        return -1;
    }
    if (read_i2c_data(data, 3) != 0) {
        log_error("Failed to read temperature data");
        return -1;
    }
    unsigned char crc = calculate_crc8(data, 2);
    if (data[2] != crc) {
        log_error("CRC mismatch for temperature");
        return -1;
    }
    float raw = (data[0] << 8) | data[1];
    return raw;
}

static int read_humidity() {
    unsigned char command = 0xF5;
    unsigned char data[3];
    if (write_i2c_data(&command, 1) != 0) {
        log_error("Failed to write humidity command");
        return -1;
    }
    if (read_i2c_data(data, 3) != 0) {
        log_error("Failed to read humidity data");
        return -1;
    }
    unsigned char crc = calculate_crc8(data, 2);
    if (data[2] != crc) {
        log_error("CRC mismatch for humidity");
        return -1;
    }
    float raw = (data[0] << 8) | data[1];
    return raw;
}

static int read_temperature_and_humidity() {
    unsigned char command = 0xE0;
    unsigned char data[3];
    if (write_i2c_data(&command, 1) != 0) {
        log_error("Failed to write paired reading command");
        return -1;
    }
    if (read_i2c_data(data, 3) != 0) {
        log_error("Failed to read paired reading data");
        return -1;
    }
    unsigned char crc = calculate_crc8(data, 2);
    if (data[2] != crc) {
        log_error("CRC mismatch for paired reading");
        return -1;
    }
    float raw_temperature = (data[0] << 8) | data[1];
    float raw_humidity = (data[2] << 8) | data[3];
    return raw_temperature;
}

static void reset_sensor() {
    unsigned char command = 0xFE;
    if (write_i2c_data(&command, 1) != 0) {
        log_error("Failed to reset sensor");
    }
}

int main() {
    if (signal(SIGINT, sigint_handler) == SIG_ERR) {
        log_error("Failed to set SIGINT handler");
        return 1;
    }
    if (signal(SIGTERM, sigint_handler) == SIG_ERR) {
        log_error("Failed to set SIGTERM handler");
        return 1;
    }

    if ((i2c_fd = open(I2C_FILE, O_RDWR)) < 0) {
        log_error("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if ((gpio_chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        log_error("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    if ((gpio_line = gpiod_chip_get_line(gpio_chip, 2)) == NULL) {
        log_error("Failed to get GPIO line 2");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "sensor_reset", 0) < 0) {
        log_error("Failed to request GPIO line 2 as output");
        gpiod_line_close(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        log_error("Failed to open log file");
        gpiod_line_close(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }
    fprintf(log_file, HEADER);
    fclose(log_file);

    while (1) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        float temperature = read_temperature();
        if (temperature < 0) {
            reset_sensor();
            continue;
        }

        float humidity = read_humidity();
        if (humidity < 0) {
            reset_sensor();
            continue;
        }

        log_data(timestamp, temperature, humidity);

        sleep(5);
    }

    gpiod_line_close(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

