This C program uses the Linux i2c-dev kernel interface to read temperature and humidity from an Adafruit Si7021 sensor on a Raspberry Pi Zero W. It handles errors, retries, and logging, and includes a SIGINT/SIGTERM handler to cleanly exit.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONT_MEAS 0x362F
#define CONV_TIME 1000000 // 1 second in microseconds
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void sig_handler(int sig) {
    should_exit = 1;
}

int crc8(const unsigned char *data, int len) {
    int crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int read_i2c(unsigned char cmd) {
    int ret;
    unsigned char buffer[10];
    unsigned char crc;

    // Write command
    ret = i2c_write_byte(i2c_handle, cmd);
    if (ret < 0) {
        fprintf(stderr, "Error writing command: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion time
    usleep(CONV_TIME);

    // Read 9 bytes: pressure MSB, pressure LSB, CRC, temperature MSB, temperature LSB, CRC, and 3 scale factor bytes
    ret = i2c_read_i2c_block_data(i2c_handle, 0, buffer, 9);
    if (ret < 0) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }

    // Calculate CRC for pressure and temperature
    crc = crc8(buffer, 6);
    if (crc != buffer[6]) {
        fprintf(stderr, "CRC mismatch for pressure\n");
        return -1;
    }
    crc = crc8(buffer + 6, 3);
    if (crc != buffer[9]) {
        fprintf(stderr, "CRC mismatch for temperature\n");
        return -1;
    }

    // Extract pressure and temperature
    int raw_pressure = (buffer[0] << 8) | buffer[1];
    int raw_temperature = (buffer[4] << 8) | buffer[5];

    // Convert pressure and temperature
    float pressure = (float)raw_pressure / buffer[2] - 1000.0;
    float temperature = (float)raw_temperature / 200.0 - 45.0;

    // Log the sample
    if (log_file == NULL) {
        log_file = fopen("airflow.dat", "wb");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }
    fwrite(&pressure, sizeof(float), 1, log_file);
    fwrite(&temperature, sizeof(float), 1, log_file);

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initialising pigpio: %s\n", strerror(errno));
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!should_exit) {
        if (read_i2c(CMD_CONT_MEAS) < 0) {
            break;
        }
        usleep(1000000); // Sample once per second
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

