This C program uses the pigpio library to read differential pressure and temperature from a Sensirion SDP810-500Pa sensor over I2C bus 1 at address 0x25. It continuously measures the sensor, calculates the pressure and temperature, and logs each sample to a binary file named 'airflow.dat'. The program handles sensor-absent and bus-error paths, and uses signal handling for a graceful shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONT_MEAS 0x3603
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define CRC8_UPDATE(c, b) ((c) ^= (b))
#define CRC8_FINAL(c) (c ^ CRC8_INIT)

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t exit_flag = 0;

void sig_handler(int sig) {
    exit_flag = 1;
}

void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file);
}

void calculate_crc8(const unsigned char *data, size_t length) {
    unsigned char crc = CRC8_INIT;
    for (size_t i = 0; i < length; ++i) {
        crc = CRC8_UPDATE(crc, data[i]);
    }
    crc = CRC8_FINAL(crc);
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("pressure_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file 'pressure_log.txt'\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!exit_flag) {
        if (i2cWriteByte(i2c_handle, CMD_CONT_MEAS) < 0) {
            fprintf(stderr, "Failed to send command 0x%02X\n", CMD_CONT_MEAS);
            continue;
        }

        usleep(45000); // Wait for conversion time

        unsigned char buffer[12];
        if (i2cRead(i2c_handle, buffer, 12) < 0) {
            fprintf(stderr, "Failed to read data\n");
            continue;
        }

        unsigned char crc = calculate_crc8(buffer, 9);
        if (crc != buffer[9]) {
            fprintf(stderr, "CRC failure: expected 0x%02X, got 0x%02X\n", crc, buffer[9]);
            continue;
        }

