    if (!log) {
        log_error("Failed to open log file");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    fclose(log);

    while (!should_exit) {
        read_flow();
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    return 0;
}

