#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define LPS33HW_ADDR 0x5D
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1_REG 0x10
#define PRESS_OUT_XL_REG 0x28
#define PRESS_OUT_L_REG 0x29
#define PRESS_OUT_H_REG 0x2A
#define TEMP_OUT_L_REG 0x2B
#define TEMP_OUT_H_REG 0x2C

static volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int signum) {
    exit_flag = 1;
}

int main() {
    FILE *log_file;
    struct tm timeinfo;
    char timestamp[20];
    int i2c_handle;
    uint8_t who_am_i;
    uint8_t ctrl_reg1;
    int32_t pressure;
    int16_t temperature;
    char buffer[100];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open log file
    log_file = fopen("environmental_data.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C handle
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Read WHO_AM_I register
    if (i2cReadReg8(i2c_handle, WHO_AM_I_REG, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != 0xB1) {
        fprintf(stderr, "WHO_AM_I register does not match expected value\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure CTRL_REG1 register
    ctrl_reg1 = 0xB0; // Block data update, 10 Hz output rate, active mode
    if (i2cWriteReg8(i2c_handle, CTRL_REG1_REG, ctrl_reg1) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1 register\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (!exit_flag) {
        // Read pressure
        if (i2cReadReg8(i2c_handle, PRESS_OUT_XL_REG, &buffer[0]) < 0) {
            fprintf(stderr, "Failed to read PRESS_OUT_XL register\n");
            continue;
        }
        if (i2cReadReg8(i2c_handle, PRESS_OUT_L_REG, &buffer[1]) < 0) {
            fprintf(stderr, "Failed to read PRESS_OUT_L register\n");
            continue;
        }
        if (i2cReadReg8(i2c_handle, PRESS_OUT_H_REG, &buffer[2]) < 0) {
            fprintf(stderr, "Failed to read PRESS_OUT_H register\n");
            continue;
        }
        pressure = (buffer[2] << 16) | (buffer[1] << 8) | buffer[0];
        pressure /= 4096.0;

        // Read temperature
        if (i2cReadReg8(i2c_handle, TEMP_OUT_L_REG, &buffer[0]) < 0) {
            fprintf(stderr, "Failed to read TEMP_OUT_L register\n");
            continue;
        }
        if (i2cReadReg8(i2c_handle, TEMP_OUT_H_REG, &buffer[1]) < 0) {
            fprintf(stderr, "Failed to read TEMP_OUT_H register\n");
            continue;
        }
        temperature = (buffer[1] << 8) | buffer[0];
        temperature = 42.5 + temperature / 480.0;

        // Format timestamp
        time(&timeinfo);
        localtime_r(&timeinfo, &timeinfo);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

        // Log reading
        snprintf(buffer, sizeof(buffer), "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
        if (fprintf(log_file, "%s", buffer) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            continue;
        }
        fflush(log_file);

        // Delay for 1 second
        usleep(1000000);
    }

    // Close log file
    fclose(log_file);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

