#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 10
#define LED_PIN 17
#define AVG_TEMP_THRESHOLD 28.0

static int i2c_handle;
static int buffer[BUFFER_SIZE];
static int buffer_index = 0;
static double running_average = 0.0;
static int led_state = 0;
static int running = 1;

static void sig_handler(int signum) {
    running = 0;
    gpioWrite(LED_PIN, 0);
    gpioI2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED mode\n");
        gpioTerminate();
        return 1;
    }

    if ((i2c_handle = gpioI2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        int16_t temp_word;
        if (gpioI2cReadWordData(i2c_handle, TEMP_REG) < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Swap bytes and extract temperature
        temp_word = (temp_word >> 8) | (temp_word << 8);
        double temp_celsius = (temp_word >> 7) / 2.0;

        // Update buffer and running average
        buffer[buffer_index] = temp_celsius;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        running_average = 0.0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            running_average += buffer[i];
        }
        running_average /= BUFFER_SIZE;

        // Turn LED on if average exceeds threshold
        if (running_average > AVG_TEMP_THRESHOLD) {
            led_state = 1;
        } else {
            led_state = 0;
        }
        gpioWrite(LED_PIN, led_state);

        // Sleep for 1 second
        sleep(1);
    }

    gpioWrite(LED_PIN, 0);
    gpioI2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

