    fprintf(stderr, "%s: %s\n", timestamp, message);
}

static int calculate_crc8(const unsigned char *data, int length) {
    int crc = SCD30_CRC_8_INITIAL_VALUE;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc = (crc >> 1) ^ ((crc & 1) ? SCD30_CRC_8_POLYNOMIAL : 0);
        }
    }
    return crc;
}

static int write_command(int handle, const unsigned char *command, int length) {
    int result = i2cWriteDevice(handle, command, length);
    if (result < 0) {
        log_error("Failed to write command to SCD30");
        return -1;
    }
    return 0;
}

static int read_response(int handle, unsigned char *response, int length) {
    int result = i2cReadDevice(handle, response, length);
    if (result < 0) {
        log_error("Failed to read response from SCD30");
        return -1;
    }
    return 0;
}

static int read_measurement(int handle, unsigned char *response) {
    unsigned char command[2] = {measurement_command >> 8, measurement_command & 0xFF};
    if (write_command(handle, command, 2) < 0) {
