    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);
    fprintf(log_file, "%s,%d,%d\n", timestamp, response[0] << 8 | response[1], response[2] << 8 | response[3]);
