        log_error("Data not ready");
        return;
    }
}

static void handle_sensor_error() {
    log_error("Sensor error");
    stop_continuous_measurement();
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

static void handle_crc_mismatch() {
    log_error("CRC mismatch");
