#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x21
#define CMD_START_MEASUREMENT 0x36
#define CMD_READ_DATA 0x2F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

// Function to calculate CRC-8 checksum
unsigned char crc8(const unsigned char *data, size_t len) {
    unsigned char crc = CRC8_INIT;
    for (size_t i = 0; i < len; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to log a reading
void log_reading(const struct timespec *ts, int pressure, int temperature, int scale_factor) {
    printf("Timestamp: %ld.%09ld, Pressure: %d Pa, Temperature: %d C, Scale Factor: %d\n",
           ts->tv_sec, ts->tv_nsec, pressure, temperature, scale_factor);
}

// Signal handler to clean up resources
void signal_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    struct timespec ts;
    int sampling_interval_ms = 1000; // Default sampling interval
    int pressure, temperature, scale_factor;
    int i2c_fd;

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    // Set sampling interval from command-line argument
    if (argc > 1) {
        sampling_interval_ms = atoi(argv[1]);
        if (sampling_interval_ms <= 0) {
            fprintf(stderr, "Invalid sampling interval\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
    }

    // Send start measurement command
    if (i2cWriteByte(i2c_fd, CMD_START_MEASUREMENT) < 0) {
        fprintf(stderr, "Failed to send start measurement command\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Poll for data
    while (1) {
        // Read 9 bytes of data
        if (i2cReadBytes(i2c_fd, (unsigned char *)&pressure, 9) < 0) {
            fprintf(stderr, "Failed to read data from sensor\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Verify CRC-8 checksum
        if (crc8((unsigned char *)&pressure, 3) != pressure & 0xFF ||
            crc8((unsigned char *)&temperature, 3) != temperature & 0xFF ||
            crc8((unsigned char *)&scale_factor, 3) != scale_factor & 0xFF) {
            fprintf(stderr, "CRC-8 checksum error\n");
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Convert raw pressure to pressure in Pascal
        pressure = (pressure >> 4) * 256 + (pressure & 0xF);

        // Log the reading
        clock_gettime(CLOCK_MONOTONIC, &ts);
        log_reading(&ts, pressure, temperature, scale_factor);

        // Wait for the specified sampling interval
        usleep(sampling_interval_ms * 1000);
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

