#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONT_MEAS 0x3615
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF
#define CRC8_CHECKSUM_OFFSET 2
#define CRC8_DATA_OFFSET 0
#define CRC8_LENGTH 3
#define PRESSURE_SCALE_FACTOR_OFFSET 6
#define TEMPERATURE_SCALE_FACTOR_OFFSET 8
#define PRESSURE_SCALE_FACTOR 1000000.0
#define TEMPERATURE_SCALE_FACTOR 200.0

static volatile sig_atomic_t quit = 0;

void sig_handler(int sig) {
    quit = 1;
}

int crc8(const unsigned char *data, int length) {
    int crc = CRC8_INIT;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!quit) {
        if (i2cWriteByte(I2C_BUS, CMD_CONT_MEAS) < 0) {
            fprintf(stderr, "Failed to write command\n");
            continue;
        }

        usleep(45000); // Wait for conversion

        unsigned char buffer[9];
        if (i2cReadBytes(I2C_BUS, buffer, 9) < 0) {
            fprintf(stderr, "Failed to read data\n");
            continue;
        }

