#define TEMPERATURE_SCALE_FACTOR 200.0

static volatile sig_atomic_t quit = 0;

void sig_handler(int sig) {
    quit = 1;
}

int crc8(const unsigned char *data, int length) {
    int crc = CRC8_INIT;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

