    msgs[1].addr = HDC1000_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = HDC1000_TEMP_HUMI_LEN;
    msgs[1].buf = temp_humi_data;
    msgset.msgs = msgs;
    msgset.nmsgs = 2;
    ret = ioctl(i2c_fd, I2C_RDWR, &msgset);
    if (ret < 0) {
        perror("Failed to configure sensor");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Read temperature and humidity
        msgs[0].addr = HDC1000_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = 1;
        msgs[0].buf = &HDC1000_TEMP_REG;
        msgs[1].addr = HDC1000_ADDR;
        msgs[1].flags = I2C_M_RD;
        msgs[1].len = HDC1000_TEMP_HUMI_LEN;
        msgs[1].buf = temp_humi_data;
        msgset.msgs = msgs;
        msgset.nmsgs = 2;
        ret = ioctl(i2c_fd, I2C_RDWR, &msgset);
        if (ret < 0) {
            perror("Failed to read temperature and humidity");
            continue;
        }

        // Convert raw data to temperature and humidity
        uint16_t raw_temp = (temp_humi_data[0] << 8) | temp_humi_data[1];
        uint16_t raw_humi = (temp_humi_data[2] << 8) | temp_humi_data[3];
        temperature = (raw_temp / 65536.0) * HDC1000_TEMP_SCALE + HDC1000_TEMP_OFFSET;
        humidity = (raw_humi / 65536.0) * HDC1000_HUMI_SCALE;

        // Log the readings
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

