This C program uses the Linux i2c-dev API to communicate with a Texas Instruments HDC1000 sensor on I2C bus 1. It configures the sensor to perform a 14-bit temperature and humidity measurement, reads the data, and logs the results every 5 seconds. The program handles errors and exits cleanly on SIGINT and SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define TEMP_REG 0xF3
#define TEMP_READ_DELAY 5000000 // 5 seconds in microseconds

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    int i2c_handle;
    int temp;
    char buffer[2];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDRESS);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (keep_running) {
        // Read temperature from the sensor
        if (i2cWriteByte(i2c_handle, TEMP_REG) < 0) {
            fprintf(stderr, "Failed to write to temperature register\n");
            goto cleanup;
        }

        if (i2cRead(i2c_handle, buffer, 2) < 0) {
            fprintf(stderr, "Failed to read temperature data\n");
            goto cleanup;
        }

        // Convert the 16-bit temperature data to Celsius
        temp = (buffer[0] << 8) | buffer[1];
        temp = (temp >> 4) * 0.0625;

        // Log the temperature
        printf("Temperature: %.2f°C\n", temp);

        // Wait for 5 seconds
        usleep(TEMP_READ_DELAY);
    }

cleanup:
    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

