#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MLX90833_ADDR 0x60
#define I2C_BUS 1
#define I2C_READ_LEN 2
#define I2C_WRITE_LEN 1
#define I2C_READ_REG 0x00
#define I2C_WRITE_REG 0x01

static volatile sig_atomic_t quit = 0;

void signal_handler(int sig) {
    quit = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (pigpio_i2c_open(I2C_BUS, MLX90833_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec sleep_time = {0, 500000000}; // 500 ms

    while (!quit) {
        uint8_t data[I2C_READ_LEN];
        if (pigpio_i2c_read(I2C_BUS, MLX90833_ADDR, I2C_READ_REG, I2C_READ_LEN, data) < 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        uint16_t pressure = (data[0] << 8) | data[1];
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        printf("%s: Pressure = %d Pa\n", timestamp, pressure);

        nanosleep(&sleep_time, NULL);
    }

    if (pigpio_i2c_close(I2C_BUS) < 0) {
        fprintf(stderr, "Failed to close I2C bus\n");
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

