#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x63
#define CALIBRATION_COMMAND 0x50
#define MEASUREMENT_COMMAND 0x40
#define MEASUREMENT_DELAY 7
#define MEASUREMENT_INTERVAL 5

static int i2c_handle;
static int gpio_handle;
static int calibration_coefficients[8];
static double scale_factor_lut[256];
static double scale_factor_h;
static double scale_factor_p;

static void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpioTerminate();
        close(i2c_handle);
        exit(EXIT_SUCCESS);
    }
}

static void read_calibration_coefficients() {
    int result = i2c_write_byte_data(i2c_handle, CALIBRATION_COMMAND, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to read calibration coefficients: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    result = i2c_read_i2c_block_data(i2c_handle, 0, 8, calibration_coefficients);
    if (result < 0) {
        fprintf(stderr, "Failed to read calibration coefficients: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Compute scale factors from calibration coefficients
    scale_factor_lut[0] = calibration_coefficients[0];
    scale_factor_lut[255] = calibration_coefficients[1];
    for (int i = 1; i < 255; i++) {
        scale_factor_lut[i] = (calibration_coefficients[2 + i] - calibration_coefficients[2]) / 255.0;
    }
    scale_factor_h = calibration_coefficients[256];
    scale_factor_p = calibration_coefficients[257];
}

static void read_pressure_temperature() {
    int result = i2c_write_byte_data(i2c_handle, MEASUREMENT_COMMAND, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %s\n", strerror(errno));
        return;
    }

    usleep(MEASUREMENT_DELAY * 1000);

    result = i2c_read_i2c_block_data(i2c_handle, 0, 6, (uint8_t *) &temperature);
    if (result < 0) {
        fprintf(stderr, "Failed to read measurement: %s\n", strerror(errno));
        return;
    }

    if (temperature == 0xFF || pressure == 0xFF) {
        fprintf(stderr, "Sensor absent or communication error\n");
        return;
    }

    // Apply compensation formulas
    temperature = (temperature * scale_factor_lut[temperature >> 4] + scale_factor_h) / 100.0;
    pressure = (pressure * scale_factor_lut[pressure >> 4] + scale_factor_p) / 100.0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    gpio_handle = gpioGetGpioPinNumber(21); // Assuming SDA is GPIO 21

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);

    read_calibration_coefficients();

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
