    if (signum == SIGINT || signum == SIGTERM) {
        gpioTerminate();
        close(i2c_handle);
        exit(EXIT_SUCCESS);
    }
}

static void read_calibration_coefficients() {
    int result = i2c_write_byte_data(i2c_handle, CALIBRATION_COMMAND, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to read calibration coefficients: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    result = i2c_read_i2c_block_data(i2c_handle, 0, 8, calibration_coefficients);
    if (result < 0) {
        fprintf(stderr, "Failed to read calibration coefficients: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Compute scale factors from calibration coefficients
    scale_factor_lut[0] = calibration_coefficients[0];
    scale_factor_lut[255] = calibration_coefficients[1];
    for (int i = 1; i < 255; i++) {
        scale_factor_lut[i] = (calibration_coefficients[2 + i] - calibration_coefficients[2]) / 255.0;
    }
    scale_factor_h = calibration_coefficients[256];
    scale_factor_p = calibration_coefficients[257];
}

static void read_pressure_temperature() {
    int result = i2c_write_byte_data(i2c_handle, MEASUREMENT_COMMAND, 0);
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %s\n", strerror(errno));
        return;
    }

    usleep(MEASUREMENT_DELAY * 1000);

    result = i2c_read_i2c_block_data(i2c_handle, 0, 6, (uint8_t *) &temperature);
