#define PRESSURE_LSB 0xAB
#define SCALE_FACTOR 0.1

static int i2c_fd;
static volatile sig_atomic_t should_exit = 0;

void sig_handler(int sig) {
    should_exit = 1;
}

int main() {
    struct timespec sleep_time = {0, 1000000000}; // 1 second
    char i2c_path[20];
    int ret;

    // Set up signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open I2C device
    snprintf(i2c_path, sizeof(i2c_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        struct timespec start_time, end_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Trigger measurement
        ret = write(i2c_fd, NULL, 0);
        if (ret < 0) {
            perror("Failed to trigger measurement");
            continue;
        }

        // Read pressure registers
        uint8_t msb, lsb;
        ret = read(i2c_fd, &msb, 1);
        if (ret < 0) {
            perror("Failed to read MSB");
            continue;
        }
        ret = read(i2c_fd, &lsb, 1);
        if (ret < 0) {
            perror("Failed to read LSB");
            continue;
        }

        // Convert raw value to kPa
        uint16_t raw_value = (msb << 8) | lsb;
        double pressure_kpa = raw_value * SCALE_FACTOR;

        // Log reading with timestamp
        struct tm *timeinfo;
        time_t now = time(NULL);
        timeinfo = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("%s: Pressure = %.2f kPa\n", timestamp, pressure_kpa);

        // Sleep for 1 second
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        long elapsed_ns = (end_time.tv_sec - start_time.tv_sec) * 1000000000 + (end_time.tv_nsec - start_time.tv_nsec);
        if (elapsed_ns < sleep_time.tv_nsec) {
            nanosleep(&sleep_time, NULL);
        }
    }

    // Close I2C device
    close(i2c_fd);

    return EXIT_SUCCESS;
}

