#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONT_MEAS 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define CRC8_TABLE_SIZE 256
#define CRC8_TABLE_INIT 0x00

static unsigned char crc8_table[CRC8_TABLE_SIZE];

void init_crc8_table() {
    for (int i = 0; i < CRC8_TABLE_SIZE; i++) {
        unsigned char crc = i;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
        crc8_table[i] = crc;
    }
}

unsigned char crc8(const unsigned char *data, int length) {
    unsigned char crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < length; i++) {
        crc = crc8_table[(crc ^ data[i]) & 0xFF];
    }
    return crc;
}

void log_data(const char *timestamp, float pressure, float temperature) {
    FILE *file = fopen("pressure_log.txt", "a");
    if (file == NULL) {
        perror("Failed to open pressure_log.txt");
        return;
    }
    fprintf(file, "%s,%f,%f\n", timestamp, pressure, temperature);
    fclose(file);
}

void handle_signal(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    close(i2c_fd);
    exit(0);
}

int main() {
    init_crc8_table();
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    unsigned char cmd[2] = {CMD_CONT_MEAS >> 8, CMD_CONT_MEAS & 0xFF};
    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Failed to send command");
        close(i2c_fd);
        return 1;
    }

    usleep(45000); // Wait 45 ms

    unsigned char data[9];
    if (read(i2c_fd, data, 9) != 9) {
        perror("Failed to read data");
        close(i2c_fd);
        return 1;
    }

    unsigned char crc = crc8(data, 9);
    if (crc != data[8]) {
        fprintf(stderr, "CRC mismatch: expected %02X, got %02X\n", crc, data[8]);
        close(i2c_fd);
        return 1;
    }

    float pressure = data[0] << 16 | data[1] << 8 | data[2];
    float temperature = data[3] << 16 | data[4] << 8 | data[5];

    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    log_data(timestamp, pressure / 60.0, temperature / 200.0);

    close(i2c_fd);
    return 0;
}

