#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONT_MEASURE 0x36
#define CMD_READ_DATA 0x2F
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define CRC_SHIFT 8
#define CRC_MASK 0xFF

static int i2c_fd;
static FILE *log_file;

static void log_pressure(double pressure) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%f\n", timestamp, pressure);
}

static int crc8(const unsigned char *data, int len) {
    int crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < CRC_SHIFT; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_pressure() {
    int ret;
    unsigned char cmd[2] = {CMD_CONT_MEASURE, 0};
    unsigned char data[4];
    unsigned char crc;

    // Trigger continuous measurement
    ret = i2c_write(i2c_fd, cmd, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to trigger measurement: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete
    usleep(8000);

    // Read data
    ret = i2c_read(i2c_fd, data, 3);
    if (ret < 0) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }

    // Calculate CRC
    crc = crc8(data, 2);

    // Verify CRC
    if (crc != data[2]) {
        fprintf(stderr, "CRC mismatch: expected 0x%02X, got 0x%02X\n", data[2], crc);
        return -1;
    }

    // Convert raw data to pressure in Pa
    int raw = (data[0] << 8) | data[1];
    double pressure = (double)raw / 60.0;

    return 0;
}

static void handle_sigint(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        i2c_close(i2c_fd);
    }
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    if (access("airflow_log.csv", F_OK) == -1) {
        log_file = fopen("airflow_log.csv", "w");
        if (!log_file) {
            fprintf(stderr, "Failed to create log file: %s\n", strerror(errno));
            gpioTerminate();
            return 1;
        }
        fprintf(log_file, "Timestamp,Pressure (Pa)\n");
    } else {
        log_file = fopen("airflow_log.csv", "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            gpioTerminate();
            return 1;
        }
    }

    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (1) {
        if (read_pressure() == 0) {
            log_pressure(pressure);
        }
        usleep(1000000);
    }

    fclose(log_file);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

