#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x27
#define MAX_LOG_SIZE 1024 * 1024 // 1 MB

static FILE *log_file;
static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int signum) {
    keep_running = 0;
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpioSetMode(I2C_BUS, PI_ALT0); // Set I2C bus to ALT0 mode

    log_file = fopen("environmental_data.log", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    struct timespec sleep_time = {0, 500000000}; // 5 seconds

    while (keep_running) {
        uint8_t buffer[4];
        int result;

        // Trigger measurement
        result = i2cWriteByte(I2C_BUS, I2C_ADDR, 0x00);
        if (result < 0) {
            fprintf(stderr, "Failed to write to sensor: %d\n", result);
            continue;
        }

        // Wait for measurement to complete
        nanosleep(&sleep_time, NULL);

        // Read 4 bytes
        result = i2cReadBytes(I2C_BUS, I2C_ADDR, buffer, 4);
        if (result < 0) {
            fprintf(stderr, "Failed to read from sensor: %d\n", result);
            continue;
        }

        // Validate sensor status bits
        if ((buffer[0] & 0x01) || (buffer[0] & 0x02)) {
            fprintf(stderr, "Sensor error detected\n");
            continue;
        }

        // Convert raw values
        uint16_t raw_T = (buffer[0] << 8) | buffer[1];
        uint16_t raw_H = (buffer[2] << 8) | buffer[3];
        float temperature = raw_T * 165.0 / 16383.0 - 40.0;
        float humidity = raw_H * 100.0 / 16383.0;

        // Log the reading
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

        // Truncate log file if it exceeds 1 MB
        if (ftell(log_file) > MAX_LOG_SIZE) {
            fseek(log_file, 0, SEEK_SET);
            fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        }

        // Handle log file size
        if (ftell(log_file) > MAX_LOG_SIZE) {
            fprintf(stderr, "Log file size exceeded 1 MB, truncating\n");
            fseek(log_file, 0, SEEK_SET);
            fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        }
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

