            }
            nibble_width = pulse_width;
            while (pulse_width < MAX_NIBBLE_WIDTH * TICK_TIME) {
                pulse_width = gpioTick();
            }
            status_nibble = (status_nibble << 4) | (nibble_width / TICK_TIME);
        }

