        gpioTerminate();
        return 1;
    }

    pressure_log = fopen("pressure_log.txt", "w");
    if (pressure_log == NULL) {
        fprintf(stderr, "Failed to open pressure_log.txt\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    read_pressure();

    fclose(pressure_log);
    gpioTerminate();

    return 0;
}
