#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SHT40_I2C_ADDR 0x44
#define SHT40_CMD_TEMP_HUM 0xFD
#define SHT40_CRC_POLY 0x31
#define SHT40_CRC_INIT 0xFF

static int i2c_handle;
static FILE *log_file;

void sigint_handler(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    pigpio_stop();
    exit(0);
}

int crc8(const unsigned char *data, int len) {
    int crc = SHT40_CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc = (crc >> 1) ^ ((crc & 1) ? SHT40_CRC_POLY : 0);
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    signal(SIGINT, sigint_handler);

    if ((i2c_handle = i2cOpen(1, SHT40_I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (1) {
        unsigned char cmd[] = {SHT40_CMD_TEMP_HUM};
        if (i2cWrite(i2c_handle, cmd, sizeof(cmd)) < 0) {
            fprintf(stderr, "Failed to write command to SHT40\n");
            break;
        }

        usleep(8500); // Wait at least 8.5 ms

        unsigned char data[6];
        if (i2cRead(i2c_handle, data, sizeof(data)) < 0) {
            fprintf(stderr, "Failed to read data from SHT40\n");
            break;
        }

        unsigned char crc_temp = data[2];
        unsigned char crc_hum = data[4];

        if (crc8(data, 2) != crc_temp || crc8(data + 3, 2) != crc_hum) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        float temp = -45 + 175 * ((data[0] << 8) | data[1]) / 65535.0;
        float hum = -6 + 125 * ((data[3] << 8) | data[4]) / 65535.0;

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, "%s, Temperature: %.2f°C, Humidity: %.2f%%RH\n", timestamp, temp, hum);
        fflush(log_file);

        sleep(5); // Read every 5 seconds
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

