code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define LOG_FILE "mag_temp_log.csv"
#define MAX_LOG_SIZE 1024

static volatile sig_atomic_t keep_running = 1;

void handle_sigint(int signum) {
    keep_running = 0;
}

int main() {
    int i2c_handle;
    FILE *log_file;
    char log_entry[MAX_LOG_SIZE];
    struct timespec sleep_time = {1, 0}; // 1 second

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d, address 0x%02X\n", I2C_BUS, I2C_ADDRESS);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if file is newly created
    if (fseek(log_file, 0, SEEK_END) == 0) {
        fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
    }

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    while (keep_running) {
        // Read raw value from sensor
        int raw_value;
        if (i2cReadWordData(i2c_handle, 0x00) < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            continue;
        }

        // Convert raw value to magnetic field (Gauss) and temperature (Celsius)
        double field_gauss = raw_value * 0.1;
        double temp_celsius = raw_value * 0.01 - 25.0;

        // Format log entry
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        strftime(log_entry, MAX_LOG_SIZE, "%Y-%m-%d %H:%M:%S,", tm_info);
        snprintf(log_entry + strlen(log_entry), MAX_LOG_SIZE - strlen(log_entry), "%.2f,%.2f\n", field_gauss, temp_celsius);

        // Write log entry to file
        if (fputs(log_entry, log_file) == EOF) {
            fprintf(stderr, "Failed to write to log file %s\n", LOG_FILE);
        }

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Close log file
    fclose(log_file);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

