This C program initializes the Raspberry Pi's GPIO and sets up a signal handler for SIGINT (Ctrl+C) to ensure proper cleanup. It then opens the I2C bus and attempts to read the temperature from the TMP117 sensor at its default address. If the I2C bus or sensor is not available, it retries up to 3 times before exiting. The temperature is read as a signed 16-bit two's-complement value, converted to Celsius, and logged to a file with the current timestamp. The program handles errors and reinitializes the I2C handle on failure, ensuring robustness and reliability.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define LOG_FILE "flow_log.txt"
#define MAX_RETRIES 3

static int i2c_handle;
static FILE *log_file;

void log_data(double slpm, double celsius) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, slpm, celsius);
    fflush(log_file);
}

void handle_signal(int signum) {
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    pigpio_stop();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    if (i2cOpen(I2C_BUS, I2C_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        uint8_t buffer[4];
        if (i2cReadDevice(i2c_handle, buffer, 4) < 0) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            if (retry == MAX_RETRIES - 1) {
                i2cClose(i2c_handle);
                fclose(log_file);
                gpioTerminate();
                return 1;
            }
            sleep(1);
            continue;
        }
        uint16_t raw_flow = (buffer[0] << 8) | buffer[1];
        uint16_t raw_temp = (buffer[2] << 8) | buffer[3];
        double slpm = ((raw_flow / 16384.0) - 0.1) / 0.8 * 25.0;
        double celsius = ((raw_temp / 4096.0) - 0.1) / 0.8 * 80.0 - 40.0;
        log_data(slpm, celsius);
        sleep(1);
    }

    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

