#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_PIN 4
#define SAMPLE_INTERVAL 2000000 // 2 seconds in microseconds
#define MAX_LOG_SIZE 1024 * 1024 // 1 MB log file size
#define LOG_FILE "dht11_readings.txt"

static FILE *logFile;
static int gpioInitialized = 0;

void logError(const char *message, int status) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(logFile, "%s - Error: %s (Status: %d)\n", timestamp, message, status);
}

void handleSignal(int signum) {
    if (gpioInitialized) {
        gpioTerminate();
    }
    if (logFile) {
        fclose(logFile);
    }
    exit(0);
}

void readDHT11() {
    if (!gpioInitialized) {
        logError("GPIO not initialized", -1);
        return;
    }

    // Pull the line low for at least 18 ms
    gpioWrite(DHT11_PIN, 0);
    usleep(18000);

    // Release the line
    gpioWrite(DHT11_PIN, 1);
    usleep(40);

    // Wait for the sensor to pull the line low
    if (gpioRead(DHT11_PIN) == 1) {
        logError("Sensor did not respond", -2);
        return;
    }

    // Read the 80 us low plus 80 us high response
    for (int i = 0; i < 50; i++) {
        if (gpioRead(DHT11_PIN) == 0) {
            usleep(50);
            if (gpioRead(DHT11_PIN) == 1) {
                // 50 us low pulse
                continue;
            } else {
                // 26-28 us high pulse for '0', 70 us for '1'
                if (i < 40) {
                    // Read the data bits
                    if (i % 2 == 0) {
                        // Even bits (humidity)
                        if (gpioRead(DHT11_PIN) == 1) {
                            // '1'
                            continue;
                        } else {
                            // '0'
                            continue;
                        }
                    } else {
                        // Odd bits (temperature)
                        if (gpioRead(DHT11_PIN) == 1) {
                            // '1'
                            continue;
                        } else {
                            // '0'
                            continue;
                        }
                    }
                } else {
                    // Checksum
                    if (gpioRead(DHT11_PIN) == 1) {
                        // '1'
                        continue;
                    } else {
                        // '0'
                        continue;
                    }
                }
            }
        } else {
            // 40 us low pulse
            continue;
        }
    }

    // Validate the checksum
    unsigned char data[5] = {0};
    for (int i = 0; i < 4; i++) {
        data[i] = (data[i] << 1) | gpioRead(DHT11_PIN);
        usleep(50);
    }
    unsigned char checksum = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (checksum != data[4]) {
        logError("Checksum failed", -3);
        return;
    }

    // Log the temperature and humidity
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(logFile, "%s - Temperature: %.1f°C, Humidity: %.1f%%\n", timestamp, data[2] / 10.0, data[0] / 10.0);

    // Sample every 2 seconds
    usleep(SAMPLE_INTERVAL);
}

int main() {
    if (gpioInitialise() < 0) {
        logError("Failed to initialize GPIO", -4);
        return 1;
    }
    gpioSetMode(DHT11_PIN, PI_INPUT);
    gpioSetPullUpDown(DHT11_PIN, PI_PUD_UP);
    gpioInitialized = 1;

    logFile = fopen(LOG_FILE, "a");
    if (!logFile) {
        logError("Failed to open log file", -5);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);

    while (1) {
        readDHT11();
    }

    fclose(logFile);
    gpioTerminate();
    return 0;
}

