This C program uses the pigpio library to bit-bang the single-wire protocol of a DHT11 temperature/humidity sensor connected to GPIO 4. It handles errors, timeouts, and checksum failures, logging all events to a file. The program samples every 2 seconds and exits gracefully on SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define RAW_PRESSURE_REG 0x0A2C
#define RAW_TEMP_REG 0x0A2E
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define PMIN 0
#define PMAX 800
#define LOG_FILE "pressure_log.txt"

static volatile sig_atomic_t run = 1;

void handle_signal(int sig) {
    run = 0;
}

int main() {
    FILE *log_file;
    int i2c_handle;
    uint16_t raw_pressure, raw_temp;
    float pressure_kPa, temp_C;
    char timestamp[20];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (run) {
        // Read raw pressure
        if (i2cReadWordData(i2c_handle, RAW_PRESSURE_REG) < 0) {
            fprintf(stderr, "Failed to read raw pressure from 0x%02X\n", RAW_PRESSURE_REG);
        } else {
            raw_pressure = i2cReadWordData(i2c_handle, RAW_PRESSURE_REG);
            pressure_kPa = (raw_pressure - OUTPUT_MIN) * (PMAX - PMIN) / (OUTPUT_MAX - OUTPUT_MIN);
        }

        // Read raw temperature
        if (i2cReadWordData(i2c_handle, RAW_TEMP_REG) < 0) {
            fprintf(stderr, "Failed to read raw temperature from 0x%02X\n", RAW_TEMP_REG);
        } else {
            raw_temp = i2cReadWordData(i2c_handle, RAW_TEMP_REG);
            temp_C = raw_temp * 0.01 - 40;
        }

        // Get current timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        // Log results
        fprintf(log_file, "%s, Pressure: %.2f kPa, Temperature: %.1f C\n", timestamp, pressure_kPa, temp_C);

        // Sleep for 2 seconds
        sleep(2);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

