        } else {
            raw_temp = i2cReadWordData(i2c_handle, RAW_TEMP_REG);
            temp_C = raw_temp * 0.01 - 40;
        }

        // Get current timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        // Log results
        fprintf(log_file, "%s, Pressure: %.2f kPa, Temperature: %.1f C\n", timestamp, pressure_kPa, temp_C);

        // Sleep for 2 seconds
        sleep(2);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}
