#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define HYST_ON 28.0
#define HYST_OFF 26.0

static int i2c_handle;
static int gpio_handle;
static int buffer[BUFFER_SIZE];
static int buffer_index = 0;
static double running_average = 0.0;
static int fan_state = 0;

static void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpio_write(gpio_handle, 18, 0); // Turn off the fan
        i2c_close(i2c_handle);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    gpio_handle = gpioOpen(18, 1); // Set GPIO 18 as output for the fan
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to open GPIO 18\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, LM75B_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        uint8_t data[2];
        if (i2cRead(i2c_handle, TEMP_REG, 2, data) < 0) {
            fprintf(stderr, "Failed to read from I2C bus %d at address 0x%02X\n", I2C_BUS, LM75B_ADDR);
            continue;
        }

        int16_t temp_raw = (data[0] << 8) | data[1];
        double temp_celsius = (temp_raw >> 1) * 0.5;

        buffer[buffer_index] = temp_celsius;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        running_average = 0.0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            running_average += buffer[i];
        }
        running_average /= BUFFER_SIZE;

        if (running_average > HYST_ON) {
            if (fan_state == 0) {
                gpioWrite(gpio_handle, 18, 1); // Turn on the fan
                fan_state = 1;
            }
        } else if (running_average < HYST_OFF) {
            if (fan_state == 1) {
                gpioWrite(gpio_handle, 18, 0); // Turn off the fan
                fan_state = 0;
            }
        }

        sleep(1);
    }

    i2c_close(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

