#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONT_MEAS 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define CRC8_UPDATE(c, b) ((c) = ((c) ^ (b)) & 0xFF)

#define LOG_FILE "airflow.log"

static volatile sig_atomic_t quit = 0;

void sig_handler(int sig) {
    quit = 1;
}

int main() {
    int i2c_fd;
    uint8_t cmd[2] = {CMD_CONT_MEAS, 0};
    uint8_t data[10];
    uint8_t crc;
    int16_t pressure, temperature;
    double pressure_pa, temperature_c;
    struct timespec ts;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Send continuous-measurement command
    if (i2cWrite(i2c_fd, cmd, 2) != 2) {
        fprintf(stderr, "Failed to send continuous-measurement command\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Wait for first measurement
    nanosleep(&ts, NULL);

    // Read 9 bytes containing 3 words and CRC
    if (i2cRead(i2c_fd, data, 9) != 9) {
        fprintf(stderr, "Failed to read data from sensor\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Calculate CRC
    crc = CRC8_INIT;
    for (int i = 0; i < 9; i++) {
        crc = CRC8_UPDATE(crc, data[i]);
    }

    // Validate CRC
    if (crc != data[9]) {
        fprintf(stderr, "CRC mismatch\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Convert raw pressure and temperature
    pressure = (data[0] << 8) | data[1];
    temperature = (data[2] << 8) | data[3];
    pressure_pa = (pressure * 60.0) / 32768.0;
    temperature_c = (temperature * 200.0) / 32768.0;

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Log timestamp, pressure, and temperature
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);

    // Print warning if pressure exceeds 5.0 Pa
    if (pressure_pa > 5.0) {
        fprintf(stderr, "Warning: Pressure exceeds 5.0 Pa\n");
    }

    // Close log file
    fclose(log_file);

    // Wait for SIGINT or SIGTERM
    while (!quit) {
        nanosleep(&ts, NULL);
    }

    // Clean up
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

