#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <libgpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_PIN 17
#define HYST 1

static int i2c_fd;
static int led_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;

void handle_sigint(int signum) {
    if (led_fd >= 0) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
        led_fd = -1;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    exit(EXIT_SUCCESS);
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Request line for LED
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Request output mode for LED
    if (gpiod_line_request_output(led_line, "LED", 0) < 0) {
        perror("Failed to request output mode for LED");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read temperature
    uint16_t temp;
    while (1) {
        if (read(i2c_fd, &temp, 2) != 2) {
            perror("Failed to read temperature from I2C");
            close(i2c_fd);
            gpiod_line_release(led_line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Combine MSB and LSB, right-shift by 4 bits, and convert to Celsius
        int16_t celsius = (temp >> 4) * 0.0625;

        // Log temperature
        printf("Temperature: %.2f °C\n", celsius);

        // Drive LED based on temperature
        if (celsius > 28 + HYST) {
            gpiod_line_set_value(led_line, 1);
        } else if (celsius < 27 - HYST) {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

