#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CMD_CONT_MEAS 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

static int gpiod_handle = -1;
static FILE *log_file = NULL;

void log_reading(const char *type, int16_t value) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s %s: %d\n", timestamp, type, value);
}

void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (gpiod_handle != -1) {
        gpioTerminate();
    }
    exit(0);
}

int crc8(const uint8_t *data, size_t length) {
