#define MAX_RETRIES 3
#define MEASURE_RH 0xF5
#define MEASURE_TEMP 0xF3
#define READ_TEMP 0xE0
#define ID_CMD 0xFA
#define ID_LEN 3

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void log_error(const char *fmt, ...) {
    va_list args;
    char buffer[1024];
    time_t now;
    struct tm *tm_info;

    time(&now);
    tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", tm_info);

    va_start(args, fmt);
    vsnprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), fmt, args);
    va_end(args);

    fprintf(stderr, "%s: %s\n", buffer, buffer + strlen(buffer));
    if (log_file) {
        fprintf(log_file, "%s: %s\n", buffer, buffer + strlen(buffer));
        fflush(log_file);
    }
}

void handle_signal(int sig) {
    should_exit = 1;
}

void init_i2c() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void close_i2c() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
}

void read_sensor() {
    uint16_t raw_temp, raw_rh;
    int retries = 0;
    int status;

    while (retries < MAX_RETRIES) {
        status = i2cWriteDevice(i2c_handle, &MEASURE_RH, 1);
        if (status < 0) {
            log_error("Failed to write to I2C device: %d", status);
            retries++;
            continue;
        }

        usleep(20000); // Wait for measurement to complete

        status = i2cReadDevice(i2c_handle, &raw_rh, 2);
        if (status < 0) {
            log_error("Failed to read from I2C device: %d", status);
            retries++;
            continue;
        }

        status = i2cWriteDevice(i2c_handle, &MEASURE_TEMP, 1);
        if (status < 0) {
            log_error("Failed to write to I2C device: %d", status);
            retries++;
            continue;
        }

        usleep(20000); // Wait for measurement to complete

        status = i2cReadDevice(i2c_handle, &raw_temp, 2);
        if (status < 0) {
            log_error("Failed to read from I2C device: %d", status);
            retries++;
            continue;
        }

        break;
    }

    if (retries == MAX_RETRIES) {
        log_error("Failed to read from sensor after %d retries", MAX_RETRIES);
        return;
    }

    float temperature = 175.72 * raw_temp / 65536.0 - 46.85;
    float humidity = 125.0 * raw_rh / 65536.0 - 6.0;
    humidity = fmax(0.0, fmin(humidity, 100.0));

    time_t now;
    struct tm *tm_info;
    char timestamp[20];
    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(stdout, "%s,%f,%f\n", timestamp, temperature, humidity);
    fflush(stdout);

    if (log_file) {
        fprintf(log_file, "%s,%f,%f\n", timestamp, temperature, humidity);
        fflush(log_file);
    }
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        log_error("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }
    if (signal(SIGTERM, handle_signal) == SIG_ERR) {
        log_error("Failed to set SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    init_i2c();

    log_file = fopen("environment.log", "w");
    if (!log_file) {
        log_error("Failed to open log file");
        close_i2c();
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        read_sensor();
        sleep(60);
    }

    close_i2c();
    return 0;
}

