#define HDC1080_TEMP_REG 0x00
#define HDC1080_HUMIDITY_REG 0x01
#define HDC1080_TEMP_RESOLUTION 14
#define HDC1080_HUMIDITY_RESOLUTION 14
#define HDC1080_TEMP_OFFSET -40.0
#define HDC1080_HUMIDITY_OFFSET 0.0
#define HDC1080_TEMP_SCALE 165.0
#define HDC1080_HUMIDITY_SCALE 100.0
#define HDC1080_READ_DELAY 20000 // 20 ms

static int i2c_handle;
static volatile sig_atomic_t should_exit = 0;

void handle_sigint(int sig) {
    should_exit = 1;
}

