    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (i2cHandleOpen(&i2c_handle, HDC1080_I2C_ADDR, 1) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Set configuration register to 14-bit temperature and 14-bit humidity
    uint16_t config = (HDC1080_TEMP_RESOLUTION << 14) | (HDC1080_HUMIDITY_RESOLUTION << 12);
    if (i2cWriteWordData(i2c_handle, HDC1080_CONFIG_REG, config) < 0) {
        fprintf(stderr, "Failed to set configuration register\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    FILE *log_file = fopen("enviro_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (!should_exit) {
        uint16_t temp_raw, humidity_raw;
        if (i2cWriteByteData(i2c_handle, HDC1080_TEMP_REG, 0x00) < 0) {
            fprintf(stderr, "Failed to start temperature conversion\n");
            continue;
