#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define STS40_ADDRESS 0x44
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define CRC8_UPDATE(c, b) ((c) ^= (b))
#define CRC8_FINAL(c) (c ^ CRC8_INIT)

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void sig_handler(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct timespec sleep_time = {0, 10000000}; // 10 ms
    unsigned char command[2] = {0x2C, 0xE0};
    unsigned char data[3];
    unsigned char crc8;
    unsigned int raw;
    double temperature;
    char timestamp[20];

    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, STS40_ADDRESS) == -1) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Send command
    if (write(i2c_fd, command, sizeof(command)) != sizeof(command)) {
        perror("Failed to send command");
        close(i2c_fd);
        return 1;
