#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define SAMPLE_INTERVAL 1000000 // 1 second in microseconds

static volatile sig_atomic_t should_exit = 0;

void sigint_handler(int sig) {
    should_exit = 1;
}

int crc8(const unsigned char *data, int length) {
    int crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc = (crc >> 1) ^ ((crc & 1) ? CRC8_POLYNOMIAL : 0);
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDRESS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen("hvac_pressure_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file hvac_pressure_log.txt\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec sleep_time = {0, SAMPLE_INTERVAL};

    signal(SIGINT, sigint_handler);

    while (!should_exit) {
        // Send continuous-measurement command
        if (i2cWriteByte(i2c_handle, 0x36) < 0) {
            fprintf(stderr, "Failed to send command 0x36\n");
            continue;
        }

        // Wait at least 50 ms
        nanosleep(&sleep_time, NULL);

        // Read 9 bytes: 2 bytes pressure plus 1 CRC, 2 bytes temperature plus 1 CRC, and 3 bytes of scale factor
        unsigned char buffer[9];
        if (i2cRead(i2c_handle, buffer, 9) < 0) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            continue;
        }

        // Validate CRC-8
        int crc = crc8(buffer, 8);
        if (crc != buffer[8]) {
            fprintf(stderr, "CRC-8 error: expected 0x%02X, got 0x%02X\n", buffer[8], crc);
            continue;
        }

        // Convert raw pressure and temperature
        int pressure_raw = (buffer[0] << 8) | buffer[1];
        int temperature_raw = (buffer[2] << 8) | buffer[3];
        float pressure_Pa = (float)pressure_raw / buffer[8];
        float temperature_C = (float)temperature_raw / 200.0;

        // Log the reading
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s,%f,%f\n", timestamp, pressure_Pa, temperature_C);

        // Flush the log file
        fflush(log_file);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

