#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <gpiod.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x62
#define SCD40_START_PERIODIC 0x21B1
#define SCD40_STOP_PERIODIC 0x3F86
#define SCD40_READ_MEASUREMENT 0xE000
#define SCD40_CRC8_POLYNOMIAL 0x31
#define SCD40_CRC8_INITIAL_VALUE 0xFF
#define SCD40_BUFFER_SIZE 100
#define SCD40_LOG_DIR "/var/log/scd40_data/"
#define SCD40_LOG_FILE "scd40_data_%Y%m%d_%H%M%S.csv"
#define SCD40_ERROR_LOG "/var/log/scd40_error.log"

typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} SCD40Reading;

volatile sig_atomic_t running = 1;

static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t buffer_cond = PTHREAD_COND_INITIALIZER;
static SCD40Reading buffer[SCD40_BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_tail = 0;

static void log_error(const char *format, ...) {
    va_list args;
    char buffer[1024];
    time_t now;
    struct tm *tm_info;

    time(&now);
    tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    va_start(args, format);
    vsnprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), format, args);
    va_end(args);

    FILE *log_file = fopen(SCD40_ERROR_LOG, "a");
    if (log_file) {
        fprintf(log_file, "%s: %s\n", buffer, strerror(errno));
        fclose(log_file);
    }
}

static int crc8(const uint8_t *data, size_t length) {
    uint8_t crc = SCD40_CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            crc = (crc >> 1) ^ ((crc & 1) ? SCD40_CRC8_POLYNOMIAL : 0);
        }
    }
    return crc;
}

static int read_scd40(uint8_t *data, size_t length) {
    int result = pigpio_i2c_read_i2c_block_data(pi, SCD40_I2C_ADDR, SCD40_READ_MEASUREMENT, data, length);
    if (result < 0) {
        log_error("Failed to read from SCD40: %s", strerror(errno));
        return -1;
    }
    return result;
}

static int write_scd40(uint8_t command) {
    int result = pigpio_i2c_write_i2c_block_data(pi, SCD40_I2C_ADDR, command, NULL, 0);
    if (result < 0) {
        log_error("Failed to write to SCD40: %s", strerror(errno));
        return -1;
    }
    return result;
}

static void *log_thread(void *arg) {
    while (running) {
        pthread_mutex_lock(&buffer_mutex);
        while (buffer_head == buffer_tail) {
            pthread_cond_wait(&buffer_cond, &buffer_mutex);
        }
        SCD40Reading reading = buffer[buffer_tail];
        buffer_tail = (buffer_tail + 1) % SCD40_BUFFER_SIZE;
        pthread_mutex_unlock(&buffer_mutex);

        char filename[1024];
        time_t now;
        struct tm *tm_info;
        time(&now);
        tm_info = localtime(&now);
        strftime(filename, sizeof(filename), SCD40_LOG_DIR SCD40_LOG_FILE, tm_info);

        FILE *log_file = fopen(filename, "a");
        if (log_file) {
            fprintf(log_file, "%lu,%u,%f,%f\n", reading.timestamp, reading.co2, reading.temperature, reading.humidity);
            fclose(log_file);
        }
    }
    return NULL;
}

static void handle_sigint(int signum) {
    running = 0;
    write_scd40(SCD40_STOP_PERIODIC);
    pthread_join(log_thread, NULL);
    pthread_mutex_lock(&buffer_mutex);
    while (buffer_head != buffer_tail) {
        SCD40Reading reading = buffer[buffer_tail];
        buffer_tail = (buffer_tail + 1) % SCD40_BUFFER_SIZE;
        pthread_mutex_unlock(&buffer_mutex);

        char filename[1024];
        time_t now;
        struct tm *tm_info;
        time(&now);
        tm_info = localtime(&now);
        strftime(filename, sizeof(filename), SCD40_LOG_DIR SCD40_LOG_FILE, tm_info);

        FILE *log_file = fopen(filename, "a");
        if (log_file) {
            fprintf(log_file, "%lu,%u,%f,%f\n", reading.timestamp, reading.co2, reading.temperature, reading.humidity);
            fclose(log_file);
        }
    }
    pthread_mutex_unlock(&buffer_mutex);
    pigpio_i2c_close(pi);
    pigpio_stop(pi);
    exit(0);
}

int main() {
    if (gpiochip_open(1) < 0) {
        log_error("Failed to open I2C bus 1: %s", strerror(errno));
        return 1;
    }
    pi = pigpio_start(NULL, NULL);
    if (pi < 0) {
        log_error("Failed to start pigpio: %s", strerror(errno));
        gpiochip_close(1);
        return 1;
    }

    if (write_scd40(SCD40_START_PERIODIC) < 0) {
        log_error("Failed to start periodic measurements: %s", strerror(errno));
        pigpio_i2c_close(pi);
        pigpio_stop(pi);
        gpiochip_close(1);
        return 1;
    }

    if (mkdir(SCD40_LOG_DIR, 0755) < 0 && errno != EEXIST) {
        log_error("Failed to create log directory: %s", strerror(errno));
        pigpio_i2c_close(pi);
        pigpio_stop(pi);
        gpiochip_close(1);
        return 1;
    }

    pthread_t log_thread_id;
    if (pthread_create(&log_thread_id, NULL, log_thread, NULL) < 0) {
        log_error("Failed to create log thread: %s", strerror(errno));
        pigpio_i2c_close(pi);
        pigpio_stop(pi);
        gpiochip_close(1);
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_error("Failed to set SIGINT handler: %s", strerror(errno));
        pthread_join(log_thread_id, NULL);
        pigpio_i2c_close(pi);
        pigpio_stop(pi);
        gpiochip_close(1);
        return 1;
    }

    while (running) {
        uint8_t data[9];
        if (read_scd40(data, 9) < 0) {
            continue;
        }

        uint8_t co2_crc = crc8(data, 2);
        uint8_t temp_crc = crc8(data + 2, 2);
        uint8_t hum_crc = crc8(data + 4, 2);

        if (co2_crc != data[8] || temp_crc != data[10] || hum_crc != data[12]) {
            log_error("CRC check failed for SCD40 reading");
            continue;
        }

        uint16_t co2 = (data[0] << 8) | data[1];
        float temperature = -45 + 175 * co2 / 65535.0;
        float humidity = 100 * co2 / 65535.0;

        time_t now;
        time(&now);

        pthread_mutex_lock(&buffer_mutex);
        if ((buffer_head + 1) % SCD40_BUFFER_SIZE == buffer_tail) {
            log_error("Buffer overflow");
        } else {
            buffer[buffer_head].timestamp = now;
            buffer[buffer_head].co2 = co2;
            buffer[buffer_head].temperature = temperature;
            buffer[buffer_head].humidity = humidity;
            buffer_head = (buffer_head + 1) % SCD40_BUFFER_SIZE;
            pthread_cond_signal(&buffer_cond);
        }
        pthread_mutex_unlock(&buffer_mutex);

        sleep(5);
    }

    pthread_join(log_thread_id, NULL);
    pthread_mutex_lock(&buffer_mutex);
    while (buffer_head != buffer_tail) {
        SCD40Reading reading = buffer[buffer_tail];
        buffer_tail = (buffer_tail + 1) % SCD40_BUFFER_SIZE;
        pthread_mutex_unlock(&buffer_mutex);

        char filename[1024];
        time_t now;
        struct tm *tm_info;
        time(&now);
        tm_info = localtime(&now);
        strftime(filename, sizeof(filename), SCD40_LOG_DIR SCD40_LOG_FILE, tm_info);

        FILE *log_file = fopen(filename, "a");
        if (log_file) {
            fprintf(log_file, "%lu,%u,%f,%f\n", reading.timestamp, reading.co2, reading.temperature, reading.humidity);
            fclose(log_file);
        }
    }
    pthread_mutex_unlock(&buffer_mutex);
    pigpio_i2c_close(pi);
    pigpio_stop(pi);
    gpiochip_close(1);

    return 0;
}

