#define CMD_MEASURE 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

static FILE *log_file;
static int i2c_handle;

void log_reading(double pressure_Pa, double temperature_C) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_Pa, temperature_C);
}

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    pigpio_stop();
    exit(0);
}

int crc8(const unsigned char *data, int length) {
    int crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    if (i2cHandle(&i2c_handle, I2C_BUS, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }
    log_file = fopen("sdp810_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, handle_sigint);

    while (1) {
        if (i2cWriteByte(i2c_handle, CMD_MEASURE) < 0) {
            fprintf(stderr, "Failed to write command\n");
            continue;
        }
        usleep(45000); // Wait at least 45 ms

        unsigned char buffer[9];
        if (i2cRead(i2c_handle, buffer, 9) < 0) {
            fprintf(stderr, "Failed to read data\n");
            continue;
        }

        unsigned char crc = crc8(buffer, 8);
        if (crc != buffer[8]) {
            fprintf(stderr, "CRC failure\n");
            continue;
        }

        unsigned short raw_pressure = (buffer[0] << 8) | buffer[1];
        unsigned short raw_temp = (buffer[2] << 8) | buffer[3];
        float scale_factor = (buffer[4] << 8) | buffer[5];

        double pressure_Pa = raw_pressure * scale_factor / 1000.0;
        double temperature_C = -45.0 + 175.0 * raw_temp / 65535.0;

        log_reading(pressure_Pa, temperature_C);

        usleep(1000000); // Wait 1 second
    }

    fclose(log_file);
    i2c_close(i2c_handle);
    gpioTerminate();
    return 0;
}

