#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define CALIBRATION_REGS 0x05
#define MEASUREMENT_REG 0x00
#define DATA_REGS 0x00
#define SAMPLE_INTERVAL 5000000 // 5 seconds in microseconds

static volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int signum) {
    exit_flag = 1;
}

int main() {
    FILE *file;
    struct timespec ts;
    char timestamp[20];
    int i2c_handle;
    uint8_t who_am_i;
    uint8_t calibration[4];
    uint8_t data[6];
    float pressure, temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    // Verify sensor identity
    if (i2cReadByte(i2c_handle, WHO_AM_I_REG) != WHO_AM_I_REG) {
        fprintf(stderr, "Failed to verify sensor identity\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration coefficients
    if (i2cReadI2CBlockData(i2c_handle, CALIBRATION_REGS, 4, calibration) != 4) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open file for logging
    file = fopen("environmental_data.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    // Main loop
    while (!exit_flag) {
        // Trigger measurement
        if (i2cWriteByte(i2c_handle, MEASUREMENT_REG, 0x00) < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        // Wait for measurement to complete
        nanosleep(&ts, NULL);

        // Read pressure and temperature data
        if (i2cReadI2CBlockData(i2c_handle, DATA_REGS, 6, data) != 6) {
            fprintf(stderr, "Failed to read pressure and temperature data\n");
            continue;
        }

        // Convert data to hPa and Celsius
        pressure = (data[0] << 16) | (data[1] << 8) | data[2];
        temperature = (data[3] << 16) | (data[4] << 8) | data[5];

        // Format timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));

        // Log and print data
        fprintf(file, "%s,%.2f,%.2f\n", timestamp, pressure / 100.0, temperature / 100.0);
        fflush(file);
        printf("%s,%.2f,%.2f\n", timestamp, pressure / 100.0, temperature / 100.0);

        // Wait for next sample
        nanosleep(&ts, NULL);
    }

    // Clean up
    fclose(file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

