#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <libgpiod.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x63
#define OTP_REG 0x66
#define CMD_MEASURE 0x4011
#define CRC_LEN 2
#define PRESSURE_LEN 2
#define TEMP_LEN 2
#define MAX_RETRIES 3
#define DELAY_MS 20
#define LED_PIN 17
#define LED_ON_TIME 500
#define LED_OFF_TIME 500
#define HIGH_ALTITUDE_THRESHOLD 95000

static int i2c_fd;
static int led_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;
static struct sigaction sa;

static void handle_sigint(int signum) {
    if (led_fd >= 0) {
        gpiod_line_release(led_line);
        close(led_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

static int read_otp_coefficients() {
    uint8_t data[4];
    int retries = MAX_RETRIES;
    while (retries--) {
        if (ioctl(i2c_fd, I2C_RDWR, 1, &data) < 0) {
            perror("Failed to read OTP coefficients");
            return -1;
        }
        if (data[0] == 0x55 && data[1] == 0xAA) {
            return 0;
        }
        usleep(100000); // Wait for 100 ms before retrying
    }
    perror("Failed to read OTP coefficients after retries");
    return -1;
}

static int read_sensor_data(uint8_t *data) {
    int retries = MAX_RETRIES;
