#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_PIN 18
#define FAN_ON_THRESHOLD 30.0
#define FAN_OFF_THRESHOLD 28.0
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    FILE *log_file;
    struct timespec ts;
    int i2c_handle;
    uint16_t ambient_temp, object_temp;
    double temp_celsius;
    int retries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Set up the fan pin
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set fan pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Read ambient temperature
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (i2cReadReg16(i2c_handle, AMBIENT_TEMP_REG, &ambient_temp) < 0) {
                fprintf(stderr, "Failed to read ambient temperature\n");
                retries++;
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }
            break;
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read ambient temperature after %d retries\n", MAX_RETRIES);
            continue;
        }

        // Read object temperature
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (i2cReadReg16(i2c_handle, OBJECT_TEMP_REG, &object_temp) < 0) {
                fprintf(stderr, "Failed to read object temperature\n");
                retries++;
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            }
            break;
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read object temperature after %d retries\n", MAX_RETRIES);
            continue;
        }

        // Convert to Celsius
        temp_celsius = (ambient_temp * 0.02) - 273.15;
        if (isnan(temp_celsius)) {
            fprintf(stderr, "Invalid temperature reading\n");
            continue;
        }

        // Log the reading
        clock_gettime(CLOCK_REALTIME, &ts);
        fprintf(log_file, "%ld,%lf,%lf\n", ts.tv_sec, temp_celsius, (object_temp * 0.02) - 273.15);
        fflush(log_file);

        // Control the fan
        if ((object_temp * 0.02) - 273.15 > FAN_ON_THRESHOLD) {
            gpioWrite(FAN_PIN, 1);
        } else if ((object_temp * 0.02) - 273.15 < FAN_OFF_THRESHOLD) {
            gpioWrite(FAN_PIN, 0);
        }

        // Sleep for 2 seconds
        usleep(2000000);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

