#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SHT40_I2C_ADDR 0x44
#define SHT40_MEASURE_CMD 0xFD
#define SHT40_MEASURE_DELAY 10000 // 10 ms
#define SHT40_MAX_RETRIES 3
#define SHT40_TEMP_OFFSET -45.0
#define SHT40_TEMP_SCALE 175.0
#define SHT40_HUMIDITY_OFFSET -6.0
#define SHT40_HUMIDITY_SCALE 125.0
#define SHT40_HUMIDITY_MAX 100.0

static int gpiod_handle = -1;
static int sht40_i2c_handle = -1;
static int http_socket = -1;
static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

void cleanup() {
    if (http_socket != -1) {
        close(http_socket);
    }
    if (sht40_i2c_handle != -1) {
        i2c_close(gpiod_handle, sht40_i2c_handle);
    }
    if (gpiod_handle != -1) {
        gpioTerminate();
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    gpiod_handle = gpioGetChipHandle(0);

    // Initialize I2C
    sht40_i2c_handle = i2cOpen(gpiod_handle, SHT40_I2C_ADDR, 0, 0);
    if (sht40_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        cleanup();
        return 1;
    }

    // Initialize HTTP server
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(8080);

    http_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (http_socket < 0) {
        fprintf(stderr, "Failed to create socket\n");
        cleanup();
        return 1;
    }

    if (bind(http_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Failed to bind socket\n");
        close(http_socket);
        cleanup();
        return 1;
    }

    if (listen(http_socket, 5) < 0) {
        fprintf(stderr, "Failed to listen on socket\n");
        close(http_socket);
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    printf("Server started on port 8080\n");

    while (!should_exit) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_socket = accept(http_socket, (struct sockaddr *)&client_addr, &client_len);
        if (client_socket < 0) {
            fprintf(stderr, "Failed to accept connection\n");
            continue;
        }

        char buffer[1024];
        int bytes_read = read(client_socket, buffer, sizeof(buffer) - 1);
        if (bytes_read < 0) {
            fprintf(stderr, "Failed to read from client\n");
            close(client_socket);
            continue;
        }
        buffer[bytes_read] = '\0';

        if (strcmp(buffer, "GET / HTTP/1.1\r\n") == 0) {
            double temperature, humidity;
            if (read_sht40_data(&temperature, &humidity)) {
                char response[1024];
                snprintf(response, sizeof(response),
                        "HTTP/1.1 200 OK\r\n"
                        "Content-Type: text/html\r\n"
                        "Connection: close\r\n"
                        "\r\n"
                        "<html><body>"
                        "<h1>Temperature and Humidity</h1>"
                        "<p>Temperature: %.2f°C</p>"
                        "<p>Humidity: %.2f%%</p>"
                        "</body></html>",
                        temperature, humidity);
                write(client_socket, response, strlen(response));
            } else {
                char response[1024];
                snprintf(response, sizeof(response),
                        "HTTP/1.1 500 Internal Server Error\r\n"
                        "Content-Type: text/plain\r\n"
                        "Connection: close\r\n"
                        "\r\n"
                        "Failed to read SHT40 data");
                write(client_socket, response, strlen(response));
            }
        } else {
            char response[1024];
            snprintf(response, sizeof(response),
                    "HTTP/1.1 404 Not Found\r\n"
                    "Content-Type: text/plain\r\n"
                    "Connection: close\r\n"
                    "\r\n"
                    "Not Found");
            write(client_socket, response, strlen(response));
        }

        close(client_socket);
    }

    cleanup();
    return 0;
}

int read_sht40_data(double *temperature, double *humidity) {
    for (int i = 0; i < SHT40_MAX_RETRIES; i++) {
        if (i > 0) {
            usleep(100000); // 100 ms delay between retries
        }

        // Send measurement command
        if (i2cWriteByteData(gpiod_handle, sht40_i2c_handle, SHT40_MEASURE_CMD) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            return 0;
        }

        // Wait for measurement to complete
        usleep(SHT40_MEASURE_DELAY);

        // Read 6 bytes of data
        uint8_t data[6];
        if (i2cReadI2CBlockData(gpiod_handle, sht40_i2c_handle, 0, data, 6) < 0) {
            fprintf(stderr, "Failed to read data from SHT40\n");
            return 0;
        }

        // Extract raw temperature and humidity
        uint16_t raw_temp = (data[0] << 8) | data[1];
