        if (*humidity < 0.0) {
            *humidity = 0.0;
        } else if (*humidity > SHT40_HUMIDITY_MAX) {
            *humidity = SHT40_HUMIDITY_MAX;
        }

        return 1;
    }

    fprintf(stderr, "Failed to read SHT40 data after %d retries\n", SHT40_MAX_RETRIES);
    return 0;
