        return 1;
    }

    // Set MEASUREMENT_CONFIG register to trigger a one-shot measurement
    uint8_t measurement_config = 0x01;
    if (pigpio_i2c_write_byte_data(1, HDC2010_MEASUREMENT_CONFIG, measurement_config) < 0) {
        fprintf(stderr, "Failed to write to MEASUREMENT_CONFIG register\n");
        pigpio_i2c_close(1);
        gpioTerminate();
        return 1;
    }

    // Wait for the measurement to complete
    uint8_t status;
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (pigpio_i2c_read_byte_data(1, HDC2010_MEASUREMENT_CONFIG, &status) < 0) {
            fprintf(stderr, "Failed to read from MEASUREMENT_CONFIG register\n");
            pigpio_i2c_close(1);
            gpioTerminate();
            return 1;
        }
        if ((status & 0x01) == 0) {
            break;
        }
        usleep(10000); // 10 ms
    }

    if ((status & 0x01) != 0) {
        fprintf(stderr, "Timeout waiting for measurement to complete\n");
        pigpio_i2c_close(1);
        gpioTerminate();
        return 1;
    }

    // Read temperature and humidity
    uint16_t temp_raw, humidity_raw;
    if (pigpio_i2c_read_word_data(1, HDC2010_TEMP, &temp_raw) < 0) {
        fprintf(stderr, "Failed to read temperature\n");
        pigpio_i2c_close(1);
        gpioTerminate();
        return 1;
    }
    if (pigpio_i2c_read_word_data(1, HDC2010_HUMIDITY, &humidity_raw) < 0) {
        fprintf(stderr, "Failed to read humidity\n");
        pigpio_i2c_close(1);
        gpioTerminate();
        return 1;
    }

    // Convert to temperature and humidity
    float temperature = (temp_raw / 65536.0) * 165.0 - 40.0;
    float humidity = (humidity_raw / 65536.0) * 100.0;

    // Print the values
    printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

    // Close the I2C handle
    pigpio_i2c_close(1);

    // Clean up GPIO
    gpioTerminate();

    return 0;
}

