#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

// Function to calculate CRC-8 checksum
unsigned char crc8(const unsigned char *data, size_t len) {
    unsigned char crc = CRC8_INIT;
    for (size_t i = 0; i < len; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            crc = (crc & 0x80) ? (crc << 1) ^ CRC8_POLY : (crc << 1);
        }
    }
    return crc;
}

// Signal handler for clean shutdown
void sigint_handler(int signum) {
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up I2C bus
    int i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Continuously read pressure and temperature
    while (1) {
        // Send measurement command
        if (i2cWriteByte(i2cHandle, MEASURE_CMD) < 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            continue;
        }

        // Wait for measurement to complete (about 45 ms)
        usleep(45000);

        // Read 6 bytes: 2 bytes pressure, 1 CRC byte, 2 bytes temperature, 1 CRC byte
        unsigned char data[6];
        if (i2cReadBytes(i2cHandle, data, 6) < 0) {
            fprintf(stderr, "Failed to read data from I2C bus\n");
            continue;
        }

        // Calculate CRC-8 checksums
        unsigned char pressure_crc = crc8(data, 2);
        unsigned char temperature_crc = crc8(data + 2, 2);

        // Verify CRC-8 checksums
        if (pressure_crc != data[3] || temperature_crc != data[5]) {
            fprintf(stderr, "CRC-8 checksums do not match\n");
            continue;
        }

        // Extract raw 16-bit pressure and temperature values
        unsigned short pressure = (data[0] << 8) | data[1];
        unsigned short temperature = (data[2] << 8) | data[3];

        // Log the raw values to the console
        printf("Pressure: %hu Pa, Temperature: %hu °C\n", pressure, temperature);

        // Wait for 500 ms before the next reading
        usleep(500000);
    }

    // Close I2C handle and terminate pigpio library
    i2cClose(i2cHandle);
    gpioTerminate();

    return 0;
}

