#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>

#define LOG_FILE "greenhouse.log"
#define DS18B20_PATH "/sys/bus/w1/devices/"
#define DS18B20_ID "28-000000000000" // Replace with your DS18B20 ID
#define RELAY_PIN 17
#define PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define READ_INTERVAL 5000000 // 5 seconds in microseconds

static int gpiod_chip = -1;
static int relay_line = -1;
static int pwm_line = -1;
static FILE *log_file = NULL;

static void log_data(double timestamp, double avg_temp, double setpoint, double pid_output, double pwm_duty_cycle) {
    char log_entry[256];
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", log_entry, avg_temp, setpoint, pid_output, pwm_duty_cycle);
    fflush(log_file);
}

static void handle_signal(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    if (pwm_line != -1) {
        gpioPWM(pwm_line, 0);
    }
    if (relay_line != -1) {
        gpioWrite(relay_line, 0);
    }
    if (gpiod_chip != -1) {
        gpiod_chip_close(gpiod_chip);
    }
    exit(0);
}

static double read_temperature() {
    char path[256];
    snprintf(path, sizeof(path), "%s%s/w1_slave", DS18B20_PATH, DS18B20_ID);
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Failed to open DS18B20 file");
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (strstr(line, "t=")) {
            fclose(file);
            char *temp_str = strchr(line, '=') + 1;
            double temp = atof(temp_str) / 1000.0;
            if (temp < -40.0 || temp > 125.0) {
                fprintf(stderr, "Invalid temperature reading: %.2f\n", temp);
                return -1;
            }
            return temp;
        }
    }
    fclose(file);
    fprintf(stderr, "Failed to read temperature from DS18B20\n");
    return -1;
}

static double calculate_pid(double setpoint, double current_temp, double prev_error, double dt) {
    static double integral = 0.0;
    double error = setpoint - current_temp;
    integral += error * dt;
    double derivative = (error - prev_error) / dt;
    return Kp * error + Ki * integral + Kd * derivative;
}

static void setup_gpio() {
    gpiod_chip = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_chip == -1) {
        perror("Failed to open GPIO chip");
        exit(1);
    }
    relay_line = gpiod_chip_get_line(gpiod_chip, RELAY_PIN);
    if (relay_line == -1) {
        perror("Failed to get relay line");
        exit(1);
    }
    pwm_line = gpiod_chip_get_line(gpiod_chip, PWM_PIN);
    if (pwm_line == -1) {
        perror("Failed to get PWM line");
        exit(1);
    }
    gpiod_line_request_output(relay_line, "relay", 0);
    gpiod_line_request_output(pwm_line, "pwm", 0);
    gpioPWM(pwm_line, 0);
    gpioSetPWMfrequency(pwm_line, PWM_FREQ);
    gpioSetPWMrange(pwm_line, PWM_RANGE);
}

static void setup_logging() {
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        exit(1);
    }
    fprintf(log_file, "Timestamp,Average Temperature,Setpoint,PID Output,PWM Duty Cycle\n");
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        exit(1);
    }
    double setpoint = atof(argv[1]);
    double Kp = atof(argv[2]);
    double Ki = atof(argv[3]);
    double Kd = atof(argv[4]);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_logging();

    double prev_error = 0.0;
    double dt = 0.0;
    double avg_temp = 0.0;
    double current_temp = 0.0;

    while (1) {
        current_temp = read_temperature();
        if (current_temp == -1) {
            continue;
        }
        avg_temp = (avg_temp * 4 + current_temp) / 5.0;
        dt = 0.0005; // 5 milliseconds
        double pid_output = calculate_pid(setpoint, current_temp, prev_error, dt);
        prev_error = error;
        double pwm_duty_cycle = pid_output * PWM_RANGE / 100.0;
        log_data(time(NULL), avg_temp, setpoint, pid_output, pwm_duty_cycle);
        gpioWrite(relay_line, 1);
        gpioPWM(pwm_line, (int)pwm_duty_cycle);
        usleep(READ_INTERVAL);
        gpioWrite(relay_line, 0);
        gpioPWM(pwm_line, 0);
    }

    fclose(log_file);
    gpiod_chip_close(gpiod_chip);
    return 0;
}
