    uint8_t calib_block[24];
    if (gpio_i2c_read_block_data(i2c_handle, BMP280_CALIB_BLOCK_START, calib_block, 24) != 24) {
        fprintf(stderr, "Failed to read calibration block\n");
        exit(EXIT_FAILURE);
    }
