    signal(SIGTERM, sig_handler);

    i2c_handle = gpioI2COpen(1, BMP280_I2C_ADDR, 1);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    uint8_t chip_id;
    for (int attempt = 0; attempt < RETRY_ATTEMPTS; attempt++) {
        if (gpio_i2c_read_byte_data(i2c_handle, BMP280_CHIP_ID_REG, &chip_id) != 1) {
            fprintf(stderr, "Failed to read chip ID\n");
            gpioI2CClose(i2c_handle);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }
        if (chip_id == 0x58) {
            break;
        }
        if (attempt == RETRY_ATTEMPTS - 1) {
