    if (gpio_i2c_write_byte_data(i2c_handle, BMP280_CTRL_MEAS_REG, ctrl_meas) != 1) {
        fprintf(stderr, "Failed to set control measurement\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        usleep(1000000); // Wait 1 second

        if (gpio_i2c_read_byte_data(i2c_handle, BMP280_CTRL_MEAS_REG, &ctrl_meas) != 1) {
            fprintf(stderr, "Failed to read control measurement\n");
            continue;
        }
        if ((ctrl_meas & 0x01) == 0) {
            continue; // Measurement not complete
        }

        uint8_t data[6];
        if (gpio_i2c_read_block_data(i2c_handle, BMP280_DATA_REG, data, 6) != 6) {
            fprintf(stderr, "Failed to read data\n");
            continue;
        }

        // Implement data parsing and compensation here
        // This is a placeholder for actual implementation
        float temperature = 0.0f;
        float pressure = 0.0f;
        apply_compensation_formulas(&temperature, &pressure);

        if (temperature > 100.0f && pressure > BMP280_PRESSURE_THRESHOLD) {
            log_pressure_breach(pressure);
        } else if (temperature < -40.0f && pressure < BMP280_MIN_PRESSURE_THRESHOLD) {
            log_pressure_breach(pressure);
        }
    }

    gpioI2CClose(i2c_handle);
    gpioTerminate();
    return 0;
}

