#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TMP117_ADDR 0x48
#define TMP117_TEMP_REG 0x00
#define TMP117_TEMP_SCALE 0.0078125
#define AHT20_ADDR 0x38
#define AHT20_INIT_CMD 0xBE
#define AHT20_MEASURE_CMD 0xAC
#define AHT20_RESPONSE_LEN 7
#define PIR_PIN 17
#define LOG_DIR "/var/log/logger"
#define LOG_FILE "temperature_humidity_motion_%Y-%m-%d.csv"
#define MAX_RETRIES 3
#define BACKOFF_MS 10

static int gpiod_chip;
static int i2c_fd;
static int pwr_pin;
static int motion_detected = 0;
static time_t last_log_time = 0;

static void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        close(i2c_fd);
        gpiod_chip_close(gpiod_chip);
        exit(EXIT_SUCCESS);
    }
}

static void log_data(time_t now, float temp, float humidity, int motion) {
    char log_path[1024];
    snprintf(log_path, sizeof(log_path), "%s/%s", LOG_DIR, LOG_FILE);
    FILE *log_file = fopen(log_path, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log_file, "%ld,%f,%f,%d\n", now, temp, humidity, motion);
    fclose(log_file);
}

static void log_temperature() {
    uint8_t data[2];
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_RDWR, 1, (struct i2c_msg[]){{TMP117_ADDR, 0, 0, data}}) < 0) {
            perror("Failed to read from TMP117");
            retries++;
            usleep(BACKOFF_MS * 1000);
            continue;
        }
        int16_t temp_raw = (data[0] << 8) | data[1];
        float temp = (float)temp_raw * TMP117_TEMP_SCALE;
        log_data(time(NULL), temp, 0.0, 0);
        break;
    }
}

static void log_humidity() {
    uint8_t data[AHT20_RESPONSE_LEN];
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(i2c_fd, I2C_RDWR, 1, (struct i2c_msg[]){{AHT20_ADDR, 0, 0, data}}) < 0) {
            perror("Failed to read from AHT20");
            retries++;
            usleep(BACKOFF_MS * 1000);
            continue;
        }
        if (data[0] & 0x80) {
            retries++;
            usleep(BACKOFF_MS * 1000);
            continue;
        }
        uint32_t humidity_raw = (data[1] << 16) | (data[2] << 8) | data[3];
        uint32_t temperature_raw = (data[4] << 16) | (data[5] << 8) | data[6];
        float humidity = (float)humidity_raw * 100.0 / 0x100000;
        float temperature = (float)temperature_raw * 100.0 / 0x100000;
        log_data(time(NULL), temperature, humidity, 0);
        break;
    }
}

static void log_motion() {
    int motion = gpiod_line_get_value(gpiod_chip, PIR_PIN);
    if (motion) {
        motion_detected = 1;
    } else {
        motion_detected = 0;
    }
    log_data(time(NULL), 0.0, 0.0, motion_detected);
}

static void log_daily() {
    time_t now = time(NULL);
    if (now < last_log_time) {
        return;
    }
    last_log_time = now;
    char log_path[1024];
    snprintf(log_path, sizeof(log_path), "%s/%s", LOG_DIR, LOG_FILE);
    FILE *log_file = fopen(log_path, "w");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    fclose(log_file);
}

static void check_sensor_presence() {
    uint8_t data[1];
    if (ioctl(i2c_fd, I2C_RDWR, 1, (struct i2c_msg[]){{TMP117_ADDR, 0, 0, data}}) < 0) {
        fprintf(stderr, "Warning: TMP117 sensor not found\n");
    }
    if (ioctl(i2c_fd, I2C_RDWR, 1, (struct i2c_msg[]){{AHT20_ADDR, 0, 0, data}}) < 0) {
        fprintf(stderr, "Warning: AHT20 sensor not found\n");
    }
}

int main() {
    if (access(LOG_DIR, W_OK) != 0) {
        perror("Log directory does not exist or is not writable");
        return EXIT_FAILURE;
    }

    gpiod_chip = gpiod_chip_open("gpiochip4");
    if (!gpiod_chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    pwr_pin = gpiod_chip_get_line(gpiod_chip, PIR_PIN);
    if (!pwr_pin) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(gpiod_chip, pwr_pin, "PIR") < 0) {
        perror("Failed to request GPIO line input");
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        gpiod_line_release(gpiod_chip, pwr_pin);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_line_release(gpiod_chip, pwr_pin);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpiod_line_release(gpiod_chip, pwr_pin);
        gpiod_chip_close(gpiod_chip);
        return EXIT_FAILURE;
    }

    check_sensor_presence();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        log_daily();
        log_temperature();
        log_humidity();
        log_motion();
        sleep(1);
    }

    close(i2c_fd);
    gpiod_line_release(gpiod_chip, pwr_pin);
    gpiod_chip_close(gpiod_chip);

    return EXIT_SUCCESS;
}

