#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <time.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27

static int gpioHandle = -1;
static int pwmHandle = -1;
static int pwmFrequency = 1000; // 1 kHz
static int pwmDutyCycle = 0;

void handleSignal(int signum) {
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }
    gpioHandle = gpioOpen(RED_PIN, PI_OUTPUT);
    if (gpioHandle < 0) {
        fprintf(stderr, "Failed to open GPIO %d\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    gpioHandle = gpioOpen(GREEN_PIN, PI_OUTPUT);
    if (gpioHandle < 0) {
        fprintf(stderr, "Failed to open GPIO %d\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    gpioHandle = gpioOpen(BLUE_PIN, PI_OUTPUT);
    if (gpioHandle < 0) {
        fprintf(stderr, "Failed to open GPIO %d\n", BLUE_PIN);
        gpioTerminate();
        return 1;
    }
    pwmHandle = gpioPWM(RED_PIN, pwmDutyCycle);
    if (pwmHandle < 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    pwmHandle = gpioPWM(GREEN_PIN, pwmDutyCycle);
    if (pwmHandle < 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    pwmHandle = gpioPWM(BLUE_PIN, pwmDutyCycle);
    if (pwmHandle < 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", BLUE_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);

    struct timespec sleepTime = {0, 500000000}; // 500 ms
    struct timespec remainingTime;
    struct stat statBuffer;
    char cpuLoad[100];
    int totalCpuLoad = 0;
    int previousTotalCpuLoad = 0;
    int cpuLoadPercentage = 0;

    while (1) {
        if (stat("/proc/stat", &statBuffer) < 0) {
            fprintf(stderr, "Failed to read /proc/stat\n");
            break;
        }
        sscanf(statBuffer.st_size, "%d", &totalCpuLoad);
        cpuLoadPercentage = (totalCpuLoad - previousTotalCpuLoad) * 100 / totalCpuLoad;
        previousTotalCpuLoad = totalCpuLoad;

        if (cpuLoadPercentage < 0) {
            cpuLoadPercentage = 0;
        } else if (cpuLoadPercentage > 100) {
            cpuLoadPercentage = 100;
        }

        if (cpuLoadPercentage == 0) {
            pwmDutyCycle = 0;
        } else if (cpuLoadPercentage == 50) {
            pwmDutyCycle = 255;
        } else if (cpuLoadPercentage == 100) {
            pwmDutyCycle = 510;
        } else {
            pwmDutyCycle = (cpuLoadPercentage / 2) * 510 / 100;
        }

        gpioPWM(RED_PIN, pwmDutyCycle);
        gpioPWM(GREEN_PIN, pwmDutyCycle);
        gpioPWM(BLUE_PIN, pwmDutyCycle);

        nanosleep(&sleepTime, &remainingTime);
    }

    gpioTerminate();
    return 0;
}

