#include <json-c/json.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_ID 0xD0
#define BMP280_REG_CALIB_08 0x88
#define BMP280_REG_CALIB_11 0xA1
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_STATUS 0xF3
#define BMP280_REG_PRESSURE_MSB 0xF7
#define BMP280_REG_PRESSURE_LSB 0xF8
#define BMP280_REG_PRESSURE_XLSB 0xF9
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_MODE_FORCED 0x03
#define BMP280_STATUS_MEASURING 0x01
#define BMP280_STATUS_OVF 0x02
#define BMP280_STATUS_IM_UPDATE 0x04
#define BMP280_STATUS_IM_UPDATE_2 0x08
#define BMP280_STATUS_IM_UPDATE_3 0x10
#define BMP280_STATUS_IM_UPDATE_4 0x20
#define BMP280_STATUS_IM_UPDATE_5 0x40
#define BMP280_STATUS_IM_UPDATE_6 0x80

#define UDP_PORT 5000
#define UDP_IP "192.168.1.100"

static int i2c_handle;
static int udp_socket;
static struct sigaction sa;

void handle_sigint(int sig) {
    close(i2c_handle);
    close(udp_socket);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    if (read_i2c_register(i2c_handle, BMP280_REG_ID) != 0x58) {
        fprintf(stderr, "BMP280 chip ID mismatch\n");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t calib_data[24];
    if (read_i2c_block(i2c_handle, BMP280_REG_CALIB_08, calib_data, 24) != 24) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint32_t dig_T1 = (calib_data[0] << 16) | (calib_data[1] << 8) | calib_data[2];
    int16_t dig_T2 = (calib_data[3] << 8) | calib_data[4];
    int16_t dig_T3 = (calib_data[5] << 8) | calib_data[6];
    uint32_t dig_P1 = (calib_data[8] << 16) | (calib_data[9] << 8) | calib_data[10];
