#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MAX31855_ADDR 0x00
#define MAX31855_FAULT_BIT 16
#define MAX31855_OC_BIT 0
#define MAX31855_SCG_BIT 1
#define MAX31855_SCV_BIT 2
#define MAX31855_TEMP_OFFSET 2500
#define MAX31855_TEMP_SCALE 25
#define PWM_GPIO 18
#define PWM_FREQ 1000
#define PWM_DUTY_MAX 255
#define BUFFER_SIZE 20
#define BUFFER_MASK (BUFFER_SIZE - 1)

static int spiHandle;
static int gpioHandle;
static int bufferIndex = 0;
static int buffer[BUFFER_SIZE];
static struct timespec lastReadTime;
static struct timespec currentTime;
static int fanDutyCycle = 0;

static void handleSignal(int signum) {
    gpioPWM(PWM_GPIO, 0);
    gpioTerminate();
    close(spiHandle);
    printf("Exiting...\n");
    exit(0);
}

static void logReading(int temperature, int dutyCycle) {
    buffer[bufferIndex] = temperature;
    bufferIndex = (bufferIndex + 1) & BUFFER_MASK;
    printf("%ld, %d, %d\n", currentTime.tv_sec, currentTime.tv_nsec / 1000000, dutyCycle);
}

static int readMax31855() {
    uint8_t tx[4] = {0x00, 0x00, 0x00, 0x00};
    uint8_t rx[4] = {0x00, 0x00, 0x00, 0x00};

    if (spiXfer(spiHandle, tx, rx, 4) < 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    int rawTemp = (rx[0] << 16) | (rx[1] << 8) | rx[2];
    int fault = (rx[3] >> 16) & 1;

    if (fault) {
        fprintf(stderr, "MAX31855 fault detected\n");
        return -1;
    }

    return rawTemp - MAX31855_TEMP_OFFSET;
}

static int getDutyCycle(int temperature) {
    if (temperature < 25) {
        return 0;
    } else if (temperature < 40) {
        return (temperature - 25) * 2;
    } else if (temperature < 60) {
        return 50 + (temperature - 40) * 10;
    } else {
        return PWM_DUTY_MAX;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (spiOpen(0, 500000, 0) < 0) {
        fprintf(stderr, "Failed to open SPI channel 0\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioPWM(PWM_GPIO, 0);

    signal(SIGINT, handleSignal);

    if (clock_gettime(CLOCK_REALTIME, &lastReadTime) < 0) {
        fprintf(stderr, "Failed to get current time\n");
        gpioTerminate();
        close(spiHandle);
        return 1;
    }

    while (1) {
        if (clock_gettime(CLOCK_REALTIME, &currentTime) < 0) {
            fprintf(stderr, "Failed to get current time\n");
            continue;
        }

        if (difftime(currentTime.tv_sec, lastReadTime.tv_sec) >= 1) {
            int rawTemp = readMax31855();
            if (rawTemp >= 0) {
                int temperature = rawTemp / MAX31855_TEMP_SCALE;
                fanDutyCycle = getDutyCycle(temperature);
                gpioPWM(PWM_GPIO, fanDutyCycle);
                logReading(temperature, fanDutyCycle);
            }
            lastReadTime = currentTime;
        }

        usleep(1000000);
    }

    gpioTerminate();
    close(spiHandle);
    return 0;
}

