This C program initializes the Raspberry Pi 4 Model B using the pigpio library to control a PWM-driven cooling fan on GPIO18 based on temperature readings from a MAX31855 thermocouple amplifier over SPI0. It handles SPI transfers, MAX31855 faults, and SIGINT to gracefully exit. The program logs each valid reading into a circular buffer and updates the fan duty cycle based on the temperature.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BMP180_ADDRESS 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_RESULT 0xF6
#define BMP180_REG_CALIB 0xAA
#define BMP180_OSS_3 0x3

static int i2c_handle;
static FILE *log_file;
static int gpio_pin = 2;
static int is_logging = 0;

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpio_unexport(gpio_pin);
    exit(0);
}

void read_calibration_data() {
    uint16_t ac1, ac2, ac3, ac4, ac5, ac6;
    uint16_t b1, b2, mb, mc, md;

    if (i2c_write_byte_data(i2c_handle, BMP180_REG_CALIB, 0xAA) < 0) {
        perror("Failed to write calibration data register");
        exit(EXIT_FAILURE);
    }

    if (i2c_read_block_data(i2c_handle, BMP180_REG_CALIB, 22, (uint8_t *)&ac1) < 0) {
        perror("Failed to read calibration data");
        exit(EXIT_FAILURE);
    }

    ac2 = (ac1 << 8) | ac2;
    ac3 = (ac1 << 8) | ac3;
    ac4 = (ac1 << 8) | ac4;
    ac5 = (ac1 << 8) | ac5;
    ac6 = (ac1 << 8) | ac6;

    if (i2c_write_byte_data(i2c_handle, BMP180_REG_CALIB, 0xAC) < 0) {
        perror("Failed to write calibration data register");
        exit(EXIT_FAILURE);
    }

    if (i2c_read_block_data(i2c_handle, BMP180_REG_CALIB, 6, (uint8_t *)&b1) < 0) {
        perror("Failed to read calibration data");
        exit(EXIT_FAILURE);
    }

    b2 = (b1 << 8) | b2;
    mb = (b1 << 8) | mb;
    mc = (b1 << 8) | mc;
    md = (b1 << 8) | md;
}

void read_pressure_temperature() {
    uint8_t control = BMP180_OSS_3;
    uint8_t result[3];
    uint32_t uncompensated_pressure, uncompensated_temperature;
    int32_t pressure, temperature;

    if (i2c_write_byte_data(i2c_handle, BMP180_REG_CONTROL, control) < 0) {
        perror("Failed to write control register");
        return;
    }

    usleep(5000); // Wait for conversion

    if (i2c_read_block_data(i2c_handle, BMP180_REG_RESULT, 3, result) < 0) {
        perror("Failed to read result");
        return;
    }

    uncompensated_pressure = (result[0] << 16) | (result[1] << 8) | result[2];
    uncompensated_temperature = (result[0] << 16) | (result[1] << 8) | result[2];

    pressure = (uncompensated_pressure >> 4) - ((ac6 << 14) + (ac5 * uncompensated_temperature) / 16384) / (1 << 16);
    temperature = (uncompensated_temperature >> 4) - ((ac5 << 14) + (ac4 * uncompensated_pressure) / 16384) / (1 << 16);

    pressure = pressure * 100; // Convert to Pa
    temperature = temperature / 10; // Convert to Celsius

    if (is_logging) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, "%s,%d,%d\n", timestamp, temperature, pressure);
        fflush(log_file);
    }
}

int main() {
    if (gpio_init() < 0) {
        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    if (gpio_export(gpio_pin, PI_INPUT) < 0) {
        perror("Failed to export GPIO");
        gpio_exit();
        exit(EXIT_FAILURE);
    }

    if (gpio_set_mode(gpio_pin, PI_INPUT) < 0) {
        perror("Failed to set GPIO mode");
        gpio_unexport(gpio_pin);
        gpio_exit();
        exit(EXIT_FAILURE);
    }

    if (gpio_set_pull_up_down(gpio_pin, PI_PUD_UP) < 0) {
        perror("Failed to set pull-up");
        gpio_unexport(gpio_pin);
        gpio_exit();
        exit(EXIT_FAILURE);
    }

    if (gpio_interrupt_callback(gpio_pin, 1, read_pressure_temperature) < 0) {
        perror("Failed to set interrupt callback");
        gpio_unexport(gpio_pin);
        gpio_exit();
        exit(EXIT_FAILURE);
    }

    if ((i2c_handle = i2c_open(1, BMP180_ADDRESS, 0)) < 0) {
        perror("Failed to open I2C bus");
        gpio_unexport(gpio_pin);
        gpio_exit();
