        perror("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    if (gpio_export(gpio_pin, PI_INPUT) < 0) {
        perror("Failed to export GPIO");
        gpio_exit();
        exit(EXIT_FAILURE);
    }

    if (gpio_set_mode(gpio_pin, PI_INPUT) < 0) {
        perror("Failed to set GPIO mode");
        gpio_unexport(gpio_pin);
        gpio_exit();
        exit(EXIT_FAILURE);
    }

    if (gpio_set_pull_up_down(gpio_pin, PI_PUD_UP) < 0) {
        perror("Failed to set pull-up");
        gpio_unexport(gpio_pin);
        gpio_exit();
        exit(EXIT_FAILURE);
    }

    if (gpio_interrupt_callback(gpio_pin, 1, read_pressure_temperature) < 0) {
        perror("Failed to set interrupt callback");
        gpio_unexport(gpio_pin);
        gpio_exit();
        exit(EXIT_FAILURE);
    }

    if ((i2c_handle = i2c_open(1, BMP180_ADDRESS, 0)) < 0) {
        perror("Failed to open I2C bus");
        gpio_unexport(gpio_pin);
        gpio_exit();
        exit(EXIT_FAILURE);
    }

    read_calibration_data();

