        perror("Failed to open log file");
        i2c_close(i2c_handle);
        gpio_unexport(gpio_pin);
        gpio_exit();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        sleep(1);
    }

    fclose(log_file);
    i2c_close(i2c_handle);
    gpio_unexport(gpio_pin);
    gpio_exit();

    return 0;
}
