#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define BME280_I2C_ADDR 0x76
#define BME280_CHIP_ID 0x60
#define I2C_BUS 1
#define I2C_SDA 2
#define I2C_SCL 3
#define LOG_FILE "bme280_log.csv"
#define BUFFER_SIZE 100

static int i2c_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_sda;
static struct gpiod_line *gpio_scl;

static void signal_handler(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (gpio_sda) {
        gpiod_line_release(gpio_sda);
    }
    if (gpio_scl) {
        gpiod_line_release(gpio_scl);
    }
    exit(signum);
}

static void log_data(double timestamp, double temperature, double humidity, double pressure) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%.0f-%.0f-%.0f %.0f:%.0f:%.0f,%.2f,%.2f,%.2f\n",
            (int)timestamp / 1000000000, (int)(timestamp / 1000000) % 60,
            (int)(timestamp / 1000) % 60, (int)(timestamp / 10) % 60,
            (int)timestamp % 10, temperature, humidity, pressure);
    fclose(log_file);
}

static void read_bme280_data(double *temperature, double *humidity, double *pressure) {
    uint8_t data[8];
    int ret;

    // Read temperature, humidity, and pressure registers
    ret = i2c_smbus_read_i2c_block_data(i2c_fd, 0xF7, 8, data);
    if (ret != 8) {
        perror("Failed to read BME280 data");
        return;
    }

    // Calculate temperature
    uint32_t adc_temp = (data[0] << 16) | (data[1] << 8) | data[2];
    int32_t var1 = (int32_t)adc_temp - 12688;
    var1 *= 2048;
    var1 /= 8192;
    var1 += 65536;
    var1 *= 3402823466;
    var1 /= 1073741824;
    var1 += 8;
    *temperature = var1 / 100.0;

    // Calculate humidity
    uint32_t adc_hum = (data[3] << 16) | (data[4] << 8) | data[5];
    int32_t var2 = (int32_t)adc_hum - 46875;
    var2 *= 2048;
    var2 /= 8192;
    var2 += 65536;
    var2 *= 16237.5;
    var2 /= 1073741824;
    *humidity = var2 / 100.0;

    // Calculate pressure
    uint32_t adc_press = (data[6] << 16) | (data[7] << 8) | data[8];
    int32_t var3 = (int32_t)adc_press - 24000;
    var3 *= var3;
    var3 /= 32768;
    var3 += 16000;
    var3 *= var3;
    var3 /= 1024;
    *pressure = var3 / 256.0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize GPIO for I2C
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }
    gpio_sda = gpiod_chip_get_line(gpio_chip, I2C_SDA);
    gpio_scl = gpiod_chip_get_line(gpio_chip, I2C_SCL);
    if (!gpio_sda || !gpio_scl) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }
    gpiod_line_request_output(gpio_sda, "bme280_sda", 0);
    gpiod_line_request_output(gpio_scl, "bme280_scl", 0);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_line_release(gpio_sda);
        gpiod_line_release(gpio_scl);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    // Check BME280 chip ID
    uint8_t chip_id;
    ret = i2c_smbus_read_byte_data(i2c_fd, 0xD0);
    if (ret < 0) {
        perror("Failed to read BME280 chip ID");
        close(i2c_fd);
        gpiod_line_release(gpio_sda);
        gpiod_line_release(gpio_scl);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }
    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "BME280 chip ID is not 0x60, got 0x%02X\n", chip_id);
        close(i2c_fd);
        gpiod_line_release(gpio_sda);
        gpiod_line_release(gpio_scl);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    // Write configuration registers
    uint8_t config[2] = {0x1F, 0x00}; // Normal mode, 10-bit resolution, filter off
    ret = i2c_smbus_write_i2c_block_data(i2c_fd, 0xF5, 2, config);
    if (ret != 2) {
        perror("Failed to write BME280 configuration");
        close(i2c_fd);
        gpiod_line_release(gpio_sda);
        gpiod_line_release(gpio_scl);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    // Write control registers
    uint8_t control[2] = {0x2F, 0x00}; // Normal mode, 16-bit resolution
    ret = i2c_smbus_write_i2c_block_data(i2c_fd, 0xF4, 2, control);
    if (ret != 2) {
        perror("Failed to write BME280 control");
        close(i2c_fd);
        gpiod_line_release(gpio_sda);
        gpiod_line_release(gpio_scl);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }

    // Log header
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_line_release(gpio_sda);
        gpiod_line_release(gpio_scl);
        gpiod_chip_close(gpio_chip);
        return EXIT_FAILURE;
    }
    fprintf(log_file, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
    fclose(log_file);

    // Main loop
    while (1) {
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double timestamp = ts.tv_sec * 1000000000 + ts.tv_nsec;

        double temperature, humidity, pressure;
        read_bme280_data(&temperature, &humidity, &pressure);

        log_data(timestamp, temperature, humidity, pressure);

        sleep(5);
    }

    // Clean up
    close(i2c_fd);
    gpiod_line_release(gpio_sda);
    gpiod_line_release(gpio_scl);
    gpiod_chip_close(gpio_chip);

    return EXIT_SUCCESS;
}

