#define LOG_FORMAT "YYYY-MM-DD HH:MM:SS, Temperature: %.2f °C, Pressure: %.2f hPa\n"

static int i2c_fd = -1;
static volatile sig_atomic_t should_exit = 0;

void handle_sigint(int sig) {
    should_exit = 1;
}

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

