    if (log_file == NULL) {
        log_error("Failed to open log file");
        return;
    }

    fprintf(log_file, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fclose(log_file);
}

void read_calibration_block(unsigned char *calib_block) {
    if (i2c_write_reg(i2c_fd, BMP280_CALIB_BLOCK_REG, 0, 0) != 0) {
        log_error("Failed to read calibration block");
        return;
    }

    if (i2c_read(i2c_fd, calib_block, BMP280_CALIB_BLOCK_SIZE) != BMP280_CALIB_BLOCK_SIZE) {
        log_error("Failed to read calibration block");
        return;
    }
}

void read_temperature_pressure(double *temperature, double *pressure) {
    unsigned char ctrl_meas = BMP280_MODE_FORCED | BMP280_OVERSAMPLING_X1 | BMP280_OVERSAMPLING_X1;
    if (i2c_write_reg(i2c_fd, BMP280_CTRL_MEAS_REG, 0, ctrl_meas) != 0) {
        log_error("Failed to set control measurement");
        return;
    }

    while (1) {
        if (i2c_read_reg(i2c_fd, BMP280_STATUS_REG, 0, 0) != 0) {
            log_error("Failed to read status register");
            return;
        }

        unsigned char status;
        if (i2c_read(i2c_fd, &status, 1) != 1) {
            log_error("Failed to read status register");
            return;
        }

        if ((status & BMP280_STATUS_MEASURING) == 0) {
            break;
        }

        usleep(100000); // Wait for measurement to complete
    }

    if (i2c_read_reg(i2c_fd, BMP280_PRESS_MSB_REG, 0, 0) != 0) {
        log_error("Failed to read pressure MSB");
        return;
    }

    unsigned char press_msb, press_lsb, press_xlsb;
    if (i2c_read(i2c_fd, &press_msb, 1) != 1) {
        log_error("Failed to read pressure MSB");
        return;
    }

    if (i2c_read(i2c_fd, &press_lsb, 1) != 1) {
        log_error("Failed to read pressure LSB");
        return;
    }

    if (i2c_read(i2c_fd, &press_xlsb, 1) != 1) {
        log_error("Failed to read pressure XLSB");
        return;
    }

    unsigned int press_raw = (press_msb << 16) | (press_lsb << 8) | press_xlsb;

    if (i2c_read_reg(i2c_fd, BMP280_TEMP_MSB_REG, 0, 0) != 0) {
        log_error("Failed to read temperature MSB");
        return;
    }

    unsigned char temp_msb, temp_lsb, temp_xlsb;
    if (i2c_read(i2c_fd, &temp_msb, 1) != 1) {
        log_error("Failed to read temperature MSB");
        return;
    }

    if (i2c_read(i2c_fd, &temp_lsb, 1) != 1) {
        log_error("Failed to read temperature LSB");
        return;
    }

    if (i2c_read(i2c_fd, &temp_xlsb, 1) != 1) {
        log_error("Failed to read temperature XLSB");
        return;
    }

    unsigned int temp_raw = (temp_msb << 16) | (temp_lsb << 8) | temp_xlsb;

    double temperature_celsius = (temp_raw / 16384.0 - 500.0) * 0.00390625;
    double pressure_hpa = (press_raw / 256.0 - 512.0) * 0.0390625;

    *temperature = temperature_celsius;
    *pressure = pressure_hpa;
}

int i2c_open(const char *dev) {
    i2c_fd = open(dev, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

int i2c_close() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    return 0;
}

int i2c_write_reg(int fd, unsigned char reg, unsigned char val) {
    unsigned char buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

int i2c_read_reg(int fd, unsigned char reg, unsigned char *val) {
    unsigned char buf[1] = {reg};
    if (write(fd, buf, 1) != 1) {
        return -1;
    }

    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

int i2c_read(int fd, unsigned char *buf, size_t len) {
    if (read(fd, buf, len) != len) {
        return -1;
    }
    return 0;
}

int main() {
    if (i2c_open("/dev/i2c-1") != 0) {
        return 1;
    }

    unsigned char chip_id;
    if (i2c_read_reg(i2c_fd, BMP280_CHIP_ID_REG, &chip_id) != 0) {
        i2c_close();
        return 1;
    }

    if (chip_id != 0x58) {
        log_error("Incorrect chip ID, expected 0x58");
        i2c_close();
        return 1;
    }

    unsigned char calib_block[BMP280_CALIB_BLOCK_SIZE];
    read_calibration_block(calib_block);

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (!should_exit) {
        double temperature, pressure;
        read_temperature_pressure(&temperature, &pressure);

        log_data(temperature, pressure);

        sleep(5); // Log every 5 seconds
    }

    i2c_close();
    return 0;
}

