    while (running) {
        int temp_raw;
        int temp_celsius;

        // Read temperature from LM75
        if (i2c_smbus_read_word_data(i2c_fd, TEMP_REG) == -1) {
            fprintf(stderr, "I2C read error\n");
            sleep(1);
            continue;
        }

        // Convert raw temperature to Celsius
        temp_raw = i2c_smbus_read_word_data(i2c_fd, TEMP_REG);
        temp_celsius = (temp_raw >> 5) * 0.0625;

        // Log the temperature
        pthread_mutex_lock(&buffer_mutex);
        buffer[buffer_head] = temp_celsius;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&buffer_mutex);

        // Compute running average
        double sum = 0.0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            sum += buffer[i];
        }
        double average = sum / BUFFER_SIZE;

        // Trigger LED if temperature exceeds MAX_TEMP
        if (temp_celsius > MAX_TEMP) {
            gpio_set_value(LED_PIN, 1);
        } else {
            gpio_set_value(LED_PIN, 0);
        }

        // Log the average temperature
        fprintf(stderr, "Temperature: %.2f°C, Average: %.2f°C\n", temp_celsius, average);

        // Sleep for 1 second
        sleep(1);
    }
    return NULL;
}

static void signal_handler(int sig) {
    running = 0;
    pthread_join(thread, NULL);
    gpio_free(LED_PIN);
    close(i2c_fd);
    pthread_mutex_destroy(&buffer_mutex);
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpiochip_open(0) == -1) {
        fprintf(stderr, "GPIO chip open error\n");
        return 1;
    }
    if (gpio_claim_line(LED_PIN) == -1) {
        fprintf(stderr, "GPIO claim line error\n");
        gpiochip_close(0);
        return 1;
    }

    // Initialize I2C
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        fprintf(stderr, "I2C open error\n");
        gpio_free(LED_PIN);
        gpiochip_close(0);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        fprintf(stderr, "I2C slave error\n");
        close(i2c_fd);
        gpio_free(LED_PIN);
        gpiochip_close(0);
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&buffer_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex init error\n");
        close(i2c_fd);
        gpio_free(LED_PIN);
        gpiochip_close(0);
        return 1;
    }

    // Create thread
    if (pthread_create(&thread, NULL, read_temperature, NULL) != 0) {
        fprintf(stderr, "Thread create error\n");
        close(i2c_fd);
        gpio_free(LED_PIN);
        gpio_mutex_destroy(&buffer_mutex);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        sleep(1);
    }

    // Clean up
    signal_handler(SIGINT);

    return 0;
}
