    init_gpio();
    init_spi();
    init_max31865();

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    while (1) {
        double current_temperature = read_rtd();
        pid_control(current_temperature);

        double now = (double)time(NULL);
        double dt = now - last_time;
        last_time = now;

        usleep(100000); // 100 ms
    }

    gpioWrite(GPIO_PWM, 0);
    gpioPWMWrite(GPIO_PWM, 0);
    gpioTerminate();
    close(spi_fd);
    return EXIT_SUCCESS;
