#define BMP180_ADDR 0x77
#define BMP180_REG_CALIB 0xAA
#define BMP180_REG_TEMP 0x2E
#define BMP180_REG_PRESS 0x34
#define BMP180_REG_ID 0xD0
#define BMP180_ID 0x55

#define BUFFER_SIZE 60
#define FAN_PIN 18
#define FAN_THRESHOLD 30.0

static int i2cHandle;
static int fanState = 0;
static int bufferIndex = 0;
static double buffer[BUFFER_SIZE];
static struct timespec lastSampleTime;

static void sigHandler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        fanState = 0;
        gpioWrite(FAN_PIN, fanState);
        i2cClose(i2cHandle);
        gpioTerminate();
        exit(0);
    }
}

static void timerCallback(gpioHandle timer) {
    struct timespec currentTime;
    clock_gettime(CLOCK_MONOTONIC, &currentTime);

    if (difftime(currentTime.tv_sec, lastSampleTime.tv_sec) >= 0.5) {
        lastSampleTime = currentTime;
        readBMP180();
    }
}

static void readBMP180() {
    int16_t ac1, ac2, ac3, ac4, ac5, ac6;
    int16_t b1, b2, b3, b4, b5, b6, b7;
    uint16_t rawTemp, rawPress;
    double temperature, pressure;

    // Read calibration data
    if (i2cRead(i2cHandle, BMP180_REG_CALIB, 22, (uint8_t *)&ac1) != 22) {
        return;
    }
    if (i2cRead(i2cHandle, BMP180_REG_CALIB + 22, 22, (uint8_t *)&ac2) != 22) {
        return;
    }
    if (i2cRead(i2cHandle, BMP180_REG_CALIB + 44, 22, (uint8_t *)&ac3) != 22) {
        return;
    }
    if (i2cRead(i2cHandle, BMP180_REG_CALIB + 66, 22, (uint8_t *)&ac4) != 22) {
        return;
    }
    if (i2cRead(i2cHandle, BMP180_REG_CALIB + 88, 22, (uint8_t *)&ac5) != 22) {
        return;
    }
    if (i2cRead(i2cHandle, BMP180_REG_CALIB + 110, 22, (uint8_t *)&ac6) != 22) {
        return;
    }
    if (i2cRead(i2cHandle, BMP180_REG_CALIB + 132, 22, (uint8_t *)&b1) != 22) {
        return;
    }
    if (i2cRead(i2cHandle, BMP180_REG_CALIB + 154, 22, (uint8_t *)&b2) != 22) {
        return;
    }
    if (i2cRead(i2cHandle, BMP180_REG_CALIB + 176, 22, (uint8_t *)&b3) != 22) {
        return;
    }
    if (i2cRead(i2cHandle, BMP180_REG_CALIB + 198, 22, (uint8_t *)&b4) != 22) {
        return;
    }
    if (i2cRead(i2cHandle, BMP180_REG_CALIB + 220, 22, (uint8_t *)&b5) != 22) {
        return;
    }
    if (i2cRead(i2cHandle, BMP180_REG_CALIB + 242, 22, (uint8_t *)&b6) != 22) {
        return;
    }
    if (i2cRead(i2cHandle, BMP180_REG_CALIB + 264, 22, (uint8_t *)&b7) != 22) {
        return;
    }

    // Read raw temperature and pressure
    if (i2cRead(i2cHandle, BMP180_REG_TEMP, 1, (uint8_t *)&rawTemp) != 1) {
        return;
    }
    if (i2cRead(i2cHandle, BMP180_REG_PRESS, 2, (uint8_t *)&rawPress) != 2) {
        return;
    }

    // Calculate true temperature
    double x1 = (rawTemp - ac6) * ac5 / 2048.0;
    double x2 = ac4 * (x1 * x1) / 8388608.0;
    double x3 = x1 + x2;
    double b5 = x3 + 16384.0;
    temperature = (b5 / 1024.0) - 500.0;

    // Calculate true pressure
    double x1 = (temperature + 25.0) * (b2 / 32768.0);
    double x2 = (temperature + 25.0) * (temperature + 25.0) * (b3 / 8388608.0);
    double x3 = (temperature + 25.0) * (temperature + 25.0) * (temperature + 25.0) * (b4 / 134217728.0);
    double b6 = b5 - (x1 + x2 + x3);
    double b7 = b7 * (1.0 + b6 / 65536.0);
    double pressure = (1048576.0 - rawPress) * (b7 / 2097152.0);
    x1 = (b3 * pressure * pressure) / 65536.0;
    x2 = (b2 * pressure) / 4096.0;
    x3 = pressure * pressure * pressure * b1 / 16777216.0;
    pressure = pressure + (x1 + x2 + x3);

    // Store timestamped reading
    buffer[bufferIndex++] = currentTime.tv_sec + currentTime.tv_nsec / 1000000000.0;
    buffer[bufferIndex++] = temperature;
    buffer[bufferIndex++] = pressure;
    bufferIndex %= BUFFER_SIZE;

    // Check if temperature exceeds threshold
    if (temperature > FAN_THRESHOLD) {
        fanState = 1;
    } else {
        fanState = 0;
    }
    gpioWrite(FAN_PIN, fanState);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioWrite(FAN_PIN, fanState);

    if (i2cOpen(1, BMP180_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (i2cRead(i2cHandle, BMP180_REG_ID, 1, (uint8_t *)&id) != 1 || id != BMP180_ID) {
        fprintf(stderr, "Invalid BMP180 ID\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    if (signal(SIGINT, sigHandler) == SIG_ERR || signal(SIGTERM, sigHandler) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handlers\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    if (gpioHardwareTimerCreate(0, 500000) < 0) {
        fprintf(stderr, "Failed to create hardware timer\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    gpioHardwareTimerStart(0);

    while (1) {
        // Wait for timer callback to execute
        sleep(1);
    }

    i2cClose(i2cHandle);
    gpioTerminate();
    return 0;
}

