#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <max31855.h>

#define HEATER_PIN 17
#define SPI_CHANNEL 0
#define SPI_CLOCK_SPEED 2000000
#define MAX_DUTY_CYCLE 80
#define TARGET_TEMP 25.0
#define LOG_FILE "heater_log.csv"

static int heater_duty_cycle = 0;
static FILE *log_file;
static int max31855_fd;
static int spi_fd;
static int running = 1;

void log_temperature(float temp) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f\n", timestamp, temp);
    fflush(log_file);
}

void pi_controller(float current_temp, float target_temp) {
    static float prev_error = 0.0;
    static float integral = 0.0;
    float error = target_temp - current_temp;
    float derivative = error - prev_error;
    prev_error = error;

    float proportional = error * 100.0; // Proportional gain
    float integral = integral + error; // Integral gain
    integral = fmaxf(fminf(integral, 100.0), -100.0); // Anti-windup
    float derivative = derivative * 0.1; // Derivative gain

    float control_signal = proportional + integral + derivative;
    control_signal = fmaxf(fminf(control_signal, MAX_DUTY_CYCLE), 0.0);

    heater_duty_cycle = (int)control_signal;
}

void handle_sigint(int signum) {
    running = 0;
}

void handle_sigterm(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(HEATER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for heater\n");
        gpioTerminate();
        pigpioTerminate();
        return 1;
    }

    if ((spi_fd = spiOpen(SPI_CHANNEL, SPI_CLOCK_SPEED, 0)) < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        pigpioTerminate();
        return 1;
    }

    if ((max31855_fd = max31855Open(0, 0, 0)) < 0) {
        fprintf(stderr, "Failed to open MAX31855\n");
        spiClose(spi_fd);
        gpioTerminate();
        pigpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        max31855Close(max31855_fd);
        spiClose(spi_fd);
        gpioTerminate();
        pigpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (running) {
        float current_temp;
        if (max31855Read(max31855_fd, &current_temp) < 0) {
            fprintf(stderr, "Failed to read MAX31855\n");
            current_temp = TARGET_TEMP;
        }

        pi_controller(current_temp, TARGET_TEMP);

        gpioPWM(HEATER_PIN, heater_duty_cycle);

        log_temperature(current_temp);

        usleep(100000); // 100 Hz sampling
    }

    fclose(log_file);
    max31855Close(max31855_fd);
    spiClose(spi_fd);
    gpioTerminate();
    pigpioTerminate();

    return 0;
}

