#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27
#define PWM_RANGE 255
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define TEMP_THRESHOLD_1 40000
#define TEMP_THRESHOLD_2 59999

volatile sig_atomic_t exit_flag = 0;

void signal_handler(int signum) {
    exit_flag = 1;
}

int main() {
    int fd;
    char temp_str[10];
    unsigned int temp_millidegrees;
    unsigned int red_duty, green_duty, blue_duty;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up PWM on each pin
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);
    gpioPWMRange(RED_PIN, PWM_RANGE);
    gpioPWMRange(GREEN_PIN, PWM_RANGE);
    gpioPWMRange(BLUE_PIN, PWM_RANGE);

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!exit_flag) {
        // Read temperature from file
        fd = open(TEMP_FILE, O_RDONLY);
        if (fd < 0) {
            perror("Failed to open temperature file");
            continue;
        }

        if (read(fd, temp_str, sizeof(temp_str)) < 0) {
            if (ferror(fd)) {
                perror("Failed to read temperature file");
            } else {
                fprintf(stderr, "Short read from temperature file\n");
            }
            close(fd);
            continue;
        }

        close(fd);

        // Convert temperature string to integer
        temp_millidegrees = atoi(temp_str);

        // Determine RGB values based on temperature
        if (temp_millidegrees < TEMP_THRESHOLD_1) {
            red_duty = 255;
            green_duty = 0;
            blue_duty = 0;
        } else if (temp_millidegrees < TEMP_THRESHOLD_2) {
            red_duty = 0;
            green_duty = 255;
            blue_duty = 0;
        } else {
            red_duty = 0;
            green_duty = 0;
            blue_duty = 255;
        }

        // Set PWM duty cycles
        gpioPWM(RED_PIN, PWM_RANGE - red_duty);
        gpioPWM(GREEN_PIN, PWM_RANGE - green_duty);
        gpioPWM(BLUE_PIN, PWM_RANGE - blue_duty);

        // Print temperature and RGB values
        printf("Temperature: %u m°C, RGB: R=%u, G=%u, B=%u\n",
               temp_millidegrees, red_duty, green_duty, blue_duty);

        // Sleep for 0.5 seconds
        usleep(500000);
    }

    // Clean up
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);
    gpioTerminate();

    return 0;
}

