#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT_PIN 4
#define MAX_RETRIES 3
#define HTTP_URL "http://yourserver.com/api/humidity"

static int retries = 0;
static int sensor_present = 0;
static int humidity = 0;
static int temperature = 0;

static void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Exiting...\n");
        gpioTerminate();
        curl_global_cleanup();
        exit(EXIT_SUCCESS);
    }
}

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    return size * nmemb;
}

static int read_dht22() {
    int data[5] = {0};
    int i, j;
    int bit;
    int result;

    // Start signal
    gpioWrite(DHT_PIN, 0);
    usleep(1000);
    gpioWrite(DHT_PIN, 1);
    usleep(40);
    gpioSetMode(DHT_PIN, PI_INPUT);

    // Wait for response
    for (i = 0; i < 85; i++) {
        while (gpioRead(DHT_PIN) == 0);
        usleep(28);
        if (gpioRead(DHT_PIN) == 1) {
            data[j / 8] <<= 1;
            data[j / 8] |= 1;
        }
        usleep(80);
    }

    // Check checksum
    result = (data[0] + data[1] + data[2] + data[3]) & 0xFF;
    if (result != data[4]) {
        printf("Checksum error\n");
        return -1;
    }

    // Parse data
    humidity = (data[0] << 8) | data[1];
    temperature = ((data[2] & 0x7F) << 8) | data[3];
    if (data[2] & 0x80) {
        temperature = -temperature;
    }

    return 0;
}

static int post_data() {
    CURL *curl;
    CURLcode res;
    char json[256];
    snprintf(json, sizeof(json), "{\"humidity\": %d, \"temperature\": %d}", humidity, temperature);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if(curl) {
        curl_easy_setopt(curl, CURLOPT_URL, HTTP_URL);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, strlen(json));
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, NULL);

        res = curl_easy_perform(curl);
        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }

    curl_global_cleanup();
    return res == CURLE_OK ? 0 : -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }
    gpioSetMode(DHT_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (retries < MAX_RETRIES) {
        if (read_dht22() == 0) {
            sensor_present = 1;
            break;
        }
        retries++;
        sleep(1);
    }

    if (sensor_present) {
        if (post_data() == 0) {
            printf("Data posted successfully\n");
        } else {
            printf("Failed to post data\n");
        }
    } else {
        printf("Sensor not present\n");
    }

    gpioTerminate();
    curl_global_cleanup();
    return EXIT_SUCCESS;
}

