#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <curl/curl.h>
#include <pigpio.h>

#define DHT_PIN 4
#define DHT_MAXCOUNT 4096
#define DHT_TIMEOUT 1000000
#define DHT_CHECKSUM 0x0C
#define DHT_RETRY 3
#define DHT_BACKOFF 2000000

static int humidity = -1;
static int retries = 0;
static int server_url_set = 0;
static char *server_url = "http://your-server.com/api/humidity";

static void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        syslog(LOG_INFO, "Received signal %d, shutting down...", sig);
        gpioTerminate();
        curl_global_cleanup();
        exit(EXIT_SUCCESS);
    }
}

static void log_error(const char *msg) {
    syslog(LOG_ERR, "Error: %s", msg);
}

static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
    return size * nmemb;
}

static int dht_read() {
    int data[5] = {0};
    int i, j;
    int count = 0;
    int laststate = 1;
    int state = 1;
    int bit = 0;
    int humidity = 0;
    int temperature = 0;
    int checksum = 0;

    gpioSetMode(DHT_PIN, PI_INPUT);
    gpioPullUpDnControl(DHT_PIN, PI_PUD_UP);
    usleep(2000000); // 2 seconds delay to allow sensor to stabilize

    gpioSetMode(DHT_PIN, PI_OUTPUT);
    gpioWrite(DHT_PIN, 0);
    usleep(1000000); // 1 second delay
    gpioWrite(DHT_PIN, 1);
    usleep(400000); // 400 µs delay

    gpioSetMode(DHT_PIN, PI_INPUT);

    while (gpioRead(DHT_PIN) == laststate) {
        count++;
        if (count > DHT_MAXCOUNT) {
            return -1;
        }
    }
    laststate = gpioRead(DHT_PIN);

    while (gpioRead(DHT_PIN) != laststate) {
        count++;
        if (count > DHT_MAXCOUNT) {
            return -1;
        }
    }
    laststate = gpioRead(DHT_PIN);

    for (i = 0; i < 40; i++) {
        count = 0;
        while (gpioRead(DHT_PIN) == laststate) {
            count++;
            if (count > DHT_MAXCOUNT) {
                return -1;
            }
        }
        laststate = gpioRead(DHT_PIN);

        if (count > DHT_MAXCOUNT) {
            return -1;
        }

        if (count < 6) {
            data[bit / 8] |= (1 << (7 - bit % 8));
        }

        bit++;
    }

    for (i = 0; i < 5; i++) {
        checksum += data[i];
    }

    if (checksum != data[4]) {
        return -1;
    }

    humidity = ((data[0] << 8) + data[1]) / 10.0;
    temperature = ((data[2] << 8) + data[3]) / 10.0;

    return 0;
}

static int post_humidity() {
    CURL *curl;
    CURLcode res;
    char json[100];
    snprintf(json, sizeof(json), "{\"humidity\": %.2f}", humidity);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        log_error("Failed to initialize libcurl");
        return -1;
    }

    curl_easy_setopt(curl, CURLOPT_URL, server_url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, strlen(json));
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, curl_slist_append(NULL, "Content-Type: application/json"));
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        log_error(curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_cleanup(curl);
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    struct sigaction sa;

    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                server_url = optarg;
                server_url_set = 1;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <url>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (!server_url_set) {
        fprintf(stderr, "Server URL not specified, using default: %s\n", server_url);
    }

    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        if (dht_read() == 0) {
            if (post_humidity() == 0) {
                syslog(LOG_INFO, "Humidity posted successfully: %.2f%%", humidity);
            } else {
                retries++;
                if (retries >= DHT_RETRY) {
                    syslog(LOG_ERR, "Failed to post humidity after %d retries", DHT_RETRY);
                    retries = 0;
                } else {
                    syslog(LOG_INFO, "Retrying post in %d ms", DHT_BACKOFF / 1000);
                    usleep(DHT_BACKOFF);
                }
            }
        } else {
            retries++;
            if (retries >= DHT_RETRY) {
                syslog(LOG_ERR, "Failed to read humidity after %d retries", DHT_RETRY);
                retries = 0;
            } else {
                syslog(LOG_INFO, "Retrying read in %d ms", DHT_BACKOFF / 1000);
                usleep(DHT_BACKOFF);
            }
        }

        sleep(10);
    }

    gpioTerminate();
    curl_global_cleanup();
    return EXIT_SUCCESS;
}

