#define FAN_CONTROL_LOG "/var/log/fan_control.log"
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_STATE_FILE "/sys/class/thermal/cooling_device0/max_state"
#define MAX_TEMP 65000 // 65°C in millidegrees Celsius
#define MIN_TEMP 45000 // 45°C in millidegrees Celsius
#define MAX_FAN_STATE 3
#define MIN_FAN_STATE 0
#define LOG_FORMAT "%s: Fan state changed to %d at %s\n"

static int fan_fd;
static int temp_fd;
static int max_state_fd;
static int fan_state;
static int temp;
static int max_state;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void log_event(const char *message, int fan_state) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[80];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, LOG_FORMAT, message, fan_state, timestamp);
    fflush(log_file);
}

void handle_signal(int signum) {
    should_exit = 1;
}

void setup_logging() {
    log_file = fopen(FAN_CONTROL_LOG, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void close_logging() {
    if (log_file != NULL) {
        fclose(log_file);
    }
}

void setup_fan_control() {
    fan_fd = open(FAN_STATE_FILE, O_WRONLY);
    if (fan_fd == -1) {
        perror("Failed to open fan state file");
        exit(EXIT_FAILURE);
    }

    temp_fd = open(TEMP_FILE, O_RDONLY);
    if (temp_fd == -1) {
        perror("Failed to open temperature file");
        exit(EXIT_FAILURE);
    }

    max_state_fd = open(MAX_STATE_FILE, O_RDONLY);
    if (max_state_fd == -1) {
        perror("Failed to open max state file");
        exit(EXIT_FAILURE);
    }

    if (read(max_state_fd, &max_state, sizeof(max_state)) != sizeof(max_state)) {
        perror("Failed to read max state");
        exit(EXIT_FAILURE);
    }

    if (max_state < MIN_FAN_STATE || max_state > MAX_FAN_STATE) {
        fprintf(stderr, "Invalid max state: %d\n", max_state);
        exit(EXIT_FAILURE);
    }
}

void update_fan_state() {
    char state_str[10];
    int new_state;

    if (read(temp_fd, &temp, sizeof(temp)) != sizeof(temp)) {
        perror("Failed to read temperature");
        return;
    }

    temp /= 1000; // Convert millidegrees Celsius to degrees Celsius

    if (temp < MIN_TEMP) {
        new_state = MIN_FAN_STATE;
    } else if (temp < 55) {
        new_state = 1;
    } else if (temp < 65) {
        new_state = 2;
    } else {
        new_state = MAX_FAN_STATE;
    }

    if (new_state != fan_state) {
        snprintf(state_str, sizeof(state_str), "%d", new_state);
        if (write(fan_fd, state_str, strlen(state_str)) != strlen(state_str)) {
            perror("Failed to write fan state");
        }
        fan_state = new_state;
        log_event("Fan state changed", new_state);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_logging();
    setup_fan_control();

    while (!should_exit) {
        update_fan_state();
        sleep(5);
    }

    close(fan_fd);
    close(temp_fd);
    close(max_state_fd);
    close_logging();

    log_event("Fan control stopped", fan_state);
    exit(EXIT_SUCCESS);
}

