#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <max31855.h>

#define HEATER_PIN 18
#define SPI_CLK 11
#define SPI_CS 8
#define SPI_DO 9
#define TARGET_TEMP 50.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define LOG_FILE "heater_log.txt"
#define MAX_TEMP 100.0
#define MIN_TEMP 0.0

static int spiHandle;
static int heaterState = 0;
static double lastError = 0.0;
static double integral = 0.0;
static double derivative = 0.0;
static double lastTime = 0.0;
static double target = TARGET_TEMP;
static double kp = Kp;
static double ki = Ki;
static double kd = Kd;

void logData(double temp, double dutyCycle, double pidOutput) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    fprintf(log, "%.2f,%.2f,%.2f\n", temp, dutyCycle, pidOutput);
    fclose(log);
}

void handleFault(int fault) {
    heaterState = 0;
    integral = 0.0;
    derivative = 0.0;
    lastError = 0.0;
    lastTime = 0.0;
    fprintf(stderr, "Fault detected: %d\n", fault);
    logData(0.0, 0.0, 0.0);
}

void handleSignal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        heaterState = 0;
        gpioWrite(HEATER_PIN, 0);
        spiClose(spiHandle);
        pigpioTerminate();
        exit(0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetPWMFrequency(HEATER_PIN, 1000);
    gpioSetPWMRange(HEATER_PIN, 100);

    spiHandle = spiOpen(0, 500000, 0);
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);

    while (1) {
        double temp = readMax31855(spiHandle);
        if (temp < MIN_TEMP || temp > MAX_TEMP) {
            handleFault(MAX31855_OPEN_CIRCUIT);
            continue;
        }

        double error = target - temp;
        integral += error;
        derivative = error - lastError;
        lastError = error;
        double pidOutput = kp * error + ki * integral + kd * derivative;

        if (pidOutput < 0) {
            pidOutput = 0;
        } else if (pidOutput > 100) {
            pidOutput = 100;
        }

        gpioPWM(HEATER_PIN, pidOutput);
        logData(temp, pidOutput, pidOutput);

        double currentTime = (double)time(NULL);
        double deltaTime = currentTime - lastTime;
        lastTime = currentTime;

        usleep(1000000); // Sleep for 1 second
    }

    spiClose(spiHandle);
    gpioTerminate();
    return 0;
}

