#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define PWM_PIN 18
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"
#define LOG_HEADER "Timestamp, Temperature (°C), PWM Duty Cycle (%)\n"
#define TEMP_THRESHOLD_LOW 40000
#define TEMP_THRESHOLD_HIGH 70000
#define PWM_FREQ 25000
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 100
#define POLL_INTERVAL 5000000 // 5 seconds in microseconds

static int gpio_fd;
static FILE *log_file;
static int fan_enabled = 1;

void log_data(double timestamp, double temp, double duty_cycle) {
    fprintf(log_file, "%.6f,%d,%d\n", timestamp, temp / 1000, duty_cycle);
}

void handle_signal(int signum) {
    if (fan_enabled) {
        gpioPWM(PWM_PIN, 0);
        fan_enabled = 0;
    }
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for PWM\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMFrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMRange(PWM_PIN, PWM_DUTY_MAX) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    if ((gpio_fd = open(TEMP_FILE, O_RDONLY)) < 0) {
        fprintf(stderr, "Failed to open temperature file\n");
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        close(gpio_fd);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, LOG_HEADER);

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (1) {
        char temp_str[10];
        if (read(gpio_fd, temp_str, sizeof(temp_str)) <= 0) {
            fprintf(stderr, "Failed to read temperature\n");
            break;
        }
        temp_str[sizeof(temp_str) - 1] = '\0';
        int temp = atoi(temp_str);
        double temp_celsius = temp / 1000.0;

        double duty_cycle;
        if (temp_celsius < TEMP_THRESHOLD_LOW) {
            duty_cycle = PWM_DUTY_MIN;
        } else if (temp_celsius > TEMP_THRESHOLD_HIGH) {
