#define I2C_BUS 1
#define I2C_ADDRESS_1 0x08
#define I2C_ADDRESS_2 0x09
#define I2C_COMMAND 0x3608
#define CRC8_POLYNOMIAL 0x07
#define CRC8_INIT 0xFF
#define CRC8_UPDATE(c, b) ((c) ^= (b), (c) = ((c) & 0x01) ? ((c) ^ CRC8_POLYNOMIAL) : (c))

static int i2c_handle_1 = -1;
static int i2c_handle_2 = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t should_exit = 0;

void sig_handler(int sig) {
    should_exit = 1;
}

void log_flow(float flow1, float flow2) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%f,%f\n", timestamp, flow1, flow2);
    fflush(log_file);
}

void calculate_crc8(const unsigned char *data, size_t length) {
    unsigned char crc = CRC8_INIT;
    for (size_t i = 0; i < length; ++i) {
        crc = CRC8_UPDATE(crc, data[i]);
    }
    return crc;
}

int read_sensor(int i2c_handle, unsigned char *data, size_t length) {
    int retries = 3;
    while (retries--) {
        if (i2c_read_i2c_block_data(i2c_handle, I2C_COMMAND, data, length) == length) {
            return 0;
        }
        usleep(100000); // Wait 100ms before retrying
    }
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if ((i2c_handle_1 = i2cOpen(I2C_BUS, I2C_ADDRESS_1, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C handle for sensor 1\n");
        gpioTerminate();
        return 1;
    }

    if ((i2c_handle_2 = i2cOpen(I2C_BUS, I2C_ADDRESS_2, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C handle for sensor 2\n");
        i2cClose(i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("flow_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!should_exit) {
        unsigned char data[4];
        if (read_sensor(i2c_handle_1, data, 4) == 0) {
            unsigned char crc = calculate_crc8(data, 3);
            if (crc == data[3]) {
                float flow1 = data[0] * 0.01;
                float flow2 = data[1] * 0.01;
                log_flow(flow1, flow2);
            }
        }

        if (read_sensor(i2c_handle_2, data, 4) == 0) {
            unsigned char crc = calculate_crc8(data, 3);
            if (crc == data[3]) {
                float flow1 = data[0] * 0.01;
                float flow2 = data[1] * 0.01;
                log_flow(flow1, flow2);
            }
        }

        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle_1);
    i2cClose(i2c_handle_2);
    gpioTerminate();

    return 0;
}

