#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_A 17
#define GPIO_B 18
#define LOG_FILE "encoder_log.txt"
#define MAX_LOG_SIZE 1024

static volatile int state = 0;
static volatile int last_state = 0;
static volatile int angle = 0;
static volatile int last_angle = 0;
static volatile int running = 1;

static void signal_handler(int signum) {
    running = 0;
    gpioTerminate();
    printf("Program terminated by signal %d\n", signum);
    exit(EXIT_SUCCESS);
}

static void log_state(int new_state, int new_angle) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    fprintf(log, "%s, %d, %d\n", timestamp, new_state, new_angle);
    fclose(log);
}

static void update_angle(int new_state) {
    int delta = new_state - last_state;
    if (delta == 1 || delta == -3) {
        angle += 90;
    } else if (delta == -1 || delta == 3) {
        angle -= 90;
    }
    last_state = new_state;
}

static void update_log(int new_state, int new_angle) {
    update_angle(new_state);
    log_state(new_state, angle);
    last_angle = angle;
}

static void gpio_callback(int gpio, int level, uint32_t tick) {
    if (gpio == GPIO_A) {
        if (level == PI_HIGH) {
            state = (state << 1) | 1;
        } else {
            state = (state << 1) | 0;
        }
    } else if (gpio == GPIO_B) {
        if (level == PI_HIGH) {
            state = (state << 1) | 1;
        } else {
            state = (state << 1) | 0;
        }
    }
    update_log(state, angle);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_A, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for A\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for B\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_A, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor for A\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_B, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor for B\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(GPIO_A, gpio_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function for A\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(GPIO_B, gpio_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function for B\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        usleep(100000); // Sleep for 100ms
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

