#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define FIFO_DATA_REG 0x60
#define RED_CHANNEL 0
#define IR_CHANNEL 1
#define THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"
#define LOG_FORMAT "%lu,%d,%d\n"

static int i2c_fd;
static int led_gpio;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;

static void sig_handler(int sig) {
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    if (led_gpio >= 0) gpiod_line_release(led_line);
    if (chip) gpiod_chip_close(chip);
    exit(0);
}

static void log_reading(uint32_t red, uint32_t ir) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    fprintf(log_file, LOG_FORMAT, (unsigned long)ts.tv_sec, red, ir);
    fflush(log_file);
}

static int read_sensor_data(uint32_t *red, uint32_t *ir) {
    uint8_t buffer[2];
    int ret;

    ret = write(i2c_fd, &FIFO_DATA_REG, 1);
    if (ret < 0) {
        perror("write");
        return -1;
    }

    ret = read(i2c_fd, buffer, 2);
    if (ret < 0) {
        perror("read");
        return -1;
    }

    *red = buffer[0] << 8 | buffer[1];
    *ir = buffer[2] << 8 | buffer[3];

    return 0;
}

static void trigger_led(uint32_t ir) {
    if (ir > THRESHOLD) {
        gpiod_line_set_value(led_line, 1);
    } else {
        gpiod_line_set_value(led_line, 0);
    }
}

int main() {
    int ret;
    uint32_t red, ir;

    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Open LED GPIO line
    led_gpio = gpiod_chip_get_line(chip, 17);
    if (!led_gpio) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Request output mode for LED GPIO line
    ret = gpiod_line_request_output(led_gpio, "adpd144ri_led", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(led_gpio);
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Log header
    fprintf(log_file, "timestamp,red,ir\n");
    fflush(log_file);

    // Main loop
    while (1) {
        if (read_sensor_data(&red, &ir) < 0) {
            continue;
        }

        trigger_led(ir);
        log_reading(red, ir);

        usleep(100000); // 100 ms delay
    }

    // Clean up
    gpiod_line_release(led_gpio);
    gpiod_chip_close(chip);
    fclose(log_file);
    close(i2c_fd);

    return 0;
}
```

This C program uses libgpiod to interface with the Raspberry Pi's GPIO pins and the Linux I2C character-device interface to communicate with the ADPD144RI sensor. It reads the red and IR channel data from the FIFO data register, triggers an LED if the IR reading exceeds a threshold, and logs the readings to a CSV file. The program handles I2C read/write errors, sensor-absent conditions, and graceful shutdown using signal handlers.

