#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <pigpio.h>

#define RPM_LOG_FILE "rpm_log.txt"
#define RPM_LOG_INTERVAL 1000000 // 1 second in microseconds
#define RPM_LOG_MAX_LINES 1000
#define RPM_LOG_LINE_LENGTH 100

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *rpm_log = NULL;
static int sensor_gpio = 18;
static int sensor_present = 1;

static void *rpm_counter(void *arg) {
    struct timespec sleep_time = {0, RPM_LOG_INTERVAL};
    struct timespec remaining_time;
    int count = 0;

    while (1) {
        if (sensor_present) {
            count = pulse_count;
            pulse_count = 0;
        }
        if (count > 0) {
            double rpm = (count * 60.0) / (RPM_LOG_INTERVAL / 1000000.0);
            pthread_mutex_lock(&pulse_mutex);
            if (rpm_log != NULL) {
                char log_line[RPM_LOG_LINE_LENGTH];
                time_t now = time(NULL);
                struct tm *tm = localtime(&now);
                strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S", tm);
                snprintf(log_line + strlen(log_line), sizeof(log_line) - strlen(log_line), "RPM: %.2f\n", rpm);
                if (fprintf(rpm_log, "%s", log_line) < 0) {
                    perror("Error writing to RPM log file");
                }
                fflush(rpm_log);
            }
            pthread_mutex_unlock(&pulse_mutex);
        }
        nanosleep(&sleep_time, &remaining_time);
    }
    return NULL;
}

static void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (rpm_log != NULL) {
            fclose(rpm_log);
        }
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(sensor_gpio, PI_INPUT) < 0) {
        perror("Failed to set GPIO mode");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(sensor_gpio, PI_PUD_DOWN) < 0) {
        perror("Failed to set pull-down resistor");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFunc(sensor_gpio, RISING_EDGE, 1000, pulse_counter) < 0) {
        perror("Failed to register ISR");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rpm_log = fopen(RPM_LOG_FILE, "a");
    if (rpm_log == NULL) {
        perror("Failed to open RPM log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    pthread_t rpm_thread;
    if (pthread_create(&rpm_thread, NULL, rpm_counter, NULL) < 0) {
        perror("Failed to create RPM thread");
        fclose(rpm_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        if (sensor_present) {
            if (pulse_count > 0) {
                double rpm = (pulse_count * 60.0) / (RPM_LOG_INTERVAL / 1000000.0);
                printf("RPM: %.2f\n", rpm);
            } else {
                printf("RPM: 0.00\n");
            }
        }
        sleep(1);
    }

    pthread_join(rpm_thread, NULL);
    fclose(rpm_log);
    gpioTerminate();
    return EXIT_SUCCESS;
}

