#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x39
#define PART_ID_REG 0x00
#define FIFO_DATA_REG 0x01
#define FIFO_STATUS_REG 0x02
#define FIFO_LEVEL_REG 0x03
#define FIFO_FLUSH_REG 0x04
#define FIFO_THRESHOLD_REG 0x05
#define FIFO_CONFIG_REG 0x06
#define FIFO_DATA_SIZE 16
#define LED_PIN 17
#define LOG_FILE "adpd144ri_log.txt"
#define THRESHOLD 2000

static int i2c_fd;
static int led_pin_fd;
static FILE *log_file;

static void log_data(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(log_file, format, args);
    va_end(args);
    fprintf(log_file, "\n");
}

static void log_error(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(stderr, format, args);
    va_end(args);
    fprintf(stderr, "\n");
}

static void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (led_pin_fd >= 0) {
        gpio_close(led_pin_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

static void handle_signal(int sig) {
    cleanup();
    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    int part_id;
    int red, ir;
    int fifo_level;
    int threshold;
    int config;
    int status;
    int data[FIFO_DATA_SIZE];
    int i;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        cleanup();
        exit(1);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C address");
        cleanup();
        exit(1);
    }

    // Open LED GPIO line
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        cleanup();
        exit(1);
    }
    line = gpiod_chip_get_line(chip, LED_PIN);
    if (!line) {
        log_error("Failed to get GPIO line");
        cleanup();
        exit(1);
    }
    led_pin_fd = gpiod_line_request_output(line, "adpd144ri", 0);
    if (led_pin_fd < 0) {
        log_error("Failed to request GPIO line");
        cleanup();
        exit(1);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        log_error("Failed to open log file");
        cleanup();
        exit(1);
    }

    // Read PART_ID register to verify sensor presence
    if (write(i2c_fd, &PART_ID_REG, 1) != 1) {
        log_error("Failed to write PART_ID register");
        cleanup();
        exit(1);
    }
    if (read(i2c_fd, &part_id, 1) != 1) {
        log_error("Failed to read PART_ID register");
        cleanup();
        exit(1);
    }
    if (part_id != 0x14) {
        log_error("Sensor not found at address 0x39");
        cleanup();
        exit(1);
    }
    log_data("Sensor found at address 0x39");

    // Configure FIFO
    threshold = 2000;
    config = 0x01; // Enable FIFO
    if (write(i2c_fd, &FIFO_THRESHOLD_REG, 1) != 1) {
        log_error("Failed to write FIFO_THRESHOLD_REG");
        cleanup();
        exit(1);
    }
    if (write(i2c_fd, &threshold, 1) != 1) {
        log_error("Failed to write FIFO_THRESHOLD");
        cleanup();
        exit(1);
    }
    if (write(i2c_fd, &FIFO_CONFIG_REG, 1) != 1) {
        log_error("Failed to write FIFO_CONFIG_REG");
        cleanup();
        exit(1);
    }
    if (write(i2c_fd, &config, 1) != 1) {
        log_error("Failed to write FIFO_CONFIG");
        cleanup();
        exit(1);
    }

    // Log header
    log_data("Timestamp,Red,IR");

    while (1) {
        // Read FIFO status
        if (write(i2c_fd, &FIFO_STATUS_REG, 1) != 1) {
            log_error("Failed to write FIFO_STATUS_REG");
            cleanup();
            exit(1);
        }
        if (read(i2c_fd, &status, 1) != 1) {
            log_error("Failed to read FIFO_STATUS");
            cleanup();
            exit(1);
        }
        if (status & 0x01) {
            // FIFO has data
            if (write(i2c_fd, &FIFO_DATA_REG, 1) != 1) {
                log_error("Failed to write FIFO_DATA_REG");
                cleanup();
                exit(1);
            }
            if (read(i2c_fd, data, FIFO_DATA_SIZE * sizeof(int)) != FIFO_DATA_SIZE * sizeof(int)) {
                log_error("Failed to read FIFO data");
                cleanup();
                exit(1);
            }
            for (i = 0; i < FIFO_DATA_SIZE; i++) {
                red = data[i] & 0x3FF;
                ir = (data[i] >> 10) & 0x3FF;
                log_data("%ld,%d,%d", time(NULL), red, ir);
                if (ir > THRESHOLD) {
                    gpiod_line_set_value(led_pin_fd, 1);
                } else {
                    gpiod_line_set_value(led_pin_fd, 0);
                }
            }
        } else {
            // No data in FIFO
            usleep(100000); // Sleep for 100 ms
        }
    }

    cleanup();
    return 0;
}

