#define MAX9814_OUT_PIN 17
#define MAX9814_GAIN_PIN 18
#define LOG_FILE "audio_log.txt"
#define SAMPLE_INTERVAL_MS 10

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int sig) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *out_line, *gain_line;
    struct timespec sleep_time;
    char timestamp[20];
    FILE *log_file;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    out_line = gpiod_chip_get_line(chip, MAX9814_OUT_PIN);
    if (!out_line) {
        perror("Failed to get GPIO line for OUT");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gain_line = gpiod_chip_get_line(chip, MAX9814_GAIN_PIN);
    if (!gain_line) {
        perror("Failed to get GPIO line for GAIN");
        gpiod_line_release(out_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set GAIN pin to LOW (60dB gain)
    ret = gpiod_line_set_value(gain_line, 0);
    if (ret < 0) {
        perror("Failed to set GAIN pin to LOW");
        gpiod_line_release(out_line);
        gpiod_line_release(gain_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(out_line);
        gpiod_line_release(gain_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Print startup message
    printf("Audio peak detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!should_exit) {
        struct timespec start_time, end_time;
        int level = 0;

        // Start timer
        ret = clock_gettime(CLOCK_MONOTONIC, &start_time);
        if (ret < 0) {
            perror("Failed to get current time");
            fclose(log_file);
            gpiod_line_release(out_line);
            gpiod_line_release(gain_line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Poll OUT pin
        while (level == 0) {
            ret = gpiod_line_get_value(out_line);
            if (ret < 0) {
                perror("Failed to read OUT pin");
                fclose(log_file);
                gpiod_line_release(out_line);
                gpiod_line_release(gain_line);
                gpiod_chip_close(chip);
                exit(EXIT_FAILURE);
            }
            level = ret;
            usleep(SAMPLE_INTERVAL_MS * 1000);
        }

        // End timer
        ret = clock_gettime(CLOCK_MONOTONIC, &end_time);
        if (ret < 0) {
            perror("Failed to get current time");
            fclose(log_file);
            gpiod_line_release(out_line);
            gpiod_line_release(gain_line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Calculate duration
        long duration_ns = (end_time.tv_sec - start_time.tv_sec) * 1000000000 + (end_time.tv_nsec - start_time.tv_nsec);
        double duration_ms = duration_ns / 1000000.0;

        // Log peak
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&start_time.tv_sec));
        fprintf(log_file, "%s 1\n", timestamp);

        // Sleep for the remaining time
        sleep_time.tv_sec = (duration_ms / 1000) - SAMPLE_INTERVAL_MS;
        sleep_time.tv_nsec = (duration_ms % 1000) * 1000000;
        ret = nanosleep(&sleep_time, NULL);
        if (ret < 0) {
            perror("Failed to sleep");
            fclose(log_file);
            gpiod_line_release(out_line);
            gpiod_line_release(gain_line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(out_line);
    gpiod_line_release(gain_line);
    gpiod_chip_close(chip);

    return 0;
}

