#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x36
#define COMMAND_START_MEASUREMENT 0x3608
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define CRC_CHECKSUM_SIZE 1
#define RAW_FLOW_SIZE 2
#define LOG_FILE "flow_log.csv"

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

void log_flow(double flow_rate) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s,%.6f\n", timestamp, flow_rate);
    fflush(log_file);
}

void handle_sigint(int signum) {
    should_exit = 1;
}

int calculate_crc8(const unsigned char *data, size_t length) {
    unsigned char crc = CRC_INIT;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            crc = (crc >> 1) ^ ((crc & 1) ? CRC_POLYNOMIAL : 0);
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (i2cWrite(i2c_handle, COMMAND_START_MEASUREMENT, 2) < 0) {
        log_error("Failed to send start measurement command");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (!should_exit) {
        unsigned char buffer[RAW_FLOW_SIZE + CRC_CHECKSUM_SIZE];
        if (i2cRead(i2c_handle, buffer, RAW_FLOW_SIZE + CRC_CHECKSUM_SIZE) < 0) {
            log_error("Failed to read from I2C bus");
            continue;
        }

        unsigned short raw_flow = (buffer[0] << 8) | buffer[1];
        unsigned char crc = buffer[2];

        if (calculate_crc8(buffer, RAW_FLOW_SIZE) != crc) {
            log_error("CRC check failed for flow reading");
            continue;
        }

        double flow_rate = (double)raw_flow / 1000.0;
        log_flow(flow_rate);

        usleep(1000000); // Sleep for 1000 ms
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

