#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define TVOC_REG 0x00
#define TVOC_SIZE 2
#define ECO2_REG 5
#define ECO2_SIZE 2

static int i2c_handle;
static FILE *log_file;

void log_data(int iaq, int tvoc, int eco2) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, iaq, tvoc, eco2);
    fflush(log_file);
}

void handle_sigint(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    signal(SIGINT, handle_sigint);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("air_quality_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file 'air_quality_log.csv'\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (1) {
        uint8_t buffer[TVOC_SIZE + ECO2_SIZE];
        int read_bytes = i2cRead(i2c_handle, TVOC_REG, buffer, TVOC_SIZE + ECO2_SIZE);
        if (read_bytes < 0) {
            fprintf(stderr, "I2C read error: %d\n", read_bytes);
            continue;
        }
        if (read_bytes != TVOC_SIZE + ECO2_SIZE) {
            fprintf(stderr, "I2C read incomplete: %d bytes read\n", read_bytes);
            continue;
        }

        int tvoc = (buffer[0] << 8) | buffer[1];
        int eco2 = (buffer[4] << 8) | buffer[5];

        int iaq = clamp(100 - (tvoc / 10.0) - ((eco2 - 400) / 50.0), 0, 100);

        log_data(iaq, tvoc, eco2);

        sleep(5);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

int clamp(int value, int min, int max) {
    return value < min ? min : (value > max ? max : value);
}

