#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define PCM_DEVICE "hw:C0D0c"
#define PCM_FORMAT SND_PCM_FORMAT_S32_LE
#define PCM_RATE 44100
#define PCM_CHANNELS 1
#define PCM_BUFFER_SIZE 4096
#define PCM_FILE "audio_capture.pcm"

static int gpiod_fd;
static int pcm_fd;
static int pcm_buffer[PCM_BUFFER_SIZE];
static FILE *pcm_file;
static volatile sig_atomic_t should_exit = 0;

static void handle_signal(int signum) {
    should_exit = 1;
}

static int init_gpiod() {
    const char *chip_name = "gpiochip0";
    const char *line_name = "17";
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, line_name);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_request_output(line, "audio_capture", 0);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set GPIO line value");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

static int init_alsa() {
    snd_pcm_t *handle;
    snd_pcm_hw_params_t *params;
    int err;

    err = snd_pcm_open(&handle, PCM_DEVICE, SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "Failed to open PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_malloc(&params);
    if (err < 0) {
        fprintf(stderr, "Failed to allocate PCM parameters: %s\n", snd_strerror(err));
        snd_pcm_close(handle);
        return -1;
    }

    err = snd_pcm_hw_params_any(handle, params);
    if (err < 0) {
        fprintf(stderr, "Failed to initialize PCM parameters: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(params);
        snd_pcm_close(handle);
        return -1;
    }

    err = snd_pcm_hw_params_set_format(handle, params, PCM_FORMAT);
    if (err < 0) {
        fprintf(stderr, "Failed to set PCM format: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(params);
        snd_pcm_close(handle);
        return -1;
    }

    err = snd_pcm_hw_params_set_rate_near(handle, params, &PCM_RATE, 0);
    if (err < 0) {
        fprintf(stderr, "Failed to set PCM rate: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(params);
        snd_pcm_close(handle);
        return -1;
    }

    err = snd_pcm_hw_params_set_channels(handle, params, PCM_CHANNELS);
    if (err < 0) {
        fprintf(stderr, "Failed to set PCM channels: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(params);
        snd_pcm_close(handle);
        return -1;
    }

    err = snd_pcm_hw_params(handle, params);
    if (err < 0) {
        fprintf(stderr, "Failed to set PCM hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_hw_params_free(params);
        snd_pcm_close(handle);
        return -1;
    }

    snd_pcm_hw_params_free(params);
    return 0;
}

static int read_audio_data() {
    int frames_read;
    int i;

    frames_read = snd_pcm_readi(pcm_fd, pcm_buffer, PCM_BUFFER_SIZE);
    if (frames_read < 0) {
        if (frames_read == -EAGAIN) {
            return 0;
        }
        fprintf(stderr, "Failed to read PCM data: %s\n", snd_strerror(frames_read));
        return -1;
    }

    for (i = 0; i < frames_read; i++) {
        int32_t sample = pcm_buffer[i];
        int16_t pcm_sample = (sample >> 8) & 0xFFFF;
        fwrite(&pcm_sample, sizeof(int16_t), 1, pcm_file);
    }

    return 0;
}

static void cleanup() {
    if (pcm_file) {
        fclose(pcm_file);
    }
    if (pcm_fd >= 0) {
        snd_pcm_close(pcm_fd);
    }
    if (gpiod_fd >= 0) {
        close(gpiod_fd);
    }
}

int main() {
    int err;

    // Register signal handler
    signal(SIGINT, handle_signal);

    // Initialize GPIO
    gpiod_fd = init_gpiod();
    if (gpiod_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize ALSA
    pcm_fd = init_alsa();
    if (pcm_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Open PCM file
    pcm_file = fopen(PCM_FILE, "wb");
    if (!pcm_file) {
        fprintf(stderr, "Failed to open PCM file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        err = read_audio_data();
        if (err < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

