        return -1;
    }

    for (i = 0; i < frames_read; i++) {
        int32_t sample = pcm_buffer[i];
        int16_t pcm_sample = (sample >> 8) & 0xFFFF;
        fwrite(&pcm_sample, sizeof(int16_t), 1, pcm_file);
    }

    return 0;
}

static void cleanup() {
    if (pcm_file) {
        fclose(pcm_file);
    }
    if (pcm_fd >= 0) {
        snd_pcm_close(pcm_fd);
    }
    if (gpiod_fd >= 0) {
        close(gpiod_fd);
    }
}

int main() {
    int err;

    // Register signal handler
    signal(SIGINT, handle_signal);

    // Initialize GPIO
    gpiod_fd = init_gpiod();
    if (gpiod_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Initialize ALSA
    pcm_fd = init_alsa();
    if (pcm_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    // Open PCM file
    pcm_file = fopen(PCM_FILE, "wb");
    if (!pcm_file) {
        fprintf(stderr, "Failed to open PCM file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        err = read_audio_data();
        if (err < 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}
