#define DEBOUNCE_DELAY 50
#define LOG_FILE "flame_log.txt"

static volatile int flame_detected = 0;
static volatile int fan_running = 0;
static volatile int fan_duty = 0;
static volatile int flame_start_time = 0;
static volatile int flame_end_time = 0;
static volatile int flame_duration = 0;
static volatile int flame_count = 0;
static volatile int sensor_absent = 0;
static volatile int sensor_absent_timeout = 5000; // 5 seconds
static volatile int sensor_absent_timer = 0;

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    FILE *log = fopen(LOG_FILE, "a");
    if (log) {
        fprintf(log, "%s %s\n", timestamp, event);
        fclose(log);
    }
}

static void handle_sigint(int signum) {
    log_event("Shutdown");
    if (fan_running) {
        gpioPWMWrite(FAN_PIN, 0);
        fan_running = 0;
    }
    gpioSetMode(FAN_PIN, PI_INPUT);
    gpioSetMode(FLAME_PIN, PI_INPUT);
    gpioTerminate();
    exit(0);
}

static void handle_sigterm(int signum) {
    log_event("Shutdown");
    if (fan_running) {
        gpioPWMWrite(FAN_PIN, 0);
        fan_running = 0;
    }
    gpioSetMode(FAN_PIN, PI_INPUT);
    gpioSetMode(FLAME_PIN, PI_INPUT);
    gpioTerminate();
    exit(0);
}

static void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
    gpioSetMode(FLAME_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetPWMFrequency(FAN_PIN, FAN_FREQ);
    gpioSetPWMRange(FAN_PIN, FAN_DUTY_MAX);
    gpioSetPullUpDown(FLAME_PIN, PI_PUD_UP);
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);
}

static void check_sensor_absent() {
    if (sensor_absent_timer > 0) {
        sensor_absent_timer--;
        if (sensor_absent_timer == 0) {
            sensor_absent = 1;
            log_event("Sensor absent");
        }
    }
}

static void monitor_flame() {
    int flame_state = gpioRead(FLAME_PIN);
    if (flame_state == 0) {
        if (!flame_detected) {
            flame_detected = 1;
            flame_start_time = time(NULL);
            log_event("Flame detected");
        }
    } else {
        if (flame_detected) {
            flame_detected = 0;
            flame_end_time = time(NULL);
            flame_duration = flame_end_time - flame_start_time;
            log_event("Flame ended");
            if (flame_duration > 0) {
                fan_running = 1;
                fan_duty = (int)(exp((double)flame_duration / 1000) * FAN_DUTY_MAX);
                if (fan_duty > FAN_DUTY_MAX) {
                    fan_duty = FAN_DUTY_MAX;
                }
                gpioPWMWrite(FAN_PIN, fan_duty);
            }
        }
    }
    check_sensor_absent();
}

int main() {
    setup_gpio();
    while (1) {
        monitor_flame();
        usleep(50000); // 50 ms
    }
    return 0;
}

