#define LOG_FILE "mmwave_data.log"
#define MAGIC_NUMBER 0x52444144
#define TIMESTAMP_SIZE 8
#define CONFIG_SIZE 24
#define FRAME_SIZE 32768

typedef struct {
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint16_t chirps;
    uint16_t samples;
    uint16_t frame_period;
} mmwave_config_t;

void log_header(mmwave_config_t *config) {
    FILE *file = fopen(LOG_FILE, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    fwrite(&MAGIC_NUMBER, sizeof(uint32_t), 1, file);
    time_t now = time(NULL);
    fwrite(&now, sizeof(time_t), 1, file);
    fwrite(config, sizeof(mmwave_config_t), 1, file);

    fclose(file);
}

void log_frame(uint32_t frame_number, uint32_t timestamp, const uint8_t *data) {
    FILE *file = fopen(LOG_FILE, "ab");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    fwrite(&frame_number, sizeof(uint32_t), 1, file);
    fwrite(&timestamp, sizeof(time_t), 1, file);
    fwrite(data, FRAME_SIZE, 1, file);

    fclose(file);
}

void handle_signal(int signum) {
    gpioTerminate();
    fclose(log_file);
    exit(EXIT_SUCCESS);
