#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 20
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    int fd;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    char timestamp[20];
    char log_entry[100];
    int prev_state = -1;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request the line
    line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the line as input
    if (gpiod_line_request_input(line, "flame_sensor")) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!should_exit) {
        // Get the current state of the line
        int current_state = gpiod_line_get_value(line);
        if (current_state == -1) {
            perror("Failed to read GPIO line value");
            break;
        }

        // Check for state transition
        if (current_state != prev_state) {
            // Get the current time
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&ts.tv_sec));

            // Log the state transition
            snprintf(log_entry, sizeof(log_entry), "%s: Flame %s\n", timestamp, current_state ? "detected" : "cleared");
            if (fprintf(log_file, "%s", log_entry) < 0) {
                perror("Failed to write to log file");
                break;
            }
        }

        // Update previous state
        prev_state = current_state;

        // Sleep for the poll interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

