#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define OPT3001_ADDR 0x44
#define OPT3001_REG_CONFIG 0x01
#define OPT3001_REG_RESULT 0x00
#define OPT3001_CONFIG_CONTINUOUS 0x00
#define OPT3001_CONFIG_100MS 0x01
#define OPT3001_CONFIG_AFSR_16X 0x00

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void sig_handler(int sig) {
    should_exit = 1;
}

void log_light_data(uint16_t lux) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f\n", timestamp, lux);
    fflush(log_file);
}

void read_opt3001() {
    uint16_t result;
    int retries = 3;

    while (retries--) {
        if (i2c_read_word_data(i2c_handle, OPT3001_REG_RESULT, &result) < 0) {
            fprintf(stderr, "I2C read error\n");
            sleep(1);
            continue;
        }

        uint16_t exponent = (result >> 12) & 0xF;
        uint16_t mantissa = result & 0xFFF;
        float lux = 0.01 * pow(2, exponent) * mantissa;

        log_light_data(lux);
        sleep(1);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (i2cHandleOpen(&i2c_handle, OPT3001_ADDR, 1) < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, OPT3001_REG_CONFIG, OPT3001_CONFIG_CONTINUOUS | OPT3001_CONFIG_100MS | OPT3001_CONFIG_AFSR_16X) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("light_data.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!should_exit) {
        read_opt3001();
    }

    fclose(log_file);
    i2cHandleClose(i2c_handle);
    gpioTerminate();

    return 0;
}

