        fprintf(stderr, "Failed to create line configuration: %s\n", gpiod_strerror(gpiod_last_error()));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the line as input with bias pulled up
    settings = gpiod_line_settings_new();
    if (!settings) {
        fprintf(stderr, "Failed to create line settings: %s\n", gpiod_strerror(gpiod_last_error()));
        gpiod_line_config_free(config);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    settings->direction = GPIOD_LINE_DIRECTION_INPUT;
    settings->bias = GPIOD_LINE_BIAS_PULL_UP;

    ret = gpiod_line_config_set_settings(config, line_name, settings);
    if (ret) {
        fprintf(stderr, "Failed to set line settings: %s\n", gpiod_strerror(gpiod_last_error()));
        gpiod_line_settings_free(settings);
        gpiod_line_config_free(config);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line
    line = gpiod_chip_request_lines(chip, config, 1, &line_name);
    if (!line) {
        fprintf(stderr, "Failed to request line: %s\n", gpiod_strerror(gpiod_last_error()));
        gpiod_line_settings_free(settings);
        gpiod_line_config_free(config);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!exit_flag) {
        int value;
        time_t now;
        struct tm *tm_info;
        char timestamp[20];

        // Get the current time
        now = time(NULL);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        // Read the line value
        value = gpiod_line_request_get_value(line);
        if (value == -1) {
            fprintf(stderr, "Failed to read line value: %s\n", gpiod_strerror(gpiod_last_error()));
            break;
        }

        // Log the flame detection status
        if (value == FLAME_DETECTED) {
            printf("%s Flame Detected: YES\n", timestamp);
        } else {
            printf("%s Flame Detected: NO\n", timestamp);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up resources
    gpiod_line_request_free(line);
    gpiod_line_settings_free(settings);
    gpiod_line_config_free(config);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}
