#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define GPIO_BASE 2
#define GPIO_INTERVAL 100

static volatile sig_atomic_t should_exit = 0;

void handle_sigint(int signum) {
    should_exit = 1;
}

int main() {
    const char *chip_name = "gpiochip0";
    const char *line_names[NUM_CHANNELS] = {"2", "3", "4", "5", "6", "7", "8", "9"};
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_CHANNELS];
    int i, ret;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open(chip_name);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(gpiod_last_error()));
        return EXIT_FAILURE;
    }

    // Request lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_BASE + i);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request line %s: %s\n", line_names[i], gpiod_strerror(gpiod_last_error()));
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Set line direction to input
    for (i = 0; i < NUM_CHANNELS; i++) {
        ret = gpiod_line_request_input(lines[i], "touch_sensor");
        if (ret) {
            fprintf(stderr, "Failed to set line %s to input: %s\n", line_names[i], gpiod_strerror(gpiod_last_error()));
            gpiod_line_release(lines[i]);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    while (!should_exit) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            ret = gpiod_line_get_value(lines[i]);
            if (ret < 0) {
                fprintf(stderr, "Failed to read line %s: %s\n", line_names[i], gpiod_strerror(gpiod_last_error()));
                break;
            }
            printf("Channel %d: %d\n", i, ret);
        }
        usleep(GPIO_INTERVAL * 1000);
    }

    // Release lines
    for (i = 0; i < NUM_CHANNELS; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

