#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define GPIO_BASE 2
#define DELAY_MS 100

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        int gpio = GPIO_BASE + i;
        if (gpioSetMode(gpio, PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", gpio);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(gpio, PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to set pull-down resistor for GPIO %d\n", gpio);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = DELAY_MS * 1000000;

    while (keep_running) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "[%Y-%m-%d %H:%M:%S]", tm);

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int gpio = GPIO_BASE + i;
            int state = gpioRead(gpio);
            printf("%s CH%d=%d ", timestamp, i + 1, state);
        }
        printf("\n");

        if (nanosleep(&ts, NULL) < 0) {
            perror("nanosleep");
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

