#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINES "2,3,4,17,27,22,10,9"
#define POLL_INTERVAL_MS 50

static gpiod_chip *chip;
static gpiod_line *lines[8];
static int running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

int main() {
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};
    struct tm *tm;
    char timestamp[20];
    char line_state[9];
    FILE *log_file;

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    for (int i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            perror("Failed to request GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Configure lines as input with bias disabled
    for (int i = 0; i < 8; i++) {
        if (gpiod_line_request_input(lines[i], "touch_sensor", GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE)) {
            perror("Failed to configure GPIO line as input");
            gpiod_chip_close(chip);
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            exit(EXIT_FAILURE);
        }
    }

    // Open log file
    log_file = fopen("touch_sensor_log.csv", "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(chip);
        for (int i = 0; i < 8; i++) {
            gpiod_line_release(lines[i]);
        }
        exit(EXIT_FAILURE);
    }

    // Log header
    fprintf(log_file, "Timestamp,Line1,Line2,Line3,Line4,Line5,Line6,Line7,Line8\n");

    // Main loop
    while (running) {
        // Get current time
        time_t now = time(NULL);
        tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        // Read line states
        for (int i = 0; i < 8; i++) {
            int value = gpiod_line_get_value(lines[i]);
            line_state[i] = value ? '1' : '0';
        }
        line_state[8] = '\0';

        // Log to file
        fprintf(log_file, "%s,%s\n", timestamp, line_state);

        // Sleep for poll interval
        nanosleep(&poll_interval, NULL);
    }

    // Close log file
    fclose(log_file);

    // Release resources
    for (int i = 0; i < 8; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

