#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PART_ID_REG 0x00
#define HW_KEY_REG 0x01
#define CHLIST_REG 0x01
#define ALS_FORCE_CMD 0x06
#define UV_INDEX_REG 0x02
#define ALS_VIS_REG 0x03

static int gpiod_handle = -1;
static FILE *log_file = NULL;

void signal_handler(int signum) {
    if (gpiod_handle != -1) {
        gpioTerminate();
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpiod_handle = gpioOpen(0, 0);
    if (gpiod_handle < 0) {
        fprintf(stderr, "Failed to open GPIO handle\n");
        gpioTerminate();
        return 1;
    }

    if (i2cOpen(gpiod_handle, I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify PART ID
    uint8_t part_id;
    if (i2cReadReg8(gpiod_handle, I2C_BUS, I2C_ADDR, PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART ID\n");
        i2cClose(gpiod_handle);
        gpioTerminate();
        return 1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02x\n", part_id);
        i2cClose(gpiod_handle);
        gpioTerminate();
        return 1;
    }

    // Write HW_KEY
    if (i2cWriteReg8(gpiod_handle, I2C_BUS, I2C_ADDR, HW_KEY_REG, 0x17) < 0) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        i2cClose(gpiod_handle);
        gpioTerminate();
        return 1;
    }

    // Configure CHLIST
    if (i2cWriteReg8(gpiod_handle, I2C_BUS, I2C_ADDR, CHLIST_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to configure CHLIST\n");
        i2cClose(gpiod_handle);
        gpioTerminate();
        return 1;
    }

    // Trigger ALS_FORCE command
    if (i2cWriteReg8(gpiod_handle, I2C_BUS, I2C_ADDR, ALS_FORCE_CMD, 0x06) < 0) {
        fprintf(stderr, "Failed to trigger ALS_FORCE\n");
        i2cClose(gpiod_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("uv_als_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(gpiod_handle);
        gpioTerminate();
        return 1;
    }

    struct timespec sleep_time = {1, 0}; // 1 second

    while (1) {
        // Read UV index
        uint8_t uv_index;
        if (i2cReadReg8(gpiod_handle, I2C_BUS, I2C_ADDR, UV_INDEX_REG, &uv_index) < 0) {
            fprintf(stderr, "Failed to read UV index\n");
            break;
        }

        // Read ALS Visible
        uint16_t als_visible;
        if (i2cReadReg16(gpiod_handle, I2C_BUS, I2C_ADDR, ALS_VIS_REG, &als_visible) < 0) {
            fprintf(stderr, "Failed to read ALS Visible\n");
            break;
        }

        // Log data
        time_t now = time(NULL);
        fprintf(log_file, "%ld,%d,%d\n", now, uv_index, als_visible);

        // Sleep for 1 second
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    fclose(log_file);
    i2cClose(gpiod_handle);
    gpioTerminate();

    return 0;
}

