static int flow_rate1, flow_rate2;
static int log_entries = 0;
static int alarm_state = 0;

static void sig_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (log_file) fclose(log_file);
        if (alarm_line) gpiod_line_release(alarm_line);
        if (chip) gpiod_chip_close(chip);
        if (i2c_fd1 >= 0) close(i2c_fd1);
        if (i2c_fd2 >= 0) close(i2c_fd2);
        exit(EXIT_SUCCESS);
    }
}

static void log_flow_rate() {
    if (log_entries >= MAX_LOG_ENTRIES) {
        log_entries = 0;
    }
    fprintf(log_file, "%d, %d, %d\n", flow_rate1, flow_rate2, log_entries++);
}

static void set_alarm_state(int state) {
    if (alarm_line) {
        gpiod_line_set_value(alarm_line, state);
    }
}

static int calculate_crc(const unsigned char *data, int length) {
    int crc = CRC_INIT;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_sensor(int i2c_fd, int addr, int cmd_reg, int data_reg, int *flow_rate) {
    unsigned char cmd[2] = {cmd_reg, 0};
    unsigned char data[MAX_READS];
    int ret;

    ret = ioctl(i2c_fd, I2C_RDWR, &cmd);
    if (ret < 0) {
        perror("ioctl(I2C_RDWR)");
        return -1;
    }

    ret = read(i2c_fd, data, MAX_READS);
    if (ret < 0) {
        perror("read");
        return -1;
    }

    if (ret != MAX_READS) {
        fprintf(stderr, "Unexpected read length: %d\n", ret);
        return -1;
    }

    int crc = calculate_crc(data, MAX_READS - 1);
    if (crc != data[MAX_READS - 1]) {
        fprintf(stderr, "CRC failure\n");
        return -1;
    }

    *flow_rate = (data[0] << 8) | data[1];
    if (*flow_rate & 0x8000) {
        *flow_rate = -(*flow_rate & 0x7FFF);
    }

    return 0;
}

static void init_sensors() {
    i2c_fd1 = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd1 < 0) {
        perror("open(i2c-1)");
        exit(EXIT_FAILURE);
    }

    i2c_fd2 = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd2 < 0) {
        perror("open(i2c-1)");
        close(i2c_fd1);
        exit(EXIT_FAILURE);
    }

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        close(i2c_fd1);
        close(i2c_fd2);
        exit(EXIT_FAILURE);
    }

    alarm_line = gpiod_line_request_output(chip, "alarm", ALARM_PIN, 0);
    if (!alarm_line) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        close(i2c_fd1);
        close(i2c_fd2);
        exit(EXIT_FAILURE);
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("fopen(flow_log.txt)");
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        close(i2c_fd1);
        close(i2c_fd2);
        exit(EXIT_FAILURE);
    }

    unsigned char start_cmd[2] = {I2C_CMD_REG, 0x3608};
    ret = write(i2c_fd1, start_cmd, 2);
    if (ret < 0) {
        perror("write(i2c_fd1)");
        fclose(log_file);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        close(i2c_fd1);
        close(i2c_fd2);
        exit(EXIT_FAILURE);
    }

    ret = write(i2c_fd2, start_cmd, 2);
    if (ret < 0) {
        perror("write(i2c_fd2)");
        fclose(log_file);
        gpiod_line_release(alarm_line);
        gpiod_chip_close(chip);
        close(i2c_fd1);
        close(i2c_fd2);
        exit(EXIT_FAILURE);
    }

    usleep(100000); // Wait 100 ms for the first measurement
}

static void read_sensors() {
    int ret;

    ret = read_sensor(i2c_fd1, I2C_ADDR1, I2C_CMD_REG, I2C_DATA_REG, &flow_rate1);
    if (ret < 0) {
        fprintf(stderr, "Error reading sensor 1\n");
    } else {
        flow_rate1 *= SCALE_FACTOR;
    }

    ret = read_sensor(i2c_fd2, I2C_ADDR2, I2C_CMD_REG, I2C_DATA_REG, &flow_rate2);
    if (ret < 0) {
        fprintf(stderr, "Error reading sensor 2\n");
    } else {
        flow_rate2 *= SCALE_FACTOR;
    }

    int average_flow_rate = (flow_rate1 + flow_rate2) / 2;
    log_flow_rate();
    set_alarm_state(average_flow_rate < MAX_FLOW_RATE);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    init_sensors();

    while (1) {
        read_sensors();
        sleep(LOG_INTERVAL);
    }

    return 0;
}
```

This C program initializes two Sensirion SLF3S-0600F Liquid Flow Sensors on I2C at addresses 0x36 and 0x37, reads their flow rates, and logs them to 'flow_log.txt'. It also drives an alarm on GPIO 17 high when the average flow rate is below 0.5 ml/min and low otherwise. The program handles errors, releases resources on all exit paths, and implements clean shutdown on SIGINT/SIGTERM.

