#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define GPIO_PIN 4
#define POLL_INTERVAL_MS 50

typedef struct {
    time_t timestamp;
    int reading;
} ObstacleDetection;

ObstacleDetection buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void handle_sigint(int signum) {
    printf("SIGINT received. Printing buffer contents:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        time_t current_time = time(NULL);
        struct tm *tm_info = localtime(&buffer[(buffer_tail + i) % BUFFER_SIZE].timestamp);
        printf("%s: %d\n", asctime(tm_info), buffer[(buffer_tail + i) % BUFFER_SIZE].reading);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO %d pull-up resistor\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        int reading = gpioRead(GPIO_PIN);
        if (reading == 0) {
            buffer[buffer_head].timestamp = time(NULL);
            buffer[buffer_head].reading = reading;
            buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    return 0;
}

