#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x55
#define MODE_CONTROL 0x1D
#define OPERATING_STATUS 0x1B
#define X_ACCEL 0x2A
#define Y_ACCEL 0x2C
#define Z_ACCEL 0x2E
#define SCALE_FACTOR 0.0009765625

static int i2c_fd;
static FILE *csv_file;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *sda_line, *scl_line;

static void handle_signal(int sig) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (csv_file) {
        fclose(csv_file);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    exit(0);
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(1);
    }
}

static void init_gpio() {
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }
    sda_line = gpiod_chip_get_line(gpio_chip, 2);
    if (!sda_line) {
        perror("Failed to get SDA line");
        gpiod_chip_close(gpio_chip);
        exit(1);
    }
    scl_line = gpiod_chip_get_line(gpio_chip, 3);
    if (!scl_line) {
        perror("Failed to get SCL line");
        gpiod_line_release(sda_line);
        gpiod_chip_close(gpio_chip);
        exit(1);
    }
    gpiod_line_request_output(sda_line, "I2C SDA", 0);
    gpiod_line_request_output(scl_line, "I2C SCL", 0);
}

static void write_register(uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to I2C register");
    }
}

static uint8_t read_register(uint8_t reg) {
    uint8_t buf[1] = {reg};
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Failed to write to I2C register");
        return 0;
    }
    if (read(i2c_fd, buf, 1) != 1) {
        perror("Failed to read from I2C register");
        return 0;
    }
    return buf[0];
}

static void init_sensor() {
    write_register(MODE_CONTROL, 0x10); // Switch to active mode
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        if (read_register(OPERATING_STATUS) & 0x01) {
            break;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (difftime(end.tv_sec, start.tv_sec) >= 1) {
            fprintf(stderr, "Sensor did not become active within 1 second\n");
            exit(1);
        }
        usleep(100000); // Sleep for 100 ms
    }
}

static void log_sample(int64_t timestamp, int16_t x, int16_t y, int16_t z) {
    char buf[256];
    snprintf(buf, sizeof(buf), "%lld,%d,%d,%d\n", timestamp, x, y, z);
    if (fputs(buf, csv_file) == EOF) {
        perror("Failed to write to CSV file");
    }
}

static void read_accelerometer() {
    uint8_t buf[8];
    if (read(i2c_fd, buf, 8) != 8) {
        perror("Failed to read from I2C registers");
        return;
    }
    int16_t x = (buf[0] << 8) | buf[1];
    int16_t y = (buf[2] << 8) | buf[3];
    int16_t z = (buf[4] << 8) | buf[5];
    log_sample(time(NULL) * 1000000000 + clock_gettime(CLOCK_MONOTONIC, NULL)->tv_nsec / 1000, x, y, z);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_i2c();
    init_sensor();

    csv_file = fopen("fan_health.csv", "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        exit(1);
    }
    if (fputs("timestamp,x,y,z\n", csv_file) == EOF) {
        perror("Failed to write header to CSV file");
        fclose(csv_file);
        exit(1);
    }

    while (1) {
        read_accelerometer();
        usleep(500000); // Sleep for 500 ms
    }

    fclose(csv_file);
    gpiod_line_release(sda_line);
    gpiod_line_release(scl_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

