        // Turn LED on if either sensor detects an obstacle
        if (sensor1_state == 0 || sensor2_state == 0) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        // Sleep for the specified interval
        usleep(POLL_INTERVAL);
    }

    // Clean up resources
    gpioTerminate();

    return EXIT_SUCCESS;
}
