#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x0E
#define DEVICE_ID_REG 0x00
#define X_AXIS_REG 0x01
#define Y_AXIS_REG 0x03
#define Z_AXIS_REG 0x05
#define LSB_SCALE_FACTOR 0.000125 // 50 mT range, 16-bit two's-complement

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void sig_handler(int sig) {
    should_exit = 1;
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle == -1) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    uint16_t device_id;
    if (i2cReadWordData(i2c_handle, DEVICE_ID_REG, &device_id) < 0) {
        fprintf(stderr, "Failed to read device ID from sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (device_id != 0x8D) {
        fprintf(stderr, "Device ID mismatch, expected 0x8D, got 0x%04X\n", device_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    log_file = fopen("magnetic_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file 'magnetic_log.csv'\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    struct timespec sleep_time = {0, 100000000}; // 100 ms

    while (!should_exit) {
        uint16_t x, y, z;
        if (i2cReadWordData(i2c_handle, X_AXIS_REG, &x) < 0) {
            fprintf(stderr, "Failed to read X-axis data from sensor\n");
        }
        if (i2cReadWordData(i2c_handle, Y_AXIS_REG, &y) < 0) {
            fprintf(stderr, "Failed to read Y-axis data from sensor\n");
        }
        if (i2cReadWordData(i2c_handle, Z_AXIS_REG, &z) < 0) {
            fprintf(stderr, "Failed to read Z-axis data from sensor\n");
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        fprintf(log_file, "%s,%f,%f,%f\n", timestamp, (float)x * LSB_SCALE_FACTOR, (float)y * LSB_SCALE_FACTOR, (float)z * LSB_SCALE_FACTOR);
        fflush(log_file);

        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

