#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL 1000000 // 1 second in microseconds

static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file;

static void signal_handler(int signum) {
    running = 0;
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

static void callback(int gpio, int level, uint32_t tick) {
    if (level == PI_RISING_EDGE) {
        atomic_fetch_add(&pulse_count, 1);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(GPIO_PIN, callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct timespec sleep_time = {0, SAMPLE_INTERVAL};
    while (running) {
        nanosleep(&sleep_time, NULL);

        int pulses_per_second = pulse_count;
        pulse_count = 0;

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, "%s %d\n", timestamp, pulses_per_second * 60);
        fflush(log_file);

        printf("%s %d\n", timestamp, pulses_per_second * 60);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

