        fprintf(stderr, "Failed to set pull-up resistor for GPIO B\n");
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, quadrature_state_machine, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        // Main loop can be a sleep or condition variable wait
        // For simplicity, we'll just sleep
        sleep(1);
    }

    pthread_join(thread, NULL);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

