#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_TOUCH_PIN 23
#define GPIO_LED_PIN 18
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t should_exit = 0;

void sig_handler(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *touch_line, *led_line;
    struct gpiod_line_request req;
    int value;
    struct timespec sleep_time;

    // Initialize logging
    openlog("touch_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip %s", GPIO_CHIP_NAME);
        exit(EXIT_FAILURE);
    }

    // Request line for touch sensor
    req.consumer = "touch_sensor";
    req.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    req.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    ret = gpiod_chip_get_line(chip, GPIO_TOUCH_PIN, &touch_line);
    if (ret) {
        syslog(LOG_ERR, "Failed to get line %d from chip %s", GPIO_TOUCH_PIN, GPIO_CHIP_NAME);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request(touch_line, &req);
    if (ret) {
        syslog(LOG_ERR, "Failed to request line %d from chip %s", GPIO_TOUCH_PIN, GPIO_CHIP_NAME);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request line for LED
    ret = gpiod_chip_get_line(chip, GPIO_LED_PIN, &led_line);
    if (ret) {
        syslog(LOG_ERR, "Failed to get line %d from chip %s", GPIO_LED_PIN, GPIO_CHIP_NAME);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request(led_line, &req);
    if (ret) {
        syslog(LOG_ERR, "Failed to request line %d from chip %s", GPIO_LED_PIN, GPIO_CHIP_NAME);
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    syslog(LOG_INFO, "Touch sensor and LED initialized");

    while (!should_exit) {
        // Read touch sensor
        ret = gpiod_line_get_value(touch_line, &value);
        if (ret) {
            syslog(LOG_ERR, "Failed to read touch sensor line %d", GPIO_TOUCH_PIN);
            continue;
        }

        // Turn LED on if touch sensor is active
        if (value == 0) {
            ret = gpiod_line_set_value(led_line, 1);
            if (ret) {
                syslog(LOG_ERR, "Failed to turn on LED line %d", GPIO_LED_PIN);
            }
        } else {
            ret = gpiod_line_set_value(led_line, 0);
            if (ret) {
                syslog(LOG_ERR, "Failed to turn off LED line %d", GPIO_LED_PIN);
            }
        }

        // Sleep for 50 ms
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000;
        nanosleep(&sleep_time, NULL);
    }

    // Release lines and close chip
    gpiod_line_release(touch_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    syslog(LOG_INFO, "Touch sensor and LED shutdown");

    closelog();

    return EXIT_SUCCESS;
}

