#define GPIO_TTP223B 17
#define GPIO_LED 18
#define DEBOUNCE_TIME_MS 50

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    const char *chip_name = "gpiochip0";
    const char *line_name_ttp223b = "gpio17";
    const char *line_name_led = "gpio18";
    struct gpiod_chip *chip;
    struct gpiod_line *line_ttp223b, *line_led;
    struct gpiod_line_event event;
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(gpiod_last_error()));
        return EXIT_FAILURE;
    }

    // Request lines
    line_ttp223b = gpiod_chip_get_line(chip, GPIO_TTP223B);
    if (!line_ttp223b) {
        fprintf(stderr, "Failed to get line %s: %s\n", line_name_ttp223b, gpiod_strerror(gpiod_last_error()));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line_led = gpiod_chip_get_line(chip, GPIO_LED);
    if (!line_led) {
        fprintf(stderr, "Failed to get line %s: %s\n", line_name_led, gpiod_strerror(gpiod_last_error()));
        gpiod_line_release(line_ttp223b);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set line direction
    ret = gpiod_line_request_input(line_ttp223b, "touch_sensor");
    if (ret) {
        fprintf(stderr, "Failed to request line %s as input: %s\n", line_name_ttp223b, gpiod_strerror(ret));
        gpiod_line_release(line_ttp223b);
        gpiod_line_release(line_led);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line_led, "led");
    if (ret) {
        fprintf(stderr, "Failed to request line %s as output: %s\n", line_name_led, gpiod_strerror(ret));
        gpiod_line_release(line_ttp223b);
        gpiod_line_release(line_led);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set initial state of LED
    ret = gpiod_line_set_value(line_led, 0);
    if (ret) {
        fprintf(stderr, "Failed to set initial state of line %s: %s\n", line_name_led, gpiod_strerror(ret));
        gpiod_line_release(line_ttp223b);
        gpiod_line_release(line_led);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Enable event detection on rising edge
    ret = gpiod_line_event_enable(line_ttp223b, GPIOD_LINE_EVENT_RISING_EDGE);
    if (ret) {
        fprintf(stderr, "Failed to enable rising edge event detection on line %s: %s\n", line_name_ttp223b, gpiod_strerror(ret));
        gpiod_line_release(line_ttp223b);
        gpiod_line_release(line_led);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        ret = gpiod_line_event_wait(line_ttp223b, NULL);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for line event: %s\n", gpiod_strerror(ret));
            break;
        }

        ret = gpiod_line_event_read(line_ttp223b, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read line event: %s\n", gpiod_strerror(ret));
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Debounce the event
            usleep(DEBOUNCE_TIME_MS * 1000);

            // Toggle the LED
            ret = gpiod_line_set_value(line_led, !gpiod_line_get_value(line_led));
            if (ret) {
                fprintf(stderr, "Failed to toggle LED: %s\n", gpiod_strerror(ret));
                break;
            }
        }
    }

    // Clean up
    gpiod_line_event_disable(line_ttp223b);
    gpiod_line_release(line_ttp223b);
    gpiod_line_release(line_led);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

