#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define LOG_FILE "/var/log/rain_events.log"

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    FILE *log_file;
    struct timespec last_state_time;
    int current_state, last_state = -1;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up the rain sensor pin as input with internal pull-up
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for pin %d\n", RAIN_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for pin %d\n", RAIN_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Get the current time
    if (clock_gettime(CLOCK_MONOTONIC, &last_state_time) < 0) {
        fprintf(stderr, "Failed to get current time\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (keep_running) {
        // Read the current state of the rain sensor
        current_state = gpioRead(RAIN_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Failed to read pin %d\n", RAIN_SENSOR_PIN);
            break;
        }

        // Check for state transition
        if (current_state != last_state) {
            // Get the current time
            struct timespec current_time;
            if (clock_gettime(CLOCK_MONOTONIC, &current_time) < 0) {
                fprintf(stderr, "Failed to get current time\n");
                break;
            }

            // Calculate the time since the last state transition
            long long time_since_transition = (current_time.tv_sec - last_state_time.tv_sec) * 1000000000 +
                                            (current_time.tv_nsec - last_state_time.tv_nsec);

            // Log the state transition
            if (current_state == 0) {
                fprintf(log_file, "%lld: Rain Detected\n", time_since_transition);
            } else {
                fprintf(log_file, "%lld: No Rain\n", time_since_transition);
            }

            // Update the last state time
            last_state_time = current_time;

            // Update the last state
            last_state = current_state;
        }

        // Sleep for 500 ms
        if (gpioSleep(PI_TIME_RELATIVE, 0, 500000) < 0) {
            fprintf(stderr, "Failed to sleep\n");
            break;
        }
    }

    // Close the log file
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();

    return EXIT_SUCCESS;
}

