#include <signal.h>
#include <pigpio.h>
#include <errno.h>

#define GPIO_PIN1 17
#define GPIO_PIN2 18
#define DEBOUNCE_TIME_MS 5
#define RPM_CALCULATION_PERIOD_MS 1000
#define LOG_FILE "shaft_log.txt"

static int gpio1_state = 0;
static int gpio2_state = 0;
static FILE *log_file;
static int running = 1;

void signal_handler(int signum) {
    running = 0;
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Program terminated by signal %d\n", signum);
    exit(EXIT_SUCCESS);
}

void log_sensor_state() {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%d,%d\n", timestamp, gpio1_state, gpio2_state);
}

void debounce_and_count() {
    static int last_gpio1_state = 0;
    static int last_gpio2_state = 0;
    static time_t last_change_time = 0;

    int gpio1_current_state = gpioRead(GPIO_PIN1);
    int gpio2_current_state = gpioRead(GPIO_PIN2);

    if (gpio1_current_state != last_gpio1_state || gpio2_current_state != last_gpio2_state) {
        if (time(NULL) - last_change_time > DEBOUNCE_TIME_MS) {
            if (gpio1_current_state != last_gpio1_state) {
                gpio1_state = gpio1_current_state;
                log_sensor_state();
            }
            if (gpio2_current_state != last_gpio2_state) {
                gpio2_state = gpio2_current_state;
                log_sensor_state();
            }
            last_change_time = time(NULL);
        }
    }

    last_gpio1_state = gpio1_current_state;
    last_gpio2_state = gpio2_current_state;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN1, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for pin %d: %s\n", GPIO_PIN1, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for pin %d: %s\n", GPIO_PIN2, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        debounce_and_count();
        usleep(RPM_CALCULATION_PERIOD_MS * 1000);
    }

    fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

