#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define PART_ID_REG 0x00
#define CONFIG_REG 0x30
#define HR_REG 0x02
#define SPO2_REG 0x04

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int signum) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDRESS);
        gpioTerminate();
        return 1;
    }

    // Verify the sensor is present
    uint8_t part_id;
    if (i2cReadReg8(i2c_handle, PART_ID_REG, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect PART_ID register value: 0x%02X\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure the sensor for continuous measurement
    uint8_t config = 0x01; // Continuous mode
    if (i2cWriteReg8(i2c_handle, CONFIG_REG, config) < 0) {
        fprintf(stderr, "Failed to write CONFIG register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file 'biometric_log.txt'\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (!exit_flag) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        uint8_t hr;
        if (i2cReadReg8(i2c_handle, HR_REG, &hr) < 0) {
            fprintf(stderr, "Failed to read HR register\n");
            continue;
        }

        uint8_t spo2;
        if (i2cReadReg8(i2c_handle, SPO2_REG, &spo2) < 0) {
            fprintf(stderr, "Failed to read SPO2 register\n");
            continue;
        }

        fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, hr, spo2);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

