    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (!exit_flag) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        uint8_t hr;
        if (i2cReadReg8(i2c_handle, HR_REG, &hr) < 0) {
            fprintf(stderr, "Failed to read HR register\n");
            continue;
        }

        uint8_t spo2;
        if (i2cReadReg8(i2c_handle, SPO2_REG, &spo2) < 0) {
            fprintf(stderr, "Failed to read SPO2 register\n");
            continue;
        }

        fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, hr, spo2);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}
```

