#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define SDA 2
#define SCL 3
#define LED_PIN 17
#define THRESHOLD 500
#define LOG_FILE "seismic_events.log"
#define MAX_RETRIES 3

// Function to log an event to the log file
void log_event(int peak_vibration) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }
    fprintf(log, "%s, %d\n", timestamp, peak_vibration);
    fclose(log);
}

// Function to read from I2C with retries
int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_write_byte_data(fd, reg, 0) < 0) {
            fprintf(stderr, "I2C write error\n");
            return -1;
        }
        if (i2c_read_i2c_block_data(fd, reg, data, len) >= 0) {
            return 0;
        }
        retries++;
    }
    fprintf(stderr, "I2C read error after %d retries\n", MAX_RETRIES);
    return -1;
}

// Function to initialize the sensor
int init_sensor(int fd) {
    uint8_t ctrl1 = 0x00; // Clear power-down bit
    if (i2c_write_byte_data(fd, 0x1F, ctrl1) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        return -1;
    }
    return 0;
}

// Function to read acceleration data and compute magnitude
int read_acceleration(int fd, int *x, int *y, int *z) {
    uint8_t data[6];
    if (i2c_read(fd, 0x28, data, 6) < 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }
    *x = (data[0] << 8) | data[1];
    *y = (data[2] << 8) | data[3];
    *z = (data[4] << 8) | data[5];
    int magnitude = sqrt((*x * *x) + (*y * *y) + (*z * *z));
    return magnitude;
}

// Signal handler to release resources
void signal_handler(int sig) {
    gpioTerminate();
    fclose(log);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPullUpDown(LED_PIN, PI_PUD_UP);

    int fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    if (init_sensor(fd) < 0) {
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    FILE *log = fopen(LOG_FILE, "w");
    if (log == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        int x, y, z;
        int magnitude = read_acceleration(fd, &x, &y, &z);
        if (magnitude > THRESHOLD) {
            log_event(magnitude);
            gpioWrite(LED_PIN, 1);
            usleep(1000000);
            gpioWrite(LED_PIN, 0);
        }
        usleep(100000);
    }

    i2cClose(fd);
    fclose(log);
    gpioTerminate();
    return 0;
}

