#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINES 4
#define GPIO_OUT 4
#define GPIO_IN 17, 27, 22
#define GPIO_LED 18
#define POLL_INTERVAL_MS 50

static int chip = -1;
static int lines[GPIO_LINES];
static int led = -1;
static int running = 1;

static void handle_signal(int sig) {
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize libgpiod
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (chip < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    for (int i = 0; i < GPIO_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_IN + i);
        if (lines[i] < 0) {
            perror("Failed to request GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Request LED line
    led = gpiod_chip_get_line(chip, GPIO_LED);
    if (led < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set lines as input
    for (int i = 0; i < GPIO_LINES; i++) {
        if (gpiod_line_request_input(lines[i], "obstacle_sensor") < 0) {
            perror("Failed to request line as input");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Set LED as output
    if (gpiod_line_request_output(led, "led", 0) < 0) {
        perror("Failed to request line as output");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Poll lines
    while (running) {
        for (int i = 0; i < GPIO_LINES; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value == 0) {
                // Object detected, turn on LED
                gpiod_line_set_value(led, 1);
                break;
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Release resources
    gpiod_line_release(led);
    for (int i = 0; i < GPIO_LINES; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

