#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define FLAME_SENSORS 5
#define GPIO_PINS {2, 3, 4, 17, 27}
#define DEBOUNCE_TIME_MS 50
#define LOG_FILE "/var/log/flame_events.log"

static volatile sig_atomic_t exit_flag = 0;
static gpiod_chip *chip = NULL;
static gpiod_line *lines[FLAME_SENSORS];
static FILE *log_file = NULL;

static void sig_handler(int signum) {
    exit_flag = 1;
    for (int i = 0; i < FLAME_SENSORS; i++) {
        gpiod_line_release(lines[i]);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    closelog();
    exit(EXIT_SUCCESS);
}

static void log_message(const char *message) {
    syslog(LOG_USER, "%s", message);
}

static void log_error(const char *message) {
    syslog(LOG_USER | LOG_ERR, "%s", message);
}

static void log_event(const char *timestamp, int sensor_id, int pin) {
    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n",
             timestamp, sensor_id, pin);
    fprintf(log_file, "%s", log_entry);
    fflush(log_file);
}

static int read_sensor(int sensor_id, int pin) {
    int value = gpiod_line_get_value(lines[sensor_id]);
    if (value == -1) {
        log_error("Failed to read line %d", pin);
        return -1;
    }
    return value;
}

static void monitor_flame_sensors() {
    struct timespec sleep_time = {0, 1000000000 / 10}; // 1 second
    while (!exit_flag) {
        for (int i = 0; i < FLAME_SENSORS; i++) {
            int pin = GPIO_PINS[i];
            int value = read_sensor(i, pin);
            if (value == -1) {
                continue;
            }
            struct timespec start_time, end_time;
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while (value == 0) {
                clock_gettime(CLOCK_MONOTONIC, &end_time);
                if (end_time.tv_sec - start_time.tv_sec > 0) {
                    break;
                }
                usleep(100000); // 100 ms
                value = read_sensor(i, pin);
            }
            if (value == 1) {
                char timestamp[256];
                time_t now = time(NULL);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
                log_event(timestamp, i, pin);
            }
        }
        nanosleep(&sleep_time, NULL);
    }
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (gpiod_chip_open_by_name("gpiochip0", &chip) < 0) {
        log_error("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < FLAME_SENSORS; i++) {
        int pin = GPIO_PINS[i];
        lines[i] = gpiod_chip_get_line(chip, pin);
        if (!lines[i]) {
            log_error("Failed to get line %d", pin);
