#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_LINES 8
#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAMES "5 6 13 19 26 12 16 20"
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t should_exit = 0;

static void handle_sigint(int signum) {
    should_exit = 1;
}

static void log_state_change(int sensor_index, int line_number, int state) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    printf("%s TTP226 Sensor %d, Line %d: %s\n", timestamp, sensor_index, line_number, state ? "Touch Detected" : "Released");
}

static void read_touch_sensor(gpiod_chip *chip) {
    gpiod_line_bulk *lines;
    int *line_states;
    int i, state;

    lines = gpiod_chip_get_lines(chip, GPIO_LINE_NAMES, NULL);
    if (!lines) {
        fprintf(stderr, "Failed to get lines: %s\n", gpiod_strerror(gpiod_last_error()));
        exit(EXIT_FAILURE);
    }

    line_states = malloc(NUM_LINES * sizeof(int));
    if (!line_states) {
        fprintf(stderr, "Failed to allocate memory for line states\n");
        gpiod_line_bulk_put(lines);
        exit(EXIT_FAILURE);
    }

    while (!should_exit) {
        if (gpiod_line_bulk_get_value(lines, line_states, NUM_LINES) < 0) {
            fprintf(stderr, "Failed to read line values: %s\n", gpiod_strerror(gpiod_last_error()));
            free(line_states);
            gpiod_line_bulk_put(lines);
            exit(EXIT_FAILURE);
        }

        for (i = 0; i < NUM_LINES; i++) {
            state = line_states[i];
            if (state != 0) {
                log_state_change(i, i, 1);
            } else {
                log_state_change(i, i, 0);
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    free(line_states);
    gpiod_line_bulk_put(lines);
}

int main() {
    gpiod_chip *chip;
    int ret;

    signal(SIGINT, handle_sigint);

    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(gpiod_last_error()));
        exit(EXIT_FAILURE);
    }

    read_touch_sensor(chip);

    gpiod_chip_close(chip);

    return 0;
}

