#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x10
#define ALS_REG 0x04
#define CONFIG_REG 0x00
#define ALS_GAIN 0x00
#define ALS_INTEGRATION_TIME 0x00
#define LED_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100

static int i2c_handle;
static FILE *log_file;
static int led_pwm_handle;
static int led_state = 0;
static int lux = 0;
static int brightness = 0;
static int error_code = 0;

void log_data(const char *format, ...) {
    va_list args;
    char buffer[256];
    time_t now;
    struct tm *tm_info;

    now = time(NULL);
    tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    va_start(args, format);
    vsnprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), format, args);
    va_end(args);

    fprintf(log_file, "%s %d %d %d\n", buffer, lux, brightness, error_code);
    fflush(log_file);
}

void handle_signal(int signum) {
    if (led_pwm_handle != -1) {
        gpioPWMWrite(led_gpio, 0);
    }
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpioInitialise() == PI_INIT_FAILED) {
        fprintf(stderr, "Failed to initialize pigpio\n");
    } else {
        gpioTerminate();
    }
    exit(signum);
}

void setup_gpio() {
    if (gpioInitialise() == PI_INIT_FAILED) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != PI_OK) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        exit(EXIT_FAILURE);
    }
    if (gpioPWMWrite(LED_GPIO, 0) != PI_OK) {
        fprintf(stderr, "Failed to set LED PWM to 0\n");
        exit(EXIT_FAILURE);
    }
    if (gpioSetPWMFrequency(LED_GPIO, PWM_FREQ) != PI_OK) {
        fprintf(stderr, "Failed to set LED PWM frequency\n");
        exit(EXIT_FAILURE);
    }
    if (gpioSetPWMRange(LED_GPIO, PWM_RANGE) != PI_OK) {
        fprintf(stderr, "Failed to set LED PWM range\n");
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle == -1) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        exit(EXIT_FAILURE);
    }
}

void setup_sensor() {
    uint16_t config_value = (ALS_GAIN << 8) | ALS_INTEGRATION_TIME;
    if (i2cWriteWordData(i2c_handle, CONFIG_REG, config_value) != 1) {
        fprintf(stderr, "Failed to write to sensor config register\n");
        error_code = 1;
        return;
    }
}

void read_als() {
    uint16_t als_value;
    if (i2cReadWordData(i2c_handle, ALS_REG, &als_value) != 1) {
        fprintf(stderr, "Failed to read from sensor ALS register\n");
        error_code = 2;
        return;
    }
    lux = als_value * 0.0576;
}

void set_brightness() {
    if (lux < 100) {
        brightness = 100;
    } else if (lux < 500) {
        brightness = 75;
    } else if (lux < 1000) {
        brightness = 50;
    } else {
        brightness = 25;
    }
    if (gpioPWMWrite(LED_GPIO, brightness * PWM_RANGE / 100) != PI_OK) {
        fprintf(stderr, "Failed to set LED PWM\n");
        error_code = 3;
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_i2c();
    setup_sensor();

    log_file = fopen("grow_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        read_als();
        set_brightness();
        log_data("Lux: %d, Brightness: %d, Error: %d", lux, brightness, error_code);
        sleep(1);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

