#include <signal.h>
#include <pigpio.h>

#define LED_PIN 17
#define TOUCH_PINS 8
#define DEBOUNCE_DELAY 50000  // 50 ms in microseconds
#define LOG_FILE "touch_log.txt"

static int gpio_fd;
static int touch_state[TOUCH_PINS];
static int led_state = 0;
static FILE *log_file;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        // Turn off the LED
        gpioWrite(LED_PIN, 0);
        // Release pigpio resources
        gpioTerminate();
        // Close the log file
        if (log_file) {
            fclose(log_file);
        }
        // Exit the program
        exit(EXIT_SUCCESS);
    }
}

void log_touch(int channel) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char log_entry[100];
    snprintf(log_entry, sizeof(log_entry), "%04d-%02d-%02d %02d:%02d:%02d - Channel %d Touched\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec, channel);
    if (log_file) {
        if (fprintf(log_file, "%s", log_entry) < 0) {
            fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        }
    } else {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
    }
}

void debounce(int channel) {
    static int last_state = 0;
    static time_t last_change = 0;
    time_t current_time = time(NULL);
    if (current_time - last_change > DEBOUNCE_DELAY / 1000000) {
        if (gpioRead(channel) != last_state) {
            last_state = gpioRead(channel);
            if (last_state) {
                log_touch(channel);
                led_state = 1;
                gpioWrite(LED_PIN, 1);
            } else {
                led_state = 0;
                gpioWrite(LED_PIN, 0);
            }
        }
        last_change = current_time;
    }
}

