#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810
#define CONVERSION_TIME 100
#define LOG_FILE "light_data.txt"

static void sigint_handler(int signum) {
    if (signum == SIGINT) {
        printf("SIGINT received, cleaning up...\n");
        if (i2cClose(1) < 0) {
            fprintf(stderr, "Failed to close I2C handle\n");
        }
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }
    if (i2cOpen(1, OPT3001_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigint_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        // Write configuration word
        uint16_t config_word = CONFIG_WORD;
        if (i2cWriteWordData(1, CONFIG_REG, config_word) < 0) {
            fprintf(stderr, "Failed to write configuration word\n");
            continue;
        }

        // Wait for conversion time
        usleep(CONVERSION_TIME * 1000);

        // Read result register
        uint16_t result;
        if (i2cReadWordData(1, RESULT_REG, &result) < 0) {
            fprintf(stderr, "Failed to read result register\n");
            continue;
        }

        // Byte-swap the result
        uint16_t swapped_result = (result >> 8) | (result << 8);

        // Calculate lux
        int exponent = (swapped_result >> 12) & 0xF;
        int mantissa = swapped_result & 0xFFF;
        float lux = mantissa * 0.01 * (1 << exponent);

        // Log the reading
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char log_entry[100];
        strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S, %.2f\n", tm, lux);
        if (fprintf(log_file, "%s", log_entry) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
        }

        // Print the lux value to stdout
        printf("Lux: %.2f\n", lux);

        // Sleep for 1 second
        sleep(1);
    }

    // Close the log file
    if (fclose(log_file) != 0) {
        fprintf(stderr, "Failed to close log file\n");
    }

    // Clean up
    i2cClose(1);
    gpioTerminate();

    return EXIT_SUCCESS;
}

