#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define ALERT_PIN 17
#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int signum) {
    keep_running = 0;
}

int main() {
    FILE *log_file;
    struct timespec sleep_time = {0, POLL_INTERVAL_MS * 1000000};
    int flame_detected = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set FLAME_SENSOR_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set ALERT_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (keep_running) {
        // Read the flame sensor
        int flame_state = gpioRead(FLAME_SENSOR_PIN);
        if (flame_state < 0) {
            fprintf(stderr, "Failed to read FLAME_SENSOR_PIN\n");
            continue;
        }

        // Log the reading
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s: Flame sensor state: %d\n", timestamp, flame_state);

        // Check for flame detection
        if (flame_state == 0 && !flame_detected) {
            flame_detected = 1;
            // Trigger alert
            if (gpioWrite(ALERT_PIN, 1) < 0) {
                fprintf(stderr, "Failed to set ALERT_PIN HIGH\n");
            }
            // Wait for 1 second
            nanosleep(&sleep_time, NULL);
            if (gpioWrite(ALERT_PIN, 0) < 0) {
                fprintf(stderr, "Failed to set ALERT_PIN LOW\n");
            }
        } else if (flame_state == 1 && flame_detected) {
            flame_detected = 0;
        }

        // Sleep for the next poll interval
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    fclose(log_file);
    gpioWrite(ALERT_PIN, 0); // Ensure alert is off
    gpioTerminate();

    return EXIT_SUCCESS;
}

