#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_LINE 4
#define DEBOUNCE_INTERVAL 50
#define LOG_FILE "touch_log.txt"

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    char timestamp[20];
    FILE *log_file;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    // Request the line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Configure the line as input with pull-down bias
    ret = gpiod_line_request_input(line, "touch_sensor");
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line %d as input\n", GPIO_LINE);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!should_exit) {
        // Wait for a transition
        ret = gpiod_line_event_wait(line, &ts);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for line event\n");
            break;
        }

        // Get the current time
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Read the line value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line %d\n", GPIO_LINE);
            break;
        }

        // Append the appropriate message to the log file
        if (value == 0) {
            fprintf(log_file, "%s: Touch Detected\n", timestamp);
        } else {
            fprintf(log_file, "%s: Touch Released\n", timestamp);
        }

        // Flush the file
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Failed to flush log file\n");
            break;
        }

        // Wait for the debounce interval
        struct timespec sleep_ts = {0, DEBOUNCE_INTERVAL * 1000000};
        nanosleep(&sleep_ts, NULL);
    }

    // Release the line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    // Close the log file
    fclose(log_file);

    return 0;
}

