#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x08
#define COMMAND 0x3608
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define SAMPLE_RATE 1000 // 1 sample per second

static FILE *log_file;
static int i2c_handle;
static int running = 1;

void log_data(double flow_rate, int flags, const char *status) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d,%H:%M:%S", tm);

    fprintf(log_file, "%s,%f,%s\n", timestamp, flow_rate, status);
    fflush(log_file);
}

void handle_sigint(int signum) {
    running = 0;
    if (log_file) fclose(log_file);
    if (i2c_handle) gpioI2CClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int calculate_crc8(const unsigned char *data, size_t length) {
    int crc = CRC_INIT;
    for (size_t i = 0; i < length; ++i) {
        crc ^= data[i];
        for (int j = 0; j < 8; ++j) {
            crc = (crc >> 1) ^ ((crc & 1) ? CRC_POLYNOMIAL : 0);
        }
    }
    return crc;
}

int read_sensor() {
    unsigned char command[2] = {COMMAND >> 8, COMMAND & 0xFF};
    unsigned char data[3];
    int bytes_read;

    if (gpioI2CWrite(i2c_handle, command, 2) < 0) {
        log_data(0.0, 0, "ERROR");
        return -1;
    }

    if (gpioI2CRead(i2c_handle, data, 3) < 0) {
        log_data(0.0, 0, "ERROR");
        return -1;
    }

    if (calculate_crc8(data, 2) != data[2]) {
        log_data(0.0, 0, "ERROR");
        return -1;
    }

    int raw_flow = (data[0] << 8) | data[1];
    double flow_rate = raw_flow / 90.0;

    if (flow_rate < 0.0 || flow_rate > 100.0) {
        log_data(flow_rate, 0, "INVALID");
    } else {
        log_data(flow_rate, 0, "OK");
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d, address 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(2, PI_INPUT) < 0 || gpioSetMode(3, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("cooling_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (fputs("Timestamp,Flow Rate (ml/min),Status\n", log_file) < 0) {
        fprintf(stderr, "Failed to write header to log file\n");
        fclose(log_file);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        if (read_sensor() < 0) {
            // Attempt recovery by re-initializing the I2C handle
            gpioI2CClose(i2c_handle);
            i2c_handle = gpioI2COpen(I2C_BUS, I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Failed to re-open I2C bus %d, address 0x%02X\n", I2C_BUS, I2C_ADDR);
                break;
            }
        }

        usleep(1000000 / SAMPLE_RATE); // Sleep for 1 second
    }

    fclose(log_file);
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    return 0;
}

