#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <stdbool.h>
#include <gpiod.h>

#define GPIO_LEFT 17
#define GPIO_MIDDLE 27
#define GPIO_RIGHT 22
#define POLL_INTERVAL_MS 50
#define LOG_FILE "path_log.csv"

static gpiod_chip *chip;
static gpiod_line *left_line, *middle_line, *right_line;
static FILE *log_file;

static void handle_sigint(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec sleep_time = {0, POLL_INTERVAL_MS * 1000000};
    char timestamp[20];
    bool left, middle, right;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for left, middle, and right sensors
    left_line = gpiod_chip_get_line(chip, GPIO_LEFT);
    if (!left_line) {
        perror("Failed to get left line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(left_line, "left_sensor") < 0) {
        perror("Failed to request left line as input");
        gpiod_line_release(left_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    middle_line = gpiod_chip_get_line(chip, GPIO_MIDDLE);
    if (!middle_line) {
        perror("Failed to get middle line");
        gpiod_line_release(left_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(middle_line, "middle_sensor") < 0) {
        perror("Failed to request middle line as input");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    right_line = gpiod_chip_get_line(chip, GPIO_RIGHT);
    if (!right_line) {
        perror("Failed to get right line");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_input(right_line, "right_sensor") < 0) {
        perror("Failed to request right line as input");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(left_line);
        gpiod_line_release(middle_line);
        gpiod_line_release(right_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Write header to the log file
    fprintf(log_file, "timestamp,left,middle,right\n");

    // Poll the sensors every 50 ms
    while (true) {
        // Get the current time
        if (clock_gettime(CLOCK_MONOTONIC, &now) < 0) {
            perror("Failed to get current time");
            break;
        }
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &now);

        // Read the sensor values
        left = gpiod_line_get_value(left_line) == 0;
        middle = gpiod_line_get_value(middle_line) == 0;
        right = gpiod_line_get_value(right_line) == 0;

        // Write the data to the log file
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, left, middle, right);

        // Sleep for the specified interval
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(left_line);
    gpiod_line_release(middle_line);
    gpiod_line_release(right_line);
    gpiod_chip_close(chip);

    return 0;
}

