This C program uses the libgpiod library to poll three KY-033 obstacle-avoidance sensors connected to GPIO17, GPIO27, and GPIO22 on a Raspberry Pi 3 Model B+. It writes each reading (0 or 1) along with an ISO-8601 timestamp to a CSV file named 'path_log.csv'. The program handles SIGINT to ensure all GPIO lines are released, the chip is closed, and the log file is flushed and closed before exiting.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define LOG_FILE "flame_events.txt"

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    const char *chip_name = "gpiochip0";
    const char *line_name = "4";
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    struct timespec ts;
    char timestamp[20];

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request the line
    line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the line as input
    ret = gpiod_line_request_input(line, "flame_sensor");
    if (ret) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set up edge detection for falling edge
    ret = gpiod_line_request_edge_detection(line, GPIOD_EDGE_FALLING, 0);
    if (ret) {
        perror("Failed to set up edge detection");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (keep_running) {
        // Wait for an edge event
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            perror("Failed to wait for edge event");
            break;
        }

        // Get the event
        struct gpiod_line_event event;
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("Failed to read edge event");
            break;
        }

        // Get the current time
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Print the alert
        printf("Alert: Flame detected at %s\n", timestamp);

        // Log the event
        fprintf(log_file, "%s: Flame detected\n", timestamp);

        // Flush the log file
        fflush(log_file);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

