#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip4"
#define GPIO_TOUCH 23
#define GPIO_LED 24
#define LOG_FILE "touch_log.txt"
#define POLL_TIMEOUT 1000000  // 1 second in microseconds

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *touch_line, *led_line;
    struct gpiod_line_event event;
    FILE *log_file;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        exit(EXIT_FAILURE);
    }

    // Request lines
    touch_line = gpiod_chip_get_line(chip, GPIO_TOUCH);
    if (!touch_line) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_TOUCH);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    led_line = gpiod_chip_get_line(chip, GPIO_LED);
    if (!led_line) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_LED);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request events on the touch line
    ret = gpiod_line_request_edge_event(touch_line, "touch_event", GPIOD_EDGE_RISING);
    if (ret) {
        fprintf(stderr, "Failed to request edge event on line %d\n", GPIO_TOUCH);
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Toggle LED on each touch event
    while (!should_exit) {
        ret = gpiod_line_event_wait(touch_line, POLL_TIMEOUT);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for line event\n");
            break;
        }

        ret = gpiod_line_event_read(touch_line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read line event\n");
            break;
        }

        // Log touch event
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
        fprintf(log_file, "%s, LED: %d\n", timestamp, gpiod_line_get_value(led_line));

        // Toggle LED
        ret = gpiod_line_set_value(led_line, !gpiod_line_get_value(led_line));
        if (ret) {
            fprintf(stderr, "Failed to toggle LED\n");
            break;
        }
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(touch_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}

