#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "alert_log.txt"
#define POLL_INTERVAL_MS 500
#define BUZZER_DURATION_MS 2000
#define BUZZER_INTERVAL_MS 100

static gpiod_chip *chip;
static gpiod_line *flame_sensor_line;
static gpiod_line *buzzer_line;
static FILE *log_file;
static int running = 1;

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s - %s\n", timestamp, event);
    fflush(log_file);
}

static void handle_signal(int signum) {
    running = 0;
    gpiod_line_set_value(buzzer_line, 0);
    gpiod_line_release(flame_sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

static void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

static void setup_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", FLAME_SENSOR_PIN, strerror(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        fprintf(stderr, "Failed to request input on line %d: %s\n", FLAME_SENSOR_PIN, strerror(errno));
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Failed to get line %d: %s\n", BUZZER_PIN, strerror(errno));
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Failed to request output on line %d: %s\n", BUZZER_PIN, strerror(errno));
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

static void setup_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        exit(EXIT_FAILURE);
    }
}

static void log_startup() {
    log_event("System started");
}

static void log_shutdown() {
    log_event("System stopped");
}

static void run_flame_detection() {
    int last_state = -1;
    while (running) {
        int current_state = gpiod_line_get_value(flame_sensor_line);
        if (current_state != last_state) {
            if (current_state == 0) {
                log_event("Flame detected");
                gpiod_line_set_value(buzzer_line, 1);
                usleep(BUZZER_DURATION_MS * 1000);
                gpiod_line_set_value(buzzer_line, 0);
            }
            last_state = current_state;
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }
}

int main() {
    setup_signals();
    setup_gpio();
    setup_log_file();
    log_startup();

    run_flame_detection();

    log_shutdown();
    fclose(log_file);
    return 0;
}

