#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_TTP223B 4
#define GPIO_LED 17
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_TIME_MS 200
#define POLL_INTERVAL_MS 10

static volatile sig_atomic_t quit = 0;

void handle_signal(int sig) {
    quit = 1;
}

int main() {
    FILE *log_file;
    struct timespec last_toggle_time;
    struct tm *timeinfo;
    char timestamp[20];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set GPIO4 as input
    if (gpioSetMode(GPIO_TTP223B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO4 as input\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as output\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Get current time for initial timestamp
    if (clock_gettime(CLOCK_REALTIME, &last_toggle_time) < 0) {
        fprintf(stderr, "Failed to get current time\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    timeinfo = localtime(&last_toggle_time.tv_sec);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    // Main loop
    while (!quit) {
        // Read GPIO4
        int ttp223b_state = gpioRead(GPIO_TTP223B);
        if (ttp223b_state < 0) {
            fprintf(stderr, "Failed to read GPIO4\n");
            break;
        }

        // Check for rising edge
        if (ttp223b_state == 0 && (clock_gettime(CLOCK_REALTIME, &last_toggle_time) < 0 || last_toggle_time.tv_sec > timeinfo->tm_sec)) {
            // Debounce
            if (clock_gettime(CLOCK_REALTIME, &last_toggle_time) < 0) {
                fprintf(stderr, "Failed to get current time\n");
                break;
            }
            timeinfo = localtime(&last_toggle_time.tv_sec);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

            // Toggle LED
            gpioWrite(GPIO_LED, !gpioRead(GPIO_LED));

            // Write to log file
            if (fprintf(log_file, "%s\n", timestamp) < 0) {
                fprintf(stderr, "Failed to write to log file\n");
            }
        }

        // Sleep for 10 ms
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();

    return 0;
}

