This C program uses the pigpio library to read a SainSmart TTP223B capacitive touch sensor on GPIO4 and toggle an LED on GPIO17. It includes error handling for all syscalls and resources are released on all exit paths. The program also implements a 200 ms software debounce to prevent multiple events from being registered for a single touch. It handles SIGINT and SIGTERM for graceful shutdown.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO4 4
#define GPIO17 17
#define GPIO27 27

#define LOG_FILE "magnet_log.txt"
#define POLL_INTERVAL 100000  // 100 ms in microseconds

static FILE *logFile;
static int gpio4State, gpio17State, gpio27State;

void logStateChange(const char *sensor, int state) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    fprintf(logFile, "%s,%s,%d\n", timestamp, sensor, state);
}

void handleSignal(int signum) {
    if (logFile) {
        fclose(logFile);
    }
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO modes and pull-ups
    if (gpioSetMode(GPIO4, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO4 mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(GPIO4, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set GPIO4 pull-up\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO17, PI_INPUT) != 0) {
