#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x3F
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A
#define MOVING_AVERAGE_SIZE 5
#define LOG_FILE "heart_rate.csv"

static int i2cHandle;
static FILE *logFile;
static int heartRateData[MOVING_AVERAGE_SIZE];
static int heartRateIndex = 0;
static int heartRateSum = 0;
static int heartRateCount = 0;
static int heartRateBPM = 0;
static int heartRateValid = 0;
static int heartRateRetryCount = 0;
static int heartRateRetryMax = 3;
static int heartRateRetryDelay = 1000; // milliseconds

static void sigintHandler(int signum) {
    if (logFile) {
        fclose(logFile);
    }
    if (i2cHandle >= 0) {
        i2cClose(i2cHandle);
    }
    if (gpioInitialised()) {
        gpioTerminate();
    }
    exit(0);
}

static void logHeartRate(int bpm) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char logLine[100];
    snprintf(logLine, sizeof(logLine), "%04d-%02d-%02d %02d:%02d:%02d,%d\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, bpm);
    fprintf(logFile, logLine);
    fflush(logFile);
}

static int readSensorRegister(int reg) {
    int result = i2cReadWordData(i2cHandle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

static int writeSensorRegister(int reg, int value) {
    int result = i2cWriteWordData(i2cHandle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

static int initSensor() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }
    if (i2cHandle < 0) {
        i2cHandle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
        if (i2cHandle < 0) {
            fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
            gpioTerminate();
            return -1;
        }
    }
    int partId = readSensorRegister(PART_ID_REG);
    int hwRev = readSensorRegister(HW_REV_REG);
    if (partId != 0x02 || hwRev != 0x01) {
        fprintf(stderr, "Sensor is absent or wrong (PART_ID: 0x%02X, HW_REV: 0x%02X)\n", partId, hwRev);
        i2cClose(i2cHandle);
        gpioTerminate();
        return -1;
    }
    if (writeSensorRegister(LED_CURRENT_REG, 0x3F) < 0) {
        return -1;
    }
    if (writeSensorRegister(AVERAGING_REG, 0x04) < 0) {
        return -1;
    }
    if (writeSensorRegister(ENABLE_REG, 0x01) < 0) {
        return -1;
    }
    return 0;
}

static int readHeartRate() {
    int heartRate = readSensorRegister(HEART_RATE_REG);
    if (heartRate < 0) {
        return -1;
    }
    heartRateData[heartRateIndex] = heartRate;
    heartRateIndex = (heartRateIndex + 1) % MOVING_AVERAGE_SIZE;
    heartRateSum = 0;
    for (int i = 0; i < MOVING_AVERAGE_SIZE; i++) {
        heartRateSum += heartRateData[i];
    }
    heartRateBPM = heartRateSum / MOVING_AVERAGE_SIZE;
    if (heartRateBPM < 30 || heartRateBPM > 220) {
        return -1;
    }
    heartRateValid = 1;
    return 0;
}

int main() {
    signal(SIGINT, sigintHandler);
    if (initSensor() < 0) {
        return 1;
    }
    logFile = fopen(LOG_FILE, "a");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }
    while (1) {
        if (readHeartRate() == 0) {
            logHeartRate(heartRateBPM);
        } else {
            if (heartRateRetryCount < heartRateRetryMax) {
                heartRateRetryCount++;
                usleep(heartRateRetryDelay * 1000);
            } else {
                fprintf(stderr, "Failed to read heart rate after %d retries\n", heartRateRetryMax);
                heartRateRetryCount = 0;
            }
        }
        usleep(1000000); // 1 second
    }
    fclose(logFile);
    i2cClose(i2cHandle);
    gpioTerminate();
    return 0;
}

