#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 17
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t should_exit = 0;

void sig_handler(int sig) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct timespec ts;
    FILE *log_file;

    // Install signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Get the line for the flame sensor
    line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the line as input with an internal pull-up
    ret = gpiod_line_request_input(line, "flame_sensor");
    if (ret) {
        perror("Failed to request GPIO line as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Poll the line every 100 ms
    while (!should_exit) {
        ret = gpiod_line_event_wait(line, POLL_INTERVAL_MS);
        if (ret < 0) {
            perror("Failed to wait for line event");
            break;
        }

        if (ret == 0) {
            // Timeout occurred, continue polling
            continue;
        }

        struct gpiod_line_event event;
        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("Failed to read line event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Falling edge detected
            printf("FLAME DETECTED\n");
            time(&ts);
            fprintf(log_file, "%s FLAME DETECTED\n", ctime(&ts));
            fflush(log_file);
        }
    }

    // Release the line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    // Close the log file
    fclose(log_file);

    return 0;
}

