#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_COUNT 8
#define GPIO_LINE_BASE 5
#define GPIO_OUTPUT_PIN 17
#define GPIO_OUTPUT_BASE 24
#define LOG_FILE "touch_log.txt"
#define STABILIZATION_DELAY 200
#define POLL_INTERVAL 10

static gpiod_chip *chip;
static gpiod_line *lines[GPIO_LINE_COUNT];
static gpiod_line_request *requests[GPIO_LINE_COUNT];
static int counter = 0;
static FILE *log_file;

static void log_touch(int channel, int value) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);
    fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, value);
    fprintf(stdout, "Touch on channel %d | Counter: %d\n", channel, value);
}

static void handle_signal(int signum) {
    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        gpiod_line_request_set_value(requests[i], 0);
    }
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(0);
}

static void setup_gpio() {
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINE_BASE + i);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        requests[i] = gpiod_line_request_bulk(chip, lines, 1, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
        if (!requests[i]) {
            perror("Failed to request GPIO line");
            gpiod_line_release_bulk(lines, 1);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        if (gpiod_line_request_set_value(requests[i], 0) < 0) {
            perror("Failed to set GPIO line value");
            gpiod_line_release_bulk(lines, 1);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
    } else {
        fprintf(log_file, "Timestamp, Channel, Counter\n");
    }
}

static void cleanup_gpio() {
    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        gpiod_line_request_release(requests[i]);
    }
    gpiod_chip_close(chip);
    if (log_file) {
        fclose(log_file);
    }
}

static void stabilize() {
    usleep(STABILIZATION_DELAY * 1000);
}

static void main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    stabilize();

    while (1) {
        for (int i = 0; i < GPIO_LINE_COUNT; i++) {
            int value = gpiod_line_request_get_value(requests[i]);
            if (value < 0) {
                perror("Failed to read GPIO line value");
                continue;
            }

            if (value == 1) {
                counter = (counter + 1) % 256;
                for (int j = 0; j < GPIO_LINE_COUNT; j++) {
                    gpiod_line_request_set_value(requests[j], 0);
                }
                gpiod_line_request_set_value(requests[i], 1);
                log_touch(i + 1, counter);
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    cleanup_gpio();
}

