    signal(SIGTERM, handle_signal);

    // Open the CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("Failed to open CSV file");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(csv_file);
        return EXIT_FAILURE;
    }

    // Request lines
    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_LINE_BASE + i);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            fclose(csv_file);
            return EXIT_FAILURE;
        }
        ret = gpiod_line_request_input(lines[i], "Tracking");
        if (ret) {
            perror("Failed to request GPIO line input");
            gpiod_line_release(lines[i]);
            gpiod_chip_close(chip);
            fclose(csv_file);
            return EXIT_FAILURE;
        }
    }

    // Write header row if the file is newly created
    if (fseek(csv_file, 0, SEEK_END) == 0) {
        fprintf(csv_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }

    // Main loop
    while (!should_exit) {
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        for (int i = 0; i < GPIO_LINE_COUNT; i++) {
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                perror("Failed to read GPIO line value");
                continue;
            }
            snprintf(line, sizeof(line), "%d", value);
            if (i > 0) {
                strcat(line, ",");
            }
        }
        fprintf(csv_file, "%s,%s\n", timestamp, line);
        fflush(csv_file);

        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    for (int i = 0; i < GPIO_LINE_COUNT; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    fclose(csv_file);

    return EXIT_SUCCESS;
}

