#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define LOG_FILE "/var/log/tilt_events.log"
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 100

static gpiod_chip *chip;
static gpiod_line *line1, *line2;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

static void log_event(int sensor, time_t timestamp) {
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
    fprintf(log_file, "%s, Sensor %d tilted\n", timestamp_str, sensor);
    fflush(log_file);
}

static void handle_signal(int signum) {
    should_exit = 1;
}

static void cleanup() {
    if (log_file) {
        fclose(log_file);
    }
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    struct timespec poll_interval = {0, POLL_INTERVAL_MS * 1000000};
    struct timespec debounce_interval = {0, DEBOUNCE_MS * 1000000};
    struct timespec last_event_time[2] = {0, 0};
    int sensor_state[2] = {1, 1};

    // Install signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return EXIT_FAILURE;
    }

    // Request lines
    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        perror("Failed to request line 17");
        cleanup();
        return EXIT_FAILURE;
    }
    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        perror("Failed to request line 18");
        cleanup();
        return EXIT_FAILURE;
    }

    // Configure lines as inputs with active-low pull-up
    if (gpiod_line_request_input(line1, "tilt_sensor1", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to configure line 17 as input");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(line2, "tilt_sensor2", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("Failed to configure line 18 as input");
        cleanup();
        return EXIT_FAILURE;
    }

    // Enable edge detection with a 50 ms debounce window
    if (gpiod_line_set_config(line1, GPIOD_LINE_REQUEST_FLAG_EDGE_RISING | GPIOD_LINE_REQUEST_FLAG_EDGE_FALLING, &debounce_interval) < 0) {
        perror("Failed to enable edge detection on line 17");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_set_config(line2, GPIOD_LINE_REQUEST_FLAG_EDGE_RISING | GPIOD_LINE_REQUEST_FLAG_EDGE_FALLING, &debounce_interval) < 0) {
        perror("Failed to enable edge detection on line 18");
        cleanup();
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        // Read line states
        int state1 = gpiod_line_get_value(line1);
        int state2 = gpiod_line_get_value(line2);

        // Check for transitions
        if (state1 != sensor_state[0] && state1 == 0) {
            log_event(1, current_time.tv_sec);
            last_event_time[0] = current_time;
        }
        if (state2 != sensor_state[1] && state2 == 0) {
            log_event(2, current_time.tv_sec);
            last_event_time[1] = current_time;
        }

        // Update sensor states
        sensor_state[0] = state1;
        sensor_state[1] = state2;

        // Sleep for the poll interval
        nanosleep(&poll_interval, NULL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

