This C program uses the libgpiod API to monitor two Omron D7E-5 tilt sensors connected to GPIO lines 17 and 18 on a Raspberry Pi 5. It configures the lines as inputs with active-low pull-up, enables edge detection with a 50 ms debounce window, and logs timestamped events to `/var/log/tilt_events.log` when a tilt event is detected. The program handles chip-open failure, line-request failure, and read errors by printing a message to stderr and exiting gracefully. It also installs signal handlers for SIGINT and SIGTERM to release all libgpiod resources and close the log file cleanly before exiting.

code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define GPIO22 22
#define LOG_FILE "obstacle_log.csv"
#define POLL_INTERVAL 100000  // 100 ms

static volatile sig_atomic_t should_exit = 0;

void handle_sigint(int signum) {
    should_exit = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2, *line3;
    int ret;
    FILE *log_file;
    struct timespec ts;
    char timestamp[20];

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for sensors and LED
    line1 = gpiod_chip_get_line(chip, GPIO17);
    line2 = gpiod_chip_get_line(chip, GPIO27);
    line3 = gpiod_chip_get_line(chip, GPIO22);

    ret = gpiod_line_request_input(line1, "sensor1");
    if (ret) {
        perror("Failed to request line 1");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(line2, "sensor2");
    if (ret) {
        perror("Failed to request line 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line3, "led", 0);
    if (ret) {
        perror("Failed to request line 3");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Log header
    fprintf(log_file, "timestamp,sensor1,sensor2,led_state\n");

    while (!should_exit) {
        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%09f", localtime(&ts.tv_sec));

        // Read sensor states
        int sensor1_state = gpiod_line_get_value(line1);
