    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            perror("Failed to request GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        ret = gpiod_line_request_input(lines[i], "sunfounder_tracing_sensor");
        if (ret) {
            perror("Failed to request GPIO line input");
            gpiod_line_release(lines[i]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Enable pull-up on all lines
    for (int i = 0; i < 3; i++) {
        ret = gpiod_line_set_config(lines[i], GPIOD_LINE_CONFIG_PULL_UP, 0);
        if (ret) {
            perror("Failed to set pull-up on GPIO line");
            gpiod_line_release(lines[i]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    while (!should_exit) {
        // Read line values
        for (int i = 0; i < 3; i++) {
            ret = gpiod_line_get_value(lines[i], &line_values[i]);
            if (ret) {
                perror("Failed to read GPIO line value");
                gpiod_line_release(lines[i]);
                gpiod_chip_close(chip);
                exit(EXIT_FAILURE);
            }
        }

        // Log line values
        printf("Left: %d, Center: %d, Right: %d\n", line_values[0], line_values[1], line_values[2]);

        // Sleep for the log interval
        usleep(LOG_INTERVAL_MS * 1000);
    }

    // Release resources
    for (int i = 0; i < 3; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

