#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <libgpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define ALS_VISIBLE_DATA_L 0x24
#define ALS_VISIBLE_DATA_H 0x25
#define I2C_TIMEOUT 1000000 // 1 second

static int i2c_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *gpio_line;

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    exit(signum);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, handle_signal);

    // Open I2C device
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO for LED control (optional)
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, 17); // Example GPIO line for LED
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(gpio_line, "HeartRateSensor", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        uint8_t data[2];
        int ret;

        // Read ALS visible data registers
        ret = read(i2c_fd, data, sizeof(data));
        if (ret < 0) {
            perror("Failed to read I2C data");
            continue;
        }
        if (ret != sizeof(data)) {
            fprintf(stderr, "Short read from I2C device\n");
            continue;
        }

        // Combine LSB and MSB into a 16-bit value
        uint16_t als_visible_data = (data[1] << 8) | data[0];

        // Log the raw sensor values
        printf("ALS Visible Data: 0x%04X\n", als_visible_data);

        // Control LED (optional)
        gpiod_line_set_value(gpio_line, 1); // Turn LED on
        usleep(100000); // Wait for 100 ms
        gpiod_line_set_value(gpio_line, 0); // Turn LED off
        usleep(100000); // Wait for 100 ms

        // Sleep for 100 ms
        usleep(I2C_TIMEOUT);
    }

    // Clean up
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

