#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define FADE_TIME 5000
#define INTERPOLATION_STEPS 50

static volatile sig_atomic_t quit = 0;

void signal_handler(int signum) {
    quit = 1;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio library");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);
}

void cleanup_gpio() {
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
}

void fade_to_color(int red, int green, int blue) {
    int steps = INTERPOLATION_STEPS;
    int step_size = PWM_RANGE / steps;
    int current_red = 0;
    int current_green = 0;
    int current_blue = 0;

    for (int i = 0; i <= steps; i++) {
        current_red = current_red + step_size;
        current_green = current_green + step_size;
        current_blue = current_blue + step_size;

        if (current_red > PWM_RANGE) current_red = PWM_RANGE;
        if (current_green > PWM_RANGE) current_green = PWM_RANGE;
        if (current_blue > PWM_RANGE) current_blue = PWM_RANGE;

        gpioPWM(RED_PIN, 255 - current_red);
        gpioPWM(GREEN_PIN, 255 - current_green);
        gpioPWM(BLUE_PIN, 255 - current_blue);

        usleep(FADE_TIME / steps);
    }
}

void random_hue_to_rgb(int hue, int *red, int *green, int *blue) {
    float h = hue / 360.0f;
    float s = 1.0f;
    float v = 1.0f;

    float c = v * s;
    float x = c * (1 - abs(fmod(h, 2) - 1));
    float m = v - c;

    if (h < 1) {
        *red = (int)(c + m);
        *green = (int)(x + m);
        *blue = (int)m;
    } else if (h < 2) {
        *red = (int)(x + m);
        *green = (int)(c + m);
        *blue = (int)m;
    } else if (h < 3) {
        *red = (int)m;
        *green = (int)(c + m);
        *blue = (int)(x + m);
    } else if (h < 4) {
        *red = (int)m;
        *green = (int)(x + m);
        *blue = (int)(c + m);
    } else if (h < 5) {
        *red = (int)(x + m);
        *green = (int)m;
        *blue = (int)(c + m);
    } else {
        *red = (int)(c + m);
        *green = (int)m;
        *blue = (int)x + m;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();

    while (!quit) {
        int hue = rand() % 360;
        int red, green, blue;
        random_hue_to_rgb(hue, &red, &green, &blue);

        fade_to_color(red, green, blue);

        syslog(LOG_INFO, "Faded to hue %d", hue);
    }

    cleanup_gpio();
    closelog();

    return 0;
}

