#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x29
#define PON 0x01
#define RGBC 0x02
#define ATIME 0x00
#define CONTROL 0x00
#define ID 0x12
#define CLEAR 0x14
#define RED 0x16
#define GREEN 0x18
#define BLUE 0x1A
#define LED_PIN 17
#define THRESHOLD 200

static int i2c_fd;
static struct gpiod_chip *led_chip;
static struct gpiod_line *led_line;

void init_sensor() {
    int ret;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Power on the sensor
    ret = write(i2c_fd, &PON, 1);
    if (ret < 0) {
        perror("Failed to power on sensor");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Enable RGBC
    ret = write(i2c_fd, &RGBC, 1);
    if (ret < 0) {
        perror("Failed to enable RGBC");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set integration time
    ret = write(i2c_fd, &ATIME, 1);
    if (ret < 0) {
        perror("Failed to set integration time");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set gain
    ret = write(i2c_fd, &CONTROL, 1);
    if (ret < 0) {
        perror("Failed to set gain");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Verify sensor ID
    uint8_t id;
    ret = read(i2c_fd, &id, 1);
    if (ret < 0) {
        perror("Failed to read sensor ID");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (id != 0x44) {
        fprintf(stderr, "Invalid sensor ID: 0x%02x\n", id);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void read_sensor() {
    uint16_t clear, red, green, blue;
    int ret;

    // Read clear channel
    ret = read(i2c_fd, &clear, 2);
    if (ret < 0) {
        perror("Failed to read clear channel");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read red channel
    ret = read(i2c_fd, &red, 2);
    if (ret < 0) {
        perror("Failed to read red channel");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read green channel
    ret = read(i2c_fd, &green, 2);
    if (ret < 0) {
        perror("Failed to read green channel");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read blue channel
    ret = read(i2c_fd, &blue, 2);
    if (ret < 0) {
        perror("Failed to read blue channel");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Apply per-channel gain and offset calibration
    // (Assuming calibration values are known and applied here)
    clear = clear;
    red = red;
    green = green;
    blue = blue;

    // Display calibrated RGB and clear values
    printf("Calibrated RGB: R=%d, G=%d, B=%d\n", red, green, blue);
    printf("Calibrated Clear: C=%d\n", clear);

    // Drive LED based on red channel value
    if (red > THRESHOLD) {
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("Failed to set LED HIGH");
        }
    } else {
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("Failed to set LED LOW");
        }
    }
}

void cleanup() {
    // Close I2C bus
    close(i2c_fd);

    // Release GPIO line
    gpiod_line_release(led_line);
    gpiod_chip_close(led_chip);

    // Power down the sensor
    // (Assuming power down command is known and applied here)
}

void signal_handler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main() {
    int ret;

    // Initialize GPIO for LED
    led_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!led_chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    led_line = gpiod_chip_get_line(led_chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(led_chip);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_output(led_line, "LED", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(led_chip);
        gpiod_line_release(led_line);
        exit(EXIT_FAILURE);
    }

    // Initialize sensor
    init_sensor();

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Poll sensor every 200 ms
    while (1) {
        read_sensor();
        usleep(200000);
    }

    // Cleanup on exit
    cleanup();

    return 0;
}

