#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define LED_PIN 18
#define I2C_ADDR 0x23
#define I2C_TIMEOUT 1000
#define MAX_RETRIES 5
#define MAX_LUX 1000
#define MAX_BRIGHTNESS 255

static int gpiod_handle;
static int i2c_fd;
static int retries = 0;

void handle_sigint(int sig) {
    printf("Received SIGINT, cleaning up...\n");
    gpioTerminate();
    close(i2c_fd);
    exit(0);
}

void handle_sigterm(int sig) {
    printf("Received SIGTERM, cleaning up...\n");
    gpioTerminate();
    close(i2c_fd);
    exit(0);
}

void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpiod_handle = gpioGetChipHandle(0);
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void read_lux() {
    uint8_t cmd[1] = {0x10};
    uint8_t data[2];
    int ret;

    for (retries = 0; retries < MAX_RETRIES; retries++) {
        ret = write(i2c_fd, cmd, 1);
        if (ret < 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            continue;
        }
        usleep(180000); // Wait 180 ms
        ret = read(i2c_fd, data, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read from I2C device\n");
            continue;
        }
        break;
    }

    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to read lux after %d retries\n", MAX_RETRIES);
        return;
    }

    uint16_t lux = (data[0] << 8) | data[1];
    printf("Lux: %d\n", lux);
}

void set_brightness(uint8_t brightness) {
    uint8_t pwm = brightness * 255 / MAX_BRIGHTNESS;
    gpioPWM(LED_PIN, pwm);
}

void main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    init_pigpio();
    init_i2c();

    while (1) {
        read_lux();
        uint8_t brightness = (uint8_t)(log(lux + 1) / log(MAX_LUX + 1) * MAX_BRIGHTNESS);
        set_brightness(brightness);
        usleep(100000); // Wait 100 ms
    }

    gpioTerminate();
    close(i2c_fd);
    exit(EXIT_SUCCESS);
}

