#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>

#define BH1750_ADDR 0x23
#define APA102_ADDR 0x00
#define LED_COUNT 30
#define SPI_SPEED_HZ 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_DELAY_USEC 0

static int i2c_fd;
static int spi_fd;
static volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int sig) {
    exit_flag = 1;
}

int main() {
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data data;
    uint8_t cmd[2] = {0x20, 0x01}; // One-Time High-Resolution mode
    uint8_t lux_data[2];
    uint32_t brightness;
    uint8_t apa102_frame[32];
    uint8_t *led_data;
    int ret;

    // Register signal handler
    signal(SIGINT, sigint_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Write command to start conversion
    msgs[0].addr = BH1750_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = sizeof(cmd);
    msgs[0].buf = cmd;
    msgs[1].addr = BH1750_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = sizeof(lux_data);
    msgs[1].buf = lux_data;
    data.msgs = msgs;
    data.nmsgs = 2;
    if (ioctl(i2c_fd, I2C_RDWR, &data) < 0) {
        perror("Failed to read from I2C device");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Convert lux data to lux
    uint16_t raw = (lux_data[0] << 8) | lux_data[1];
    float lux = raw / 1.2;

    // Map lux to APA102 brightness
    if (lux < 10 || lux > 300) {
        brightness = 0;
    } else {
        brightness = (uint32_t)((lux - 10) * 31.0 / 200.0);
    }

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI parameters
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.speed_hz = SPI_SPEED_HZ;
    tr.mode = SPI_MODE;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs = SPI_DELAY_USEC;
    tr.len = 32;
    tr.tx_buf = (unsigned long)apa102_frame;

    // Create APA102 frame
    apa102_frame[0] = 0x00; // Zero start frame
    for (int i = 0; i < LED_COUNT; i++) {
        apa102_frame[4 + i * 4] = 0xE0 | brightness; // Global brightness
        apa102_frame[5 + i * 4] = 0x00; // Blue
        apa102_frame[6 + i * 4] = 0x00; // Green
        apa102_frame[7 + i * 4] = 0xFF; // Red
    }
    apa102_frame[31] = 0xFF; // End frame

    // Send APA102 frame
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
    if (ret < 0) {
        perror("Failed to send SPI message");
        close(spi_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Wait for SIGINT
    while (!exit_flag) {
        usleep(100000);
    }

    // Turn off LEDs
    memset(apa102_frame, 0, sizeof(apa102_frame));
    apa102_frame[0] = 0x00; // Zero start frame
    apa102_frame[31] = 0xFF; // End frame
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
    if (ret < 0) {
        perror("Failed to send SPI message");
        close(spi_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Close file descriptors
    close(spi_fd);
    close(i2c_fd);

    return 0;
}

