#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <bh1750.h>

#define LED_STRIP_MOSI 10
#define LED_STRIP_SCLK 11
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define LED_STRIP_LENGTH 100
#define MAX_BRIGHTNESS 31
#define FADE_TIME_MS 500
#define DELAY_TIME_MS 100

static int bh1750_handles[2] = {-1, -1};
static int spi_handle = -1;
static int brightness = 0;
static int running = 1;

void sigint_handler(int signum) {
    running = 0;
    gpioTerminate();
    for (int i = 0; i < 2; i++) {
        if (bh1750_handles[i] != -1) {
            bh1750_close(bh1750_handles[i]);
        }
    }
    if (spi_handle != -1) {
        spi_close(spi_handle);
    }
    exit(0);
}

void fade_to_brightness(int target_brightness) {
    int step = (target_brightness - brightness) / (FADE_TIME_MS / DELAY_TIME_MS);
    for (int i = brightness; i != target_brightness; i += step) {
        brightness = i;
        update_led_strip();
        usleep(DELAY_TIME_MS * 1000);
    }
    brightness = target_brightness;
    update_led_strip();
}

void update_led_strip() {
    uint8_t data[LED_STRIP_LENGTH * 4];
    for (int i = 0; i < LED_STRIP_LENGTH; i++) {
        data[i * 4] = 0xFF; // Full brightness
        data[i * 4 + 1] = brightness;
        data[i * 4 + 2] = 0; // Green
        data[i * 4 + 3] = 0; // Blue
    }
    spi_write(spi_handle, data, LED_STRIP_LENGTH * 4);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    signal(SIGINT, sigint_handler);

    spi_handle = spiOpen(0, 1000000, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < 2; i++) {
        bh1750_handles[i] = bh1750_open(i == 0 ? BH1750_ADDR_LOW : BH1750_ADDR_HIGH);
        if (bh1750_handles[i] < 0) {
            fprintf(stderr, "Failed to open BH1750 sensor at address 0x%02X\n", i == 0 ? BH1750_ADDR_LOW : BH1750_ADDR_HIGH);
        }
    }

    while (running) {
        int total_lux = 0;
        int sensor_count = 0;
        for (int i = 0; i < 2; i++) {
            if (bh1750_handles[i] != -1) {
                int lux = bh1750_read(bh1750_handles[i]);
                if (lux >= 0) {
                    total_lux += lux;
                    sensor_count++;
                } else {
                    fprintf(stderr, "Failed to read from BH1750 sensor at address 0x%02X\n", i == 0 ? BH1750_ADDR_LOW : BH1750_ADDR_HIGH);
                }
            }
        }
        if (sensor_count > 0) {
            int average_lux = total_lux / sensor_count;
            int target_brightness = MAX_BRIGHTNESS - (average_lux / 10); // Map lux to brightness
            fade_to_brightness(target_brightness);
        } else {
            fprintf(stderr, "No valid BH1750 sensors found\n");
        }
        usleep(1000000); // 1 second delay
    }

    gpioTerminate();
    for (int i = 0; i < 2; i++) {
        if (bh1750_handles[i] != -1) {
            bh1750_close(bh1750_handles[i]);
        }
    }
    if (spi_handle != -1) {
        spi_close(spi_handle);
    }

    return 0;
}

