#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x10
#define LED_PIN 18
#define MAX_RETRIES 3
#define RETRY_DELAY 100
#define MAX_LUX 120000
#define MAX_BRIGHTNESS 255
#define GAIN 1/8
#define INTEGRATION_TIME 100
#define BIT_BANG_FREQ 800000
#define THRESHOLD 128

static int i2c_fd;
static int gpio_fd;
static int retries = 0;
static int running = 1;

static void handle_signal(int sig) {
    running = 0;
    gpio_fd = gpiochip_close(gpio_fd);
    i2c_fd = close(i2c_fd);
    printf("Exiting...\n");
    exit(0);
}

static void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_gpio() {
    gpio_fd = gpiochip_open(0);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    struct gpiochip_info info;
    if (ioctl(gpio_fd, GPIO_GET_CHIPINFO_IOCTL, &info) < 0) {
        perror("Failed to get GPIO chip info");
        gpiochip_close(gpio_fd);
        exit(EXIT_FAILURE);
    }
    if (info.lines < LED_PIN) {
        fprintf(stderr, "Not enough GPIO lines\n");
        gpiochip_close(gpio_fd);
        exit(EXIT_FAILURE);
    }
    struct gpiod_line_request req = {
        .line_offset = LED_PIN,
        .consumer = "ws2812b",
        .request_type = GPIO_LINE_REQUEST_OUTPUT,
    };
    if (gpiochip_request_line(gpio_fd, &req) < 0) {
        perror("Failed to request GPIO line");
        gpiochip_close(gpio_fd);
        exit(EXIT_FAILURE);
    }
}

static void write_i2c(uint16_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg >> 8;
    buf[1] = reg & 0xFF;
    buf[2] = value >> 8;
    buf[3] = value & 0xFF;
    if (write(i2c_fd, buf, 4) != 4) {
        perror("Failed to write to I2C device");
        retries++;
        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "I2C device failed after %d retries\n", MAX_RETRIES);
            exit(EXIT_FAILURE);
        }
        sleep(RETRY_DELAY / 1000);
    }
}

static uint16_t read_i2c(uint16_t reg) {
    uint8_t buf[2];
    buf[0] = reg >> 8;
    buf[1] = reg & 0xFF;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        retries++;
        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "I2C device failed after %d retries\n", MAX_RETRIES);
            exit(EXIT_FAILURE);
        }
        sleep(RETRY_DELAY / 1000);
    }
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        retries++;
        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "I2C device failed after %d retries\n", MAX_RETRIES);
            exit(EXIT_FAILURE);
        }
        sleep(RETRY_DELAY / 1000);
    }
    return (buf[0] << 8) | buf[1];
}

static void set_led_brightness(uint8_t brightness) {
    // Bit-bang the LED pin with the given brightness
    // This is a placeholder for the actual bit-banging code
    // You will need to implement this based on the WS2812B protocol
    // and the desired brightness level
    // For simplicity, we will just print the brightness value
    printf("Setting LED brightness to %d\n", brightness);
}

static void loop() {
    while (running) {
        uint16_t config = 0x0000;
        write_i2c(0x00, config);
        uint16_t lux = read_i2c(0x04);
        printf("Lux: %d\n", lux);
        uint8_t brightness = (uint8_t)(255 * pow(lux / MAX_LUX, 1.0/2.2));
        set_led_brightness(brightness);
        usleep(200000);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
    init_i2c();
    init_gpio();
    loop();
    gpiochip_close(gpio_fd);
    close(i2c_fd);
    return 0;
}

