#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18
#define SELF_TEST_INTERVAL 100
#define SELF_TEST_RETRIES 5
#define FLAME_THRESHOLD 0
#define LOG_FILE "flame_sensor.log"

static gpiod_chip *chip;
static gpiod_line *flame_sensor_line, *buzzer_line, *led_line;
static FILE *log_file;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(log_file, "%02d:%02d:%02d %s\n", tm->tm_hour, tm->tm_min, tm->tm_sec, event);
    fflush(log_file);
}

void handle_sigint(int signum) {
    log_event("SIGINT received, cleaning up...");
    gpiod_line_release(flame_sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_line_release(led_line);
    fclose(log_file);
    exit(0);
}

int main() {
    int ret;
    struct timespec sleep_time = {0, 500000000}; // 50 ms
    struct timespec self_test_sleep_time = {0, 1000000}; // 100 ms

    // Initialize signal handler
    signal(SIGINT, handle_sigint);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(1);
    }

    // Request lines
    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        perror("Failed to get flame sensor line");
        gpiod_chip_close(chip);
        exit(1);
    }
    ret = gpiod_line_request_input(flame_sensor_line, "flame_sensor");
    if (ret) {
        perror("Failed to request flame sensor line as input");
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Failed to get buzzer line");
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        exit(1);
    }
    ret = gpiod_line_request_output(buzzer_line, "buzzer", 0);
    if (ret) {
        perror("Failed to request buzzer line as output");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        exit(1);
    }
    ret = gpiod_line_request_output(led_line, "LED", 0);
    if (ret) {
        perror("Failed to request LED line as output");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Self-test
    log_event("Running self-test...");
    for (int i = 0; i < SELF_TEST_RETRIES; i++) {
        ret = gpiod_line_get_value(flame_sensor_line);
        if (ret != FLAME_THRESHOLD) {
            log_event("Self-test failed: flame sensor did not detect flame");
            // Signal error with distinct pattern
            for (int j = 0; j < 5; j++) {
                gpiod_line_set_value(led_line, 1);
                nanosleep(&sleep_time, NULL);
                gpiod_line_set_value(led_line, 0);
                nanosleep(&sleep_time, NULL);
            }
            for (int j = 0; j < 3; j++) {
                gpiod_line_set_value(buzzer_line, 1);
                nanosleep(&self_test_sleep_time, NULL);
                gpiod_line_set_value(buzzer_line, 0);
                nanosleep(&self_test_sleep_time, NULL);
                gpiod_line_set_value(buzzer_line, 1);
                nanosleep(&self_test_sleep_time, NULL);
                gpiod_line_set_value(buzzer_line, 0);
                nanosleep(&self_test_sleep_time, NULL);
            }
            fclose(log_file);
            gpiod_line_release(flame_sensor_line);
            gpiod_line_release(buzzer_line);
            gpiod_line_release(led_line);
            gpiod_chip_close(chip);
            exit(1);
        }
        nanosleep(&self_test_sleep_time, NULL);
    }
    log_event("Self-test passed.");

    // Main loop
    while (1) {
        ret = gpiod_line_get_value(flame_sensor_line);
        if (ret == FLAME_THRESHOLD) {
            log_event("Flame detected.");
            gpiod_line_set_value(buzzer_line, 1);
            gpiod_line_set_value(led_line, 1);
            while (1) {
                ret = gpiod_line_get_value(flame_sensor_line);
                if (ret != FLAME_THRESHOLD) {
                    log_event("Flame gone.");
                    gpiod_line_set_value(buzzer_line, 0);
                    gpiod_line_set_value(led_line, 0);
                    break;
                }
                nanosleep(&sleep_time, NULL);
            }
        } else {
            nanosleep(&sleep_time, NULL);
        }
    }

    // Clean up
    gpiod_line_release(flame_sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_line_release(led_line);
    fclose(log_file);
    gpiod_chip_close(chip);

    return 0;
}

