#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BUFFER_SIZE 60
#define LED_GPIO 17
#define LED_PATH "/sys/class/gpio/gpio%d"
#define LED_EXPORT "export"
#define LED_UNEXPORT "unexport"
#define LED_DIR "direction"
#define LED_VALUE "value"

static int i2c_fd;
static int led_fd;
static int buffer[BUFFER_SIZE];
static int buffer_index = 0;
static double avg_lux = 0.0;
static volatile sig_atomic_t should_exit = 0;

static void signal_handler(int sig) {
    should_exit = 1;
}

static void init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void init_led() {
    char led_path[100];
    snprintf(led_path, sizeof(led_path), LED_PATH, LED_GPIO);
    led_fd = open(led_path, O_WRONLY);
    if (led_fd < 0) {
        perror("Failed to open LED GPIO");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (write(led_fd, LED_DIR, strlen(LED_DIR)) < 0) {
        perror("Failed to set LED direction");
        close(led_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (write(led_fd, LED_EXPORT, strlen(LED_EXPORT)) < 0) {
        perror("Failed to export LED GPIO");
        close(led_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void close_i2c() {
    close(i2c_fd);
}

static void close_led() {
    close(led_fd);
    unlink(LED_PATH);
}

static void read_lux() {
    uint8_t cmd[1] = {BH1750_CONTINUOUS_HIGH_RES_MODE};
    uint8_t data[2];
    int ret;

    ret = write(i2c_fd, cmd, sizeof(cmd));
    if (ret < 0) {
        perror("Failed to write command to BH1750");
        return;
    }

    ret = read(i2c_fd, data, sizeof(data));
    if (ret < 0) {
        perror("Failed to read data from BH1750");
        return;
    }

    int raw = (data[0] << 8) | data[1];
    avg_lux = raw / 1.2;
    buffer[buffer_index] = avg_lux;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void compute_average_lux() {
    double sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    avg_lux = sum / BUFFER_SIZE;
}

static void set_led_blink_rate() {
    double rate = 0.5 + (avg_lux / 1000) * 4.5;
    rate = fmax(0.5, fmin(rate, 5.0));
    int period = (int)(1000.0 / rate);
    int on_time = period / 2;
    int off_time = period / 2;

    char led_path[100];
    snprintf(led_path, sizeof(led_path), LED_PATH, LED_GPIO);
    led_path[strlen(led_path) - 1] = '0' + (int)(on_time / 100.0);
    led_path[strlen(led_path) - 2] = '0' + (int)(on_time % 100.0);
    led_path[strlen(led_path) - 3] = '0' + (int)(off_time / 100.0);
    led_path[strlen(led_path) - 4] = '0' + (int)(off_time % 100.0);

    if (write(led_fd, led_path, strlen(led_path)) < 0) {
        perror("Failed to set LED blink rate");
    }
}

int main() {
    signal(SIGINT, signal_handler);

    init_i2c();
    init_led();

    while (!should_exit) {
        read_lux();
        compute_average_lux();
        set_led_blink_rate();
        sleep(1);
    }

    close_i2c();
    close_led();

    return 0;
}

