#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <gpiod.h>

#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27
#define NUM_SEGMENTS 8

// Function to shift out 8 bits to the 74HC595
void shift_out(gpiod_chip *chip, gpiod_line *data_line, gpiod_line *clock_line, gpiod_line *latch_line, unsigned char data) {
    for (int i = 0; i < NUM_SEGMENTS; i++) {
        gpiod_line_set_value(data_line, (data >> i) & 1);
        gpiod_line_set_value(clock_line, 1);
        gpiod_line_set_value(clock_line, 0);
    }
    gpiod_line_set_value(latch_line, 1);
    gpiod_line_set_value(latch_line, 0);
}

// Function to initialize the 74HC595
void init_74hc595(gpiod_chip **chip, gpiod_line **data_line, gpiod_line **clock_line, gpiod_line **latch_line) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    *data_line = gpiod_chip_get_line(*chip, DATA_PIN);
    if (!*data_line) {
        perror("Failed to get data line");
        gpiod_chip_close(*chip);
        exit(EXIT_FAILURE);
    }

    *clock_line = gpiod_chip_get_line(*chip, CLOCK_PIN);
    if (!*clock_line) {
        perror("Failed to get clock line");
        gpiod_line_release(*data_line);
        gpiod_chip_close(*chip);
        exit(EXIT_FAILURE);
    }

    *latch_line = gpiod_chip_get_line(*chip, LATCH_PIN);
    if (!*latch_line) {
        perror("Failed to get latch line");
        gpiod_line_release(*data_line);
        gpiod_line_release(*clock_line);
        gpiod_chip_close(*chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(*data_line, "data", 0);
    gpiod_line_request_output(*clock_line, "clock", 0);
    gpiod_line_request_output(*latch_line, "latch", 0);
}

// Function to clean up and release resources
void cleanup(gpiod_chip *chip, gpiod_line *data_line, gpiod_line *clock_line, gpiod_line *latch_line) {
    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);
    gpiod_chip_close(chip);
}

int main() {
    gpiod_chip *chip;
    gpiod_line *data_line, *clock_line, *latch_line;

    init_74hc595(&chip, &data_line, &clock_line, &latch_line);

    while (1) {
        // Display the digit '5'
        unsigned char digit = 0b01100001; // 0b01100001 = '5' in 7-segment format
        shift_out(chip, data_line, clock_line, latch_line, digit);

        // Wait for 500 ms
        usleep(500000);

        // Clear the display
        digit = 0b00000000; // 0b00000000 = '0' in 7-segment format
        shift_out(chip, data_line, clock_line, latch_line, digit);

        // Wait for 500 ms
        usleep(500000);
    }

    cleanup(chip, data_line, clock_line, latch_line);

    return 0;
}

