#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 17
#define BUTTON_PIN 18
#define CHIP_NAME "gpiochip0"
#define EVENT_TIMEOUT 1000000  // 1 second in microseconds

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *button_line;
    struct gpiod_line_event event;
    struct gpiod_line_request req;

    // Set up signal handler for SIGINT
    signal(SIGINT, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open(CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request the LED line as output initially low
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret) {
        perror("Failed to request LED line as output");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the button line as input with an internal pull-up and falling-edge event detection
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Failed to get button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    req.flags = GPIOD_LINE_REQUEST_FLAG_INPUT | GPIOD_LINE_REQUEST_FLAG_EDGE_RISING;
    ret = gpiod_line_request_event(button_line, &req, EVENT_TIMEOUT);
    if (ret) {
        perror("Failed to request button line event");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Blink the LED
    while (!should_exit) {
        gpiod_line_set_value(led_line, 1);  // Turn on LED
        usleep(1000000);  // 1 second
        gpiod_line_set_value(led_line, 0);  // Turn off LED
        usleep(1000000);  // 1 second

        // Wait for button event
        ret = gpiod_line_event_wait(button_line, &event);
        if (ret == -ETIMEDOUT) {
            continue;
        } else if (ret) {
            perror("Failed to wait for button event");
            gpiod_line_release(led_line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Check if it's a falling edge (button press)
        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            printf("Button pressed, stopping blinking.\n");
            gpiod_line_set_value(led_line, 0);  // Turn off LED
            gpiod_line_release(led_line);
            gpiod_chip_close(chip);
            exit(EXIT_SUCCESS);
        }
    }

    // Clean up on exit
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}

