#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define LED_PIN 24
#define BUTTON_PIN 22
#define LED_ON 1
#define LED_OFF 0
#define BUTTON_PRESSED 0
#define BUTTON_RELEASED 1
#define BLINK_PERIOD 500

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    const char *chip_name = "gpiochip0";
    const char *led_label = "LED";
    const char *button_label = "BUTTON";
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *button_line;
    int led_value, button_value;
    int blink_count = 0;

    // Register signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the gpiochip device
    chip = gpiod_chip_open(chip_name);
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip device: %s\n", gpiod_strerror(gpiod_last_error()));
        return EXIT_FAILURE;
    }

    // Get the LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line: %s\n", gpiod_strerror(gpiod_last_error()));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get the button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        fprintf(stderr, "Failed to get button line: %s\n", gpiod_strerror(gpiod_last_error()));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the direction of the LED line to output
    if (gpiod_line_request_output(led_line, led_label, LED_OFF) < 0) {
        fprintf(stderr, "Failed to set LED line direction: %s\n", gpiod_strerror(gpiod_last_error()));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set the direction of the button line to input with internal pull-down
    if (gpiod_line_request_input(button_line, button_label, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        fprintf(stderr, "Failed to set button line direction: %s\n", gpiod_strerror(gpiod_last_error()));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Read the button value
        button_value = gpiod_line_get_value(button_line);
        if (button_value < 0) {
            fprintf(stderr, "Failed to read button line value: %s\n", gpiod_strerror(gpiod_last_error()));
            break;
        }

        // If the button is pressed
        if (button_value == BUTTON_PRESSED) {
            // Blink the LED
            for (int i = 0; i < 2; i++) {
                gpiod_line_set_value(led_line, LED_ON);
                usleep(BLINK_PERIOD * 1000);
                gpiod_line_set_value(led_line, LED_OFF);
                usleep(BLINK_PERIOD * 1000);
            }
            blink_count++;
        } else {
            // If the button is released
            gpiod_line_set_value(led_line, LED_OFF);
        }

        // Sleep for a short period to avoid busy-waiting
        usleep(10000);
    }

    // Release the lines and chip
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

