#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_RED 24
#define GPIO_GREEN 23
#define GPIO_BLUE 18
#define PWM_PERIOD 100000000  // 10 ms period
#define PWM_DUTY_MAX 100

static gpiod_chip *chip;
static gpiod_line *red_line, *green_line, *blue_line;

static void sigint_handler(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    struct timespec sleep_time = {0, 1000000};  // 1 ms
    int red, green, blue;
    srand(time(NULL));

    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get lines for each color
    red_line = gpiod_chip_get_line(chip, GPIO_RED);
    if (!red_line) {
        perror("Failed to get GPIO line for red");
        gpiod_chip_close(chip);
        return 1;
    }

    green_line = gpiod_chip_get_line(chip, GPIO_GREEN);
    if (!green_line) {
        perror("Failed to get GPIO line for green");
        gpiod_line_release(red_line);
        gpiod_chip_close(chip);
        return 1;
    }

    blue_line = gpiod_chip_get_line(chip, GPIO_BLUE);
    if (!blue_line) {
        perror("Failed to get GPIO line for blue");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request lines as outputs
    if (gpiod_line_request_output(red_line, "red", 0) < 0) {
        perror("Failed to request GPIO line for red as output");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(green_line, "green", 0) < 0) {
        perror("Failed to request GPIO line for green as output");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(blue_line, "blue", 0) < 0) {
        perror("Failed to request GPIO line for blue as output");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(chip);
        return 1;
    }

    while (1) {
        // Generate random RGB values
        red = rand() % (PWM_DUTY_MAX + 1);
        green = rand() % (PWM_DUTY_MAX + 1);
        blue = rand() % (PWM_DUTY_MAX + 1);

        // Set PWM duty cycles
        gpiod_line_set_value(red_line, red);
        gpiod_line_set_value(green_line, green);
        gpiod_line_set_value(blue_line, blue);

        // Busy-wait PWM loop
        while (1) {
            if (clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time) < 0) {
                perror("Failed to sleep");
                break;
            }
        }
    }

    // Clean up
    gpiod_line_release(red_line);
    gpiod_line_release(green_line);
    gpiod_line_release(blue_line);
    gpiod_chip_close(chip);

    return 0;
}

