#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDR 0x19
#define I2C_BUS 1
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0
#define LOG_FILE "impact_log.txt"
#define SAMPLE_RATE 10
#define G_TO_LSB 16384.0

static int i2c_handle;
static int gpio_pin;
static double threshold = DEFAULT_THRESHOLD;
static int running = 1;

void signal_handler(int sig) {
    running = 0;
    gpio_write(gpio_pin, 0);
    close(i2c_handle);
    pigpio_stop();
    printf("Program terminated by signal %d\n", sig);
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    int opt;
    struct timespec ts;
    double x, y, z, g_force;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio library
    if (pigpio_start() < 0) {
        fprintf(stderr, "Failed to start pigpio library\n");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO
    gpio_pin = GPIO_PIN;
    if (gpio_set_mode(gpio_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    i2c_handle = i2c_open(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        exit(EXIT_FAILURE);
    }

    // Configure LSM303DLHC
    if (i2c_write_byte_data(i2c_handle, 0x20, 0x07) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1_A\n");
        exit(EXIT_FAILURE);
    }
    if (i2c_write_byte_data(i2c_handle, 0x23, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4_A\n");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read accelerometer data
        if (i2c_read_i2c_block_data(i2c_handle, 0x28, 6, (uint8_t *)&x) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        // Convert raw data to G-force
        x = (double)x / G_TO_LSB;
        y = (double)y / G_TO_LSB;
        z = (double)z / G_TO_LSB;
        g_force = sqrt(x * x + y * y + z * z);

        // Check if impact threshold is exceeded
        if (g_force > threshold) {
            // Pulse GPIO17 HIGH for 50 ms
            gpio_write(gpio_pin, 1);
            usleep(50000);
            gpio_write(gpio_pin, 0);

            // Log timestamped accelerometer data
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Failed to open log file\n");
                continue;
            }
            fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", timestamp, x, y, z);
            fclose(log_file);
        }

        // Sleep for 100 ms
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000;
        nanosleep(&ts, NULL);
    }

    // Clean up
    close(i2c_handle);
    gpio_write(gpio_pin, 0);
    gpio_free(gpio_pin);
    pigpio_stop();

    return EXIT_SUCCESS;
}

