            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        // Convert raw data to G-force
        x = (double)x / G_TO_LSB;
        y = (double)y / G_TO_LSB;
        z = (double)z / G_TO_LSB;
        g_force = sqrt(x * x + y * y + z * z);

        // Check if impact threshold is exceeded
        if (g_force > threshold) {
            // Pulse GPIO17 HIGH for 50 ms
            gpio_write(gpio_pin, 1);
            usleep(50000);
            gpio_write(gpio_pin, 0);

            // Log timestamped accelerometer data
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Failed to open log file\n");
                continue;
            }
            fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", timestamp, x, y, z);
            fclose(log_file);
        }

        // Sleep for 100 ms
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000;
        nanosleep(&ts, NULL);
    }

    // Clean up
    close(i2c_handle);
    gpio_write(gpio_pin, 0);
    gpio_free(gpio_pin);
    pigpio_stop();

    return EXIT_SUCCESS;
}
