#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define ALS_REG 0x64
#define ALS_MSB_REG 0x65
#define RGB_REG 0x66
#define RGB_MSB_REG 0x68
#define RGB_GREEN_REG 0x6A
#define MODE_REG 0x0D
#define MODE_NORMAL 0x01
#define LED_PIN 18
#define PWM_FREQ 1000
#define PWM_DUTY_MAX 255
#define CSV_FILE "color_log.csv"
#define MAX_RETRIES 10
#define RETRY_DELAY_MS 100

static int i2c_handle;
static FILE *csv_file;
static int led_pwm_handle;
static int led_state = 0;
static int retries = 0;

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

void log_data(unsigned short als, unsigned short r, unsigned short g, unsigned short b) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    fprintf(csv_file, "%ld,%u,%u,%u,%u\n", ts.tv_sec * 1000000 + ts.tv_nsec / 1000, als, r, g, b);
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (csv_file) {
            fclose(csv_file);
        }
        if (led_pwm_handle) {
            gpioPWMWrite(led_pin, 0);
            gpioPWMStop(led_pin);
        }
        if (i2c_handle) {
            i2cClose(i2c_handle);
        }
        exit(0);
    }
}

void init_i2c() {
    if (i2cHandleOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        log_error("Failed to open I2C handle");
        exit(EXIT_FAILURE);
    }
}

void init_led() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set LED pin mode");
        exit(EXIT_FAILURE);
    }
    if (gpioPWMWrite(LED_PIN, 0) < 0) {
        log_error("Failed to set LED initial duty cycle");
        exit(EXIT_FAILURE);
    }
    if (gpioPWM(led_pin, PWM_FREQ) < 0) {
        log_error("Failed to start LED PWM");
        exit(EXIT_FAILURE);
    }
}

void write_mode() {
    unsigned char mode = MODE_NORMAL;
    if (i2cWriteReg(i2c_handle, MODE_REG, mode) < 0) {
        log_error("Failed to write mode register");
        retries++;
        if (retries >= MAX_RETRIES) {
            log_error("Too many retries, exiting");
            exit(EXIT_FAILURE);
        }
        usleep(RETRY_DELAY_MS * 1000);
        write_mode();
    }
}

unsigned short read_16bit_reg(unsigned char reg) {
    unsigned char data[2];
    if (i2cReadReg(i2c_handle, reg, data, 2) < 0) {
        log_error("Failed to read 16-bit register");
        retries++;
        if (retries >= MAX_RETRIES) {
            log_error("Too many retries, exiting");
            exit(EXIT_FAILURE);
        }
        usleep(RETRY_DELAY_MS * 1000);
        return 0;
    }
    return (data[1] << 8) | data[0];
}

void read_sensor_data() {
    unsigned short als = read_16bit_reg(ALS_REG);
    unsigned short r = read_16bit_reg(RGB_REG);
    unsigned short g = read_16bit_reg(RGB_GREEN_REG);
    unsigned short b = read_16bit_reg(RGB_MSB_REG);
    log_data(als, r, g, b);
}

int main() {
    if (gpioSetSignalFunc(SIGINT, handle_signal) < 0) {
        log_error("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }
    if (gpioSetSignalFunc(SIGTERM, handle_signal) < 0) {
        log_error("Failed to set SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    init_i2c();
    init_led();
    write_mode();

    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        log_error("Failed to open CSV file");
        exit(EXIT_FAILURE);
    }
    fprintf(csv_file, "timestamp,als,r,g,b\n");

    while (1) {
        read_sensor_data();
        usleep(500000); // Sample every 500 ms
    }

    fclose(csv_file);
    gpioPWMWrite(led_pin, 0);
    gpioPWMStop(led_pin);
    gpioTerminate();
    i2cClose(i2c_handle);

    return 0;
}

