#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define LOG_FILE "gyro_log.txt"
#define SAMPLE_RATE 20
#define CALIBRATION_SAMPLES 100
#define CALIBRATION_OFFSET 0.00875
#define MAX_DPS 50.0

static int i2c_fd;
static FILE *log_file;
static int calibration_done = 0;
static double zero_rate_offsets[3] = {0.0, 0.0, 0.0};

static void handle_signal(int sig) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

static void log_data(double x, double y, double z) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
}

static void calibrate_gyro() {
    int i;
    double sum_x = 0.0, sum_y = 0.0, sum_z = 0.0;
    for (i = 0; i < CALIBRATION_SAMPLES; i++) {
        int ret = read(i2c_fd, &zero_rate_offsets[0], 6);
        if (ret != 6) {
            perror("Failed to read calibration data");
            exit(1);
        }
        sum_x += zero_rate_offsets[0] * CALIBRATION_OFFSET;
        sum_y += zero_rate_offsets[1] * CALIBRATION_OFFSET;
        sum_z += zero_rate_offsets[2] * CALIBRATION_OFFSET;
        usleep(50000); // 50 ms delay
    }
    zero_rate_offsets[0] = sum_x / CALIBRATION_SAMPLES;
    zero_rate_offsets[1] = sum_y / CALIBRATION_SAMPLES;
    zero_rate_offsets[2] = sum_z / CALIBRATION_SAMPLES;
    calibration_done = 1;
}

static void read_gyro() {
    int ret;
    int16_t raw_x, raw_y, raw_z;
    double x, y, z;

    ret = read(i2c_fd, &raw_x, 2);
    if (ret != 2) {
        perror("Failed to read X data");
        exit(1);
    }
    ret = read(i2c_fd, &raw_y, 2);
    if (ret != 2) {
        perror("Failed to read Y data");
        exit(1);
    }
    ret = read(i2c_fd, &raw_z, 2);
    if (ret != 2) {
        perror("Failed to read Z data");
        exit(1);
    }

    x = (raw_x - zero_rate_offsets[0]) * CALIBRATION_OFFSET;
    y = (raw_y - zero_rate_offsets[1]) * CALIBRATION_OFFSET;
    z = (raw_z - zero_rate_offsets[2]) * CALIBRATION_OFFSET;

    if (x > MAX_DPS || x < -MAX_DPS || y > MAX_DPS || y < -MAX_DPS || z > MAX_DPS || z < -MAX_DPS) {
        fprintf(stderr, "Warning: Gyro exceeds 50 dps: %.2f, %.2f, %.2f\n", x, y, z);
        log_data(x, y, z);
    }

    log_data(x, y, z);
}

int main() {
    int ret;
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data msgset;
    uint8_t buf[10];

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    // Set I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(1);
    }

    // Check WHO_AM_I
    buf[0] = WHO_AM_I;
