This C program uses the Linux i2c-dev ioctl interface to read angular velocity from a GY-50 L3G4200D gyroscope on a Raspberry Pi Zero W. It configures the gyroscope, performs a calibration, and logs the readings with ISO-8601 timestamps. The program handles sensor absence and I2C bus errors, and logs any axis readings exceeding 50 dps. It also cleans up resources on SIGINT/SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define DEVID_REG 0x00
#define X_REG 0x32
#define LOG_FILE "accel_log.txt"
#define LED_PIN 17
#define SAMPLE_RATE 10 // Hz
#define MAX_SAMPLES 1000000 // 1000 samples per second for 10 Hz

static volatile sig_atomic_t keep_running = 1;

void sig_handler(int sig) {
    keep_running = 0;
}

int main() {
    FILE *log_file;
    int i2c_handle;
    uint8_t dev_id;
    uint8_t data[6];
    struct timespec sleep_time;
    double x, y, z;
    double max_accel = 2.0; // g
    int led_state = 0;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up I2C handle
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    // Read DEVID register to verify sensor
    if (i2cReadReg8(i2c_handle, DEVID_REG, &dev_id) < 0) {
        fprintf(stderr, "Failed to read DEVID register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (dev_id != 0xE5) {
        fprintf(stderr, "Invalid DEVID register value: 0x%02X\n", dev_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up LED pin
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor for full-resolution, ±2g range
    if (i2cWriteReg8(i2c_handle, 0x2D, 0x08) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Main loop
    while (keep_running) {
        // Read X/Y/Z data
        if (i2cReadBlockData(i2c_handle, X_REG, data, 6) < 0) {
            fprintf(stderr, "Failed to read X/Y/Z data\n");
            continue;
        }

        // Convert raw data to g units
        x = (double)data[0] / 256.0 + (double)data[1] / 256.0;
        y = (double)data[2] / 256.0 + (double)data[3] / 256.0;
        z = (double)data[4] / 256.0 + (double)data[5] / 256.0;

        // Log sample
        fprintf(log_file, "%ld,%0.3f,%0.3f,%0.3f\n", time(NULL), x, y, z);

        // Check if any axis exceeds max_accel
        if (fabs(x) > max_accel || fabs(y) > max_accel || fabs(z) > max_accel) {
            led_state = 1;
        } else {
            led_state = 0;
        }

        // Set LED state
        if (gpioWrite(LED_PIN, led_state) < 0) {
            fprintf(stderr, "Failed to set LED state\n");
        }

        // Sleep for 100 ms
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000;
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

