This C program uses the pigpio library to read acceleration data from an ADXL345 accelerometer over I2C bus 1 at address 0x53. It configures the sensor for full-resolution, ±2g range, verifies the DEVID register, reads the 6 bytes of X/Y/Z data every 100 ms (10 Hz), logs each sample to 'accel_log.txt', and turns on an LED connected to GPIO17 when the absolute acceleration on any axis exceeds 2.0 g. The program handles I2C read failures and ensures clean resource release on SIGINT/SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CONTROL_REG 0x00
#define SAMPLE_INTERVAL_MS 10
#define MAX_RETRIES 3

static int i2c_handle1, i2c_handle2;
static FILE *log_file;
static volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int signum) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C handle for sensor 1\n");
        pigpioTerminate();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C handle for sensor 2\n");
        i2cClose(i2c_handle1);
        pigpioTerminate();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteReg16(i2c_handle1, CONTROL_REG, 0x80) < 0) {
        fprintf(stderr, "Failed to enable continuous measurement for sensor 1\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        pigpioTerminate();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteReg16(i2c_handle2, CONTROL_REG, 0x80) < 0) {
        fprintf(stderr, "Failed to enable continuous measurement for sensor 2\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        pigpioTerminate();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen("audio_log.dat", "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        pigpioTerminate();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_REALTIME, &start_time);

    while (!exit_flag) {
        for (int i = 0; i < 2; i++) {
            int retries = MAX_RETRIES;
            int sensor_addr = i == 0 ? SENSOR1_ADDR : SENSOR2_ADDR;
            int data_reg = i == 0 ? DATA_REG : DATA_REG + 2; // Assuming each sensor has two registers

            while (retries--) {
                if (i2cReadReg16(i2c_handle1, data_reg, &data) < 0) {
                    fprintf(stderr, "Failed to read data from sensor %d\n", i + 1);
                    continue;
                }

                if (clock_gettime(CLOCK_REALTIME, &current_time) < 0) {
                    fprintf(stderr, "Failed to get current time\n");
                    continue;
                }

                struct timespec diff;
                timespec_diff(&current_time, &start_time, &diff);

                fprintf(log_file, "%ld,%ld,%d,%d,%ld\n",
                        diff.tv_sec, diff.tv_nsec, sensor_addr, data, diff.tv_nsec - data);

                break;
            }
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    pigpioTerminate();
    gpioTerminate();

    return EXIT_SUCCESS;
}

void timespec_diff(struct timespec *result, struct timespec *start, struct timespec *end) {
    if (end->tv_nsec < start->tv_nsec) {
        end->tv_nsec += 1000000000;
        end->tv_sec--;
    }
    result->tv_sec = end->tv_sec - start->tv_sec;
    result->tv_nsec = end->tv_nsec - start->tv_nsec;
}

