        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    pigpioTerminate();
    gpioTerminate();

    return EXIT_SUCCESS;
}

void timespec_diff(struct timespec *result, struct timespec *start, struct timespec *end) {
    if (end->tv_nsec < start->tv_nsec) {
        end->tv_nsec += 1000000000;
        end->tv_sec--;
    }
    result->tv_sec = end->tv_sec - start->tv_sec;
    result->tv_nsec = end->tv_nsec - start->tv_nsec;
}
