#define REG_Y_GYRO 0x06
#define REG_Z_GYRO 0x08
#define REG_X_ACCEL 0x0A
#define REG_Y_ACCEL 0x0C
#define REG_Z_ACCEL 0x0E
#define GYRO_SENSITIVITY 0.005
#define ACCEL_SENSITIVITY 0.00025
#define SAMPLE_INTERVAL_MS 100
#define MAX_SAMPLES 1000000
#define CSV_HEADER "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z"

static volatile int running = 1;

void cleanup() {
    if (running) {
        running = 0;
        usleep(100000); // Wait for any pending SPI transfers to complete
        gpioTerminate();
        fclose(fp);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    atexit(cleanup);

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        return 1;
    }

    FILE *fp = fopen("imu_data.csv", "w");
    if (!fp) {
        fprintf(stderr, "Failed to open CSV file\n");
        return 1;
    }

    fprintf(fp, "%s\n", CSV_HEADER);

    struct timespec ts;
    while (running) {
        for (int i = 0; i < 3; i++) {
            uint16_t reg = 0;
            uint16_t data = 0;

            // Send the register address
            reg = 0x0000 | (i * 2);
            if (spiXfer(SPI_CHANNEL, &reg, &data, 1) < 0) {
                fprintf(stderr, "SPI transfer failed\n");
                continue;
            }

            // Wait for 40 microseconds
            clock_gettime(CLOCK_MONOTONIC, &ts);
            ts.tv_nsec += 40000000;
            if (ts.tv_nsec >= 1000000000) {
                ts.tv_nsec -= 1000000000;
                ts.tv_sec++;
            }
            nanosleep(&ts, NULL);

            // Send the register address again to get the data
            reg = 0x0000 | (i * 2 + 1);
            if (spiXfer(SPI_CHANNEL, &reg, &data, 1) < 0) {
                fprintf(stderr, "SPI transfer failed\n");
                continue;
            }

