            fprintf(fp, "%ld,%f,%f,%f,%f,%f,%f\n", ts.tv_sec * 1000000 + ts.tv_nsec / 1000, value, value, value, value, value, value);
        }

        // Non-blocking sampling delay
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(fp);
    return 0;
}

