#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_GPIO 8
#define SPI_MODE 3
#define SPI_SPEED 1000000
#define REG_XGYRO 0x04
#define REG_YGYRO 0x06
#define REG_ZGYRO 0x08
#define REG_XACCL 0x0A
#define REG_YACCL 0x0C
#define REG_ZACCL 0x0E
#define SCALE_GYRO 0.02
#define SCALE_ACCL 0.00025
#define LOG_INTERVAL 100000  // 100 ms

static int spi_fd;
static int cs_gpio_fd;
static struct gpiod_chip *cs_gpio_chip;
static struct gpiod_line *cs_gpio_line;
static struct timespec sleep_time;

static void sig_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        close(spi_fd);
        gpiod_chip_close(cs_gpio_chip);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int ret;
    uint8_t tx[2];
    uint16_t rx[2];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 1,
    };

    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Open GPIO chip
    cs_gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!cs_gpio_chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Get GPIO line
    cs_gpio_line = gpiod_chip_get_line(cs_gpio_chip, CS_GPIO);
    if (!cs_gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(cs_gpio_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Request GPIO line as output
    ret = gpiod_line_request_output(cs_gpio_line, "ADIS16448_CS", 0);
    if (ret) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(cs_gpio_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set GPIO line to high
    ret = gpiod_line_set_value(cs_gpio_line, 1);
    if (ret) {
        perror("Failed to set GPIO line high");
        gpiod_line_release(cs_gpio_line);
        gpiod_chip_close(cs_gpio_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret) {
        perror("Failed to set SPI mode");
        gpiod_line_release(cs_gpio_line);
        gpiod_chip_close(cs_gpio_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret) {
        perror("Failed to set SPI speed");
        gpiod_line_release(cs_gpio_line);
        gpiod_chip_close(cs_gpio_chip);
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set sleep time for logging
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = LOG_INTERVAL;

    while (1) {
        // Read gyroscope X
        tx[0] = REG_XGYRO | 0x80;  // Set bit 7
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
