        int16_t gyro_y = (rx[0] << 8) | rx[1];
        printf("Gyroscope Y: %d\n", gyro_y);

        // Read gyroscope Z
        tx[0] = REG_ZGYRO | 0x80;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
        if (ret) {
            perror("Failed to read gyroscope Z");
            continue;
        }
        int16_t gyro_z = (rx[0] << 8) | rx[1];
        printf("Gyroscope Z: %d\n", gyro_z);

        // Read accelerometer X
        tx[0] = REG_XACCL | 0x80;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
        if (ret) {
            perror("Failed to read accelerometer X");
            continue;
        }
        int16_t acc_x = (rx[0] << 8) | rx[1];
        printf("Accelerometer X: %d\n", acc_x);

        // Read accelerometer Y
        tx[0] = REG_YACCL | 0x80;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
        if (ret) {
            perror("Failed to read accelerometer Y");
            continue;
        }
        int16_t acc_y = (rx[0] << 8) | rx[1];
        printf("Accelerometer Y: %d\n", acc_y);

        // Read accelerometer Z
        tx[0] = REG_ZACCL | 0x80;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE, &tr);
        if (ret) {
            perror("Failed to read accelerometer Z");
            continue;
        }
        int16_t acc_z = (rx[0] << 8) | rx[1];
        printf("Accelerometer Z: %d\n", acc_z);

        // Apply scale factors
        printf("Gyroscope X (dps): %f\n", gyro_x * SCALE_GYRO);
        printf("Gyroscope Y (dps): %f\n", gyro_y * SCALE_GYRO);
        printf("Gyroscope Z (dps): %f\n", gyro_z * SCALE_GYRO);
        printf("Accelerometer X (g): %f\n", acc_x * SCALE_ACCL);
        printf("Accelerometer Y (g): %f\n", acc_y * SCALE_ACCL);
        printf("Accelerometer Z (g): %f\n", acc_z * SCALE_ACCL);

        // Sleep for 100 ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    gpiod_line_release(cs_gpio_line);
    gpiod_chip_close(cs_gpio_chip);
    close(spi_fd);

    return 0;
}

