#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_DELAY_USEC 40
#define GYRO_SCALE 0.05
#define ACCEL_SCALE 0.00025

static volatile sig_atomic_t quit = 0;

void sigint_handler(int sig) {
    quit = 1;
}

int main() {
    int fd;
    uint16_t gyro_x, gyro_y, gyro_z;
    uint16_t accel_x, accel_y, accel_z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up SPI
    fd = gpioSpidevOpen(SPI_CHANNEL, SPI_SPEED_HZ, SPI_MODE);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    while (!quit) {
        // Read gyroscope x, y, z
        uint16_t gyro_reg = 0x04; // X_GYRO_OUT
        if (gpioSpidevRead(fd, &gyro_x, 2) < 0) {
            fprintf(stderr, "Failed to read from SPI\n");
            break;
        }
        gyro_x = (gyro_x << 8) | gyro_y;
        gyro_x = (gyro_x << 8) | gyro_z;
        gyro_x = (gyro_x >> 2); // Remove the first two bits
        gyro_x *= GYRO_SCALE;
        printf("Gyro X: %.2f deg/sec\n", gyro_x);

        // Read accelerometer x, y, z
        uint16_t accel_reg = 0x0A; // X_ACCL_OUT
        if (gpioSpidevRead(fd, &accel_x, 2) < 0) {
            fprintf(stderr, "Failed to read from SPI\n");
            break;
        }
        accel_x = (accel_x << 8) | accel_y;
        accel_x = (accel_x << 8) | accel_z;
        accel_x = (accel_x >> 2); // Remove the first two bits
        accel_x *= ACCEL_SCALE;
        printf("Accel X: %.2f g\n", accel_x);

        // Read gyroscope y, z
        gyro_reg = 0x06; // Y_GYRO_OUT
        if (gpioSpidevRead(fd, &gyro_y, 2) < 0) {
            fprintf(stderr, "Failed to read from SPI\n");
            break;
        }
        gyro_y = (gyro_y << 8) | gyro_z;
        gyro_y = (gyro_y << 8) | gyro_x;
        gyro_y = (gyro_y >> 2); // Remove the first two bits
        gyro_y *= GYRO_SCALE;
        printf("Gyro Y: %.2f deg/sec\n", gyro_y);

        // Read accelerometer y, z
        accel_reg = 0x0C; // Y_ACCL_OUT
        if (gpioSpidevRead(fd, &accel_y, 2) < 0) {
            fprintf(stderr, "Failed to read from SPI\n");
            break;
