#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define LED_PIN 17
#define LOG_FILE "impact_log.txt"
#define MAX_ACCEL 2.5
#define POLL_INTERVAL 10000

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    int i2c_handle;
    int accel_x, accel_y, accel_z;
    float magnitude;
    char log_entry[256];
    struct timespec ts;
    FILE *log_file;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up I2C
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up LED
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read device ID
    if (i2cReadReg8(i2c_handle, 0x00) != 0xE5) {
        fprintf(stderr, "Device ID mismatch\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure accelerometer
    i2cWriteReg8(i2c_handle, 0x31, 0x08); // Set data rate to 100 Hz
    i2cWriteReg8(i2c_handle, 0x32, 0x08); // Set range to +-2g
    i2cWriteReg8(i2c_handle, 0x33, 0x08); // Set resolution to 10-bit

    // Main loop
    while (keep_running) {
        // Read accelerometer data
        if (i2cReadReg8(i2c_handle, 0x32) != 0x08) {
            fprintf(stderr, "Failed to read data rate\n");
            break;
        }
        if (i2cReadReg8(i2c_handle, 0x33) != 0x08) {
            fprintf(stderr, "Failed to read resolution\n");
            break;
        }
        if (i2cReadReg8(i2c_handle, 0x34) != 0x08) {
            fprintf(stderr, "Failed to read range\n");
