#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define WHO_AM_I 0x75
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int signum) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (i2cHandleOpen(I2C_BUS, I2C_ADDR, &i2c_handle) < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, WHO_AM_I, 0x00) < 0) {
        fprintf(stderr, "Failed to write WHO_AM_I register\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i;
    if (i2cReadByteData(i2c_handle, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != 0x12) {
        fprintf(stderr, "Failed to detect ICM-20602\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer to +-2g\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set gyroscope to +-250 dps\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("imu_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct timespec sleep_time = {0, 10000000}; // 100 ms
    struct timespec remaining_time;

    signal(SIGINT, handle_sigint);

    while (!exit_flag) {
        uint8_t accel_data[6];
        uint8_t gyro_data[6];

        if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, accel_data, 6) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, gyro_data, 6) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        fprintf(log_file, "%s, %d, %d, %d, %d, %d, %d, %d, %d, %d, %d, %d\n",
                timestamp,
                (accel_data[0] << 8) | accel_data[1],
                (accel_data[2] << 8) | accel_data[3],
                (accel_data[4] << 8) | accel_data[5],
                (gyro_data[0] << 8) | gyro_data[1],
                (gyro_data[2] << 8) | gyro_data[3],
                (gyro_data[4] << 8) | gyro_data[5],
                (gyro_data[6] << 8) | gyro_data[7],
                (gyro_data[8] << 8) | gyro_data[9],
                (gyro_data[10] << 8) | gyro_data[11],
                (gyro_data[12] << 8) | gyro_data[13],
                (gyro_data[14] << 8) | gyro_data[15]);

        nanosleep(&sleep_time, &remaining_time);
    }

    fclose(log_file);
    i2cHandleClose(i2c_handle);
    gpioTerminate();

    return 0;
