#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <libgpiod.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define ACCEL_X_REG 0x01
#define ACCEL_Y_REG 0x03
#define ACCEL_Z_REG 0x05
#define ACCEL_RANGE 1024
#define THRESHOLD 2.0
#define LED_PIN 17
#define LOG_FILE "impact_log.txt"

static int i2c_fd;
static int led_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *led_line;

void log_impact(const char *message) {
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open impact_log.txt");
        return;
    }
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(log, "%s: %s\n", asctime(tm), message);
    fclose(log);
}

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (led_fd >= 0) {
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open LED GPIO line
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(led_line, "impact_led", 0) < 0) {
        perror("Failed to request LED GPIO line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Verify WHO_AM_I register
    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (who_am_i != 0x1A) {
        fprintf(stderr, "Invalid WHO_AM_I register value: 0x%02X\n", who_am_i);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read acceleration data
        uint8_t data[6];
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read acceleration data");
            continue;
        }
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        // Calculate magnitude of acceleration
        float magnitude = sqrt(x * x + y * y + z * z) / ACCEL_RANGE;

        // Check if impact is detected
        if (magnitude > THRESHOLD) {
            // Turn on LED
            gpiod_line_set_value(led_line, 1);
            // Log impact
            log_impact("Impact detected");
            // Wait for 500 ms
            usleep(500000);
            // Turn off LED
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

