    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(log, "%s: %s\n", asctime(tm), message);
    fclose(log);
}

void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (led_fd >= 0) {
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
    }
    exit(signum);
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open LED GPIO line
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(led_line, "impact_led", 0) < 0) {
        perror("Failed to request LED GPIO line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Verify WHO_AM_I register
    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (who_am_i != 0x1A) {
        fprintf(stderr, "Invalid WHO_AM_I register value: 0x%02X\n", who_am_i);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read acceleration data
        uint8_t data[6];
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read acceleration data");
            continue;
        }
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        // Calculate magnitude of acceleration
        float magnitude = sqrt(x * x + y * y + z * z) / ACCEL_RANGE;

        // Check if impact is detected
        if (magnitude > THRESHOLD) {
            // Turn on LED
            gpiod_line_set_value(led_line, 1);
            // Log impact
            log_impact("Impact detected");
            // Wait for 500 ms
            usleep(500000);
            // Turn off LED
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}
```

This C program reads X, Y, and Z acceleration data from a GY-45 MMA8451Q accelerometer over I2C bus 1 at address 0x1D, using the Linux i2c-dev ioctl interface for I2C access and libgpiod for the LED GPIO line on GPIO17 (BCM numbering). It verifies the sensor's identity by reading the WHO_AM_I register, polls the sensor every 100 ms, and triggers the LED if the magnitude of acceleration on any axis exceeds a threshold of 2.0g. It handles I2C read/write errors gracefully and cleanly releases all resources on SIGINT or SIGTERM.

