#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define GPIO_INT1 17
#define LOG_FILE "freefall_log.csv"
#define MAX_LOG_SIZE 1024 * 1024 // 1 MB

static int i2c_fd;
static int gpio_fd;
static FILE *log_file;
static struct gpiod_chip *chip;
static struct gpiod_line *line;
static struct gpiod_line_event event;
static struct timespec ts;
static char log_buffer[MAX_LOG_SIZE];
static size_t log_offset = 0;

static void log_freefall(int x, int y, int z) {
    clock_gettime(CLOCK_REALTIME, &ts);
    strftime(log_buffer + log_offset, MAX_LOG_SIZE - log_offset, "%Y-%m-%d %H:%M:%S.%03ld", &ts);
    log_offset += snprintf(log_buffer + log_offset, MAX_LOG_SIZE - log_offset, ",%d,%d,%d\n", x, y, z);
    if (log_offset >= MAX_LOG_SIZE) {
        log_offset = 0;
        if (ftruncate(log_file, 0) == -1) {
            perror("ftruncate");
        }
    }
    if (fwrite(log_buffer, 1, log_offset, log_file) != log_offset) {
        perror("fwrite");
    }
    fflush(log_file);
}

static void handle_interrupt(void) {
    int x, y, z;
    uint8_t data[6];
    int ret;

    ret = gpiod_event_read(gpio_fd, &event);
    if (ret == -1) {
        perror("gpiod_event_read");
        return;
    }

    if (event.type != GPIOD_LINE_EVENT_RISING_EDGE) {
        return;
    }

    ret = ioctl(i2c_fd, I2C_SMBUS_READ_BLOCK_DATA, ADXL345_ADDR, 0x30, data);
    if (ret == -1) {
        perror("I2C_SMBUS_READ_BLOCK_DATA");
        return;
    }

    if ((data[0] & 0x04) == 0) {
        return;
    }

    x = (data[1] << 8) | data[2];
    y = (data[3] << 8) | data[4];
    z = (data[5] << 8) | data[6];

    log_freefall(x, y, z);
}

static void handle_signal(int sig) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_fd >= 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    int ret;
    uint8_t data[6];
    uint8_t id;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return 1;
    }

    // Open GPIO line
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        close(i2c_fd);
        return 1;
    }
    line = gpiod_chip_get_line(chip, GPIO_INT1);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    ret = gpiod_line_request_input(line, "freefall");
    if (ret) {
        perror("gpiod_line_request_input");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Check device ID
    ret = ioctl(i2c_fd, I2C_SMBUS_READ_BYTE, ADXL345_ADDR);
    if (ret == -1) {
        perror("I2C_SMBUS_READ_BYTE");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    id = ret;
    if (id != 0xE5) {
        fprintf(stderr, "Device ID is not 0xE5, got 0x%02X\n", id);
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Enter standby mode
    data[0] = 0x2D;
    data[1] = 0x00;
    ret = ioctl(i2c_fd, I2C_SMBUS_WRITE_BLOCK_DATA, ADXL345_ADDR, 2, data);
    if (ret == -1) {
        perror("I2C_SMBUS_WRITE_BLOCK_DATA");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Configure freefall settings
    data[0] = 0x0A; // THRESH_FF
    data[1] = 0x00; // 300 mg
    ret = ioctl(i2c_fd, I2C_SMBUS_WRITE_BLOCK_DATA, ADXL345_ADDR, 2, data);
    if (ret == -1) {
        perror("I2C_SMBUS_WRITE_BLOCK_DATA");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    data[0] = 0x20; // TIME_FF
    data[1] = 0x00; // 100 ms
    ret = ioctl(i2c_fd, I2C_SMBUS_WRITE_BLOCK_DATA, ADXL345_ADDR, 2, data);
    if (ret == -1) {
        perror("I2C_SMBUS_WRITE_BLOCK_DATA");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    data[0] = 0x2E; // INT_ENABLE
    data[1] = 0x04; // Enable freefall interrupt
    ret = ioctl(i2c_fd, I2C_SMBUS_WRITE_BLOCK_DATA, ADXL345_ADDR, 2, data);
    if (ret == -1) {
        perror("I2C_SMBUS_WRITE_BLOCK_DATA");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }
    data[0] = 0x2F; // INT_MAP
    data[1] = 0x00; // Map freefall interrupt to INT1
    ret = ioctl(i2c_fd, I2C_SMBUS_WRITE_BLOCK_DATA, ADXL345_ADDR, 2, data);
    if (ret == -1) {
        perror("I2C_SMBUS_WRITE_BLOCK_DATA");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Enter measurement mode
    data[0] = 0x2D;
    data[1] = 0x08;
    ret = ioctl(i2c_fd, I2C_SMBUS_WRITE_BLOCK_DATA, ADXL345_ADDR, 2, data);
    if (ret == -1) {
        perror("I2C_SMBUS_WRITE_BLOCK_DATA");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Poll for interrupts
    while (1) {
        ret = gpiod_event_wait(gpio_fd, -1);
        if (ret == -1) {
            perror("gpiod_event_wait");
            break;
        }
        handle_interrupt();
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

