        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Enter measurement mode
    data[0] = 0x2D;
    data[1] = 0x08;
    ret = ioctl(i2c_fd, I2C_SMBUS_WRITE_BLOCK_DATA, ADXL345_ADDR, 2, data);
    if (ret == -1) {
        perror("I2C_SMBUS_WRITE_BLOCK_DATA");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Poll for interrupts
    while (1) {
        ret = gpiod_event_wait(gpio_fd, -1);
        if (ret == -1) {
            perror("gpiod_event_wait");
            break;
        }
        handle_interrupt();
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}
