#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define SDA 2
#define SCL 3
#define ACCEL_XOUT_H 0x28
#define ACCEL_XOUT_L 0x29
#define ACCEL_YOUT_H 0x2A
#define ACCEL_YOUT_L 0x2B
#define ACCEL_ZOUT_H 0x2C
#define ACCEL_ZOUT_L 0x2D
#define GYRO_XOUT_H 0x2E
#define GYRO_XOUT_L 0x2F
#define GYRO_YOUT_H 0x30
#define GYRO_YOUT_L 0x31
#define GYRO_ZOUT_H 0x32
#define GYRO_ZOUT_L 0x33
#define WHO_AM_I 0x0F
#define ACCEL_FS_2G 0x08
#define GYRO_FS_250DPS 0x00
#define GYRO_ODR_104HZ 0x07
#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define WINDOW_DURATION 1000000 // 1 second in microseconds

static int gpiod_handle;
static FILE *log_file;
static int freefall_detected = 0;
static int impact_detected = 0;
static int freefall_start_time = 0;
static int impact_start_time = 0;

void signal_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (gpiod_handle >= 0) {
        gpioTerminate();
    }
    exit(signum);
}

int read_i2c_register(int reg) {
    uint8_t buffer[2];
    int result = gpioI2CReadReg8(gpiod_handle, I2C_ADDR, reg, buffer);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    return buffer[0] | (buffer[1] << 8);
}

void write_i2c_register(int reg, int value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    int result = gpioI2CWriteReg8(gpiod_handle, I2C_ADDR, buffer[0], buffer[1]);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "GPIO initialisation failed\n");
        exit(EXIT_FAILURE);
    }
    gpiod_handle = gpioOpen(I2C_BUS, 0);
    if (gpiod_handle < 0) {
        fprintf(stderr, "GPIO open failed\n");
        exit(EXIT_FAILURE);
    }
    write_i2c_register(WHO_AM_I, 0x6A); // Check WHO_AM_I register
    if (read_i2c_register(WHO_AM_I) != 0x6A) {
        fprintf(stderr, "LSM6DSR not found at address 0x6A\n");
        exit(EXIT_FAILURE);
    }
    write_i2c_register(0x10, ACCEL_FS_2G | GYRO_FS_250DPS); // Set full scale range
    write_i2c_register(0x11, GYRO_ODR_104HZ); // Set output data rate
}

