    fprintf(log_file, "%d,%f,%f,%f,%f,%f,%f\n", timestamp, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
}

void check_freefall() {
    static int last_accel_x = 0;
    static int last_accel_y = 0;
    static int last_accel_z = 0;
    static int freefall_count = 0;

    int accel_x = read_i2c_register(ACCEL_XOUT_H) | (read_i2c_register(ACCEL_XOUT_L) << 8);
    int accel_y = read_i2c_register(ACCEL_YOUT_H) | (read_i2c_register(ACCEL_YOUT_L) << 8);
    int accel_z = read_i2c_register(ACCEL_ZOUT_H) | (read_i2c_register(ACCEL_ZOUT_L) << 8);

    float accel_magnitude = sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z) / 32768.0;

    if (accel_magnitude < FREEFALL_THRESHOLD) {
        freefall_count++;
        if (freefall_count >= 3) {
            if (freefall_start_time == 0) {
                freefall_start_time = time(NULL) * 1000000;
            }
            if (time(NULL) * 1000000 - freefall_start_time >= WINDOW_DURATION) {
                freefall_detected = 1;
                freefall_start_time = 0;
                freefall_count = 0;
            }
        }
    } else {
        freefall_count = 0;
    }

    if (freefall_detected) {
        log_motion(time(NULL) * 1000000, accel_x / 32768.0, accel_y / 32768.0, accel_z / 32768.0, 0, 0, 0);
        freefall_detected = 0;
    }
}

void check_impact() {
    static int last_accel_x = 0;
    static int last_accel_y = 0;
    static int last_accel_z = 0;
    static int impact_count = 0;

    int accel_x = read_i2c_register(ACCEL_XOUT_H) | (read_i2c_register(ACCEL_XOUT_L) << 8);
    int accel_y = read_i2c_register(ACCEL_YOUT_H) | (read_i2c_register(ACCEL_YOUT_L) << 8);
    int accel_z = read_i2c_register(ACCEL_ZOUT_H) | (read_i2c_register(ACCEL_ZOUT_L) << 8);

    float accel_magnitude = sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z) / 32768.0;

    if (accel_magnitude > IMPACT_THRESHOLD) {
        impact_count++;
        if (impact_count >= 3) {
            if (impact_start_time == 0) {
                impact_start_time = time(NULL) * 1000000;
            }
            if (time(NULL) * 1000000 - impact_start_time >= WINDOW_DURATION) {
                impact_detected = 1;
                impact_start_time = 0;
                impact_count = 0;
            }
        }
    } else {
        impact_count = 0;
    }

    if (impact_detected) {
        log_motion(time(NULL) * 1000000, accel_x / 32768.0, accel_y / 32768.0, accel_z / 32768.0, 0, 0, 0);
        impact_detected = 0;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_i2c();

    log_file = fopen("motion_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    while (1) {
        check_freefall();
        check_impact();
        usleep(10000); // 10 Hz
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

