#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GYRO_ADDR 0x69
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

#define MAX_RETRIES 3
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "gyro_log.csv"

static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (i2cHandleOpen(&i2c_handle, GYRO_ADDR, 1) < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteReg(i2c_handle, WHO_AM_I, 0x0F) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cReadReg(i2c_handle, WHO_AM_I, 0x0F) != 0xD3) {
        fprintf(stderr, "Sensor not found\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteReg(i2c_handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Failed to set CTRL_REG1\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteReg(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to set CTRL_REG4\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(log_file, "Timestamp,X,Y,Z\n");

    struct timespec sleep_time = {0, SAMPLE_INTERVAL_MS * 1000000};

    while (!should_exit) {
        uint8_t data[6];
        for (int retry = 0; retry < MAX_RETRIES; retry++) {
            if (i2cReadBlockData(i2c_handle, OUT_X_L, data, 6) == 6) {
                break;
            }
            if (retry == MAX_RETRIES - 1) {
                fprintf(stderr, "Failed to read data from sensor\n");
                break;
            }
        }

        if (should_exit) {
            break;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        uint16_t x = (data[1] << 8) | data[0];
        uint16_t y = (data[3] << 8) | data[2];
        uint16_t z = (data[5] << 8) | data[4];

        double x_degrees = (double)x / 114.285;
        double y_degrees = (double)y / 114.285;
        double z_degrees = (double)z / 114.285;

        fprintf(log_file, "%ld,%f,%f,%f\n", now.tv_sec * 1000000000 + now.tv_nsec, x_degrees, y_degrees, z_degrees);

        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    i2cHandleClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

int i2cHandleOpen(int *handle, uint8_t addr, int bus) {
    *handle = i2cOpen(bus, addr, 0);
    if (*handle < 0) {
        fprintf(stderr, "Failed to open I2C handle for address 0x%02X on bus %d\n", addr, bus);
        return -1;
    }
    return 0;
}

void i2cHandleClose(int handle) {
    i2cClose(handle);
}

int i2cWriteReg(int handle, uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "Failed to write to register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

int i2cReadReg(int handle, uint8_t reg, uint8_t *value) {
    if (i2cReadByteData(handle, reg, value) < 0) {
        fprintf(stderr, "Failed to read from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

int i2cReadBlockData(int handle, uint8_t reg, uint8_t *data, int length) {
    if (i2cReadBlockData(handle, reg, data, length) < 0) {
        fprintf(stderr, "Failed to read block data from register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

