#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_MS 500

static volatile sig_atomic_t stop = 0;

void sigint_handler(int signum) {
    stop = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO17 as an input with internal pull-up resistor
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for FLAME_SENSOR_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor for FLAME_SENSOR_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file in append mode
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!stop) {
        // Read the sensor
        int sensor_state = gpioRead(FLAME_SENSOR_PIN);
        if (sensor_state < 0) {
            fprintf(stderr, "Failed to read GPIO state for FLAME_SENSOR_PIN\n");
            continue;
        }

        // Log the event
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        char log_line[100];
        snprintf(log_line, sizeof(log_line), "%s - Flame detected: %s\n", timestamp, sensor_state ? "NO" : "YES");
        if (fprintf(log_file, "%s", log_line) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
        }
        fflush(log_file);

        // Print a simulated fire alarm if a flame is detected
        if (sensor_state == 0) {
            printf("FLAME DETECTED!\n");
        }

        // Sleep for the specified interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Close the log file
    if (log_file) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    return EXIT_SUCCESS;
}

