#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x53
#define REG_X_LSB 0x28
#define REG_X_MSB 0x29
#define REG_Y_LSB 0x2A
#define REG_Y_MSB 0x2B
#define REG_Z_LSB 0x2C
#define REG_Z_MSB 0x2D
#define CSV_FILE "vibration_log.csv"
#define MAX_SAMPLES 10000
#define SAMPLE_INTERVAL_MS 100

static int i2c_fd = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t should_exit = 0;

void sigint_handler(int signum) {
    should_exit = 1;
}

int main() {
    struct timespec sleep_time = {0, SAMPLE_INTERVAL_MS * 1000000};
    struct tm *timeinfo;
    char timestamp[20];
    int x, y, z;
    int sample_count = 0;

    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
