#include <time.h>
#include <gpiod.h>

#define LOG_FILE "conveyor_log.txt"
#define GPIO17 17
#define GPIO27 27
#define LOG_INTERVAL_MS 50
#define MAX_LOG_ENTRIES 1000

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int sig) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    struct timespec ts;
    char log_entry[MAX_LOG_ENTRIES][100];
    int log_index = 0;
    FILE *log_file;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    line1 = gpiod_chip_get_line(chip, GPIO17);
    if (!line1) {
        perror("Failed to request line 17");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line2 = gpiod_chip_get_line(chip, GPIO27);
    if (!line2) {
        perror("Failed to request line 27");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Configure lines as inputs with internal pull-ups
    ret = gpiod_line_request_input(line1, "conveyor_log", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret) {
        perror("Failed to request line 17 as input");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_input(line2, "conveyor_log", GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
    if (ret) {
        perror("Failed to request line 27 as input");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!should_exit) {
        // Read sensor states
        int state1 = gpiod_line_get_value(line1);
        int state2 = gpiod_line_get_value(line2);

        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &ts);
        struct tm *timeinfo = localtime(&ts.tv_sec);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log entry
        snprintf(log_entry[log_index], sizeof(log_entry[log_index]), "%s, %d, %d\n", time_str, state1, state2);
        log_index = (log_index + 1) % MAX_LOG_ENTRIES;

        // Write log entry to file
        if (fputs(log_entry[log_index - 1], log_file) == EOF) {
            perror("Failed to write to log file");
        }

        // Sleep for LOG_INTERVAL_MS
        usleep(LOG_INTERVAL_MS * 1000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

