#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1_REG 0x2A
#define DATA_REG1 0x01
#define DATA_REG2 0x02
#define DATA_REG3 0x03
#define DATA_REG4 0x04
#define DATA_REG5 0x05
#define DATA_REG6 0x06
#define SAMPLE_RATE 100  // 100 Hz

static int i2c_fd = -1;
static FILE *fall_log = NULL;

static void sig_handler(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (fall_log != NULL) {
        fclose(fall_log);
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Verify WHO_AM_I register
    uint8_t who_am_i;
    if (read(i2c_fd, &who_am_i, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (who_am_i != 0x2A) {
        fprintf(stderr, "Error: WHO_AM_I register does not match expected value (0x2A)\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize sensor
    uint8_t ctrl_reg1 = 0x00;  // Standby mode
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("Failed to write CTRL_REG1 register");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ctrl_reg1 |= 0x01;  // Data rate 100 Hz
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("Failed to write CTRL_REG1 register");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    ctrl_reg1 |= 0x01;  // Active mode
    if (write(i2c_fd, &ctrl_reg1, 1) != 1) {
        perror("Failed to write CTRL_REG1 register");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    fall_log = fopen("fall_log.txt", "a");
    if (fall_log == NULL) {
        perror("Failed to open fall_log.txt");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    struct timespec sleep_time = {0, 10000000};  // 10 ms
    while (1) {
        uint8_t data[6];
        if (read(i2c_fd, data, 6) != 6) {
            perror("Failed to read accelerometer data");
            continue;
        }

        // Combine MSB/LSB and right-shift by 4 to form signed 12-bit values
        int16_t x = (data[0] << 4) | (data[1] >> 4);
        int16_t y = (data[2] << 4) | (data[3] >> 4);
        int16_t z = (data[4] << 4) | (data[5] >> 4);

        // Compute tilt angle of the X-axis relative to gravity
        double angle = atan2(x, sqrt(y * y + z * z)) * 180.0 / M_PI;

        // Check if tilt angle exceeds 45 degrees
        if (fabs(angle) > 45.0) {
            // Log timestamped line containing the raw 12-bit X, Y, Z values
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(fall_log, "%s, %d, %d, %d\n", timestamp, x, y, z);
            fflush(fall_log);
        }

        // Sleep for 10 ms
        nanosleep(&sleep_time, NULL);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(fall_log);

    return 0;
}

