#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <math.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x0C
#define CTRL_REG3 0x00
#define STATUS_REG 0x27
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define MAG_CAL_X 0.00015f // Example calibration constants
#define MAG_CAL_Y 0.00012f
#define MAG_CAL_Z 0.00013f
#define MAG_SCALE 0.146f // +-4 gauss sensitivity in mG/LSB

static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t should_exit = 0;

void signal_handler(int sig) {
    should_exit = 1;
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(uint8_t reg, const uint8_t *data, size_t len) {
    int ret;
    struct i2c_msg msgs[1];
    struct i2c_rdwr_ioctl_data msgset;

    msgs[0].addr = I2C_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = len + 1;
    msgs[0].buf = (uint8_t *)malloc(msgs[0].len);
    msgs[0].buf[0] = reg;
    memcpy(msgs[0].buf + 1, data, len);

    msgset.msgs = msgs;
    msgset.nmsgs = 1;

