    msgs[0].addr = I2C_ADDR;
    msgs[0].flags = I2C_M_RD;
    msgs[0].len = len;
    msgs[0].buf = data;

    msgset.msgs = msgs;
    msgset.nmsgs = 1;

    ret = ioctl(i2c_fd, I2C_RDWR, &msgset);
    if (ret < 0) {
        perror("I2C read");
        return -1;
    }

    return 0;
}

