#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define RESET_REG 0x1F
#define POWER_CTL 0x2D
#define STATUS 0x04
#define PARTID 0x01
#define XDATA 0x08
#define YDATA 0x0B
#define ZDATA 0x0E
#define MAX_RETRIES 5
#define LOG_FILE "vibration_log.txt"

static int spi_handle;
static FILE *log_file;
static volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int sig) {
    exit_flag = 1;
}

void log_data(int x, int y, int z) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    fprintf(log_file, "%ld.%09ld, %d, %d, %d\n", ts.tv_sec, ts.tv_nsec, x, y, z);
}

void spi_read(int reg, int *data) {
    int retries = MAX_RETRIES;
    while (retries--) {
        if (gpio SpiXfer(spi_handle, reg | 0x80 | 0x40, data, 3) == 3) {
            return;
        }
        usleep(1000);
    }
    fprintf(stderr, "SPI read failed for register 0x%02X\n", reg);
    exit(EXIT_FAILURE);
}

void spi_write(int reg, int data) {
    if (gpio SpiXfer(spi_handle, reg | 0x80, &data, 1) != 1) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg);
        exit(EXIT_FAILURE);
    }
}

void reset_sensor() {
    spi_write(RESET_REG, 0x52);
    usleep(1000);
    spi_write(POWER_CTL, 0x00);
    while (!(gpio SpiXfer(spi_handle, STATUS, NULL, 1) & 0x08)) {
        usleep(1000);
    }
    spi_write(POWER_CTL, 0x01);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(SPI_CHANNEL, PI_OUTPUT)) {
        fprintf(stderr, "Failed to set SPI mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(SPI_CHANNEL, PI_PUD_UP)) {
        fprintf(stderr, "Failed to set SPI pull-up\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(SPI_CHANNEL, PI_ALT0)) {
        fprintf(stderr, "Failed to set SPI alternate function\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSpiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioSpiClose(spi_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    reset_sensor();

    if (gpioRead(PARTID) != 0x1D) {
        fprintf(stderr, "Sensor not detected\n");
        fclose(log_file);
        gpioSpiClose(spi_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    while (!exit_flag) {
        int x, y, z;
        spi_read(XDATA, &x);
        spi_read(YDATA, &y);
        spi_read(ZDATA, &z);
        log_data(x, y, z);
        usleep(100000);
    }

    fclose(log_file);
    gpioSpiClose(spi_handle);
    gpioTerminate();

    return 0;
}

