This C program initializes the Raspberry Pi 4 Model B to communicate with an Analog Devices ADXL354B accelerometer over SPI channel 0. It handles SPI communication errors with retries, checks sensor presence by reading the PARTID register, and logs X, Y, and Z axis readings with timestamps every 100 ms to a file named 'vibration_log.txt'. The program also implements graceful shutdown via SIGINT/SIGTERM with proper resource cleanup.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_BAUDRATE 1000000
#define SPI_MODE 3
#define REG_X_GYRO 0x04
#define REG_Y_GYRO 0x06
#define REG_Z_GYRO 0x08
#define REG_X_ACCL 0x0A
#define REG_Y_ACCL 0x0C
#define REG_Z_ACCL 0x0E
#define LOG_FILE "imu_log.csv"
#define MAX_READS 1000000
#define DELAY_MS 10

static volatile sig_atomic_t should_exit = 0;

void signal_handler(int signum) {
    should_exit = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUDRATE, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    for (int i = 0; i < MAX_READS && !should_exit; i++) {
        struct timespec sleep_time = {0, DELAY_MS * 1000000};
        nanosleep(&sleep_time, NULL);

        uint8_t reg_address = 0x80 | REG_X_GYRO; // MSB set for read
        uint8_t dummy_byte = 0x00;
        uint16_t data[6];

        // Read X_GYRO
        if (spiXfer(spi_handle, &reg_address, &dummy_byte, 2) < 0) {
            fprintf(stderr, "SPI read failed for X_GYRO\n");
            continue;
        }
        if (spiXfer(spi_handle, &reg_address, data, 2) < 0) {
            fprintf(stderr, "SPI read failed for X_GYRO\n");
            continue;
        }

        // Read Y_GYRO
        if (spiXfer(spi_handle, &reg_address, &dummy_byte, 2) < 0) {
            fprintf(stderr, "SPI read failed for Y_GYRO\n");
            continue;
        }
        if (spiXfer(spi_handle, &reg_address, data + 2, 2) < 0) {
            fprintf(stderr, "SPI read failed for Y_GYRO\n");
            continue;
        }

        // Read Z_GYRO
        if (spiXfer(spi_handle, &reg_address, &dummy_byte, 2) < 0) {
            fprintf(stderr, "SPI read failed for Z_GYRO\n");
            continue;
        }
        if (spiXfer(spi_handle, &reg_address, data + 4, 2) < 0) {
            fprintf(stderr, "SPI read failed for Z_GYRO\n");
            continue;
        }

        // Read X_ACCL
        if (spiXfer(spi_handle, &reg_address, &dummy_byte, 2) < 0) {
            fprintf(stderr, "SPI read failed for X_ACCL\n");
            continue;
        }
        if (spiXfer(spi_handle, &reg_address, data + 6, 2) < 0) {
            fprintf(stderr, "SPI read failed for X_ACCL\n");
            continue;
        }

        // Read Y_ACCL
        if (spiXfer(spi_handle, &reg_address, &dummy_byte, 2) < 0) {
            fprintf(stderr, "SPI read failed for Y_ACCL\n");
            continue;
        }
        if (spiXfer(spi_handle, &reg_address, data + 8, 2) < 0) {
            fprintf(stderr, "SPI read failed for Y_ACCL\n");
            continue;
        }

        // Read Z_ACCL
        if (spiXfer(spi_handle, &reg_address, &dummy_byte, 2) < 0) {
            fprintf(stderr, "SPI read failed for Z_ACCL\n");
            continue;
        }
        if (spiXfer(spi_handle, &reg_address, data + 10, 2) < 0) {
            fprintf(stderr, "SPI read failed for Z_ACCL\n");
            continue;
        }

        // Convert to degrees/second and g
        double x_gyro = (double)data[0] * 0.05;
        double y_gyro = (double)data[2] * 0.05;
        double z_gyro = (double)data[4] * 0.05;
        double x_accel = (double)data[6] * 0.0025;
        double y_accel = (double)data[8] * 0.0025;
        double z_accel = (double)data[10] * 0.0025;

        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        // Calculate timestamp
        uint64_t timestamp = (current_time.tv_sec - start_time.tv_sec) * 1000000000 + current_time.tv_nsec;

        // Log the data
        fprintf(log_file, "%llu,%f,%f,%f,%f,%f,%f\n", timestamp, x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel);
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

