#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_17 17
#define GPIO_LINE_27 27
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t should_exit = 0;

void handle_sigint(int signum) {
    should_exit = 1;
}

int main() {
    const char *chip_name = GPIO_CHIP_NAME;
    const int line_17 = GPIO_LINE_17;
    const int line_27 = GPIO_LINE_27;
    struct gpiod_chip *chip;
    struct gpiod_line *line_17_line, *line_27_line;
    struct gpiod_line_bulk *bulk;
    unsigned int values[2];
    struct timespec sleep_time;
    int ret;

    // Register signal handler for SIGINT
    signal(SIGINT, handle_sigint);

    // Open the gpiochip
    chip = gpiod_chip_open(chip_name);
    if (!chip) {
        perror("Failed to open gpiochip");
        exit(EXIT_FAILURE);
    }

    // Request lines 17 and 27 for input
    line_17_line = gpiod_chip_get_line(chip, line_17);
    if (!line_17_line) {
        perror("Failed to get line 17");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    line_27_line = gpiod_chip_get_line(chip, line_27);
    if (!line_27_line) {
        perror("Failed to get line 27");
        gpiod_line_release(line_17_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request both lines together for input
    bulk = gpiod_line_request_bulk(chip, "obstacle_avoidance", line_17_line, line_27_line);
    if (!bulk) {
        perror("Failed to request lines");
        gpiod_line_release(line_17_line);
        gpiod_line_release(line_27_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set the direction of the lines to input
    ret = gpiod_line_set_direction_bulk(bulk, GPIOD_LINE_DIRECTION_INPUT);
    if (ret) {
        perror("Failed to set line direction");
        gpiod_line_release_bulk(bulk);
        gpiod_line_release(line_17_line);
        gpiod_line_release(line_27_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set the edge detection for both lines to rising edge
    ret = gpiod_line_set_edge_detection_bulk(bulk, GPIOD_LINE_EDGE_RISING);
    if (ret) {
        perror("Failed to set edge detection");
        gpiod_line_release_bulk(bulk);
        gpiod_line_release(line_17_line);
        gpiod_line_release(line_27_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!should_exit) {
        // Read the values of both lines
        ret = gpiod_line_request_get_values(bulk, values);
        if (ret) {
            perror("Failed to read line values");
            gpiod_line_release_bulk(bulk);
            gpiod_line_release(line_17_line);
            gpiod_line_release(line_27_line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Log the obstacle detection status
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        printf("%s: Line 17: %d, Line 27: %d\n", timestamp, values[0], values[1]);

        // Sleep for 100 ms
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = POLL_INTERVAL_MS * 1000000;
        nanosleep(&sleep_time, NULL);
    }

    // Release resources
    gpiod_line_release_bulk(bulk);
    gpiod_line_release(line_17_line);
    gpiod_line_release(line_27_line);
    gpiod_chip_close(chip);

    return 0;
}

