code:
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <libgpiod.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED_HZ 1000000
#define SCALE_FACTOR 0.02
#define LOG_INTERVAL_MS 100

static int spi_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *cs_line;
static struct spi_ioc_transfer xfer[2];
static uint8_t tx[2];
static int16_t rx[2];
static int running = 1;

static void sigint_handler(int signum) {
    running = 0;
}

int main() {
    int ret;

    // Register signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request the CS line
    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("Failed to get CS line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the CS line as output
    ret = gpiod_line_request_output(cs_line, "spi_cs", 0);
    if (ret) {
        perror("Failed to request CS line as output");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Initialize SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Enable data ready mode
    tx[0] = 0x24; // MSC_CTRL register address
    tx[1] = 0x01; // Enable data ready mode
    ret = write(spi_fd, tx, 2);
    if (ret != 2) {
        perror("Failed to write to MSC_CTRL register");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Set CS line low
        ret = gpiod_line_set_value(cs_line, 0);
        if (ret) {
            perror("Failed to set CS line low");
            close(spi_fd);
            gpiod_line_release(cs_line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Send address with MSB set
        tx[0] = 0x04 | 0x80; // X-axis angular rate register address
        tx[1] = 0x06 | 0x80; // Y-axis angular rate register address
        tx[2] = 0x08 | 0x80; // Z-axis angular rate register address
        ret = write(spi_fd, tx, 3);
        if (ret != 3) {
            perror("Failed to send address with MSB set");
            close(spi_fd);
            gpiod_line_release(cs_line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Read 2 bytes from each register
        xfer[0].tx_buf = (unsigned long)tx;
        xfer[0].rx_buf = (unsigned long)rx;
        xfer[0].len = 3;
        xfer[0].speed_hz = SPI_SPEED_HZ;
        xfer[0].bits_per_word = 8;
        xfer[0].delay_usecs = 0;
        xfer[0].cs_change = 1;

        xfer[1].tx_buf = (unsigned long)tx;
        xfer[1].rx_buf = (unsigned long)rx;
        xfer[1].len = 3;
        xfer[1].speed_hz = SPI_SPEED_HZ;
        xfer[1].bits_per_word = 8;
        xfer[1].delay_usecs = 0;
        xfer[1].cs_change = 1;

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE, xfer);
        if (ret < 0) {
            perror("Failed to read from SPI device");
            close(spi_fd);
            gpiod_line_release(cs_line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Set CS line high
        ret = gpiod_line_set_value(cs_line, 1);
        if (ret) {
            perror("Failed to set CS line high");
            close(spi_fd);
            gpiod_line_release(cs_line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Convert raw 16-bit signed values to angular rates
        int16_t x_rate = (int16_t)((rx[0] << 8) | rx[1]);
        int16_t y_rate = (int16_t)((rx[2] << 8) | rx[3]);
        int16_t z_rate = (int16_t)((rx[4] << 8) | rx[5]);

        // Log the results
        printf("X: %d deg/sec, Y: %d deg/sec, Z: %d deg/sec\n", x_rate * SCALE_FACTOR, y_rate * SCALE_FACTOR, z_rate * SCALE_FACTOR);

        // Sleep for 100 ms
        usleep(LOG_INTERVAL_MS * 1000);
    }

    // Clean up resources
    close(spi_fd);
