        gpioTerminate();
        return 1;
    }

    uint8_t who_am_i;
    if (i2cReadByte(i2c_handle, WHO_AM_I_REG, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I register does not match expected value\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByte(i2c_handle, CTRL1_XL_REG, 0x42) < 0) {
        fprintf(stderr, "Failed to write CTRL1_XL register\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

