        double gyro_y_dps = gyro_y * 0.00875;
        double gyro_z_dps = gyro_z * 0.00875;
        double accel_x_g = accel_x * 0.000061;
        double accel_y_g = accel_y * 0.000061;
        double accel_z_g = accel_z * 0.000061;

        printf("Gyro: X=%f, Y=%f, Z=%f\n", gyro_x_dps, gyro_y_dps, gyro_z_dps);
        printf("Accel: X=%f, Y=%f, Z=%f\n", accel_x_g, accel_y_g, accel_z_g);

        usleep(100000); // 100 ms
    }

    i2cHandleClose(i2c_handle);
    gpioTerminate();
    return 0;
}

int i2cHandleOpen(int *handle, uint8_t addr, int bus) {
    *handle = i2cOpen(bus, addr, 0);
    if (*handle < 0) {
        return -1;
    }
    return 0;
}

void i2cHandleClose(int handle) {
    i2cClose(handle);
}

int i2cReadByte(int handle, uint8_t reg, uint8_t *data) {
    int result = i2cReadReg8(handle, reg, data);
    if (result < 0) {
        fprintf(stderr, "Failed to read byte from register 0x%02X\n", reg);
    }
    return result;
}

int i2cReadBytes(int handle, uint8_t reg, int count, uint8_t *data) {
    int result = i2cReadRegs8(handle, reg, count, data);
    if (result < 0) {
        fprintf(stderr, "Failed to read %d bytes from register 0x%02X\n", count, reg);
    }
    return result;
}

