#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define WHO_AM_I_VALUE 0xC7
#define CTRL_REG1 0x2A
#define CTRL_REG2 0x2B
#define M_CTRL_REG1 0x5B
#define M_CTRL_REG2 0x5C
#define OUT_X_MSB 0x01

static int i2c_handle;
static volatile sig_atomic_t exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (i2cHandleOpen(&i2c_handle, I2C_BUS, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        gpioTerminate();
        return 1;
    }

    if (readWhoAmI(i2c_handle) != WHO_AM_I_VALUE) {
        fprintf(stderr, "Failed to detect FXOS8700\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (configureSensor(i2c_handle) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        i2cHandleClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!exit_flag) {
        if (readSensorData(i2c_handle) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue;
        }
        usleep(100000); // Sleep for 100 ms
    }

    i2cHandleClose(i2c_handle);
    gpioTerminate();
    return 0;
}

int readWhoAmI(int i2c_handle) {
    uint8_t data[1];
    if (i2cReadByte(i2c_handle, WHO_AM_I_REG, data) < 0) {
        return -1;
    }
    return data[0];
}

int configureSensor(int i2c_handle) {
    uint8_t data[2];
    data[0] = 0x01; // Enable accelerometer and magnetometer
    data[1] = 0x00; // Set accelerometer range to ±2g and magnetometer range to ±12 gauss
    if (i2cWriteBlockData(i2c_handle, CTRL_REG1, data, 2) < 0) {
        return -1;
    }
    data[0] = 0x00; // Enable accelerometer and magnetometer
    data[1] = 0x00; // Set accelerometer range to ±2g and magnetometer range to ±12 gauss
    if (i2cWriteBlockData(i2c_handle, CTRL_REG2, data, 2) < 0) {
        return -1;
    }
    data[0] = 0x00; // Enable accelerometer and magnetometer
    data[1] = 0x00; // Set accelerometer range to ±2g and magnetometer range to ±12 gauss
    if (i2cWriteBlockData(i2c_handle, M_CTRL_REG1, data, 2) < 0) {
        return -1;
    }
    data[0] = 0x00; // Enable accelerometer and magnetometer
    data[1] = 0x00; // Set accelerometer range to ±2g and magnetometer range to ±12 gauss
    if (i2cWriteBlockData(i2c_handle, M_CTRL_REG2, data, 2) < 0) {
        return -1;
    }
    return 0;
}

int readSensorData(int i2c_handle) {
    uint8_t data[12];
    if (i2cReadBlockData(i2c_handle, OUT_X_MSB, data, 12) < 0) {
        return -1;
    }
    int16_t accel_x = (data[0] << 8) | data[1];
    int16_t accel_y = (data[2] << 8) | data[3];
    int16_t accel_z = (data[4] << 8) | data[5];
    int16_t mag_x = (data[6] << 8) | data[7];
    int16_t mag_y = (data[8] << 8) | data[9];
    int16_t mag_z = (data[10] << 8) | data[11];
    printf("Accel: X=%d, Y=%d, Z=%d\n", accel_x, accel_y, accel_z);
    printf("Mag: X=%d, Y=%d, Z=%d\n", mag_x, mag_y, mag_z);
    return 0;
}

int i2cHandleOpen(int *handle, int bus, int addr) {
    *handle = i2cOpen(bus, addr, 0);
    if (*handle < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        return -1;
    }
    return 0;
}

int i2cHandleClose(int handle) {
    if (i2cClose(handle) < 0) {
        fprintf(stderr, "Failed to close I2C handle\n");
        return -1;
    }
    return 0;
}

int i2cReadByte(int handle, int reg, uint8_t *data) {
    if (i2cReadByteData(handle, reg, data) < 0) {
        fprintf(stderr, "Failed to read byte from I2C\n");
        return -1;
    }
    return 0;
}

int i2cWriteBlockData(int handle, int reg, const uint8_t *data, int length) {
    if (i2cWriteBlockData(handle, reg, data, length) < 0) {
        fprintf(stderr, "Failed to write block data to I2C\n");
        return -1;
    }
    return 0;
}

