#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <math.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define X_REG 0x32
#define Y_REG 0x33
#define Z_REG 0x34
#define THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"

static int i2c_fd;
static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

void log_tilt_event(double x, double y, double z) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(log, "%s: X=%f, Y=%f, Z=%f\n", timestamp, x, y, z);
    fclose(log);
}

void read_accelerometer() {
    uint8_t data[6];
    int ret;

    ret = ioctl(i2c_fd, I2C_RDWR, 1);
    if (ret < 0) {
        perror("Failed to start I2C transaction");
        return;
    }

    ret = write(i2c_fd, &ADXL345_ADDR, 1);
    if (ret < 0) {
        perror("Failed to write address to I2C");
        return;
    }

    ret = read(i2c_fd, data, 6);
    if (ret < 0) {
        perror("Failed to read data from I2C");
        return;
    }

    int16_t x = (data[1] << 8) | data[0];
    int16_t y = (data[3] << 8) | data[2];
    int16_t z = (data[5] << 8) | data[4];

    double x_g = x / 256.0;
    double y_g = y / 256.0;
    double z_g = z / 256.0;

    double angle_x = atan2(y_g, z_g) * 180.0 / M_PI;
    double angle_y = atan2(-x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0 / M_PI;

    if (fabs(angle_x) > THRESHOLD || fabs(angle_y) > THRESHOLD) {
        log_tilt_event(angle_x, angle_y, z_g);
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    int ret = ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        read_accelerometer();
        usleep(100000); // Sleep for 100 ms
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

