#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define THRESHOLD_ARG 1
#define THRESHOLD_MIN 1
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_DURATION_MS 5000
#define MAX_SAMPLES 5000

static volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold;
    if (sscanf(argv[THRESHOLD_ARG], "%d", &threshold) != 1 || threshold <= THRESHOLD_MIN) {
        fprintf(stderr, "Error: Threshold must be a positive integer.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio.\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO mode.\n");
        gpioTerminate();
        return 1;
    }

    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        int high_count = 0;
        clock_gettime(CLOCK_MONOTONIC, &current_time);

        while (difftime(current_time.tv_sec, start_time.tv_sec) * 1000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000000 < WINDOW_DURATION_MS) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            usleep(SAMPLE_INTERVAL_MS * 1000);
        }

        if (high_count >= threshold) {
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&start_time.tv_sec));
            printf("%s ALERT: %d high readings in %d ms\n", timestamp, high_count, WINDOW_DURATION_MS);
        } else {
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&start_time.tv_sec));
            printf("%s Normal: %d high readings in %d ms\n", timestamp, high_count, WINDOW_DURATION_MS);
        }

        start_time.tv_sec += WINDOW_DURATION_MS / 1000;
        start_time.tv_nsec += (WINDOW_DURATION_MS % 1000) * 1000000;
        if (start_time.tv_nsec >= 1000000000) {
            start_time.tv_nsec -= 1000000000;
            start_time.tv_sec++;
        }

        sleep(1);
    }

    gpioTerminate();
    return 0;
}

