#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO17 17
#define GPIO27 27
#define MAX_CODE_LENGTH 7
#define LOG_FILE "access_log.txt"

volatile sig_atomic_t exit_flag = 0;

void sig_handler(int sig) {
    exit_flag = 1;
}

int main() {
    // Initialize GPIO
    struct gpiod_chip *chip;
    struct gpiod_line *line17, *line27;
    int ret;

    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Get lines
    line17 = gpiod_chip_get_line(chip, GPIO17);
    line27 = gpiod_chip_get_line(chip, GPIO27);
    if (!line17 || !line27) {
        fprintf(stderr, "Failed to get GPIO lines\n");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request lines for output
    ret = gpiod_line_request_output(line17, "Door A", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO17);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line27, "Door B", 0);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO27);
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize random number generator
    srand(time(NULL));

    // Generate random 6-digit code
    char code[MAX_CODE_LENGTH];
    snprintf(code, MAX_CODE_LENGTH, "%06d", rand() % 900000 + 100000);
    printf("Security code: %s\n", code);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!exit_flag) {
        char input[MAX_CODE_LENGTH];
        printf("Enter the security code: ");
        if (fgets(input, MAX_CODE_LENGTH, stdin) != NULL) {
            // Remove newline character if present
            size_t len = strlen(input);
            if (len > 0 && input[len - 1] == '\n') {
                input[len - 1] = '\0';
            }

            // Check if input is a valid 6-digit number
            if (strlen(input) == 6 && input[0] >= '0' && input[0] <= '9') {
                for (size_t i = 1; i < 6; i++) {
                    if (input[i] < '0' || input[i] > '9') {
                        fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
                        continue;
                    }
                }

                // Compare input with generated code
                if (strcmp(input, code) == 0) {
                    // Unlock Door A
                    gpiod_line_set_value(line17, 1);
                    printf("Door A unlocked.\n");

                    // Wait for 5 seconds
                    sleep(5);

                    // Lock Door A
                    gpiod_line_set_value(line17, 0);
                    printf("Door A locked.\n");

                    // Log successful entry
                    time_t now = time(NULL);
                    struct tm *tm = localtime(&now);
                    char log_entry[100];
                    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S,%06d", tm, rand() % 900000 + 100000);
                    fprintf(log_file, "%s\n", log_entry);

                    // Generate new random code
                    snprintf(code, MAX_CODE_LENGTH, "%06d", rand() % 900000 + 100000);
                    printf("New security code: %s\n", code);
                } else {
                    printf("Access denied.\n");
                }
            } else {
                fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
            }
        }
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line17);
    gpiod_line_release(line27);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

