#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define ONE_TIME_HIGH_RES_MODE_2 0x21
#define MAX_CONVERSION_TIME 180
#define LOG_FILE "light_log.txt"

static int i2c_fd;
static struct gpiod_chip *chip;
static struct gpiod_line *gpio;

void log_illuminance(double lux) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log, "%s, Lux: %.2f\n", timestamp, lux);
    fclose(log);
}

void handle_signal(int signum) {
    if (signum == SIGINT) {
        printf("Interrupted by user, cleaning up...\n");
        close(i2c_fd);
        gpiod_chip_close(chip);
        gpio_free(gpio);
        exit(0);
    }
}

int main() {
    // Set up signal handling
    signal(SIGINT, handle_signal);

    // Initialize GPIO for I2C
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }
    gpio = gpiod_chip_get_line(chip, 2);
    if (gpio == NULL) {
        perror("Failed to get GPIO line 2");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(gpio, "I2C SDA", 0) < 0) {
        perror("Failed to request GPIO line 2 as output");
        gpiod_chip_close(chip);
        gpio_free(gpio);
        return 1;
    }
    gpio = gpiod_chip_get_line(chip, 3);
    if (gpio == NULL) {
        perror("Failed to get GPIO line 3");
        gpiod_chip_close(chip);
        gpio_free(gpio);
        return 1;
    }
    if (gpiod_line_request_output(gpio, "I2C SCL", 0) < 0) {
        perror("Failed to request GPIO line 3 as output");
        gpiod_chip_close(chip);
        gpio_free(gpio);
        return 1;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpiod_chip_close(chip);
        gpio_free(gpio);
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        gpiod_chip_close(chip);
        gpio_free(gpio);
        return 1;
    }

    // Write One-Time High-Resolution Mode 2 command
    if (write(i2c_fd, &ONE_TIME_HIGH_RES_MODE_2, 1) != 1) {
        perror("Failed to write command to sensor");
        close(i2c_fd);
        gpiod_chip_close(chip);
        gpio_free(gpio);
        return 1;
    }

    // Wait for conversion time
    usleep(MAX_CONVERSION_TIME * 1000);

    // Read 2 bytes of data
    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read data from sensor");
        close(i2c_fd);
        gpiod_chip_close(chip);
        gpio_free(gpio);
        return 1;
    }

    // Calculate illuminance in lux
    double lux = (data[0] << 8) | data[1];
    lux = lux * 5.0 / 6.0;

    // Log the illuminance
    log_illuminance(lux);

    // Close I2C bus and GPIO
    close(i2c_fd);
    gpiod_chip_close(chip);
    gpio_free(gpio);

    return 0;
}

