#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <mpir.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define PWM_PIN 18
#define SAMPLE_RATE 5000 // 5000 samples per second
#define SAMPLE_INTERVAL 20 // 20 ms between samples
#define MAX_ELECTRODES 12
#define LOG_FILE "frequency_log.txt"
#define SECRET_KEY "MySecretKey"
#define MOTION_DETECTED "MOTION_DETECTED:"

static int gpiod_handle;
static int i2c_handle;
static int socket_fd;
static int pwm_handle;
static int running = 1;

void handle_sigint(int signum) {
    running = 0;
    gpioPWMWrite(pwm_handle, 0);
    gpioTerminate();
    close(i2c_handle);
    close(socket_fd);
    printf("Exiting...\n");
    exit(0);
}

void log_frequency(double frequency) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%.2f\n", frequency);
    fclose(log_file);
}

void play_tone(double frequency) {
    int duty_cycle = (int)(1000000.0 / frequency);
    gpioPWMWrite(pwm_handle, duty_cycle);
}

void read_mpr121() {
    uint8_t data[12];
    if (i2cReadData(i2c_handle, 0x00, data, 12) != 12) {
        perror("Failed to read MPR121 data");
        return;
    }
    for (int i = 0; i < MAX_ELECTRODES; i++) {
        int electrode_data = (data[i * 2] << 8) | data[i * 2 + 1];
        if (electrode_data > 0) {
            double frequency = 220.0 * pow(2.0, (electrode_data - 1) / 1023.0 * 12.0);
            log_frequency(frequency);
            play_tone(frequency);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return 1;
    }
    gpiod_handle = gpioOpen(0, 0);
    if (gpiod_handle < 0) {
        perror("Failed to open gpiod handle");
        gpioTerminate();
        return 1;
    }
    pwm_handle = gpioPWM(PWM_PIN, 0);
    if (pwm_handle < 0) {
        perror("Failed to initialize PWM");
        gpioTerminate();
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        perror("Failed to open I2C device");
        gpioTerminate();
        return 1;
    }
    if (i2cWriteData(i2c_handle, 0x80, 0x01) != 1) {
        perror("Failed to reset MPR121");
        gpioTerminate();
        close(i2c_handle);
        return 1;
    }
    if (i2cWriteData(i2c_handle, 0x80, 0x02) != 1) {
        perror("Failed to configure MPR121");
        gpioTerminate();
        close(i2c_handle);
        return 1;
    }
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(12345);
    server_addr.sin_addr.s_addr = INADDR_ANY;
    if (bind(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind socket");
        gpioTerminate();
        close(i2c_handle);
        close(socket_fd);
        return 1;
    }
    if (listen(socket_fd, 5) < 0) {
        perror("Failed to listen on socket");
        gpioTerminate();
        close(i2c_handle);
        close(socket_fd);
        return 1;
    }
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);
    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(socket_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            perror("Failed to accept connection");
            continue;
        }
        char buffer[1024];
        ssize_t bytes_read = read(client_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read < 0) {
            perror("Failed to read from client");
            close(client_fd);
            continue;
        }
        buffer[bytes_read] = '\0';
        if (strncmp(buffer, MOTION_DETECTED, strlen(MOTION_DETECTED)) == 0) {
            char *secret = strtok(buffer + strlen(MOTION_DETECTED), " ");
            if (secret != NULL && strcmp(secret, SECRET_KEY) == 0) {
                for (int i = 0; i < SAMPLE_RATE / SAMPLE_INTERVAL; i++) {
                    read_mpr121();
                    usleep(SAMPLE_INTERVAL * 1000);
                }
            }
        }
        close(client_fd);
    }
    gpioPWMWrite(pwm_handle, 0);
    gpioTerminate();
    close(i2c_handle);
    close(socket_fd);
    return 0;
}

