#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x1E
#define CONFIG_REG_A 0x70
#define CONFIG_REG_B 0x20
#define MODE_REG 0x00
#define AVG_SAMPLES 8
#define OUTPUT_RATE 15
#define GAIN 1.3
#define OFFSET_WINDOW 100
#define OFFSET_SAMPLE_RATE 500

static int i2c_handle;
static int offset_index = 0;
static float offsets[3][OFFSET_WINDOW];
static float offset_sum[3] = {0.0, 0.0, 0.0};
static float offset_avg[3] = {0.0, 0.0, 0.0};

void handle_signal(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Configure the HMC5883L
    uint8_t config_a = 0x70; // 8-sample averaging, 15 Hz output rate
    uint8_t config_b = 0x20; // Gain setting of 1.3 Gauss
    uint8_t mode = 0x00; // Continuous mode

    if (i2cWriteByteData(i2c_handle, CONFIG_REG_A, config_a) < 0) {
        fprintf(stderr, "Failed to write to CONFIG_REG_A\n");
        i2c_close(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, CONFIG_REG_B, config_b) < 0) {
        fprintf(stderr, "Failed to write to CONFIG_REG_B\n");
        i2c_close(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, MODE_REG, mode) < 0) {
        fprintf(stderr, "Failed to write to MODE_REG\n");
        i2c_close(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (1) {
        uint8_t data[6];
        if (i2cReadBlockData(i2c_handle, 0x03, data, 6) < 0) {
            fprintf(stderr, "Failed to read from HMC5883L\n");
            continue;
        }

        // Convert raw data to signed 16-bit values
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        // Compute hard-iron offsets
        offset_sum[0] += x;
        offset_sum[1] += y;
        offset_sum[2] += z;
        if (offset_index < OFFSET_WINDOW) {
            offset_index++;
        } else {
            offset_avg[0] = offset_sum[0] / OFFSET_WINDOW;
            offset_avg[1] = offset_sum[1] / OFFSET_WINDOW;
            offset_avg[2] = offset_sum[2] / OFFSET_WINDOW;
            offset_sum[0] = 0.0;
            offset_sum[1] = 0.0;
            offset_sum[2] = 0.0;
            offset_index = 0;
        }

        // Apply hard-iron offsets
        float x_offset = offset_avg[0];
        float y_offset = offset_avg[1];
        float z_offset = offset_avg[2];

        // Print offset-corrected values
        printf("X: %.2f, Y: %.2f, Z: %.2f\n", x - x_offset, y - y_offset, z - z_offset);

        // Wait for 500 ms
        usleep(OFFSET_SAMPLE_RATE * 1000);
    }

    i2c_close(i2c_handle);
    gpioTerminate();
    return 0;
}

