#define LSM303D_ADDRESS 0x1D
#define WHO_AM_I_REG 0x0F
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define INT1_CFG 0x2A
#define OUT_X_L_A 0x28
#define BUFFER_SIZE 64
#define INT1_PIN 23
#define INT1_LINE 0

static int i2c_fd;
static int gpio_fd;
static int buffer_index = 0;
static int buffer[BUFFER_SIZE];
static struct timespec last_interrupt_time;

void print_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

void read_accelerometer() {
    uint8_t data[6];
    if (i2c_smbus_read_i2c_block_data(i2c_fd, OUT_X_L_A, 6, data) != 6) {
        fprintf(stderr, "I2C read failed\n");
        return;
    }
    buffer[buffer_index] = (data[0] << 8) | data[1];
    buffer[buffer_index + 1] = (data[2] << 8) | data[3];
    buffer[buffer_index + 2] = (data[4] << 8) | data[5];
    buffer_index = (buffer_index + 3) % BUFFER_SIZE;
}

void handle_interrupt() {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);
    if (current_time.tv_sec - last_interrupt_time.tv_sec > 0) {
        printf("Timestamp: %ld.%09ld\n", current_time.tv_sec, current_time.tv_nsec);
        for (int i = 0; i < 10; i++) {
            printf("Sample %d: %d\n", i, buffer[(buffer_index + i) % BUFFER_SIZE]);
        }
    }
    last_interrupt_time = current_time;
}

int main() {
    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        print_error("Failed to open I2C device");
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDRESS) < 0) {
        print_error("Failed to set I2C slave address");
    }

    // Read WHO_AM_I register
    uint8_t who_am_i;
    if (i2c_smbus_read_byte_data(i2c_fd, WHO_AM_I_REG) != 0x49) {
        print_error("LSM303D not found");
    }

    // Configure accelerometer
    uint8_t ctrl_reg1 = 0x57; // 50 Hz ODR, all axes enabled
    uint8_t ctrl_reg4 = 0x00; // Full-scale +-2g, sensitivity 0.061 mg/LSB
    uint8_t int1_cfg = 0x2A; // Threshold interrupt on any-axis-high event
    uint8_t threshold = 0x7D; // 2000 mg threshold
    uint8_t duration = 0; // Immediate duration

    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1, ctrl_reg1) != 0) {
        print_error("Failed to write CTRL_REG1");
    }
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG4, ctrl_reg4) != 0) {
        print_error("Failed to write CTRL_REG4");
    }
    if (i2c_smbus_write_byte_data(i2c_fd, INT1_CFG, int1_cfg) != 0) {
        print_error("Failed to write INT1_CFG");
    }
    if (i2c_smbus_write_byte_data(i2c_fd, 0x2B, threshold) != 0) {
        print_error("Failed to write threshold");
    }
    if (i2c_smbus_write_byte_data(i2c_fd, 0x2C, duration) != 0) {
        print_error("Failed to write duration");
    }

    // Request GPIO interrupt line
    gpio_fd = gpiochip_open(0);
    if (gpio_fd < 0) {
        print_error("Failed to open GPIO chip");
    }
    struct gpiod_line_request req = {
        .line = INT1_PIN,
        .consumer = "lsm303d_mon",
        .request_type = GPIO_LINE_REQUEST_FLAG_EDGE_RISING,
    };
    if (gpiod_request_line(gpio_fd, &req) < 0) {
        print_error("Failed to request GPIO line");
    }

    // Poll accelerometer and handle interrupts
    struct timespec poll_interval = {0, 10000000}; // 10 ms
    struct timespec remaining;
    while (1) {
        read_accelerometer();
        nanosleep(&poll_interval, &remaining);
        if (gpiod_event_wait(gpio_fd, &remaining) < 0) {
            print_error("Failed to wait for GPIO event");
        }
        handle_interrupt();
    }

    // Disable accelerometer and clean up
    if (i2c_smbus_write_byte_data(i2c_fd, CTRL_REG1, 0x00) != 0) {
        print_error("Failed to disable accelerometer");
    }
    close(i2c_fd);
    gpiochip_close(gpio_fd);
    return 0;
}

