#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_1 17
#define GPIO_LINE_2 27
#define DELAY_MS 500

static volatile sig_atomic_t should_exit = 0;

void sig_handler(int signum) {
    should_exit = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line1, *line2;
    int ret;

    // Install signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP_NAME);
        return EXIT_FAILURE;
    }

    // Request lines with consumer labels
    line1 = gpiod_chip_get_line(chip, GPIO_LINE_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_LINE_1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_LINE_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_LINE_2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Set line direction to output
    ret = gpiod_line_request_output(line1, "solenoid1", 0);
    if (ret) {
        fprintf(stderr, "Failed to request line %d as output\n", GPIO_LINE_1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_request_output(line2, "solenoid2", 0);
    if (ret) {
        fprintf(stderr, "Failed to request line %d as output\n", GPIO_LINE_2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Drive both lines LOW
    ret = gpiod_line_set_value(line1, 0);
    if (ret) {
        fprintf(stderr, "Failed to set line %d to LOW\n", GPIO_LINE_1);
        gpiod_line_release(line2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    ret = gpiod_line_set_value(line2, 0);
    if (ret) {
        fprintf(stderr, "Failed to set line %d to LOW\n", GPIO_LINE_2);
        gpiod_line_release(line2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    while (!should_exit) {
        // Energize solenoid 1 for 500 ms
        ret = gpiod_line_set_value(line1, 1);
        if (ret) {
            fprintf(stderr, "Failed to set line %d to HIGH\n", GPIO_LINE_1);
            break;
        }
        nanosleep(&(struct timespec){0, DELAY_MS * 1000000}, NULL);

        // De-energize solenoid 1 and energize solenoid 2 for 500 ms
        ret = gpiod_line_set_value(line1, 0);
        if (ret) {
            fprintf(stderr, "Failed to set line %d to LOW\n", GPIO_LINE_1);
            break;
        }
        ret = gpiod_line_set_value(line2, 1);
        if (ret) {
            fprintf(stderr, "Failed to set line %d to HIGH\n", GPIO_LINE_2);
            break;
        }
        nanosleep(&(struct timespec){0, DELAY_MS * 1000000}, NULL);

        // De-energize solenoid 2
        ret = gpiod_line_set_value(line2, 0);
        if (ret) {
            fprintf(stderr, "Failed to set line %d to LOW\n", GPIO_LINE_2);
            break;
        }
    }

    // Release lines and close chip
    gpiod_line_release(line2);
    gpiod_line_release(line1);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

