This C program uses the libgpiod library to control two 12V DC push-pull solenoids on a Raspberry Pi 3 Model B+. It sets up the GPIO lines, drives them in an alternating sequence, and includes a signal handler to cleanly exit and release resources on Ctrl+C.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO17 17
#define GPIO27 27
#define BAUDRATE 9600
#define TIMEOUT 5000
#define EXPECTED_CODE "123456"
#define MAX_CODE_LENGTH 7

static int serial_fd0, serial_fd1;
static int gpio17_state = 0, gpio27_state = 0;
static volatile sig_atomic_t exit_flag = 0;

void handle_sigint(int sig) {
    exit_flag = 1;
}

void gpio_cleanup() {
    gpioWrite(GPIO17, 0);
    gpioWrite(GPIO27, 0);
    gpioTerminate();
}

void serial_cleanup() {
    if (serial_fd0 >= 0) {
        close(serial_fd0);
    }
    if (serial_fd1 >= 0) {
        close(serial_fd1);
    }
}

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

int setup_serial(const char *path, int baudrate) {
    struct termios options;
    int fd = open(path, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        log_error("Failed to open serial port");
        return -1;
    }

    if (tcgetattr(fd, &options) == -1) {
        log_error("Failed to get serial port attributes");
        close(fd);
        return -1;
    }

    cfsetispeed(&options, baudrate);
    cfsetospeed(&options, baudrate);

    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS;
    options.c_cflag |= CREAD | CLOCAL;

    options.c_lflag &= ~ICANON;
    options.c_lflag &= ~ECHO;
    options.c_lflag &= ~ECHOE;
    options.c_lflag &= ~ECHONL;
    options.c_lflag &= ~ISIG;

    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | INLCR | IGNCR | ICRNL | IXON);

    options.c_oflag &= ~OPOST;
    options.c_oflag &= ~ONLCR;

    if (tcsetattr(fd, TCSANOW, &options) == -1) {
        log_error("Failed to set serial port attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_serial(int fd, char *buffer, size_t length) {
    fd_set set;
    struct timeval timeout;
    int n;

    FD_ZERO(&set);
    FD_SET(fd, &set);

    timeout.tv_sec = TIMEOUT / 1000;
    timeout.tv_usec = (TIMEOUT % 1000) * 1000;

    n = select(fd + 1, &set, NULL, NULL, &timeout);
    if (n == -1) {
        log_error("Failed to select serial port");
        return -1;
    } else if (n == 0) {
        return 0; // Timeout
    }

    n = read(fd, buffer, length - 1);
    if (n == -1) {
