#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>

#define PIR_PIN 4
#define RELAY_PIN 17
#define PIR_TIMEOUT 10000 // 10 seconds in milliseconds
#define STRIKE_DURATION 1000 // 1 second in milliseconds

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    int ret;
    struct gpiod_chip *chip;
    struct gpiod_line *pir_line, *relay_line;
    struct gpiod_line_request_config config;
    struct timespec sleep_time = {0, 50000000}; // 50 ms

    // Open the gpiochip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0");
        exit(EXIT_FAILURE);
    }

    // Request the PIR line
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.consumer = "PIR Sensor";
    ret = gpiod_line_request(chip, PIR_PIN, &config);
    if (ret) {
        syslog(LOG_ERR, "Failed to request PIR line: %s", gpiod_errno(chip));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request the relay line
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.consumer = "Relay";
    ret = gpiod_line_request(chip, RELAY_PIN, &config);
    if (ret) {
        syslog(LOG_ERR, "Failed to request relay line: %s", gpiod_errno(chip));
        gpiod_line_release(chip, PIR_PIN);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set the relay line to LOW initially
    ret = gpiod_line_set_value(chip, RELAY_PIN, 0);
    if (ret) {
        syslog(LOG_ERR, "Failed to set relay line to LOW: %s", gpiod_errno(chip));
        gpiod_line_release(chip, PIR_PIN);
        gpiod_line_release(chip, RELAY_PIN);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!should_exit) {
        int pir_state = gpiod_line_get_value(chip, PIR_PIN);
        syslog(LOG_INFO, "PIR state: %d", pir_state);

        if (pir_state) {
            // Motion detected
            syslog(LOG_INFO, "Motion detected, energizing relay");
            ret = gpiod_line_set_value(chip, RELAY_PIN, 1);
            if (ret) {
                syslog(LOG_ERR, "Failed to energize relay: %s", gpiod_errno(chip));
                break;
            }

            // Strike duration
            usleep(STRIKE_DURATION * 1000);

            // De-energize relay
            syslog(LOG_INFO, "De-energizing relay");
            ret = gpiod_line_set_value(chip, RELAY_PIN, 0);
            if (ret) {
                syslog(LOG_ERR, "Failed to de-energize relay: %s", gpiod_errno(chip));
                break;
            }
        } else {
            // No motion detected
            syslog(LOG_INFO, "No motion detected, de-energizing relay");
            ret = gpiod_line_set_value(chip, RELAY_PIN, 0);
            if (ret) {
                syslog(LOG_ERR, "Failed to de-energize relay: %s", gpiod_errno(chip));
                break;
            }
        }

        // Check for PIR timeout
        struct timespec start_time, current_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        while (!should_exit) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            if ((current_time.tv_sec - start_time.tv_sec) * 1000000000 +
                (current_time.tv_nsec - start_time.tv_nsec) >= PIR_TIMEOUT) {
                syslog(LOG_WARNING, "PIR sensor has been HIGH for more than 10 seconds, de-energizing relay");
                ret = gpiod_line_set_value(chip, RELAY_PIN, 0);
                if (ret) {
                    syslog(LOG_ERR, "Failed to de-energize relay: %s", gpiod_errno(chip));
                    break;
                }
                break;
            }
            nanosleep(&sleep_time, NULL);
        }
    }

    // Clean up
    gpiod_line_release(chip, PIR_PIN);
    gpiod_line_release(chip, RELAY_PIN);
    gpiod_chip_close(chip);

    syslog(LOG_INFO, "Exiting program");
    closelog();

    return 0;
}

