#define NUM_RELAYS 4
#define RELAY_PINS {4, 17, 27, 22}
#define ACTIVATION_TIME 300
#define PAUSE_TIME 60
#define LOG_IDENTIFIER "irrigation_system"

volatile sig_atomic_t running = 1;

void log_error(const char *msg) {
    syslog(LOG_ERR, "Error: %s", msg);
    exit(EXIT_FAILURE);
}

void log_info(const char *msg) {
    syslog(LOG_INFO, "Info: %s", msg);
}

