    running = 0;
    log_info("Received signal, deactivating relays and exiting.");
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(RELAY_PINS[i], 1); // Set all relays to HIGH (OFF)
    }
    gpioTerminate();
    closelog();
    exit(EXIT_SUCCESS);
}

void activate_relay(int pin) {
    gpioWrite(pin, 0); // Set relay to LOW (ON)
    log_info("Relay %d activated.", pin);
}

void deactivate_relay(int pin) {
    gpioWrite(pin, 1); // Set relay to HIGH (OFF)
    log_info("Relay %d deactivated.", pin);
}

void timer_callback(int timer, uint32_t ticks, void *data) {
    static int current_relay = 0;
    static enum { ACTIVATE, DEACTIVATE, PAUSE } state = ACTIVATE;

    switch (state) {
        case ACTIVATE:
            activate_relay(RELAY_PINS[current_relay]);
            state = DEACTIVATE;
            break;
        case DEACTIVATE:
            deactivate_relay(RELAY_PINS[current_relay]);
            state = PAUSE;
            break;
        case PAUSE:
            if (current_relay == NUM_RELAYS - 1) {
                current_relay = 0;
            } else {
                current_relay++;
            }
            state = ACTIVATE;
            break;
    }
}

