#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define RELAY_PINS {18, 23, 24, 25}
#define INTERVALS {2, 3, 5, 7}

static gpiod_chip *chip;
static gpiod_line *lines[NUM_RELAYS];
static int exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

void release_resources() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    printf("Resources released.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, RELAY_PINS[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            release_resources();
            exit(EXIT_FAILURE);
        }
        int flags = GPIOD_LINE_REQUEST_OUTPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
        int ret = gpiod_line_request_output(lines[i], "relay", flags, 0);
        if (ret) {
            perror("Failed to request GPIO line");
            release_resources();
            exit(EXIT_FAILURE);
        }
    }

    // Main loop
    struct timespec next_time[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        clock_gettime(CLOCK_MONOTONIC, &next_time[i]);
        next_time[i].tv_sec += INTERVALS[i];
    }

    while (!exit_flag) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (clock_gettime(CLOCK_MONOTONIC, &next_time[i]) == 0 &&
                next_time[i].tv_sec <= time(NULL)) {
                gpiod_line_set_value(lines[i], 1); // Turn on relay
