#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <fcntl.h>
#include <errno.h>

#define SERIAL_PORT "/dev/serial0"
#define BAUD_RATE 9600
#define TXD_PIN 14
#define RXD_PIN 15
#define READ_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define CHECKSUM_OFFSET 7
#define CHECKSUM_LENGTH 1
#define RESPONSE_LENGTH 9
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define LOG_INTERVAL 5
#define TIMEOUT 1000000 // 1 second in microseconds

static int pi;
static int serial_fd;
static FILE *log_file;
static FILE *error_log_file;

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(error_log_file, "%04d-%02d-%02d %02d:%02d:%02d %s\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, message);
    fflush(error_log_file);
}

static void log_json(const char *json) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d %s\n", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, json);
    fflush(log_file);
    printf("%s\n", json);
}

static void handle_sigint(int signum) {
    if (serial_fd != -1) {
        serClose(serial_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    if (pi != -1) {
        gpioTerminate();
    }
    exit(0);
}

static int read_co2() {
    uint8_t response[RESPONSE_LENGTH];
    int bytes_read = 0;
    int timeout_start = time(NULL) * 1000000;
    int timeout_end = timeout_start + TIMEOUT;

    while (time(NULL) * 1000000 < timeout_end) {
        if (serDataAvailable(serial_fd) >= RESPONSE_LENGTH) {
            bytes_read = serRead(serial_fd, response, RESPONSE_LENGTH);
            if (bytes_read == RESPONSE_LENGTH) {
                break;
            }
        }
        usleep(10000); // 10 ms
    }

    if (bytes_read != RESPONSE_LENGTH) {
        log_error("Timeout reading CO2 data");
        return -1;
    }

    uint8_t checksum = 0;
    for (int i = 0; i < CHECKSUM_OFFSET; i++) {
        checksum ^= response[i];
    }
    checksum = ~checksum + 1;

    if (checksum != response[CHECKSUM_OFFSET]) {
        log_error("Invalid checksum in CO2 data");
        return -1;
    }

    int co2_ppm = (response[2] << 8) | response[3];
    log_json("{\"timestamp\": \"%04d-%02d-%02d %02d:%02d:%02d\", \"co2_ppm\": %d, \"error\": false}", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, co2_ppm);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }
    pi = gpioGetPiId();

    if ((serial_fd = serOpen(SERIAL_PORT, BAUD_RATE, 0)) < 0) {
        log_error("Failed to open serial port");
        gpioTerminate();
        return 1;
    }

    if (signal(SIGINT, handle_sigint) == SIG_ERR) {
        log_error("Failed to set SIGINT handler");
        serClose(serial_fd);
        gpioTerminate();
        return 1;
    }

    if (signal(SIGTERM, handle_sigint) == SIG_ERR) {
        log_error("Failed to set SIGTERM handler");
        serClose(serial_fd);
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        log_error("Failed to open log file");
        serClose(serial_fd);
        gpioTerminate();
        return 1;
    }

    if ((error_log_file = fopen(ERROR_LOG_FILE, "a")) == NULL) {
        log_error("Failed to open error log file");
        fclose(log_file);
        serClose(serial_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        if (read_co2() == 0) {
            // Simulate sending to remote server
            log_json("{\"timestamp\": \"%04d-%02d-%02d %02d:%02d:%02d\", \"co2_ppm\": %d, \"error\": false}", tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec, co2_ppm);
        }
        sleep(LOG_INTERVAL);
    }

    fclose(log_file);
    fclose(error_log_file);
    serClose(serial_fd);
    gpioTerminate();
    return 0;
}

