#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_START 0x03
#define BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define DEG_TO_RAD 0.017453292519943295

typedef struct {
    int16_t x, y, z;
} SensorData;

SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_full = 0;

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

void log_heading(float heading) {
    printf("Compensated Heading: %.2f degrees\n", heading);
}

void read_sensor_data(SensorData *data) {
    int16_t raw_data[6];
    if (gpio_i2c_read_block_data(I2C_BUS, I2C_ADDR, DATA_START, raw_data, 6) != 6) {
        log_error("Failed to read sensor data");
        return;
    }

    data->x = (raw_data[0] << 8) | raw_data[1];
    data->y = (raw_data[2] << 8) | raw_data[3];
    data->z = (raw_data[4] << 8) | raw_data[5];
}

float compensate_heading(float x, float y) {
    float x_offset = 100.0;
    float y_offset = -50.0;
    return atan2(y - y_offset, x - x_offset) * 180.0 / M_PI;
}

void update_gpio(int gpio, float heading) {
    if (fabs(heading - TARGET_HEADING) > 10.0) {
        gpio_write(gpio, 1);
    } else {
        gpio_write(gpio, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        return 1;
    }

    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO mode");
        gpioTerminate();
        return 1;
    }

    if (gpioI2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    uint8_t config_a = 0x70;
    uint8_t config_b = 0x20;
    uint8_t mode = 0x00;
    if (gpioI2cWriteByteData(I2C_BUS, I2C_ADDR, CONFIG_A, config_a) < 0) {
        log_error("Failed to write CONFIG_A");
        gpioTerminate();
        return 1;
    }
    if (gpioI2cWriteByteData(I2C_BUS, I2C_ADDR, CONFIG_B, config_b) < 0) {
        log_error("Failed to write CONFIG_B");
        gpioTerminate();
        return 1;
    }
    if (gpioI2cWriteByteData(I2C_BUS, I2C_ADDR, MODE, mode) < 0) {
        log_error("Failed to write MODE");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        SensorData data;
        read_sensor_data(&data);

        float x = data.x;
        float y = data.y;
        float z = data.z;

        float heading = compensate_heading(x, y);
        log_heading(heading);

        update_gpio(17, heading);

        // Update buffer
        buffer[buffer_index].x = x;
        buffer[buffer_index].y = y;
        buffer[buffer_index].z = z;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        if (buffer_index == 0) {
            buffer_full = 1;
        }

        usleep(100000); // Sample every 100 ms
    }

    gpioTerminate();
    return 0;
}

