#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define RED_RELAY 17
#define GREEN_RELAY 27
#define BLUE_RELAY 22
#define LOG_FILE "lighting_log.txt"
#define MAX_LUX 300
#define MIN_LUX 50
#define HIGH_RES_MODE 0x10
#define CONVERSION_DELAY 120

static int i2c_fd;
static int gpio_fd;
static FILE *log_file;

static void log_lighting_data(time_t timestamp, int lux, int red, int green, int blue) {
    fprintf(log_file, "%ld, %d, %d, %d, %d\n", timestamp, lux, red, green, blue);
    fflush(log_file);
}

static void handle_signal(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    if (gpio_fd >= 0) {
        gpiod_chip_close(gpio_fd);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

static void setup_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void setup_gpio() {
    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }
    struct gpiod_line *red_line = gpiod_chip_get_line(gpio_fd, RED_RELAY);
    struct gpiod_line *green_line = gpiod_chip_get_line(gpio_fd, GREEN_RELAY);
    struct gpiod_line *blue_line = gpiod_chip_get_line(gpio_fd, BLUE_RELAY);
    if (!red_line || !green_line || !blue_line) {
        perror("Failed to get GPIO lines");
        gpiod_chip_close(gpio_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(red_line, "RED_RELAY", 0) < 0 ||
        gpiod_line_request_output(green_line, "GREEN_RELAY", 0) < 0 ||
        gpiod_line_request_output(blue_line, "BLUE_RELAY", 0) < 0) {
        perror("Failed to request GPIO lines");
        gpiod_line_release(red_line);
        gpiod_line_release(green_line);
        gpiod_line_release(blue_line);
        gpiod_chip_close(gpio_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void setup_logging() {
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_chip_close(gpio_fd);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "Timestamp, Lux, RED, GREEN, BLUE\n");
    fflush(log_file);
}

static void write_i2c_register(int reg, int value) {
    uint8_t buf[2] = {reg, value};
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        gpiod_chip_close(gpio_fd);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }
}

static int read_i2c_register(int reg) {
    uint8_t buf[1] = {reg};
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Failed to write to I2C device");
        close(i2c_fd);
        gpiod_chip_close(gpio_fd);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }
    if (read(i2c_fd, buf, 1) != 1) {
        perror("Failed to read from I2C device");
        close(i2c_fd);
        gpiod_chip_close(gpio_fd);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }
    return buf[0];
}

static void set_bh1750_mode(int mode) {
    write_i2c_register(0x01, mode);
    usleep(CONVERSION_DELAY * 1000);
}

static int read_bh1750_lux() {
    set_bh1750_mode(HIGH_RES_MODE);
    uint8_t buf[2];
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        close(i2c_fd);
        gpiod_chip_close(gpio_fd);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }
    return (buf[0] << 8) | buf[1];
}

static void set_relay(int relay, int state) {
    if (relay == RED_RELAY) {
        gpiod_line_set_value(gpiod_chip_get_line(gpio_fd, RED_RELAY), state);
    } else if (relay == GREEN_RELAY) {
        gpiod_line_set_value(gpiod_chip_get_line(gpio_fd, GREEN_RELAY), state);
    } else if (relay == BLUE_RELAY) {
        gpiod_line_set_value(gpiod_chip_get_line(gpio_fd, BLUE_RELAY), state);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_i2c();
    setup_gpio();
    setup_logging();

    while (1) {
        time_t timestamp = time(NULL);
        int lux = read_bh1750_lux();
        int red = lux < MIN_LUX ? 1 : 0;
        int green = lux >= MIN_LUX && lux < MAX_LUX ? 1 : 0;
        int blue = lux >= MAX_LUX ? 1 : 0;

        set_relay(RED_RELAY, red);
        set_relay(GREEN_RELAY, green);
        set_relay(BLUE_RELAY, blue);

        log_lighting_data(timestamp, lux, red, green, blue);

        sleep(1);
    }

    fclose(log_file);
    gpiod_chip_close(gpio_fd);
    close(i2c_fd);

    return 0;
}

