#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

void stopMotors() {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
}

void cleanup() {
    stopMotors();
    gpioTerminate();
    printf("Cleanup complete.\n");
}

void handleSignal(int sig) {
    printf("Signal %d received, cleaning up...\n", sig);
    cleanup();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <distance>\n", argv[0]);
        return 1;
    }

    int distance = atoi(argv[1]);
    if (distance < 10 || distance > 100) {
        fprintf(stderr, "Distance must be between 10 and 100 cm.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    gpioSetPWMFrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMFrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);

    while (1) {
        int dutyCycle = (PWM_RANGE * (100 - distance)) / 100;
        dutyCycle = (dutyCycle < 0) ? 0 : (dutyCycle > PWM_RANGE) ? PWM_RANGE : dutyCycle;

        if (distance < 50) {
            gpioWrite(MOTOR_A_IN1, 1);
            gpioWrite(MOTOR_A_IN2, 0);
            gpioWrite(MOTOR_B_IN3, 1);
            gpioWrite(MOTOR_B_IN4, dutyCycle);
        } else {
            gpioWrite(MOTOR_A_IN1, 0);
            gpioWrite(MOTOR_A_IN2, 1);
            gpioWrite(MOTOR_B_IN3, 0);
            gpioWrite(MOTOR_B_IN4, dutyCycle);
        }

        usleep(100000); // 100 ms delay
    }

    cleanup();
    return 0;
}

