#include <signal.h>
#include <pigpio.h>

#define STEPPER_PINS {17, 18, 27, 22}
#define BUTTON_LOCK 24
#define BUTTON_UNLOCK 23
#define STEPS_PER_TURN 512
#define INTER_STEP_DELAY 2000

static volatile sig_atomic_t exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

void unlock_motor() {
    printf("Unlocking the door...\n");
    for (int i = 0; i < STEPS_PER_TURN; i++) {
        for (int j = 0; j < 4; j++) {
            gpioWrite(STEPPER_PINS[j], 1);
            gpioDelay(INTER_STEP_DELAY);
            gpioWrite(STEPPER_PINS[j], 0);
        }
    }
    printf("Door unlocked.\n");
}

void lock_motor() {
    printf("Locking the door...\n");
    for (int i = 0; i < STEPS_PER_TURN; i++) {
        for (int j = 3; j >= 0; j--) {
            gpioWrite(STEPPER_PINS[j], 1);
            gpioDelay(INTER_STEP_DELAY);
            gpioWrite(STEPPER_PINS[j], 0);
        }
    }
    printf("Door locked.\n");
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(STEPPER_PINS[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", STEPPER_PINS[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetMode(BUTTON_LOCK, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", BUTTON_LOCK);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_UNLOCK, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", BUTTON_UNLOCK);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_LOCK, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", BUTTON_LOCK);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_UNLOCK, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", BUTTON_UNLOCK);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!exit_flag) {
        if (gpioRead(BUTTON_LOCK) == 0) {
            lock_motor();
            while (gpioRead(BUTTON_LOCK) == 0) {
                // Wait for button release
            }
        } else if (gpioRead(BUTTON_UNLOCK) == 0) {
            unlock_motor();
            while (gpioRead(BUTTON_UNLOCK) == 0) {
                // Wait for button release
            }
        }
    }

    gpioWrite(STEPPER_PINS[0], 0);
    gpioWrite(STEPPER_PINS[1], 0);
    gpioWrite(STEPPER_PINS[2], 0);
    gpioWrite(STEPPER_PINS[3], 0);

    gpioTerminate();

    return EXIT_SUCCESS;
}

