#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define SCHEDULE_FILE "lighting_schedule.txt"
#define MAX_SCHEDULE_ENTRIES 100
#define MAX_LINE_LENGTH 100

static int gpio_pins[NUM_RELAYS] = {4, 17, 27, 22};
static int pwm_duties[NUM_RELAYS] = {0, 0, 0, 0};
static int schedule_entries = 0;
static struct tm current_time;
static struct tm next_event_time;
static int current_event_index = 0;
static int running = 1;

static void handle_signal(int signum) {
    running = 0;
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(gpio_pins[i], 0);
    }
    gpioTerminate();
    exit(0);
}

static void load_schedule() {
    FILE *file = fopen(SCHEDULE_FILE, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening schedule file: %s\n", SCHEDULE_FILE);
        exit(1);
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file) != NULL) {
        char time_str[9];
        char relay_str[2];
        char onoff_str[2];
        int relay;
        int onoff;

        if (sscanf(line, "%8s %1s %1s", time_str, relay_str, onoff_str) != 3) {
            fprintf(stderr, "Invalid schedule entry: %s\n", line);
            continue;
        }

        relay = atoi(relay_str) - 1;
        onoff = onoff_str[0] == '1';

        if (relay < 0 || relay >= NUM_RELAYS || onoff < 0 || onoff > 1) {
            fprintf(stderr, "Invalid schedule entry: %s\n", line);
            continue;
        }

        struct tm event_time;
        if (strptime(time_str, "%H:%M:%S", &event_time) == NULL) {
            fprintf(stderr, "Invalid schedule entry: %s\n", line);
            continue;
        }

        if (current_event_index < MAX_SCHEDULE_ENTRIES) {
            schedule_entries++;
            next_event_time = event_time;
            pwm_duties[relay] = onoff ? PWM_RANGE : 0;
        } else {
            fprintf(stderr, "Schedule file contains too many entries\n");
            exit(1);
        }
    }

    fclose(file);
}

static void update_time() {
    time_t now = time(NULL);
    localtime_r(&now, &current_time);
}

static void update_next_event() {
    if (current_event_index < schedule_entries) {
        next_event_time = schedule_entries[current_event_index];
    } else {
        next_event_time = current_time;
    }
}

static void update_pwm_duties() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (pwm_duties[i] > 0) {
            gpioPWM(gpio_pins[i], pwm_duties[i]);
        } else {
            gpioPWM(gpio_pins[i], 0);
        }
    }
}

static void update_schedule() {
    update_time();
    update_next_event();
    update_pwm_duties();
}

static void run() {
    while (running) {
        update_schedule();
        sleep(1);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    load_schedule();
    run();

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWM(gpio_pins[i], 0);
    }
    gpioTerminate();
    return 0;
}

