#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18
#define MAX_DISTANCE 30
#define MIN_DISTANCE 2
#define MAX_FREQ 2000
#define MIN_FREQ 200
#define SAMPLE_RATE 50
#define TIMEOUT 1000000 // 1 second

static volatile int running = 1;
static volatile int echo_start = 0;
static volatile int echo_end = 0;

void handle_sigint(int signum) {
    running = 0;
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    exit(0);
}

void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(1);
    }
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
}

void cleanup_pigpio() {
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microsecond pulse
    gpioWrite(TRIGGER_PIN, 0);
}

int measure_distance() {
    gpioSetAlertFunc(ECHO_PIN, echo_handler);
    while (!echo_start) {
        if (!running) {
            return -1;
        }
    }
    echo_end = gpioTick();
    gpioSetAlertFunc(ECHO_PIN, NULL);
    return (echo_end - echo_start) / 58.2; // Convert microseconds to centimeters
}

void echo_handler(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN && level == 1) {
        echo_start = tick;
    }
}

int map_distance_to_frequency(int distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQ;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQ;
    }
    return (distance - MIN_DISTANCE) * (MAX_FREQ - MIN_FREQ) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_FREQ;
}

void play_frequency(int frequency) {
    if (frequency < MIN_FREQ || frequency > MAX_FREQ) {
        return;
    }
    int period = 1000000 / frequency; // Calculate period in microseconds
    gpioPWM(BUZZER_PIN, period, period / 2); // 50% duty cycle
}

int main() {
    signal(SIGINT, handle_sigint);
    init_pigpio();

    while (running) {
        trigger_sensor();
        int distance = measure_distance();
        if (distance < 0) {
            fprintf(stderr, "Failed to measure distance\n");
            continue;
        }
        int frequency = map_distance_to_frequency(distance);
        play_frequency(frequency);
        gpioDelay(60000); // 60 ms gap between measurements
    }

    cleanup_pigpio();
    return 0;
}

