#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 22
#define BLUE_PIN 27
#define PWM_FREQUENCY 1000

static volatile int running = 1;

void handle_sigint(int signum) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for RED_PIN\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GREEN_PIN\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for BLUE_PIN\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMFrequency(RED_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for RED_PIN\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMFrequency(GREEN_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GREEN_PIN\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMFrequency(BLUE_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for BLUE_PIN\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        double proximity = sin(gpioTick() / 1000000.0 * 2 * M_PI); // Simulated proximity value
        proximity = (proximity + 1.0) / 2.0; // Scale to 0.0 to 1.0

        int red = (int)(proximity * 255);
        int green = (int)((1.0 - proximity) * 255);
        int blue = 0;

        if (gpioPWM(RED_PIN, red) < 0) {
            fprintf(stderr, "Failed to set PWM for RED_PIN\n");
            break;
        }

        if (gpioPWM(GREEN_PIN, green) < 0) {
            fprintf(stderr, "Failed to set PWM for GREEN_PIN\n");
            break;
        }

        if (gpioPWM(BLUE_PIN, blue) < 0) {
            fprintf(stderr, "Failed to set PWM for BLUE_PIN\n");
            break;
        }

        usleep(10000); // Sleep for 10 ms
    }

    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);

    gpioTerminate();

    return 0;
}

