#include <signal.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48
#define GYRO_SENSITIVITY 131.0

static int i2c_fd;
static FILE *gyro_log;

void log_gyro_reading(int x, int y, int z) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    fprintf(gyro_log, "%ld.%09ld, %d, %d, %d\n", ts.tv_sec, ts.tv_nsec, x, y, z);
}

void handle_signal(int sig) {
    if (gyro_log) fclose(gyro_log);
    if (i2c_fd >= 0) close(i2c_fd);
    exit(0);
}

int main() {
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data msgset;
    int x, y, z;
    int ret;

    // Register PWR_MGMT_1 to wake the sensor
    msgs[0].addr = MPU6050_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = (unsigned char *)&PWR_MGMT_1;
    msgs[1].addr = MPU6050_ADDR;
    msgs[1].flags = I2C_M_RD;
