#define DUTY_CYCLE 50        // 50% duty cycle for volume
#define MELody_LENGTH 10     // Number of notes in the melody

// Melody in Hz
const int melody[] = {440, 494, 587, 659, 784, 932, 1046, 1175, 1319, 1397};

// Flag to control playback
volatile sig_atomic_t play = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    play = 0;  // Stop playback
    gpioHardwarePWM(BUZZER_PIN, 0, 0);  // Stop PWM
    gpioTerminate();  // Clean shutdown
    exit(EXIT_SUCCESS);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set GPIO17 as input with internal pull-up
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO17 pull-up\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set GPIO18 as hardware PWM0
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO18 mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioHardwarePWM(BUZZER_PIN, TONE_FREQ, DUTY_CYCLE) < 0) {
        fprintf(stderr, "Failed to set GPIO18 hardware PWM\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up interrupt on GPIO17
    if (gpioSetISRFuncEx(BUTTON_PIN, RISING_EDGE, DEBOUNCE_TIME, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to set GPIO17 interrupt\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        if (play) {
            // Play the melody
            for (int i = 0; i < MELody_LENGTH; i++) {
                gpioHardwarePWM(BUZZER_PIN, melody[i], DUTY_CYCLE);
                usleep(melody[i] * 1000);  // Wait for the note duration
                gpioHardwarePWM(BUZZER_PIN, 0, 0);  // Stop PWM
                usleep(50000);  // Wait for 50 ms
            }
            play = 0;  // Stop playback
        }
    }

    // Clean shutdown
    gpioHardwarePWM(BUZZER_PIN, 0, 0);  // Stop PWM
    gpioTerminate();  // Clean shutdown

    return EXIT_SUCCESS;
}

