#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define LOG_FILE "vibration_events.log"
#define DEFAULT_TIMEOUT 1000
#define WINDOW_SIZE 5

volatile sig_atomic_t exit_flag = 0;

void sig_handler(int signum) {
    exit_flag = 1;
}

int main(int argc, char *argv[]) {
    int timeout = DEFAULT_TIMEOUT;
    struct timespec ts;
    struct tm *tm;
    char timestamp[20];
    int fd;
    gpiod_chip *chip;
    gpiod_line *line;
    gpiod_line_request *request;
    gpiod_line_event event;
    int event_count = 0;
    int event_window[WINDOW_SIZE];
    int event_window_index = 0;
    int event_window_high_count = 0;

    // Install signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Parse timeout from command line argument
    if (argc > 1) {
        timeout = atoi(argv[1]);
        if (timeout <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default %d ms.\n", DEFAULT_TIMEOUT);
            timeout = DEFAULT_TIMEOUT;
        }
    }

    // Open log file
    fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd == -1) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Request line
    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        close(fd);
        exit(EXIT_FAILURE);
    }

    request = gpiod_line_request_input(line, "vibration_sensor");
    if (!request) {
        perror("Failed to request line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!exit_flag) {
        // Wait for an event
        if (gpiod_line_event_wait(line, timeout, &event) < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("Failed to wait for event");
            break;
        }

        // Read event
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("Failed to read event");
            break;
        }

        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        tm = localtime(&ts.tv_sec);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

        // Log event
        if (write(fd, timestamp, strlen(timestamp)) < 0) {
            perror("Failed to write to log file");
        }
        if (write(fd, " ", 1) < 0) {
            perror("Failed to write to log file");
        }
        if (write(fd, event.event_type == GPIOD_LINE_EVENT_RISING_EDGE ? "1" : "0", 1) < 0) {
            perror("Failed to write to log file");
        }
        if (write(fd, "\n", 1) < 0) {
            perror("Failed to write to log file");
        }
        if (fflush(fd) < 0) {
            perror("Failed to flush log file");
        }

        // Update event window
        event_window[event_window_index] = event.event_type == GPIOD_LINE_EVENT_RISING_EDGE ? 1 : 0;
        event_window_index = (event_window_index + 1) % WINDOW_SIZE;
        event_window_high_count = 0;
        for (int i = 0; i < WINDOW_SIZE; i++) {
            if (event_window[i] == 1) {
                event_window_high_count++;
            }
        }

        // Check for earthquake alert
        if (event_window_high_count >= 3) {
            fprintf(stderr, "EARTHQUAKE ALERT: %s\n", timestamp);
        }

        // Reset event count
        event_count = 0;
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(fd);

    return 0;
}

