#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define LOG_FILE "relay_log.json"
#define DEBOUNCE_TIME_MS 200

static int gpio;
static FILE *log_file;
static char log_entry[256];
static struct timespec last_touch_time;

void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    strftime(log_entry, sizeof(log_entry), "{\"timestamp\":\"%Y-%m-%dT%H:%M:%S\",\"relay_state\":\"%s\"}\n", state ? "ON" : "OFF");
    if (fputs(log_entry, log_file) == EOF) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }
}

void gpio_isr_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_FALLING_EDGE) {
        struct timespec current_time;
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if ((current_time.tv_sec - last_touch_time.tv_sec) * 1000000000 + (current_time.tv_nsec - last_touch_time.tv_nsec) / 1000 > DEBOUNCE_TIME_MS * 1000000) {
            last_touch_time = current_time;
            log_relay_state(1);
            gpioWrite(RELAY_PIN, 1);
        }
    }
}

void signal_handler(int signum) {
    gpioWrite(RELAY_PIN, 0);
    log_relay_state(0);
    fclose(log_file);
    gpioTerminate();
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN);
    gpioSetISRFunc(TOUCH_PIN, RISING_EDGE, 100, gpio_isr_callback);

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (1) {
        sleep(1); // Keep the program running
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

