#define LOG_FILE "irrigation_log.txt"
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%S,%03d\t%d\t%d\n"
#define DELAY_BETWEEN_RELAYS 1000000 // 1 second in microseconds
#define DELAY_BETWEEN_ACTIVATIONS 5000000 // 5 seconds in microseconds

static gpiod_chip *chip = NULL;
static gpiod_line *lines[GPIO_LINES] = {NULL};
static FILE *log_file = NULL;
static int moisture_level = 0;

static void log_irrigation_event(int relay, int moisture) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, LOG_FORMAT, ts.tv_sec, ts.tv_nsec / 1000, relay, moisture);
    fflush(log_file);
}

static void handle_signal(int sig) {
    if (chip) {
        for (int i = 0; i < GPIO_LINES; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the gpiochip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open gpiochip");
        exit(EXIT_FAILURE);
    }

    // Request the four lines as outputs with an inactive drive of 1
    for (int i = 0; i < GPIO_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            perror("Failed to get line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        int ret = gpiod_line_request_output(lines[i], "irrigation", 1);
        if (ret) {
            perror("Failed to request line as output");
            gpiod_line_release(lines[i]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        for (int i = 0; i < GPIO_LINES; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Seed the random number generator
    srand(time(NULL));

    while (1) {
        // Generate a simulated soil-moisture value
        moisture_level = rand() % 101;

        // Log the moisture level
        log_irrigation_event(-1, moisture_level);

        // Check if the moisture level is below 30
        if (moisture_level < 30) {
            // Activate each relay
            for (int i = 0; i < GPIO_LINES; i++) {
                int ret = gpiod_line_set_value(lines[i], 0);
                if (ret) {
                    perror("Failed to set line value");
                    break;
                }
                log_irrigation_event(i + 1, moisture_level);
                usleep(DELAY_BETWEEN_ACTIVATIONS);
                ret = gpiod_line_set_value(lines[i], 1);
                if (ret) {
                    perror("Failed to set line value");
                    break;
                }
                usleep(DELAY_BETWEEN_RELAYS);
            }
        }

        // Wait for 10 seconds
        sleep(10);
    }

    // Close the log file and release resources
    fclose(log_file);
    for (int i = 0; i < GPIO_LINES; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

