#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_PIN 17
#define NOZZLE_PIN 18
#define MOISTURE_READINGS 5
#define MOISTURE_THRESHOLD 50
#define WATERING_DURATION 2
#define HOLD_DURATION 5
#define MAX_RETRIES 3
#define RETRY_DELAY 100000  // 100 ms

volatile sig_atomic_t stop = 0;

void handle_signal(int sig) {
    stop = 1;
    gpioServo(VALVE_PIN, 0);
    gpioServo(NOZZLE_PIN, 0);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(VALVE_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_PIN, PI_OUTPUT);

    int moisture_readings[MOISTURE_READINGS] = {20, 40, 60, 80, 100};
    int valve_open = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!stop) {
        for (int i = 0; i < MOISTURE_READINGS; i++) {
            int moisture = moisture_readings[i];
            printf("Moisture reading: %d\n", moisture);

            if (moisture < MOISTURE_THRESHOLD) {
                valve_open = 1;
                gpioServo(VALVE_PIN, 90);
                printf("Valve opened\n");

                for (int angle = 0; angle < 5; angle++) {
                    for (int retry = 0; retry < MAX_RETRIES; retry++) {
                        if (gpioServo(NOZZLE_PIN, angle * 45) >= 0) {
                            printf("Nozzle set to %d degrees\n", angle * 45);
                            break;
                        } else {
                            printf("Failed to set nozzle to %d degrees, retrying...\n", angle * 45);
                            usleep(RETRY_DELAY);
                        }
                    }
                    if (retry == MAX_RETRIES) {
                        printf("Critical warning: Failed to set nozzle to %d degrees\n", angle * 45);
                        break;
                    }
                }

                usleep(WATERING_DURATION * 1000000);  // 2 seconds

                for (int angle = 4; angle >= 0; angle--) {
                    for (int retry = 0; retry < MAX_RETRIES; retry++) {
                        if (gpioServo(NOZZLE_PIN, angle * 45) >= 0) {
                            printf("Nozzle set to %d degrees\n", angle * 45);
                            break;
                        } else {
                            printf("Failed to set nozzle to %d degrees, retrying...\n", angle * 45);
                            usleep(RETRY_DELAY);
                        }
                    }
                    if (retry == MAX_RETRIES) {
                        printf("Critical warning: Failed to set nozzle to %d degrees\n", angle * 45);
                        break;
                    }
                }

                usleep(HOLD_DURATION * 1000000);  // 5 seconds

                gpioServo(VALVE_PIN, 0);
                printf("Valve closed\n");
            } else {
                printf("Moisture level is above threshold, skipping watering\n");
            }

            usleep(5000000);  // 5 seconds
        }
    }

    gpioServo(VALVE_PIN, 0);
    gpioServo(NOZZLE_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

