#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define MPU6050_ADDR 0x68
#define GYRO_XOUT_H 0x43
#define PWR_MGMT_1 0x6B
#define SAMPLE_RATE 10
#define LOG_FILE "gyro_log.txt"

static int i2c_fd;
static struct gpiod_chip *pwr_mgmt_chip;
static struct gpiod_line *pwr_mgmt_line;

void signal_handler(int sig) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (pwr_mgmt_chip) {
        gpiod_chip_close(pwr_mgmt_chip);
    }
    if (pwr_mgmt_line) {
        gpiod_line_release(pwr_mgmt_line);
    }
    exit(0);
}

int main() {
    int ret;
    struct timespec ts;
    uint8_t buffer[6];
    FILE *log_file;

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set MPU6050 address
    ret = ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize power management register
    buffer[0] = PWR_MGMT_1;
    buffer[1] = 0x00; // Wake up the sensor
    ret = write(i2c_fd, buffer, 2);
    if (ret < 0) {
        perror("Failed to write to PWR_MGMT_1");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Read gyroscope data at 10 Hz
    while (1) {
        // Read 6 bytes of gyroscope data
        ret = read(i2c_fd, buffer, 6);
        if (ret < 0) {
            perror("Failed to read from MPU6050");
            close(i2c_fd);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }

        // Convert raw 16-bit big-endian values to degrees/second
        int16_t x = (buffer[0] << 8) | buffer[1];
        int16_t y = (buffer[2] << 8) | buffer[3];
        int16_t z = (buffer[4] << 8) | buffer[5];
        x = x * 131.0 / 32768.0;
        y = y * 131.0 / 32768.0;
        z = z * 131.0 / 32768.0;

        // Get current timestamp
        clock_gettime(CLOCK_MONOTONIC, &ts);

        // Log the reading
        fprintf(log_file, "%ld,%f,%f,%f\n", ts.tv_sec * 1000000000 + ts.tv_nsec, x, y, z);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close log file
    fclose(log_file);

    // Clean up
    close(i2c_fd);
    gpiod_chip_close(pwr_mgmt_chip);
    gpiod_line_release(pwr_mgmt_line);

    return 0;
}

