#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define LOG_FILE "distance_log.txt"
#define TIMEOUT_MS 50
#define MIN_GUARD_MS 60

static gpiod_chip *chip;
static gpiod_line *trigger_line, *echo_line;
static FILE *log_file;
static int running = 1;

static void handle_signal(int signum) {
    running = 0;
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

int main() {
    struct timespec start, end;
    long duration_us;
    int distance_cm;
    int ret;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Get the trigger and echo lines
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Failed to get trigger line");
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Failed to get echo line");
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Request the trigger line as output
    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret) {
        perror("Failed to request trigger line as output");
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Request the echo line as input with active-high polarity
    ret = gpiod_line_request_input(echo_line, "echo", GPIOD_LINE_FLAG_ACTIVE_LOW);
    if (ret) {
        perror("Failed to request echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Generate a 10 microsecond high pulse on the trigger
        gpiod_line_set_value(trigger_line, 1);
        usleep(10);
        gpiod_line_set_value(trigger_line, 0);

        // Wait for the echo pulse to start
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 0) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
                perror("Failed to get current time");
                break;
            }
            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_MS) {
                fprintf(log_file, "-1\n");
                fprintf(stderr, "Echo timeout\n");
                break;
            }
        }

        // Wait for the echo pulse to end
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpiod_line_get_value(echo_line) == 1) {
            if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
                perror("Failed to get current time");
                break;
            }
            if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000 > TIMEOUT_MS) {
                fprintf(log_file, "-1\n");
                fprintf(stderr, "Echo timeout\n");
                break;
            }
        }

        // Calculate the pulse width in microseconds
        duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        // Convert the pulse width to distance in centimeters
        distance_cm = duration_us * 0.01715;

        // Log the distance to the file
        fprintf(log_file, "%d\n", distance_cm);

        // Enforce a 60 ms minimum guard between measurements
        usleep(MIN_GUARD_MS * 1000);
    }

    // Release resources
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

