    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    // Open GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(1);
    }

    // Open GPIO line for SDA
    line = gpiod_chip_get_line(chip, 2);
    if (!line) {
        perror("Failed to get GPIO line for SDA");
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(1);
    }

    // Open GPIO line for SCL
    line = gpiod_chip_get_line(chip, 3);
    if (!line) {
        perror("Failed to get GPIO line for SCL");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(1);
    }

    // Set GPIO line direction to output
    ret = gpiod_line_request_output(line, "MPU6050_SDA", 0);
    if (ret) {
