        gpiod_line_close(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(1);
    }

    ret = gpiod_line_request_output(line, "MPU6050_SCL", 0);
    if (ret) {
        perror("Failed to request GPIO line for SCL");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(1);
    }

    // Set I2C speed to 400kHz
    ret = ioctl(i2c_fd, I2C_SET_SPEED, 400000);
    if (ret) {
        perror("Failed to set I2C speed");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(1);
    }

    // Wake up the MPU-6050
    ret = i2c_smbus_write_byte_data(i2c_fd, MPU6050_ADDRESS, PWR_MGMT_1, 0x00);
    if (ret < 0) {
        perror("Failed to wake up MPU-6050");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(1);
    }

    // Set gyroscope full-scale range to ±250 dps
    ret = i2c_smbus_write_byte_data(i2c_fd, MPU6050_ADDRESS, GYRO_CONFIG, 0x00);
    if (ret < 0) {
        perror("Failed to set gyroscope full-scale range");
        gpiod_line_close(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(1);
    }

    while (1) {
        // Read 6 bytes of gyroscope data
        unsigned char data[6];
        ret = i2c_smbus_read_i2c_block_data(i2c_fd, MPU6050_ADDRESS, GYRO_XOUT_H, 6, data);
        if (ret < 0) {
            perror("Failed to read gyroscope data");
            continue;
        }

        // Convert raw signed 16-bit big-endian values to degrees/second
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        // Log the x, y, and z axis readings
        printf("X: %d, Y: %d, Z: %d\n", x, y, z);

        // Sleep for 100ms
        usleep(100000);
    }

    // Clean up
    gpiod_line_close(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
