#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINES 4
#define GPIO_PINS {17, 18, 27, 22}
#define LOG_FILE "watering_log.txt"
#define POLL_INTERVAL 60
#define WATERING_INTERVAL 86400

static gpiod_chip *chip;
static gpiod_line *lines[GPIO_LINES];
static FILE *log_file;
static int running = 1;

static void sigint_handler(int signum) {
    running = 0;
    gpiod_line_release_bulk(lines, GPIO_LINES);
    gpiod_chip_close(chip);
    fclose(log_file);
    exit(EXIT_SUCCESS);
}

static void log_watering_start() {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s\n", timestamp);
}

int main() {
    // Register signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request lines as outputs with active-low semantics
    for (int i = 0; i < GPIO_LINES; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        int flags = GPIOD_LINE_REQUEST_OUTPUT | GPIOD_LINE_REQUEST_ACTIVE_LOW;
        int ret = gpiod_line_request_bulk(lines, "watering", flags, 0);
        if (ret) {
            perror("Failed to request GPIO lines");
            gpiod_line_release_bulk(lines, GPIO_LINES);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Set all lines HIGH (inactive) at startup
    for (int i = 0; i < GPIO_LINES; i++) {
        gpiod_line_set_value(lines[i], 1);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release_bulk(lines, GPIO_LINES);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        log_watering_start();
        for (int i = 0; i < GPIO_LINES; i++) {
            gpiod_line_set_value(lines[i], 0); // Activate relay
            sleep(5); // Watering duration
            gpiod_line_set_value(lines[i], 1); // Deactivate relay
        }
        sleep(WATERING_INTERVAL - POLL_INTERVAL); // Wait until next watering cycle
    }

    // Clean up
    gpiod_line_release_bulk(lines, GPIO_LINES);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

