#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define GPIO_PINS {17, 18, 27, 22}
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE_INCREMENT 1
#define LOG_FILE "smart_lighting.log"
#define LOG_FORMAT "%Y-%m-%d %H:%M:%S - %s\n"

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
}

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, LOG_FORMAT, timestamp, message);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(GPIO_PINS[i], PI_OUTPUT) < 0) {
            perror("Failed to set GPIO mode");
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    if (gpioSetPWMFrequency(GPIO_PINS[0], PWM_FREQUENCY) < 0) {
        perror("Failed to set PWM frequency");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetPWMRange(GPIO_PINS[i], 255) < 0) {
            perror("Failed to set PWM range");
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Sunrise simulation started");

    for (int duty_cycle = 0; duty_cycle <= 255; duty_cycle += PWM_DUTY_CYCLE_INCREMENT) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            if (gpioPWM(GPIO_PINS[i], duty_cycle) < 0) {
                perror("Failed to set PWM duty cycle");
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        log_event("Duty cycle set to %d", duty_cycle);
        sleep(1);
    }

    log_event("Sunrise simulation completed");

    gpioTerminate();

    return EXIT_SUCCESS;
}

