    }

    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set LED pin low\n");
        exit(EXIT_FAILURE);
    }

    if (i2cHandleOpen(&i2c_handle, I2C_BUS, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to open I2C handle\n");
        exit(EXIT_FAILURE);
    }

    // Wake up the MPU-6050
    if (i2cWriteByte(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        exit(EXIT_FAILURE);
    }

    // Set sample rate to 1 kHz
    if (i2cWriteByte(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Failed to set sample rate\n");
        exit(EXIT_FAILURE);
    }

    // Set gyro range to ±250 deg/s
    if (i2cWriteByte(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set gyro range\n");
        exit(EXIT_FAILURE);
    }

    // Verify WHO_AM_I register
    uint8_t who_am_i;
    if (i2cReadByte(i2c_handle, WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        exit(EXIT_FAILURE);
    }
    if (who_am_i != 0x68) {
        fprintf(stderr, "MPU-6050 not found\n");
        exit(EXIT_FAILURE);
    }
}

void read_gyro_data() {
    uint8_t data[6];
    for (int i = 0; i < 3; i++) {
        if (i2cReadBytes(i2c_handle, GYRO_XOUT_H + i * 2, data + i * 2) < 0) {
            fprintf(stderr, "Failed to read gyro data\n");
            exit(EXIT_FAILURE);
        }
    }

    int16_t x = (data[0] << 8) | data[1];
    int16_t y = (data[2] << 8) | data[3];
    int16_t z = (data[4] << 8) | data[5];

    // Convert to degrees/second
    x /= 131.0;
    y /= 131.0;
    z /= 131.0;

    // Store in buffer
    buffer[buffer_index] = (x + y + z) / 3;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    // Check if any axis exceeds 250 deg/s
    if (abs(x) > 250 || abs(y) > 250 || abs(z) > 250) {
        led_state = 1;
    } else {
        led_state = 0;
    }

    // Turn LED on/off
    gpioWrite(LED_PIN, led_state);
}

void main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_mpu6050();

    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);
    last_sample_time = current_time;

    while (1) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (current_time.tv_sec - last_sample_time.tv_sec >= 1) {
            read_gyro_data();
            last_sample_time = current_time;
        }

        // Sleep for the remaining time until the next sample
        struct timespec sleep_time = {0, SAMPLE_PERIOD_MS * 1000000 - (current_time.tv_nsec - last_sample_time.tv_nsec) / 1000};
        nanosleep(&sleep_time, NULL);
    }

    gpioTerminate();
    close(i2c_handle);
}

