#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_LSB_FIRST 0
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47
#define GYRO_SCALE_FACTOR 131.0
#define LOG_FILE "gyro_log.txt"
#define MAX_RETRIES 3

static int spi_fd;
static struct gpiod_chip *gpio_chip;
static struct gpiod_line *cs_line;
static FILE *log_file;

static void sig_handler(int signum) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(signum);
}

static void log_gyro_data(double x_rate, double y_rate, double z_rate) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(log_file, "%ld,%f,%f,%f\n", (long)ts.tv_sec * 1000000000 + ts.tv_nsec, x_rate, y_rate, z_rate);
}

static int read_gyro_data() {
    uint8_t buffer[6];
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = gpiod_line_set_value(cs_line, 0);
        if (ret < 0) {
            perror("Failed to assert CS");
            return -1;
        }

        ret = ioctl(spi_fd, SPI_IOC_MESSAGE, buffer);
        if (ret < 0) {
            perror("SPI read failed");
            ret = gpiod_line_set_value(cs_line, 1);
            if (ret < 0) {
                perror("Failed to deassert CS");
            }
            retries++;
            continue;
        }

        ret = gpiod_line_set_value(cs_line, 1);
        if (ret < 0) {
            perror("Failed to deassert CS");
            return -1;
        }

        int16_t x = (buffer[0] << 8) | buffer[1];
        int16_t y = (buffer[2] << 8) | buffer[3];
        int16_t z = (buffer[4] << 8) | buffer[5];

        double x_rate = x / GYRO_SCALE_FACTOR;
        double y_rate = y / GYRO_SCALE_FACTOR;
        double z_rate = z / GYRO_SCALE_FACTOR;

        log_gyro_data(x_rate, y_rate, z_rate);

        return 0;
    }

    fprintf(stderr, "SPI read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

int main() {
    int ret;

    // Register signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    // Set SPI parameters
    struct spi_ioc_transfer tr = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 6,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .cs_change = 1,
        .delay_usecs = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &SPI_LSB_FIRST);
    if (ret < 0) {
        perror("Failed to set SPI LSB first");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Get GPIO line for CS
    cs_line = gpiod_chip_get_line(gpio_chip, 8);
    if (!cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Request the line for output
    ret = gpiod_line_request_output(cs_line, "gyro_cs", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        gpiod_line_release(cs_line);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(cs_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return EXIT_FAILURE;
    }

    // Log header
    fprintf(log_file, "timestamp,x_rate,y_rate,z_rate\n");

    // Main loop
    while (1) {
        if (read_gyro_data() < 0) {
            sleep(1);
            continue;
        }
        sleep(10);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(cs_line);
    gpiod_chip_close(gpio_chip);
    close(spi_fd);

    return EXIT_SUCCESS;
}

