#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED_HZ 3900000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_BUFFER_SIZE 64
#define BUFFER_SIZE 64
#define LED_PIN 17
#define LED_ON_TIME 500
#define LED_OFF_TIME 500

#define MPU6050_ADDRESS 0x68
#define MPU6050_REG_XOUT_H 0x43
#define MPU6050_REG_XOUT_L 0x44
#define MPU6050_REG_YOUT_H 0x45
#define MPU6050_REG_YOUT_L 0x46
#define MPU6050_REG_ZOUT_H 0x47
#define MPU6050_REG_ZOUT_L 0x48
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_CONFIG 0x1A
#define MPU6050_REG_GYRO_CONFIG 0x1B
#define MPU6050_REG_ACCEL_CONFIG 0x1C
#define MPU6050_REG_INT_ENABLE 0x38
#define MPU6050_REG_INT_STATUS 0x3A
#define MPU6050_REG_WHO_AM_I 0x75
#define MPU6050_WHO_AM_I_VALUE 0x68

#define MAX_ERROR_MSG_LEN 256

typedef struct {
    uint32_t timestamp;
    int16_t x, y, z;
} GyroscopeReading;

GyroscopeReading buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int buffer_count = 0;

int spi_fd = -1;
int gpio_fd = -1;
int led_fd = -1;

void handle_sigint(int signum) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_fd != -1) {
        gpio_close(gpio_fd);
    }
    if (led_fd != -1) {
        close(led_fd);
    }
    exit(0);
}

void init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer transfer;
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)NULL;
    transfer.rx_buf = (unsigned long)NULL;
    transfer.len = 0;
    transfer.speed_hz = SPI_SPEED_HZ;
    transfer.bits_per_word = SPI_BITS_PER_WORD;
    transfer.cs_change = 1;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) == -1) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) == -1) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED_HZ) == -1) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

