    gpio_fd = gpio_open(0, 0);
    if (gpio_fd == -1) {
        perror("Failed to open GPIO");
        exit(EXIT_FAILURE);
    }

    led_fd = gpio_export(LED_PIN, GPIO_OUTPUT);
    if (led_fd == -1) {
        perror("Failed to export LED GPIO");
