}

void init_mpu6050() {
    uint8_t who_am_i = 0;
    if (spi_transfer(spi_fd, &who_am_i, 1, 1) != 1) {
        perror("Failed to read WHO_AM_I register");
        exit(EXIT_FAILURE);
    }

    if (who_am_i != MPU6050_WHO_AM_I_VALUE) {
        fprintf(stderr, "Failed to find MPU6050, expected 0x68, got 0x%02X\n", who_am_i);
        exit(EXIT_FAILURE);
    }

    // Configure the MPU6050
    uint8_t config = 0x00; // Set to 0 for normal mode
    if (spi_transfer(spi_fd, &config, 1, 1) != 1) {
        perror("Failed to write CONFIG register");
        exit(EXIT_FAILURE);
    }

    uint8_t gyro_config = 0x08; // Set to 0x08 for 2000 deg/s, 200 Hz
    if (spi_transfer(spi_fd, &gyro_config, 1, 1) != 1) {
        perror("Failed to write GYRO_CONFIG register");
        exit(EXIT_FAILURE);
    }

    uint8_t accel_config = 0x00; // Set to 0x00 for 2g, 200 Hz
    if (spi_transfer(spi_fd, &accel_config, 1, 1) != 1) {
        perror("Failed to write ACCEL_CONFIG register");
        exit(EXIT_FAILURE);
    }

    uint8_t int_enable = 0x00; // Disable interrupts
    if (spi_transfer(spi_fd, &int_enable, 1, 1) != 1) {
        perror("Failed to write INT_ENABLE register");
        exit(EXIT_FAILURE);
    }
}

void spi_transfer(uint8_t *tx, uint8_t *rx, size_t len, size_t count) {
    struct spi_ioc_transfer transfer[count];
    memset(transfer, 0, sizeof(transfer));

    for (size_t i = 0; i < count; i++) {
        transfer[i].tx_buf = (unsigned long)tx;
        transfer[i].rx_buf = (unsigned long)rx;
        transfer[i].len = 1;
        transfer[i].speed_hz = SPI_SPEED_HZ;
        transfer[i].bits_per_word = SPI_BITS_PER_WORD;
        transfer[i].cs_change = 1;
    }

