    int16_t y = (data[2] << 8) | data[3];
    int16_t z = (data[4] << 8) | data[5];

    if (x == 0 || y == 0 || z == 0) {
        fprintf(stderr, "Invalid gyroscope data\n");
        return;
    }

    GyroscopeReading reading;
    reading.timestamp = time(NULL);
    reading.x = x;
    reading.y = y;
    reading.z = z;

    if (buffer_count < BUFFER_SIZE) {
        buffer[buffer_head] = reading;
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
        buffer_count++;
    } else {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
        buffer[buffer_tail] = reading;
