#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

#define LED_PIN 21
#define LOG_FILE "tilt_log.txt"

int i2c_handle;
int led_pin;
FILE *log_file;

void log_tilt(double roll, double pitch) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    printf("Tilt: Roll = %.2f, Pitch = %.2f\n", roll, pitch);
}

void handle_sigint(int signum) {
    gpioWrite(led_pin, 0);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    led_pin = LED_PIN;
    if (gpioSetMode(led_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Wake up the sensor
    if (i2cWriteByte(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set accelerometer full-scale range to ±2g
    if (i2cWriteByte(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer full-scale range\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Log initial configuration
    log_tilt(0, 0);

    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (1) {
        uint8_t data[6];
        if (i2cReadBlockData(i2c_handle, ACCEL_XOUT_H, data, 6) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        double roll = atan2(y, z) * 180 / M_PI;
        double pitch = atan2(-x, sqrt(y * y + z * z)) * 180 / M_PI;

        log_tilt(roll, pitch);

        if (fabs(roll) > 45 || fabs(pitch) > 45) {
            gpioWrite(led_pin, 1);
        } else {
            gpioWrite(led_pin, 0);
        }

        usleep(100000); // Sleep for 100 ms
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

