#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x5A
#define REG_AMBIENT 0x20
#define REG_PROXIMITY 0x22
#define LED_PIN 17
#define MAX_RETRIES 3
#define LOG_FILE "biometric_log.txt"

static int i2c_fd;
static int led_pin_fd;
static FILE *log_file;

static void log_reading(const char *timestamp, int ambient, int proximity) {
    fprintf(log_file, "%s,AmbientLight:%04X,Proximity:%04X\n", timestamp, ambient, proximity);
    fflush(log_file);
}

static void handle_signal(int signum) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (led_pin_fd >= 0) {
        gpiod_line_set_value(led_pin_fd, 0);
        gpiod_line_release(led_pin_fd);
    }
    exit(0);
}

static void setup_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void setup_gpio() {
    led_pin_fd = gpiod_line_request_output(LED_PIN, "biometric_sensor", 0);
    if (led_pin_fd < 0) {
        perror("Failed to request GPIO line");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void setup_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpiod_line_release(led_pin_fd);
        exit(EXIT_FAILURE);
    }
}

static void read_sensor() {
    uint8_t buffer[4];
    int retries = 0;
    int success = 0;

    while (retries < MAX_RETRIES && !success) {
        if (write(i2c_fd, &REG_AMBIENT, 1) != 1) {
            perror("Failed to write to I2C");
            retries++;
            usleep(10000);
            continue;
        }
        if (read(i2c_fd, buffer, 2) != 2) {
            perror("Failed to read from I2C");
            retries++;
            usleep(10000);
            continue;
        }
        if (write(i2c_fd, &REG_PROXIMITY, 1) != 1) {
            perror("Failed to write to I2C");
            retries++;
            usleep(10000);
            continue;
        }
        if (read(i2c_fd, buffer + 2, 2) != 2) {
            perror("Failed to read from I2C");
            retries++;
            usleep(10000);
            continue;
        }
        success = 1;
    }

    if (!success) {
        fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
        return;
    }

    int ambient = (buffer[0] << 8) | buffer[1];
    int proximity = (buffer[2] << 8) | buffer[3];

    log_reading(strftime(NULL, sizeof(NULL), "%Y-%m-%d %H:%M:%S", NULL), ambient, proximity);

    if (proximity > 100) {
        gpiod_line_set_value(led_pin_fd, 1);
    } else {
        gpiod_line_set_value(led_pin_fd, 0);
    }
}

