#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_ADDRESS_X 0x02
#define SPI_ADDRESS_Y 0x04
#define SPI_READ_BIT 0x80
#define SPI_DUMMY_BYTE 0x00
#define LOG_FILE "gyro_data.csv"
#define MAX_RETRIES 3

static int spiHandle;
static FILE *logFile;
static volatile sig_atomic_t exitFlag = 0;

void sigintHandler(int signum) {
    exitFlag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((logFile = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        spiClose(spiHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fprintf(logFile, "timestamp, X rate, Y rate\n");

    struct timespec delay = {0, 10000000}; // 10 ms delay

    for (int i = 0; !exitFlag; i++) {
        int retries = 0;
        int xRate, yRate;

        while (retries < MAX_RETRIES) {
            int result = spiXfer(spiHandle, SPI_ADDRESS_X | SPI_READ_BIT, &SPI_DUMMY_BYTE, 2, &xRate);
            if (result == 2) {
                break;
            }
            retries++;
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read X rate after %d retries\n", MAX_RETRIES);
            continue;
        }

        retries = 0;

        while (retries < MAX_RETRIES) {
            int result = spiXfer(spiHandle, SPI_ADDRESS_Y | SPI_READ_BIT, &SPI_DUMMY_BYTE, 2, &yRate);
            if (result == 2) {
                break;
            }
            retries++;
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read Y rate after %d retries\n", MAX_RETRIES);
            continue;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double timestamp = now.tv_sec + now.tv_nsec / 1e9;

        fprintf(logFile, "%.9f, %d, %d\n", timestamp, xRate, yRate);

        nanosleep(&delay, NULL);
    }

    fclose(logFile);
    spiClose(spiHandle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

