        fprintf(stderr, "Failed to set pull-up/down for SEISMIC_PIN2\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(SEISMIC_PIN1, seismic_callback1) < 0) {
        fprintf(stderr, "Failed to set alert function for SEISMIC_PIN1\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(SEISMIC_PIN2, seismic_callback2) < 0) {
        fprintf(stderr, "Failed to set alert function for SEISMIC_PIN2\n");
        gpioTerminate();
        return 1;
    }

