        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        if (seismic1_state && seismic2_state) {
            alert();
            log_event("Seismic event detected!");
        }
        usleep(100000); // Sleep for 100ms
    }

    fclose(log_fd);
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
    return 0;
}

