#include <pigpio.h>
#include <pthread.h>

#define SPI_CHANNEL 0
#define SPI_CLOCK_SPEED_HZ 1000000
#define SPI_MODE 0
#define SPI_BUFFER_SIZE 2
#define SPI_ADDRESS_SIZE 2
#define SPI_READ_BIT 0x80
#define SPI_BUFFER_CAPACITY 100
#define LED_PIN 17
#define THRESHOLD 20.0

typedef struct {
    uint16_t data;
    struct timespec timestamp;
} GyroReading;

GyroReading buffer[SPI_BUFFER_CAPACITY];
int buffer_head = 0;
int buffer_tail = 0;
int buffer_count = 0;

volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    running = 0;
}

void* read_gyro(void* arg) {
    int fd = pigpio_start(0, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(fd, LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(fd, LED_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set LED pin pull-up\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(fd, SPI_CHANNEL, PI_ALT0) < 0) {
        fprintf(stderr, "Failed to set SPI channel mode\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMFrequency(fd, SPI_CLOCK_SPEED_HZ) < 0) {
        fprintf(stderr, "Failed to set SPI clock frequency\n");
        exit(EXIT_FAILURE);
    }

    uint8_t address[SPI_ADDRESS_SIZE] = {SPI_READ_BIT | 0x02, SPI_READ_BIT | 0x03};
    uint8_t buffer[SPI_BUFFER_SIZE];
    int bytes_read;

    while (running) {
        if (gpioHardwareSPIRead(fd, address, SPI_ADDRESS_SIZE) < 0) {
            fprintf(stderr, "Failed to read from SPI\n");
            break;
        }

        if (gpioHardwareSPIRead(fd, buffer, SPI_BUFFER_SIZE) < 0) {
            fprintf(stderr, "Failed to read from SPI\n");
            break;
        }

        GyroReading reading;
        reading.data = (buffer[0] << 8) | buffer[1];
        clock_gettime(CLOCK_MONOTONIC, &reading.timestamp);

        pthread_mutex_lock(&buffer_mutex);
        if (buffer_count < SPI_BUFFER_CAPACITY) {
            buffer[buffer_head] = reading;
            buffer_head = (buffer_head + 1) % SPI_BUFFER_CAPACITY;
            buffer_count++;
        }
        pthread_mutex_unlock(&buffer_mutex);

        double rate = (double)reading.data * 200.0 / 32768.0;
        if (rate > THRESHOLD) {
            gpioWrite(fd, LED_PIN, 1);
        } else {
            gpioWrite(fd, LED_PIN, 0);
        }
    }

    gpioTerminate(fd);
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, read_gyro, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        sleep(1);
    }

    pthread_join(thread, NULL);
    gpioTerminate();
    return EXIT_SUCCESS;
}

