        fprintf(stderr, "Failed to set SPI channel mode\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMFrequency(fd, SPI_CLOCK_SPEED_HZ) < 0) {
        fprintf(stderr, "Failed to set SPI clock frequency\n");
        exit(EXIT_FAILURE);
    }

    uint8_t address[SPI_ADDRESS_SIZE] = {SPI_READ_BIT | 0x02, SPI_READ_BIT | 0x03};
    uint8_t buffer[SPI_BUFFER_SIZE];
    int bytes_read;

    while (running) {
        if (gpioHardwareSPIRead(fd, address, SPI_ADDRESS_SIZE) < 0) {
            fprintf(stderr, "Failed to read from SPI\n");
            break;
        }

        if (gpioHardwareSPIRead(fd, buffer, SPI_BUFFER_SIZE) < 0) {
            fprintf(stderr, "Failed to read from SPI\n");
            break;
        }

        GyroReading reading;
        reading.data = (buffer[0] << 8) | buffer[1];
        clock_gettime(CLOCK_MONOTONIC, &reading.timestamp);

        pthread_mutex_lock(&buffer_mutex);
        if (buffer_count < SPI_BUFFER_CAPACITY) {
            buffer[buffer_head] = reading;
            buffer_head = (buffer_head + 1) % SPI_BUFFER_CAPACITY;
            buffer_count++;
        }
        pthread_mutex_unlock(&buffer_mutex);

        double rate = (double)reading.data * 200.0 / 32768.0;
        if (rate > THRESHOLD) {
            gpioWrite(fd, LED_PIN, 1);
        } else {
            gpioWrite(fd, LED_PIN, 0);
        }
    }

    gpioTerminate(fd);
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, read_gyro, NULL) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        sleep(1);
    }

    pthread_join(thread, NULL);
    gpioTerminate();
    return EXIT_SUCCESS;
}
