#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>

#define NUM_RELAYS 3
#define RELAY_PINS {17, 18, 27}
#define PWM_RANGE 255
#define PWM_FREQUENCY 100
#define MAX_DURATION 3600

static int gpio_fd[NUM_RELAYS];
static int pwm_handle[NUM_RELAYS];
static int duration;

void cleanup() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWMWrite(gpio_fd[i], pwm_handle[i], 0);
        gpioPWMWrite(gpio_fd[i], 0, 0);
        gpioTerminate();
    }
    printf("All lamps turned off and resources released.\n");
}

void handle_signal(int sig) {
    printf("Received signal %d, turning off all lamps and releasing resources.\n", sig);
    cleanup();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_in_seconds>\n", argv[0]);
        return 1;
    }

    duration = atoi(argv[1]);
    if (duration < 1 || duration > MAX_DURATION) {
        fprintf(stderr, "Duration must be between 1 and %d seconds.\n", MAX_DURATION);
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpio_fd[i] = gpioOpen(RELAY_PINS[i], OUTPUT);
        if (gpio_fd[i] < 0) {
            fprintf(stderr, "Failed to open GPIO pin %d.\n", RELAY_PINS[i]);
            cleanup();
            return 1;
        }
        pwm_handle[i] = gpioPWM(RELAY_PINS[i], PWM_RANGE, 0);
        if (pwm_handle[i] < 0) {
            fprintf(stderr, "Failed to set PWM on GPIO pin %d.\n", RELAY_PINS[i]);
            cleanup();
            return 1;
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    printf("Smart sunset simulator started. Duration: %d seconds.\n", duration);

    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioPWMWrite(gpio_fd[i], pwm_handle[i], PWM_RANGE);
        printf("Lamp %d starting fade to off.\n", i + 1);
        for (int j = PWM_RANGE; j >= 0; j--) {
            gpioPWMWrite(gpio_fd[i], pwm_handle[i], j);
            usleep(1000000 / PWM_FREQUENCY);
        }
        printf("Lamp %d fade complete.\n", i + 1);
    }

    cleanup();
    return 0;
}

