#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define RED_PIN 17
#define YELLOW_PIN 22
#define GREEN_PIN 23
#define BLUE_PIN 24
#define DELAY_RED 10
#define DELAY_RED_YELLOW 2
#define DELAY_GREEN 10
#define DELAY_YELLOW 3

static gpiod_chip *chip;
static gpiod_line *lines[NUM_RELAYS];
static int state = 0;

void signal_handler(int signum) {
    if (chip) {
        gpiod_chip_close(chip);
    }
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    exit(signum);
}

void set_state(int new_state) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_set_value(lines[i], new_state == i);
    }
    state = new_state;
    printf("State: %d\n", state);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, i);
        if (!lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(lines[i], "traffic_light", 0)) {
            perror("Failed to request GPIO line as output");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Set initial state
    set_state(0);

    // Main loop
    while (1) {
        switch (state) {
            case 0:
                set_state(1); // Red
                sleep(DELAY_RED);
                break;
            case 1:
                set_state(2); // Red + Yellow
                sleep(DELAY_RED_YELLOW);
                break;
            case 2:
                set_state(3); // Green
                sleep(DELAY_GREEN);
                break;
            case 3:
                set_state(0); // Yellow
                sleep(DELAY_YELLOW);
                break;
        }
    }

    // This line is never reached, but it's here to satisfy the compiler
    return 0;
}

