#define LOG_FILE "touch_relay.log"
#define RELAY_PIN 17
#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define TOUCH_STATUS_REG 0x00
#define TOUCH_STATUS_REG_MSB 0x01
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE 0x21
#define CHARGE_TIME 0x0D
#define RUN_MODE 0x0D

static int i2c_handle;
static FILE *log_file;
static int running = 1;

void log_error(const char *func, const char *msg) {
    time_t now;
    struct tm *tm_info;
    char buffer[80];

    time(&now);
    tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s - %s: %s\n", buffer, func, msg);
}

void handle_signal(int sig) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("gpioInitialise", "Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        log_error("gpioSetMode", "Failed to set GPIO mode for relay");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioWrite(RELAY_PIN, 0) < 0) {
        log_error("gpioWrite", "Failed to set relay to LOW");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        log_error("i2cOpen", "Failed to open I2C device");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (i2cWriteByte(i2c_handle, 0x80) < 0) {
        log_error("i2cWriteByte", "Failed to reset MPR121");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (i2cWriteByte(i2c_handle, 0x5E) < 0) {
        log_error("i2cWriteByte", "Failed to stop MPR121");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (i2cWriteByte(i2c_handle, 0x5D) < 0) {
        log_error("i2cWriteByte", "Failed to enable electrode 0");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (i2cWriteByte(i2c_handle, TOUCH_THRESHOLD) < 0) {
        log_error("i2cWriteByte", "Failed to set touch threshold");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (i2cWriteByte(i2c_handle, RELEASE_THRESHOLD) < 0) {
        log_error("i2cWriteByte", "Failed to set release threshold");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (i2cWriteByte(i2c_handle, DEBOUNCE) < 0) {
        log_error("i2cWriteByte", "Failed to set debounce");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (i2cWriteByte(i2c_handle, CHARGE_TIME) < 0) {
        log_error("i2cWriteByte", "Failed to set charge time");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (i2cWriteByte(i2c_handle, RUN_MODE) < 0) {
        log_error("i2cWriteByte", "Failed to set run mode");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        log_error("fopen", "Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        uint8_t status[2];
        if (i2cReadBytes(i2c_handle, TOUCH_STATUS_REG, 2, status) < 0) {
            log_error("i2cReadBytes", "Failed to read touch status");
            continue;
        }

        if (status[0] & 0x01) {
            if (gpioWrite(RELAY_PIN, 1) < 0) {
                log_error("gpioWrite", "Failed to set relay to HIGH");
            }
        } else {
            if (gpioWrite(RELAY_PIN, 0) < 0) {
                log_error("gpioWrite", "Failed to set relay to LOW");
            }
        }

        usleep(100000); // 100 ms delay
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

