#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO17 17
#define GPIO27 27
#define DISPENSE_DURATION_MS 1000
#define DELAY_BETWEEN_DISPENSES_MS 5000

static volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int signum) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as output\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO27 as output\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("dispense_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open dispense_log.txt for writing\n");
        gpioTerminate();
        return 1;
    }

    struct timespec start_time, end_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (!exit_flag) {
        // Activate solenoid 1
        gpioWrite(GPIO17, 1);
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        gpioDelay(DISPENSE_DURATION_MS / 2 * 1000);
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        gpioWrite(GPIO17, 0);

        // Activate solenoid 2
        gpioWrite(GPIO27, 1);
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        gpioDelay(DISPENSE_DURATION_MS / 2 * 1000);
        clock_gettime(CLOCK_MONOTONIC, &end_time);
        gpioWrite(GPIO27, 0);

        // Log the dispense event
        fprintf(log_file, "%ld,%d,%d,%ld\n", start_time.tv_sec * 1000000 + start_time.tv_nsec / 1000,
                GPIO17, GPIO27, (end_time.tv_sec * 1000000 + end_time.tv_nsec / 1000) - (start_time.tv_sec * 1000000 + start_time.tv_nsec / 1000));

        // Wait for the next dispense
        clock_gettime(CLOCK_MONOTONIC, &start_time);
        gpioDelay(DELAY_BETWEEN_DISPENSES_MS * 1000);
        clock_gettime(CLOCK_MONOTONIC, &end_time);
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
}

