#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENA 24
#define ENB 25
#define LOG_FILE "balance_log.txt"
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1
#define MAX_SPEED 255
#define MIN_SPEED 0
#define OBSTACLE_DISTANCE 20.0
#define MAX_DISTANCE 400.0
#define MIN_DISTANCE 2.0
#define SAMPLE_PERIOD 50000  // 50 ms

static int motor_a_speed = 0;
static int motor_b_speed = 0;
static FILE *log_file;
static int tilt_error = 0;
static float distance = 0.0;
static float integral = 0.0;
static float derivative = 0.0;
static float last_error = 0.0;
static int obstacle_detected = 0;

void log_data() {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%d,%d\n",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec,
            tilt_error, distance, motor_a_speed, motor_b_speed);
}

void signal_handler(int signum) {
    if (signum == SIGINT) {
        motor_a_speed = 0;
        motor_b_speed = 0;
        fclose(log_file);
        gpioTerminate();
        printf("Program terminated by user.\n");
        exit(0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }
    signal(SIGINT, signal_handler);

    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);

    gpioPWM(ENA, MAX_SPEED);
    gpioPWM(ENB, MAX_SPEED);

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s.\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    srand(time(NULL));

    while (1) {
        tilt_error = rand() % 21 - 10;  // Random tilt error between -10 and 10 degrees
        distance = (rand() % (int)(MAX_DISTANCE - MIN_DISTANCE + 1)) + MIN_DISTANCE;  // Random distance between 2 and 400 cm

        if (distance < OBSTACLE_DISTANCE) {
            obstacle_detected = 1;
            motor_a_speed = MAX_SPEED / 2;
            motor_b_speed = MAX_SPEED / 2;
        } else {
            obstacle_detected = 0;
            integral += tilt_error * SAMPLE_PERIOD / 1000.0;
            derivative = (tilt_error - last_error) * SAMPLE_PERIOD / 1000.0;
            last_error = tilt_error;

            float control_signal = Kp * tilt_error + Ki * integral + Kd * derivative;

            motor_a_speed = (int)(control_signal + 0.5);
            motor_b_speed = (int)(control_signal + 0.5);

            if (motor_a_speed > MAX_SPEED) motor_a_speed = MAX_SPEED;
            if (motor_a_speed < MIN_SPEED) motor_a_speed = MIN_SPEED;
            if (motor_b_speed > MAX_SPEED) motor_b_speed = MAX_SPEED;
            if (motor_b_speed < MIN_SPEED) motor_b_speed = MIN_SPEED;
        }

        gpioPWM(MOTOR_A_FORWARD, motor_a_speed);
        gpioPWM(MOTOR_A_BACKWARD, 0);
        gpioPWM(MOTOR_B_FORWARD, motor_b_speed);
        gpioPWM(MOTOR_B_BACKWARD, 0);

        log_data();

        usleep(SAMPLE_PERIOD);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

