#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_DELAY 50000  // 50 ms in microseconds

static volatile sig_atomic_t quit = 0;

void signal_handler(int sig) {
    quit = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d mode\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d mode\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up pull-down resistor on touch pin
    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO%d\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
