#define DEBOUNCE_DELAY 50000  // 50 ms in microseconds

static volatile sig_atomic_t quit = 0;

void signal_handler(int sig) {
    quit = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

