    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d mode\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
