        fprintf(stderr, "Failed to set GPIO%d mode\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up pull-down resistor on touch pin
    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO%d\n", TOUCH_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch the TTP223 capacitive touch sensor on GPIO%d to toggle the relay on GPIO%d\n", TOUCH_PIN, RELAY_PIN);

    while (!quit) {
        // Wait for touch
        if (gpioRead(TOUCH_PIN) == 1) {
            // Debounce
            usleep(DEBOUNCE_DELAY);

