#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define CLEAR_LOW 0x14
#define CLEAR_HIGH 0x15
#define RED_LOW 0x16
#define RED_HIGH 0x17
#define GREEN_LOW 0x18
#define GREEN_HIGH 0x19
#define BLUE_LOW 0x1A
#define BLUE_HIGH 0x1B
#define RGBC_ENABLE 0x80
#define INTEGRATION_TIME 0x81

static int i2c_handle;
static FILE *csv_file;

void sig_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (csv_file) {
            fclose(csv_file);
        }
        if (i2c_handle != -1) {
            i2c_close(i2c_handle);
        }
        gpioTerminate();
        exit(0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpioSetSignalFunc(SIGINT, sig_handler);
    gpioSetSignalFunc(SIGTERM, sig_handler);

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        return 1;
    }

    // Initialize the sensor
    if (i2cWriteByteData(i2c_handle, RGBC_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Failed to enable RGBC\n");
        i2cWriteByteData(i2c_handle, RGBC_ENABLE, 0x00);
    }
    if (i2cWriteByteData(i2c_handle, INTEGRATION_TIME, 0xD5) < 0) {
        fprintf(stderr, "Failed to set integration time\n");
        i2cWriteByteData(i2c_handle, INTEGRATION_TIME, 0x00);
    }

    if ((csv_file = fopen("color_data.csv", "w")) == NULL) {
        fprintf(stderr, "Failed to open color_data.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(csv_file, "timestamp,C, R, G, B\n");

    while (1) {
        struct timespec sleep_time = {0, 500000000}; // 500 ms
        nanosleep(&sleep_time, NULL);

        uint16_t clear_low, clear_high, red_low, red_high, green_low, green_high, blue_low, blue_high;
        if (i2cReadBlockData(i2c_handle, CLEAR_LOW, &clear_low, 2) < 0) {
            fprintf(stderr, "Failed to read clear low\n");
            clear_low = 0;
        }
        if (i2cReadBlockData(i2c_handle, CLEAR_HIGH, &clear_high, 2) < 0) {
            fprintf(stderr, "Failed to read clear high\n");
            clear_high = 0;
        }
        if (i2cReadBlockData(i2c_handle, RED_LOW, &red_low, 2) < 0) {
            fprintf(stderr, "Failed to read red low\n");
            red_low = 0;
