#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define RELAY_PINS {17, 27, 22, 23}
#define PWM_DUTY_CYCLE_INCREMENT 10
#define PWM_DUTY_CYCLE_MAX 100
#define PWM_DUTY_CYCLE_MIN 0
#define PHASE_DURATION_SECONDS 3600
#define NIGHTTIME_DURATION_SECONDS 14400

static gpiod_chip *chip;
static gpiod_line *lines[NUM_RELAYS];
static int duty_cycle = PWM_DUTY_CYCLE_MIN;
static int phase = 0;
static int running = 1;

void handle_signal(int signum) {
    running = 0;
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_set_value(lines[i], 1); // Turn off all relays
    }
    gpiod_line_release(lines[0]);
    gpiod_line_release(lines[1]);
    gpiod_line_release(lines[2]);
    gpiod_line_release(lines[3]);
    gpiod_chip_close(chip);
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for the relays
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_line_get(chip, RELAY_PINS[i]);
        if (!lines[i]) {
            perror("Failed to get line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        if (gpiod_line_request_output(lines[i], "relay", 0)) {
            perror("Failed to request line as output");
            gpiod_line_release(lines[0]);
            gpiod_line_release(lines[1]);
            gpiod_line_release(lines[2]);
            gpiod_line_release(lines[3]);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    while (running) {
        switch (phase) {
            case 0: // Sunrise
                duty_cycle += PWM_DUTY_CYCLE_INCREMENT;
                if (duty_cycle > PWM_DUTY_CYCLE_MAX) {
                    duty_cycle = PWM_DUTY_CYCLE_MAX;
                    phase = 1;
                }
                break;
            case 1: // Daytime
                duty_cycle = PWM_DUTY_CYCLE_MAX;
                break;
            case 2: // Sunset
                duty_cycle -= PWM_DUTY_CYCLE_INCREMENT;
                if (duty_cycle < PWM_DUTY_CYCLE_MIN) {
                    duty_cycle = PWM_DUTY_CYCLE_MIN;
                    phase = 3;
                }
                break;
            case 3: // Nighttime
                duty_cycle = PWM_DUTY_CYCLE_MIN;
                break;
        }

        for (int i = 0; i < NUM_RELAYS; i++) {
            gpiod_line_set_value(lines[i], duty_cycle > PWM_DUTY_CYCLE_MIN);
        }

        sleep(PHASE_DURATION_SECONDS);
        phase = (phase + 1) % 4;
    }

    // Clean up
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);

    return 0;
}

