#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define DEBOUNCE_INTERVAL 200

static int motion_detected = 0;
static FILE *log_file;
static time_t last_motion_time;

void sigint_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio\n");
    }
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        int current_time = time(NULL);
        if (current_time - last_motion_time >= DEBOUNCE_INTERVAL) {
            int level = gpioRead(GPIO_PIN);
            if (level == 0 && !motion_detected) {
                motion_detected = 1;
                char filename[100];
                time_t now = time(NULL);
                struct tm *tm = localtime(&now);
                strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.h264", tm);
                char full_path[100];
                snprintf(full_path, sizeof(full_path), "%s%s", VIDEO_DIR, filename);
                if (system("raspivid -o " full_path " -t 5000") != 0) {
                    fprintf(stderr, "Failed to record video\n");
                }
                fprintf(log_file, "%s\n", ctime(&now));
                last_motion_time = current_time;
            }
        }
        usleep(100000); // Sleep for 100 ms
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

