#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define MPU6050_ADDRESS 0x68
#define I2C_BUS 1
#define SAMPLE_RATE_DIVIDER 125
#define GYRO_FULL_SCALE_RANGE 250
#define GYRO_SENSITIVITY 131.0
#define LOG_FILE "gyro_log.csv"
#define MAX_RETRIES 3

static int i2c_handle;
static FILE *log_file;
static int retries = 0;

void sig_handler(int signum) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    exit(signum);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if ((i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDRESS, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Wake up the MPU-6050
    if (i2cWriteByteData(i2c_handle, 0x6B, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        return 1;
    }

    // Set sample rate divider
    if (i2cWriteByteData(i2c_handle, 0x19, SAMPLE_RATE_DIVIDER) < 0) {
        fprintf(stderr, "Failed to set sample rate divider\n");
        return 1;
    }

    // Set gyroscope full-scale range
    if (i2cWriteByteData(i2c_handle, 0x1B, GYRO_FULL_SCALE_RANGE) < 0) {
        fprintf(stderr, "Failed to set gyroscope full-scale range\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");

    struct timespec sleep_time = {0, 10000000}; // 10 ms

    while (1) {
        int retries = 0;
        while (retries < MAX_RETRIES) {
            uint8_t data[6];
            if (i2cReadI2CBlockData(i2c_handle, 0x43, data, 6) < 0) {
                fprintf(stderr, "Failed to read gyroscope data\n");
                retries++;
                continue;
            }
            break;
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read gyroscope data after %d retries\n", MAX_RETRIES);
            continue;
        }

        // Convert raw data to degrees per second
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];
        float x_degps = x / GYRO_SENSITIVITY;
        float y_degps = y / GYRO_SENSITIVITY;
        float z_degps = z / GYRO_SENSITIVITY;

        // Get current timestamp
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double timestamp = now.tv_sec + now.tv_nsec / 1000000000.0;

        // Write data to log file
        fprintf(log_file, "%.9f,%f,%f,%f\n", timestamp, x_degps, y_degps, z_degps);

        // Sleep for 10 ms
        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

