        while (retries < MAX_RETRIES) {
            uint8_t data[6];
            if (i2cReadI2CBlockData(i2c_handle, 0x43, data, 6) < 0) {
                fprintf(stderr, "Failed to read gyroscope data\n");
                retries++;
                continue;
            }
            break;
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read gyroscope data after %d retries\n", MAX_RETRIES);
            continue;
        }

        // Convert raw data to degrees per second
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];
        float x_degps = x / GYRO_SENSITIVITY;
        float y_degps = y / GYRO_SENSITIVITY;
        float z_degps = z / GYRO_SENSITIVITY;

        // Get current timestamp
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double timestamp = now.tv_sec + now.tv_nsec / 1000000000.0;

        // Write data to log file
        fprintf(log_file, "%.9f,%f,%f,%f\n", timestamp, x_degps, y_degps, z_degps);

        // Sleep for 10 ms
        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}
```

This C program initializes the MPU-6050 gyroscope on a Raspberry Pi 4 Model B using the pigpio library. It reads the raw signed 16-bit gyroscope values from registers 0x43-0x48, converts them to degrees per second, and logs each reading to a CSV file with columns for timestamp and each gyroscope axis. The program handles read failures by attempting sensor re-initialization up to 3 times before logging an error and continuing. It also includes a SIGINT/SIGTERM handler to close the log file and release the I2C handle, and runs indefinitely until interrupted.

