    while (1) {
        for (int i = 0; i < NUM_RELAYS; i++) {
            int moisture_reading = rand() % 101;
            fprintf(log_file, "%d, %d, %d\n", moisture_reading, moisture_reading < 30 ? 0 : 1, time(NULL));
            fflush(log_file);
            gpioWrite(gpio_handle[i], moisture_reading < 30 ? 0 : 1); // Activate or deactivate relay
        }
        usleep(READ_INTERVAL);
    }

    fclose(log_file);
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(gpio_handle[i], 1); // Deactivate all relays
    }
    gpioTerminate();

    return 0;
}

