#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_ADDRESS 0x53
#define DATA_FORMAT_REG 0x31
#define POWER_CTL_REG 0x2D
#define DATAX0_REG 0x32
#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 5000
#define LOG_FILE "freefall.log"
#define GPIO_ALARM 27

static int i2c_handle;
static int gpio_alarm_handle;
static int freefall_detected = 0;
static int freefall_start_time = 0;

static void sigint_handler(int signum) {
    if (i2c_handle != -1) {
        i2c_close(i2c_handle);
    }
    if (gpio_alarm_handle != -1) {
        gpio_write(gpio_alarm_handle, 0);
        gpio_close(gpio_alarm_handle);
    }
    pigpio_stop();
    exit(0);
}

static void log_freefall(double x, double y, double z) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(log_file);
}

static void read_accelerometer() {
    uint8_t data[6];
    if (i2c_read_i2c_block_data(i2c_handle, DATAX0_REG, 6, data) != 6) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return;
    }

    int16_t x = (data[0] << 8) | data[1];
    int16_t y = (data[2] << 8) | data[3];
    int16_t z = (data[4] << 8) | data[5];

    double x_g = (double)x / 256.0;
    double y_g = (double)y / 256.0;
    double z_g = (double)z / 256.0;

    if (freefall_detected) {
        if (freefall_start_time + FREEFALL_DURATION < time(NULL) * 1000) {
            freefall_detected = 0;
            gpio_write(gpio_alarm_handle, 0);
        }
    } else {
        if (x_g < -FREEFALL_THRESHOLD && y_g < -FREEFALL_THRESHOLD && z_g < -FREEFALL_THRESHOLD) {
            freefall_detected = 1;
            freefall_start_time = time(NULL) * 1000;
            gpio_write(gpio_alarm_handle, 1);
            gpio_write(gpio_alarm_handle, 0);
            log_freefall(x_g, y_g, z_g);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpioAlarmSet(100, read_accelerometer, 0);
    gpioAlarmEnable(100);

    if (i2cOpen(1, I2C_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, DATA_FORMAT_REG, 0x0B) < 0) {
        fprintf(stderr, "Failed to set data format\n");
        return 1;
    }

    if (i2cWriteByteData(i2c_handle, POWER_CTL_REG, 0x08) < 0) {
        fprintf(stderr, "Failed to enable measurement mode\n");
        return 1;
    }

    gpio_alarm_handle = gpioCreateEventISR(0, RISING_EDGE, GPIO_ALARM, NULL);
    if (gpio_alarm_handle < 0) {
        fprintf(stderr, "Failed to create GPIO alarm\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        sleep(1);
    }

    return 0;
}

