#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define OUT_X_L 0x28
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define Buzzer_PIN 17
#define MAX_RETRIES 3
#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 1.5

static int gpiod_handle;
static int i2c_handle;
static int retries = 0;
static int freefall_detected = 0;
static int impact_detected = 0;

void handle_sigint(int signum) {
    printf("Caught SIGINT, cleaning up...\n");
    gpioTerminate();
    i2cClose(i2c_handle);
    exit(EXIT_SUCCESS);
}

void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpiod_handle = gpioOpen(0, 0);
    if (gpiod_handle < 0) {
        fprintf(stderr, "Failed to open gpiod\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x\n", I2C_BUS, LIS3DH_ADDR);
        exit(EXIT_FAILURE);
    }
}

void configure_lis3dh() {
    uint8_t data[2];
    data[0] = CTRL_REG1;
    data[1] = 0x77; // 100 Hz data rate, ±2g full scale
    if (i2cWrite(i2c_handle, data, 2) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        retries++;
        if (retries >= MAX_RETRIES) {
            i2cClose(i2c_handle);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }
        return;
    }
    retries = 0;

    data[0] = CTRL_REG4;
    data[1] = 0x00; // No interrupts, no FIFO
    if (i2cWrite(i2c_handle, data, 2) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        retries++;
        if (retries >= MAX_RETRIES) {
            i2cClose(i2c_handle);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }
        return;
    }
    retries = 0;
}

void read_acceleration() {
    uint8_t data[6];
    if (i2cRead(i2c_handle, OUT_X_L, 6) < 0) {
        fprintf(stderr, "Failed to read from OUT_X_L\n");
        retries++;
        if (retries >= MAX_RETRIES) {
            i2cClose(i2c_handle);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }
        return;
    }
    retries = 0;

    int16_t x = (data[1] << 8) | data[0];
    int16_t y = (data[3] << 8) | data[2];
    int16_t z = (data[5] << 8) | data[4];

    float magnitude = sqrt(x * x + y * y + z * z) / 16384.0;
    printf("Acceleration: X=%f, Y=%f, Z=%f\n", x / 16384.0, y / 16384.0, z / 16384.0);

    if (magnitude < FREEFALL_THRESHOLD) {
        freefall_detected = 1;
    } else if (magnitude > IMPACT_THRESHOLD) {
        impact_detected = 1;
    }
}

void activate_buzzer() {
    gpioWrite(gpiod_handle, Buzzer_PIN, 1);
    usleep(1000000); // 1 second
    gpioWrite(gpiod_handle, Buzzer_PIN, 0);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, handle_sigint);

    init_pigpio();
    init_i2c();
    configure_lis3dh();

    while (1) {
        read_acceleration();
        if (freefall_detected) {
            printf("Freefall detected!\n");
            activate_buzzer();
            freefall_detected = 0;
        } else if (impact_detected) {
            printf("Impact detected!\n");
            activate_buzzer();
            impact_detected = 0;
        }
        usleep(100000); // 100 Hz
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

