#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define X_STEPS 5000 // 50 mm at 10 steps/mm
#define Y_STEPS 5000
#define STEPS_PER_REV 2048
#define MICROSECONDS_PER_STEP 1000
#define DELAY 1000000 // microseconds

#define X_IN1 4
#define X_IN2 17
#define X_IN3 27
#define X_IN4 22

#define Y_IN1 5
#define Y_IN2 6
#define Y_IN3 13
#define Y_IN4 19

#define NUM_STEPS 4
#define STEPS_PER_WAVE 4

static volatile sig_atomic_t stop = 0;

void handle_sigint(int signum) {
    stop = 1;
}

void move_motor(int pin, int steps, int direction) {
    for (int i = 0; i < steps; i++) {
        for (int j = 0; j < NUM_STEPS; j++) {
            for (int k = 0; k < STEPS_PER_WAVE; k++) {
                gpioWrite(pin + j, direction);
                usleep(MICROSECONDS_PER_STEP);
            }
        }
        gpioWrite(pin + 0, 0);
        gpioWrite(pin + 1, 0);
        gpioWrite(pin + 2, 0);
        gpioWrite(pin + 3, 0);
        usleep(DELAY);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(X_IN1, PI_OUTPUT);
    gpioSetMode(X_IN2, PI_OUTPUT);
    gpioSetMode(X_IN3, PI_OUTPUT);
    gpioSetMode(X_IN4, PI_OUTPUT);

    gpioSetMode(Y_IN1, PI_OUTPUT);
    gpioSetMode(Y_IN2, PI_OUTPUT);
    gpioSetMode(Y_IN3, PI_OUTPUT);
    gpioSetMode(Y_IN4, PI_OUTPUT);

    signal(SIGINT, handle_sigint);

    // Move X-axis to draw a square
    move_motor(X_IN1, X_STEPS, 1); // Move right
    move_motor(X_IN1, X_STEPS, 0); // Move left
    move_motor(X_IN1, X_STEPS, 1); // Move right
    move_motor(X_IN1, X_STEPS, 0); // Move left

    // Move Y-axis to draw a square
    move_motor(Y_IN1, Y_STEPS, 1); // Move up
    move_motor(Y_IN1, Y_STEPS, 0); // Move down
    move_motor(Y_IN1, Y_STEPS, 1); // Move up
    move_motor(Y_IN1, Y_STEPS, 0); // Move down

    gpioWrite(X_IN1, 0);
    gpioWrite(X_IN2, 0);
    gpioWrite(X_IN3, 0);
    gpioWrite(X_IN4, 0);

    gpioWrite(Y_IN1, 0);
    gpioWrite(Y_IN2, 0);
    gpioWrite(Y_IN3, 0);
    gpioWrite(Y_IN4, 0);

    gpioTerminate();

    return 0;
}

