#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

#define DEFAULT_THRESHOLD 2.0
#define DEFAULT_I2C_ADDR 0x18

static int i2c_handle;
static float threshold = DEFAULT_THRESHOLD;
static int i2c_addr = DEFAULT_I2C_ADDR;

static void sigint_handler(int signum) {
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    if (gpioInitialise() >= 0) {
        gpioTerminate();
    }
    exit(0);
}

static void log_event(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    FILE *log_file = fopen("/var/log/high_acceleration.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    fprintf(log_file, "%s: X=%f, Y=%f, Z=%f\n", timestamp, x, y, z);
    fclose(log_file);
}

static void read_acceleration() {
    uint8_t data[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, data, 6) != 6) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return;
    }

    int16_t x = (data[1] << 8) | data[0];
    int16_t y = (data[3] << 8) | data[2];
    int16_t z = (data[5] << 8) | data[4];

    float g_x = (float)x / 2048.0 * 0.0009765625;
    float g_y = (float)y / 2048.0 * 0.0009765625;
    float g_z = (float)z / 2048.0 * 0.0009765625;

    if (fabs(g_x) > threshold || fabs(g_y) > threshold || fabs(g_z) > threshold) {
        log_event(g_x, g_y, g_z);
        system("sudo shutdown -h now");
    }
}

int main(int argc, char *argv[]) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    signal(SIGINT, sigint_handler);

    if (argc > 1) {
        if (sscanf(argv[1], "-a %x", &i2c_addr) != 1 || i2c_addr < 0x08 || i2c_addr > 0x77) {
            fprintf(stderr, "Invalid I2C address\n");
            gpioTerminate();
            return 1;
        }
    }

    if (argc > 2) {
        if (sscanf(argv[2], "-t %f", &threshold) != 1 || threshold <= 0) {
            fprintf(stderr, "Invalid threshold\n");
            gpioTerminate();
            return 1;
        }
    }

    i2c_handle = i2cOpen(1, i2c_addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    uint8_t ctrl_reg1 = 0x57; // ±2g, high-resolution mode, 100 Hz
    uint8_t ctrl_reg4 = 0x88; // 100 Hz output data rate
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, ctrl_reg1) != 1 || i2cWriteByteData(i2c_handle, CTRL_REG4, ctrl_reg4) != 1) {
        fprintf(stderr, "Failed to configure sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (1) {
        read_acceleration();
        usleep(100000); // 10 Hz
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

