static int left_pin_fd = -1;
static int center_pin_fd = -1;
static int right_pin_fd = -1;
static int buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int alert_count = 0;

static void handle_signal(int sig) {
    if (gpiod_ctx != -1) {
        gpiod_chip_close(gpiod_ctx);
    }
    if (alert_pin_fd != -1) {
        close(alert_pin_fd);
    }
    if (left_pin_fd != -1) {
        close(left_pin_fd);
    }
    if (center_pin_fd != -1) {
        close(center_pin_fd);
    }
    if (right_pin_fd != -1) {
        close(right_pin_fd);
    }
    exit(0);
}

static void init_gpio() {
    gpiod_ctx = gpiod_chip_open_by_name("gpiochip0");
    if (gpiod_ctx == -1) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    alert_pin_fd = gpiod_line_request_output(gpiod_ctx, "alert", ALERT_PIN, 0);
    if (alert_pin_fd == -1) {
        perror("Failed to request alert pin");
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    left_pin_fd = gpiod_line_request_input(gpiod_ctx, "left", LEFT_PIN);
    if (left_pin_fd == -1) {
        perror("Failed to request left pin");
        gpiod_line_release(alert_pin_fd);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    center_pin_fd = gpiod_line_request_input(gpiod_ctx, "center", CENTER_PIN);
    if (center_pin_fd == -1) {
        perror("Failed to request center pin");
        gpiod_line_release(alert_pin_fd);
        gpiod_line_release(left_pin_fd);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }

    right_pin_fd = gpiod_line_request_input(gpiod_ctx, "right", RIGHT_PIN);
    if (right_pin_fd == -1) {
        perror("Failed to request right pin");
        gpiod_line_release(alert_pin_fd);
        gpiod_line_release(left_pin_fd);
        gpiod_line_release(center_pin_fd);
        gpiod_chip_close(gpiod_ctx);
        exit(EXIT_FAILURE);
    }
}

static void log_reading(int reading) {
    buffer[buffer_index] = reading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

