        alert_count++;
        if (alert_count >= 5) {
            gpiod_line_set_value(alert_pin_fd, 1);
            sleep(2);
            gpiod_line_set_value(alert_pin_fd, 0);
            alert_count = 0;
        }
    } else {
        alert_count = 0;
    }
}

static void line_following() {
    int left = gpiod_line_get_value(left_pin_fd);
    int center = gpiod_line_get_value(center_pin_fd);
    int right = gpiod_line_get_value(right_pin_fd);

    log_reading(left);
    log_reading(center);
    log_reading(right);

