        printf("Move forward\n");
    } else if (left == 0) {
        // Turn left
        // Placeholder for motor control
        printf("Turn left\n");
    } else if (right == 0) {
        // Turn right
        // Placeholder for motor control
        printf("Turn right\n");
    } else {
        // Stop
        // Placeholder for motor control
        printf("Stop\n");
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();

    while (1) {
        line_following();
        usleep(POLL_INTERVAL);
    }

    return 0;
