#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x30
#define GPIO_RELAY 17
#define THRESHOLD 5.0
#define POLL_INTERVAL 100
#define MAX_POLL_ATTEMPTS 50
#define LOG_FILE "magnetic_events.txt"

static int i2c_handle;
static int relay_state = 0;
static FILE *log_file;

void log_event(const char *format, ...) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);

    va_list args;
    va_start(args, format);
    fprintf(log_file, "%s: ", timestamp);
    vfprintf(log_file, format, args);
    fprintf(log_file, "\n");
    va_end(args);
}

void sigint_handler(int signum) {
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    gpioWrite(GPIO_RELAY, 0);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        log_event("Failed to initialize GPIO");
        return 1;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        log_event("Failed to set GPIO mode for relay");
        gpioTerminate();
        return 1;
    }

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        log_event("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_event("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        if (gpioWrite(GPIO_RELAY, 1) < 0) {
            log_event("Failed to set relay to high");
            continue;
        }

        if (i2cWriteByte(i2c_handle, 0xC1) < 0) {
            log_event("Failed to write to register 0xC1");
            gpioWrite(GPIO_RELAY, 0);
            continue;
        }

        int poll_attempts = 0;
        while (poll_attempts < MAX_POLL_ATTEMPTS) {
            if (i2cReadByte(i2c_handle, 0xC1) < 0) {
                log_event("Failed to read from register 0xC1");
                gpioWrite(GPIO_RELAY, 0);
                break;
            }

            if (i2cReadByte(i2c_handle, 0xC1) == 0x00) {
                break;
            }

            poll_attempts++;
            usleep(POLL_INTERVAL * 1000);
        }

        if (poll_attempts == MAX_POLL_ATTEMPTS) {
            log_event("Timeout waiting for register 0xC1 to clear");
            gpioWrite(GPIO_RELAY, 0);
            continue;
        }

        if (i2cReadByteData(i2c_handle, 0xC0) < 0) {
            log_event("Failed to read from register 0xC0");
            gpioWrite(GPIO_RELAY, 0);
            continue;
        }

        if (i2cReadByteData(i2c_handle, 0xC0) < 0) {
            log_event("Failed to read from register 0xC0");
            gpioWrite(GPIO_RELAY, 0);
            continue;
        }

        int lsb = i2cReadByteData(i2c_handle, 0xC0);
        int msb = i2cReadByteData(i2c_handle, 0xC0);

        int field_raw = (msb << 8) | lsb;
        float field_mT_x100 = field_raw * 25 / 1000;

        if (field_mT_x100 > THRESHOLD * 100) {
            log_event("Field strength exceeded threshold: %.2f mT", field_mT_x100 / 100.0);
            relay_state = 1;
        } else {
            log_event("Field strength below threshold: %.2f mT", field_mT_x100 / 100.0);
            relay_state = 0;
        }

        if (gpioWrite(GPIO_RELAY, relay_state) < 0) {
            log_event("Failed to set relay state");
        }

        log_event("Field reading: %.2f mT", field_mT_x100 / 100.0);
        log_event("Relay state: %d", relay_state);

        usleep(POLL_INTERVAL * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

