    signal(SIGINT, sigint_handler);

    while (1) {
        if (gpioWrite(GPIO_RELAY, 1) < 0) {
            log_event("Failed to set relay to high");
            continue;
        }

        if (i2cWriteByte(i2c_handle, 0xC1) < 0) {
            log_event("Failed to write to register 0xC1");
            gpioWrite(GPIO_RELAY, 0);
            continue;
        }

        int poll_attempts = 0;
        while (poll_attempts < MAX_POLL_ATTEMPTS) {
            if (i2cReadByte(i2c_handle, 0xC1) < 0) {
                log_event("Failed to read from register 0xC1");
                gpioWrite(GPIO_RELAY, 0);
                break;
            }

            if (i2cReadByte(i2c_handle, 0xC1) == 0x00) {
                break;
            }

            poll_attempts++;
            usleep(POLL_INTERVAL * 1000);
        }

        if (poll_attempts == MAX_POLL_ATTEMPTS) {
            log_event("Timeout waiting for register 0xC1 to clear");
            gpioWrite(GPIO_RELAY, 0);
            continue;
        }

        if (i2cReadByteData(i2c_handle, 0xC0) < 0) {
            log_event("Failed to read from register 0xC0");
            gpioWrite(GPIO_RELAY, 0);
            continue;
        }

        if (i2cReadByteData(i2c_handle, 0xC0) < 0) {
            log_event("Failed to read from register 0xC0");
            gpioWrite(GPIO_RELAY, 0);
            continue;
        }

        int lsb = i2cReadByteData(i2c_handle, 0xC0);
        int msb = i2cReadByteData(i2c_handle, 0xC0);

        int field_raw = (msb << 8) | lsb;
        float field_mT_x100 = field_raw * 25 / 1000;

        if (field_mT_x100 > THRESHOLD * 100) {
            log_event("Field strength exceeded threshold: %.2f mT", field_mT_x100 / 100.0);
            relay_state = 1;
        } else {
            log_event("Field strength below threshold: %.2f mT", field_mT_x100 / 100.0);
            relay_state = 0;
        }

        if (gpioWrite(GPIO_RELAY, relay_state) < 0) {
            log_event("Failed to set relay state");
        }

        log_event("Field reading: %.2f mT", field_mT_x100 / 100.0);
        log_event("Relay state: %d", relay_state);

        usleep(POLL_INTERVAL * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}
