#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define RELAY_PIN 18
#define LOG_FILE "relay_log.txt"

static int gpiod_handle;
static FILE *log_file;
static int socket_fd;
static int relay_state = 0;

void log_event(const char *event) {
    time_t now;
    struct tm *tm_info;
    char time_str[80];

    time(&now);
    tm_info = localtime(&now);
    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s - %s\n", time_str, event);
    fflush(log_file);
}

void handle_command(const char *command) {
    if (strcasecmp(command, "ON") == 0) {
        if (relay_state == 0) {
            log_event("Relay turned ON");
            gpioWrite(gpiod_handle, RELAY_PIN, 1);
            relay_state = 1;
        } else {
            log_event("Relay is already ON");
        }
    } else if (strcasecmp(command, "OFF") == 0) {
        if (relay_state == 1) {
            log_event("Relay turned OFF");
            gpioWrite(gpiod_handle, RELAY_PIN, 0);
            relay_state = 0;
        } else {
            log_event("Relay is already OFF");
        }
    } else {
        log_event("Invalid command: %s", command);
    }
}

void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes_read;

    while ((bytes_read = read(client_fd, buffer, sizeof(buffer) - 1)) > 0) {
        buffer[bytes_read] = '\0';
        handle_command(buffer);
    }

    close(client_fd);
}

void handle_sigint(int signum) {
    log_event("Received SIGINT, shutting down...");
    close(socket_fd);
    fclose(log_file);
    gpioWrite(gpiod_handle, RELAY_PIN, 0);
    gpioTerminate();
    exit(0);
}

void handle_sigterm(int signum) {
    log_event("Received SIGTERM, shutting down...");
    close(socket_fd);
    fclose(log_file);
    gpioWrite(gpiod_handle, RELAY_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpiod_handle = gpioGetChipHandle(0);

    if (gpioSetMode(gpiod_handle, RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    if ((socket_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        fprintf(stderr, "Failed to create socket\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Failed to bind socket\n");
        close(socket_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (listen(socket_fd, 5) < 0) {
        fprintf(stderr, "Failed to listen on socket\n");
        close(socket_fd);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    log_event("Server started on port 5000");

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(socket_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            fprintf(stderr, "Failed to accept connection\n");
            continue;
        }

        log_event("Accepted connection from %s:%d", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));
        handle_client(client_fd);
    }

    close(socket_fd);
    fclose(log_file);
    gpioWrite(gpiod_handle, RELAY_PIN, 0);
    gpioTerminate();
    return 0;
}

