This C program uses the pigpio library to control a KY-019 relay module connected to GPIO 18 on a Raspberry Pi 4 Model B. It listens for TCP commands on port 5000 to turn the relay on or off. The program logs every activation, deactivation, and invalid command event to a file named `relay_log.txt`. It handles errors for socket operations and GPIO initialization, and it gracefully shuts down on receiving SIGINT or SIGTERM.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <fcntl.h>
#include <errno.h>

#define I2C_BUS 1
#define SLF3S_ADDR1 0x08
#define SLF3S_ADDR2 0x09
#define SLF3S_START_CMD {0x36, 0x08}
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define CRC8_FINAL_XOR 0x00
#define GPIO_RELAY 18
#define SAMPLE_RATE_MS 100
#define MIN_FLOW 5.0

volatile sig_atomic_t exit_flag = 0;

void sig_handler(int sig) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_fd1 = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd1 < 0) {
        fprintf(stderr, "Failed to open I2C device 1: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int i2c_fd2 = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd2 < 0) {
        fprintf(stderr, "Failed to open I2C device 2: %s\n", strerror(errno));
        close(i2c_fd1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd1, I2C_SLAVE, SLF3S_ADDR1) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 1: %s\n", strerror(errno));
        close(i2c_fd1);
        close(i2c_fd2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd2, I2C_SLAVE, SLF3S_ADDR2) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 2: %s\n", strerror(errno));
        close(i2c_fd1);
        close(i2c_fd2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode: %s\n", GPIO_RELAY, strerror(errno));
        close(i2c_fd1);
        close(i2c_fd2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(GPIO_RELAY, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO %d low: %s\n", GPIO_RELAY, strerror(errno));
        close(i2c_fd1);
        close(i2c_fd2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        close(i2c_fd1);
        close(i2c_fd2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        close(i2c_fd1);
        close(i2c_fd2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *flow_log = fopen("flow_log.txt", "a");
    if (flow_log == NULL) {
        fprintf(stderr, "Failed to open flow_log.txt: %s\n", strerror(errno));
        close(i2c_fd1);
        close(i2c_fd2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (!exit_flag) {
        uint8_t cmd[2] = SLF3S_START_CMD;
        if (write(i2c_fd1, cmd, sizeof(cmd)) != sizeof(cmd)) {
            fprintf(stderr, "Failed to write start command to sensor 1: %s\n", strerror(errno));
            continue;
        }

        if (write(i2c_fd2, cmd, sizeof(cmd)) != sizeof(cmd)) {
            fprintf(stderr, "Failed to write start command to sensor 2: %s\n", strerror(errno));
            continue;
        }

        uint8_t data1[3], data2[3];
        if (read(i2c_fd1, data1, sizeof(data1)) != sizeof(data1)) {
            fprintf(stderr, "Failed to read from sensor 1: %s\n", strerror(errno));
            continue;
        }

        if (read(i2c_fd2, data2, sizeof(data2)) != sizeof(data2)) {
            fprintf(stderr, "Failed to read from sensor 2: %s\n", strerror(errno));
            continue;
        }

        uint8_t crc1 = crc8(data1, sizeof(data1) - 1);
        uint8_t crc2 = crc8(data2, sizeof(data2) - 1);

        if (crc1 != data1[2] || crc2 != data2[2]) {
            fprintf(stderr, "CRC mismatch on sensor 1 or 2\n");
            continue;
        }

        int16_t flow1 = (data1[0] << 8) | data1[1];
        int16_t flow2 = (data2[0] << 8) | data2[1];

        double flow_rate1 = flow1 / 1500.0;
        double flow_rate2 = flow2 / 1500.0;

        if (flow_rate1 < MIN_FLOW || flow_rate2 < MIN_FLOW) {
            if (gpioWrite(GPIO_RELAY, 1) < 0) {
                fprintf(stderr, "Failed to set GPIO %d high: %s\n", GPIO_RELAY, strerror(errno));
            }
        } else {
            if (gpioWrite(GPIO_RELAY, 0) < 0) {
                fprintf(stderr, "Failed to set GPIO %d low: %s\n", GPIO_RELAY, strerror(errno));
            }
        }

        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        fprintf(flow_log, "%ld.%03ld, %.2f, %.2f\n", ts.tv_sec, ts.tv_nsec / 1000000, flow_rate1, flow_rate2);
        fflush(flow_log);

        usleep(SAMPLE_RATE_MS * 1000);
    }

    fclose(flow_log);
    close(i2c_fd1);
    close(i2c_fd2);
    gpioTerminate();

    return EXIT_SUCCESS;
}

uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc ^ CRC8_FINAL_XOR;
}

