#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24
#define POLL_INTERVAL_MS 200
#define MOTOR_RUN_TIME_MS 5000
#define DRY_THRESHOLD 3

static volatile sig_atomic_t run = 1;

void signal_handler(int sig) {
    run = 0;
    gpioWrite(MOTOR_ENA_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioTerminate();
    closelog();
    exit(EXIT_SUCCESS);
}

int main() {
    int gpioErr;
    int rainState = 1; // Assume initially dry
    int dryCount = 0;

    // Initialize syslog
    openlog("rain_window", LOG_PID, LOG_USER);

    // Initialize pigpio
    if ((gpioErr = gpioInitialise()) < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio: %s", gpioErrDescription(gpioErr));
        closelog();
        exit(EXIT_FAILURE);
    }

    // Set up GPIOs
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Rain window controller started");

    while (run) {
        // Read rain sensor
        int sensorState = gpioRead(RAIN_SENSOR_PIN);
        syslog(LOG_INFO, "Rain sensor state: %d", sensorState);

        // Check for dry-to-wet transition
        if (sensorState == 1 && rainState == 0) {
            syslog(LOG_INFO, "Rain detected, starting motor");

            // Start motor
            gpioWrite(MOTOR_ENA_PIN, 1);
            gpioWrite(MOTOR_IN1_PIN, 1);
            gpioWrite(MOTOR_IN2_PIN, 0);

            // Run motor for 5 seconds
            usleep(MOTOR_RUN_TIME_MS * 1000);

            // Stop motor
            gpioWrite(MOTOR_ENA_PIN, 0);
            gpioWrite(MOTOR_IN1_PIN, 0);
            gpioWrite(MOTOR_IN2_PIN, 0);

            syslog(LOG_INFO, "Motor stopped");

            // Reset dry count
            dryCount = 0;
        } else if (sensorState == 0) {
            // Increment dry count
            dryCount++;
            syslog(LOG_INFO, "Dry count: %d", dryCount);

            // Check if dry for 3 consecutive polls
            if (dryCount >= DRY_THRESHOLD) {
                syslog(LOG_INFO, "Dry for 3 consecutive polls, resetting dry count");
                dryCount = 0;
            }
        }

        // Poll every 200 ms
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    gpioTerminate();
    closelog();

    return EXIT_SUCCESS;
}

