#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define BUTTON1_PIN 21
#define BUTTON2_PIN 22
#define DEBOUNCE_DELAY 50000  // 50 ms debounce delay
#define LOCK_PULSE_WIDTH 2000  // 2000 µs pulse width for locked position
#define UNLOCK_PULSE_WIDTH 1000  // 1000 µs pulse width for unlocked position

static volatile int lock = 0;
static volatile int unlock = 0;

void sigint_handler(int sig) {
    gpioWrite(SERVO_PIN, 0);  // Stop the servo
    gpioTerminate();
    printf("Servo stopped and resources released.\n");
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON1_PIN, PI_INPUT);
    gpioSetMode(BUTTON2_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON2_PIN, PI_PUD_UP);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        if (gpioRead(BUTTON1_PIN) == 0) {
            if (lock == 0) {
                lock = 1;
                gpioServo(SERVO_PIN, LOCK_PULSE_WIDTH);
                printf("Locked.\n");
            }
        } else {
            lock = 0;
        }

        if (gpioRead(BUTTON2_PIN) == 0) {
            if (unlock == 0) {
                unlock = 1;
                gpioServo(SERVO_PIN, UNLOCK_PULSE_WIDTH);
                printf("Unlocked.\n");
            }
        } else {
            unlock = 0;
        }

        usleep(10000);  // Sleep for 10 ms to avoid high CPU usage
    }

    gpioTerminate();
    return 0;
}

