#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define PIR_PIN 4
#define LED_PIN 17
#define LOG_FILE "security_log.txt"
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%S\n"
#define LOG_DURATION_FORMAT "%Y-%m-%dT%H:%M:%S %d seconds\n"

static volatile sig_atomic_t keep_running = 1;
static FILE *log_file;

void sig_handler(int signum) {
    keep_running = 0;
    gpioWrite(LED_PIN, 0);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    struct timespec sleep_time = {0, 100000000}; // 100 ms
    struct timespec start_time, end_time;
    time_t start_time_t, end_time_t;
    char log_entry[1024];

    while (keep_running) {
        if (gpioRead(PIR_PIN) == 1) {
            gpioWrite(LED_PIN, 1);
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            while (keep_running && gpioRead(PIR_PIN) == 1) {
                clock_gettime(CLOCK_MONOTONIC, &end_time);
                if (end_time.tv_sec - start_time.tv_sec >= 60) {
                    break;
                }
                nanosleep(&sleep_time, NULL);
            }
            gpioWrite(LED_PIN, 0);
            clock_gettime(CLOCK_MONOTONIC, &end_time);
            start_time_t = start_time.tv_sec;
            end_time_t = end_time.tv_sec;
            snprintf(log_entry, sizeof(log_entry), LOG_DURATION_FORMAT, ctime(&start_time_t), end_time_t - start_time_t);
            if (fprintf(log_file, "%s", log_entry) < 0) {
                fprintf(stderr, "Failed to write to log file\n");
                gpioWrite(LED_PIN, 0);
                fclose(log_file);
                gpioTerminate();
                return 1;
            }
        }
        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

