#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define ELECTRODE_COUNT 12
#define DEBOUNCE_TIME 200

static volatile int running = 1;
static int gpio_handle;
static int i2c_handle;

void handle_signal(int sig) {
    running = 0;
    gpioTerminate();
    i2cClose(i2c_handle);
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpio_handle = gpioGetChipHandle(0);

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay to OFF state
    gpioWrite(RELAY_PIN, 0);

    // Soft-reset the MPR121
    if (i2cWriteByteData(i2c_handle, 0x80, 0x00) < 0) {
        fprintf(stderr, "Failed to soft-reset MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x00) < 0) { // MHD
        fprintf(stderr, "Failed to configure MHD\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x00) < 0) { // NHD
        fprintf(stderr, "Failed to configure NHD\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x00) < 0) { // NCL
        fprintf(stderr, "Failed to configure NCL\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5F, 0x00) < 0) { // FDL
        fprintf(stderr, "Failed to configure FDL\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set debounce
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x00) < 0) { // Debounce
        fprintf(stderr, "Failed to set debounce\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set FFI/SFI/CDT
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x00) < 0) { // FFI
        fprintf(stderr, "Failed to set FFI\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x00) < 0) { // SFI
        fprintf(stderr, "Failed to set SFI\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x00) < 0) { // CDT
        fprintf(stderr, "Failed to set CDT\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Enable auto-config
    if (i2cWriteByteData(i2c_handle, 0x7B, 0x00) < 0) { // Auto-config
        fprintf(stderr, "Failed to enable auto-config\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, 0x7C, 0x00) < 0) { // Auto-config
        fprintf(stderr, "Failed to enable auto-config\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(i2c_handle, 0x7D, 0x00) < 0) { // Auto-config
        fprintf(stderr, "Failed to enable auto-config\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Enable exactly 12 electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Enable electrodes
        fprintf(stderr, "Failed to enable electrodes\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        uint16_t touch_status;
        if (i2cReadWordData(i2c_handle, 0x00, &touch_status) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            continue;
        }

        if ((touch_status & (1 << 0)) && !(touch_status & (1 << 1))) {
            // Rising-edge touch on electrode 0
            gpioWrite(RELAY_PIN, 1);
            usleep(DEBOUNCE_TIME * 1000);
            gpioWrite(RELAY_PIN, 0);
        }
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

