#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <syslog.h>
#include <gpiod.h>
#include <pthread.h>
#include <stdarg.h>
#include <time.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define MAX_COMMAND_LENGTH 100

static pthread_t servo_thread;
static int socket_fd;
static int servo_fd;
static int piro_fd;
static int log_fd;
static int running = 1;

void log_message(const char *format, ...) {
    va_list args;
    char buffer[1024];
    time_t now;
    struct tm *tm_info;

    time(&now);
    tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    va_start(args, format);
    vsnprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), format, args);
    va_end(args);

    syslog(LOG_USER, "%s: %s", buffer, buffer);
    if (log_fd != -1) {
        fprintf(log_fd, "%s: %s\n", buffer, buffer);
        fflush(log_fd);
    }
}

void *servo_thread_function(void *arg) {
    int duty_cycle = 0;
    int step = 1;
    int max_duty_cycle = 1000; // 1000 corresponds to 180 degrees

    while (running) {
        if (duty_cycle >= max_duty_cycle) {
            step = -1;
        } else if (duty_cycle <= 0) {
            step = 1;
        }
        duty_cycle += step;
        gpiod_line_set_value(servo_fd, 1, duty_cycle / 1000.0);
        usleep(50000); // 50 Hz
    }

    return NULL;
}

void handle_command(const char *command) {
    if (strncmp(command, "SERVO ", 6) == 0) {
        int angle = atoi(command + 6);
        if (angle >= 0 && angle <= 180) {
            int duty_cycle = angle * 1000 / 180;
            gpiod_line_set_value(servo_fd, 1, duty_cycle / 1000.0);
            log_message("Servo set to angle %d", angle);
        } else {
            log_message("Invalid servo angle: %s", command);
        }
    } else if (strcmp(command, "PIR") == 0) {
        int value = gpiod_line_get_value(piro_fd);
        log_message("PIR sensor: %d", value);
        send(socket_fd, value ? "PIR:1\n" : "PIR:0\n", 6, 0);
    } else {
        log_message("Unknown command: %s", command);
    }
}

void handle_client(int client_fd) {
    char buffer[MAX_COMMAND_LENGTH];
    ssize_t bytes_received;

    while (running && (bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        handle_command(buffer);
    }

    close(client_fd);
}

void handle_signal(int signum) {
    running = 0;
    pthread_join(servo_thread, NULL);
    close(socket_fd);
    close(servo_fd);
    close(piro_fd);
    if (log_fd != -1) {
        fclose(log_fd);
    }
    log_message("Program terminated");
    exit(0);
}

int main() {
    int ret;
    struct sockaddr_in server_addr;
    struct sigaction sa;

    // Initialize libgpiod
    ret = gpiod_chip_open_by_name("gpiochip0");
    if (ret < 0) {
        log_message("Failed to open GPIO chip: %s", gpiod_strerror(ret));
        exit(EXIT_FAILURE);
    }
    servo_fd = gpiod_chip_get_line(ret, SERVO_PIN);
    if (servo_fd < 0) {
        log_message("Failed to get servo GPIO line: %s", gpiod_strerror(servo_fd));
        gpiod_chip_close(ret);
        exit(EXIT_FAILURE);
    }
    piro_fd = gpiod_chip_get_line(ret, PIR_PIN);
    if (piro_fd < 0) {
        log_message("Failed to get PIR GPIO line: %s", gpiod_strerror(piro_fd));
        gpiod_line_release(servo_fd);
        gpiod_chip_close(ret);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_output(servo_fd, "servo", 0);
    if (ret < 0) {
        log_message("Failed to request servo GPIO line: %s", gpiod_strerror(ret));
        gpiod_line_release(servo_fd);
        gpiod_chip_close(ret);
        exit(EXIT_FAILURE);
    }
    ret = gpiod_line_request_input(piro_fd, "pir");
    if (ret < 0) {
        log_message("Failed to request PIR GPIO line: %s", gpiod_strerror(ret));
        gpiod_line_release(servo_fd);
        gpiod_line_release(piro_fd);
        gpiod_chip_close(ret);
        exit(EXIT_FAILURE);
    }

    // Initialize socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd < 0) {
        log_message("Failed to create socket: %s", strerror(errno));
        gpiod_line_release(servo_fd);
        gpiod_line_release(piro_fd);
        gpiod_chip_close(ret);
        exit(EXIT_FAILURE);
    }
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);
    ret = bind(socket_fd, (struct sockaddr *)&server_addr, sizeof(server_addr));
    if (ret < 0) {
        log_message("Failed to bind socket: %s", strerror(errno));
        close(socket_fd);
        gpiod_line_release(servo_fd);
        gpiod_line_release(piro_fd);
        gpiod_chip_close(ret);
        exit(EXIT_FAILURE);
    }
    ret = listen(socket_fd, 5);
    if (ret < 0) {
        log_message("Failed to listen on socket: %s", strerror(errno));
        close(socket_fd);
        gpiod_line_release(servo_fd);
        gpiod_line_release(piro_fd);
        gpiod_chip_close(ret);
        exit(EXIT_FAILURE);
    }

    // Initialize syslog
    openlog("raspberry_pi_servo", LOG_PID, LOG_USER);

    // Initialize log file
    log_fd = fopen(LOG_FILE, "a");
    if (log_fd == NULL) {
        log_message("Failed to open log file: %s", strerror(errno));
        closelog();
        close(socket_fd);
        gpiod_line_release(servo_fd);
        gpiod_line_release(piro_fd);
        gpiod_chip_close(ret);
        exit(EXIT_FAILURE);
    }

    // Start servo thread
    ret = pthread_create(&servo_thread, NULL, servo_thread_function, NULL);
    if (ret < 0) {
        log_message("Failed to create servo thread: %s", strerror(errno));
        fclose(log_fd);
        close(socket_fd);
        gpiod_line_release(servo_fd);
        gpiod_line_release(piro_fd);
        gpiod_chip_close(ret);
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Accept connections
    while (running) {
        int client_fd = accept(socket_fd, NULL, NULL);
        if (client_fd < 0) {
            log_message("Failed to accept connection: %s", strerror(errno));
            continue;
        }
        handle_client(client_fd);
    }

    // Clean up
    pthread_join(servo_thread, NULL);
    close(socket_fd);
    close(servo_fd);
    close(piro_fd);
    if (log_fd != -1) {
        fclose(log_fd);
    }
    closelog();

    return 0;
}

