This C program uses the libgpiod API to control a servo motor and a PIR sensor on a Raspberry Pi 5. It listens for TCP commands on port 5000 and handles 'SERVO <angle>' commands to set the servo angle and 'PIR' commands to read the PIR sensor status. The program logs all activation events, commands, and errors to both syslog and a local file named `security.log` with ISO 8601 timestamps. It also handles SIGINT and SIGTERM for graceful shutdown, releasing all libgpiod resources, closing the socket, and closing the log file.

code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define BH1750_ADDR 0x23
#define RELAY_PIN 23
#define I2C_BUS 1
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL 2000000 // 2 seconds in microseconds

static int i2cHandle;
static FILE *logFile;
static int relayState = 0;

void logData(const char *message, int lux) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(logFile, "%s, %d\n", timestamp, lux);
    fflush(logFile);
}

void handleSignal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpioTerminate();
        if (logFile) fclose(logFile);
        if (i2cHandle != -1) i2cClose(i2cHandle);
        exit(0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, relayState);

    if ((i2cHandle = i2cOpen(I2C_BUS, BH1750_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByte(i2cHandle, 0x10) < 0) {
        fprintf(stderr, "Failed to set BH1750 to One-Time High-Resolution mode\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    if ((logFile = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handleSignal);
    signal(SIGTERM, handleSignal);

    while (1) {
        usleep(SAMPLE_INTERVAL);

        if (i2cWriteByte(i2cHandle, 0x20) < 0) {
            fprintf(stderr, "Failed to trigger BH1750 conversion\n");
            continue;
        }

        usleep(120000); // Wait for conversion

        uint8_t data[2];
        if (i2cReadDevice(i2cHandle, data, 2) < 0) {
            fprintf(stderr, "Failed to read from BH1750\n");
            continue;
        }

        int raw = (data[0] << 8) | data[1];
        int lux = raw / 1.2;

        logData("Sample", lux);

        if (lux < 150) {
            if (relayState == 0) {
                gpioWrite(RELAY_PIN, 1);
                relayState = 1;
            }
        } else {
            if (relayState == 1) {
                gpioWrite(RELAY_PIN, 0);
                relayState = 0;
            }
        }
    }

    fclose(logFile);
    i2cClose(i2cHandle);
    gpioTerminate();
    return 0;
}

