#define DOUT_PIN 23
#define SCK_PIN 24
#define LOCK_PIN 25
#define TARE_READS 10
#define MEASUREMENT_READS 5
#define THRESHOLD_DEFAULT 1000
#define SCALE_DEFAULT 1000000
#define DURATION_DEFAULT 500
#define MAX_RETRIES 3
#define RETRY_DELAY 1000000 // 1 second

static int gpiod_chip = -1;
static int gpiod_line_dout = -1;
static int gpiod_line_sck = -1;
static int gpiod_line_lock = -1;
static int threshold = THRESHOLD_DEFAULT;
static int scale = SCALE_DEFAULT;
static int duration = DURATION_DEFAULT;
static int retries = MAX_RETRIES;
static int retry_delay = RETRY_DELAY;
static int tare_offset = 0;
static int weight = 0;
static int lock_state = 0;
static int running = 1;

static void signal_handler(int signum) {
    running = 0;
    gpiochip_close(gpiod_chip);
    gpiod_line_close(gpiod_line_dout);
    gpiod_line_close(gpiod_line_sck);
    gpiod_line_close(gpiod_line_lock);
    closelog();
    exit(EXIT_SUCCESS);
}

static void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

static void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

static int read_hx711() {
    int retries_left = retries;
    while (retries_left > 0) {
        if (gpio_line_get_value(gpiod_line_dout) == 0) {
            unsigned int raw = 0;
            for (int i = 0; i < 24; i++) {
                gpio_line_set_value(gpiod_line_sck, 1);
                raw = (raw << 1) | gpio_line_get_value(gpiod_line_dout);
                gpio_line_set_value(gpiod_line_sck, 0);
            }
            gpio_line_set_value(gpiod_line_sck, 1); // Select Channel A / Gain 128
            gpio_line_set_value(gpiod_line_sck, 0);
            return raw;
        }
        retries_left--;
        usleep(retry_delay);
    }
    log_error("DOUT did not go LOW within 1 second");
    return -1;
}

static void tare() {
    int sum = 0;
    for (int i = 0; i < TARE_READS; i++) {
        sum += read_hx711();
    }
    tare_offset = sum / TARE_READS;
}

static void measure() {
    int sum = 0;
    for (int i = 0; i < MEASUREMENT_READS; i++) {
        sum += read_hx711();
    }
    weight = (sum / MEASUREMENT_READS) - tare_offset;
}

static void lock_solenoid() {
    gpio_line_set_value(gpiod_line_lock, 1);
    usleep(200000); // 200 ms
    gpio_line_set_value(gpiod_line_lock, 0);
}

