        } else if (strcmp(argv[i], "--scale") == 0 && i + 1 < argc) {
            scale = atoi(argv[i + 1]);
        } else if (strcmp(argv[i], "--duration") == 0 && i + 1 < argc) {
            duration = atoi(argv[i + 1]);
        }
    }

    // Initialize GPIO
    gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_chip < 0) {
        log_error("Failed to open GPIO chip");
        closelog();
        exit(EXIT_FAILURE);
    }

    gpiod_line_dout = gpiod_chip_get_line(gpiod_chip, DOUT_PIN);
    if (gpiod_line_dout < 0) {
        log_error("Failed to get GPIO line for DOUT");
        gpiochip_close(gpiod_chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    gpiod_line_sck = gpiod_chip_get_line(gpiod_chip, SCK_PIN);
    if (gpiod_line_sck < 0) {
        log_error("Failed to get GPIO line for SCK");
        gpiod_line_close(gpiod_line_dout);
        gpiochip_close(gpiod_chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    gpiod_line_lock = gpiod_chip_get_line(gpiod_chip, LOCK_PIN);
    if (gpiod_line_lock < 0) {
        log_error("Failed to get GPIO line for LOCK");
        gpiod_line_close(gpiod_line_dout);
        gpiod_line_close(gpiod_line_sck);
        gpiochip_close(gpiod_chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(gpiod_line_dout, "hx711_dout") < 0) {
        log_error("Failed to request GPIO line for DOUT as input");
        gpiod_line_close(gpiod_line_dout);
        gpiod_line_close(gpiod_line_sck);
        gpiod_line_close(gpiod_line_lock);
        gpiochip_close(gpiod_chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(gpiod_line_sck, "hx711_sck", 0) < 0) {
        log_error("Failed to request GPIO line for SCK as output");
        gpiod_line_close(gpiod_line_dout);
        gpiod_line_close(gpiod_line_sck);
        gpiod_line_close(gpiod_line_lock);
        gpiochip_close(gpiod_chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(gpiod_line_lock, "hx711_lock", 0) < 0) {
        log_error("Failed to request GPIO line for LOCK as output");
        gpiod_line_close(gpiod_line_dout);
        gpiod_line_close(gpiod_line_sck);
        gpiod_line_close(gpiod_line_lock);
        gpiochip_close(gpiod_chip);
        closelog();
        exit(EXIT_FAILURE);
    }

    // Tare the scale
    tare();

    // Main loop
    while (running) {
        measure();
        if (weight > threshold) {
            lock_solenoid();
        }
        usleep(duration * 1000); // Poll every 500 ms
    }

    // Clean up
    gpio_line_set_value(gpiod_line_lock, 0);
    gpiod_line_close(gpiod_line_dout);
    gpiod_line_close(gpiod_line_sck);
    gpiod_line_close(gpiod_line_lock);
    gpiochip_close(gpiod_chip);
    closelog();

    return EXIT_SUCCESS;
