static void on_connect(struct mosquitto *mosq, int rc) {
    if (rc == 0) {
        mqtt_connected = 1;
        syslog(LOG_USER, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
    } else {
        syslog(LOG_ERR, "Connection failed with code %d", rc);
        mqtt_connected = 0;
    }
