#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define MQTT_QOS 0
#define MQTT_KEEPALIVE 60

static struct mosquitto *mosq;
static int gpio_initialized = 0;
static int mqtt_connected = 0;

static void on_connect(struct mosquitto *mosq, int rc) {
    if (rc == 0) {
        mqtt_connected = 1;
        syslog(LOG_USER, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
    } else {
        syslog(LOG_ERR, "Connection failed with code %d", rc);
        mqtt_connected = 0;
    }
}

static void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *msg) {
    if (msg->payloadlen > 0) {
        const char *payload = (const char *)msg->payload;
        if (strcmp(payload, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1);
            syslog(LOG_USER, "Received ON message, relay energized");
        } else if (strcmp(payload, "OFF") == 0) {
            gpioWrite(GPIO_PIN, 0);
            syslog(LOG_USER, "Received OFF message, relay de-energized");
        } else {
            syslog(LOG_ERR, "Received invalid payload: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Received empty message");
    }
}

