#include <stdio.h>
#include <pigpio.h>

#define PWM_FREQUENCY 50
#define PWM_RANGE 2000
#define SERVO_PINS {7, 8, 9, 10, 11}
#define SERVO_POSITIONS {1000, 1500, 2000, 500, 2500}
#define HOLD_TIME 3000000 // 3 seconds in microseconds

int main() {
    int i, result;

    // Initialize pigpio library
    result = gpioInitialise();
    if (result < 0) {
        fprintf(stderr, "Failed to initialize pigpio library: %s\n", gpioErrDescription(result));
        return 1;
    }

    // Set the PWM frequency and range for each servo
    for (i = 0; i < 5; i++) {
        result = gpioSetPWMFrequency(SERVO_PINS[i], PWM_FREQUENCY);
        if (result < 0) {
            fprintf(stderr, "Failed to set PWM frequency for pin %d: %s\n", SERVO_PINS[i], gpioErrDescription(result));
            gpioTerminate();
            return 1;
        }

        result = gpioSetPWMRange(SERVO_PINS[i], PWM_RANGE);
        if (result < 0) {
            fprintf(stderr, "Failed to set PWM range for pin %d: %s\n", SERVO_PINS[i], gpioErrDescription(result));
            gpioTerminate();
            return 1;
        }
    }

    // Apply the pulse widths to each servo
    for (i = 0; i < 5; i++) {
        result = gpioPWM(SERVO_PINS[i], SERVO_POSITIONS[i]);
        if (result < 0) {
            fprintf(stderr, "Failed to set PWM for pin %d: %s\n", SERVO_PINS[i], gpioErrDescription(result));
            gpioTerminate();
            return 1;
        }
    }

    // Hold the signals for 3 seconds
    usleep(HOLD_TIME);

    // Cleanly stop the PWM and release the library resources
    for (i = 0; i < 5; i++) {
        result = gpioPWM(SERVO_PINS[i], 0);
        if (result < 0) {
            fprintf(stderr, "Failed to stop PWM for pin %d: %s\n", SERVO_PINS[i], gpioErrDescription(result));
        }
    }

    result = gpioTerminate();
    if (result < 0) {
        fprintf(stderr, "Failed to terminate pigpio library: %s\n", gpioErrDescription(result));
        return 1;
    }

    printf("Servos have been moved to their positions and will now stop.\n");

    return 0;
}

