#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define BH1750_I2C_BUS 1
#define BH1750_I2C_ADDR 0x23
#define LOG_FILE "chicken_coop_log.txt"
#define HISTORIC_READS 10
#define HISTORIC_READ_DELAY 1000000 // 1 second

static int i2c_handle;
static FILE *log_file;
static int relay_state = 0;
static int historic_lux[HISTORIC_READS];
static int historic_index = 0;

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char log_entry[100];
    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s: %s\n", log_entry, event);
    fflush(log_file);
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_event("Shutting down");
        fclose(log_file);
        i2c_close(i2c_handle);
        gpioTerminate();
        exit(0);
    }
}

void read_lux() {
    uint16_t lux;
    if (i2c_write_byte(i2c_handle, 0x21) != 0) {
        log_event("Failed to start One-Time High-Resolution Mode 2");
        relay_state = 0;
        return;
    }
    usleep(180000); // Wait at least 180 ms
    if (i2c_read_word_data(i2c_handle, 0x00) != 0) {
        log_event("Failed to read lux data");
        relay_state = 0;
        return;
    }
    lux = i2c_read_word_data(i2c_handle, 0x00);
    historic_lux[historic_index] = lux;
    historic_index = (historic_index + 1) % HISTORIC_READS;
    log_event(f"Lux = {lux}, Relay = {'ON' if relay_state else 'OFF'}");
}

void check_lux() {
    int avg_lux = 0;
    for (int i = 0; i < HISTORIC_READS; i++) {
        avg_lux += historic_lux[i];
    }
    avg_lux /= HISTORIC_READS;
    if (avg_lux < 50) {
        if (relay_state == 0) {
            gpioWrite(RELAY_PIN, 1);
            relay_state = 1;
        }
    } else if (avg_lux > 200) {
        if (relay_state == 1) {
            gpioWrite(RELAY_PIN, 0);
            relay_state = 0;
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_event("Failed to initialize pigpio");
        return 1;
    }
    if (i2cOpen(BH1750_I2C_BUS, BH1750_I2C_ADDR, 0) < 0) {
        log_event("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        log_event("Failed to set relay pin mode");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_event("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
    while (1) {
        read_lux();
        check_lux();
        usleep(HISTORIC_READ_DELAY);
    }
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

