#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEBOUNCE_DELAY 50
#define LOG_FILE "relay_state.log"

static volatile sig_atomic_t quit = 0;

void sigint_handler(int sig) {
    quit = 1;
}

void log_state(int state) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
    FILE *log = fopen(LOG_FILE, "a");
    if (log == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }
    fprintf(log, "%s %s\n", timestamp, state ? "ON" : "OFF");
    fclose(log);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set touch pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    int last_state = 0;
    int current_state = 0;
    int touch_state = 0;
    int debounce_timer = 0;

    while (!quit) {
        touch_state = gpioRead(TOUCH_PIN);
        if (touch_state == 1) {
            debounce_timer = DEBOUNCE_DELAY;
        } else if (debounce_timer > 0) {
            debounce_timer--;
        } else {
            current_state = gpioRead(RELAY_PIN);
            if (current_state != touch_state) {
                gpioWrite(RELAY_PIN, touch_state);
                log_state(touch_state);
            }
        }

        usleep(10000); // 10 ms sleep
    }

    gpioWrite(RELAY_PIN, 0); // Turn relay off
    gpioTerminate();
    log_state(0); // Log final state
    printf("Program exited gracefully.\n");
    return 0;
}

