#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define LOG_FILE "water_flow.log"
#define HISTORIC_THRESHOLD 0.5
#define PULSE_PER_LITER 450.0
#define LPM_PER_SECOND 60.0
#define DEBOUNCE_TIMEOUT 1000000  // 1 second in microseconds

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static int solenoid_state = 1;  // Open by default
static FILE *log_file = NULL;

static void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s - %s\n", timestamp, event);
}

static void *flow_sensor_thread(void *arg) {
    while (1) {
        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);

        double lpm = (current_pulse_count / PULSE_PER_LITER) * LPM_PER_SECOND;
        log_event(fprintf(log_file, "LPM: %.2f\n", lpm) > 0 ? "LPM logged" : "LPM log failed");

        if (lpm > 5.0) {
            solenoid_state = 0;  // Close solenoid
            log_event(fprintf(log_file, "Solenoid closed\n") > 0 ? "Solenoid closed" : "Solenoid close log failed");
        } else if (lpm < 4.5) {
            solenoid_state = 1;  // Open solenoid
            log_event(fprintf(log_file, "Solenoid opened\n") > 0 ? "Solenoid opened" : "Solenoid open log failed");
        }
    }
    return NULL;
}

static void handle_signal(int signum) {
    log_event(fprintf(log_file, "Received signal %d\n", signum) > 0 ? "Signal logged" : "Signal log failed");
    solenoid_state = 1;  // Reopen solenoid
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_PIN, solenoid_state) < 0) {
        fprintf(stderr, "Failed to set solenoid initial state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, DEBOUNCE_TIMEOUT, NULL, flow_sensor_thread) < 0) {
        fprintf(stderr, "Failed to set flow sensor ISR\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    pthread_t flow_thread;
    if (pthread_create(&flow_thread, NULL, flow_sensor_thread, NULL) < 0) {
        fprintf(stderr, "Failed to create flow sensor thread\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        sleep(1);
    }

    pthread_join(flow_thread, NULL);
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    return EXIT_SUCCESS;
}

