#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEFAULT_DEBOUNCE_TIME 50
#define MAX_LOG_LENGTH 100

static int debounce_time = DEFAULT_DEBOUNCE_TIME;
static int relay_state = 0;
static FILE *log_file = NULL;

void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char log_message[MAX_LOG_LENGTH];
    snprintf(log_message, MAX_LOG_LENGTH, "%04d-%02d-%02d %02d:%02d:%02d Relay: %s",
            tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday,
            tm->tm_hour, tm->tm_min, tm->tm_sec,
            state ? "ON" : "OFF");
    fprintf(log_file, "%s\n", log_message);
}

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        gpioWrite(RELAY_PIN, 0); // Turn off the relay
        gpioTerminate(); // Terminate pigpio
        if (log_file) {
            fclose(log_file);
        }
        exit(EXIT_SUCCESS);
    }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_time = atoi(optarg);
                if (debounce_time < 0) {
                    fprintf(stderr, "Invalid debounce time. Using default.\n");
                    debounce_time = DEFAULT_DEBOUNCE_TIME;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(TOUCH_PIN, PI_INPUT);

    log_file = fopen("relay_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int touch_state = gpioRead(TOUCH_PIN);
        if (touch_state == 1) {
            int stable_state = 0;
            for (int i = 0; i < debounce_time; i++) {
                stable_state = gpioRead(TOUCH_PIN);
                if (stable_state != touch_state) {
                    break;
                }
                usleep(1000);
            }
            if (stable_state == 1) {
                relay_state = !relay_state;
                gpioWrite(RELAY_PIN, relay_state);
                log_relay_state(relay_state);
            }
        }
        usleep(1000);
    }

    gpioTerminate();
    fclose(log_file);
    return 0;
}

