                if (stable_state != touch_state) {
                    break;
                }
                usleep(1000);
            }
            if (stable_state == 1) {
                relay_state = !relay_state;
                gpioWrite(RELAY_PIN, relay_state);
                log_relay_state(relay_state);
            }
        }
        usleep(1000);
    }

    gpioTerminate();
    fclose(log_file);
    return 0;
}
