#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQ 50
#define PWM_PERIOD 20000
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define ANGLE_INCREMENT 10

static struct termios old_termios;
static int fd;

void restore_termios() {
    tcsetattr(fd, TCSANOW, &old_termios);
}

void handle_sigint(int signum) {
    restore_termios();
    gpioPWM(SERVO_PIN, 0);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(SERVO_PIN, 1500) < 0) {
        fprintf(stderr, "Failed to set initial PWM\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    fd = open("/dev/tty", O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Failed to open terminal\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (tcgetattr(fd, &old_termios) < 0) {
        fprintf(stderr, "Failed to get terminal attributes\n");
        close(fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct termios new_termios = old_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO);
    new_termios.c_cc[VTIME] = 0;
    new_termios.c_cc[VMIN] = 1;
    if (tcsetattr(fd, TCSANOW, &new_termios) < 0) {
        fprintf(stderr, "Failed to set terminal attributes\n");
        close(fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    int angle = 90;
    while (1) {
        char ch;
        if (read(fd, &ch, 1) > 0) {
            switch (ch) {
                case '+':
                    angle = (angle + ANGLE_INCREMENT) % (MAX_ANGLE + 1);
                    break;
                case '-':
                    angle = (angle - ANGLE_INCREMENT + (MAX_ANGLE + 1)) % (MAX_ANGLE + 1);
                    break;
                case 'q':
                    angle = 0;
                    break;
                default:
                    continue;
            }
            int pulse_width = (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / MAX_ANGLE) + MIN_PULSE_WIDTH;
            if (gpioPWM(SERVO_PIN, pulse_width) < 0) {
                fprintf(stderr, "Failed to set PWM\n");
                break;
            }
            printf("Angle: %d\n", angle);
        }
    }

    restore_termios();
    gpioPWM(SERVO_PIN, 0);
    gpioTerminate();
    close(fd);
    return EXIT_SUCCESS;
}

