#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define LOG_FILE "motor_rpm.log"
#define DEBOUNCE_WINDOW_MS 2
#define SAMPLE_INTERVAL_MS 5000

static volatile sig_atomic_t should_exit = 0;
static gpiod_chip *chip = NULL;
static gpiod_line *line = NULL;
static FILE *log_file = NULL;
static uint64_t pulse_count = 0;
static struct timespec last_pulse_time;

void handle_signal(int signum) {
    should_exit = 1;
}

void log_rpm() {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);
    double elapsed_seconds = (now.tv_sec - last_pulse_time.tv_sec) + (now.tv_nsec - last_pulse_time.tv_nsec) / 1e9;
    double rpm = (pulse_count / elapsed_seconds) * 60.0;
    fprintf(log_file, "%s,%.2f\n", ctime(&now), rpm);
    fflush(log_file);
}

int main() {
    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line as input with pull-up
    int flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;
    int ret = gpiod_line_request_input_flags(line, "motor_rpm", flags);
    if (ret) {
        fprintf(stderr, "Failed to request GPIO line %d as input with pull-up: %d\n", GPIO_PIN, ret);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize last pulse time
    clock_gettime(CLOCK_MONOTONIC, &last_pulse_time);

    // Main loop
    while (!should_exit) {
        struct timespec timeout = {SAMPLE_INTERVAL_MS / 1000, (SAMPLE_INTERVAL_MS % 1000) * 1000000};
        struct gpiod_line_event event;
        ret = gpiod_line_event_wait(line, &timeout);
        if (ret == -1) {
            if (errno == EAGAIN) {
                // Timeout occurred, check for new pulses
                struct timespec now;
                clock_gettime(CLOCK_MONOTONIC, &now);
                double elapsed_seconds = (now.tv_sec - last_pulse_time.tv_sec) + (now.tv_nsec - last_pulse_time.tv_nsec) / 1e9;
                if (elapsed_seconds > 0.002) {
                    log_rpm();
                }
            } else {
                fprintf(stderr, "Failed to wait for GPIO event: %d\n", ret);
                break;
            }
        } else if (ret == 0) {
            // No event occurred, check for new pulses
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            double elapsed_seconds = (now.tv_sec - last_pulse_time.tv_sec) + (now.tv_nsec - last_pulse_time.tv_nsec) / 1e9;
            if (elapsed_seconds > 0.002) {
                log_rpm();
            }
        } else {
            // Event occurred
            ret = gpiod_line_event_read(line, &event);
            if (ret) {
                fprintf(stderr, "Failed to read GPIO event: %d\n", ret);
                break;
            }
            if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                pulse_count++;
                last_pulse_time = now;
            }
        }
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

