#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define TIMEOUT 10000 // 10 seconds in milliseconds

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return EXIT_FAILURE;
    }

    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(TOUCH_PIN, PI_INPUT);

    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_UP);

    struct timespec last_touch_time;
    struct timespec current_time;
    time_t start_time;
    time_t end_time;

    while (!exit_flag) {
        if (gpioRead(TOUCH_PIN) == PI_HIGH) {
            if (start_time == 0) {
                start_time = time(NULL);
            }
            end_time = time(NULL);
            if ((end_time - start_time) > TIMEOUT) {
                gpioWrite(RELAY_PIN, PI_LOW);
                start_time = 0;
                end_time = 0;
            }
        } else {
            if (start_time != 0) {
                end_time = time(NULL);
                if ((end_time - start_time) <= TIMEOUT) {
                    gpioWrite(RELAY_PIN, !gpioRead(RELAY_PIN));
                }
                start_time = 0;
                end_time = 0;
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        if (current_time.tv_sec - last_touch_time.tv_sec > 50) {
            gpioWrite(RELAY_PIN, PI_LOW);
            last_touch_time = current_time;
        }

        sleep(1);
    }

    gpioWrite(RELAY_PIN, PI_LOW);
    gpioTerminate();

    return EXIT_SUCCESS;
}

