#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define GPIO_PWM 18
#define GPIO_DIR 23
#define GPIO_FLOW 24
#define PWM_FREQ 1000
#define LOG_FILE "flow_log.csv"
#define Kp 1.0
#define CALIBRATION_PULSES_PER_LITER 450

static int flow_count = 0;
static double target_flow_rate = -1.0;
static FILE *log_file = NULL;
static int running = 1;

static void handle_sigint(int signum) {
    running = 0;
}

static void handle_sigterm(int signum) {
    running = 0;
}

static void isr_handler(int gpio, int level, uint32_t tick) {
    if (level == PI_RISING_EDGE) {
        flow_count++;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate_in_L/min>\n", argv[0]);
        return 1;
    }

    if (sscanf(argv[1], "%lf", &target_flow_rate) != 1 || target_flow_rate <= 0) {
        fprintf(stderr, "Invalid target flow rate. Please provide a positive number.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library.\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PWM, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode.\n", GPIO_PWM);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_DIR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to output mode.\n", GPIO_DIR);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_FLOW, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to input mode.\n", GPIO_FLOW);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_FLOW, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d.\n", GPIO_FLOW);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFunc(GPIO_FLOW, RISING_EDGE, 100000, isr_handler) < 0) {
        fprintf(stderr, "Failed to register ISR for GPIO %d.\n", GPIO_FLOW);
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "w")) == NULL) {
        fprintf(stderr, "Failed to open log file %s.\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    gpioWrite(GPIO_DIR, 1); // Enable the valve

    struct timespec sleep_time = {0, 100000000}; // 100 ms

    while (running) {
        double flow_rate = (flow_count * CALIBRATION_PULSES_PER_LITER) / 60.0;
        double error = target_flow_rate - flow_rate;
        int pwm_duty_cycle = (int)(Kp * error);

        if (pwm_duty_cycle < 0) {
            pwm_duty_cycle = 0;
        } else if (pwm_duty_cycle > 255) {
            pwm_duty_cycle = 255;
        }

        gpioWrite(GPIO_PWM, pwm_duty_cycle);

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        double timestamp_ms = now.tv_sec * 1000.0 + now.tv_nsec / 1000000.0;

        fprintf(log_file, "%.3f,%.3f,%d\n", timestamp_ms, flow_rate, pwm_duty_cycle);

        flow_count = 0;
        nanosleep(&sleep_time, NULL);
    }

    fclose(log_file);
    gpioWrite(GPIO_PWM, 0);
    gpioWrite(GPIO_DIR, 0);
    gpioTerminate();

    return 0;
}

