        syslog(LOG_ERR, "Failed to open log file");
        spiClose(spi_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (!exit_flag) {
        if (gpioRead(BUTTON_PIN) == 0) {
            // Button press detected
            if (read_rfid_tag() == 0) {
                // RFID tag read successfully
                if (gpioWrite(LOCK_PIN_1, 0) < 0) {
                    syslog(LOG_ERR, "Failed to write to lock pin 1");
