#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define GPIO_RELAY 17
#define LOG_FILE "relay_log.txt"
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t quit = 0;

void handle_sigint(int signum) {
    quit = 1;
}

int main() {
    FILE *log_file;
    struct timespec ts;
    int i2c_handle;
    uint8_t mpr121_data[2];
    uint8_t mpr121_config[12];
    uint8_t mpr121_status[2];
    uint8_t mpr121_touch_thresholds[12];
    uint8_t mpr121_release_thresholds[12];
    uint8_t mpr121_filter_config[12];
    uint8_t mpr121_run_mode = 0x01;
    uint8_t mpr121_reset = 0x80;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up GPIO 17 as an output for the relay
    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", GPIO_RELAY);
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        return 1;
    }

    // Soft reset the MPR121
    if (i2cWriteByte(i2c_handle, mpr121_reset) < 0) {
        fprintf(stderr, "Failed to send soft reset to MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for the MPR121 to reset
    usleep(100000);

    // Configure filtering
    for (i = 0; i < 12; i++) {
        mpr121_filter_config[i] = 0x00; // Set to default configuration
    }
    if (i2cWriteBlockData(i2c_handle, 0x04, mpr121_filter_config, 12) < 0) {
        fprintf(stderr, "Failed to write filter configuration to MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set touch and release thresholds for all electrodes
    for (i = 0; i < 12; i++) {
        mpr121_touch_thresholds[i] = 0x01; // Set to default threshold
        mpr121_release_thresholds[i] = 0x01; // Set to default threshold
    }
    if (i2cWriteBlockData(i2c_handle, 0x0E, mpr121_touch_thresholds, 12) < 0) {
        fprintf(stderr, "Failed to write touch thresholds to MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteBlockData(i2c_handle, 0x10, mpr121_release_thresholds, 12) < 0) {
        fprintf(stderr, "Failed to write release thresholds to MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Enable run mode
    if (i2cWriteByte(i2c_handle, mpr121_run_mode) < 0) {
        fprintf(stderr, "Failed to enable run mode in MPR121\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!quit) {
        // Read touch status registers
        if (i2cReadBlockData(i2c_handle, 0x00, mpr121_status, 2) < 0) {
            fprintf(stderr, "Failed to read touch status from MPR121\n");
            break;
        }

        // Check if any electrode is touched
        if (mpr121_status[0] != 0x00 || mpr121_status[1] != 0x00) {
            // Activate relay
            gpioWrite(GPIO_RELAY, 1);
            fprintf(log_file, "%ld: Relay activated\n", time(NULL));
        } else {
            // Deactivate relay
            gpioWrite(GPIO_RELAY, 0);
            fprintf(log_file, "%ld: Relay deactivated\n", time(NULL));
        }

        // Sleep for the specified interval
        nanosleep(&ts, NULL);
    }

    // Close log file
    fclose(log_file);

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

