#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_VALVE1 17
#define GPIO_VALVE2 18
#define LOG_FILE "valve_log.txt"
#define LOG_FORMAT "%Y-%m-%dT%H:%M:%S.%fZ"

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int signum) {
    should_exit = 1;
}

int main() {
    int ret;
    struct timespec sleep_time;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *log_file;

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize libgpiod
    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Request lines for valve control
    struct gpiod_line *line1 = gpiod_chip_get_line(chip, GPIO_VALVE1);
    if (!line1) {
        perror("Failed to get line for Valve 1");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *line2 = gpiod_chip_get_line(chip, GPIO_VALVE2);
    if (!line2) {
        perror("Failed to get line for Valve 2");
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(line1, "Valve 1", 0);
