#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define RELAY_PIN 17
#define TOUCH_THRESHOLD 0x10
#define RELEASE_THRESHOLD 0x0A
#define FILTER_CHARGE_TIME 0x20
#define ELECTRODE_CURRENT 0x01
#define ELE_EN 0x20
#define TOUCH_STATUS_REG 0x00
#define TOUCH_STATUS_MASK 0x0F

static int i2c_fd;
static int gpio_fd;
static int touch_status;
static int relay_state = 0;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        gpio_write(gpio_fd, RELAY_PIN, 0); // Turn off relay
        gpio_close(gpio_fd);
        close(i2c_fd);
        pigpio_stop();
        printf("Program terminated gracefully.\n");
        exit(0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }
    gpio_fd = gpioOpen(RELAY_PIN, OUTPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO %d.\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X.\n", I2C_BUS, I2C_ADDR);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121 in stop mode
    if (i2cWriteByteData(i2c_fd, 0x0F, 0x00) < 0) {
        fprintf(stderr, "Failed to set MPR121 to stop mode.\n");
        close(i2c_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }

    // Set touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_fd, 0x14 + i, TOUCH_THRESHOLD) < 0) {
            fprintf(stderr, "Failed to set touch threshold for electrode %d.\n", i);
            close(i2c_fd);
            gpioClose(gpio_fd);
            gpioTerminate();
            return 1;
        }
        if (i2cWriteByteData(i2c_fd, 0x18 + i, RELEASE_THRESHOLD) < 0) {
            fprintf(stderr, "Failed to set release threshold for electrode %d.\n", i);
            close(i2c_fd);
            gpioClose(gpio_fd);
            gpioTerminate();
            return 1;
        }
    }

    // Configure filter/charge time and electrode current
    if (i2cWriteByteData(i2c_fd, 0x20, FILTER_CHARGE_TIME) < 0) {
        fprintf(stderr, "Failed to set filter/charge time.\n");
        close(i2c_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWriteByteData(i2c_fd, 0x21, ELECTRODE_CURRENT) < 0) {
        fprintf(stderr, "Failed to set electrode current.\n");
        close(i2c_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }

    // Enter run mode with ELE_EN=1
    if (i2cWriteByteData(i2c_fd, 0x20, ELE_EN) < 0) {
        fprintf(stderr, "Failed to enable electrodes.\n");
        close(i2c_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }

    // Wait for stabilization
    usleep(100000);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        if (i2cReadByteData(i2c_fd, TOUCH_STATUS_REG, &touch_status) < 0) {
            fprintf(stderr, "Failed to read touch status.\n");
            close(i2c_fd);
            gpioClose(gpio_fd);
            gpioTerminate();
            return 1;
        }

        if (touch_status > 0) {
            relay_state = !relay_state;
            gpioWrite(gpio_fd, RELAY_PIN, relay_state);
            printf("Relay state: %d\n", relay_state);
        }

        usleep(100000);
    }

    close(i2c_fd);
    gpioClose(gpio_fd);
    gpioTerminate();
    return 0;
}

