#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define LOG_FILE "door_events.log"
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t keep_running = 1;
static FILE *log_file;
static time_t last_unlock_time = 0;

void handle_signal(int signum) {
    keep_running = 0;
}

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(log_file, "%s - %s\n", timestamp, event);
    fflush(log_file);
}

void unlock_door() {
    gpioWrite(RELAY_PIN, 1);
    usleep(500000); // 500 ms
    gpioWrite(RELAY_PIN, 0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set PIR pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set PIR pin pull-down\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);

    while (keep_running) {
        if (gpioRead(PIR_PIN) == 1) {
            time_t current_time = time(NULL);
            if (current_time - last_unlock_time > RATE_LIMIT_MS) {
                log_event("Motion detected");
                unlock_door();
                last_unlock_time = current_time;
            }
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
}

