#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DURATION 50
#define MAX_DURATION 200

volatile sig_atomic_t shutdown = 0;

void handle_sigint(int signum) {
    shutdown = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for motor 1\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode for motor 2\n");
        gpioTerminate();
        return 1;
    }

    srand(time(NULL));

    while (!shutdown) {
        int steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;
        int duration = rand() % (MAX_DURATION - MIN_DURATION + 1) + MIN_DURATION;

        for (int i = 0; i < steps; i++) {
            int dutyCycle1 = rand() % 256;
            int dutyCycle2 = rand() % 256;

            if (gpioPWM(MOTOR1_PIN, dutyCycle1) < 0) {
                fprintf(stderr, "Failed to set PWM for motor 1\n");
                break;
            }

            if (gpioPWM(MOTOR2_PIN, dutyCycle2) < 0) {
                fprintf(stderr, "Failed to set PWM for motor 2\n");
                break;
            }

            gpioDelay(duration);
        }
    }

    gpioTerminate();
    return 0;
}

