#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define DATA_PIN 4
#define CLOCK_PIN 17
#define LOCK_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define THRESHOLD 10.0
#define TIMEOUT 500000  // 0.5 seconds in microseconds

static volatile sig_atomic_t should_exit = 0;

void handle_sigint(int signum) {
    should_exit = 1;
}

int main() {
    FILE *calibration_file = fopen(CALIBRATION_FILE, "r");
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!calibration_file && !log_file) {
        fprintf(stderr, "Failed to open files\n");
        return 1;
    }

    if (pigpio_start(0, 0) < 0) {
        fprintf(stderr, "Failed to start pigpio\n");
        fclose(calibration_file);
        fclose(log_file);
        return 1;
    }

    int data_pin = DATA_PIN;
    int clock_pin = CLOCK_PIN;
    int lock_pin = LOCK_PIN;

    if (gpioSetMode(data_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set data pin mode\n");
        pigpio_stop();
        fclose(calibration_file);
        fclose(log_file);
        return 1;
    }

    if (gpioSetMode(clock_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set clock pin mode\n");
        gpioStop();
        fclose(calibration_file);
        fclose(log_file);
        return 1;
    }

    if (gpioSetMode(lock_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set lock pin mode\n");
        gpioStop();
        fclose(calibration_file);
        fclose(log_file);
        return 1;
    }

    double scale_factor = 1.0;
    double offset = 0.0;

    if (calibration_file) {
        if (fscanf(calibration_file, "%lf %lf", &scale_factor, &offset) != 2) {
            fprintf(stderr, "Invalid calibration data in %s\n", CALIBRATION_FILE);
            scale_factor = 1.0;
            offset = 0.0;
        }
        fclose(calibration_file);
    }

    if (should_exit) {
        gpioStop();
        fclose(log_file);
        return 0;
    }

    // Perform one-time startup calibration
    double sum = 0.0;
    for (int i = 0; i < 100; i++) {
        if (gpioRead(data_pin) == 0) {
            int raw_value = 0;
            for (int j = 0; j < 24; j++) {
                gpioWrite(clock_pin, 1);
                raw_value <<= 1;
                raw_value |= gpioRead(data_pin);
                gpioWrite(clock_pin, 0);
            }
            sum += raw_value;
        }
    }
    offset = sum / 100.0;

    if (calibration_file) {
        fprintf(calibration_file, "%lf %lf\n", scale_factor, offset);
        fclose(calibration_file);
    }

    if (should_exit) {
        gpioStop();
        fclose(log_file);
        return 0;
    }

    struct timespec sleep_time = {0, 500000};  // 500 ms
    while (!should_exit) {
        if (gpioRead(data_pin) == 0) {
            int raw_value = 0;
            for (int j = 0; j < 24; j++) {
                gpioWrite(clock_pin, 1);
                raw_value <<= 1;
                raw_value |= gpioRead(data_pin);
                gpioWrite(clock_pin, 0);
            }
            double weight = (raw_value - offset) * scale_factor;
            if (weight > THRESHOLD) {
                gpioWrite(lock_pin, 1);
            } else {
                gpioWrite(lock_pin, 0);
            }
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            fprintf(log_file, "%02d:%02d:%02d %lf\n", tm->tm_hour, tm->tm_min, tm->tm_sec, weight);
        } else {
            usleep(TIMEOUT);
        }
    }

    gpioStop();
    fclose(log_file);
    return 0;
}

