#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <pigpio.h>

#define GPIO_RAIN_SENSOR 4
#define GPIO_IN1 17
#define GPIO_IN2 18
#define GPIO_PWM_ENABLE 27
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define DEBOUNCE_INTERVAL 50
#define DEBOUNCE_READINGS 3
#define LOG_FILE "/var/log/window_control.log"
#define LOG_LEVEL LOG_INFO

static int gpio_rain_sensor;
static int gpio_in1;
static int gpio_in2;
static int gpio_pwm_enable;
static int pwm_handle;
static int rain_detected = 0;
static int motor_running = 0;
static int log_fd;

void log_event(const char *message) {
    time_t now;
    struct tm *tm_info;
    char buffer[80];

    time(&now);
    tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    syslog(LOG_LEVEL, "%s: %s", buffer, message);
}

void handle_sigint(int signum) {
    if (motor_running) {
        gpioPWMWrite(gpio_pwm_enable, 0);
        gpioWrite(gpio_in1, 0);
        gpioWrite(gpio_in2, 0);
    }
    gpioTerminate();
    close(log_fd);
    exit(EXIT_SUCCESS);
}

void handle_sigterm(int signum) {
    if (motor_running) {
        gpioPWMWrite(gpio_pwm_enable, 0);
        gpioWrite(gpio_in1, 0);
        gpioWrite(gpio_in2, 0);
    }
    gpioTerminate();
    close(log_fd);
    exit(EXIT_SUCCESS);
}

void check_rain() {
    int readings[DEBOUNCE_READINGS];
    int count = 0;
    int i;

    for (i = 0; i < DEBOUNCE_READINGS; i++) {
        usleep(DEBOUNCE_INTERVAL * 1000);
        readings[i] = gpioRead(gpio_rain_sensor);
        if (readings[i] == 0) {
            count++;
        }
    }

    if (count >= DEBOUNCE_READINGS) {
        if (!rain_detected) {
            log_event("Rain detected");
            rain_detected = 1;
            motor_running = 1;
            gpioPWMWrite(gpio_pwm_enable, PWM_DUTY_CYCLE);
            gpioWrite(gpio_in1, 1);
            gpioWrite(gpio_in2, 0);
            sleep(5);
            gpioPWMWrite(gpio_pwm_enable, 0);
            gpioWrite(gpio_in1, 0);
            gpioWrite(gpio_in2, 0);
            motor_running = 0;
            rain_detected = 0;
        }
    } else {
        rain_detected = 0;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    gpio_rain_sensor = GPIO_RAIN_SENSOR;
    gpio_in1 = GPIO_IN1;
    gpio_in2 = GPIO_IN2;
    gpio_pwm_enable = GPIO_PWM_ENABLE;

    if (gpioSetMode(gpio_rain_sensor, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode for rain sensor");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(gpio_in1, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode for IN1");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(gpio_in2, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode for IN2");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(gpio_pwm_enable, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode for PWM enable");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioPWM(gpio_pwm_enable, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        syslog(LOG_ERR, "Failed to open log file");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    while (1) {
        check_rain();
        sleep(60);
    }

    close(log_fd);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

