#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID 17
#define LOG_FILE "stock_events.txt"
#define TIMEOUT 1000000 // 1 second in microseconds

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    keep_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_DOUT, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set HX711_DOUT mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(HX711_SCK, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set HX711_SCK mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SOLENOID mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(HX711_DOUT, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set HX711_DOUT pull-up\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(HX711_SCK, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set HX711_SCK pull-up\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SOLENOID, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set SOLENOID pull-up\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct timespec sleep_time = {0, TIMEOUT};

    while (keep_running) {
        if (gpioRead(HX711_DOUT) == 0) {
            // Wait for the data line to go low
            while (gpioRead(HX711_DOUT) == 0) {
                if (nanosleep(&sleep_time, NULL) != 0) {
                    fprintf(stderr, "Failed to sleep\n");
                    break;
                }
            }
        }

        // Send a clock pulse
        gpioWrite(HX711_SCK, 1);
        gpioWrite(HX711_SCK, 0);

        // Read the data
        int data = 0;
        for (int i = 0; i < 24; i++) {
            gpioWrite(HX711_SCK, 1);
            data <<= 1;
            if (gpioRead(HX711_DOUT) == 1) {
                data |= 1;
            }
            gpioWrite(HX711_SCK, 0);
            if (nanosleep(&sleep_time, NULL) != 0) {
                fprintf(stderr, "Failed to sleep\n");
                break;
            }
        }

        // Check for timeout
        if (data == 0) {
            fprintf(stderr, "Timeout reading HX711\n");
            continue;
        }

        // Convert to weight
        long weight = (long) data * 1000 / 1024;

        // Check if weight is below 100 g
        if (weight < 100) {
            // Activate solenoid
            gpioWrite(SOLENOID, 1);
            sleep(5);
            gpioWrite(SOLENOID, 0);

            // Log event
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(log_file, "%s: Weight below 100 g\n", timestamp);
        }

        // Sleep for 1 second
        if (nanosleep(&sleep_time, NULL) != 0) {
            fprintf(stderr, "Failed to sleep\n");
            break;
        }
    }

    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}

