        // Read the data
        int data = 0;
        for (int i = 0; i < 24; i++) {
            gpioWrite(HX711_SCK, 1);
            data <<= 1;
            if (gpioRead(HX711_DOUT) == 1) {
                data |= 1;
            }
            gpioWrite(HX711_SCK, 0);
            if (nanosleep(&sleep_time, NULL) != 0) {
                fprintf(stderr, "Failed to sleep\n");
                break;
            }
        }

        // Check for timeout
        if (data == 0) {
            fprintf(stderr, "Timeout reading HX711\n");
            continue;
        }

        // Convert to weight
        long weight = (long) data * 1000 / 1024;

        // Check if weight is below 100 g
        if (weight < 100) {
            // Activate solenoid
            gpioWrite(SOLENOID, 1);
            sleep(5);
            gpioWrite(SOLENOID, 0);

            // Log event
            time_t now = time(NULL);
            struct tm *tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
            fprintf(log_file, "%s: Weight below 100 g\n", timestamp);
        }

        // Sleep for 1 second
        if (nanosleep(&sleep_time, NULL) != 0) {
            fprintf(stderr, "Failed to sleep\n");
            break;
        }
    }

    fclose(log_file);
    gpioTerminate();

    return EXIT_SUCCESS;
}
