#include <signal.h>
#include <gpiod.h>

#define SENSOR_PIN 16
#define RELAY_PIN 20
#define LOG_FILE "relay_events.log"

static volatile sig_atomic_t should_exit = 0;

void handle_signal(int sig) {
    should_exit = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line, *relay_line;
    int ret;
    FILE *log_file;
    char timestamp[20];
    char relay_state[10];

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Get the sensor and relay lines
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        perror("Failed to get sensor line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Request bulk inputs/outputs
    ret = gpiod_line_request_bulk_inputs_outputs(chip, "obstacle_avoidance", 1, 1, NULL, NULL, NULL, NULL);
    if (ret) {
        perror("Failed to request lines");
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!should_exit) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value == 0) {
            // Obstacle detected
            int relay_state_value = gpiod_line_get_value(relay_line);
            if (relay_state_value == 0) {
                // Relay is OFF, turn it ON
                gpiod_line_set_value(relay_line, 1);
                relay_state[0] = '1';
            } else {
                // Relay is ON, turn it OFF
                gpiod_line_set_value(relay_line, 0);
                relay_state[0] = '0';
            }
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
            fprintf(log_file, "%s, %s\n", timestamp, relay_state);
            fflush(log_file);
        }
        usleep(100000); // Sleep for 100ms
    }

    // Clean up resources
    fclose(log_file);
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    return 0;
}

