int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int duration;
    char linebuf[100];
    FILE *config_file;

    // Register signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Open the configuration file
    config_file = fopen(CONFIG_FILE, "r");
    if (!config_file) {
        fprintf(stderr, "Error: Could not open configuration file '%s'\n", CONFIG_FILE);
        return EXIT_FAILURE;
    }

    // Read the watering duration from the configuration file
    if (fgets(linebuf, sizeof(linebuf), config_file) == NULL) {
        fprintf(stderr, "Error: Could not read from configuration file '%s'\n", CONFIG_FILE);
        fclose(config_file);
        return EXIT_FAILURE;
    }

    // Parse the duration from the configuration file
    if (sscanf(linebuf, "duration=%d", &duration) != 1 || duration <= 0 || duration > MAX_DURATION) {
        fprintf(stderr, "Error: Invalid duration in configuration file '%s'\n", CONFIG_FILE);
        fclose(config_file);
        return EXIT_FAILURE;
    }

    // Close the configuration file
    fclose(config_file);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip\n");
