#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define LOG_FILE "trace_log.txt"
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27
#define LEFT_MOTOR_PWM 22
#define RIGHT_MOTOR_PWM 23
#define LEFT_MOTOR_DIR 24
#define RIGHT_MOTOR_DIR 25
#define BASE_SPEED 150
#define MAX_SPEED 255
#define PWM_FREQ 1000
#define SAMPLE_PERIOD 10000

static volatile sig_atomic_t stop = 0;

void sigint_handler(int sig) {
    stop = 1;
}

int main() {
    FILE *log_file;
    struct timespec ts;
    int left_sensor, middle_sensor, right_sensor;
    int left_motor_speed, right_motor_speed;
    int left_pwm, right_pwm;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Set up GPIOs
    if (gpioSetMode(LEFT_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for left sensor\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(MIDDLE_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for middle sensor\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(RIGHT_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for right sensor\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(LEFT_MOTOR_PWM, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for left motor PWM\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(RIGHT_MOTOR_PWM, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for right motor PWM\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(LEFT_MOTOR_DIR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for left motor direction\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(RIGHT_MOTOR_DIR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for right motor direction\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up PWM for motors
    if (gpioSetPWMfrequency(LEFT_MOTOR_PWM, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for left motor\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (gpioSetPWMfrequency(RIGHT_MOTOR_PWM, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for right motor\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    while (!stop) {
        // Read sensor states
        left_sensor = gpioRead(LEFT_SENSOR);
        middle_sensor = gpioRead(MIDDLE_SENSOR);
        right_sensor = gpioRead(RIGHT_SENSOR);

        // Determine motor speeds
        if (middle_sensor == 0) {
            left_motor_speed = BASE_SPEED;
            right_motor_speed = BASE_SPEED;
        } else if (left_sensor == 0) {
            left_motor_speed = BASE_SPEED / 2;
            right_motor_speed = BASE_SPEED;
        } else if (right_sensor == 0) {
            left_motor_speed = BASE_SPEED;
            right_motor_speed = BASE_SPEED / 2;
        } else {
            left_motor_speed = 0;
            right_motor_speed = 0;
        }

        // Set motor speeds
        left_pwm = left_motor_speed * MAX_SPEED / BASE_SPEED;
        right_pwm = right_motor_speed * MAX_SPEED / BASE_SPEED;
        gpioPWM(LEFT_MOTOR_PWM, left_pwm);
        gpioPWM(RIGHT_MOTOR_PWM, right_pwm);

        // Set motor directions
        if (left_motor_speed > 0) {
            gpioWrite(LEFT_MOTOR_DIR, 1);
        } else {
            gpioWrite(LEFT_MOTOR_DIR, 0);
        }
        if (right_motor_speed > 0) {
            gpioWrite(RIGHT_MOTOR_DIR, 1);
        } else {
            gpioWrite(RIGHT_MOTOR_DIR, 0);
        }

        // Log control cycle
        clock_gettime(CLOCK_MONOTONIC, &ts);
        fprintf(log_file, "%ld,%d,%d,%d,%d\n", ts.tv_sec * 1000000000 + ts.tv_nsec, left_sensor, middle_sensor, right_sensor, left_motor_speed);
        fflush(log_file);

        // Sleep for sample period
        nanosleep(&ts, NULL);
    }

    // Stop motors
    gpioPWM(LEFT_MOTOR_PWM, 0);
    gpioPWM(RIGHT_MOTOR_PWM, 0);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

