#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x23
#define RELAY_PIN 23
#define MIN_LUX 150

static volatile sig_atomic_t run = 1;

void handle_sigint(int signum) {
    run = 0;
}

int main() {
    FILE *log_file;
    struct timespec ts;
    int i2c_handle;
    uint16_t lux;
    int relay_state = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up I2C
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x\n", I2C_BUS, I2C_ADDRESS);
        gpioTerminate();
        return 1;
    }

    // Set up relay
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, relay_state);

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    // Log header
    log_file = fopen("grow_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,Lux,RelayState\n");

    while (run) {
        // Set continuous high-resolution mode
        if (i2cWriteByte(i2c_handle, 0x10) < 0) {
            fprintf(stderr, "Failed to set continuous high-resolution mode\n");
            continue;
        }

        // Wait for measurement
        usleep(180000);

        // Read lux
        if (i2cReadWordData(i2c_handle, 0x0C) < 0) {
            fprintf(stderr, "Failed to read lux\n");
            continue;
        }

        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &ts);

        // Log lux reading
        fprintf(log_file, "%ld,%d,%d\n", ts.tv_sec * 1000000 + ts.tv_nsec / 1000, lux, relay_state);

        // Check if relay should be activated
        if (lux < MIN_LUX) {
            if (relay_state == 0) {
                gpioWrite(RELAY_PIN, 1);
                relay_state = 1;
                fprintf(log_file, "%ld,Relay activated\n", ts.tv_sec * 1000000 + ts.tv_nsec / 1000);
            }
        } else {
            if (relay_state == 1) {
                gpioWrite(RELAY_PIN, 0);
                relay_state = 0;
                fprintf(log_file, "%ld,Relay deactivated\n", ts.tv_sec * 1000000 + ts.tv_nsec / 1000);
            }
        }
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

