#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LOCK_BUTTON 21
#define UNLOCK_BUTTON 22
#define SERVO_PIN 18
#define SERVO_MIN_PULSEWIDTH 500
#define SERVO_MAX_PULSEWIDTH 2500
#define DEBOUNCE_DELAY 100

static int lock_state = 0;
static int unlock_state = 0;
static int servo_position = 0;

static void sigint_handler(int signum) {
    gpioTerminate();
    printf("Exiting...\n");
    exit(EXIT_SUCCESS);
}

static void debounce_button(int button, int *state) {
    static int last_state = 0;
    static unsigned long last_change = 0;

    int current_state = gpioRead(button);
    if (current_state != last_state) {
        last_state = current_state;
        last_change = time(NULL) * 1000 + (unsigned long)(time(NULL) % 1000);
    } else if (time(NULL) * 1000 + (unsigned long)(time(NULL) % 1000) - last_change > DEBOUNCE_DELAY) {
        *state = current_state;
    }
}

static void move_servo(int position) {
    if (position < SERVO_MIN_PULSEWIDTH || position > SERVO_MAX_PULSEWIDTH) {
        printf("Invalid servo position: %d\n", position);
        return;
    }
    gpioPWM(SERVO_PIN, position);
    servo_position = position;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioPWMFrequency(SERVO_PIN, 50); // 50 Hz PWM

    signal(SIGINT, sigint_handler);

    while (1) {
        debounce_button(LOCK_BUTTON, &lock_state);
        debounce_button(UNLOCK_BUTTON, &unlock_state);

        if (lock_state) {
            move_servo(SERVO_MIN_PULSEWIDTH);
            printf("Locked\n");
        } else if (unlock_state) {
            move_servo(SERVO_MAX_PULSEWIDTH);
            printf("Unlocked\n");
        }

        usleep(100000); // Sleep for 100 ms
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}
