        ret = gpiod_line_set_value(line2, 1);
        if (ret) {
            perror("Failed to set line value for motor 2");
            should_stop = 1;
        }
        usleep(PULSE_DURATION_2 * 1000);

        // Wait for the next pulse interval
        usleep(PULSE_INTERVAL * 1000);
    }

    // Release the GPIO lines
    gpiod_line_release(line1);
    gpiod_line_release(line2);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

