#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <zmq.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_SOUND_SENSOR_PIN 17
#define GPIO_ALARM_LED_PIN 27
#define ZMQ_TOPIC "SOUND_ALERTS"
#define POLL_INTERVAL_MS 10

static gpiod_chip *chip = NULL;
static gpiod_line *sound_sensor_line = NULL;
static gpiod_line *alarm_led_line = NULL;
static zmq_ctx_t *context = NULL;
static zmq_socket *subscriber = NULL;
static zmq_socket *publisher = NULL;

static void cleanup() {
    if (publisher) {
        zmq_close(publisher);
    }
    if (subscriber) {
        zmq_close(subscriber);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }
    if (alarm_led_line) {
        gpiod_line_release(alarm_led_line);
    }
    if (sound_sensor_line) {
        gpiod_line_release(sound_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

static void handle_signal(int signum) {
    cleanup();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <mode>\n", argv[0]);
        fprintf(stderr, "Modes: sound_sensor, alarm_node\n");
        return 1;
    }

    const char *mode = argv[1];

    if (strcmp(mode, "sound_sensor") != 0 && strcmp(mode, "alarm_node") != 0) {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    sound_sensor_line = gpiod_chip_get_line(chip, GPIO_SOUND_SENSOR_PIN);
    if (!sound_sensor_line) {
        perror("Failed to get sound sensor line");
        cleanup();
        return 1;
    }

    alarm_led_line = gpiod_chip_get_line(chip, GPIO_ALARM_LED_PIN);
    if (!alarm_led_line) {
        perror("Failed to get alarm LED line");
        cleanup();
        return 1;
    }

    int ret = gpiod_line_request_input(sound_sensor_line, "sound_sensor");
    if (ret) {
        perror("Failed to request sound sensor line as input");
        cleanup();
        return 1;
    }

    ret = gpiod_line_request_output(alarm_led_line, "alarm_led", 0);
    if (ret) {
        perror("Failed to request alarm LED line as output");
        cleanup();
        return 1;
    }

    // Initialize ZeroMQ
    context = zmq_ctx_new();
    if (!context) {
        perror("Failed to create ZeroMQ context");
        cleanup();
        return 1;
    }

    publisher = zmq_socket(context, ZMQ_PUB);
    if (!publisher) {
        perror("Failed to create ZeroMQ publisher");
        zmq_ctx_destroy(context);
        cleanup();
        return 1;
    }

    ret = zmq_bind(publisher, "tcp://*:5555");
    if (ret) {
        perror("Failed to bind ZeroMQ publisher");
        zmq_close(publisher);
        zmq_ctx_destroy(context);
        cleanup();
        return 1;
    }

    subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        perror("Failed to create ZeroMQ subscriber");
        zmq_close(publisher);
        zmq_ctx_destroy(context);
        cleanup();
        return 1;
    }

    ret = zmq_connect(subscriber, "tcp://localhost:5555");
    if (ret) {
        perror("Failed to connect ZeroMQ subscriber");
        zmq_close(subscriber);
        zmq_close(publisher);
        zmq_ctx_destroy(context);
        cleanup();
        return 1;
    }

    ret = zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
    if (ret) {
        perror("Failed to subscribe to ZeroMQ topic");
        zmq_close(subscriber);
        zmq_close(publisher);
        zmq_ctx_destroy(context);
        cleanup();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (strcmp(mode, "sound_sensor") == 0) {
        while (1) {
            int value = gpiod_line_get_value(sound_sensor_line);
            if (value == 0) {
                zmq_msg_t msg;
                zmq_msg_init(&msg);
                zmq_msg_send(&msg, publisher, 0);
                zmq_msg_close(&msg);
                usleep(1000000); // 1 second
            }
            usleep(POLL_INTERVAL_MS * 1000); // 10 ms
        }
    } else if (strcmp(mode, "alarm_node") == 0) {
        while (1) {
            zmq_msg_t msg;
            zmq_msg_init(&msg);
            zmq_msg_recv(&msg, subscriber, 0);
            zmq_msg_close(&msg);
            gpiod_line_set_value(alarm_led_line, 1);
            usleep(1000000); // 1 second
            gpiod_line_set_value(alarm_led_line, 0);
            usleep(1000000); // 1 second
        }
    }

    cleanup();
    return 0;
}

