#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <paho-mqtt-c/mqtt.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define MAX_PULSES 1000
#define MARK 9000
#define SPACE 4500
#define BIT_MARK 560
#define SPACE_1 1690
#define SPACE_0 560

static int pulse_count = 0;
static int pulse_buffer[MAX_PULSES];
static int pulse_index = 0;
static int address = 0;
static int command = 0;
static int checksum = 0;
static int inverted = 0;
static int mqtt_client = NULL;
static int mqtt_connected = 0;

static void sig_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (mqtt_client) {
            mqtt_client->disconnect(mqtt_client);
            mqtt_client->loop_stop(mqtt_client);
        }
        if (pulse_buffer) {
            free(pulse_buffer);
        }
        if (gpioInitialise() >= 0) {
            gpioTerminate();
        }
        syslog(LOG_INFO, "Program terminated by signal %d", sig);
        closelog();
        exit(EXIT_SUCCESS);
    }
}

static void gpio_alert_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_FallingEdge) {
        if (pulse_count < MAX_PULSES) {
            pulse_buffer[pulse_index++] = tick;
            pulse_count++;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow");
        }
    }
}

static void decode_nec() {
    if (pulse_count < 32) {
        syslog(LOG_ERR, "Not enough pulses to decode NEC frame");
        return;
    }

    int mark_count = 0;
    int space_count = 0;
    int bit_count = 0;
    int bit_index = 0;

    for (int i = 0; i < pulse_count; i++) {
        int pulse = pulse_buffer[i];
        int next_pulse = i + 1 < pulse_count ? pulse_buffer[i + 1] : 0;

        if (pulse - pulse_buffer[i - 1] > MARK) {
            mark_count++;
        } else if (pulse - pulse_buffer[i - 1] > SPACE) {
            space_count++;
        } else {
            bit_count++;
            if (bit_count == 1) {
                if (pulse - pulse_buffer[i - 1] > BIT_MARK) {
                    command |= (1 << bit_index);
                } else {
                    command &= ~(1 << bit_index);
                }
                bit_index++;
            }
        }
    }

    if (mark_count != 1 || space_count != 1 || bit_count != 32) {
        syslog(LOG_ERR, "Invalid NEC frame");
        return;
    }

    address = (command >> 12) & 0xFFF;
    command &= 0xFFF;

    checksum = (address >> 8) + (address & 0xFF) + (command >> 8) + (command & 0xFF);
    if (checksum != 0) {
        syslog(LOG_ERR, "Invalid checksum");
        return;
    }

    inverted = (command >> 11) & 1;
    if (inverted) {
        command ^= 0xFFF;
    }

    syslog(LOG_INFO, "Decoded address: 0x%03X, command: 0x%03X", address, command);
}

static void publish_to_mqtt() {
    char payload[100];
    snprintf(payload, sizeof(payload), "{\"address\": %d, \"command\": %d}", address, command);
    mqtt_client->publish(mqtt_client, "ir/decoded", strlen(payload), payload, 0, 1);
}

static void mqtt_callback(struct mosquitto *mosq, void *userdata, int msgtype, const struct mosquitto_message *message) {
    if (msgtype == MQTT_MSG_PUBLISH) {
        syslog(LOG_INFO, "Received MQTT message: %s", message->payload);
    }
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetAlertFuncEx(GPIO_PIN, gpio_alert_callback, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO alert function");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (mqttClientInit(&mqtt_client, "127.0.0.1", 1883, NULL, NULL, NULL, 0) != MQTT_OK) {
        syslog(LOG_ERR, "Failed to initialize MQTT client");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    mqtt_client->connect_callback_set(mqtt_client, mqtt_callback);
    mqtt_client->loop_start(mqtt_client);

    while (1) {
        if (pulse_count >= 32) {
            decode_nec();
            publish_to_mqtt();
            pulse_count = 0;
            pulse_index = 0;
        }
        usleep(10000);
    }

