#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDRS {0x23, 0x24, 0x25, 0x26}
#define UDP_PORT 5005
#define UDP_ADDR "239.255.255.250"
#define MAX_SENSORS 4
#define MAX_DATA 2

static int i2c_fd[MAX_SENSORS];
static int udp_fd;
static volatile sig_atomic_t exit_flag = 0;

void handle_signal(int sig) {
    exit_flag = 1;
}

void close_resources() {
    for (int i = 0; i < MAX_SENSORS; i++) {
        if (i2c_fd[i] != -1) {
            close(i2c_fd[i]);
        }
    }
    if (udp_fd != -1) {
        close(udp_fd);
    }
    printf("Resources closed.\n");
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C bus
    for (int i = 0; i < MAX_SENSORS; i++) {
        i2c_fd[i] = open("/dev/i2c-" I2C_BUS, O_RDWR);
        if (i2c_fd[i] == -1) {
            perror("Failed to open I2C bus");
            close_resources();
            return EXIT_FAILURE;
        }
    }

    // Set slave addresses
    for (int i = 0; i < MAX_SENSORS; i++) {
        if (ioctl(i2c_fd[i], I2C_SLAVE, I2C_ADDRS[i]) == -1) {
            perror("Failed to set I2C slave address");
            close_resources();
            return EXIT_FAILURE;
        }
    }

    // Open UDP socket
    udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_fd == -1) {
        perror("Failed to open UDP socket");
        close_resources();
        return EXIT_FAILURE;
    }

    struct sockaddr_in udp_addr;
    memset(&udp_addr, 0, sizeof(udp_addr));
    udp_addr.sin_family = AF_INET;
    udp_addr.sin_port = htons(UDP_PORT);
    inet_pton(AF_INET, UDP_ADDR, &udp_addr.sin_addr);

    // Main loop
    while (!exit_flag) {
        char buffer[MAX_SENSORS * (MAX_DATA + 1) * 2];
        int len = 0;

        for (int i = 0; i < MAX_SENSORS; i++) {
            // Write One-Time High-Resolution mode command
            if (write(i2c_fd[i], "\x20", 1) != 1) {
                perror("Failed to write command to sensor");
                snprintf(buffer + len, sizeof(buffer) - len, "%d,NaN;", i + 1);
                len += strlen(buffer + len);
                continue;
            }

            // Wait for conversion
            usleep(180000);

            // Read 2 bytes
            char data[MAX_DATA];
            if (read(i2c_fd[i], data, MAX_DATA) != MAX_DATA) {
                perror("Failed to read data from sensor");
                snprintf(buffer + len, sizeof(buffer) - len, "%d,NaN;", i + 1);
                len += strlen(buffer + len);
                continue;
            }

            // Convert to lux
            int lux = ((data[0] << 8) | data[1]) / 120;
            snprintf(buffer + len, sizeof(buffer) - len, "%d,%d;", i + 1, lux);
            len += strlen(buffer + len);
        }

        // Broadcast the packet
        if (sendto(udp_fd, buffer, len, 0, (struct sockaddr *)&udp_addr, sizeof(udp_addr)) == -1) {
            perror("Failed to send UDP packet");
        }

        // Sleep for 1 second
        sleep(1);
    }

    close_resources();
    return EXIT_SUCCESS;
}

