#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x28
#define LOG_FILE "airflow_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static int i2c_fd = -1;
static FILE *log_file = NULL;

static void sigint_handler(int signum) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

static int read_flow() {
    uint8_t buffer[2];
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = write(i2c_fd, NULL, 0); // Start condition
        if (ret < 0) {
            perror("write");
            return -1;
        }

        ret = read(i2c_fd, buffer, 2); // Read 2 bytes
        if (ret < 0) {
            if (errno == EIO) {
                perror("read");
                retries++;
                usleep(RETRY_DELAY_MS * 1000);
                continue;
            } else if (errno == ENXIO) {
                fprintf(stderr, "Sensor not found\n");
                return -1;
            } else {
                perror("read");
                return -1;
            }
        }

        // Mask the raw value with 0x3FFF
        uint16_t raw = (buffer[0] << 8) | buffer[1];
        raw &= 0x3FFF;

        // Convert raw value to SLPM
        float flow = (raw - 3277) * 0.1;

        // Log the timestamped flow rate
        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(log_file, "%s, %.2f\n", timestamp, flow);

        return 0;
    }

    fprintf(stderr, "Failed to read flow after %d retries\n", MAX_RETRIES);
    return -1;
}

int main() {
    struct sigaction sa;

    // Set up signal handler for SIGINT
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        return 1;
    }

    // Log header
    fprintf(log_file, "Timestamp, Flow (SLPM)\n");

    // Read flow data every second
    while (1) {
        if (read_flow() < 0) {
            break;
        }
        sleep(1);
    }

    // Close log file
    fclose(log_file);

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

