#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x39
#define WHO_AM_I_REG 0x24
#define ENABLE_REG 0x80
#define CFG6_REG 0xAF
#define SP_EN_REG 0x81
#define F1_REG 0x60
#define F2_REG 0x61
#define F3_REG 0x62
#define F4_REG 0x63
#define F5_REG 0x64
#define F6_REG 0x65
#define F7_REG 0x66
#define F8_REG 0x67
#define CLEAR_REG 0x68
#define NIR_REG 0x69
#define LOG_FILE "spectral_log.csv"

static int i2c_fd;
static FILE *log_file;

static void log_spectral_data(double f1, double f2, double f3, double f4, double f5, double f6, double f7, double f8, double clear, double nir) {
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d,%H:%M:%S", tm);

    fprintf(log_file, "%s,%f,%f,%f,%f,%f,%f,%f,%f,%f\n", timestamp, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir);
    fflush(log_file);
}

static void init_sensor() {
    int ret;

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Verify WHO_AM_I/ID register
    uint8_t who_am_i;
    ret = read(i2c_fd, &who_am_i, 1);
    if (ret != 1 || who_am_i != 0x19) {
        fprintf(stderr, "Sensor not found or ID mismatch\n");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Power on the sensor
    uint8_t enable = 1;
    ret = write(i2c_fd, &enable, 1);
    if (ret != 1) {
        perror("Failed to power on sensor");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure SMUX for spectral readings
    uint8_t cfg6 = 0x00; // Default configuration
    ret = write(i2c_fd, &cfg6, 1);
    if (ret != 1) {
        perror("Failed to configure SMUX");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Enable spectral measurement
    uint8_t sp_en = 1;
    ret = write(i2c_fd, &sp_en, 1);
    if (ret != 1) {
        perror("Failed to enable spectral measurement");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

static void read_spectral_data() {
    double f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;

    // Read spectral channels
    uint8_t data[10];
    int ret = read(i2c_fd, data, 10);
    if (ret != 10) {
        perror("Failed to read spectral data");
