#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>

#define BH1750_ADDR 0x23
#define BH1750_POWER_ON 0x01
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define BH1750_READ_MODE 0x01
#define BH1750_READ_LENGTH 2
#define UDP_PORT 5000
#define UDP_ADDR "239.255.255.250"
#define TTL 1

static int i2c_fd = -1;
static int udp_socket = -1;

static void signal_handler(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Power on the sensor
    if (write(i2c_fd, &BH1750_POWER_ON, 1) != 1) {
        perror("Failed to power on BH1750");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set continuous high-resolution mode
    if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        perror("Failed to set continuous high-resolution mode");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set TTL
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &TTL, sizeof(TTL)) < 0) {
        perror("Failed to set TTL");
        close(udp_socket);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set up UDP address
    struct sockaddr_in udp_addr;
    memset(&udp_addr, 0, sizeof(udp_addr));
    udp_addr.sin_family = AF_INET;
