#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <fcntl.h>
#include <errno.h>

#define UART_DEV "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD 0x0204030608050709
#define MAX_FRAME_SIZE 1024
#define CSV_FILE "radar_data.csv"

static int uart_fd;
static FILE *csv_file;
static volatile sig_atomic_t exit_flag = 0;

void signal_handler(int sig) {
    exit_flag = 1;
}

void write_csv(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(csv_file, format, args);
    va_end(args);
    fflush(csv_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    if ((uart_fd = open(UART_DEV, O_RDWR | O_NOCTTY | O_NDELAY)) < 0) {
        fprintf(stderr, "Failed to open UART: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct termios options;
    tcgetattr(uart_fd, &options);
    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag |= CREAD | CLOCAL;
    options.c_lflag &= ~ICANON;
    options.c_lflag &= ~ECHO;
    options.c_lflag &= ~ECHOE;
    options.c_lflag &= ~ECHONL;
    options.c_lflag &= ~ISIG;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_oflag &= ~OPOST;
    tcsetattr(uart_fd, TCSANOW, &options);

    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        close(uart_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_csv("timestamp,object_index,range_m,velocity_mps\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!exit_flag) {
        char buffer[MAX_FRAME_SIZE];
        ssize_t bytes_read = read(uart_fd, buffer, MAX_FRAME_SIZE);
        if (bytes_read < 0) {
            if (errno == EAGAIN) {
                usleep(100000); // Wait for a bit before retrying
                continue;
            }
            fprintf(stderr, "Failed to read from UART: %s\n", strerror(errno));
            break;
        }

        if (bytes_read < 8) {
            fprintf(stderr, "Partial read: %zd bytes\n", bytes_read);
            continue;
        }

        uint32_t magic_word = (buffer[0] << 24) | (buffer[1] << 16) | (buffer[2] << 8) | buffer[3];
        uint32_t payload_length = (buffer[4] << 24) | (buffer[5] << 16) | (buffer[6] << 8) | buffer[7];

        if (magic_word != MAGIC_WORD) {
            fprintf(stderr, "Invalid magic word: 0x%08X\n", magic_word);
            continue;
        }

        if (bytes_read < 8 + payload_length) {
            fprintf(stderr, "Incomplete frame: %zd bytes, expected %zd\n", bytes_read, 8 + payload_length);
            continue;
        }

        uint32_t timestamp = (buffer[8] << 24) | (buffer[9] << 16) | (buffer[10] << 8) | buffer[11];
        uint32_t object_index = (buffer[12] << 24) | (buffer[13] << 16) | (buffer[14] << 8) | buffer[15];
        uint32_t range_m = (buffer[16] << 24) | (buffer[17] << 16) | (buffer[18] << 8) | buffer[19];
        uint32_t velocity_mps = (buffer[20] << 24) | (buffer[21] << 16) | (buffer[22] << 8) | buffer[23];

        write_csv("%u,%u,%f,%f\n", timestamp, object_index, range_m / 1000.0, velocity_mps / 1000.0);

        // Skip the rest of the payload
        buffer += 8 + payload_length;
        bytes_read -= 8 + payload_length;
    }

    fclose(csv_file);
    close(uart_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

