#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define UART_DEVICE "/dev/serial0"
#define BAUDRATE B115200
#define TIMEOUT 2000 // 2 seconds
#define INTER_BYTE_TIMEOUT 500 // 0.5 seconds
#define BUFFER_SIZE 256

static int uart_fd;
static struct termios old_termios;
static struct gpiod_chip *chip;
static struct gpiod_line *line;

void handle_sigint(int signum) {
    close_uart();
    exit(0);
}

void handle_sigterm(int signum) {
    close_uart();
    exit(0);
}

void close_uart() {
    if (uart_fd != -1) {
        tcsetattr(uart_fd, TCSANOW, &old_termios);
        close(uart_fd);
        uart_fd = -1;
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (line != NULL) {
        gpiod_line_release(line);
        line = NULL;
    }
}

void setup_uart() {
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd == -1) {
        perror("Failed to open UART");
        exit(EXIT_FAILURE);
    }

    struct termios new_termios;
    tcgetattr(uart_fd, &old_termios);
    memcpy(&new_termios, &old_termios, sizeof(new_termios));

    cfsetispeed(&new_termios, BAUDRATE);
    cfsetospeed(&new_termios, BAUDRATE);
    new_termios.c_cflag &= ~PARENB;
    new_termios.c_cflag &= ~CSTOPB;
    new_termios.c_cflag &= ~CSIZE;
    new_termios.c_cflag |= CS8;
    new_termios.c_cflag &= ~CRTSCTS;
    new_termios.c_cflag |= CREAD | CLOCAL;
    new_termios.c_lflag &= ~ICANON;
    new_termios.c_lflag &= ~ECHO;
    new_termios.c_lflag &= ~ECHOE;
    new_termios.c_lflag &= ~ECHONL;
    new_termios.c_lflag &= ~ISIG;
    new_termios.c_iflag &= ~(IXON | IXOFF | IXANY);
    new_termios.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | INLCR | IGNCR | ICRNL | IXON);
    new_termios.c_oflag &= ~OPOST;
    new_termios.c_cc[VTIME] = INTER_BYTE_TIMEOUT / 10;
    new_termios.c_cc[VMIN] = 0;

    if (tcsetattr(uart_fd, TCSANOW, &new_termios) == -1) {
        perror("Failed to set UART attributes");
        close_uart();
        exit(EXIT_FAILURE);
    }
}

void setup_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        close_uart();
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 14);
    if (line == NULL) {
        perror("Failed to get GPIO line 14");
        gpiod_chip_close(chip);
        close_uart();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, "radar_sensor") != 0) {
        perror("Failed to request GPIO line 14 as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close_uart();
        exit(EXIT_FAILURE);
    }
}

void check_sensor_status() {
    int sensor_status = gpiod_line_get_value(line);
    if (sensor_status == 0) {
        fprintf(stderr, "Sensor is absent or bus error detected.\n");
        close_uart();
        exit(EXIT_FAILURE);
    }
}

void read_radar_data() {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;
    fd_set read_fds;
    struct timeval timeout;

    while (1) {
        FD_ZERO(&read_fds);
        FD_SET(uart_fd, &read_fds);

        timeout.tv_sec = TIMEOUT / 1000;
        timeout.tv_usec = (TIMEOUT % 1000) * 1000;

        if (select(uart_fd + 1, &read_fds, NULL, NULL, &timeout) == -1) {
            perror("Failed to select");
            close_uart();
            exit(EXIT_FAILURE);
        }

        if (FD_ISSET(uart_fd, &read_fds)) {
            bytes_read = read(uart_fd, buffer, BUFFER_SIZE - 1);
            if (bytes_read == -1) {
                perror("Failed to read from UART");
                close_uart();
                exit(EXIT_FAILURE);
            }

            buffer[bytes_read] = '\0';

            char *line_start = buffer;
            while ((line_start = strstr(line_start, "\n")) != NULL) {
                char *line_end = line_start + strlen(line_start);
                if (line_end - line_start > 1) {
                    char *timestamp_str = line_start;
                    char *range_str = line_start + strlen(timestamp_str) + 1;
                    char *newline = line_end;

                    char *timestamp_end = strchr(timestamp_str, ',');
                    if (timestamp_end == NULL) {
                        fprintf(stderr, "Invalid line format: %s\n", line_start);
                        continue;
                    }

                    *timestamp_end = '\0';
                    char *range_end = strchr(range_str, '\n');
                    if (range_end == NULL) {
                        fprintf(stderr, "Invalid line format: %s\n", line_start);
                        continue;
                    }

                    *range_end = '\0';

                    struct tm *timeinfo;
                    time_t rawtime;
                    time(&rawtime);
                    timeinfo = localtime(&rawtime);

                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                    double range = atof(range_str);
                    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range);

                    line_start = newline;
                }
            }
        }
    }
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    setup_gpio();
    check_sensor_status();
    setup_uart();
    read_radar_data();

    return 0;
}

