    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("Failed to open GPIO chip");
        close_uart();
        exit(EXIT_FAILURE);
    }

    line = gpiod_chip_get_line(chip, 14);
    if (line == NULL) {
        perror("Failed to get GPIO line 14");
        gpiod_chip_close(chip);
        close_uart();
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, "radar_sensor") != 0) {
        perror("Failed to request GPIO line 14 as input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close_uart();
        exit(EXIT_FAILURE);
    }
}

void check_sensor_status() {
    int sensor_status = gpiod_line_get_value(line);
    if (sensor_status == 0) {
        fprintf(stderr, "Sensor is absent or bus error detected.\n");
        close_uart();
        exit(EXIT_FAILURE);
    }
}

void read_radar_data() {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;
    fd_set read_fds;
    struct timeval timeout;

    while (1) {
        FD_ZERO(&read_fds);
        FD_SET(uart_fd, &read_fds);

        timeout.tv_sec = TIMEOUT / 1000;
        timeout.tv_usec = (TIMEOUT % 1000) * 1000;

        if (select(uart_fd + 1, &read_fds, NULL, NULL, &timeout) == -1) {
            perror("Failed to select");
            close_uart();
            exit(EXIT_FAILURE);
        }

        if (FD_ISSET(uart_fd, &read_fds)) {
            bytes_read = read(uart_fd, buffer, BUFFER_SIZE - 1);
            if (bytes_read == -1) {
                perror("Failed to read from UART");
                close_uart();
                exit(EXIT_FAILURE);
            }

            buffer[bytes_read] = '\0';

            char *line_start = buffer;
            while ((line_start = strstr(line_start, "\n")) != NULL) {
                char *line_end = line_start + strlen(line_start);
                if (line_end - line_start > 1) {
                    char *timestamp_str = line_start;
                    char *range_str = line_start + strlen(timestamp_str) + 1;
                    char *newline = line_end;

                    char *timestamp_end = strchr(timestamp_str, ',');
                    if (timestamp_end == NULL) {
                        fprintf(stderr, "Invalid line format: %s\n", line_start);
                        continue;
                    }

                    *timestamp_end = '\0';
                    char *range_end = strchr(range_str, '\n');
                    if (range_end == NULL) {
                        fprintf(stderr, "Invalid line format: %s\n", line_start);
                        continue;
                    }

                    *range_end = '\0';

                    struct tm *timeinfo;
                    time_t rawtime;
                    time(&rawtime);
                    timeinfo = localtime(&rawtime);

                    char timestamp[20];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                    double range = atof(range_str);
                    printf("Timestamp: %s, Range: %.2f meters\n", timestamp, range);

                    line_start = newline;
                }
            }
        }
    }
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    setup_gpio();
    check_sensor_status();
    setup_uart();
    read_radar_data();

    return 0;
}
```

This C program sets up a UART connection to a Texas Instruments AWR1642 mmWave radar sensor connected to the Raspberry Pi 4 Model B. It reads data in non-canonical mode with a 0.5 s inter-byte timeout and a 2-second timeout for select(). The program accumulates partial reads into a buffer, parses only complete newline-terminated lines, and logs each valid detection to stdout. It handles sensor-absent or bus-error paths and gracefully shuts down on SIGINT and SIGTERM.

