        fprintf(stderr, "Failed to set GPIO17 pull-up\n");
        goto cleanup;
    }
    if (gpioSetPullUpDown(27, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO27 pull-up\n");
        goto cleanup;
    }

    // Open serial port
    serial_fd = open(SERIAL_PORT, O_WRONLY | O_NOCTTY | O_NDELAY);
    if (serial_fd < 0) {
        fprintf(stderr, "Failed to open serial port %s\n", SERIAL_PORT);
        goto cleanup;
    }

    // Set serial port parameters
    struct termios options;
    tcgetattr(serial_fd, &options);
    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);
    options.c_cflag &= ~PARENB;
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CSIZE;
    options.c_cflag |= CS8;
    options.c_cflag &= ~CRTSCTS;
    options.c_cflag |= CLOCAL | CREAD;
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    options.c_oflag &= ~OPOST;
    tcsetattr(serial_fd, TCSANOW, &options);

    // Main loop
    while (1) {
        struct timespec sleep_time = {0, PERIOD};
        nanosleep(&sleep_time, NULL);

        int states[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            int pin = 4 + i;
            states[i] = gpioRead(pin);
        }

        time_t now = time(NULL);
        struct tm *tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

        printf("%s: ", timestamp);
        for (int i = 0; i < NUM_SENSORS; i++) {
            printf("%d ", states[i]);
        }
        printf("\n");

        if (states[0] == 0 && states[1] == 0 && states[2] == 0) {
            char emergency_stop[] = "EMERGENCY STOP!\n";
            if (write(serial_fd, emergency_stop, strlen(emergency_stop)) < 0) {
                fprintf(stderr, "Failed to write to serial port\n");
            }
        }
    }

cleanup:
